const ALERTAS_TIPOS = {
    entrega:        { label: 'Entregas atrasadas / hoje',         icon: '🚚' },
    medicao:        { label: 'Medições atrasadas / agendadas',    icon: '📐' },
    instalacao:     { label: 'Instalações atrasadas / agendadas', icon: '🔧' },
    estoque:        { label: 'Estoque abaixo do mínimo',          icon: '📦' },
    fin_vencimento: { label: 'Contas vencendo hoje / em breve',   icon: '📅' },
    fin_atraso:     { label: 'Recebimentos / pagamentos atrasados', icon: '❌' },
    fin_gap:        { label: 'Gap de caixa (7 dias)',             icon: '⚠️' },
    fin_meta:       { label: 'Progresso da meta de faturamento',  icon: '🎯' },
    fin_tendencia:  { label: 'Tendência de faturamento mensal',   icon: '📈' },
    compromisso:    { label: 'Lembretes de compromisso',          icon: '📌' },
};

function getAlertasCfg() {
    try { return JSON.parse(localStorage.getItem('sc_alertas_cfg')) || {}; } catch(e) { return {}; }
}
function alertaAtivo(tipo) {
    return getAlertasCfg()[tipo] !== false;
}
function toggleAlertaTipo(tipo) {
    const cfg = getAlertasCfg();
    cfg[tipo] = !alertaAtivo(tipo);
    localStorage.setItem('sc_alertas_cfg', JSON.stringify(cfg));
    renderBellIndicator();
    Notif.atualizar();
    renderEmpresaAlertasCfg();
}
function renderEmpresaAlertasCfg() {
    const el = document.getElementById('emp-alertas-cfg');
    if (!el) return;
    const cfg = getAlertasCfg();
    el.innerHTML = Object.entries(ALERTAS_TIPOS).map(([key, info]) => {
        const ativo = cfg[key] !== false;
        return `<div class="alerta-toggle-row">
            <div style="display:flex;align-items:center;gap:10px">
                <span style="font-size:20px">${info.icon}</span>
                <div>
                    <div style="font-size:13px;font-weight:500;color:var(--dark)">${info.label}</div>
                    <div style="font-size:11px;color:${ativo?'var(--primary-text)':'#8F8F8F'};margin-top:1px">${ativo?'Ativo':'Desativado'}</div>
                </div>
            </div>
            <label class="toggle-switch">
                <input type="checkbox" ${ativo?'checked':''} onchange="toggleAlertaTipo('${key}')">
                <span class="toggle-slider"></span>
            </label>
        </div>`;
    }).join('');
}
// ── CONFIGURAÇÃO DE CARDS DO DASHBOARD ────────────────────────
const DASHBOARD_CARDS = {
    fat_mes:            { label: 'Faturamento do Mês',            icon: '💰' },
    producao:           { label: 'Em Produção',                   icon: '🧵' },
    orcamentos:         { label: 'Orçamentos Abertos',            icon: '📋' },
    ticket:             { label: 'Ticket Médio',                  icon: '🎫' },
    estoque_critico:    { label: 'Estoque Crítico',               icon: '📦' },
    atrasados:          { label: 'Entregas Atrasadas',            icon: '🚚' },
    a_receber:          { label: 'A Receber (Total)',             icon: '💵' },
    alertas:            { label: 'Painel de Alertas do Sistema',  icon: '🔔' },
    chart_status:       { label: 'Gráfico: Pedidos por Status',   icon: '📊' },
    agenda_instalacoes: { label: 'Agenda de Instalações (resumo)', icon: '🔧' },
    agenda_medicoes:    { label: 'Agenda de Medições (resumo)',    icon: '📐' },
};
const DASH_CARD_ELEMENT_IDS = {
    fat_mes: 'card-fat-mes', producao: 'card-producao', orcamentos: 'card-orcamentos',
    ticket: 'card-ticket', estoque_critico: 'card-estoque-critico', atrasados: 'card-atrasados',
    a_receber: 'card-a-receber', alertas: 'card-alertas', chart_status: 'card-chart-status',
    agenda_instalacoes: 'dashboard-instalacoes', agenda_medicoes: 'dashboard-medicoes',
};

function getDashCardsCfg() {
    try { return JSON.parse(localStorage.getItem('sc_dashcards_cfg')) || {}; } catch(e) { return {}; }
}
function dashCardVisivel(key) {
    return getDashCardsCfg()[key] !== false;
}
function toggleDashCard(key) {
    const cfg = getDashCardsCfg();
    cfg[key] = !dashCardVisivel(key);
    localStorage.setItem('sc_dashcards_cfg', JSON.stringify(cfg));
    renderEmpresaDashCardsCfg();
    aplicarDashCardsVisibilidade();
}
function renderEmpresaDashCardsCfg() {
    const el = document.getElementById('emp-dashcards-cfg');
    if (!el) return;
    const cfg = getDashCardsCfg();
    el.innerHTML = Object.entries(DASHBOARD_CARDS).map(([key, info]) => {
        const ativo = cfg[key] !== false;
        return `<div class="alerta-toggle-row">
            <div style="display:flex;align-items:center;gap:10px">
                <span style="font-size:20px">${info.icon}</span>
                <div>
                    <div style="font-size:13px;font-weight:500;color:var(--dark)">${info.label}</div>
                    <div style="font-size:11px;color:${ativo?'var(--primary-text)':'#8F8F8F'};margin-top:1px">${ativo?'Visível':'Oculto'}</div>
                </div>
            </div>
            <label class="toggle-switch">
                <input type="checkbox" ${ativo?'checked':''} onchange="toggleDashCard('${key}')">
                <span class="toggle-slider"></span>
            </label>
        </div>`;
    }).join('');
}
function aplicarDashCardsVisibilidade() {
    const cfg = getDashCardsCfg();
    Object.entries(DASH_CARD_ELEMENT_IDS).forEach(([key, elId]) => {
        const elCard = document.getElementById(elId);
        if (!elCard) return;
        if (cfg[key] === false) elCard.style.display = 'none';
        else if (key !== 'agenda_instalacoes' && key !== 'agenda_medicoes') elCard.style.display = '';
    });
}

function _getHeaderGroup() {
    let grp = document.getElementById('header-right-group');
    if (!grp) {
        const headerEl = document.querySelector('.header');
        if (!headerEl) return null;
        grp = document.createElement('div');
        grp.id = 'header-right-group';
        grp.style.cssText = 'display:flex;align-items:center;gap:10px;margin-left:auto';
        headerEl.appendChild(grp);
    }
    return grp;
}

function renderBellIndicator() {
    const cfg = getAlertasCfg();
    const temDesativado = Object.keys(ALERTAS_TIPOS).some(k => cfg[k] === false);
    let bell = document.getElementById('alerta-bell-disabled');
    // O sino leva a Configurar Empresa. Para quem nao alcanca aquela tela ele
    // so renderia um convite a ser barrado na porta.
    if (!temDesativado || !temAcesso('configuracoes.empresa', 'visualizar')) { if (bell) bell.remove(); return; }
    if (!bell) {
        bell = document.createElement('div');
        bell.id = 'alerta-bell-disabled';
        bell.onclick = () => window.location.href = 'empresa.html#preferencias';
        const grp = _getHeaderGroup();
        if (grp) grp.appendChild(bell);
    }
    bell.innerHTML = `🔕 Alertas desabilitados<div class="bell-tip">Alguns alertas estão desabilitados. Clique para gerenciar em Configurar Empresa.</div>`;
}

function renderDashboardsButton() {
    if (document.getElementById('dash-nav-btn')) return;
    if (window.location.pathname.toLowerCase().includes('dashboards')) return;
    const grp = _getHeaderGroup();
    if (!grp) return;
    const DASH_LIST = [
        ['comercial','📊','Comercial / Vendas'],
        ['producao','🏭','Produção'],
        ['estoque','📦','Estoque'],
        ['instalacoes','🔧','Instalações'],
        ['compras','🛒','Compras'],
        ['gerencial','👔','Gerencial'],
    ];
    const wrap = document.createElement('div');
    wrap.id = 'dash-nav-btn';
    wrap.style.cssText = 'position:relative';
    wrap.innerHTML = `<button class="btn btn-outline btn-sm" onclick="toggleDashboardsMenu(event)" style="display:flex;align-items:center;gap:5px;font-weight:600">
        📊 Dashboards <span style="font-size:9px;opacity:.7">▾</span>
    </button>
    <div id="dash-dropdown" style="display:none;position:absolute;top:calc(100%+8px);right:0;background:var(--white);border:1px solid var(--border);border-radius:10px;box-shadow:0 8px 28px rgba(0,0,0,.14);z-index:3000;min-width:220px;padding:5px 0;overflow:hidden">
        ${DASH_LIST.map(([id,ic,lb])=>`<a href="dashboards.html?dash=${id}" style="display:flex;align-items:center;gap:10px;padding:10px 16px;font-size:13px;font-weight:500;color:var(--dark);text-decoration:none;white-space:nowrap;transition:background-color .15s ease" onmouseover="this.style.background='var(--light)'" onmouseout="this.style.background=''">${ic} <span>${lb}</span></a>`).join('<div style="height:1px;background:var(--border)"></div>')}
    </div>`;
    grp.insertBefore(wrap, grp.firstChild);
    // Painel: o botao Agenda fica logo a esquerda de Dashboards.
    if (document.getElementById('card-fat-mes') && !document.getElementById('btn-agenda')) {
        const ag = document.createElement('button');
        ag.type = 'button'; ag.id = 'btn-agenda'; ag.className = 'btn btn-outline btn-sm';
        ag.style.cssText = 'display:flex;align-items:center;gap:5px;font-weight:600';
        ag.setAttribute('onclick', 'abrirAgenda()');
        ag.textContent = '📅 Agenda';
        grp.insertBefore(ag, wrap);
    }
}

// Abas menos usadas do Estoque, fora da barra principal: ficam num menu de
// tres pontos ao lado de Dashboards. So aparece na tela de Estoque.
const ABAS_EXTRAS_ESTOQUE = [
    ['historico', '📋', 'Histórico'],
    ['futuro',    '📊', 'Estoque Futuro'],
    ['backup',    '💾', 'Backup']
];

function renderMenuExtrasEstoque() {
    if (document.getElementById('estoque-extras-btn')) return;
    if (!document.getElementById('tab-historico')) return;   // só na tela de Estoque
    const grp = _getHeaderGroup();
    if (!grp) return;
    const wrap = document.createElement('div');
    wrap.id = 'estoque-extras-btn';
    wrap.style.cssText = 'position:relative';
    wrap.innerHTML = `<button class="btn btn-outline btn-sm" onclick="toggleExtrasEstoque(event)"
            title="Mais abas do estoque" style="font-weight:700;letter-spacing:1px;padding:6px 12px">⋯</button>
        <div id="estoque-extras-menu" style="display:none;position:absolute;top:calc(100% + 8px);right:0;background:var(--white);border:1px solid var(--border);border-radius:10px;box-shadow:0 8px 28px rgba(0,0,0,.14);z-index:3000;min-width:200px;padding:5px 0;overflow:hidden">
        ${ABAS_EXTRAS_ESTOQUE.map(([id, ic, lb]) =>
            `<button type="button" onclick="mostrarTabEstoque('${id}')" style="display:flex;align-items:center;gap:10px;padding:10px 16px;font-size:13px;font-weight:500;color:var(--dark);background:none;border:0;width:100%;text-align:left;cursor:pointer;white-space:nowrap;transition:background-color .15s ease" onmouseover="this.style.background='var(--light)'" onmouseout="this.style.background=''">${ic} <span>${lb}</span></button>`
        ).join('<div style="height:1px;background:var(--border)"></div>')}
        </div>`;
    grp.insertBefore(wrap, grp.firstChild);
}

function toggleExtrasEstoque(e) {
    e.stopPropagation();
    const m = document.getElementById('estoque-extras-menu');
    if (m) m.style.display = m.style.display === 'none' ? 'block' : 'none';
}
document.addEventListener('click', () => {
    const m = document.getElementById('estoque-extras-menu');
    if (m) m.style.display = 'none';
});

function toggleDashboardsMenu(e) {
    e.stopPropagation();
    const m = document.getElementById('dash-dropdown');
    if (m) m.style.display = m.style.display === 'none' ? 'block' : 'none';
}
document.addEventListener('click', () => {
    const m = document.getElementById('dash-dropdown');
    if (m) m.style.display = 'none';
});

// ── ALERTAS DO SISTEMA (coletores do sino e do card do Painel) ──
// Cada tipo de banner e um coletor registrado em Notif (js/notificacoes.js):
// o card do Painel e o sino da barra superior leem a mesma lista, em qualquer pagina.
const _ALERTA_CORES = {
    danger: ['var(--danger-bg)', '#F79B90', 'var(--danger-text)'],
    warn:   ['var(--warn-bg)',   '#F2C924', 'var(--warn-text)'],
    info:   ['var(--info-bg)',   '#9FC4E5', 'var(--info-text)'],
    success:['var(--ok-bg)',     '#8FD98D', 'var(--ok-text)']
};
const _ALERTA_SEP = ' &nbsp;·&nbsp; ';
// Data local (e nao UTC): das 21h a meia-noite o dia ainda e o de hoje.
const _alertaHoje = () => hojeLocal();
const _alertaDataBR = d => d.split('-').reverse().join('/');
const _alertaIds = lista => lista.map(x => x.id).join(',');
const _ALERTA_INST_STATUS = ['Pronto p/ Instalação', 'Aguardando Financeiro'];
// Pedido que ja aparece em "Instalacoes atrasadas / de hoje" nao entra de novo em "Entregas":
// vale quando o alerta de instalacoes esta ligado (desligado, o pedido ficaria sem aviso nenhum).
const _alertaEhInstalacao = p => alertaAtivo('instalacao') && _ALERTA_INST_STATUS.includes(normalizarStatus(p.status));
const _alertaLinkPedido = (p, cor, extra) =>
    `<span style="cursor:pointer;color:${cor};font-weight:600;text-decoration:underline" onclick="editarPedido(${p.id})">#${formatPedidoId(p.id)} ${escapeHtml(p.clienteNome||'')}${extra || ''}</span>`;

Notif.registrar('entregas-atrasadas', () => {
    if (!alertaAtivo('entrega')) return [];
    const hojeStr = _alertaHoje(), hoje = new Date(); hoje.setHours(0, 0, 0, 0);
    const lista = filtrarPedidosVisiveis(db.pedidos).filter(p =>
        p.data_entrega && normalizarStatus(p.status) !== 'Instalado' && p.data_entrega < hojeStr && !_alertaEhInstalacao(p));
    if (!lista.length) return [];
    const itens = lista.sort((a, b) => a.data_entrega.localeCompare(b.data_entrega)).map(p => {
        const diasAtraso = Math.round((hoje - new Date(p.data_entrega + 'T00:00:00')) / 86400000);
        return `<span style="cursor:pointer;color:var(--danger-text);font-weight:600;text-decoration:underline" onclick="editarPedido(${p.id})" title="${diasAtraso}d de atraso">#${formatPedidoId(p.id)} ${escapeHtml(p.clienteNome||'')} (${_alertaDataBR(p.data_entrega)})</span>`;
    }).join(_ALERTA_SEP);
    return [{ chave: 'entregas-atrasadas:' + _alertaIds(lista), icone: '🚨', cor: 'danger', urgente: true, href: 'pedidos.html',
        titulo: `<strong>${lista.length} entrega(s) atrasada(s):</strong>`, texto: itens }];
});

Notif.registrar('entregas-hoje', () => {
    if (!alertaAtivo('entrega')) return [];
    const hojeStr = _alertaHoje();
    const lista = filtrarPedidosVisiveis(db.pedidos).filter(p =>
        p.data_entrega && normalizarStatus(p.status) !== 'Instalado' && p.data_entrega === hojeStr && !_alertaEhInstalacao(p));
    if (!lista.length) return [];
    return [{ chave: 'entregas-hoje:' + _alertaIds(lista), icone: '🔔', cor: 'warn', urgente: false, href: 'pedidos.html',
        titulo: `<strong>${lista.length} pedido(s)</strong> com entrega prevista para hoje:`,
        texto: lista.map(p => _alertaLinkPedido(p, 'var(--warn-text)')).join(_ALERTA_SEP) }];
});

Notif.registrar('medicoes-atrasadas', () => {
    if (!alertaAtivo('medicao')) return [];
    const hojeStr = _alertaHoje();
    const lista = filtrarMedicoesVisiveis(db.medicoes).filter(m => m.status === 'Agendado' && m.data < hojeStr);
    if (!lista.length) return [];
    const itens = lista.map(m =>
        `<span style="cursor:pointer;color:var(--danger-text);font-weight:600;text-decoration:underline" onclick="location.href='pcp.html?view=medicoes'">${escapeHtml(m.clienteNome||'—')} (${_alertaDataBR(m.data)})</span>`
    ).join(_ALERTA_SEP);
    return [{ chave: 'medicoes-atrasadas:' + _alertaIds(lista), icone: '📐', cor: 'danger', urgente: true, href: 'pcp.html?view=medicoes',
        titulo: `<strong>${lista.length} medição(ões)</strong> atrasada(s):`, texto: itens }];
});

Notif.registrar('medicoes-hoje', () => {
    if (!alertaAtivo('medicao')) return [];
    const hojeStr = _alertaHoje();
    const lista = filtrarMedicoesVisiveis(db.medicoes).filter(m => m.status === 'Agendado' && m.data === hojeStr);
    if (!lista.length) return [];
    const itens = lista.map(m =>
        `<span style="cursor:pointer;color:#2D77C1;font-weight:600;text-decoration:underline" onclick="location.href='pcp.html?view=medicoes'">${escapeHtml(m.clienteNome||'—')}${m.hora ? ' às ' + m.hora : ''}</span>`
    ).join(_ALERTA_SEP);
    return [{ chave: 'medicoes-hoje:' + _alertaIds(lista), icone: '📐', cor: 'info', urgente: false, href: 'pcp.html?view=medicoes',
        titulo: `<strong>${lista.length} medição(ões)</strong> agendada(s) para hoje:`, texto: itens }];
});

Notif.registrar('instalacoes-atrasadas', () => {
    if (!alertaAtivo('instalacao')) return [];
    const hojeStr = _alertaHoje();
    const lista = filtrarPedidosVisiveis(db.pedidos).filter(p =>
        _ALERTA_INST_STATUS.includes(normalizarStatus(p.status)) && p.data_entrega && p.data_entrega < hojeStr);
    if (!lista.length) return [];
    const itens = lista.map(p => _alertaLinkPedido(p, 'var(--danger-text)', ` (${_alertaDataBR(p.data_entrega)})`)).join(_ALERTA_SEP);
    return [{ chave: 'instalacoes-atrasadas:' + _alertaIds(lista), icone: '🔧', cor: 'danger', urgente: true, href: 'pedidos.html',
        titulo: `<strong>${lista.length} instalação(ões)</strong> atrasada(s):`, texto: itens }];
});

Notif.registrar('instalacoes-hoje', () => {
    if (!alertaAtivo('instalacao')) return [];
    const hojeStr = _alertaHoje();
    const lista = filtrarPedidosVisiveis(db.pedidos).filter(p =>
        _ALERTA_INST_STATUS.includes(normalizarStatus(p.status)) && p.data_entrega === hojeStr);
    if (!lista.length) return [];
    const itens = lista.map(p => _alertaLinkPedido(p, '#2D77C1', p.inst_hora ? ' às ' + p.inst_hora : '')).join(_ALERTA_SEP);
    return [{ chave: 'instalacoes-hoje:' + _alertaIds(lista), icone: '🔧', cor: 'info', urgente: false, href: 'pedidos.html',
        titulo: `<strong>${lista.length} instalação(ões)</strong> agendada(s) para hoje:`, texto: itens }];
});

Notif.registrar('estoque-minimo', () => {
    if (!alertaAtivo('estoque')) return [];
    const tecidos = db.catalogo.filter(c => !temEstoqueInfinito(c) && c.min_estoque > 0 && estoqueDisponivel(c.id) < c.min_estoque);
    const mats    = db.materiais.filter(m => !temEstoqueInfinito(m) && m.min_estoque > 0 && (m.estoque_atual || 0) < m.min_estoque);
    const total = tecidos.length + mats.length;
    if (!total) return [];
    const itens = [
        ...tecidos.map(c => `<span style="cursor:pointer;color:var(--warn-text);font-weight:600;text-decoration:underline" onclick="location.href='estoque.html'">${escapeHtml(c.nome)}: ${estoqueDisponivel(c.id).toFixed(2)} m (mín. ${c.min_estoque} m)</span>`),
        ...mats.map(m => `<span style="cursor:pointer;color:var(--warn-text);font-weight:600;text-decoration:underline" onclick="location.href='estoque.html'">${escapeHtml(m.nome)}: ${(m.estoque_atual||0).toFixed(2)} ${m.unidade||''} (mín. ${m.min_estoque})</span>`)
    ].join(_ALERTA_SEP);
    return [{ chave: 'estoque-minimo:' + tecidos.map(c => 't' + c.id).concat(mats.map(m => 'm' + m.id)).join(','),
        icone: '⚠️', cor: 'warn', urgente: false, href: 'estoque.html',
        titulo: `<strong>${total} item(ns)</strong> com estoque abaixo do mínimo:`, texto: itens }];
});

// Alertas do Financeiro (mesmos textos e regras da Visao Geral do Financeiro, via finAlertasCalcular):
// so para quem tem acesso ao Financeiro. Urgente = o que e vermelho la (atrasos e gap de caixa).
// Cada alerta so aparece para quem pode ver a aba do Financeiro que trata do assunto (a mesma do link);
// clicar abre essa aba.
Notif.registrar('financeiro', () => {
    if (!temAcessoAlgumaSub('financeiro', 'visualizar')) return [];
    return finAlertasCalcular(hojeLocal()).filter(a => finModuloVisivel(FIN_TAB_MODULO[a.aba] || 'financeiro')).map(a => ({
        chave: 'fin:' + a.id, icone: a.icone, cor: a.cor === 'warning' ? 'warn' : a.cor, urgente: a.cor === 'danger',
        href: 'financeiro.html?aba=' + a.aba, titulo: '', texto: a.html }));
});

// Aceite de medicao/instalacao destinada a outro usuario (ver "ACEITE" mais abaixo).
// Quem recebeu: pedido persistente, com Aceitar e Recusar, ate responder.
Notif.registrar('aceite-recebidos', () => {
    const u = getUsuarioLogado();
    if (!u) return [];
    const out = [];
    (db.medicoes || []).forEach(m => {
        if (m.status !== 'Agendado' || !_aceitePend(m.aceite) || m.usuario_id !== u.id || _aceiteVencido(m.data, m.hora)) return;
        out.push({ chave: 'aceite-med:' + m.id + ':' + m.aceite.em, icone: '📐', cor: 'warn', urgente: true, persistente: true,
            href: 'pcp.html?view=medicoes', titulo: '',
            texto: escapeHtml(`Você recebeu a medição de ${m.clienteNome || 'cliente'} em ${_aceiteQuando(m.data, m.hora)}.`),
            acoes: _aceiteAcoes('med', m.id) });
    });
    (db.pedidos || []).forEach(p => {
        if (!_instPendente(p) || !_aceitePend(p.inst_aceite) || p.usuario_instalacao_id !== u.id || _aceiteVencido(p.data_entrega, p.inst_hora)) return;
        out.push({ chave: 'aceite-inst:' + p.id + ':' + p.inst_aceite.em, icone: '🔧', cor: 'warn', urgente: true, persistente: true,
            href: 'pcp.html?view=agenda', titulo: '',
            texto: escapeHtml(`Você recebeu a instalação do pedido #${formatPedidoId(p.id)} (${p.clienteNome || 'cliente'}) em ${_aceiteQuando(p.data_entrega, p.inst_hora)}.`),
            acoes: _aceiteAcoes('inst', p.id) });
    });
    return out;
});

// Quem destinou: "aceitou" (some 7 dias depois da resposta) e "recusou" (fica ate reagendar,
// com o botao Reagendar).
const _ACEITE_DIAS_AVISO = 7;
Notif.registrar('aceite-respostas', () => {
    const u = getUsuarioLogado();
    if (!u) return [];
    const out = [];
    const limite = Date.now() - _ACEITE_DIAS_AVISO * 86400000;
    (db.medicoes || []).forEach(m => {
        if (m.status === 'Agendado' && m.aceite && m.aceite.status === 'aceito' && m.aceite.por === u.id && m.aceite.resp_em && m.aceite.resp_em > limite) {
            out.push({ chave: 'aceite-ok-med:' + m.id + ':' + m.aceite.resp_em, icone: '✅', cor: 'info', urgente: false, titulo: '',
                href: 'pcp.html?view=medicoes',
                texto: escapeHtml(`${nomeUsuario(m.usuario_id)} aceitou a medição de ${m.clienteNome || 'cliente'} (${_aceiteQuando(m.data, m.hora, true)}).`) });
        }
        // Pedido de aceite vencido sem resposta: quem destinou e avisado para reagendar.
        if (m.status === 'Agendado' && _aceitePend(m.aceite) && m.aceite.por === u.id && _aceiteVencido(m.data, m.hora)) {
            out.push({ chave: 'aceite-vencido-med:' + m.id + ':' + m.aceite.em, icone: '⏰', cor: 'danger', urgente: true, titulo: '',
                href: 'pcp.html?view=medicoes',
                texto: escapeHtml(`${nomeUsuario(m.usuario_id)} não respondeu à medição de ${m.clienteNome || 'cliente'} (${_aceiteQuando(m.data, m.hora, true)}). Reagende.`),
                acoes: [{ rotulo: 'Reagendar', fn: `aceiteReagendar('med',${m.id})` }] });
        }
        if (m.status === 'A reagendar' && m.recusa && m.recusa.para === u.id) {
            out.push({ chave: 'aceite-recusa-med:' + m.id + ':' + m.recusa.em, icone: '⚠️', cor: 'danger', urgente: true, titulo: '',
                href: 'pcp.html?view=medicoes',
                texto: escapeHtml(`${nomeUsuario(m.recusa.por)} recusou a medição de ${m.clienteNome || 'cliente'}: ${m.recusa.motivo}`),
                acoes: [{ rotulo: 'Reagendar', fn: `aceiteReagendar('med',${m.id})` }] });
        }
    });
    (db.pedidos || []).forEach(p => {
        const a = p.inst_aceite, r = p.inst_recusa;
        if (_instPendente(p) && a && a.status === 'aceito' && a.por === u.id && a.resp_em && a.resp_em > limite) {
            out.push({ chave: 'aceite-ok-inst:' + p.id + ':' + a.resp_em, icone: '✅', cor: 'info', urgente: false, titulo: '',
                href: 'pcp.html?view=agenda',
                texto: escapeHtml(`${nomeUsuario(p.usuario_instalacao_id)} aceitou a instalação do pedido #${formatPedidoId(p.id)} (${_aceiteQuando(p.data_entrega, p.inst_hora, true)}).`) });
        }
        if (_instPendente(p) && _aceitePend(a) && a.por === u.id && _aceiteVencido(p.data_entrega, p.inst_hora)) {
            out.push({ chave: 'aceite-vencido-inst:' + p.id + ':' + a.em, icone: '⏰', cor: 'danger', urgente: true, titulo: '',
                href: 'pcp.html?view=agenda',
                texto: escapeHtml(`${nomeUsuario(p.usuario_instalacao_id)} não respondeu à instalação do pedido #${formatPedidoId(p.id)} (${_aceiteQuando(p.data_entrega, p.inst_hora, true)}). Reagende.`),
                acoes: [{ rotulo: 'Reagendar', fn: `aceiteReagendar('inst',${p.id})` }] });
        }
        if (r && r.para === u.id && normalizarStatus(p.status) === 'Pronto p/ Instalação' && !_instAgendada(p)) {
            out.push({ chave: 'aceite-recusa-inst:' + p.id + ':' + r.em, icone: '⚠️', cor: 'danger', urgente: true, titulo: '',
                href: 'pcp.html?view=agenda',
                texto: escapeHtml(`${nomeUsuario(r.por)} recusou a instalação do pedido #${formatPedidoId(p.id)}: ${r.motivo}`),
                acoes: [{ rotulo: 'Reagendar', fn: `aceiteReagendar('inst',${p.id})` }] });
        }
    });
    return out;
});

// Outra aba gravou: traz para a memoria o que os alertas leem.
// So troca o array quando o texto gravado mudou (ver _dbRecarregarChave).
const _NOTIF_CHAVES_DB = ['sc_ped', 'sc_med', 'sc_cat', 'sc_mat', 'sc_est', 'sc_mov', 'sc_cr', 'sc_cp', 'sc_mov_fin', 'sc_usr', 'sc_pap', 'sc_agd_ev', 'sc_fin_cat', 'sc_fin_excluidos', 'sc_fin_extrato', 'sc_fin_extrato_imp', 'sc_nf'];
function _notifRecarregarDB(chave) {
    if (_NOTIF_CHAVES_DB.includes(chave)) _dbRecarregarChave(chave);
}

function _alertaBannerHTML(it) {
    const [bg, bord, txt] = _ALERTA_CORES[it.cor] || _ALERTA_CORES[it.urgente ? 'danger' : 'warn'];
    const acao = Notif.acoesDe(it)
        .map(a => `<button type="button" class="btn ${a.sec ? 'btn-outline' : 'btn-primary'} btn-sm" data-alerta-acao="${escapeHtml(a.fn)}">${escapeHtml(a.rotulo)}</button>`).join('');
    // Com link (e acesso a pagina), o banner inteiro leva ao destino, como no sino.
    const href = it.href && (typeof _hrefPermitido !== 'function' || _hrefPermitido(it.href)) ? it.href : '';
    return `<div data-urgente="${it.urgente ? 1 : 0}" data-chave="${escapeHtml(it.chave)}"${href ? ` data-href="${escapeHtml(href)}" role="link" tabindex="0"` : ''} style="${href ? 'cursor:pointer;' : ''}display:flex;align-items:center;flex-wrap:wrap;gap:8px;background:${bg};border:1px solid ${bord};border-radius:8px;padding:10px 16px;font-size:13px">
            <span style="font-size:17px;flex-shrink:0">${it.icone || '🔔'}</span>
            <span style="color:${txt}">${it.titulo || ''}</span>
            <span>${it.texto || ''}</span>${acao}
        </div>`;
}

function renderDashboardAlertas() {
    Notif.desenharSino();
    _renderCardAlertas();
}

function _renderCardAlertas() {
    const el = document.getElementById('dashboard-alertas');
    if (!el) return;
    if (!el._notifClique) {
        // Abrir um alerta no card tambem o marca como visto no sino.
        el._notifClique = true;
        el.addEventListener('keydown', e => {
            if ((e.key === 'Enter' || e.key === ' ') && e.target.dataset && e.target.dataset.href) { e.preventDefault(); e.target.click(); }
        });
        el.addEventListener('click', e => {
            const b = e.target.closest('[data-chave]');
            if (!b || !el.contains(b)) return;
            const ac = e.target.closest('[data-alerta-acao]');
            Notif.marcarVisto(b.dataset.chave);
            if (ac) { try { new Function(ac.dataset.alertaAcao)(); } catch (err) { console.error(err); } return; }
            // Link proprio dentro da faixa (ex.: o pedido, com onclick) cuida do clique sozinho.
            const interno = e.target.closest('[onclick]');
            if (interno && interno !== b && b.contains(interno)) return;
            if (b.dataset.href && !e.target.closest('button, a')) window.location.href = b.dataset.href;
        });
    }
    const prefNotif = prefsUsuario().notificacoes;
    const banners = Notif.listar().map(_alertaBannerHTML);

    // Contador no cabeçalho do card
    const countEl = document.getElementById('dash-alertas-count');
    if (countEl) {
        if (banners.length) {
            countEl.textContent = banners.length + (banners.length === 1 ? ' alerta' : ' alertas');
            countEl.style.background = 'var(--danger-bg)';
            countEl.style.color = 'var(--danger-text)';
        } else {
            countEl.textContent = '';
            countEl.style.background = 'var(--surface-3)';
            countEl.style.color = '#8F8F8F';
        }
    }

    if (!banners.length) {
        el.innerHTML = `<div style="display:flex;flex-direction:column;align-items:center;justify-content:center;height:100%;padding:32px 0;color:#8F8F8F;font-size:13px;gap:8px">
            <span style="font-size:32px">${prefNotif === 'nenhuma' ? '🔕' : '✅'}</span>
            <span>${prefNotif === 'nenhuma' ? 'Alertas desligados nas suas preferências.' : prefNotif === 'urgentes' ? 'Nenhum alerta urgente no momento.' : 'Nenhum alerta ativo no momento.'}</span>
        </div>`;
        clearInterval(window._dashAlertaScroll);
        return;
    }

    el.innerHTML = `<div style="display:flex;flex-direction:column;gap:8px;padding-right:2px">${banners.join('')}</div>`;

    // Auto-scroll quando há mais de um alerta
    clearInterval(window._dashAlertaScroll);
    if (banners.length > 1) {
        let pausado = false;
        el.addEventListener('mouseenter', () => { pausado = true; }, { passive: true });
        el.addEventListener('mouseleave', () => { pausado = false; }, { passive: true });
        window._dashAlertaScroll = setInterval(() => {
            if (pausado) return;
            if (el.scrollTop + el.clientHeight >= el.scrollHeight - 2) {
                // chegou ao fim — pausa 2s e volta ao topo suavemente
                clearInterval(window._dashAlertaScroll);
                setTimeout(() => {
                    el.scrollTo({ top: 0, behavior: 'smooth' });
                    setTimeout(() => {
                        if (document.getElementById('dashboard-alertas') === el) {
                            _renderCardAlertas();
                        }
                    }, 800);
                }, 2000);
            } else {
                el.scrollTop += 1;
            }
        }, 35);
    }
}

function filtrarMetrica(valor) {
    const sel = document.getElementById('filtro-status');
    if (sel) { sel.value = valor; }
    const tFiltro = document.getElementById('filtro-texto');
    if (tFiltro) tFiltro.value = '';
    renderDashboard();
    document.getElementById('tb-pedidos')?.closest('.card')?.scrollIntoView({ behavior: 'smooth' });
}

// --- ESTOQUE DE TECIDO: helpers ---
// Metragem do rolo de um tecido sem controle de estoque. E so um numero para
// o item existir na lista de rolos; ele nunca e consumido. Fica aqui, e nao
// no importador, porque o cadastro manual tambem cria esse rolo e app.js e o
// unico arquivo carregado em todas as telas.
const METRAGEM_INFINITA = 99999;

// Item marcado como "estoque infinito" na importação da tabela do fornecedor:
// está sempre disponível, nunca sofre baixa e fica fora dos alertas de mínimo.
// A flag é por registro, então nenhum item fora da importação é afetado.
function temEstoqueInfinito(registro) {
    return !!(registro && registro.estoque_infinito);
}
function tecidoTemEstoqueInfinito(tecidoId) {
    return temEstoqueInfinito(db.catalogo.find(c => c.id == tecidoId));
}
// Saldo para mostrar na tela: "∞" quando o item não tem controle de estoque.
function textoSaldoTecido(c) {
    if (temEstoqueInfinito(c)) return '∞';
    // Sem rolo nenhum o saldo e' zero, e e' isso que a coluna diz. Um traço
    // aqui se confundia com "não se aplica", que e' o caso do infinito.
    return `${estoqueDisponivel(c.id).toFixed(2)} m`;
}

// Um item infinito carrega um rolo/saldo de fachada (METRAGEM_INFINITA) so
// para aparecer nas listas. Ao voltar a ser controlado, esse saldo nao pode
// virar estoque real: ele e' apagado e o item fica zerado, esperando entrada.
// Minimo para mostrar na tela. Item sem controle de estoque nao tem ponto de
// pedido, entao a coluna diz "—" mesmo que haja um numero guardado de antes.
function textoMinimo(registro, unidade) {
    if (temEstoqueInfinito(registro)) return '—';
    const m = registro && registro.min_estoque;
    return m > 0 ? m + (unidade ? ' ' + unidade : '') : '—';
}

function _ehSaldoDeFachada(rolo) {
    return rolo.lote === 'ESTOQUE INFINITO' || rolo.metragem_inicial >= METRAGEM_INFINITA;
}
function limparSaldoDeFachadaDoTecido(tecidoId) {
    const antes = db.estoque.length;
    db.estoque = db.estoque.filter(r => !(r.tecido_id == tecidoId && _ehSaldoDeFachada(r)));
    return antes !== db.estoque.length;
}

function estoqueDisponivel(tecidoId) {
    return db.estoque.filter(r => r.tecido_id == tecidoId && r.metragem_atual > 0).reduce((s, r) => s + r.metragem_atual, 0);
}
function rolosDisponiveis(tecidoId) {
    return db.estoque.filter(r => r.tecido_id == tecidoId && r.metragem_atual > 0);
}
function verificarConflitoDeLote(tecidoId, metrosNecessarios) {
    const rolos = rolosDisponiveis(tecidoId);
    if (!rolos.length) return false;
    if (rolos.some(r => r.metragem_atual >= metrosNecessarios)) return false;
    const total = rolos.reduce((s, r) => s + r.metragem_atual, 0);
    if (total < metrosNecessarios) return false;
    return new Set(rolos.map(r => r.lote)).size > 1;
}

// --- ESTOQUE DE TECIDO: CRUD ---
function _calcularPrecoVenda(custoId, markupId, displayId) {
    const custo  = parseFloat(document.getElementById(custoId)?.value) || 0;
    const markup = parseFloat(document.getElementById(markupId)?.value) || 0;
    const venda  = custo > 0 ? custo * (1 + markup / 100) : 0;
    const display = document.getElementById(displayId);
    if (display) display.textContent = 'R$ ' + venda.toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
}
function calcularPrecoVendaTecido() { _calcularPrecoVenda('est-preco-custo', 'est-markup', 'est-preco-venda-display'); }

// ─── BALANÇO DE ESTOQUE ──────────────────────────────────────────────────────

function abrirBalanco() {
    const existing = document.getElementById('balanco-overlay');
    if (existing) existing.remove();

    // --- Montar linhas de tecidos (ativos e esgotados separados) ---
    // Item sem controle de estoque (estoque infinito) nao se conta: o "rolo"
    // dele e' so um saldo de fachada. A coluna Codigo mostra o codigo do
    // tecido; o codigo do rolo vai em letra miuda embaixo do nome.
    let rowsTecidos = '';
    const rolosDoBalanco = db.estoque.filter(r => !_ehSaldoDeFachada(r) && !tecidoTemEstoqueInfinito(r.tecido_id));
    const rolosEsgotados = rolosDoBalanco.filter(r => !(r.metragem_atual > 0));
    rolosDoBalanco.forEach(r => {
        const esgotado = !(r.metragem_atual > 0);
        const cat  = db.catalogo.find(c => c.id == r.tecido_id);
        const nome = cat ? cat.nome : '—';
        const cod  = (cat && cat.referencia) || '';
        const sys  = (r.metragem_atual || 0).toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
        const rowStyle = esgotado ? 'opacity:.5;background:var(--surface-2)' : '';
        rowsTecidos += `<tr data-balanco-nome="${escapeHtml(nome.toLowerCase())}" data-balanco-ref="${escapeHtml(cod.toLowerCase())}" data-balanco-rolo-cod="${escapeHtml((r.lote||'').toLowerCase())}"
            data-pdf-cod="${escapeHtml(cod || '—')}" data-pdf-nome="${escapeHtml(nome)}" data-pdf-rolo="${escapeHtml(r.lote || '')}" data-esgotado="${esgotado ? '1' : '0'}" style="${rowStyle}">
            <td>${escapeHtml(cod || '—')}</td>
            <td>${escapeHtml(nome)}${esgotado ? ' <span style="font-size:10px;background:var(--surface-4);color:#8F8F8F;padding:1px 5px;border-radius:4px;font-weight:600">ESGOTADO</span>' : ''}${r.lote ? `<div style="font-size:11px;color:#8F8F8F">Rolo: ${escapeHtml(r.lote)}</div>` : ''}</td>
            <td style="text-align:right;color:${esgotado ? '#8F8F8F' : 'inherit'}">${sys} m</td>
            <td><input type="number" min="0" step="0.01" placeholder="—"
                data-balanco-rolo="${r.id}"
                data-sys="${r.metragem_atual || 0}"
                oninput="_diffBalanco(this)"
                style="width:100%;padding:5px 8px;border:1px solid var(--border-strong);border-radius:4px;text-align:right"></td>
            <td id="diff-rolo-${r.id}" style="text-align:right;font-weight:600;color:#8F8F8F">—</td>
        </tr>`;
    });
    if (!rowsTecidos) rowsTecidos = '<tr><td colspan="5" style="text-align:center;color:#aaa;padding:16px">Nenhum rolo em estoque</td></tr>';

    // --- Montar linhas de materiais ---
    let rowsMats = '';
    db.materiais.filter(m => !temEstoqueInfinito(m)).forEach(m => {
        const sys = (m.estoque_atual || 0).toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
        rowsMats += `<tr data-balanco-nome="${escapeHtml(m.nome.toLowerCase())}" data-balanco-ref="${escapeHtml((m.referencia||'').toLowerCase())}">
            <td>${escapeHtml(m.referencia || '—')}</td>
            <td>${escapeHtml(m.nome)}</td>
            <td style="text-align:center">${m.unidade || 'un'}</td>
            <td style="text-align:right">${sys}</td>
            <td><input type="number" min="0" step="0.01" placeholder="—"
                data-balanco-mat="${m.id}"
                data-sys="${m.estoque_atual || 0}"
                oninput="_diffBalanco(this)"
                style="width:100%;padding:5px 8px;border:1px solid var(--border-strong);border-radius:4px;text-align:right"></td>
            <td id="diff-mat-${m.id}" style="text-align:right;font-weight:600;color:#8F8F8F">—</td>
        </tr>`;
    });
    if (!rowsMats) rowsMats = '<tr><td colspan="6" style="text-align:center;color:#aaa;padding:16px">Nenhum material em estoque</td></tr>';

    const thStyle = 'background:var(--surface-2);padding:10px 12px;border-bottom:2px solid var(--border);color:var(--text-soft);font-size:13px;white-space:nowrap';
    const inpStyle = 'padding:7px 10px;border:1px solid var(--border);border-radius:6px;font-size:13px;outline:none;transition:border-color .15s;width:100%';
    const overlay = document.createElement('div');
    overlay.id = 'balanco-overlay';
    overlay.className = 'modal-overlay';
    overlay.innerHTML = `
        <div class="modal-box" style="max-width:960px;width:100%">
            <div class="modal-header">
                <div>
                    <h3 style="margin:0;font-size:16px">📋 Balanço de Estoque</h3>
                    <p style="margin:4px 0 0;font-size:12px;color:#8F8F8F">${new Date().toLocaleDateString('pt-BR', {day:'2-digit',month:'long',year:'numeric'})}</p>
                </div>
                <div style="display:flex;gap:8px;align-items:center">
                    <button class="btn btn-success btn-sm" id="btn-enviar-doc" onclick="abrirEnviarBalanco(this)">📤 Enviar</button>
                    <button class="btn btn-outline btn-sm" onclick="exportarBalancoPDF()">📄 Exportar PDF</button>
                    <button class="btn btn-success btn-sm" onclick="aplicarAjustesBalanco()">✔ Aplicar Ajustes</button>
                    <button class="modal-close" onclick="document.getElementById('balanco-overlay').remove()">×</button>
                </div>
            </div>
            <div class="modal-body">
                <p style="font-size:13px;color:#8F8F8F;margin-bottom:14px">
                    Preencha a coluna <strong>Contado</strong> com as quantidades físicas apuradas. Deixe em branco os itens não contados.
                    Clique em <strong>Exportar PDF</strong> para imprimir a planilha de contagem, ou em <strong>Aplicar Ajustes</strong> para atualizar o estoque.
                </p>

                <!-- Filtros -->
                <div class="balanco-caixa" style="display:flex;gap:10px;margin-bottom:${rolosEsgotados.length ? '8px' : '20px'};padding:12px 14px;background:var(--surface-2);border:1px solid var(--border);border-radius:8px;flex-wrap:wrap">
                    <div style="flex:1;min-width:150px">
                        <label style="font-size:11px;font-weight:600;color:#8F8F8F;text-transform:uppercase;letter-spacing:.4px;display:block;margin-bottom:4px">Código</label>
                        <input id="balanco-filter-ref" type="text" list="balanco-lista-cod" autocomplete="off" placeholder="Código do item ou do rolo..." style="${inpStyle}" oninput="_balancoDigitou('cod')">
                    </div>
                    <div style="flex:2;min-width:180px">
                        <label style="font-size:11px;font-weight:600;color:#8F8F8F;text-transform:uppercase;letter-spacing:.4px;display:block;margin-bottom:4px">Nome</label>
                        <input id="balanco-filter-nome" type="text" list="balanco-lista-nome" autocomplete="off" placeholder="Nome do item..." style="${inpStyle}" oninput="_balancoDigitou('nome')">
                    </div>
                    <datalist id="balanco-lista-cod">${_itensDoBalanco().filter(i => i.cod).map(i => `<option value="${escapeHtml(i.cod)}">${escapeHtml(i.nome)}</option>`).join('')}</datalist>
                    <datalist id="balanco-lista-nome">${_balancoOpcoesNome()}</datalist>
                    <div style="display:flex;align-items:flex-end;gap:8px">
                        <button class="btn btn-outline btn-sm" onclick="_limparFiltrosBalanco()" style="white-space:nowrap">✕ Limpar</button>
                    </div>
                </div>
                ${rolosEsgotados.length ? `<div class="balanco-caixa" style="margin-bottom:16px;padding:8px 12px;background:var(--surface-2);border:1px solid var(--border);border-radius:6px;display:flex;align-items:center;gap:10px;font-size:12px;color:#8F8F8F">
                    <label style="display:flex;align-items:center;gap:6px;cursor:pointer;user-select:none">
                        <input type="checkbox" id="balanco-show-esgotados" onchange="_filtrarBalanco()" style="width:14px;height:14px;cursor:pointer">
                        Mostrar <strong style="color:var(--dark)">${rolosEsgotados.length} rolo(s) esgotado(s)</strong> (metragem = 0 no sistema)
                    </label>
                </div>` : ''}

                <h4 style="font-size:13px;font-weight:700;text-transform:uppercase;letter-spacing:.5px;color:var(--primary-text);margin-bottom:8px">🧵 Tecidos / Rolos</h4>
                <div style="overflow-x:auto;margin-bottom:24px">
                    <table style="width:100%;border-collapse:collapse;font-size:13px">
                        <thead><tr>
                            <th style="${thStyle}">Código</th>
                            <th style="${thStyle}">Tecido</th>
                            <th style="${thStyle};text-align:right">Sist. (m)</th>
                            <th style="${thStyle};text-align:right;width:130px">Contado (m)</th>
                            <th style="${thStyle};text-align:right;width:100px">Diferença</th>
                        </tr></thead>
                        <tbody id="balanco-tbody-tecidos">${rowsTecidos}</tbody>
                    </table>
                </div>

                <h4 style="font-size:13px;font-weight:700;text-transform:uppercase;letter-spacing:.5px;color:var(--primary-text);margin-bottom:8px">🔩 Materiais e Acessórios</h4>
                <div style="overflow-x:auto">
                    <table style="width:100%;border-collapse:collapse;font-size:13px">
                        <thead><tr>
                            <th style="${thStyle}">Código</th>
                            <th style="${thStyle}">Material</th>
                            <th style="${thStyle};text-align:center">Un.</th>
                            <th style="${thStyle};text-align:right">Sist.</th>
                            <th style="${thStyle};text-align:right;width:130px">Contado</th>
                            <th style="${thStyle};text-align:right;width:100px">Diferença</th>
                        </tr></thead>
                        <tbody id="balanco-tbody-mats">${rowsMats}</tbody>
                    </table>
                </div>
            </div>
        </div>`;
    document.body.appendChild(overlay);
    overlay.addEventListener('click', e => { if (e.target === overlay) overlay.remove(); });
    // Oculta rolos esgotados por padrão ao abrir
    if (rolosEsgotados.length) _filtrarBalanco();
}

// Itens que entram no balanco (com controle de estoque), para as sugestoes
// e para o preenchimento automatico Codigo <-> Nome.
function _itensDoBalanco() {
    const itens = [];
    db.catalogo.filter(c => !temEstoqueInfinito(c)).forEach(c => itens.push({ cod: c.referencia || '', nome: c.nome || '', tipo: 'Tecido' }));
    db.materiais.filter(m => !temEstoqueInfinito(m)).forEach(m => itens.push({ cod: m.referencia || '', nome: m.nome || '', tipo: 'Material' }));
    const vezes = {};
    itens.forEach(i => { const k = i.nome.trim().toLowerCase(); vezes[k] = (vezes[k] || 0) + 1; });
    // Nome repetido (ex.: um tecido e um material): a sugestao leva o tipo.
    itens.forEach(i => { i.repetido = vezes[i.nome.trim().toLowerCase()] > 1; i.rotulo = i.repetido ? `${i.nome} — ${i.tipo}` : i.nome; });
    // Mesmo nome e mesmo tipo: o codigo desempata ("Nome — Tecido (T-100)").
    const rotulos = {};
    itens.forEach(i => { const k = i.rotulo.trim().toLowerCase(); rotulos[k] = (rotulos[k] || 0) + 1; });
    itens.forEach(i => { if (rotulos[i.rotulo.trim().toLowerCase()] > 1 && i.cod) i.rotulo = `${i.rotulo} (${i.cod})`; });
    return itens;
}

// Sugestoes do campo Nome: nome repetido aparece como "Nome — Tipo".
function _balancoOpcoesNome() {
    return _itensDoBalanco().map(i => `<option value="${escapeHtml(i.rotulo)}">${escapeHtml(i.cod)}</option>`).join('');
}

// O que foi digitado no Nome aponta para um item? Nome unico, ou sugestao
// "Nome — Tipo" escolhida. Nome repetido sem o tipo nao aponta para nenhum.
function _balancoItemPorNome(v) {
    const itens = _itensDoBalanco();
    const porRotulo = itens.find(i => i.rotulo.trim().toLowerCase() === v);
    if (porRotulo) return porRotulo;
    const iguais = itens.filter(i => i.nome.trim().toLowerCase() === v);
    return iguais.length === 1 ? iguais[0] : null;
}

// Digitou o codigo exato de um item: o nome vem sozinho (e vice-versa). Se o
// campo de origem deixa de bater, o que foi preenchido sozinho e' apagado.
function _balancoDigitou(campo) {
    const cod  = document.getElementById('balanco-filter-ref');
    const nome = document.getElementById('balanco-filter-nome');
    if (!cod || !nome) return;
    const fonte = campo === 'cod' ? cod : nome;
    const alvo  = campo === 'cod' ? nome : cod;
    const v = fonte.value.trim().toLowerCase();
    const item = v && (campo === 'cod'
        ? _itensDoBalanco().find(i => i.cod.trim().toLowerCase() === v)
        : _balancoItemPorNome(v));
    delete fonte.dataset.auto;
    if (item) {
        // escolheu "Nome — Tipo": o campo fica com o nome puro e o codigo certo
        if (campo === 'nome' && fonte.value.trim().toLowerCase() !== item.nome.trim().toLowerCase()) fonte.value = item.nome;
        alvo.value = campo === 'cod' ? item.nome : item.cod;
        alvo.dataset.auto = '1';
    } else if (alvo.dataset.auto === '1') {
        alvo.value = '';
        delete alvo.dataset.auto;
    }
    _filtrarBalanco();
}

function _filtrarBalanco() {
    const nome         = (document.getElementById('balanco-filter-nome')?.value || '').toLowerCase().trim();
    const ref          = (document.getElementById('balanco-filter-ref')?.value  || '').toLowerCase().trim();
    const mostrarEsg   = document.getElementById('balanco-show-esgotados')?.checked ?? true;
    document.querySelectorAll('#balanco-tbody-tecidos tr[data-balanco-nome], #balanco-tbody-mats tr[data-balanco-nome]').forEach(tr => {
        const trNome     = tr.dataset.balancoNome || '';
        const trRef      = tr.dataset.balancoRef  || '';
        const trRolo     = tr.dataset.balancoRoloCod || '';
        const isEsgotado = tr.dataset.esgotado === '1';
        const passaNome  = !nome || trNome.includes(nome);
        const passaRef   = !ref  || trRef.includes(ref) || trRolo.includes(ref);
        const passaEsg   = !isEsgotado || mostrarEsg;
        tr.style.display = passaNome && passaRef && passaEsg ? '' : 'none';
    });
}

function _limparFiltrosBalanco() {
    const n = document.getElementById('balanco-filter-nome');
    const r = document.getElementById('balanco-filter-ref');
    if (n) { n.value = ''; delete n.dataset.auto; }
    if (r) { r.value = ''; delete r.dataset.auto; }
    _filtrarBalanco();
}

async function _logoBase64() {
    return new Promise(resolve => {
        const img = new Image();
        img.crossOrigin = 'anonymous';
        img.onload = () => {
            try {
                const c = document.createElement('canvas');
                c.width = img.naturalWidth; c.height = img.naturalHeight;
                c.getContext('2d').drawImage(img, 0, 0);
                resolve(c.toDataURL('image/png'));
            } catch(e) { resolve(null); }
        };
        img.onerror = () => resolve(null);
        img.src = 'images/logo.png';
    });
}

function _diffBalanco(input) {
    const sys = parseFloat(input.dataset.sys) || 0;
    const contado = input.value === '' ? null : parseFloat(input.value);
    const roloId = input.dataset.balancoRolo;
    const matId  = input.dataset.balancoMat;
    const cellId = roloId ? `diff-rolo-${roloId}` : `diff-mat-${matId}`;
    const cell   = document.getElementById(cellId);
    if (!cell) return;
    if (contado === null || isNaN(contado)) { cell.textContent = '—'; cell.style.color = '#8F8F8F'; return; }
    const diff = contado - sys;
    const fmt  = (Math.abs(diff)).toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
    if (Math.abs(diff) < 0.001) { cell.textContent = '='; cell.style.color = '#8F8F8F'; }
    else if (diff > 0)  { cell.textContent = `+${fmt}`; cell.style.color = 'var(--primary-text)'; }
    else                { cell.textContent = `−${fmt}`; cell.style.color = '#F43927'; }
}

async function _balancoPdfPartes() {
    const dataHoje = new Date().toLocaleDateString('pt-BR', { day: '2-digit', month: '2-digit', year: 'numeric' });
    const logoSrc  = await _logoBase64();
    const logoHtml = logoSrc
        ? `<img src="${logoSrc}" style="width:52px;height:52px;object-fit:contain;border-radius:10px;border:1px solid #E0E0E0;padding:4px;background:#fff">`
        : `<div style="width:52px;height:52px;background:#005D3B;border-radius:10px;display:flex;align-items:center;justify-content:center;color:white;font-weight:800;font-size:20px">S</div>`;

    const trStyle = 'border-bottom:1px solid #E0E0E0';
    const th = (t, extra='') => `<th style="background:#FAFAFA;padding:10px 12px;border-bottom:2px solid #E0E0E0;font-size:11px;color:#444;text-align:left;${extra}">${t}</th>`;
    const td = (t, extra='') => `<td style="padding:10px 12px;font-size:12px;${extra}">${t}</td>`;
    const tdBlank = (w='120px') => `<td style="padding:10px 12px;border-bottom:1px solid #aaa;width:${w}"></td>`;

    // Lê apenas linhas visíveis do modal (respeita filtros ativos)
    const visibleTec = [...document.querySelectorAll('#balanco-tbody-tecidos tr[data-balanco-nome]')]
        .filter(tr => tr.style.display !== 'none');
    const visibleMat = [...document.querySelectorAll('#balanco-tbody-mats tr[data-balanco-nome]')]
        .filter(tr => tr.style.display !== 'none');

    const filtroNome = (document.getElementById('balanco-filter-nome')?.value || '').trim();
    const filtroRef  = (document.getElementById('balanco-filter-ref')?.value  || '').trim();
    const filtroAtivo = filtroNome || filtroRef;
    const filtroDesc = [filtroNome && `Nome: "${filtroNome}"`, filtroRef && `Código: "${filtroRef}"`].filter(Boolean).join(' · ');

    let rowsTec = '';
    visibleTec.forEach(tr => {
        const cells    = tr.querySelectorAll('td');
        const esgotado = tr.dataset.esgotado === '1';
        const rolo     = tr.dataset.pdfRolo ? `<div style="font-size:10px;color:#8F8F8F">Rolo: ${escapeHtml(tr.dataset.pdfRolo)}</div>` : '';
        const nomeCell = escapeHtml(tr.dataset.pdfNome || '—') + (esgotado ? ' (esgotado)' : '') + rolo;
        const extra    = esgotado ? 'color:#8F8F8F;font-style:italic' : '';
        rowsTec += `<tr style="${trStyle}">${td(escapeHtml(tr.dataset.pdfCod || '—'), extra)}${td(nomeCell, extra)}${td(cells[2]?.textContent||'—', 'text-align:right;'+extra)}${tdBlank('120px')}${tdBlank('100px')}</tr>`;
    });

    let rowsMat = '';
    visibleMat.forEach(tr => {
        const cells = tr.querySelectorAll('td');
        rowsMat += `<tr style="${trStyle}">${td(cells[0]?.textContent||'—')}${td(cells[1]?.textContent||'—')}${td(cells[2]?.textContent||'un','text-align:center')}${td(cells[3]?.textContent||'—','text-align:right')}${tdBlank('120px')}${tdBlank('100px')}</tr>`;
    });

    // estilo(raiz): as regras do documento presas a um seletor raiz; no PDF
    // enviado elas nao podem vazar para a tela do sistema.
    const estilo = raiz => `
        ${raiz} * { margin:0; padding:0; box-sizing:border-box; font-family:'Segoe UI',Arial,sans-serif; }
        ${raiz} table { width:100%; border-collapse:collapse; margin-bottom:32px; }
        ${raiz} h2 { font-size:21px; font-weight:800; margin-bottom:2px; }
        ${raiz} h3 { font-size:12px; font-weight:700; text-transform:uppercase; letter-spacing:.6px; color:#005D3B; margin:24px 0 10px; border-left:3px solid #005D3B; padding-left:8px; }`;
    const corpo = `
    <!-- Cabeçalho -->
    <div style="display:flex;justify-content:space-between;align-items:center;padding-bottom:18px;border-bottom:3px solid #005D3B;margin-bottom:24px">
        <div style="display:flex;align-items:center;gap:14px">
            ${logoHtml}
            <div>
                <div style="font-size:20px;font-weight:800;color:#005D3B;line-height:1.1">SCTech</div>
                <div style="font-size:11px;color:#8F8F8F;margin-top:2px">Sistema de Gestão</div>
            </div>
        </div>
        <div style="text-align:right">
            <h2 style="color:#242424">Balanço de Estoque</h2>
            <div style="font-size:12px;color:#8F8F8F;margin-top:4px">Data: <strong>${dataHoje}</strong></div>
            <div style="font-size:12px;margin-top:8px;display:flex;align-items:center;gap:6px;justify-content:flex-end">
                Responsável:&nbsp;<span style="display:inline-block;min-width:200px;border-bottom:1px solid #999">&nbsp;</span>
            </div>
        </div>
    </div>

    ${filtroAtivo ? `<div style="margin-bottom:20px;padding:8px 12px;background:#FEFAE9;border:1px solid #F2C924;border-radius:6px;font-size:11px;color:#8A6A00">
        <strong>Filtro aplicado:</strong> ${filtroDesc} — exibindo ${visibleTec.length} tecido(s) e ${visibleMat.length} material(is).
    </div>` : ''}

    <h3>Tecidos / Rolos</h3>
    <table>
        <thead><tr>${th('Código')}${th('Tecido')}${th('Qtd. Sistema','text-align:right')}${th('Qtd. Contada','text-align:right;width:130px')}${th('Diferença','text-align:right;width:110px')}</tr></thead>
        <tbody>${rowsTec || `<tr><td colspan="5" style="padding:14px;color:#aaa;text-align:center">${filtroAtivo ? 'Nenhum tecido corresponde ao filtro' : 'Nenhum rolo em estoque'}</td></tr>`}</tbody>
    </table>

    <h3>Materiais e Acessórios</h3>
    <table>
        <thead><tr>${th('Código')}${th('Material')}${th('Un.','text-align:center;width:60px')}${th('Qtd. Sistema','text-align:right')}${th('Qtd. Contada','text-align:right;width:130px')}${th('Diferença','text-align:right;width:110px')}</tr></thead>
        <tbody>${rowsMat || `<tr><td colspan="6" style="padding:14px;color:#aaa;text-align:center">${filtroAtivo ? 'Nenhum material corresponde ao filtro' : 'Nenhum material em estoque'}</td></tr>`}</tbody>
    </table>

    <!-- Assinaturas -->
    <div style="margin-top:48px;display:flex;justify-content:space-between;gap:24px;padding-top:20px;border-top:1px solid #E0E0E0">
        <div style="text-align:center;flex:1">
            <div style="border-top:1px solid #555;margin:0 16px 8px;padding-top:8px"></div>
            <div style="font-size:11px;color:#8F8F8F">Responsável pelo Balanço</div>
        </div>
        <div style="text-align:center;flex:1">
            <div style="border-top:1px solid #555;margin:0 16px 8px;padding-top:8px"></div>
            <div style="font-size:11px;color:#8F8F8F">Supervisor / Aprovação</div>
        </div>
        <div style="text-align:center;flex:1">
            <div style="border-top:1px solid #555;margin:0 16px 8px;padding-top:8px"></div>
            <div style="font-size:11px;color:#8F8F8F">Data de Conclusão</div>
        </div>
    </div>

`;
    return { dataHoje, estilo, corpo };
}

async function exportarBalancoPDF() {
    const { dataHoje, estilo, corpo } = await _balancoPdfPartes();
    const html = `<!DOCTYPE html><html lang="pt-BR"><head><meta charset="UTF-8">
    <title>Balanço de Estoque — ${dataHoje}</title>
    <style>
        ${estilo('')}
        body { padding:32px 40px; color:#242424; background:#fff; }
        @media print {
            @page { size: A4; margin:20mm 18mm; }
            body { padding:0; }
            .no-print { display:none !important; }
        }
    </style>
    </head><body>${corpo}
    <script>window.onload = () => window.print();<\/script>
    </body></html>`;
    const win = window.open('', '_blank');
    win.document.write(html);
    win.document.close();
}

// "Enviar" do balanco: monta o mesmo documento do PDF (respeitando os
// filtros) num elemento, e o envio gera o PDF dele.
async function abrirEnviarBalanco(botao) {
    const { dataHoje, estilo, corpo } = await _balancoPdfPartes();
    const el = document.createElement('div');
    el.className = 'bal-doc';
    el.innerHTML = `<style>${estilo('.bal-doc')}</style>${corpo}`;
    definirEnvioDoc(envioDocumentoInterno('Balanço de estoque — ' + dataHoje, 'Balanco-de-estoque-' + dataHoje.replace(/\//g, '-'), () => el));
    abrirMenuEnviar(botao);
}

function _showConfirmBalanco(ajustes) {
    return new Promise(resolve => {
        const o = _getModal();
        document.getElementById('sc-modal-icon').textContent = '📋';
        const msgEl = document.getElementById('sc-modal-msg');

        const fmt = (v, un) => v.toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 }) + (un ? ' ' + un : '');
        let listHtml = `<strong style="font-size:14px;display:block;margin-bottom:10px">Confirmar ${ajustes.length} ajuste(s) no estoque?</strong>`;
        listHtml += `<div style="max-height:240px;overflow-y:auto;text-align:left;border:1px solid var(--border);border-radius:8px;background:var(--surface-2)">`;
        ajustes.forEach((a, i) => {
            const nome   = a.tipo === 'rolo'
                ? ((db.catalogo.find(c => c.id === a.rolo.tecido_id)?.nome || 'Tecido') + (a.rolo.lote ? ` [${a.rolo.lote}]` : ''))
                : a.mat.nome;
            const antes  = a.tipo === 'rolo' ? (a.rolo.metragem_atual || 0) : (a.mat.estoque_atual || 0);
            const un     = a.tipo === 'rolo' ? 'm' : (a.mat.unidade || 'un');
            const diff   = a.contado - antes;
            const color  = diff > 0 ? 'var(--primary-text)' : '#F43927';
            const sign   = diff > 0 ? '+' : '';
            const sep    = i < ajustes.length - 1 ? 'border-bottom:1px solid var(--border)' : '';
            listHtml += `<div style="padding:8px 12px;${sep};display:flex;justify-content:space-between;align-items:center;gap:16px;font-size:12px">
                <span style="color:var(--dark);font-weight:500;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${nome}</span>
                <span style="white-space:nowrap;flex-shrink:0;color:#8F8F8F">
                    ${fmt(antes, un)} → <strong style="color:${color}">${fmt(a.contado, un)}</strong>
                    <span style="color:${color};margin-left:4px">(${sign}${fmt(Math.abs(diff), '')})</span>
                </span>
            </div>`;
        });
        listHtml += `</div><p style="font-size:11px;color:#8F8F8F;margin-top:10px">As quantidades serão registradas no histórico de movimentações.</p>`;
        msgEl.innerHTML = listHtml;

        const btns = document.getElementById('sc-modal-btns');
        btns.innerHTML = `<button class="btn btn-outline" id="sc-modal-cancel">Cancelar</button><button class="btn btn-success" id="sc-modal-ok">Confirmar Ajustes</button>`;
        o.style.display = 'flex';
        const close = val => {
            o.style.display = 'none';
            document.removeEventListener('keydown', esc);
            msgEl.innerHTML = '';
            resolve(val);
        };
        const esc = e => { if (e.key === 'Escape') close(false); };
        document.getElementById('sc-modal-ok').addEventListener('click', () => close(true), { once: true });
        document.getElementById('sc-modal-cancel').addEventListener('click', () => close(false), { once: true });
        document.addEventListener('keydown', esc);
        document.getElementById('sc-modal-ok').focus();
    });
}

function _atualizarLinhasBalanco(ajustes) {
    const fmt2 = v => v.toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
    ajustes.forEach(a => {
        if (a.tipo === 'rolo') {
            const input = document.querySelector(`[data-balanco-rolo="${a.rolo.id}"]`);
            if (!input) return;
            const novo = a.rolo.metragem_atual;
            input.dataset.sys = novo;
            input.value = '';
            const cells = input.closest('tr')?.querySelectorAll('td');
            if (cells?.[2]) cells[2].textContent = fmt2(novo) + ' m';
            const diffCell = document.getElementById(`diff-rolo-${a.rolo.id}`);
            if (diffCell) { diffCell.textContent = '—'; diffCell.style.color = '#8F8F8F'; }
        } else {
            const input = document.querySelector(`[data-balanco-mat="${a.mat.id}"]`);
            if (!input) return;
            const novo = a.mat.estoque_atual;
            input.dataset.sys = novo;
            input.value = '';
            const cells = input.closest('tr')?.querySelectorAll('td');
            if (cells?.[3]) cells[3].textContent = fmt2(novo);
            const diffCell = document.getElementById(`diff-mat-${a.mat.id}`);
            if (diffCell) { diffCell.textContent = '—'; diffCell.style.color = '#8F8F8F'; }
        }
    });
}

async function aplicarAjustesBalanco() {
    const ajustes = [];

    document.querySelectorAll('[data-balanco-rolo]').forEach(input => {
        if (input.value === '') return;
        const contado = parseFloat(input.value);
        if (isNaN(contado)) return;
        const rolo = db.estoque.find(r => r.id == input.dataset.balancoRolo);
        if (!rolo) return;
        const diff = contado - (rolo.metragem_atual || 0);
        if (Math.abs(diff) < 0.001) return;
        ajustes.push({ tipo: 'rolo', rolo, diff, contado });
    });

    document.querySelectorAll('[data-balanco-mat]').forEach(input => {
        if (input.value === '') return;
        const contado = parseFloat(input.value);
        if (isNaN(contado)) return;
        const mat = db.materiais.find(m => m.id == input.dataset.balancoMat);
        if (!mat) return;
        const diff = contado - (mat.estoque_atual || 0);
        if (Math.abs(diff) < 0.001) return;
        ajustes.push({ tipo: 'mat', mat, diff, contado });
    });

    if (!ajustes.length) {
        toast('Nenhuma diferença para ajustar. Preencha as quantidades contadas.', 'info');
        return;
    }

    if (!await _showConfirmBalanco(ajustes)) return;

    ajustes.forEach(a => {
        if (a.tipo === 'rolo') {
            const cat  = db.catalogo.find(c => c.id === a.rolo.tecido_id);
            const nome = (cat ? cat.nome : 'Tecido') + ' [' + (a.rolo.lote || '') + ']';
            a.rolo.metragem_atual = Math.max(0, a.contado);
            registrarMovimento(a.diff >= 0 ? 'Ajuste +' : 'Ajuste -', nome, 'tecido', a.diff, 'm', a.rolo.lote || '');
        } else {
            a.mat.estoque_atual = Math.max(0, a.contado);
            registrarMovimento(a.diff >= 0 ? 'Ajuste +' : 'Ajuste -', a.mat.nome, 'material', a.diff, a.mat.unidade || 'un', a.mat.referencia || '');
        }
    });

    syncDB();
    _atualizarLinhasBalanco(ajustes);
    toast(`${ajustes.length} ajuste(s) aplicado(s) com sucesso!`, 'success');
    renderEstoque();
    renderEstoqueMateriais();
}

// ─────────────────────────────────────────────────────────────────────────────

async function salvarEntradaEstoque() {
    const referencia = document.getElementById('est-lote').value.trim();
    const tecidoId   = parseInt(document.getElementById('est-tecido').value);
    const metros     = parseFloat(document.getElementById('est-metros').value);
    const data       = document.getElementById('est-data').value;
    const custo      = parseFloat(document.getElementById('est-preco-custo')?.value) || 0;
    const markup     = parseFloat(document.getElementById('est-markup')?.value) || 0;
    if (!referencia)            { await showAlert('Informe a referência do rolo.', '⚠️'); return; }
    if (!tecidoId)              { await showAlert('Escolha o tecido na lista de sugestões.', '⚠️'); return; }
    if (!metros || metros <= 0) { await showAlert('Informe a metragem do rolo.', '⚠️'); return; }
    const nomeTecConf = db.catalogo.find(t => t.id === tecidoId)?.nome || '—';
    const precoVendaConf = custo > 0 ? (custo * (1 + markup / 100)).toFixed(2) : null;
    const linhaPreco = custo > 0 ? `\nCusto: R$ ${custo.toFixed(2)}/m  →  Venda: R$ ${precoVendaConf}/m` : '';
    if (!await showConfirm(`Confirmar entrada de rolo?\n\nTecido: ${nomeTecConf}\nCódigo: ${referencia}\nMetragem: ${metros} m${linhaPreco}`, '📦', 'Confirmar Entrada', 'Cancelar')) return;
    _aplicarEntradaTecido({ tecidoId, lote: referencia, metros, data, custo, markup });
    salvarERecarregar('Entrada registrada!');
}

// Grava a entrada de um rolo: rolo no estoque, custo/preco do tecido e o
// movimento "Entrada". Usada pela entrada manual e pela entrada que abre quando
// o pedido de compra e marcado Recebido. markup null = nao mexe no preco de venda.
function _aplicarEntradaTecido({ tecidoId, lote, metros, data, custo, markup }) {
    let id = Date.now();
    while (db.estoque.some(r => r.id === id)) id++;
    db.estoque.push({ id, tecido_id: tecidoId, lote, metragem_inicial: metros, metragem_atual: metros, data_entrada: data });
    const tec = db.catalogo.find(t => t.id === tecidoId);
    if (custo > 0 && tec) {
        tec.preco_custo = custo;
        if (markup !== null) tec.preco = Math.round(custo * (1 + markup / 100) * 100) / 100;
    }
    registrarMovimento('Entrada', `${tec?.nome || 'Tecido'} — Código ${lote}`, 'tecido', metros, 'm', lote);
}

function autoFillTecidoNoAmbiente(ambId, tidx) {
    const ref = document.getElementById(`a-tec-ref-${ambId}-${tidx}`)?.value.trim();
    if (!ref || ref.length < 2) return;
    const tec = db.catalogo.find(c => c.referencia && c.referencia.toLowerCase() === ref.toLowerCase());
    if (!tec) return;
    const sel = document.getElementById(`a-tecido-${ambId}-${tidx}`);
    if (sel) sel.value = String(tec.id);
}

function autoFillRefFromTecido(ambId, tidx) {
    const selEl = document.getElementById(`a-tecido-${ambId}-${tidx}`);
    if (!selEl || !selEl.value) return;
    const tec = db.catalogo.find(c => c.id == selEl.value);
    const refEl = document.getElementById(`a-tec-ref-${ambId}-${tidx}`);
    if (refEl) refEl.value = tec?.referencia || '';
}

// ═══════════════════════════════════════════════════════════════════════
// CAMPO DE BUSCA COM SUGESTOES
// ═══════════════════════════════════════════════════════════════════════
//
// Substitui os <select> de tecido e de material nas entradas de estoque. Um
// input de texto visivel, com o nome, e um input escondido com o ID: o ID e' a
// fonte da verdade, e por isso mexer no texto o limpa — ver um nome na tela e
// gravar outro item seria pior do que nao achar nada.
//
// Uma implementacao so para os dois campos. O <select> que saiu dava para usar
// pelo teclado, entao setas, Enter e Esc continuam funcionando aqui.

const _BUSCAS = {
    'est-tecido': {
        itens: () => db.catalogo,
        rotulo: c => c.nome,
        aoEscolher: () => autoFillEntradaTecido(),
        vazio: 'Nenhum tecido com esse código ou nome'
    },
    'est-mat-id': {
        itens: () => db.materiais,
        rotulo: m => `${m.nome} (${m.unidade || 'un'})`,
        aoEscolher: () => autoFillEntradaMaterialById(),
        vazio: 'Nenhum material com esse código ou nome'
    }
};

// Qual sugestao esta percorrida pelo teclado, por campo. -1 = nenhuma.
const _buscaAtiva = {};

function _buscaNormaliza(t) {
    return String(t || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').trim();
}

function _buscaAchados(campo) {
    const cfg = _BUSCAS[campo];
    const termo = _buscaNormaliza(document.getElementById(campo + '-busca')?.value);
    if (!termo) return [];
    return cfg.itens().filter(i =>
        _buscaNormaliza(i.nome).includes(termo) || _buscaNormaliza(i.referencia).includes(termo)
    ).slice(0, 12);
}

function _buscaRender(campo) {
    const caixa = document.getElementById(campo + '-sug');
    if (!caixa) return;
    const achados = _buscaAchados(campo);
    const ativa = _buscaAtiva[campo];

    if (!document.getElementById(campo + '-busca')?.value.trim()) {
        caixa.classList.remove('aberta'); caixa.innerHTML = ''; return;
    }
    if (!achados.length) {
        caixa.innerHTML = `<div class="consulta-sug-item" style="cursor:default;color:var(--muted)">${escapeHtml(_BUSCAS[campo].vazio)}</div>`;
        caixa.classList.add('aberta');
        return;
    }
    caixa.innerHTML = achados.map((i, n) => `
        <div class="consulta-sug-item${n === ativa ? ' ativa' : ''}" onclick="buscaEscolher('${campo}', ${i.id})">
            <span class="consulta-sug-cod">${escapeHtml(i.referencia || '—')}</span>
            <span class="consulta-sug-nome">${escapeHtml(_BUSCAS[campo].rotulo(i))}</span>
        </div>`).join('');
    caixa.classList.add('aberta');
    caixa.querySelector('.consulta-sug-item.ativa')?.scrollIntoView({ block: 'nearest' });
}

// Digitar invalida a escolha anterior: o texto e o id precisam andar juntos.
function buscaDigitou(campo) {
    const esc = document.getElementById(campo);
    if (esc) esc.value = '';
    _buscaAtiva[campo] = -1;
    _buscaRender(campo);
}

function buscaEscolher(campo, id) {
    const item = _BUSCAS[campo].itens().find(i => i.id == id);
    if (!item) return;
    const esc = document.getElementById(campo);
    const txt = document.getElementById(campo + '-busca');
    if (esc) esc.value = String(item.id);
    if (txt) txt.value = _BUSCAS[campo].rotulo(item);
    buscaFechar(campo);
    _BUSCAS[campo].aoEscolher();
}

function buscaFechar(campo) {
    _buscaAtiva[campo] = -1;
    const caixa = document.getElementById(campo + '-sug');
    if (caixa) { caixa.classList.remove('aberta'); caixa.innerHTML = ''; }
}

function buscaTecla(campo, e) {
    const achados = _buscaAchados(campo);
    const aberta = document.getElementById(campo + '-sug')?.classList.contains('aberta');
    if (e.key === 'Escape') { buscaFechar(campo); return; }
    if (!achados.length) return;

    if (e.key === 'ArrowDown' || e.key === 'ArrowUp') {
        e.preventDefault();
        if (!aberta) { _buscaRender(campo); return; }
        const total = achados.length;
        const atual = _buscaAtiva[campo] === undefined ? -1 : _buscaAtiva[campo];
        // Da' a volta nas duas pontas: do ultimo para o primeiro e vice-versa.
        _buscaAtiva[campo] = e.key === 'ArrowDown'
            ? (atual + 1) % total
            : (atual <= 0 ? total - 1 : atual - 1);
        _buscaRender(campo);
        return;
    }
    if (e.key === 'Enter') {
        // Sem nada percorrido, um unico achado e' escolha obvia; varios, nao.
        const alvo = _buscaAtiva[campo] >= 0 ? achados[_buscaAtiva[campo]]
            : (achados.length === 1 ? achados[0] : null);
        if (alvo) { e.preventDefault(); buscaEscolher(campo, alvo.id); }
    }
}

// Preenche de fora (ex.: achar o tecido pelo lote digitado).
function buscaDefinir(campo, id) {
    const item = _BUSCAS[campo].itens().find(i => i.id == id);
    if (!item) return;
    const esc = document.getElementById(campo);
    const txt = document.getElementById(campo + '-busca');
    if (esc) esc.value = String(item.id);
    if (txt) txt.value = _BUSCAS[campo].rotulo(item);
    buscaFechar(campo);
}

document.addEventListener('click', e => {
    Object.keys(_BUSCAS).forEach(campo => {
        if (e.target.closest && e.target.closest('#' + campo + '-campo')) return;
        buscaFechar(campo);
    });
});

function autoFillEntradaTecido() {
    const tecidoId = parseInt(document.getElementById('est-tecido')?.value);
    if (!tecidoId) return;
    const tec = db.catalogo.find(t => t.id === tecidoId);
    const ultimoRolo = db.estoque.filter(r => r.tecido_id === tecidoId).sort((a, b) => b.id - a.id)[0];
    if (ultimoRolo) {
        const metrosEl = document.getElementById('est-metros');
        if (metrosEl) metrosEl.value = ultimoRolo.metragem_inicial;
    }
    if (tec) {
        // Escolher o tecido pelo nome preenche a referencia com o codigo dele,
        // para nao ser preciso saber o codigo de cor. So preenche se o campo
        // estiver VAZIO: se o usuario ja digitou um banho de cor, ele manda.
        const refEl = document.getElementById('est-lote');
        if (refEl && !refEl.value.trim() && tec.referencia) refEl.value = tec.referencia;
        const custoEl = document.getElementById('est-preco-custo');
        if (custoEl && tec.preco_custo) custoEl.value = tec.preco_custo;
        const markupEl = document.getElementById('est-markup');
        if (markupEl && tec.preco_custo > 0 && tec.preco > 0)
            markupEl.value = Math.round(((tec.preco / tec.preco_custo) - 1) * 100);
        calcularPrecoVendaTecido();
    }
}

function autoFillEntradaMaterialById() {
    const matId = parseInt(document.getElementById('est-mat-id')?.value);
    if (!matId) return;
    const mat = db.materiais.find(m => m.id === matId);
    if (!mat) return;
    const lastMov = db.movimentos.filter(m => m.item_nome === mat.nome && m.tipo === 'Entrada').sort((a, b) => b.id - a.id)[0];
    if (lastMov) {
        const qtdEl = document.getElementById('est-mat-qtd');
        if (qtdEl) qtdEl.value = lastMov.quantidade;
    }
    if (mat.preco_custo > 0) {
        const custoEl = document.getElementById('est-mat-preco-custo');
        if (custoEl) custoEl.value = mat.preco_custo;
        const markupEl = document.getElementById('est-mat-markup');
        if (markupEl && mat.preco > 0)
            markupEl.value = Math.round(((mat.preco / mat.preco_custo) - 1) * 100);
        calcularPrecoVendaMat();
    }
}

function autoFillTecidoPorReferencia() {
    const ref = document.getElementById('est-lote')?.value.trim();
    if (!ref || ref.length < 2) return;
    if (!document.getElementById('est-tecido')) return;
    const tec = db.catalogo.find(c => c.referencia && c.referencia.toLowerCase() === ref.toLowerCase());
    if (tec) { buscaDefinir('est-tecido', tec.id); autoFillEntradaTecido(); return; }
    const existing = db.estoque.find(r => r.lote && r.lote.toLowerCase() === ref.toLowerCase());
    if (existing) { buscaDefinir('est-tecido', existing.tecido_id); autoFillEntradaTecido(); }
}

// Qual tecido esta com os rolos abertos na aba Estoque. Um de cada vez.
let _estoqueTecidoAberto = null;

function alternarRolosDoTecido(id) {
    _estoqueTecidoAberto = _estoqueTecidoAberto === id ? null : id;
    renderEstoque();
}

function mostrarBaixaForm(roloId) {
    document.querySelectorAll('.baixa-form').forEach(el => { el.style.display = 'none'; });
    const row = document.getElementById('baixa-' + roloId);
    if (row) row.style.display = 'table-row';
}
function cancelarBaixa() {
    document.querySelectorAll('.baixa-form').forEach(el => { el.style.display = 'none'; });
}
async function confirmarBaixa(roloId) {
    const rolo = db.estoque.find(r => r.id == roloId);
    if (!rolo) return;
    const qtd = parseFloat(document.getElementById('baixa-qtd-' + roloId).value);
    if (!qtd || qtd <= 0) { await showAlert('Informe a quantidade a baixar.', '⚠️'); return; }
    if (qtd > rolo.metragem_atual) { await showAlert(`Quantidade maior que o saldo disponível (${rolo.metragem_atual.toFixed(3)} m).`, '⚠️'); return; }
    rolo.metragem_atual = Math.round((rolo.metragem_atual - qtd) * 1000) / 1000;
    const nomeTecBaixa = db.catalogo.find(t => t.id === rolo.tecido_id)?.nome || 'Tecido';
    registrarMovimento('Baixa Manual', `${nomeTecBaixa} — Ref. ${rolo.lote}`, 'tecido', qtd, 'm', '');
    salvarERecarregar('Baixa de estoque registrada!');
}
async function removerRolo(id) {
    if (!await showConfirm('Remover este rolo do estoque?', '🗑️', 'Remover', 'Cancelar')) return;
    db.estoque = db.estoque.filter(r => r.id != id);
    salvarERecarregar('Rolo removido.');
}

// Um tecido "já teve entrada" se existe rolo dele — mesmo zerado, porque rolo
// esgotado continua sendo histórico de compra — ou se há movimento de entrada
// registrado em nome dele.
function teveEntradaDeTecido(tecidoId) {
    if ((db.estoque || []).some(r => r.tecido_id == tecidoId)) return true;
    const tec = (db.catalogo || []).find(c => c.id == tecidoId);
    if (!tec) return false;
    return (db.movimentos || []).some(mv =>
        mv.tipo === 'Entrada' && mv.item_tipo === 'tecido' && mv.item_nome === tec.nome);
}

// Recolhe ou mostra a lista de alertas de estoque mínimo. A escolha fica
// guardada, senão o usuário teria de recolher de novo a cada visita.
function alternarAlertasTecido() {
    const atual = localStorage.getItem('sc_alertas_tecido_recolhidos') === '1';
    localStorage.setItem('sc_alertas_tecido_recolhidos', atual ? '0' : '1');
    renderEstoque();
}

// --- ESTOQUE DE TECIDO: renderização ---
// Busca da Gestao de Estoque (Tecidos, Materiais, Kits): um campo so, que
// procura no codigo e na descricao. Sem o campo na pagina (ex.: Catalogo),
// nada e' filtrado.
function textoBuscaEstoque(inputId) {
    const el = document.getElementById(inputId);
    return el ? el.value.trim().toLowerCase() : '';
}
function passaBuscaEstoque(item, busca) {
    if (!busca) return true;
    return [item.referencia, item.nome, item.descricao]
        .some(t => String(t || '').toLowerCase().includes(busca));
}
function linhaNadaEncontrado(colunas) {
    return `<tr><td colspan="${colunas}" style="text-align:center;color:#999;padding:24px;">Nenhum item encontrado para a busca.</td></tr>`;
}

function renderEstoque() {
    const tb = document.getElementById('tb-estoque');
    if (!tb) return;
    // a coluna Acoes so tem o botao do carrinho (exige Estoque completo): sem ele, some inteira
    const comAcoes = podeAdicionarAoCarrinho();
    const thAcoes = document.getElementById('th-estoque-acoes');
    if (thAcoes) thAcoes.style.display = comAcoes ? '' : 'none';

    const alertBox = document.getElementById('alertas-ponto-pedido');
    if (alertBox) {
        // Só alerta tecido que JÁ TEVE entrada. Um tecido recém-cadastrado e
        // nunca comprado não está "abaixo do mínimo" — está apenas por usar, e
        // avisar sobre ele enche a tela de ruído.
        const criticos = db.catalogo.filter(c =>
            !temEstoqueInfinito(c) && c.min_estoque > 0 && teveEntradaDeTecido(c.id) && estoqueDisponivel(c.id) < c.min_estoque);
        if (criticos.length) {
            const recolhido = localStorage.getItem('sc_alertas_tecido_recolhidos') === '1';
            alertBox.innerHTML = `
                <div class="alertas-cabecalho">
                    <span>⚠ ${criticos.length} tecido(s) abaixo do estoque mínimo</span>
                    <button type="button" class="alertas-toggle" onclick="alternarAlertasTecido()">
                        ${recolhido ? 'Mostrar' : 'Recolher'}
                    </button>
                </div>
                <div class="alertas-corpo" ${recolhido ? 'style="display:none"' : ''}>
                    ${criticos.map(c =>
                        `<div class="alerta-item">⚠ <strong>${escapeHtml(c.nome)}</strong>: ${estoqueDisponivel(c.id).toFixed(2)} m disponível — mínimo: ${c.min_estoque} m</div>`
                    ).join('')}
                </div>`;
            alertBox.style.display = 'block';
        } else {
            alertBox.innerHTML = '';
            alertBox.style.display = 'none';
        }
    }

    // Uma linha por tecido, nas mesmas colunas do Cadastro/Catálogo (mais a
    // unidade, pedida para o módulo de estoque). Os rolos — com Baixar e
    // Remover — aparecem ao clicar na linha, como na Consulta de Estoque.
    let html = '';
    pintarCabecalhoOrdenacao('#tabela-est-tecidos', catSortState);
    const buscaTec = textoBuscaEstoque('busca-est-tecidos');
    ordenarLista(db.catalogo, catSortState, valorOrdenacaoTecido).filter(tec => passaBuscaEstoque(tec, buscaTec)).forEach(tec => {
        const rolos = db.estoque.filter(r => r.tecido_id == tec.id);
        const infinito = temEstoqueInfinito(tec);
        const totalDisp = rolos.reduce((s, r) => s + r.metragem_atual, 0);
        const abaixoMin = !infinito && tec.min_estoque > 0 && totalDisp < tec.min_estoque;
        const aberto = _estoqueTecidoAberto === tec.id;
        const saldo = infinito ? '<strong title="Estoque infinito">∞</strong>'
            : `<strong>${totalDisp.toFixed(2)}</strong> m`;

        html += `<tr class="est-tec-linha${aberto ? ' aberta' : ''}" onclick="alternarRolosDoTecido(${tec.id})">
            <td class="col-codigo" title="${escapeHtml(tec.referencia || '')}">${escapeHtml(tec.referencia || '—')}</td>
            <td class="col-nome" title="${escapeHtml(tec.nome)}"><strong>${escapeHtml(tec.nome)}</strong>${abaixoMin ? ' <span class="badge-alerta">⚠</span>' : ''}</td>
            <td class="col-un">m</td>
            <td class="col-num">${(tec.largura_rolo || 2.80).toFixed(2)} m</td>
            <td class="col-num">${saldo}</td>
            <td class="col-num">${textoMinimo(tec, 'm')}</td>
            <td class="col-num">${tec.preco > 0 ? 'R$ ' + tec.preco.toFixed(2) : '—'}</td>
            <td class="col-forn" title="${escapeHtml(tec.fornecedor_nome || '')}">${escapeHtml(tec.fornecedor_nome || '—')}</td>
            <td class="col-acoes">${rolos.length ? `${rolos.length} rolo(s) ${aberto ? '▲' : '▼'}` : '<span style="color:#999">sem rolo</span>'}</td>
            ${comAcoes ? `<td class="col-acoes">${botaoAdicionarAoCarrinho('tecido', tec.id)}</td>` : ''}
        </tr>`;

        if (!aberto || !rolos.length) return;
        html += `<tr class="est-tec-rolos"><td colspan="${comAcoes ? 10 : 9}"><table class="est-rolos-tabela">
            <thead><tr><th>Código</th><th>Metragem inicial</th><th>Disponível</th><th>Ocupação</th><th>Entrada</th><th>Ações</th></tr></thead>
            <tbody>` + rolos.map(r => {
            const pct = r.metragem_inicial > 0 ? Math.round((r.metragem_atual / r.metragem_inicial) * 100) : 0;
            const cor = pct > 40 ? 'var(--primary-text)' : pct > 15 ? '#F2C924' : '#F43927';
            const esgotado = r.metragem_atual <= 0;
            return `<tr class="${esgotado ? 'rolo-esgotado' : ''}">
                <td>${escapeHtml(r.lote)}</td>
                <td>${infinito ? '∞' : r.metragem_inicial.toFixed(2) + ' m'}</td>
                <td><strong>${infinito ? '∞' : r.metragem_atual.toFixed(3) + ' m'}</strong></td>
                <td>${infinito ? '<span style="font-size:11px;color:#8F8F8F">sem controle de estoque</span>'
                    : `<div class="progresso-bar"><div class="progresso-fill" style="width:${pct}%;background:${cor}"></div></div><span style="font-size:11px;color:#888">${pct}%</span>`}</td>
                <td>${new Date(r.data_entrada + 'T12:00:00').toLocaleDateString('pt-BR')}</td>
                <td onclick="event.stopPropagation()">
                    ${infinito ? '' : (!esgotado ? `<button class="btn btn-outline btn-sm" onclick="mostrarBaixaForm(${r.id})">↓ Baixar</button>` : '<span class="badge-esgotado">Esgotado</span>')}
                    <button class="btn btn-outline btn-sm btn-danger" onclick="removerRolo(${r.id})">🗑️</button>
                </td>
            </tr>
            ${infinito ? '' : `<tr id="baixa-${r.id}" class="baixa-form" style="display:none">
                <td colspan="6" class="baixa-form-cell" onclick="event.stopPropagation()">
                    <strong>Baixar rolo ${escapeHtml(r.lote)}</strong> — saldo: <strong>${r.metragem_atual.toFixed(3)} m</strong> &emsp;
                    <input type="number" id="baixa-qtd-${r.id}" placeholder="Metros a baixar" step="0.001" min="0.001" max="${r.metragem_atual}" style="width:160px;padding:5px 8px;border:1px solid var(--border-strong);border-radius:4px">
                    <button class="btn btn-sm" style="background:#F2C924" onclick="confirmarBaixa(${r.id})">Confirmar Baixa</button>
                    <button class="btn btn-outline btn-sm" onclick="cancelarBaixa()">Cancelar</button>
                </td>
            </tr>`}`;
        }).join('') + `</tbody></table></td></tr>`;
    });
    if (!html && buscaTec && db.catalogo.length) { tb.innerHTML = linhaNadaEncontrado(comAcoes ? 10 : 9); return; }
    tb.innerHTML = html || `<tr><td colspan="${comAcoes ? 10 : 9}" style="text-align:center;color:#999;padding:24px;">Nenhum tecido cadastrado. <a href="catalogo.html">Cadastre em Catálogo</a>.</td></tr>`;
}

// --- MATERIAIS (acessórios, ferragens, trilhos, etc.) ---
async function salvarMaterial() {
    const referencia = document.getElementById('mat-ref')?.value.trim() || '';
    const nome = document.getElementById('mat-nome')?.value.trim();
    const unidade = document.getElementById('mat-unidade')?.value || 'un';
    const min_estoque = parseFloat(document.getElementById('mat-min')?.value) || 0;
    if (!nome) { await showAlert('Informe o nome do material.', '⚠️'); return; }
    const forn_id_mat  = parseInt(document.getElementById('mat-fornecedor')?.value) || null;
    const forn_obj_mat = forn_id_mat ? db.fornecedores.find(f => f.id === forn_id_mat) : null;
    if (editandoMaterialId !== null) {
        const m = db.materiais.find(x => x.id == editandoMaterialId);
        if (m) {
            const preco = parseFloat(document.getElementById('mat-preco')?.value) || m.preco || 0;
            const dupNome = db.materiais.find(x => x.id != editandoMaterialId && x.nome.trim().toLowerCase() === nome.toLowerCase());
            if (dupNome) { await showAlert(`Já existe outro material com o nome "${dupNome.nome}".`, '⚠️'); return; }
            if (referencia) {
                const dupRef = db.materiais.find(x => x.id != editandoMaterialId && x.referencia && x.referencia.toLowerCase() === referencia.toLowerCase());
                if (dupRef) { await showAlert(`Código "${referencia}" já usado por "${dupRef.nome}".`, '⚠️'); return; }
            }
            const eraInfinito = temEstoqueInfinito(m);
            const ficaInfinito = _matEstado.estoqueModo === 'infinito';
            if (eraInfinito && !ficaInfinito) {
                const ok = await showConfirm(
                    `"${m.nome}" passa a ter estoque controlado.\n\nO saldo infinito será apagado e o material fica zerado até você dar entrada nele.`,
                    '📦', 'Zerar e controlar', 'Cancelar');
                if (!ok) return;
                m.estoque_atual = 0;
                registrarMovimento('Saída', m.nome, 'material', 0, unidade, 'Passou a ter estoque controlado');
            }
            if (!eraInfinito && ficaInfinito) {
                registrarMovimento('Entrada', m.nome, 'material', 0, unidade, 'Passou a ter estoque infinito');
            }
            Object.assign(m, { referencia, nome, unidade, preco, min_estoque: ficaInfinito ? 0 : min_estoque, estoque_infinito: ficaInfinito, fornecedor_id: forn_id_mat, fornecedor_nome: forn_obj_mat ? forn_obj_mat.nome : '' });
        }
        editandoMaterialId = null;
        const precoGroup = document.getElementById('mat-preco-group');
        if (precoGroup) precoGroup.style.display = 'none';
        salvarERecarregar('Material atualizado!');
    } else {
        const dup = db.materiais.find(m => m.nome.trim().toLowerCase() === nome.toLowerCase());
        if (dup) { await showAlert(`Já existe um material com o nome "${dup.nome}".`, '⚠️'); return; }
        if (referencia) {
            const dupRef = db.materiais.find(m => m.referencia && m.referencia.toLowerCase() === referencia.toLowerCase());
            if (dupRef) { await showAlert(`Código "${referencia}" já usado por "${dupRef.nome}".`, '⚠️'); return; }
        }
        if (_matEstado.margemModo === 'total' && _matEstado.markup === null) {
            await showAlert('Informe a margem total (%) ou escolha “Definir margem depois”.', '⚠️');
            return;
        }
        const custo = parseFloat(document.getElementById('mat-custo')?.value) || 0;
        const qtd = parseFloat(document.getElementById('mat-qtd')?.value) || 0;
        const infinito = _matEstado.estoqueModo === 'infinito';
        db.materiais.push({
            id: Date.now(), referencia, nome, unidade,
            min_estoque: _cfgMinimo(_matEstado, min_estoque),
            // Quantidade e custo seguem a unidade escolhida acima.
            preco_custo: custo,
            preco: _cfgVenda(_matEstado, custo) || 0,
            estoque_atual: qtd,
            estoque_infinito: infinito,
            fornecedor_id: forn_id_mat,
            fornecedor_nome: forn_obj_mat ? forn_obj_mat.nome : ''
        });
        if (qtd > 0) registrarMovimento('Entrada', nome, 'material', qtd, unidade, 'Cadastro manual');
        salvarERecarregar('Material cadastrado!');
    }
}

function autoFillMaterialPorReferencia() {
    const ref = document.getElementById('mat-ref')?.value.trim();
    if (!ref || ref.length < 2) return;
    const existing = db.materiais.find(m => m.referencia && m.referencia.toLowerCase() === ref.toLowerCase());
    if (!existing) return;
    const nomeEl = document.getElementById('mat-nome');
    if (nomeEl) nomeEl.value = existing.nome || '';
    const unEl = document.getElementById('mat-unidade');
    if (unEl) unEl.value = existing.unidade || 'un';
    const precoEl = document.getElementById('mat-preco');
    if (precoEl) precoEl.value = existing.preco || '';
    const minEl = document.getElementById('mat-min');
    if (minEl) minEl.value = existing.min_estoque || 0;
    const fornSel = document.getElementById('mat-fornecedor');
    if (fornSel && existing.fornecedor_id) fornSel.value = existing.fornecedor_id;
}

async function excluirMaterial(id) {
    if (!await showConfirm('Remover este material? Kits que o utilizam serão afetados.', '🗑️', 'Remover', 'Cancelar')) return;
    db.materiais = db.materiais.filter(m => m.id != id);
    db.kits.forEach(k => { k.itens = k.itens.filter(i => i.materialId != id); });
    salvarERecarregar('Material removido.');
}

function editarMaterial(id) {
    const m = db.materiais.find(x => x.id == id);
    if (!m) return;
    editandoMaterialId = id;
    document.getElementById('mat-ref').value = m.referencia || '';
    document.getElementById('mat-nome').value = m.nome || '';
    document.getElementById('mat-unidade').value = m.unidade || 'un';
    document.getElementById('mat-min').value = m.min_estoque || 0;
    const fornSel = document.getElementById('mat-fornecedor');
    if (fornSel) fornSel.value = m.fornecedor_id || '';
    const precoGroup = document.getElementById('mat-preco-group');
    if (precoGroup) {
        precoGroup.style.display = '';
        document.getElementById('mat-preco').value = m.preco || 0;
    }
    carregarCfgDoRegistro('mat', m);
    const btn = document.querySelector('button[onclick="salvarMaterial()"]');
    if (btn) btn.textContent = 'Atualizar Material';
    document.getElementById('mat-ref').scrollIntoView({ behavior: 'smooth', block: 'start' });
}

function mostrarAjusteForm(id) {
    document.querySelectorAll('.ajuste-form').forEach(el => el.style.display = 'none');
    const row = document.getElementById('ajuste-' + id);
    if (row) row.style.display = 'table-row';
}
function cancelarAjuste() {
    document.querySelectorAll('.ajuste-form').forEach(el => el.style.display = 'none');
}

async function confirmarAjuste(id) {
    const mat = db.materiais.find(m => m.id == id);
    if (!mat) return;
    const qtd = parseFloat(document.getElementById(`ajuste-qtd-${id}`)?.value);
    if (isNaN(qtd)) { await showAlert('Informe uma quantidade válida (positivo para entrada, negativo para saída).', '⚠️'); return; }
    mat.estoque_atual = Math.max(0, (mat.estoque_atual || 0) + qtd);
    registrarMovimento(qtd >= 0 ? 'Ajuste +' : 'Ajuste -', mat.nome, 'material', qtd, mat.unidade, '');
    salvarERecarregar('Ajuste realizado!');
}

function renderMateriais() {
    const tb = document.getElementById('tb-materiais');
    if (!tb) return;

    // Alertas de mínimo
    const alertBox = document.getElementById('alertas-mat-min');
    if (alertBox) {
        const criticos = db.materiais.filter(m => !temEstoqueInfinito(m) && m.min_estoque > 0 && (m.estoque_atual || 0) < m.min_estoque);
        if (criticos.length) {
            alertBox.innerHTML = criticos.map(m =>
                `<div class="alerta-item">⚠ <strong>${m.nome}</strong>: ${(m.estoque_atual||0).toFixed(2)} ${m.unidade} — mínimo: ${m.min_estoque} ${m.unidade}</div>`
            ).join('');
            alertBox.style.display = 'block';
        }
    }

    _catPreencherSelect('f-mat-forn', _catOpcoesFornecedor(db.materiais));

    const lista = ordenarLista(filtrarMateriais(db.materiais), matSortState, valorOrdenacaoMaterial);
    catVisiveis.material = lista.map(m => m.id);
    pintarCabecalhoOrdenacao('#tabela-materiais', matSortState);

    const cont = document.getElementById('f-mat-contagem');
    if (cont) cont.textContent = lista.length === db.materiais.length
        ? `${db.materiais.length} material(is)`
        : `${lista.length} de ${db.materiais.length} material(is)`;

    tb.innerHTML = lista.map(m => {
        const abaixoMin = !temEstoqueInfinito(m) && m.min_estoque > 0 && (m.estoque_atual || 0) < m.min_estoque;
        const corEstoque = abaixoMin ? '#F43927' : 'var(--primary-text)';
        const marcado = catSelecao.material.has(m.id);
        return `
        <tr class="${marcado ? 'cat-linha-marcada' : ''}">
            <td class="cat-col-check"><input type="checkbox"${marcado ? ' checked' : ''} onchange="alternarSelecao('material',${m.id},this)"></td>
            <td class="col-codigo" title="${escapeHtml(m.referencia || '')}">${escapeHtml(m.referencia || '—')}</td>
            <td class="col-nome" title="${escapeHtml(m.nome)}"><strong>${escapeHtml(m.nome)}</strong>${abaixoMin ? `<span class="badge-alerta" style="margin-left:6px">⚠</span>` : ''}</td>
            <td class="col-un">${escapeHtml(m.unidade || '')}</td>
            <td class="col-num" style="color:${corEstoque}" title="${temEstoqueInfinito(m) || !(m.min_estoque > 0) ? '' : 'Mínimo: ' + m.min_estoque + ' ' + (m.unidade || '')}">${temEstoqueInfinito(m)
                ? '<strong title="Estoque infinito">∞</strong>'
                : `<strong>${(m.estoque_atual || 0).toFixed(2)}</strong>`}</td>
            <td class="col-num">R$ ${(m.preco || 0).toFixed(2)}</td>
            <td class="col-forn" title="${escapeHtml(m.fornecedor_nome || '')}">${escapeHtml(m.fornecedor_nome || '—')}</td>
            <td class="col-acoes">${menuAcoesHtml([
                { icone: '✏️', rotulo: 'Editar', onclick: `editarMaterial(${m.id})` },
                { icone: '±', rotulo: 'Ajustar estoque', onclick: `mostrarAjusteForm(${m.id})` },
                { icone: '🛒', rotulo: 'Adicionar ao carrinho', onclick: `abrirAdicionarAoCarrinho('material',${m.id})`, oculto: !podeAdicionarAoCarrinho() },
                { icone: '🗑️', rotulo: 'Excluir material', onclick: `excluirMaterial(${m.id})`, perigo: true }
            ])}</td>
        </tr>
        <tr id="ajuste-${m.id}" class="ajuste-form" style="display:none">
            <td colspan="8" class="baixa-form-cell">
                <strong>${escapeHtml(m.nome)}</strong> — saldo: <strong>${(m.estoque_atual||0).toFixed(2)} ${m.unidade}</strong> &emsp;
                Quantidade (+ entrada / − saída):
                <input type="number" id="ajuste-qtd-${m.id}" placeholder="Ex: +10 ou -3" step="0.01" style="width:130px;padding:5px 8px;border:1px solid var(--border-strong);border-radius:4px;margin:0 8px">
                <button class="btn btn-sm" style="background:#005D3B" onclick="confirmarAjuste(${m.id})">Confirmar</button>
                <button class="btn btn-outline btn-sm" onclick="cancelarAjuste()">Cancelar</button>
            </td>
        </tr>`;
    }).join('') || `<tr><td colspan="8" style="text-align:center;color:#999;padding:24px;">${db.materiais.length ? 'Nenhum material com esses filtros.' : 'Nenhum material cadastrado.'}</td></tr>`;

    atualizarBarraSelecao('material');
}

function sortMateriais(col) {
    if (matSortState.col === col) matSortState.dir *= -1;
    else { matSortState.col = col; matSortState.dir = 1; }
    _gravarOrdenacao('material', matSortState);
    renderMateriais();
    renderEstoqueMateriais();
}

function sortKits(col) {
    if (kitSortState.col === col) kitSortState.dir *= -1;
    else { kitSortState.col = col; kitSortState.dir = 1; }
    _gravarOrdenacao('kit', kitSortState);
    renderKits();
}

// --- KITS ---
let kitDraftItens = [];
let kitEditandoId = null;   // kit de montagem aberto para edição (null = criando)

// Kit de fixação: kit de montagem marcado para aparecer em "Material de
// Instalação" no pedido. Kit pronto nunca é de fixação.
function ehKitFixacao(kit) {
    return !!(kit && kit.fixacao === true && !ehKitPronto(kit));
}

// Item de kit contado por metro (largura da parede) ou por kit (fixo).
function textoQtdItemKit(i) {
    return `${i.quantidade} ${i.unidade || ''}${i.por_metro ? '/m' : ''}`.replace(/\s+\//, '/').trim();
}

async function adicionarItemAoKit() {
    const matId = parseInt(document.getElementById('kit-item-mat')?.value);
    const qtd   = parseFloat(document.getElementById('kit-item-qtd')?.value);
    const porMetro = document.getElementById('kit-item-modo')?.value === 'metro';
    if (!matId) { await showAlert('Escolha o material na lista de sugestões.', '⚠️'); return; }
    if (!qtd || qtd <= 0) { await showAlert('Informe uma quantidade válida.', '⚠️'); return; }
    const mat = db.materiais.find(m => m.id == matId);
    if (!mat) return;
    // Mesmo material com a mesma contagem soma; com contagem diferente vira outra linha.
    const existing = kitDraftItens.find(i => i.materialId === matId && !!i.por_metro === porMetro);
    if (existing) { existing.quantidade += qtd; }
    else { kitDraftItens.push({ materialId: matId, nome: mat.nome, unidade: mat.unidade, quantidade: qtd, por_metro: porMetro }); }
    renderKitDraftItens();
}

function removerItemDoKit(idx) {
    kitDraftItens.splice(idx, 1);
    renderKitDraftItens();
}

function mudarModoItemDoKit(idx, valor) {
    if (kitDraftItens[idx]) kitDraftItens[idx].por_metro = valor === 'metro';
}

function renderKitDraftItens() {
    const tb = document.getElementById('tb-kit-draft');
    if (!tb) return;
    if (!kitDraftItens.length) {
        tb.innerHTML = '<tr><td colspan="4" style="text-align:center;color:#999;padding:10px;font-size:13px">Nenhum item adicionado ainda.</td></tr>';
        return;
    }
    tb.innerHTML = kitDraftItens.map((i, idx) => `<tr>
        <td>${escapeHtml(i.nome)}</td>
        <td>${i.quantidade} ${escapeHtml(i.unidade || '')}</td>
        <td><select class="kit-item-modo-linha" onchange="mudarModoItemDoKit(${idx}, this.value)" aria-label="Contagem de ${escapeHtml(i.nome)}">
            <option value="kit"${i.por_metro ? '' : ' selected'}>Por kit</option>
            <option value="metro"${i.por_metro ? ' selected' : ''}>Por metro</option>
        </select></td>
        <td><button class="btn btn-outline btn-sm btn-danger" onclick="removerItemDoKit(${idx})">✕</button></td>
    </tr>`).join('');
}

function editarKit(id) {
    const kit = db.kits.find(k => k.id == id);
    if (!kit || ehKitPronto(kit) || !document.getElementById('kit-ref')) return;
    kitEditandoId = kit.id;
    document.getElementById('kit-ref').value = kit.referencia || '';
    document.getElementById('kit-nome').value = kit.nome || '';
    const desc = document.getElementById('kit-desc'); if (desc) desc.value = kit.descricao || '';
    const fix = document.getElementById('kit-fixacao'); if (fix) fix.checked = ehKitFixacao(kit);
    kitDraftItens = (kit.itens || []).map(i => ({ ...i }));
    renderKitDraftItens();
    const titulo = document.getElementById('kit-form-titulo'); if (titulo) titulo.textContent = 'Editar Kit';
    const salvar = document.getElementById('kit-btn-salvar'); if (salvar) salvar.textContent = 'Salvar Alterações';
    const cancelar = document.getElementById('kit-btn-cancelar'); if (cancelar) cancelar.hidden = false;
    document.getElementById('kit-form-card')?.scrollIntoView({ behavior: 'smooth', block: 'start' });
}

function cancelarEdicaoKit() {
    kitEditandoId = null;
    ['kit-ref', 'kit-nome', 'kit-desc'].forEach(id => { const el = document.getElementById(id); if (el) el.value = ''; });
    const fix = document.getElementById('kit-fixacao'); if (fix) fix.checked = false;
    kitDraftItens = [];
    renderKitDraftItens();
    const titulo = document.getElementById('kit-form-titulo'); if (titulo) titulo.textContent = 'Criar Kit';
    const salvar = document.getElementById('kit-btn-salvar'); if (salvar) salvar.textContent = 'Salvar Kit';
    const cancelar = document.getElementById('kit-btn-cancelar'); if (cancelar) cancelar.hidden = true;
}

// Uma regra só de normalização de código em todo o sistema: a do importador.
// As telas que criam código carregam importador-core.js por isso — duas
// implementações da mesma regra é como elas acabam divergindo.
function normalizarCodigoDoSistema(bruto) {
    return window.ImportadorCore.normalizarCodigo(bruto).codigo;
}

// Código já em uso por um tecido, material ou kit. Devolve a descrição do dono
// ou null. Um código vale para o sistema inteiro, não só dentro do seu tipo.
function donoDoCodigo(codigo, ignorarKitId) {
    const alvo = normalizarCodigoDoSistema(codigo);
    if (!alvo) return null;
    const bate = r => {
        const cod = normalizarCodigoDoSistema(r.referencia);
        return cod && cod === alvo;
    };
    const tec = (db.catalogo || []).find(bate);
    if (tec) return `o tecido "${tec.nome}"`;
    const mat = (db.materiais || []).find(bate);
    if (mat) return `o material "${mat.nome}"`;
    const kit = (db.kits || []).find(k => k.id !== ignorarKitId && bate(k));
    if (kit) return `o kit "${kit.nome}"`;
    return null;
}

async function salvarKit() {
    const ref = document.getElementById('kit-ref')?.value.trim();
    const nome = document.getElementById('kit-nome')?.value.trim();
    if (!ref) { await showAlert('Informe o código do kit.', '⚠️'); return; }
    if (!nome) { await showAlert('Informe o nome do kit.', '⚠️'); return; }
    const editando = kitEditandoId != null ? db.kits.find(k => k.id === kitEditandoId) : null;
    const dono = donoDoCodigo(ref, editando ? editando.id : undefined);
    if (dono) { await showAlert(`O código ${ref} já é de ${dono}. Use outro código.`, '🚫'); return; }
    const fixacao = !!document.getElementById('kit-fixacao')?.checked;
    // Kit de fixação pode nascer vazio: só registra o tipo de instalação.
    if (!kitDraftItens.length && !fixacao) { await showAlert('Adicione pelo menos um item ao kit.', '⚠️'); return; }
    const dados = {
        referencia: normalizarCodigoDoSistema(ref),
        nome,
        descricao: document.getElementById('kit-desc')?.value.trim() || '',
        fixacao,
        itens: kitDraftItens.map(i => ({ ...i, por_metro: !!i.por_metro }))
    };
    if (editando) {
        Object.assign(editando, dados);
        kitEditandoId = null;
        salvarERecarregar('Kit atualizado!');
        return;
    }
    db.kits.push({ id: Date.now(), ...dados });
    salvarERecarregar('Kit salvo!');
}

// ═══════════════════════════════════════════════════════════════════════
// KIT PRONTO criado à mão (Cadastro › Kits)
//
// Mesmo produto que vem da importação: código e preço próprios, sem os
// materiais descritos. Os cartões de margem e estoque são os mesmos da
// popup de importação, para a regra ser uma só.
// ═══════════════════════════════════════════════════════════════════════

const _kpEstado  = { margemModo: 'total', estoqueModo: 'ajustar', markup: null };
const _catEstado = { margemModo: 'total', estoqueModo: 'ajustar', markup: null };
const _matEstado = { margemModo: 'total', estoqueModo: 'ajustar', markup: null };

// ─── Cartões de margem e estoque, compartilhados pelas três abas ─────────
//
// Uma implementação só. Copiar este bloco para cada aba e' exatamente como as
// tres versoes acabariam divergindo — ja aconteceu nesta base com a validacao
// do passo 3 do importador.
//
// `cfg` = { prefixo, estado, item }. O `item` so troca a palavra nas
// descricoes ("o kit", "o tecido", "o material"); os TITULOS sao identicos
// nas tres abas, de proposito.
const _CFG_ABAS = {
    kp:  { estado: _kpEstado,  item: 'O kit',      aoMudar: () => atualizarVendaKitPronto() },
    cat: { estado: _catEstado, item: 'O tecido',   aoMudar: () => atualizarVendaTecido() },
    mat: { estado: _matEstado, item: 'O material', aoMudar: () => atualizarVendaMaterial() }
};

// `soEstoque` e' o modo edicao: ali o preco de venda e' digitado direto no
// campo, entao os cartoes de margem nao mandam em nada e mostra-los seria
// mentir para quem edita. Os de estoque continuam, porque eles mandam.
function renderCartoesConfig(prefixo, soEstoque) {
    const alvo = document.getElementById(prefixo + '-cfg');
    const cfg = _CFG_ABAS[prefixo];
    if (!alvo || !cfg || typeof _impIcone !== 'function') return;
    const estado = cfg.estado;

    const campoMargem = `<div class="imp-cfg-campo">
        <label for="${prefixo}-markup">Margem total (%)</label>
        <div class="imp-cfg-campo-caixa">
            <input type="number" id="${prefixo}-markup" value="${estado.markup === null ? '' : estado.markup}"
                   min="0" step="1" placeholder="Ex.: 30" oninput="_cfgMargemMudou('${prefixo}', this.value)" onclick="event.stopPropagation()">
            <span class="imp-cfg-sufixo">%</span>
        </div>
    </div>`;

    const card = (grupo, valor, icone, titulo, descricao, extra) => {
        const atual = grupo === 'margem' ? estado.margemModo : estado.estoqueModo;
        const sel = atual === valor;
        return `<label class="imp-cfg-card${sel ? ' imp-cfg-card-sel' : ''}">
            <div class="imp-cfg-topo">
                <input type="radio" name="${prefixo}-cfg-${grupo}" value="${valor}"${sel ? ' checked' : ''}
                       onchange="_cfgEscolher('${prefixo}','${grupo}','${valor}')">
                ${_impIcone(icone)}
                <span class="imp-cfg-titulo">${titulo}</span>
            </div>
            <p class="imp-cfg-desc">${descricao}</p>
            ${sel && extra ? extra : ''}
        </label>`;
    };

    const it = cfg.item;
    const margem = soEstoque ? [] : [
        card('margem', 'total', 'porcento', 'Definir margem total',
            'A margem informada forma o preço de venda a partir do custo.', campoMargem),
        card('margem', 'item', 'sliders', 'Definir margem depois',
            `${it} entra com a venda igual ao custo e você ajusta o preço quando quiser.`)
    ];
    alvo.innerHTML = margem.concat([
        card('estoque', 'infinito', 'infinito', 'Estoque infinito',
            `${it} fica sempre disponível. Não haverá controle de estoque, baixa ou entrada.`),
        card('estoque', 'ajustar', 'caixa', 'Ajustar estoque',
            'O estoque será controlado. Você dá entrada depois e o sistema faz a baixa ao sair nos pedidos.')
    ]).join('');
    alvo.dataset.soEstoque = soEstoque ? '1' : '';
    _cfgCampoMinimo(prefixo, estado.estoqueModo === 'infinito');
    cfg.aoMudar();
}

// Item sem controle de estoque nao tem ponto de pedido: pedir um minimo que
// nunca sera comparado so faz o usuario preencher a toa. O campo some, e o
// valor digitado antes nao e' apagado — se ele voltar para estoque
// controlado, o minimo que ele tinha definido reaparece.
const _CFG_CAMPO_MINIMO = { kp: 'kp-min', cat: 'cat-min', mat: 'mat-min' };
function _cfgCampoMinimo(prefixo, infinito) {
    const campo = document.getElementById(_CFG_CAMPO_MINIMO[prefixo]);
    const grupo = campo?.closest('.form-group');
    if (grupo) grupo.style.display = infinito ? 'none' : '';
}
// Quem grava: infinito nao guarda minimo.
function _cfgMinimo(estado, valor) {
    return estado.estoqueModo === 'infinito' ? 0 : valor;
}

// Quem re-renderiza depois de um clique precisa manter o modo em que a tela
// esta: senao os cartoes de margem voltariam no meio de uma edicao.
function _cfgSoEstoque(prefixo) {
    return document.getElementById(prefixo + '-cfg')?.dataset.soEstoque === '1';
}

// Leva o item que esta sendo editado para dentro dos cartoes, para a tela
// dizer a verdade sobre ele. Sem isto a edicao mostrava sempre "Ajustar
// estoque", mesmo num item infinito.
function carregarCfgDoRegistro(prefixo, registro) {
    const estado = _CFG_ABAS[prefixo]?.estado;
    if (!estado) return;
    estado.estoqueModo = temEstoqueInfinito(registro) ? 'infinito' : 'ajustar';
    renderCartoesConfig(prefixo, true);
    _cfgAjuda(prefixo, true);
}

// O texto de ajuda da secao fala de margem; na edicao, so de estoque.
function _cfgAjuda(prefixo, soEstoque) {
    const secao = document.getElementById(prefixo + '-cfg')?.closest('.imp-cfg-secao');
    const ajuda = secao?.querySelector('.imp-cfg-secao-ajuda');
    if (!ajuda) return;
    if (ajuda.dataset.original === undefined) ajuda.dataset.original = ajuda.textContent;
    ajuda.textContent = soEstoque
        ? 'Escolha o controle de estoque deste item. A margem não aparece aqui porque, na edição, o preço de venda é digitado direto no campo acima.'
        : ajuda.dataset.original;
}

function _cfgEscolher(prefixo, grupo, valor) {
    const estado = _CFG_ABAS[prefixo].estado;
    if (grupo === 'margem') estado.margemModo = valor;
    else estado.estoqueModo = valor;
    renderCartoesConfig(prefixo, _cfgSoEstoque(prefixo));
}

function _cfgMargemMudou(prefixo, valor) {
    const estado = _CFG_ABAS[prefixo].estado;
    const bruto = String(valor).trim();
    const v = parseFloat(bruto);
    estado.markup = (bruto !== '' && isFinite(v) && v >= 0) ? v : null;
    _CFG_ABAS[prefixo].aoMudar();
}

// Venda = custo x (1 + margem/100), a mesma conta do resto do sistema.
function _cfgVenda(estado, custo) {
    if (!isFinite(custo) || custo <= 0) return null;
    const margem = estado.margemModo === 'item' ? 0 : (estado.markup || 0);
    return window.ImportadorCore.aplicarMarkup(custo, margem);
}

function _cfgMostrarVenda(idSaida, estado, custo, sufixo) {
    const el = document.getElementById(idSaida);
    if (!el) return;
    const venda = _cfgVenda(estado, custo);
    el.textContent = venda === null ? '—' : 'R$ ' + venda.toFixed(2) + (sufixo || '');
}

function renderCfgKitPronto() { renderCartoesConfig('kp'); }

function atualizarVendaKitPronto() {
    _cfgMostrarVenda('kp-venda', _kpEstado, parseFloat(document.getElementById('kp-custo')?.value));
}

function atualizarVendaTecido() {
    _cfgMostrarVenda('cat-venda', _catEstado, parseFloat(document.getElementById('cat-custo')?.value), '/m');
}

function atualizarVendaMaterial() {
    const un = document.getElementById('mat-unidade')?.value || '';
    _cfgMostrarVenda('mat-venda', _matEstado, parseFloat(document.getElementById('mat-custo')?.value), un ? '/' + un : '');
}

async function salvarKitPronto() {
    const ref = document.getElementById('kp-ref')?.value.trim();
    const nome = document.getElementById('kp-nome')?.value.trim();
    const custo = parseFloat(document.getElementById('kp-custo')?.value);

    if (!ref) { await showAlert('Informe o código do kit.', '⚠️'); return; }
    if (!nome) { await showAlert('Informe o nome do kit.', '⚠️'); return; }
    if (!isFinite(custo) || custo <= 0) { await showAlert('Informe o preço de custo do kit.', '⚠️'); return; }
    if (_kpEstado.margemModo === 'total' && _kpEstado.markup === null) {
        await showAlert('Informe a margem total (%) ou escolha “Definir margem depois”.', '⚠️');
        return;
    }
    const dono = donoDoCodigo(ref);
    if (dono) { await showAlert(`O código ${ref} já é de ${dono}. Use outro código.`, '🚫'); return; }

    const margem = _kpEstado.margemModo === 'item' ? 0 : _kpEstado.markup;
    db.kits.push({
        id: Date.now(),
        tipo: 'pronto',
        referencia: normalizarCodigoDoSistema(ref),
        nome,
        descricao: document.getElementById('kp-desc')?.value.trim() || '',
        medida: document.getElementById('kp-medida')?.value.trim() || '',
        preco_custo: Math.round(custo * 100) / 100,
        preco: window.ImportadorCore.aplicarMarkup(custo, margem),
        estoque_atual: parseFloat(document.getElementById('kp-qtd')?.value) || 0,
        min_estoque: _cfgMinimo(_kpEstado, parseFloat(document.getElementById('kp-min')?.value) || 0),
        estoque_infinito: _kpEstado.estoqueModo === 'infinito',
        fornecedor_id: null,
        fornecedor_nome: '',
        // Kit pronto não tem componentes; a lista vazia existe para o código
        // que lê k.itens continuar funcionando sem checagem.
        itens: []
    });
    salvarERecarregar('Kit pronto cadastrado!');
}

async function excluirKit(id) {
    if (!await showConfirm('Remover este kit?', '🗑️', 'Remover', 'Cancelar')) return;
    db.kits = db.kits.filter(k => k.id != id);
    salvarERecarregar('Kit removido.');
}

// Ajuste de saldo de kit pronto, irmão do ajuste de material.
async function confirmarAjusteKit(id) {
    const kit = db.kits.find(k => k.id == id);
    if (!kit) return;
    const qtd = parseFloat(document.getElementById(`ajuste-qtd-kit-${id}`)?.value);
    if (isNaN(qtd)) { await showAlert('Informe uma quantidade válida (positivo para entrada, negativo para saída).', '⚠️'); return; }
    kit.estoque_atual = Math.max(0, (kit.estoque_atual || 0) + qtd);
    registrarMovimento(qtd >= 0 ? 'Ajuste +' : 'Ajuste -', kit.nome, 'kit', qtd, 'un', '');
    salvarERecarregar('Ajuste realizado!');
}

function renderKits() {
    const tb = document.getElementById('tb-kits');
    if (!tb) return;
    if (!db.kits.length) {
        tb.innerHTML = '<tr><td colspan="8" style="text-align:center;color:#999;padding:24px;">Nenhum kit cadastrado.</td></tr>';
        return;
    }
    // A lista do Estoque tem uma coluna de unidade a mais que a do Catálogo,
    // pedida para o módulo de estoque. A tabela diz qual das duas é.
    const comUnidade = !!tb.closest('table')?.dataset.comUnidade;
    pintarCabecalhoOrdenacao('#tabela-kits', kitSortState);
    const buscaKit = textoBuscaEstoque('busca-est-kits');
    const kits = ordenarLista(db.kits, kitSortState, valorOrdenacaoKit).filter(k => passaBuscaEstoque(k, buscaKit));
    if (!kits.length) { tb.innerHTML = linhaNadaEncontrado(comUnidade ? 8 : 7); return; }
    tb.innerHTML = kits.map(k => {
        const pronto = ehKitPronto(k);
        const saldo = temEstoqueInfinito(k) ? '<strong title="Estoque infinito">∞</strong>'
            : (pronto ? `<strong>${(k.estoque_atual || 0).toFixed(0)}</strong> un` : '—');
        const composicao = pronto
            ? '<span style="color:#999">kit pronto do fornecedor</span>'
            : ((k.itens || []).length
                ? k.itens.map(i => `${escapeHtml(i.nome)}: ${escapeHtml(textoQtdItemKit(i))}`).join(' · ')
                : '<span style="color:#999">sem itens</span>');
        const selo = pronto
            ? '<span class="kit-selo">pronto</span>'
            : ehKitFixacao(k)
                ? '<span class="kit-selo kit-selo-fixacao">fixação</span>'
                : '<span class="kit-selo kit-selo-montagem">montagem</span>';
        const colunas = comUnidade ? 8 : 7;
        const linhaAjuste = pronto && !temEstoqueInfinito(k) ? `
        <tr id="ajuste-kit-${k.id}" class="ajuste-form" style="display:none">
            <td colspan="${colunas}" class="baixa-form-cell">
                <strong>${escapeHtml(k.nome)}</strong> — saldo: <strong>${(k.estoque_atual || 0).toFixed(0)} un</strong> &emsp;
                Quantidade (+ entrada / − saída):
                <input type="number" id="ajuste-qtd-kit-${k.id}" placeholder="Ex: +10 ou -3" step="1" style="width:130px;padding:5px 8px;border:1px solid var(--border-strong);border-radius:4px;margin:0 8px">
                <button class="btn btn-sm" style="background:#005D3B" onclick="confirmarAjusteKit(${k.id})">Confirmar</button>
                <button class="btn btn-outline btn-sm" onclick="cancelarAjuste()">Cancelar</button>
            </td>
        </tr>` : '';

        return `<tr>
            <td class="col-codigo" title="${escapeHtml(k.referencia || '')}">${escapeHtml(k.referencia || '—')}</td>
            <td class="col-nome" title="${escapeHtml(k.nome)}${k.descricao ? ' — ' + escapeHtml(k.descricao) : ''}"><strong>${escapeHtml(k.nome)}</strong> ${selo}</td>
            ${comUnidade ? '<td class="col-un">un</td>' : ''}
            <td class="col-num" title="${escapeHtml(k.medida || '')}">${escapeHtml(k.medida || '—')}</td>
            <td class="col-num">${pronto ? 'R$ ' + (k.preco || 0).toFixed(2) : '—'}</td>
            <td class="col-num">${saldo}</td>
            <td class="col-nome" title="${escapeHtml((k.itens || []).map(i => i.nome + ': ' + textoQtdItemKit(i)).join(' · '))}">${composicao}</td>
            <td class="col-acoes">${menuAcoesHtml([
                { icone: '±', rotulo: 'Ajustar estoque', onclick: `mostrarAjusteForm('kit-${k.id}')`, oculto: !(pronto && !temEstoqueInfinito(k)) },
                { icone: '✏️', rotulo: 'Editar kit', onclick: `editarKit(${k.id})`, oculto: pronto || !document.getElementById('kit-ref') },
                { icone: '🗑️', rotulo: 'Excluir kit', onclick: `excluirKit(${k.id})`, perigo: true }
            ])}</td>
        </tr>${linhaAjuste}`;
    }).join('');
}

// --- HISTÓRICO DE MOVIMENTAÇÕES ---
let _histPag = 0;
let _histMovsFiltrados = [];
function renderHistorico() {
    _histPag = 0;
    _aplicarFiltrosHistorico();
}
function _aplicarFiltrosHistorico() {
    const filtroTipo = document.getElementById('hist-filtro-tipo')?.value  || '';
    const filtroItem = (document.getElementById('hist-filtro-item')?.value || '').toLowerCase().trim();
    const filtroDE   = document.getElementById('hist-filtro-de')?.value    || '';
    const filtroAte  = document.getElementById('hist-filtro-ate')?.value   || '';
    let movs = db.movimentos.slice(0, 2000);
    if (filtroTipo) movs = movs.filter(m => m.tipo === filtroTipo);
    if (filtroItem) movs = movs.filter(m => m.item_nome.toLowerCase().includes(filtroItem));
    if (filtroDE)   movs = movs.filter(m => new Date(m.data) >= new Date(filtroDE  + 'T00:00:00'));
    if (filtroAte)  movs = movs.filter(m => new Date(m.data) <= new Date(filtroAte + 'T23:59:59'));
    _histMovsFiltrados = movs;
    _renderHistPage();
}
function _renderHistPage() {
    const tb = document.getElementById('tb-historico');
    if (!tb) return;
    const POR_PAG = 30;
    const movs = _histMovsFiltrados;
    const totalPags = Math.max(1, Math.ceil(movs.length / POR_PAG));
    if (_histPag >= totalPags) _histPag = totalPags - 1;
    if (!movs.length) {
        tb.innerHTML = '<tr><td colspan="5" style="text-align:center;color:#999;padding:24px;">Nenhuma movimentação encontrada.</td></tr>';
        _renderHistPaginacao(0, 0);
        return;
    }
    const COR = { 'Entrada':'mov-entrada','Baixa Pedido':'mov-baixa-pedido','Baixa Manual':'mov-baixa-manual','Ajuste +':'mov-ajuste-pos','Ajuste -':'mov-ajuste-neg' };
    const inicio = _histPag * POR_PAG;
    tb.innerHTML = movs.slice(inicio, inicio + POR_PAG).map(m => {
        const cls = COR[m.tipo] || '';
        const data = new Date(m.data).toLocaleString('pt-BR',{day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit'});
        const tipoLabel = m.tipo === 'Ajuste +' ? 'Ajuste ↑' : m.tipo === 'Ajuste -' ? 'Ajuste ↓' : m.tipo;
        return `<tr>
            <td style="font-size:12px;color:#8F8F8F;white-space:nowrap">${data}</td>
            <td><span class="mov-badge ${cls}">${tipoLabel}</span></td>
            <td>${escapeHtml(m.item_nome)} <span style="font-size:11px;color:#8F8F8F">(${m.item_tipo==='tecido'?'Tecido':'Material'})</span></td>
            <td><strong>${m.quantidade.toFixed(2)}</strong> ${m.unidade}</td>
            <td style="font-size:12px;color:#8F8F8F">${escapeHtml(m.referencia||'—')}</td>
        </tr>`;
    }).join('');
    _renderHistPaginacao(totalPags, movs.length);
}
function _renderHistPaginacao(totalPags, total) {
    const pagEl = document.getElementById('hist-pag');
    if (!pagEl) return;
    pagEl.innerHTML = '';
    if (totalPags <= 1) return;
    const btnPrev = document.createElement('button');
    btnPrev.className = 'btn btn-outline btn-sm'; btnPrev.textContent = '‹ Anterior'; btnPrev.disabled = _histPag === 0;
    btnPrev.onclick = () => { _histPag--; _renderHistPage(); };
    const info = document.createElement('span');
    info.style.cssText = 'font-size:13px;color:#8F8F8F';
    info.textContent = `${_histPag + 1} / ${totalPags} · ${total} registro(s)`;
    const btnNext = document.createElement('button');
    btnNext.className = 'btn btn-outline btn-sm'; btnNext.textContent = 'Próximo ›'; btnNext.disabled = _histPag >= totalPags - 1;
    btnNext.onclick = () => { _histPag++; _renderHistPage(); };
    pagEl.append(btnPrev, info, btnNext);
}
function limparFiltrosHistorico() {
    ['hist-filtro-tipo','hist-filtro-item','hist-filtro-de','hist-filtro-ate'].forEach(id => { const el = document.getElementById(id); if (el) el.value = ''; });
    renderHistorico();
}

function renderEstoqueFuturo() {
    const el = document.getElementById('tab-futuro');
    if (!el) return;
    const statusAtivos = ['Medição','Aguardando Tecido','Na Costura','Pronto p/ Instalação','Aguardando Financeiro'];
    const pedAtivos = db.pedidos.filter(p => statusAtivos.includes(normalizarStatus(p.status)));
    const consumoPorTecido = {};
    const pedComTecido = new Set();   // so os que ainda tem tecido a baixar
    for (const ped of pedAtivos) {
        // Tecido ja baixado do rolo: ja saiu do estoque, nao conta de novo.
        if (ped.baixa_tecido_realizada || ped.baixa_realizada) continue;
        for (const amb of normalizarAmbientes(ped)) {
            for (const t of (amb.tecidos || [])) {
                if (!t.tecidoId || !(t.consumo_linear > 0)) continue;
                const key = String(t.tecidoId);
                if (!consumoPorTecido[key]) consumoPorTecido[key] = { total: 0, pedidoIds: new Set() };
                consumoPorTecido[key].total += t.consumo_linear;
                consumoPorTecido[key].pedidoIds.add(ped.id);
                pedComTecido.add(ped.id);
            }
        }
    }
    const rows = db.catalogo.map(c => {
        const key = String(c.id);
        const info = consumoPorTecido[key];
        if (!info) return null;
        const infinito = temEstoqueInfinito(c);
        const disponivel = estoqueDisponivel(c.id);
        const reservado = Math.round(info.total * 100) / 100;
        const saldo = Math.round((disponivel - reservado) * 100) / 100;
        const saldoCss = saldo < 0 ? 'color:#F43927;font-weight:700' : saldo < 2 ? 'color:#F2C924;font-weight:600' : 'color:#159912';
        return `<tr>
            <td><span style="font-size:11px;color:#8F8F8F;display:block">${escapeHtml(c.referencia||'')}</span>${escapeHtml(c.nome)}</td>
            <td style="text-align:center">${info.pedidoIds.size}</td>
            <td>${reservado.toFixed(2)} m</td>
            <td>${infinito ? '∞' : disponivel.toFixed(2) + ' m'}</td>
            <td style="${infinito ? 'color:#159912' : saldoCss}">${infinito ? 'sem controle' : (saldo >= 0 ? '+' : '') + saldo.toFixed(2) + ' m'}</td>
        </tr>`;
    }).filter(Boolean).join('');
    el.innerHTML = `<div class="card">
        <h3 style="margin-bottom:4px">Consumo Previsto — Pedidos em Produção</h3>
        <p style="font-size:13px;color:#8F8F8F;margin-bottom:16px">${pedComTecido.size} pedido(s) em produção com tecido a baixar. Saldo negativo indica necessidade de reposição.</p>
        <table>
            <thead><tr>
                <th>Tecido</th>
                <th style="text-align:center">Pedidos</th>
                <th>Reservado</th>
                <th>Em Estoque</th>
                <th>Saldo</th>
            </tr></thead>
            <tbody>${rows || '<tr><td colspan="5" style="text-align:center;color:#999;padding:24px">Nenhum tecido consumido pelos pedidos em produção.</td></tr>'}</tbody>
        </table>
    </div>`;
}

// Troca de aba no estoque
function mostrarTabEstoque(tab) {
    if (_curTabEstoque !== tab) { _prevTabEstoque = _curTabEstoque; _curTabEstoque = tab; }
    document.querySelectorAll('.tab-panel').forEach(p => p.classList.remove('active'));
    document.querySelectorAll('.tab-btn').forEach(b => b.classList.remove('active'));
    document.getElementById('tab-' + tab)?.classList.add('active');
    document.querySelector(`.tab-btn[data-tab="${tab}"]`)?.classList.add('active');
    _tabBackBtn('.tab-nav', _prevTabEstoque, () => mostrarTabEstoque(_prevTabEstoque));
    if (tab === 'consulta') renderConsultaEstoque();
    if (tab === 'futuro') renderEstoqueFuturo();
}

// --- FORMULÁRIO DE PEDIDO (MULTI-AMBIENTE + ACESSÓRIOS) ---
let editandoIdPedido = null;
// Agendamento de medicao que originou o pedido novo ("Criar Pedido" na agenda).
let pedidoMedicaoId = null;
let pedidoDraft = { ambientes: [], itens: [] };
let _ambienteCounter = 0;

// Imagens das aberturas: "images/Aberturas/" = desenho tecnico;
// "images/Aberturas/Ambiente/" = cortina instalada no ambiente.
const PASTA_ABERTURAS = 'images/Aberturas/Ambiente/';

// Ao escolher/trocar a abertura, toca uma vez a cortina abrindo (arquivo
// -anim, que so existe na versao Ambiente). Ao abrir o pedido e na OS a
// imagem fica parada. Quem pede menos movimento no sistema ve a estatica.
function urlAberturaAnimada(letra) {
    const semMovimento = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
    if (semMovimento || !PASTA_ABERTURAS.includes('Ambiente')) return `${PASTA_ABERTURAS}Abertura${letra}.svg`;
    // O parametro novo faz o navegador recarregar o SVG, e a animacao recomeca.
    return `${PASTA_ABERTURAS}Abertura${letra}-anim.svg?t=${Date.now()}`;
}

// Desenho da cortina com a abertura e a prega de cada tecido (js/cortina-desenho.js).
// Sem o modulo carregado, cai na imagem fixa da abertura.
function _semMovimento() {
    return !!(window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches);
}

function urlDesenhoCortina(abertura, pregas, animado) {
    if (typeof CortinaDesenho === 'undefined') {
        return animado ? urlAberturaAnimada(abertura || 'A') : `${PASTA_ABERTURAS}Abertura${abertura || 'A'}.svg`;
    }
    return CortinaDesenho.urlSvg({ abertura, pregas, animado: animado && !_semMovimento() });
}

function descricaoDesenhoCortina(abertura, pregas) {
    return typeof CortinaDesenho === 'undefined'
        ? `Abertura ${abertura || 'A'}`
        : CortinaDesenho.descricao({ abertura, pregas });
}

// Pregas do ambiente como estao na tela (um select por tecido), na ordem dos tecidos.
function _pregasNaTela(ambId) {
    const amb = (pedidoDraft.ambientes || []).find(a => a.id == ambId);
    const n = amb ? (amb.tecidos || []).length : 0;
    const pregas = [];
    for (let i = 0; i < n; i++) {
        const v = document.getElementById(`t-prega-${ambId}-${i}`)?.value;
        pregas.push(v || (amb.tecidos[i] && amb.tecidos[i].prega) || '');
    }
    return pregas;
}

// Ao trocar a abertura ou a prega, toca uma vez a cortina abrindo.
function atualizarDesenhoCortina(id) {
    const abertura = document.getElementById(`a-abertura-${id}`)?.value || 'A';
    const pregas = _pregasNaTela(id);
    const desc = descricaoDesenhoCortina(abertura, pregas);
    const img = document.getElementById(`img-abertura-${id}`);
    if (img) { img.src = urlDesenhoCortina(abertura, pregas, true); img.alt = desc; }
    const lbl = document.getElementById(`lbl-abertura-${id}`);
    if (lbl) lbl.textContent = desc;
}

function onAberturaChange(id) {
    atualizarDesenhoCortina(id);
}

function onPregaTecido(ambId, tidx) {
    const fatoresSugeridos = {
        'Americana': '2.5', 'Franzido': '2.5',
        'Wave Botao': '2.0', 'Wave Plus': '2.0',
        'Macho-Femea': '2.0', 'Painel': '1.5'
    };
    const prega = document.getElementById(`t-prega-${ambId}-${tidx}`)?.value;
    const fatorEl = document.getElementById(`t-fator-${ambId}-${tidx}`);
    if (fatorEl && prega) fatorEl.value = fatoresSugeridos[prega] || '2.5';
    atualizarDesenhoCortina(ambId);
}

function renderAmbienteBreakdown(a) {
    if (!a.calculado) return '';
    const tecidos = a.tecidos || [];
    if (!tecidos.length) return '';
    const totalMat = tecidos.reduce((s,t)=>s+(t.total_material||0),0);
    const parts = tecidos.map((t, tidx) => {
        if (!t.tecidoId) return '';
        const disp = estoqueDisponivel(t.tecidoId);
        const stockColor = !tecidoTemEstoqueInfinito(t.tecidoId) && disp < (t.consumo_linear||0) ? '#F43927' : 'var(--primary-text)';
        const temConflito = verificarConflitoDeLote(t.tecidoId, t.consumo_linear||0);
        const alt_bruta = (a.altura||0) + (t.bainha_cm??15)/100 + (t.cabecote_cm??0)/100;
        const titulo = tecidos.length > 1 ? `<div class="breakdown-row" style="font-weight:bold;color:var(--primary);padding-bottom:6px;border-bottom:1px solid #dde">Tecido ${tidx+1}: ${escapeHtml(t.tecidoNome||'')}</div>` : '';
        return `<div class="breakdown-box">
            ${titulo}
            <div class="breakdown-row"><span class="label">Tipo de prega</span><span><strong>${escapeHtml(t.prega||'—')}</strong></span></div>
            <div class="breakdown-row"><span class="label" title="Largura da parede × fator de franzimento">Largura total</span><span><strong>${((a.largura||0)*(t.fator||1)).toFixed(2)}</strong> m</span></div>
            <div class="breakdown-row"><span class="label">Largura do rolo</span><span><strong>${(t.largura_rolo||2.80).toFixed(2)}</strong> m</span></div>
            <div class="breakdown-row"><span class="label">Número de panos</span><span><strong>${t.num_panos}</strong> pano(s)</span></div>
            <div class="breakdown-row"><span class="label" title="Altura da parede + barra + cabeçote">Altura bruta</span><span><strong>${alt_bruta.toFixed(3)}</strong> m</span></div>
            <div class="breakdown-row destaque"><span>Consumo total</span><span><strong>${(t.consumo_linear||0).toFixed(2)}</strong> m lineares</span></div>
            <div class="breakdown-row"><span class="label">Estoque disponível</span><span style="color:${stockColor}"><strong>${disp.toFixed(2)} m</strong></span></div>
            <div class="breakdown-row destaque"><span>Valor do tecido</span><span>R$ <strong>${(t.total_material||0).toFixed(2)}</strong></span></div>
            ${temConflito ? `<div class="alerta-lote-pedido" style="display:flex;margin-top:4px">⚠ <strong style="margin:0 4px">Atenção:</strong> pode exigir múltiplos lotes — risco de variação de tonalidade.</div>` : ''}
        </div>`;
    }).join('');
    const totalRow = tecidos.length > 1 ? `<div class="breakdown-box breakdown-total"><div class="breakdown-row destaque"><span>Total combinado (${tecidos.length} tecidos)</span><span>R$ <strong>${totalMat.toFixed(2)}</strong></span></div></div>` : '';
    return `<div class="breakdown-wrap">${parts}</div>${totalRow}`;
}

function syncAmbientesFromDOM() {
    pedidoDraft.ambientes.forEach(a => {
        const v = id => document.getElementById(id)?.value;
        const amb = v(`a-amb-${a.id}`); if (amb !== undefined) a.amb = amb.trim();
        // A fixação não é lida aqui: só muda pelo onchange (onFixacaoChange),
        // senão um pedido antigo ganharia kit sem ninguém ter escolhido.
        const abertura = v(`a-abertura-${a.id}`); if (abertura) a.abertura = abertura;
        const local = v(`a-local-${a.id}`); if (local) a.local_instalacao = local;
        const larg = parseFloat(v(`a-larg-${a.id}`)); if (!isNaN(larg)) a.largura = larg;
        const alt = parseFloat(v(`a-alt-${a.id}`)); if (!isNaN(alt)) a.altura = alt;
        _lerAcionamentoDOM(a);
        (a.tecidos || []).forEach((t, tidx) => {
            const sel = document.getElementById(`a-tecido-${a.id}-${tidx}`);
            if (sel && sel.value) t.tecidoId = parseInt(sel.value) || null;
            const refEl = document.getElementById(`a-tec-ref-${a.id}-${tidx}`);
            if (refEl) t._ref = refEl.value;
            const prega = v(`t-prega-${a.id}-${tidx}`); if (prega) t.prega = prega;
            const fator = parseFloat(v(`t-fator-${a.id}-${tidx}`)); if (!isNaN(fator)) t.fator = fator;
            const bainha = parseFloat(v(`t-bainha-${a.id}-${tidx}`)); if (!isNaN(bainha)) t.bainha_cm = bainha;
            const cab = parseFloat(v(`t-cabecote-${a.id}-${tidx}`)); if (!isNaN(cab)) t.cabecote_cm = cab;
        });
    });
}

const ABERTURAS_OPTS = [
    {v:'A',l:'Abertura A — Rec. Esq., Cmd. Esq.'},
    {v:'B',l:'Abertura B — Rec. Dir., Cmd. Dir.'},
    {v:'C',l:'Abertura C — Central, Cmd. Esq.'},
    {v:'D',l:'Abertura D — Central, Cmd. Dir.'},
    {v:'E',l:'Abertura E — Rec. Esq., Cmd. Dir.'},
    {v:'F',l:'Abertura F — Rec. Dir., Cmd. Esq.'},
    {v:'G',l:'Abertura G — Centro, Cmd. Esq.'},
    {v:'H',l:'Abertura H — Centro, Cmd. Dir.'}
];
function rotuloAbertura(v) {
    return (ABERTURAS_OPTS.find(o => o.v === v)?.l) || (v ? 'Abertura ' + v : '—');
}

// Acionamento da cortina: 'com' (comando de corda, com a altura do
// comando em m) ou 'sem'. Vazio = nao informado (pedidos antigos).
function textoAcionamento(a) {
    if (a?.acionamento === 'com') return a.altura_acionamento > 0 ? `Com acionamento — altura ${String(a.altura_acionamento).replace('.', ',')} m` : 'Com acionamento';
    if (a?.acionamento === 'sem') return 'Sem acionamento';
    return '—';
}
function onAcionamentoChange(id) {
    const com = document.querySelector(`input[name="a-acion-${id}"]:checked`)?.value === 'com';
    const grupo = document.getElementById(`a-acion-alt-grupo-${id}`);
    if (grupo) grupo.hidden = !com;
}
function _lerAcionamentoDOM(a) {
    const marcado = document.querySelector(`input[name="a-acion-${a.id}"]:checked`);
    if (!marcado) return;
    a.acionamento = marcado.value;
    if (a.acionamento === 'com') {
        const alt = parseFloat(document.getElementById(`a-acion-alt-${a.id}`)?.value);
        a.altura_acionamento = alt > 0 ? alt : null;
    } else a.altura_acionamento = null;
}

function renderAmbientes() {
    const container = document.getElementById('ambientes-container');
    if (!container) return;
    const FATORES = ['1.0','1.5','2.0','2.5','2.7', '3.0','3.5','4.0'];
    const PREGA_OPTS = [
        {v:'Americana',l:'Prega Americana'},
        {v:'Wave Botao',l:'Wave Botão'},
        {v:'Wave Plus',l:'Wave Plus/Flex'},
        {v:'Franzido',l:'Franzido'},
        {v:'Macho-Femea',l:'Prega Macho-Fêmea'},
        {v:'Painel',l:'Painel / Sem Prega'}
    ];
    container.innerHTML = pedidoDraft.ambientes.map((a, idx) => {
        const n = idx + 1;
        const fixacaoOpts = opcoesFixacaoAmbiente(a);
        const localOpts = ['Parede','Teto'].map(o=>`<option value="${o}"${(a.local_instalacao||'Parede')===o?' selected':''}>${o}</option>`).join('');
        const aberturaOpts = ABERTURAS_OPTS.map(o=>`<option value="${o.v}"${(a.abertura||'A')===o.v?' selected':''}>${o.l}</option>`).join('');
        const tecidos = a.tecidos || [];
        const buildTecOpts = (selId) => '<option value="">— Selecione o Tecido —</option>' + db.catalogo.map(c => {
            const disp = estoqueDisponivel(c.id);
            const stockInfo = temEstoqueInfinito(c) ? ' · est: ∞' : (db.estoque.some(r=>r.tecido_id==c.id) ? ` · est: ${disp.toFixed(1)} m` : '');
            return `<option value="${c.id}"${selId==c.id?' selected':''}>${c.referencia?c.referencia+' · ':''}${c.nome} — R$ ${c.preco.toFixed(2)}/m${stockInfo}</option>`;
        }).join('');
        const tecidosHTML = tecidos.map((t, tidx) => {
            const pregaOpts = PREGA_OPTS.map(o=>`<option value="${o.v}"${(t.prega||'Americana')===o.v?' selected':''}>${o.l}</option>`).join('');
            const fatorOpts = FATORES.map(f=>`<option value="${f}"${parseFloat(f)===(t.fator??2.5)?' selected':''}>${f}x</option>`).join('');
            const removeBtn = tecidos.length > 1
                ? `<button class="btn btn-outline btn-sm btn-danger" onclick="removerTecidoDoAmbiente(${a.id},${tidx})" title="Remover este tecido" style="flex-shrink:0">×</button>`
                : '';
            return `<div class="tecido-row-compact">
                <div class="form-group" style="width:118px;flex-shrink:0">
                    <label>Tipo de Prega${typeof abrirGaleriaPedido === 'function' ? ` <button type="button" class="link-galeria" onclick="abrirGaleriaPedido(${a.id},${tidx})" title="Escolher a prega na Galeria, com o cliente">🖼️</button>` : ''}</label>
                    <select id="t-prega-${a.id}-${tidx}" onchange="onPregaTecido(${a.id},${tidx})">${pregaOpts}</select>
                </div>
                <div class="form-group" style="width:64px;flex-shrink:0">
                    <label>Fator <span class="info-tag" style="margin-left:0;font-size:9px">auto</span></label>
                    <select id="t-fator-${a.id}-${tidx}">${fatorOpts}</select>
                </div>
                <div class="form-group" style="width:56px;flex-shrink:0">
                    <label>Barra (cm)</label>
                    <input type="number" id="t-bainha-${a.id}-${tidx}" value="${t.bainha_cm??15}" step="1">
                </div>
                <div class="form-group" style="width:56px;flex-shrink:0">
                    <label>Cabeç. (cm)</label>
                    <input type="number" id="t-cabecote-${a.id}-${tidx}" value="${t.cabecote_cm??0}" step="1">
                </div>
                <div class="form-group" style="width:110px;flex-shrink:0">
                    <label>Ref. Tecido</label>
                    <input type="text" id="a-tec-ref-${a.id}-${tidx}" value="${escapeHtml(t._ref||'')}" placeholder="Código" oninput="autoFillTecidoNoAmbiente(${a.id},${tidx})">
                </div>
                <div class="form-group" style="flex:1;min-width:170px">
                    <label>${tecidos.length > 1 ? 'Tecido '+(tidx+1) : 'Tecido'}</label>
                    <select id="a-tecido-${a.id}-${tidx}" onchange="autoFillRefFromTecido(${a.id},${tidx})">${buildTecOpts(t.tecidoId)}</select>
                </div>
                ${removeBtn}
            </div>`;
        }).join('');
        const addTecBtn = tecidos.length < 3
            ? `<button class="btn btn-outline btn-sm" onclick="adicionarTecidoAoAmbiente(${a.id})" style="margin-bottom:10px;font-size:12px">+ Adicionar Tecido</button>`
            : '';
        const removeAmb = pedidoDraft.ambientes.length > 1
            ? `<button class="btn btn-outline btn-sm btn-danger" onclick="removerAmbiente(${a.id})" title="Remover ambiente">Remover</button>` : '';
        return `
<div class="card ambiente-card" id="amb-card-${a.id}">
    <div class="ambiente-card-header">
        <h4 style="margin:0;color:var(--primary)">Ambiente ${n}</h4>${removeAmb}
    </div>
    <div style="display:flex;gap:20px;align-items:flex-start;margin-top:15px;flex-wrap:wrap">
        <div style="flex:1;min-width:280px">
            <div class="grid" style="margin-bottom:0">
                <div class="form-group" style="max-width:280px"><label>Nome do Ambiente</label>
                    <input type="text" id="a-amb-${a.id}" value="${escapeHtml(a.amb||'')}" placeholder="Ex: Quarto Casal"></div>
            </div>
            <div class="grid">
                <div class="form-group"><label>Material de Instalação</label><select id="a-fixacao-${a.id}" onchange="onFixacaoChange(${a.id})">${fixacaoOpts}</select></div>
                <div class="form-group"><label>Tipo de Abertura</label><select id="a-abertura-${a.id}" onchange="onAberturaChange(${a.id})">${aberturaOpts}</select></div>
                <div class="form-group"><label>Local de Instalação</label><select id="a-local-${a.id}">${localOpts}</select></div>
                <div class="form-group"><label>Largura da Parede (m)</label><input type="number" id="a-larg-${a.id}" value="${a.largura||''}" placeholder="Ex: 2.40" step="0.01" onchange="onLarguraAmbienteChange(${a.id})"></div>
                <div class="form-group"><label>Altura da Parede (m)</label><input type="number" id="a-alt-${a.id}" value="${a.altura||''}" placeholder="Ex: 2.60" step="0.01"></div>
                <div class="form-group amb-acion" id="a-acion-grupo-${a.id}">
                    <label>Acionamento</label>
                    <div class="amb-acion-opcoes" role="radiogroup" aria-label="Acionamento do ambiente ${n}">
                        <label class="amb-acion-op"><input type="radio" name="a-acion-${a.id}" value="com"${a.acionamento==='com'?' checked':''} onchange="onAcionamentoChange(${a.id})"> Com acionamento</label>
                        <label class="amb-acion-op"><input type="radio" name="a-acion-${a.id}" value="sem"${a.acionamento==='sem'?' checked':''} onchange="onAcionamentoChange(${a.id})"> Sem acionamento</label>
                    </div>
                </div>
                <div class="form-group" id="a-acion-alt-grupo-${a.id}"${a.acionamento==='com'?'':' hidden'}><label>Altura do Acionamento (m)</label><input type="number" id="a-acion-alt-${a.id}" value="${a.altura_acionamento||''}" placeholder="Ex: 1.20" step="0.01" min="0"></div>
            </div>
            <div style="max-width:none">${tecidosHTML}${addTecBtn}</div>
            <div style="text-align:right;margin-top:5px">
                <button class="btn" onclick="calcularAmbiente(${a.id})">Calcular Consumo &rarr;</button>
            </div>
        </div>
        <div style="flex:0 1 560px;min-width:220px;max-width:560px;margin:0 auto;text-align:center">
            <img id="img-abertura-${a.id}" src="${urlDesenhoCortina(a.abertura||'A', tecidos.map(t => t.prega), false)}" alt="${escapeHtml(descricaoDesenhoCortina(a.abertura||'A', tecidos.map(t => t.prega)))}" style="width:100%;height:auto;border:1px solid var(--border);border-radius:6px;display:block">
            <div id="lbl-abertura-${a.id}" style="font-size:11px;color:var(--text-soft);margin-top:4px;font-weight:600">${escapeHtml(descricaoDesenhoCortina(a.abertura||'A', tecidos.map(t => t.prega)))}</div>
        </div>
    </div>
    ${a.calculado ? renderAmbienteBreakdown(a) : ''}
</div>`;
    }).join('');
}

function adicionarAmbiente() {
    syncAmbientesFromDOM();
    _ambienteCounter++;
    pedidoDraft.ambientes.push({
        id: _ambienteCounter, calculado: false, amb: '', fixacao: '', fixacao_kit_id: null, abertura: 'A', local_instalacao: 'Parede',
        largura: null, altura: null,
        tecidos: [{ tecidoId: null, tecidoNome: '', largura_rolo: 2.80, prega: 'Americana', fator: 2.5, bainha_cm: 15, cabecote_cm: 0, num_panos: 0, alt_corte: 0, consumo_linear: 0, total_material: 0 }],
        total_material: 0
    });
    renderAmbientes();
}

function adicionarTecidoAoAmbiente(ambId) {
    syncAmbientesFromDOM();
    const a = pedidoDraft.ambientes.find(x => x.id === ambId);
    if (!a || (a.tecidos || []).length >= 3) return;
    if (!a.tecidos) a.tecidos = [];
    a.tecidos.push({ tecidoId: null, tecidoNome: '', largura_rolo: 2.80, prega: 'Americana', fator: 2.5, bainha_cm: 15, cabecote_cm: 0, num_panos: 0, alt_corte: 0, consumo_linear: 0, total_material: 0 });
    a.calculado = false;
    renderAmbientes();
}

function removerTecidoDoAmbiente(ambId, tidx) {
    syncAmbientesFromDOM();
    const a = pedidoDraft.ambientes.find(x => x.id === ambId);
    if (!a || !a.tecidos || a.tecidos.length <= 1) return;
    a.tecidos.splice(tidx, 1);
    a.calculado = false;
    renderAmbientes(); atualizarTotalPedido();
}

function removerAmbiente(id) {
    syncAmbientesFromDOM();
    const removido = pedidoDraft.ambientes.find(a => a.id === id);
    pedidoDraft.ambientes = pedidoDraft.ambientes.filter(a => a.id !== id);
    if (removido?.fixacao_kit_id) { recalcularItensFixacao(); renderItensPedido(); }
    renderAmbientes(); atualizarTotalPedido();
}

// ─── Material de Instalação = kit de fixação ────────────────────────────
// O ambiente guarda o nome (o que a OS e a proposta mostram) e o id do kit.
// Pedido antigo só tem o nome: se ele bate com um kit, o kit aparece marcado;
// senão o nome aparece como opção própria, sem kit.
function _kitFixacaoDoAmbiente(a) {
    const kits = db.kits.filter(ehKitFixacao);
    if (a.fixacao_kit_id != null) {
        const k = kits.find(x => x.id == a.fixacao_kit_id);
        if (k) return k;
    }
    if (!a.fixacao) return null;
    const alvo = _normNomeKit(a.fixacao);
    return kits.find(x => _normNomeKit(x.nome) === alvo) || null;
}

function opcoesFixacaoAmbiente(a) {
    const kits = db.kits.filter(ehKitFixacao)
        .slice().sort((x, y) => String(x.nome).localeCompare(String(y.nome), 'pt-BR'));
    const atual = _kitFixacaoDoAmbiente(a);
    let html = `<option value=""${!atual && !a.fixacao ? ' selected' : ''}>— Selecione —</option>`;
    if (!atual && a.fixacao) {
        html += `<option value="__legado" selected>${escapeHtml(a.fixacao)}</option>`;
    }
    html += kits.map(k => `<option value="${k.id}"${atual && atual.id === k.id ? ' selected' : ''}>${escapeHtml(k.nome)}</option>`).join('');
    return html;
}

function onFixacaoChange(ambId) {
    syncAmbientesFromDOM();
    const a = pedidoDraft.ambientes.find(x => x.id === ambId);
    if (!a) return;
    const valor = document.getElementById(`a-fixacao-${ambId}`)?.value || '';
    if (valor === '__legado') return;   // voltou para o texto antigo: nada muda
    const kit = valor ? db.kits.find(k => k.id == valor) : null;
    a.fixacao_kit_id = kit ? kit.id : null;
    a.fixacao = kit ? kit.nome : '';
    recalcularItensFixacao();
    renderAmbientes(); renderItensPedido(); atualizarTotalPedido();
}

function onLarguraAmbienteChange(ambId) {
    const a = pedidoDraft.ambientes.find(x => x.id === ambId);
    if (!a) return;
    const larg = parseFloat(document.getElementById(`a-larg-${ambId}`)?.value);
    a.largura = larg > 0 ? larg : null;
    if (!a.fixacao_kit_id) return;
    recalcularItensFixacao();
    renderItensPedido(); atualizarTotalPedido();
}

// Quantidade de um item do kit para uma parede. "Por metro" multiplica pela
// largura e arredonda para cima; o epsilon evita 1.1 × 10 = 11.000000000000002 → 12.
function qtdItemFixacao(item, largura) {
    const q = +item.quantidade || 0;
    if (!item.por_metro) return q;
    if (!(largura > 0)) return 0;
    return Math.ceil(q * largura - 1e-9);
}

// Refaz as linhas de fixação do pedido a partir dos ambientes. Linhas lançadas
// à mão (sem origem) não são tocadas; as de fixação são trocadas por inteiro.
function recalcularItensFixacao() {
    const somas = new Map();
    pedidoDraft.ambientes.forEach(a => {
        if (a.fixacao_kit_id == null) return;
        const kit = db.kits.find(k => k.id == a.fixacao_kit_id);
        if (!ehKitFixacao(kit)) return;
        (kit.itens || []).forEach(it => {
            const qtd = qtdItemFixacao(it, a.largura);
            if (qtd <= 0) return;
            somas.set(it.materialId, (somas.get(it.materialId) || 0) + qtd);
        });
    });
    const manuais = pedidoDraft.itens.filter(i => i.origem !== 'fixacao');
    const fixacao = [];
    somas.forEach((qtd, materialId) => {
        const mat = db.materiais.find(m => m.id == materialId);
        if (!mat) return;
        const preco = mat.preco || 0;
        fixacao.push({ materialId: mat.id, nome: mat.nome, unidade: mat.unidade, quantidade: qtd,
            preco_unit: preco, subtotal: qtd * preco, origem: 'fixacao' });
    });
    pedidoDraft.itens = [...manuais, ...fixacao];
}

async function calcularAmbiente(id) {
    // Guarda o que foi digitado nos OUTROS ambientes antes do re-render,
    // senao tecidos escolhidos e ainda nao calculados somem da tela.
    syncAmbientesFromDOM();
    const a = pedidoDraft.ambientes.find(x => x.id === id);
    if (!a) return;
    const larg = parseFloat(document.getElementById(`a-larg-${id}`)?.value);
    const alt  = parseFloat(document.getElementById(`a-alt-${id}`)?.value);
    if (!larg || larg <= 0) { await showAlert('Informe a largura da parede.', '⚠️'); return; }
    if (!alt  || alt  <= 0) { await showAlert('Informe a altura da parede.', '⚠️'); return; }
    a.amb = document.getElementById(`a-amb-${id}`)?.value.trim() || '';
    a.abertura = document.getElementById(`a-abertura-${id}`)?.value || 'A';
    a.local_instalacao = document.getElementById(`a-local-${id}`)?.value || 'Parede';
    a.largura = larg; a.altura = alt;
    _lerAcionamentoDOM(a);
    const tecidos = a.tecidos || [];
    if (!tecidos.length) { await showAlert('Adicione pelo menos um tecido ao ambiente.', '⚠️'); return; }
    let totalMat = 0;
    for (let tidx = 0; tidx < tecidos.length; tidx++) {
        const tecidoId = document.getElementById(`a-tecido-${id}-${tidx}`)?.value;
        if (!tecidoId) { await showAlert(`Selecione o tecido${tecidos.length > 1 ? ' '+(tidx+1) : ''} do ambiente.`, '⚠️'); return; }
        const tecido = db.catalogo.find(t => t.id == tecidoId);
        if (!tecido) return;
        const t = tecidos[tidx];
        const fator       = parseFloat(document.getElementById(`t-fator-${id}-${tidx}`)?.value);
        const bainha_cm   = parseFloat(document.getElementById(`t-bainha-${id}-${tidx}`)?.value) || 15;
        const cabecote_cm = parseFloat(document.getElementById(`t-cabecote-${id}-${tidx}`)?.value) || 0;
        if (!fator || fator <= 0) { await showAlert(`Informe um fator de franzimento válido para o tecido${tecidos.length > 1 ? ' '+(tidx+1) : ''} (ex: 2.0).`, '⚠️'); return; }
        t.tecidoId = tecido.id; t.tecidoNome = tecido.nome;
        t._ref = document.getElementById(`a-tec-ref-${id}-${tidx}`)?.value || t._ref || '';
        t.prega = document.getElementById(`t-prega-${id}-${tidx}`)?.value || 'Americana';
        t.fator = fator; t.bainha_cm = bainha_cm; t.cabecote_cm = cabecote_cm;
        t.largura_rolo = tecido.largura_rolo || 2.80;
        const alt_bruta = alt + bainha_cm / 100 + cabecote_cm / 100;
        const num_panos = Math.ceil((larg * fator) / t.largura_rolo);
        const consumo_linear = num_panos * alt_bruta;
        t.alt_corte = alt_bruta;
        t.num_panos = num_panos; t.consumo_linear = consumo_linear;
        t.total_material = consumo_linear * tecido.preco;
        totalMat += t.total_material;
    }
    a.total_material = totalMat;
    a.calculado = true;
    renderAmbientes(); atualizarTotalPedido();
}

// --- PEDIDO: acessórios/itens ---
function renderItensPedido() {
    const tb = document.getElementById('tb-itens-pedido');
    if (!tb) return;
    if (!pedidoDraft.itens.length) {
        tb.innerHTML = '<tr><td colspan="6" style="text-align:center;color:#999;padding:12px;font-size:13px">Nenhum item adicionado. Use um kit ou adicione itens avulsos.</td></tr>';
        return;
    }
    tb.innerHTML = pedidoDraft.itens.map((item, idx) => `<tr${item.origem === 'fixacao' ? ' class="ped-item-fixacao"' : ''}>
        <td>${escapeHtml(item.nome)}${item.origem === 'fixacao' ? ' <span class="kit-selo kit-selo-fixacao" title="Vem do Material de Instalação dos ambientes; é refeito ao trocar o kit ou a largura">fixação</span>' : ''}</td>
        <td><input type="number" value="${item.quantidade}" step="0.01" min="0.01" style="width:72px;padding:4px 6px;border:1px solid var(--border-strong);border-radius:4px;font-size:13px" onchange="atualizarQuantidadeItem(${idx},this.value)"></td>
        <td>${item.unidade}</td>
        <td>R$ ${item.preco_unit.toFixed(2)}</td>
        <td>R$ ${item.subtotal.toFixed(2)}</td>
        <td><button class="btn btn-outline btn-sm btn-danger" onclick="removerItemPedido(${idx})">✕</button></td>
    </tr>`).join('');
}

async function adicionarItemPedido() {
    const matId = parseInt(document.getElementById('ped-item-mat')?.value);
    const qtd   = parseFloat(document.getElementById('ped-item-qtd')?.value) || 1;
    if (!matId) { await showAlert('Selecione um material.', '⚠️'); return; }
    const mat = db.materiais.find(m => m.id == matId);
    if (!mat) return;
    const existing = pedidoDraft.itens.find(i => i.materialId === matId && i.origem !== 'fixacao');
    if (existing) { existing.quantidade += qtd; existing.subtotal = existing.quantidade * existing.preco_unit; }
    else { pedidoDraft.itens.push({ materialId: mat.id, nome: mat.nome, unidade: mat.unidade, quantidade: qtd, preco_unit: mat.preco || 0, subtotal: qtd * (mat.preco || 0) }); }
    renderItensPedido(); atualizarTotalPedido();
}

function removerItemPedido(idx) {
    pedidoDraft.itens.splice(idx, 1);
    renderItensPedido(); atualizarTotalPedido();
}

function atualizarQuantidadeItem(idx, valor) {
    const qtd = parseFloat(valor) || 0;
    if (qtd <= 0) return;
    pedidoDraft.itens[idx].quantidade = qtd;
    pedidoDraft.itens[idx].subtotal   = qtd * pedidoDraft.itens[idx].preco_unit;
    renderItensPedido(); atualizarTotalPedido();
}

// Kit pronto: produto em si, com código e preço próprios e sem componentes.
// Kit de montagem (o de sempre) não tem a marca e é explodido em materiais.
function ehKitPronto(kit) {
    return !!(kit && kit.tipo === 'pronto');
}

async function aplicarKit() {
    const kitId = parseInt(document.getElementById('ped-kit')?.value);
    if (!kitId) { await showAlert('Selecione um kit para aplicar.', '⚠️'); return; }
    const kit = db.kits.find(k => k.id == kitId);
    if (!kit) return;

    // Kit pronto entra como UMA linha, com o preço dele. Não há o que explodir.
    if (ehKitPronto(kit)) {
        const existente = pedidoDraft.itens.find(i => i.kitId === kit.id);
        if (existente) {
            existente.quantidade += 1;
            existente.subtotal = existente.quantidade * existente.preco_unit;
        } else {
            const preco = kit.preco || 0;
            pedidoDraft.itens.push({
                kitId: kit.id,
                nome: kit.nome + (kit.medida ? ' (' + kit.medida + ')' : ''),
                unidade: 'un', quantidade: 1, preco_unit: preco, subtotal: preco
            });
        }
        renderItensPedido(); atualizarTotalPedido();
        document.getElementById('ped-kit').value = '';
        return;
    }

    for (const item of kit.itens) {
        const mat = db.materiais.find(m => m.id == item.materialId);
        if (!mat) continue;
        const existing = pedidoDraft.itens.find(i => i.materialId === item.materialId && i.origem !== 'fixacao');
        if (existing) { existing.quantidade += item.quantidade; existing.subtotal = existing.quantidade * existing.preco_unit; }
        else { pedidoDraft.itens.push({ materialId: mat.id, nome: mat.nome, unidade: mat.unidade, quantidade: item.quantidade, preco_unit: mat.preco || 0, subtotal: item.quantidade * (mat.preco || 0) }); }
    }
    renderItensPedido(); atualizarTotalPedido();
    document.getElementById('ped-kit').value = '';
}

// ── Busca rapida de kit / material no pedido ────────────────────────────────
// Dois campos: "Buscar Kit" (#ped-kit-busca) so procura kits, "Buscar
// Material" (#ped-mat-busca) so materiais, pela referencia ou pelo nome.
// Escolher um resultado adiciona o item ao pedido na hora: material com a
// quantidade do campo "Quantidade", kit como em "Aplicar Kit".

let _pedBuscaAtiva = -1;

function _pedBuscaAchados(tipo) {
    const termo = _buscaNormaliza(document.getElementById(`ped-${tipo}-busca`)?.value);
    if (!termo) return [];
    const casa = i => _buscaNormaliza(i.nome).includes(termo) || _buscaNormaliza(i.referencia).includes(termo);
    const lista = tipo === 'kit' ? (db.kits || []) : (db.materiais || []);
    // Quem bate a referencia exata vem primeiro: quem digita o codigo sabe o que quer.
    const exato = a => _buscaNormaliza(a.item.referencia) === termo ? 0 : 1;
    return lista.filter(casa).map(item => ({ tipo, item }))
        .sort((a, b) => exato(a) - exato(b)).slice(0, 12);
}

function _pedBuscaDetalhe(a) {
    const i = a.item;
    if (a.tipo === 'kit') {
        return ehKitPronto(i)
            ? `${i.medida ? i.medida + ' · ' : ''}R$ ${(i.preco || 0).toFixed(2)}`
            : 'kit de montagem';
    }
    const est = temEstoqueInfinito(i) ? '∞' : (i.estoque_atual || 0).toFixed(1);
    return `${i.unidade || 'un'} · R$ ${(i.preco || 0).toFixed(2)} · estoque: ${est}`;
}

function pedBuscaRender(tipo) {
    const caixa = document.getElementById(`ped-${tipo}-busca-sug`);
    if (!caixa) return;
    if (!document.getElementById(`ped-${tipo}-busca`)?.value.trim()) { pedBuscaFechar(tipo); return; }
    const achados = _pedBuscaAchados(tipo);
    if (!achados.length) {
        caixa.innerHTML = `<div class="consulta-sug-item" style="cursor:default;color:var(--muted)">Nenhum ${tipo === 'kit' ? 'kit' : 'material'} com essa referência ou nome</div>`;
        caixa.classList.add('aberta');
        return;
    }
    caixa.innerHTML = achados.map((a, n) => `
        <div class="consulta-sug-item ped-sug-item${n === _pedBuscaAtiva ? ' ativa' : ''}" onmousedown="event.preventDefault()" onclick="pedBuscaEscolher('${a.tipo}', ${a.item.id})">
            <span class="consulta-tag ${a.tipo}">${a.tipo === 'kit' ? 'KIT' : 'MAT'}</span>
            <span class="consulta-sug-cod">${escapeHtml(a.item.referencia || '—')}</span>
            <span class="consulta-sug-nome" style="color:var(--dark)">${escapeHtml(a.item.nome)}</span>
            <span class="ped-sug-det">${escapeHtml(_pedBuscaDetalhe(a))}</span>
        </div>`).join('');
    caixa.classList.add('aberta');
    caixa.querySelector('.consulta-sug-item.ativa')?.scrollIntoView({ block: 'nearest' });
}

function pedBuscaDigitou(tipo) {
    _pedBuscaAtiva = -1;
    pedBuscaRender(tipo);
}

// Sem tipo, fecha as duas listas.
function pedBuscaFechar(tipo) {
    _pedBuscaAtiva = -1;
    for (const t of tipo ? [tipo] : ['kit', 'mat']) {
        const caixa = document.getElementById(`ped-${t}-busca-sug`);
        if (caixa) { caixa.classList.remove('aberta'); caixa.innerHTML = ''; }
    }
}

async function pedBuscaEscolher(tipo, id) {
    const sel = document.getElementById(tipo === 'kit' ? 'ped-kit' : 'ped-item-mat');
    if (!sel) return;
    sel.value = String(id);
    pedBuscaFechar();
    if (tipo === 'kit') await aplicarKit();
    else {
        await adicionarItemPedido();
        sel.value = '';
    }
    const campo = document.getElementById(`ped-${tipo}-busca`);
    if (campo) { campo.value = ''; campo.focus(); }
}

function pedBuscaTecla(e, tipo) {
    if (e.key === 'Escape') { pedBuscaFechar(tipo); return; }
    const achados = _pedBuscaAchados(tipo);
    if (!achados.length) return;
    if (e.key === 'ArrowDown' || e.key === 'ArrowUp') {
        e.preventDefault();
        const total = achados.length;
        _pedBuscaAtiva = e.key === 'ArrowDown'
            ? (_pedBuscaAtiva + 1) % total
            : (_pedBuscaAtiva <= 0 ? total - 1 : _pedBuscaAtiva - 1);
        pedBuscaRender(tipo);
        return;
    }
    if (e.key === 'Enter') {
        // Sem nada percorrido, um unico achado e' escolha obvia; varios, nao.
        const alvo = _pedBuscaAtiva >= 0 ? achados[_pedBuscaAtiva]
            : (achados.length === 1 ? achados[0] : null);
        if (alvo) { e.preventDefault(); pedBuscaEscolher(alvo.tipo, alvo.item.id); }
    }
}

document.addEventListener('click', e => {
    if (e.target.closest && e.target.closest('.ped-busca')) return;
    pedBuscaFechar();
});

// O valor do pedido e' a soma dos seus itens. O modo "por pedido" (margem
// global sobre o custo) saiu da tela: os itens ja carregam a margem deles.
// Pedidos antigos fechados naquele modo guardam os proprios valores e nao sao
// recalculados — ver o DRE, que ainda le tipo_precificacao.
function atualizarTotalPedido() {
    const mao     = parseFloat(document.getElementById('ped-mao')?.value) || 0;
    const descPct = parseFloat(document.getElementById('ped-desconto')?.value) || 0;

    const totalMat   = pedidoDraft.ambientes.filter(a => a.calculado).reduce((s, a) => s + (a.tecidos || []).reduce((ts, t) => ts + (t.total_material || 0), 0), 0);
    const totalItens = pedidoDraft.itens.reduce((s, i) => s + (i.subtotal || 0), 0);
    const bruto      = totalMat + totalItens + mao;

    const descVal  = Math.round(bruto * descPct / 100 * 100) / 100;
    const total    = bruto - descVal;
    const recEl    = document.getElementById('ped-valor-recebido');
    const recebido = parseFloat(document.getElementById('ped-valor-recebido')?.value) || 0;
    const saldo    = Math.max(0, total - recebido);
    const el = id => document.getElementById(id);
    if (el('ped-total-mat'))    el('ped-total-mat').textContent    = totalMat.toFixed(2);
    if (el('ped-total-itens'))  el('ped-total-itens').textContent  = totalItens.toFixed(2);
    if (el('ped-desconto-val')) el('ped-desconto-val').textContent = descVal.toFixed(2);
    if (el('ped-total-final'))  el('ped-total-final').textContent  = total.toFixed(2);
    if (el('ped-saldo'))        el('ped-saldo').textContent        = saldo.toFixed(2);

    [['ped-vendedor', 'ped-comissao'], ['ped-arquiteto', 'ped-comissao-arq']].forEach(([sel, pre]) => {
        const { pct, valor } = comissaoDoCadastro(document.getElementById(sel)?.value, total);
        const rowEl = el(pre + '-row');
        if (rowEl) rowEl.style.display = pct > 0 ? '' : 'none';
        if (el(pre + '-pct')) el(pre + '-pct').textContent = pct;
        if (el(pre + '-val')) el(pre + '-val').textContent = valor.toFixed(2);
    });
}

function filtrarClientes() {
    const busca = (document.getElementById('ped-cliente-busca')?.value || '').toLowerCase().trim();
    const sel   = document.getElementById('ped-cliente');
    if (!sel) return;
    const filtrados = busca
        ? db.clientes.filter(c =>
            c.nome.toLowerCase().includes(busca) ||
            (c.cpf || '').replace(/\D/g, '').includes(busca.replace(/\D/g, ''))
          )
        : db.clientes;
    sel.innerHTML = '<option value="">— Selecione o Cliente —</option>' +
        filtrados.map(c => `<option value="${c.id}">${c.nome}${c.cpf ? ' · ' + c.cpf : ''}</option>`).join('');
    if (filtrados.length === 1) sel.value = String(filtrados[0].id);
}

async function salvarPedido() {
    if (!await exigirPermissao('pedidos', 'completo')) return;
    const statusAnterior = editandoIdPedido
        ? normalizarStatus(db.pedidos.find(p => p.id == editandoIdPedido)?.status || 'Orçamento')
        : 'Orçamento';
    if (statusAnterior !== 'Orçamento') {
        await showAlert(`O pedido #${formatPedidoId(editandoIdPedido)} já foi aprovado (${statusAnterior}) e está bloqueado para edição.
Volte o pedido para Orçamento para editar.`, '🔒');
        return;
    }
    const clienteId = document.getElementById('ped-cliente')?.value;
    if (!clienteId) { await showAlert('Selecione o cliente.', '⚠️'); return; }
    if (!pedidoDraft.ambientes.length) { await showAlert('Adicione pelo menos um ambiente.', '⚠️'); return; }
    const naoCalculados = pedidoDraft.ambientes.filter(a => !a.calculado);
    if (naoCalculados.length) { await showAlert(`${naoCalculados.length} ambiente(s) ainda não calculado(s). Clique em "Calcular Consumo" em cada ambiente.`, '⚠️'); return; }
    pedidoDraft.ambientes.forEach(a => {
        const el = document.getElementById(`a-amb-${a.id}`);
        if (el) a.amb = el.value.trim() || a.amb;
    });
    const cliente          = db.clientes.find(c => c.id == clienteId);
    const maoObra          = parseFloat(document.getElementById('ped-mao')?.value) || 0;
    const desconto_pct     = parseFloat(document.getElementById('ped-desconto')?.value) || 0;
    const total_material   = pedidoDraft.ambientes.reduce((s,a)=>s+(a.tecidos||[]).reduce((ts,t)=>ts+(t.total_material||0),0),0);
    const total_acessorios = pedidoDraft.itens.reduce((s,i)=>s+(i.subtotal||0),0);
    const bruto            = total_material + total_acessorios + maoObra;
    const desconto_valor   = Math.round(bruto * desconto_pct / 100 * 100) / 100;
    const valor            = bruto - desconto_valor;
    const ambNomes         = pedidoDraft.ambientes.map(a=>a.amb).filter(Boolean).join(', ') || 'Sem nome';
    const vendedor_id_sel  = parseInt(document.getElementById('ped-vendedor')?.value) || null;
    const arq_id_sel       = parseInt(document.getElementById('ped-arquiteto')?.value) || null;
    if (!vendedor_id_sel && !arq_id_sel) { await showAlert('Informe pelo menos um vendedor ou um arquiteto.', '⚠️'); return; }
    const vendedor_obj     = vendedor_id_sel ? db.vendedores.find(v => v.id === vendedor_id_sel) : null;
    const arq_obj          = arq_id_sel ? db.vendedores.find(v => v.id === arq_id_sel) : null;
    const { pct: comissao_pct, valor: comissao_valor }         = comissaoDoCadastro(vendedor_id_sel, valor);
    const { pct: arq_comissao_pct, valor: arq_comissao_valor } = comissaoDoCadastro(arq_id_sel, valor);
    const dadosPedido = {
        clienteId, clienteNome: cliente ? cliente.nome : 'Cliente Não Vinculado',
        amb: ambNomes, ambientes: pedidoDraft.ambientes.map(a=>({...a})),
        itens: pedidoDraft.itens.map(i=>({...i})),
        maoObra, total_material, total_acessorios, desconto_pct, desconto_valor, valor,
        // Fica gravado para o DRE distinguir destes os pedidos antigos, que
        // foram fechados com margem global e guardam o proprio custo.
        tipo_precificacao: 'item', custo_mat: null, custo_acess: null,
        status:         document.getElementById('ped-status')?.value || 'Orçamento',
        data_entrega:   document.getElementById('ped-entrega')?.value || null,
        observacoes:    document.getElementById('ped-obs')?.value.trim() || '',
        valor_recebido: 0,   // fonte unica: soma das parcelas pagas (sincronizarRecebidoPedido)
        vendedor_id:    vendedor_id_sel,
        vendedor_nome:  vendedor_obj ? vendedor_obj.nome : '',
        comissao_pct,
        comissao_valor,
        arq_id:         arq_id_sel,
        arq_nome:       arq_obj ? arq_obj.nome : '',
        arq_comissao_pct,
        arq_comissao_valor,
        arquiteto_nome: '',
        rt_pct: 0,
        forma_pagamento: document.getElementById('ped-forma-pagamento')?.value || getFormasPagamento()[0]
    };
    dadosPedido.entrada_pct = _entradaValida(document.getElementById('ped-entrada-pct')?.value, entradaDaFormaPagamento(dadosPedido.forma_pagamento));
    dadosPedido.meio_entrada = dadosPedido.entrada_pct <= 0 ? null : _lerMeioPedido('entrada');
    dadosPedido.meio_saldo = dadosPedido.entrada_pct >= 100 ? null : _lerMeioPedido('saldo');
    if (editandoIdPedido && !await confirmarValorContraNotas(editandoIdPedido, valor)) return;
    const avisosComissaoPaga = [];
    if (editandoIdPedido) {
        const index = db.pedidos.findIndex(p => p.id == editandoIdPedido);
        dadosPedido.id = editandoIdPedido;
        if (index >= 0) {
            dadosPedido.data_producao     = db.pedidos[index].data_producao;
            dadosPedido.valor_recebido    = db.pedidos[index].valor_recebido || 0;
            dadosPedido.data_instalado    = db.pedidos[index].data_instalado;
            dadosPedido.baixa_realizada   = db.pedidos[index].baixa_realizada;
            // Baixas parciais e a timeline sobrevivem a edicao (pedido que
            // voltou para Orcamento nao repete baixa nem perde o historico).
            dadosPedido.baixa_tecido_realizada = db.pedidos[index].baixa_tecido_realizada;
            dadosPedido.baixa_mat_realizada    = db.pedidos[index].baixa_mat_realizada;
            if (db.pedidos[index].timeline) dadosPedido.timeline = db.pedidos[index].timeline;
            // Etiquetas: volumes e conferencia sobrevivem a edicao (so se ja existiam).
            if (db.pedidos[index].volumes !== undefined) dadosPedido.volumes = db.pedidos[index].volumes;
            if (db.pedidos[index].conferencia !== undefined) dadosPedido.conferencia = db.pedidos[index].conferencia;
            dadosPedido.data_criacao      = db.pedidos[index].data_criacao || db.pedidos[index].id;
            // Quem criou o pedido (lembrete de instalacao, "pedidos que vejo") nao muda ao editar.
            dadosPedido.criado_por        = db.pedidos[index].criado_por ?? null;
            // Agendamento de instalacao e vinculo com o instalador sobrevivem a edicao
            // (so se ja existiam; o formulario do pedido nao os edita).
            ['inst_agendado', 'inst_hora', 'inst_duracao', 'inst_obs', 'inst_endereco', 'inst_cidade',
             'inst_cep', 'inst_rua', 'inst_numero', 'inst_complemento', 'inst_bairro', 'inst_uf',
             'inst_historico', 'inst_confirmada_em', 'usuario_instalacao_id', 'instalador_nome', 'inst_aceite', 'inst_recusa']
                .forEach(k => { if (db.pedidos[index][k] !== undefined) dadosPedido[k] = db.pedidos[index][k]; });
            // Comissao paga e um retrato: valor, % e pessoa nao mudam com a edicao (so a nao paga recalcula).
            Object.keys(CAMPOS_COMISSAO).forEach(papel => {
                const c = CAMPOS_COMISSAO[papel], orig = db.pedidos[index];
                if (FinanceiroCore.statusEsperadoComissao(orig, papel) !== 'paga') return;
                const mudou = String(dadosPedido[c.id] || '') !== String(orig[c.id] || '')
                    || Math.abs((Number(dadosPedido[c.valor]) || 0) - (Number(orig[c.valor]) || 0)) >= 0.005;
                ['id', 'nome', 'pct', 'valor'].forEach(k => { dadosPedido[c[k]] = orig[c[k]]; });
                if (mudou) avisosComissaoPaga.push(`A comissão de ${orig[c.nome] || ''} já foi paga (${_finBrl(orig[c.valor])}). Ela não muda com esta edição.`);
            });
            dadosPedido.comissao_paga     = db.pedidos[index].comissao_paga     || false;
            // Status, pagamento e historico das comissoes sobrevivem a edicao.
            ['comissao_status', 'comissao_mov_id', 'comissao_conta_id', 'comissao_historico',
             'arq_comissao_status', 'arq_comissao_mov_id', 'arq_comissao_conta_id', 'arq_comissao_historico']
                .forEach(k => { if (db.pedidos[index][k] !== undefined) dadosPedido[k] = db.pedidos[index][k]; });
            dadosPedido.comissao_data_pgto = db.pedidos[index].comissao_data_pgto || null;
            dadosPedido.arq_comissao_paga      = db.pedidos[index].arq_comissao_paga      || false;
            dadosPedido.arq_comissao_data_pgto = db.pedidos[index].arq_comissao_data_pgto || null;
            dadosPedido.financeiro_gerado  = db.pedidos[index].financeiro_gerado  || false;
            // Data da 1a aprovacao (competencia das contas a receber): nunca muda.
            if (db.pedidos[index].data_aprovacao) dadosPedido.data_aprovacao = db.pedidos[index].data_aprovacao;
            dadosPedido.rt_gerado          = db.pedidos[index].rt_gerado          || false;
            // RT antiga (campo livre que saiu da tela): editar o pedido nao a apaga.
            dadosPedido.arquiteto_nome     = db.pedidos[index].arquiteto_nome     || '';
            dadosPedido.rt_pct             = db.pedidos[index].rt_pct             || 0;
            // Editar nao desfaz o vinculo com o agendamento de medicao.
            if (db.pedidos[index].medicao_id != null) dadosPedido.medicao_id = db.pedidos[index].medicao_id;
            if (dadosPedido.status === 'Na Costura' && !dadosPedido.baixa_realizada) {
                realizarBaixaEstoque(dadosPedido);
            }
            db.pedidos[index] = dadosPedido;
        }
    } else {
        // Vindo de "Criar Pedido" na agenda: se o agendamento ja ganhou pedido
        // (outra aba, botao voltar), nao cria um segundo.
        const med = pedidoMedicaoId ? (db.medicoes || []).find(m => m.id == pedidoMedicaoId) : null;
        const jaTem = _medPedidoVinculado(med);
        if (jaTem) {
            await showAlert(`Este agendamento de medição já tem o pedido #${formatPedidoId(jaTem.id)}.\nAbra esse pedido para alterá-lo.`, '⚠️');
            return;
        }
        dadosPedido.id = gerarNumeroPedido();
        dadosPedido.data_criacao = Date.now();
        if (med) _medVincularPedido(med, dadosPedido);
        dadosPedido.criado_por = getUsuarioLogado()?.id || null;
        if (dadosPedido.status === 'Na Costura') {
            realizarBaixaEstoque(dadosPedido);
        }
        db.pedidos.push(dadosPedido);
    }
    let pagoAMais = null;
    if (statusAnterior === 'Orçamento' && normalizarStatus(dadosPedido.status) !== 'Orçamento') {
        pagoAMais = gerarFinanceiroPedido(dadosPedido);
        registrarCustoPedido(dadosPedido);
    }
    gerarComissoesPedido(dadosPedido);
    syncDB();
    await avisarPagoAMais(pagoAMais);
    if (avisosComissaoPaga.length) await showAlert(avisosComissaoPaga.join(String.fromCharCode(10)), 'ℹ️');
    localStorage.removeItem('sc_editando_id');
    toastReload('Pedido salvo!');
    window.location.href = 'index.html';
}

// Pedido aprovado (qualquer etapa depois de Orcamento) abre so para leitura.
// Para editar, o pedido volta para Orcamento -- pelo botao do aviso, exceto
// o Instalado, que fica fechado de vez.
function bloquearPedidoAprovado() {
    const ped = db.pedidos.find(p => p.id == editandoIdPedido);
    if (!ped) return;
    const status = normalizarStatus(ped.status);
    if (status === 'Orçamento') return;

    document.querySelectorAll('.main input, .main select, .main textarea, .main button')
        .forEach(el => { el.disabled = true; });
    // a Galeria continua abrindo para mostrar os modelos (sem aplicar nada)
    document.querySelectorAll('.btn-galeria-pedido').forEach(el => { el.disabled = false; });
    const saveBtn = document.querySelector('.btn-success[onclick="salvarPedido()"]');
    if (saveBtn) saveBtn.style.display = 'none';

    const header = document.querySelector('.header');
    if (!header) return;
    const instalado = status === 'Instalado';
    const notice = document.createElement('div');
    notice.id = 'ped-aviso-bloqueio';
    notice.className = 'ped-aviso-bloqueio';
    notice.innerHTML = instalado
        ? '<span>🔒 Pedido instalado — somente leitura</span>'
        : `<span>🔒 Pedido aprovado (${escapeHtml(status)}) — bloqueado para edição. Para alterar, volte o pedido para Orçamento.</span>
           <button type="button" class="btn btn-sm" id="ped-voltar-orcamento" onclick="voltarPedidoParaOrcamento(${ped.id})">↩ Voltar para Orçamento</button>`;
    header.appendChild(notice);
}

// Volta um pedido aprovado para Orcamento, liberando a edicao. Os
// recebimentos em aberto saem do Financeiro e sao gerados de novo, com os
// valores atualizados, quando o pedido for aprovado outra vez; os ja pagos
// ficam e a nova aprovacao so cobra o que falta. Baixas de
// estoque ja feitas continuam valendo (nao sao repetidas).
async function voltarPedidoParaOrcamento(id) {
    if (!await exigirPermissao('pedidos', 'completo')) return;
    const ped = db.pedidos.find(p => p.id == id);
    if (!ped) return;
    const status = normalizarStatus(ped.status);
    if (status === 'Orçamento' || status === 'Instalado') return;
    if (_pedidoTemNotaAtiva(ped.id)) {
        await showAlert('Este pedido tem nota fiscal emitida. Cancele a nota antes de voltar para Orçamento.', '⚠️');
        return;
    }
    const recebimentos = (db.contas_receber || []).filter(cr => cr.pedido_id == ped.id && cr.status !== 'Cancelado');
    const pagos = recebimentos.filter(cr => cr.status === 'Pago');
    const abertos = recebimentos.filter(finAberta);
    const avisoFin = !recebimentos.length ? ''
        : pagos.length
            ? `

O que já foi recebido continua no Financeiro.${abertos.length ? ` ${abertos.length} lançamento(s) em aberto saem do Financeiro e` : ' Ao aprovar de novo,'} ${abertos.length ? 'serão gerados de novo ao aprovar, só com o que falta receber.' : 'só será cobrado o que falta receber.'}`
            : `

${abertos.length} lançamento(s) a receber em aberto sairão do Financeiro e serão gerados de novo ao aprovar.`;
    const nCom = (db.contas_pagar || []).filter(cp => cp.pedido_id == ped.id && cp.papel_comissao && finAberta(cp)).length;
    const avisoCom = nCom ? (nCom === 1 ? ' A comissão pendente deste pedido será removida.' : ` As ${nCom} comissões pendentes deste pedido serão removidas.`) : '';
    const ok = await showConfirm(`Voltar o pedido #${formatPedidoId(ped.id)} de "${status}" para Orçamento?

Ele sai do painel de produção e fica liberado para edição até ser aprovado de novo.${avisoFin}${avisoCom}`, '↩', 'Voltar para Orçamento', 'Cancelar');
    if (!ok) return;
    removerFinanceiroAbertoPedido(ped.id);
    ped.financeiro_gerado = false;
    ped.status = 'Orçamento';
    sincronizarComissoesPedido(ped);   // comissao nao paga deixa de ser registrada (volta a aprovar)
    if (!ped.timeline) ped.timeline = [];
    ped.timeline.push({ status: 'Orçamento', data: Date.now(), label: `Voltou para Orçamento (estava em ${status})` });
    // Conferencia valia para o pedido aprovado; volumes continuam.
    EtiquetasCore.zerarConferencia(ped, 'pedido voltou para Orçamento', Date.now());
    localStorage.setItem('sc_editando_id', ped.id);
    salvarERecarregar('Pedido voltou para Orçamento e está liberado para edição.');
}

function carregarPedidoParaEdicao(id) {
    const ped = db.pedidos.find(p => p.id == id);
    if (!ped) return;
    const cli = db.clientes.find(c => c.id == ped.clienteId);
    const buscaEl = document.getElementById('ped-cliente-busca');
    if (buscaEl && cli) { buscaEl.value = cli.nome; filtrarClientes(); }
    document.getElementById('ped-cliente').value = String(ped.clienteId || '');
    document.getElementById('ped-mao').value     = ped.maoObra || 0;
    document.getElementById('ped-status').value  = normalizarStatus(ped.status);
    const entregaEl = document.getElementById('ped-entrega');
    if (entregaEl) entregaEl.value = ped.data_entrega || '';
    const obsEl = document.getElementById('ped-obs');
    if (obsEl) obsEl.value = ped.observacoes || '';
    const recebidoEl = document.getElementById('ped-valor-recebido');
    if (recebidoEl) recebidoEl.value = ped.valor_recebido || 0;
    const descontoEl = document.getElementById('ped-desconto');
    if (descontoEl) descontoEl.value = ped.desconto_pct || 0;
    const vendedorEl = document.getElementById('ped-vendedor');
    if (vendedorEl) vendedorEl.value = String(ped.vendedor_id || '');
    const arqEl = document.getElementById('ped-arquiteto');
    if (arqEl) arqEl.value = String(ped.arq_id || '');
    preencherSelectFormaPagamento(formaPagamentoDoPedido(ped));
    const entradaEl = document.getElementById('ped-entrada-pct');
    if (entradaEl) entradaEl.value = Number.isFinite(ped.entrada_pct) ? ped.entrada_pct : entradaDaFormaPagamento(formaPagamentoDoPedido(ped));
    _mostrarMeioPedido('entrada', ped.meio_entrada);
    _mostrarMeioPedido('saldo', ped.meio_saldo);
    atualizarMeiosPedido();
    const ambientes = normalizarAmbientes(ped);
    _ambienteCounter = ambientes.length;
    pedidoDraft.ambientes = ambientes.map((a, i) => ({
        ...a, id: i + 1,
        tecidos: (a.tecidos || []).map(t => ({...t}))
    }));
    pedidoDraft.itens = (ped.itens || []).map(i => ({ ...i }));
    renderAmbientes(); renderItensPedido(); atualizarTotalPedido();
}

// --- KANBAN PCP ---
let _kanbanFiltro = { cliente: '', vendedor: '', tecido: '' };

// Os filtros ficam guardados na aba (sessionStorage): mudar o pedido de etapa recarrega
// a pagina, e o filtro escolhido tem que continuar valendo depois do recarregamento.
const KANBAN_CHAVE_FILTRO = 'sc_pcp_filtro';

function _kanbanLerCamposFiltro() {
    _kanbanFiltro.cliente  = (document.getElementById('kf-cliente')?.value  || '').toLowerCase().trim();
    _kanbanFiltro.vendedor = document.getElementById('kf-vendedor')?.value  || '';
    _kanbanFiltro.tecido   = document.getElementById('kf-tecido')?.value    || '';
}

function aplicarFiltroKanban() {
    _kanbanLerCamposFiltro();
    try {
        sessionStorage.setItem(KANBAN_CHAVE_FILTRO, JSON.stringify({
            cliente:  document.getElementById('kf-cliente')?.value || '',
            vendedor: _kanbanFiltro.vendedor,
            tecido:   _kanbanFiltro.tecido
        }));
    } catch (e) { /* sem sessionStorage: o filtro vale so ate recarregar */ }
    renderKanban();
}

// Devolve aos campos o filtro guardado. Vendedor ou tecido que nao existe mais volta a "Todos".
function _kanbanRestaurarFiltro() {
    let salvo = null;
    try { salvo = JSON.parse(sessionStorage.getItem(KANBAN_CHAVE_FILTRO) || 'null'); } catch (e) { salvo = null; }
    if (!salvo || typeof salvo !== 'object') return;
    const c = document.getElementById('kf-cliente');
    if (c) c.value = String(salvo.cliente || '');
    [['kf-vendedor', salvo.vendedor], ['kf-tecido', salvo.tecido]].forEach(([id, valor]) => {
        const sel = document.getElementById(id);
        if (!sel) return;
        const v = String(valor || '');
        sel.value = [...sel.options].some(o => o.value === v) ? v : '';
    });
    _kanbanLerCamposFiltro();
}

function limparFiltroKanban() {
    _kanbanFiltro = { cliente: '', vendedor: '', tecido: '' };
    try { sessionStorage.removeItem(KANBAN_CHAVE_FILTRO); } catch (e) { /* nada a limpar */ }
    const c = document.getElementById('kf-cliente');   if (c) c.value = '';
    const v = document.getElementById('kf-vendedor');  if (v) v.value = '';
    const t = document.getElementById('kf-tecido');    if (t) t.value = '';
    renderKanban();
}

function renderKanban() {
    const board = document.getElementById('kanban-board');
    if (!board) return;
    const COLUNAS = [
        { status: 'Medição',              label: 'Aguardando Medição Fina', cor: '#2D77C1', bg: 'var(--info-bg)' },
        { status: 'Aguardando Tecido',    label: 'Aguardando Tecido',       cor: '#FF7F08', bg: 'var(--orange-bg)' },
        { status: 'Na Costura',           label: 'Na Costura',              cor: '#9B31C8', bg: 'var(--purple-bg)' },
        { status: 'Pronto p/ Instalação', label: 'Pronto p/ Instalação',    cor: '#005D3B', bg: 'var(--ok-bg)' },
        { status: 'Aguardando Financeiro', label: 'Aguardando Financeiro',    cor: '#FF575F', bg: 'var(--danger-bg)' },
        { status: 'Instalado',            label: 'Instalado / Entregue',    cor: '#159912', bg: 'var(--ok-bg)' }
    ];
    const avisoEl = document.getElementById('aviso-orcamentos');
    const orcamentos = db.pedidos.filter(p => normalizarStatus(p.status) === 'Orçamento');
    if (avisoEl) {
        if (orcamentos.length > 0) {
            avisoEl.innerHTML = `<span>📋 <strong>${orcamentos.length}</strong> orçamento(s) aguardando aprovação</span><a href="index.html" class="btn btn-outline btn-sm">Ver no Dashboard →</a>`;
            avisoEl.style.display = 'flex';
        } else { avisoEl.style.display = 'none'; }
    }
    const filtroAtivo = _kanbanFiltro.cliente || _kanbanFiltro.vendedor || _kanbanFiltro.tecido;
    let totalFiltrado = 0;
    // Os mesmos pedidos filtrados alimentam o Kanban e a Lista.
    const grupos = COLUNAS.map(col => {
        const pedidos = db.pedidos.filter(p => normalizarStatus(p.status) === col.status && _kanbanPassaFiltro(p));
        totalFiltrado += pedidos.length;
        return { col, pedidos };
    });
    const resEl = document.getElementById('kf-resultado');
    if (resEl) resEl.textContent = filtroAtivo ? `${totalFiltrado} pedido(s) encontrado(s)` : '';
    const modo = _pcpModo();
    _pcpMarcarModo(modo);
    const lista = document.getElementById('kanban-lista');
    board.hidden = modo === 'lista';
    if (lista) lista.hidden = modo !== 'lista';
    if (modo === 'lista' && lista) { lista.innerHTML = _pcpListaHTML(grupos, filtroAtivo); return; }
    board.innerHTML = grupos.map(({ col, pedidos: pedidosCol }) => {
        const idx = STATUS_PIPELINE.indexOf(col.status);
        const isInstalado = col.status === 'Instalado';
        const cards = pedidosCol.length === 0 ? `<div class="kanban-empty">Nenhum pedido nesta etapa</div>`
            : pedidosCol.map(p => {
                const dataRef      = p.data_producao || p.id;
                const dias         = Math.floor((Date.now() - dataRef) / (1000 * 60 * 60 * 24));
                const ambientes    = normalizarAmbientes(p);
                const podeVoltar   = idx > 1;
                const podeAvancar  = idx < STATUS_PIPELINE.length - 1;
                const obsBadge     = p.observacoes ? `<span title="${escapeHtml(p.observacoes)}" style="cursor:help;margin-left:4px">💬</span>` : '';
                const cardAtrasado = statusEntrega(p)?.cls === 'badge-atrasado' ? ' kanban-card-atrasado' : '';
                const vendedorLinha = p.vendedor_nome ? `<div class="kanban-card-vendedor">👤 ${escapeHtml(p.vendedor_nome)}</div>` : '';
                if (isInstalado) {
                    const dataInst = p.data_instalado ? new Date(p.data_instalado).toLocaleDateString('pt-BR') : (dias + 'd atrás');
                    return `<div class="kanban-card${cardAtrasado}" style="padding:8px 10px">
                        <div class="kanban-card-top">
                            <span class="kanban-card-id" style="cursor:pointer;text-decoration:underline" onclick="editarPedido(${p.id})" title="Editar pedido">#${formatPedidoId(p.id)}</span>
                            <span class="kanban-card-age">${dataInst}</span>
                            ${_menuAcoesCardPedido(p, { podeVoltar })}
                        </div>
                        ${vendedorLinha}
                        <div class="kanban-card-cliente" style="font-size:13px">${escapeHtml(p.clienteNome||'')}${obsBadge}</div>
                        ${_badgeSaldoEmAberto(p)}
                        ${_badgeConferencia(p) ? `<div style="margin-top:4px">${_badgeConferencia(p)}</div>` : ''}
                    </div>`;
                }
                let badgeEst = '';
                const tecidoJaBaixado = p.baixa_tecido_realizada || p.baixa_realizada;
                for (const a of (tecidoJaBaixado ? [] : ambientes)) {
                    for (const t of (a.tecidos||[])) {
                        if (!t.tecidoId) continue;
                        if (tecidoTemEstoqueInfinito(t.tecidoId)) continue;
                        const disp = estoqueDisponivel(t.tecidoId);
                        if (disp < (t.consumo_linear||0)) { badgeEst = `<span class="badge-sem-estoque">⚠ Sem estoque</span>`; break; }
                        else if (!badgeEst && verificarConflitoDeLote(t.tecidoId, t.consumo_linear||0)) badgeEst = `<span class="badge-lote">⚠ Múltiplos lotes</span>`;
                    }
                    if (badgeEst.includes('Sem estoque')) break;
                }
                const badgeBaixa   = (p.baixa_realizada ? `<span class="badge-baixa">✔ Baixa OK</span>` : '') + _badgeConferencia(p);
                const entregaInf   = statusEntrega(p);
                const entregaBadge = entregaInf ? `<span class="${entregaInf.cls}">${entregaInf.label}</span>` : '';
                // Pronto p/ Instalacao: sem agendamento, a seta leva para a
                // agenda com o pedido ja selecionado; agendado, confirma a entrega.
                const prontoSemAgenda = col.status === 'Pronto p/ Instalação' && !_instAgendada(p);
                const instLinha = col.status !== 'Pronto p/ Instalação' ? ''
                    : prontoSemAgenda
                        ? `<div class="kanban-inst kanban-inst-pend">📅 Aguardando agendamento</div>`
                        : `<div class="kanban-inst">📅 ${_agdFmtData(p.data_entrega)}${p.inst_hora ? ' · ' + escapeHtml(p.inst_hora) : ''}${nomeInstalador(p) ? ' · ' + escapeHtml(nomeInstalador(p)) : ''}</div>`;
                const agFin = col.status === 'Aguardando Financeiro';
                const finLinha = agFin ? _kanbanFinanceiroHTML(p) : '';
                const podeAvancarMenu = podeAvancar && !prontoSemAgenda && !agFin;
                const btnAgendar = prontoSemAgenda
                    ? `<button class="btn btn-sm kanban-btn-agendar" onclick="irParaAgendaInstalacao(${p.id})" title="Agendar instalação">📅 Agendar instalação</button>`
                    : '';
                return `<div class="kanban-card${cardAtrasado}">
                    <div class="kanban-card-top">
                        <span class="kanban-card-id" style="cursor:pointer;text-decoration:underline" onclick="editarPedido(${p.id})" title="Editar pedido">#${formatPedidoId(p.id)}</span>
                        <span class="kanban-card-age${dias >= 30 ? ' kanban-card-age-critical' : dias >= 14 ? ' kanban-card-age-warning' : ''}">${dias === 0 ? 'hoje' : dias + 'd'}</span>
                        ${_menuAcoesCardPedido(p, { podeVoltar, podeAvancar: podeAvancarMenu })}
                    </div>
                    ${vendedorLinha}
                    <div class="kanban-card-cliente">${escapeHtml(p.clienteNome||'')}${obsBadge}</div>
                    ${entregaBadge ? `<div style="margin:3px 0 5px">${entregaBadge}</div>` : ''}
                    ${instLinha}
                    ${finLinha}
                    ${badgeEst||badgeBaixa ? `<div style="margin-bottom:6px">${badgeEst}${badgeBaixa}</div>` : ''}
                    ${btnAgendar}
                    ${agFin ? _kanbanBtnConfirmarPagamento(p) : ''}
                </div>`;
            }).join('');
        return `<div class="kanban-col">
            <div class="kanban-col-header" style="background:${col.cor}"><span>${col.label}</span><span class="kanban-count">${pedidosCol.length}</span></div>
            <div class="kanban-col-body" style="background:${col.bg}">${cards}</div>
        </div>`;
    }).join('');
    _kanbanAjustarAltura();
}

// Card em Aguardando Financeiro: a forma de pagamento escolhida na emissao
// (so nesta etapa) e a marca "Pendente" quando a instalacao informou saldo.
function _kanbanFinanceiroHTML(p) {
    const forma = formaPagamentoDoPedido(p);
    const pend = p.pagamento_pendente ? `<span class="kanban-pag-pendente" title="Saldo pendente informado na instalação">⏳ Pendente</span>` : '';
    if (!forma && !pend) return '';
    return `<div class="kanban-fin">${forma ? `<span class="kanban-fin-forma" title="Plano de pagamento">💳 ${escapeHtml(forma)}</span>` : ''}${pend}</div>`;
}

// Pedido Instalado com parcela ainda em aberto.
function _badgeSaldoEmAberto(p) {
    if (normalizarStatus(p.status) !== 'Instalado') return '';
    if (FinanceiroCore.saldoEmAberto(db.contas_receber, p.id) <= 0.01) return '';
    return `<div class="kanban-fin"><span class="kanban-pag-pendente" title="Ainda há parcela a receber">saldo em aberto</span></div>`;
}

// So Administrador/Financeiro veem o botao; os demais, o aviso de quem decide.
function _kanbanBtnConfirmarPagamento(p, curto) {
    return podeConfirmarPagamento()
        ? `<button class="btn btn-sm kanban-btn-pagamento" onclick="confirmarPagamentoPedido(${p.id})" title="Confirmar pagamento e marcar como instalado">💰 ${curto ? 'Confirmar' : 'Confirmar pagamento'}</button>`
        : `<div class="kanban-fin-aviso">Aguardando confirmação do financeiro</div>`;
}

// Altura fixa do quadro: o espaco que sobra entre o topo do quadro e o fim da
// area principal, para a pagina nao rolar. Mesmo com o aviso de orcamentos ou
// os filtros quebrando linha, o calculo parte da posicao real do quadro.
const _KANBAN_ALTURA_MIN = 320;
function _kanbanAjustarAltura() {
    const board = document.getElementById('kanban-board');
    if (!board || board.hidden || !board.offsetParent) return;
    const main = board.closest('.main');
    const topoMain = main ? main.getBoundingClientRect().top : 0;
    const altMain  = main ? main.clientHeight : window.innerHeight;
    const padBaixo = main ? parseFloat(getComputedStyle(main).paddingBottom) || 0 : 0;
    const topo = board.getBoundingClientRect().top - topoMain + (main ? main.scrollTop : 0);
    const alt = Math.max(_KANBAN_ALTURA_MIN, Math.floor(altMain - topo - padBaixo));
    board.style.setProperty('--kanban-altura', alt + 'px');
}
window.addEventListener('resize', () => _kanbanAjustarAltura());
// A fonte da pagina (Nunito) chega depois do primeiro desenho e muda a altura do que fica
// acima do quadro: recalcula quando ela termina de carregar.
if (document.fonts) {
    if (document.fonts.addEventListener) document.fonts.addEventListener('loadingdone', () => _kanbanAjustarAltura());
    if (document.fonts.ready) document.fonts.ready.then(() => _kanbanAjustarAltura());
}

// Busca do topo: nome do cliente ou numero do pedido (com ou sem #).
function _kanbanPassaFiltro(p) {
    const q = _kanbanFiltro.cliente;
    if (q) {
        const num = q.replace(/^#/, '');
        const casaNome = (p.clienteNome || '').toLowerCase().includes(q);
        const casaNum  = num && (String(p.id).includes(num) || String(formatPedidoId(p.id)).toLowerCase().includes(num));
        if (!casaNome && !casaNum) return false;
    }
    if (_kanbanFiltro.vendedor && (p.vendedor_nome||p.vendedor||'') !== _kanbanFiltro.vendedor) return false;
    if (_kanbanFiltro.tecido) {
        const amb = normalizarAmbientes(p);
        if (!amb.some(a => (a.tecidos||[]).some(t => String(t.tecidoId) === _kanbanFiltro.tecido))) return false;
    }
    return true;
}

// --- Status dos pedidos: modo Lista ------------------------------------------
// A escolha Kanban/Lista e os blocos fechados ficam guardados por usuario,
// neste navegador. Leitura e escrita protegidas: sem armazenamento, vale o padrao.
function _pcpChave(nome) { return `sc_pcp_${nome}_${getUsuarioLogado()?.id || 0}`; }
function _pcpLer(nome, padrao) {
    try { const v = localStorage.getItem(_pcpChave(nome)); return v == null ? padrao : JSON.parse(v); } catch (e) { return padrao; }
}
function _pcpGravar(nome, valor) {
    try { localStorage.setItem(_pcpChave(nome), JSON.stringify(valor)); } catch (e) {}
}
function _pcpModo() { return _pcpLer('modo', 'kanban') === 'lista' ? 'lista' : 'kanban'; }

function _pcpMarcarModo(modo) {
    ['kanban', 'lista'].forEach(m => {
        const b = document.getElementById('pcp-modo-' + m);
        if (!b) return;
        b.classList.toggle('ativo', m === modo);
        b.setAttribute('aria-pressed', String(m === modo));
    });
}

function trocarModoPCP(modo) {
    _pcpGravar('modo', modo === 'lista' ? 'lista' : 'kanban');
    renderKanban();
}

// Instalado comeca fechado: e a etapa que so cresce.
function _pcpFechados() {
    const v = _pcpLer('fechados', ['Instalado']);
    return Array.isArray(v) ? v : ['Instalado'];
}

function alternarBlocoPCP(status) {
    const f = _pcpFechados();
    const i = f.indexOf(status);
    if (i >= 0) f.splice(i, 1); else f.push(status);
    _pcpGravar('fechados', f);
    renderKanban();
}

function _pcpListaHTML(grupos, filtroAtivo) {
    const fechados = _pcpFechados();
    // Com filtro, bloco sem resultado some; sem filtro, aparece com a contagem 0.
    const visiveis = filtroAtivo ? grupos.filter(g => g.pedidos.length) : grupos;
    if (!visiveis.length) return `<div class="pcp-lista-vazia">Nenhum pedido encontrado com esses filtros.</div>`;
    return visiveis.map(({ col, pedidos }) => {
        const aberto = !fechados.includes(col.status);
        const idx = STATUS_PIPELINE.indexOf(col.status);
        const linhas = !pedidos.length
            ? `<div class="pcp-lista-nada">Nenhum pedido nesta etapa</div>`
            : pedidos.map(p => _pcpLinhaHTML(p, col, idx)).join('');
        const statusJs = escapeHtml(JSON.stringify(col.status));
        return `<section class="pcp-bloco${aberto ? ' aberto' : ''}" data-status="${escapeHtml(col.status)}" style="--bloco-cor:${col.cor};--bloco-bg:${col.bg}">
            <button type="button" class="pcp-bloco-head" onclick="alternarBlocoPCP(${statusJs})" aria-expanded="${aberto}">
                <span class="pcp-bloco-seta" aria-hidden="true">▸</span>
                <span class="pcp-bloco-nome">${escapeHtml(col.label)}</span>
                <span class="pcp-bloco-count">${pedidos.length}</span>
            </button>
            ${aberto ? `<div class="pcp-bloco-corpo">${linhas}</div>` : ''}
        </section>`;
    }).join('');
}

// Etiquetas so existem a partir de "Pronto p/ Instalacao" (regra em EtiquetasCore).
// Antes disso o botao continua visivel, mas travado, dizendo por que.
function podeImprimirEtiquetas(ped) {
    const st = normalizarStatus(ped && ped.status);
    return typeof EtiquetasCore !== 'undefined' ? EtiquetasCore.statusPermiteEtiqueta(st)
        : ['Pronto p/ Instalação', 'Aguardando Financeiro', 'Instalado'].includes(st);
}
function rotuloStatus(status) {
    return status === 'Medição' ? 'Aguardando Medição Fina' : status;
}
function msgEtiquetaBloqueada(ped) {
    return `As etiquetas só podem ser impressas quando o pedido chega em "Pronto p/ Instalação". Este pedido está em "${rotuloStatus(normalizarStatus(ped && ped.status))}".`;
}
// Acoes do pedido no Painel de Producao (card do Kanban e linha da Lista), no menu ⋮.
// Mesmas acoes e ordem dos antigos botoes; voltar/avancar so quando a etapa permite.
function _menuAcoesCardPedido(p, { podeVoltar, podeAvancar } = {}) {
    const etiquetaOk = podeImprimirEtiquetas(p);
    return menuAcoesHtml([
        { icone: '📋', rotulo: 'Ver Ordem de Serviço', onclick: `abrirOS(${p.id})` },
        etiquetaOk
            ? { icone: '🏷️', rotulo: 'Imprimir etiquetas', onclick: `abrirImpressaoEtiquetas(${p.id})` }
            : { icone: '🏷️', rotulo: 'Imprimir etiquetas', bloqueado: true, dica: 'Liberado a partir de "Pronto p/ Instalação"', onclick: `toast(msgEtiquetaBloqueada(db.pedidos.find(x => x.id == ${p.id})), 'warning', 4500)` },
        { icone: '⏱', rotulo: 'Ver timeline', onclick: `verTimeline(${p.id})` },
        { icone: '🧾', rotulo: 'Notas fiscais', onclick: `abrirNotasDoPedido(${p.id})`, oculto: (normalizarStatus(p.status) === 'Orçamento' && !_pedidoTemNota(p.id)) || typeof abrirNotasDoPedido !== 'function' },
        { icone: '←', rotulo: 'Voltar etapa', onclick: `moverStatus(${p.id},-1)`, oculto: !podeVoltar },
        { icone: '→', rotulo: 'Avançar etapa', onclick: `moverStatus(${p.id},1)`, oculto: !podeAvancar }
    ]);
}
function _badgeConferencia(p) {
    const m = (typeof EtiquetasCore !== 'undefined') ? EtiquetasCore.marcacaoConferencia(p) : null;
    return m ? `<span class="${m.cls}">${m.texto}</span>` : '';
}

function _pcpLinhaHTML(p, col, idx) {
    const podeVoltar  = idx > 1;
    const podeAvancar = idx < STATUS_PIPELINE.length - 1;
    const prontoSemAgenda = col.status === 'Pronto p/ Instalação' && !_instAgendada(p);
    const entrega = statusEntrega(p);
    const obs = p.observacoes ? `<span class="pcp-linha-obs" title="${escapeHtml(p.observacoes)}">💬</span>` : '';
    const agFin = col.status === 'Aguardando Financeiro';
    const avancar = !podeAvancar ? ''
        : agFin ? _kanbanBtnConfirmarPagamento(p, true)
        : prontoSemAgenda
            ? `<button class="btn btn-sm kanban-btn-agendar" onclick="irParaAgendaInstalacao(${p.id})" title="Agendar instalação">📅 Agendar</button>`
            : '';
    const menu = _menuAcoesCardPedido(p, { podeVoltar, podeAvancar: podeAvancar && !agFin && !prontoSemAgenda });
    return `<div class="pcp-linha">
        <button type="button" class="pcp-linha-num" onclick="editarPedido(${p.id})" title="Abrir pedido">#${formatPedidoId(p.id)}</button>
        <div class="pcp-linha-cli">
            <span class="pcp-linha-nome">${escapeHtml(p.clienteNome || '')}${obs}${p.baixa_realizada ? '<span class="badge-baixa">✔ Baixa OK</span>' : ''}${_badgeConferencia(p)}</span>
            ${p.amb ? `<span class="pcp-linha-amb">${escapeHtml(p.amb)}</span>` : ''}
            ${agFin ? _kanbanFinanceiroHTML(p) : _badgeSaldoEmAberto(p)}
        </div>
        <div class="pcp-linha-entrega">${entrega ? `<span class="${entrega.cls}">${entrega.label}</span>` : ''}</div>
        <div class="pcp-linha-acoes">
            ${avancar}
            ${menu}
        </div>
    </div>`;
}

// --- ASSINATURA DIGITAL (canvas) ---
function buildAssinaturaHTML(pedidoId, campo, w, h) {
    w = w || 260; h = h || 90;
    const ped = db.pedidos.find(p => p.id == pedidoId);
    const dataUrl = ped?.assinaturas?.[campo] || '';
    const canvasId = `sig-canvas-${pedidoId}-${campo}`;
    if (dataUrl) {
        return `<div class="assinatura-box">
            <img src="${dataUrl}" class="assinatura-img" style="width:${w}px;height:${h}px;object-fit:contain" alt="Assinatura">
            <button type="button" class="btn btn-outline btn-sm no-print" style="margin-top:4px" onclick="refazerAssinatura(${pedidoId},'${campo}')">✏️ Refazer assinatura</button>
        </div>`;
    }
    return `<div class="assinatura-box">
        <canvas id="${canvasId}" class="assinatura-canvas" data-pedido="${pedidoId}" data-campo="${campo}" width="${w}" height="${h}" style="width:${w}px;height:${h}px"></canvas>
        <div class="no-print" style="margin-top:4px;display:flex;gap:6px">
            <button type="button" class="btn btn-outline btn-sm" onclick="limparAssinatura('${canvasId}')">🗑️ Limpar</button>
            <button type="button" class="btn btn-sm" onclick="salvarAssinatura(${pedidoId},'${campo}','${canvasId}')">💾 Salvar Assinatura</button>
        </div>
    </div>`;
}

function iniciarAssinaturaPads(root) {
    (root || document).querySelectorAll('canvas.assinatura-canvas').forEach(canvas => {
        if (canvas._sigBound) return;
        canvas._sigBound = true;
        const ctx = canvas.getContext('2d');
        ctx.lineWidth = 2; ctx.lineCap = 'round'; ctx.strokeStyle = '#242424';
        let drawing = false, last = null;
        const pos = e => {
            const r = canvas.getBoundingClientRect();
            const cx = (e.touches ? e.touches[0].clientX : e.clientX) - r.left;
            const cy = (e.touches ? e.touches[0].clientY : e.clientY) - r.top;
            return { x: cx * canvas.width / r.width, y: cy * canvas.height / r.height };
        };
        const start = e => { drawing = true; last = pos(e); e.preventDefault(); };
        const move  = e => {
            if (!drawing) return;
            const p = pos(e);
            ctx.beginPath(); ctx.moveTo(last.x, last.y); ctx.lineTo(p.x, p.y); ctx.stroke();
            last = p; e.preventDefault();
        };
        const end = () => { drawing = false; };
        canvas.addEventListener('mousedown', start);
        canvas.addEventListener('mousemove', move);
        window.addEventListener('mouseup', end);
        canvas.addEventListener('touchstart', start, { passive: false });
        canvas.addEventListener('touchmove', move, { passive: false });
        canvas.addEventListener('touchend', end);
    });
}

function limparAssinatura(canvasId) {
    const canvas = document.getElementById(canvasId);
    if (!canvas) return;
    canvas.getContext('2d').clearRect(0, 0, canvas.width, canvas.height);
}

function _assinaturaCanvasVazio(canvas) {
    const data = canvas.getContext('2d').getImageData(0, 0, canvas.width, canvas.height).data;
    for (let i = 3; i < data.length; i += 4) if (data[i] !== 0) return false;
    return true;
}

async function salvarAssinatura(pedidoId, campo, canvasId) {
    const canvas = document.getElementById(canvasId);
    if (!canvas) return;
    if (_assinaturaCanvasVazio(canvas)) { await showAlert('Desenhe a assinatura antes de salvar.', '⚠️'); return; }
    const ped = db.pedidos.find(p => p.id == pedidoId);
    if (!ped) return;
    if (!ped.assinaturas) ped.assinaturas = {};
    ped.assinaturas[campo] = canvas.toDataURL('image/png');
    syncDB();
    toast('Assinatura salva!', 'success', 1500);
    _refrescarDocModalAtual();
}

async function refazerAssinatura(pedidoId, campo) {
    const ok = await showConfirm('Apagar esta assinatura e assinar novamente?', '🖊️');
    if (!ok) return;
    const ped = db.pedidos.find(p => p.id == pedidoId);
    if (ped?.assinaturas) delete ped.assinaturas[campo];
    syncDB();
    _refrescarDocModalAtual();
}

// --- DOC MODAL ---
let _docModalAtual = null; // { tipo: 'os'|'proposta', pedidoId, dias }

function _refrescarDocModalAtual() {
    if (!_docModalAtual) return;
    const paper = document.getElementById('doc-modal-paper')
        || document.getElementById('os-container')
        || document.getElementById('proposta-container');
    if (!paper) return;
    paper.innerHTML = _docModalAtual.tipo === 'os'
        ? gerarHTMLOS(_docModalAtual.pedidoId)
        : gerarHTMLProposta(_docModalAtual.pedidoId, _docModalAtual.dias || 15);
    iniciarAssinaturaPads(paper);
    preencherCodigosDocumento(paper);
}

// envio (opcional): o que vai no botao "📤 Enviar" (js/compartilhar-doc.js).
function abrirDocModal(htmlContent, titulo, extraToolbar, envio) {
    let overlay = document.getElementById('doc-modal-overlay');
    if (!overlay) {
        overlay = document.createElement('div');
        overlay.id = 'doc-modal-overlay';
        overlay.innerHTML = `
            <div id="doc-modal-topbar">
                <span id="doc-modal-topbar-title"></span>
                <div id="doc-modal-topbar-actions"></div>
            </div>
            <div id="doc-modal-scroll">
                <div id="doc-modal-paper"></div>
            </div>`;
        document.body.appendChild(overlay);
        overlay.addEventListener('click', e => { if (e.target === overlay) fecharDocModal(); });
    }
    document.getElementById('doc-modal-topbar-title').textContent = titulo || 'Documento';
    const paper = document.getElementById('doc-modal-paper');
    paper.innerHTML = htmlContent;
    iniciarAssinaturaPads(paper);
    preencherCodigosDocumento(paper);
    const comEnvio = !!envio && typeof definirEnvioDoc === 'function';
    if (typeof definirEnvioDoc === 'function') definirEnvioDoc(envio || null);
    document.getElementById('doc-modal-topbar-actions').innerHTML =
        (extraToolbar || '') +
        (comEnvio ? botaoEnviarHtml() : '') +
        `<button class="doc-modal-btn" onclick="imprimirDocModal()">🖨️ Imprimir / PDF</button>` +
        `<button class="doc-modal-btn doc-modal-btn-close" onclick="fecharDocModal()">✕ Fechar</button>`;
    overlay.classList.add('active');
    document.body.style.overflow = 'hidden';
}

// Quem abre um documento por cima de outra tela pode pedir para voltar a ela ao fechar (uma vez so).
let _docAoFecharUmaVez = null;

function fecharDocModal() {
    const voltar = _docAoFecharUmaVez;
    _docAoFecharUmaVez = null;
    // Usou o Enviar e nao respondeu se enviou: pergunta depois de fechar.
    const envio = typeof _envioDocAtual !== 'undefined' ? _envioDocAtual : null;
    const overlay = document.getElementById('doc-modal-overlay');
    if (overlay) overlay.classList.remove('active');
    document.body.style.overflow = '';
    _docModalAtual = null;
    if (typeof fecharMenuEnviar === 'function') fecharMenuEnviar(true);
    if (typeof definirEnvioDoc === 'function') definirEnvioDoc(null);
    if (envio && envio.usouEnviar && !envio.enviadoTratado && envio.aoFecharDepoisDeEnviar) envio.aoFecharDepoisDeEnviar();
    if (voltar) voltar();
}

async function imprimirDocModal() {
    const paper = document.getElementById('doc-modal-paper');
    if (!paper) return;
    if (!await documentoProntoParaImprimir(paper)) return;
    let printRoot = document.getElementById('doc-print-root');
    if (!printRoot) {
        printRoot = document.createElement('div');
        printRoot.id = 'doc-print-root';
        document.body.appendChild(printRoot);
    }
    const clone = paper.cloneNode(true);
    // cloneNode não preserva o bitmap desenhado no canvas — substitui cada canvas de
    // assinatura pela imagem atual antes de imprimir, mesmo que ainda não tenha sido salva.
    const origCanvases  = paper.querySelectorAll('canvas.assinatura-canvas');
    const cloneCanvases = clone.querySelectorAll('canvas.assinatura-canvas');
    origCanvases.forEach((origCanvas, i) => {
        const cloneCanvas = cloneCanvases[i];
        if (!cloneCanvas) return;
        const img = document.createElement('img');
        img.className = 'assinatura-img';
        img.style.cssText = cloneCanvas.style.cssText;
        img.src = origCanvas.toDataURL('image/png');
        cloneCanvas.replaceWith(img);
    });
    printRoot.innerHTML = '';
    printRoot.appendChild(clone);
    document.body.classList.add('doc-modal-printing');
    window.print();
    window.addEventListener('afterprint', function cleanup() {
        document.body.classList.remove('doc-modal-printing');
        printRoot.innerHTML = '';
        window.removeEventListener('afterprint', cleanup);
    }, { once: true });
}

function abrirPropostaModal(pedidoId) {
    _docModalAtual = { tipo: 'proposta', pedidoId, dias: 15 };
    const extra = `<label style="color:#fff;font-size:13px;display:flex;align-items:center;gap:6px;margin-right:4px">
        Validade: <input type="number" id="proposta-dias-modal" value="15" min="1" max="365"
            style="width:56px;padding:4px 6px;border-radius:4px;border:none;font-size:13px;text-align:center"
            onchange="atualizarPropostaModal(${pedidoId}, this.value)"> dias
    </label>`;
    abrirDocModal(gerarHTMLProposta(pedidoId, 15), 'Proposta Comercial', extra, envioProposta(pedidoId));
}

function atualizarPropostaModal(pedidoId, dias) {
    if (_docModalAtual) _docModalAtual.dias = parseInt(dias) || 15;
    const paper = document.getElementById('doc-modal-paper');
    if (paper) { paper.innerHTML = gerarHTMLProposta(pedidoId, parseInt(dias) || 15); iniciarAssinaturaPads(paper); }
}

// --- ORDEM DE SERVIÇO ---
function gerarHTMLOS(pedidoId, layout) {
    const ped = db.pedidos.find(p => p.id == pedidoId);
    if (!ped) return '<p style="text-align:center;color:#999;padding:40px;">OS não encontrada.</p>';
    return _htmlOS(ped, db.clientes.find(c => c.id == ped.clienteId), layout);
}

function _htmlOS(ped, cliente, layout) {
    layout = layout || getLayoutDocumento('os');
    const ambientes = normalizarAmbientes(ped);
    const hoje      = new Date().toLocaleDateString('pt-BR');
    const entrega   = ped.data_entrega ? new Date(ped.data_entrega + 'T12:00:00').toLocaleDateString('pt-BR') : '';
    const valores = Object.assign(valoresComunsEmpresa(), {
        cliente: cliente ? cliente.nome : (ped.clienteNome || ''),
        numero: formatPedidoId(ped.id), data_emissao: hoje, previsao_entrega: entrega,
        status: normalizarStatus(ped.status)
    });
    const tit = id => textoDoc(blocoDoLayout(layout, id).titulo, valores);
    const osSpec = (label, val) => `<span class="os-spec"><span class="os-spec-lbl">${label}</span>${val}</span>`;
    const ambientesHTML = ambientes.map((a, idx) => {
        const tecidos = a.tecidos || [];
        const totalConsumo = tecidos.reduce((s,t)=>s+(t.consumo_linear||0),0);
        const tecBlocks = tecidos.map((t, tidx) => {
            const prefixo = tecidos.length > 1 ? `Tecido ${tidx+1}: ` : '';
            const largTotal = ((a.largura||0)*(t.fator||1)).toFixed(2);
            return `<div class="os-tec-block">
                <div class="os-tec-name">${prefixo}${escapeHtml(t.tecidoNome||'—')}</div>
                <div class="os-tec-specs">
                    ${osSpec('Prega', escapeHtml(t.prega||'—'))}
                    ${osSpec('Fator', (t.fator||'—')+'x')}
                    ${osSpec('Barra', (t.bainha_cm??15)+' cm')}
                    ${osSpec('Cabeçote', (t.cabecote_cm??0)+' cm')}
                    ${osSpec('Largura total', largTotal+' m')}
                    ${osSpec('Panos', t.num_panos||'—')}
                    ${osSpec('Alt. corte', (t.alt_corte?t.alt_corte.toFixed(3):'—')+' m')}
                    <span class="os-spec os-spec-consumo"><span class="os-spec-lbl">Consumo</span><strong>${(t.consumo_linear||0).toFixed(2)} m</strong></span>
                </div>
            </div>`;
        }).join('');
        return `
        <div class="os-amb-card">
            <div class="os-amb-head">
                <span class="os-amb-name">Ambiente ${idx+1}${a.amb ? ': '+escapeHtml(a.amb) : ''}</span>
                <span class="os-amb-meta">${escapeHtml(a.fixacao||'—')} · ${escapeHtml(a.local_instalacao||'Parede')} · Abertura ${escapeHtml(a.abertura||'A')} · ${a.largura||'—'}m × ${a.altura||'—'}m${a.acionamento ? ' · ' + escapeHtml(textoAcionamento(a)) : ''}</span>
            </div>
            ${tecBlocks}
            ${tecidos.length > 1 ? `<div class="os-amb-total">Total do ambiente: <strong>${totalConsumo.toFixed(2)} m lineares</strong></div>` : ''}
        </div>`;
    }).join('');
    const assin = legendasAssinaturas(blocoDoLayout(layout, 'assinaturas'), 'os');
    const chavesAssin = [['costureira', assin[0]], ['instalador', assin[1]], ['conferencia', assin[2]]];
    const blocos = {
        cabecalho: `
        <div class="os-header doc-cab">
            <div>
                <div class="os-empresa">${buildEmpresaHeaderHTML(42)}</div>
                <div class="os-titulo">${textoDoc(layout.titulo, valores)}</div>
                ${(blocoDoLayout(layout, 'cabecalho').aviso || '').trim() ? `<div class="os-aviso">${textoDoc(blocoDoLayout(layout, 'cabecalho').aviso, valores)}</div>` : ''}
            </div>
            <div class="os-meta">
                <div class="os-meta-item"><span>OS Nº</span><strong>${formatPedidoId(ped.id)}</strong></div>
                ${htmlCodigoDocumento(ped.id)}
                <div class="os-meta-item"><span>Emissão</span><strong>${hoje}</strong></div>
                ${entrega ? `<div class="os-meta-item"><span>Previsão entrega</span><strong>${entrega}</strong></div>` : ''}
                <div class="os-meta-item"><span>Status</span><strong>${normalizarStatus(ped.status)}</strong></div>
            </div>
        </div>`,
        cliente: `<div class="os-cliente-bar"><span class="os-cliente-label">${tit('cliente')}</span><strong>${escapeHtml(cliente?cliente.nome:'—')}</strong></div>`,
        ambientes: ambientesHTML,
        materiais: ped.itens && ped.itens.length ? `
        <div class="os-section">
            <div class="os-section-title">${tit('materiais')}</div>
            <table class="os-table">
                <tr><td class="os-th" style="width:40%">Material</td><td class="os-th">Quantidade</td><td class="os-th">Unidade</td></tr>
                ${ped.itens.map(i=>`<tr><td>${escapeHtml(i.nome)}</td><td>${i.quantidade}</td><td>${escapeHtml(i.unidade)}</td></tr>`).join('')}
            </table>
        </div>` : '',
        observacoes: `<div class="os-section"><div class="os-section-title">${tit('observacoes')}</div><div class="os-obs-box" style="padding:10px 14px;font-size:14px;min-height:64px">${ped.observacoes ? escapeHtml(ped.observacoes) : ''}</div></div>`,
        assinaturas: `
        <div class="os-assinaturas">
            ${chavesAssin.map(([chave, a]) => `<div class="os-assinatura-item"><div class="os-section-title">${textoDoc(a.titulo, valores)}</div>${buildAssinaturaHTML(ped.id, chave, 200, 70)}<small>${textoDoc(a.legenda, valores)}</small></div>`).join('')}
        </div>`
    };
    return montarDocumentoLayout('os', layout, blocos, valores);
}

function renderOS() {
    const container = document.getElementById('os-container');
    if (!container) return;
    const pedidoId = localStorage.getItem('sc_os_id');
    _docModalAtual = { tipo: 'os', pedidoId };
    if (typeof definirEnvioDoc === 'function') definirEnvioDoc(envioOS(pedidoId));
    container.innerHTML = gerarHTMLOS(pedidoId);
    iniciarAssinaturaPads(container);
    preencherCodigosDocumento(container);
}

// --- LAYOUT DOS DOCUMENTOS ---
// Cada documento impresso e montado bloco a bloco a partir do layout salvo em
// Configurar Empresa (sc_doc_layouts). O catalogo, os padroes e a leitura
// tolerante ficam em js/docs-layout-core.js (DocsLayout).
function getLayoutsDocumentos() {
    const l = DocsLayout.ler(localStorage.getItem('sc_doc_layouts'));
    return DocsLayout.migrarCondicoes(l, localStorage.getItem('sc_cond_gerais'));
}

function getLayoutDocumento(docId) {
    return DocsLayout.doDocumento(getLayoutsDocumentos(), docId);
}

function valoresComunsEmpresa() {
    const emp = getEmpresa();
    return {
        empresa:          emp.nome_fantasia || emp.razao_social || 'SCTech',
        empresa_telefone: emp.telefone || '',
        empresa_email:    emp.email || '',
        empresa_site:     emp.site || '',
        empresa_endereco: emp.endereco || '',
        empresa_cnpj:     emp.cnpj || ''
    };
}

// Texto do usuario com marcadores: o texto e escapado e cada {campo} vira o
// valor (tambem escapado). Marcador desconhecido fica como esta.
function textoDoc(texto, valores) {
    if (!String(texto || '').trim()) return '';
    return DocsLayout.preencher(escapeHtml(texto || ''), valores, escapeHtml);
}

function blocoDoLayout(layout, id) {
    return layout.blocos.find(b => b.id === id) || {};
}

const _fontesDocCarregadas = new Set();
function _carregarFonteDocumento(fonteId) {
    const f = DocsLayout.FONTES.find(x => x.id === fonteId);
    if (!f || !f.google || _fontesDocCarregadas.has(f.google) || typeof document === 'undefined') return;
    _fontesDocCarregadas.add(f.google);
    const link = document.createElement('link');
    link.rel = 'stylesheet';
    link.href = 'https://fonts.googleapis.com/css2?family=' + encodeURIComponent(f.google).replace(/%20/g, '+') + ':wght@400;600;700&display=swap';
    document.head.appendChild(link);
}

// Bloco de texto livre (blocos proprios): titulo + um paragrafo por linha.
function htmlBlocoTexto(bloco, valores) {
    const linhas = String(bloco.corpo || '').split('\n').filter(l => l.trim());
    if (!linhas.length && !(bloco.titulo || '').trim()) return '';
    const titulo = (bloco.titulo || '').trim() ? `<h4 class="doc-texto-titulo">${textoDoc(bloco.titulo, valores)}</h4>` : '';
    return `<div class="doc-texto">${titulo}${linhas.map(l => `<p>${textoDoc(l.trim(), valores)}</p>`).join('')}</div>`;
}

// Legendas das assinaturas: uma linha "Titulo | legenda" por assinatura, na
// ordem; linha faltando usa a do padrao.
function legendasAssinaturas(bloco, docId) {
    const cat = DocsLayout.DOCUMENTOS[docId].blocos.find(b => b.id === bloco.id) || {};
    const ler = t => String(t || '').split('\n').map(l => { const [a, b] = l.split('|'); return { titulo: (a || '').trim(), legenda: (b || '').trim() }; });
    const salvas = ler(bloco.corpo);
    return ler(cat.corpo).map((p, i) => salvas[i] && (salvas[i].titulo || salvas[i].legenda) ? salvas[i] : p);
}

// Junta os blocos na ordem do layout, aplica cores/fonte por variaveis CSS e
// poe a logo no fundo. `blocos` e { idDoBloco: html }; bloco vazio e pulado.
function montarDocumentoLayout(docId, layout, blocos, valores) {
    const emp = getEmpresa();
    _carregarFonteDocumento(layout.estilo.fonte);
    const css = DocsLayout.variaveisCss(layout.estilo);
    const m = layout.estilo.marca;
    const marca = m.ativa && emp.logo_base64
        ? `<div class="doc-marca-dagua doc-marca-${m.tamanho}" style="opacity:${m.opacidade / 100}" aria-hidden="true"><img src="${escapeHtml(emp.logo_base64)}" alt=""></div>`
        : '';
    const corpo = layout.blocos.filter(b => b.visivel).map(b => {
        const html = b.proprio ? htmlBlocoTexto(b, valores) : (blocos[b.id] || '');
        if (!String(html).trim()) return '';
        return `<div class="doc-bloco doc-bloco-${b.id} doc-var-${b.variante}" data-bloco="${b.id}">${html}</div>`;
    }).join('');
    return `<div class="doc-layout doc-layout-${docId}"${css ? ` style="${escapeHtml(css)}"` : ''}>${marca}${corpo}</div>`;
}

// --- PROPOSTA PDF ---
function gerarHTMLProposta(pedidoId, diasValidade, layout) {
    const ped = db.pedidos.find(p => p.id == pedidoId);
    if (!ped) return '<p style="text-align:center;color:#999;padding:40px;">Pedido não encontrado.</p>';
    const cliente = db.clientes.find(c => c.id == ped.clienteId);
    return _htmlProposta(ped, cliente, diasValidade, layout);
}

function _htmlProposta(ped, cliente, diasValidade, layout) {
    layout = layout || getLayoutDocumento('proposta');
    diasValidade = diasValidade || 15;
    const ambientes    = normalizarAmbientes(ped);
    const hoje           = new Date().toLocaleDateString('pt-BR');
    const validade       = new Date(Date.now() + diasValidade * 24 * 60 * 60 * 1000).toLocaleDateString('pt-BR');
    const entrega = ped.data_entrega ? new Date(ped.data_entrega + 'T12:00:00').toLocaleDateString('pt-BR') : '';
    const valores = Object.assign(valoresComunsEmpresa(), {
        cliente: cliente ? cliente.nome : (ped.clienteNome || ''),
        cliente_telefone: cliente?.tel || '', cliente_email: cliente?.email || '', cliente_endereco: cliente ? _endImpCliente(cliente) : '',
        numero: formatPedidoId(ped.id), data_emissao: hoje, validade, diasValidade,
        total: 'R$ ' + (ped.valor || 0).toFixed(2), previsao_entrega: entrega,
        vendedor: ped.vendedor_nome || '', forma_pagamento: formaPagamentoDoPedido(ped)
    });
    const tit = id => textoDoc(blocoDoLayout(layout, id).titulo, valores);
    const ambRows = ambientes.map(a => {
        const tecidos = a.tecidos || [];
        const primTec = tecidos[0] || {};
        const descTecidos = tecidos.map(t => {
            const nome = escapeHtml(t.tecidoNome||'');
            return nome ? `${nome}${t.prega ? ' ('+escapeHtml(t.prega)+', '+t.fator+'x)' : ''}` : '';
        }).filter(Boolean).join(' + ') || 'Tecido selecionado';
        const aberturaImg = a.abertura
            ? `<img src="${urlDesenhoCortina(a.abertura, tecidos.map(t => t.prega), false)}" alt="${escapeHtml(descricaoDesenhoCortina(a.abertura, tecidos.map(t => t.prega)))}"
                style="height:54px;width:auto;vertical-align:middle;margin-left:10px;border:1px solid #E0E0E0;border-radius:4px;padding:2px;background:#fff"
                title="Tipo de abertura: ${escapeHtml(a.abertura)}">`
            : '';
        return `<tr>
            <td><strong>${escapeHtml(a.amb||'—')}</strong></td>
            <td>
                <div style="display:flex;align-items:flex-start;justify-content:space-between;gap:12px">
                    <div>
                        <strong>Cortina</strong> em ${descTecidos}${a.fixacao?' — '+escapeHtml(a.fixacao):''}${a.abertura?' | Abertura '+escapeHtml(a.abertura):''}${a.local_instalacao?' | '+escapeHtml(a.local_instalacao):''}
                        <br><small>Parede: ${a.largura}m × ${a.altura||'—'}m | ${(primTec.num_panos||'—')} pano(s) de ${primTec.alt_corte?primTec.alt_corte.toFixed(3):'—'}m${tecidos.length>1?' | '+tecidos.length+' tecidos':''}</small>
                    </div>
                    ${aberturaImg}
                </div>
            </td>
        </tr>`;
    }).join('');
    const acessRows = ped.itens && ped.itens.length ? ped.itens.map(i =>
        `<tr><td><em>Acessório</em></td><td>${escapeHtml(i.nome)} — ${i.quantidade} ${escapeHtml(i.unidade)}</td></tr>`
    ).join('') : '';
    const condicoes = String(blocoDoLayout(layout, 'condicoes').corpo || '').split('\n').filter(l => l.trim());
    const blocos = {
        cabecalho: `
        <div class="proposta-header doc-cab">
            <div class="proposta-logo">${buildEmpresaHeaderHTML(64)}</div>
            <div class="proposta-info"><h2>${textoDoc(layout.titulo, valores)}</h2><p>Nº <strong>${formatPedidoId(ped.id)}</strong></p>${htmlCodigoDocumento(ped.id)}<p>Data de emissão: ${hoje}</p><p>Válida até: ${validade}</p></div>
        </div>`,
        cliente: `
        <div class="proposta-cliente doc-pessoa">
            <h3>${tit('cliente')}</h3>
            <p><strong>${escapeHtml(cliente?cliente.nome:'Não vinculado')}</strong></p>
            ${cliente&&cliente.cpf   ? `<p>CPF: ${escapeHtml(cliente.cpf)}</p>`     : ''}
            ${cliente&&cliente.tel   ? `<p>Tel: ${escapeHtml(cliente.tel)}</p>`     : ''}
            ${cliente&&cliente.email ? `<p>${escapeHtml(cliente.email)}</p>`        : ''}
            ${cliente&&cliente.end   ? `<p>${escapeHtml(_endImpCliente(cliente))}</p>`  : ''}
        </div>`,
        ambientes: `
        <table class="proposta-tabela">
            <thead><tr><th style="width:15%">Ambiente</th><th>Descrição</th></tr></thead>
            <tbody>${ambRows}${acessRows}</tbody>
        </table>`,
        observacoes: ped.observacoes ? `<div class="proposta-obs" style="margin:16px 0;padding:12px 16px;background:var(--doc-fundo,#FAFAFA);border-left:3px solid var(--doc-destaque,#005D3B);border-radius:0 6px 6px 0">
            <div class="proposta-obs-titulo" style="font-size:11px;font-weight:700;color:#8F8F8F;text-transform:uppercase;letter-spacing:.5px;margin-bottom:6px">${tit('observacoes')}</div>
            <p style="font-size:13px;color:var(--dark);margin:0;white-space:pre-line">${escapeHtml(ped.observacoes)}</p>
        </div>` : '',
        totais: `
        <div class="proposta-totais">
            ${ped.desconto_pct > 0 ? `<div class="proposta-linha" style="color:#F43927"><span>Desconto (${ped.desconto_pct}%)</span><span>− R$ ${(ped.desconto_valor||0).toFixed(2)}</span></div>` : ''}
            <div class="proposta-linha proposta-total"><span>${tit('totais')}</span><span>R$ ${ped.valor.toFixed(2)}</span></div>
            ${entrega ? `<div class="proposta-linha" style="margin-top:10px;padding-top:10px;border-top:1px solid #eee;font-weight:600"><span>Previsão de Entrega</span><span>${entrega}</span></div>` : ''}
        </div>`,
        condicoes: condicoes.length ? `
        <div class="proposta-termos">
            <h4>${tit('condicoes')}</h4>
            <ul>${condicoes.map(l => `<li>${textoDoc(l.trim(), valores)}</li>`).join('')}
            </ul>
        </div>` : '',
        aprovacao: `
        <div class="proposta-aprovacao">
            <p>Aprovado em: _____ / _____ / _________</p>
            <p style="margin-top:12px">${textoDoc(blocoDoLayout(layout, 'aprovacao').corpo, valores)}</p>
            ${buildAssinaturaHTML(ped.id,'cliente',300,100)}
        </div>`
    };
    return montarDocumentoLayout('proposta', layout, blocos, valores);
}

function renderProposta() {
    const container = document.getElementById('proposta-container');
    if (!container) return;
    const pedidoId = localStorage.getItem('sc_proposta_id');
    _docModalAtual = { tipo: 'proposta', pedidoId, dias: 15 };
    if (typeof definirEnvioDoc === 'function') definirEnvioDoc(envioProposta(pedidoId));
    container.innerHTML = gerarHTMLProposta(pedidoId, 15);
    iniciarAssinaturaPads(container);
    preencherCodigosDocumento(container);
}

// --- BACKUP / EXPORTAR ---
// Dados do backup. fin_fase0: 1 diz que o arquivo ja passou pela migracao do
// Financeiro (Fase 0); importar um arquivo sem a marca migra de novo.
function _lerObjetoLS(chave) {
    try { const o = JSON.parse(localStorage.getItem(chave) || '{}'); return (o && typeof o === 'object' && !Array.isArray(o)) ? o : {}; } catch (e) { return {}; }
}
// Configuracoes que moram em chave propria do navegador e entram no backup (texto
// cru de cada chave). Ficam de fora o que e so do navegador/aba (sessao, tema,
// menu lateral, ordenacao, filtros, avisos ja vistos, cache de enderecos, passagem
// de dados entre telas e a copia de desfazer do importador).
const CHAVES_CONFIG_BACKUP = ['sc_doc_layouts', 'sc_cond_gerais', 'sc_etiqueta_cfg', 'sc_mostruario',
    'sc_alertas_cfg', 'sc_dashcards_cfg', 'sc_agd_cfg', 'sc_kits_fixacao_padrao', 'sc_papel_gerente'];
function _configsLS() {
    const o = {};
    CHAVES_CONFIG_BACKUP.forEach(k => { try { const v = localStorage.getItem(k); if (v !== null) o[k] = v; } catch (e) { /* sem storage */ } });
    return o;
}
function _dadosExportacao(marcaFase0) {
    const dados = {
        versao: '1.0', exportado_em: new Date().toISOString(),
        clientes: db.clientes, catalogo: db.catalogo, pedidos: db.pedidos,
        estoque: db.estoque, materiais: db.materiais, kits: db.kits,
        movimentos: db.movimentos, vendedores: db.vendedores,
        fornecedores: db.fornecedores, pedidos_compra: db.pedidos_compra, carrinhos: db.carrinhos,
        contas_receber: db.contas_receber, contas_pagar: db.contas_pagar, despesas_fixas: db.despesas_fixas,
        contas_fin: db.contas_fin, meios_pag: db.meios_pag, movimentos_fin: db.movimentos_fin, fechamentos_fin: db.fechamentos_fin,
        medicoes: db.medicoes, rotas: db.rotas || [], agenda_eventos: db.agenda_eventos || [],
        fin_metas: _lerObjetoLS('sc_fin_metas'), fin_orcamento_mes: _lerObjetoLS('sc_fin_orcamento_mes'),
        // Financeiro novo: categorias da DRE, excluidos e a versao dos dados (backup sem ela passa pela migracao v4).
        fin_categorias: db.fin_categorias, fin_excluidos: db.fin_excluidos || [], fin_extrato: db.fin_extrato || [], fin_extrato_imp: db.fin_extrato_imp || [], notas_fiscais: db.notas_fiscais || [], fin_versao: localStorage.getItem(CHAVE_FIN_VERSAO), comissao_v2: localStorage.getItem('sc_comissao_v2') === '1',
        empresa: getEmpresa(), formas_pag: getFormasPagamentoCfg(),
        import_perfis: db.import_perfis || [],
        config_ls: _configsLS(),
        ped_seq: parseInt(localStorage.getItem('sc_ped_seq') || '0') || 0,
        pc_seq: parseInt(localStorage.getItem('sc_pc_seq') || '0') || 0
    };
    // Acesso: usuarios (com senha ja em hash e preferencias) e papeis so entram no arquivo
    // quando quem exporta e o Administrador (a aba Backup tambem e do Gerente/Financeiro).
    // A sessao de quem esta logado fica so na aba e nunca entra no arquivo.
    if (ehAdministrador()) { dados.usuarios = db.usuarios; dados.papeis = db.papeis; }
    if (marcaFase0) dados.fin_fase0 = 1;
    return dados;
}
function _baixarJSON(dados, nome) {
    const blob = new Blob([JSON.stringify(dados, null, 2)], { type: 'application/json' });
    const url  = URL.createObjectURL(blob);
    const a    = document.createElement('a');
    a.href = url; a.download = nome;
    a.click(); setTimeout(() => URL.revokeObjectURL(url), 1000);
}
async function exportarDados() {
    const dados = _dadosExportacao(localStorage.getItem('sc_fin_migracao') === '1');
    // Os PDFs das notas ficam no IndexedDB: entram no arquivo do backup.
    if (typeof NfArquivos !== 'undefined') { try { dados.notas_fiscais = await NfArquivos.paraBackup(dados.notas_fiscais); } catch (e) { /* segue sem os PDFs */ } }
    _baixarJSON(dados, `sctech_backup_${hojeLocal()}.json`);
    toast('Backup exportado com sucesso!');
    const semPdf = typeof NfArquivos !== 'undefined' ? NfArquivos.falhasBackup || 0 : 0;
    if (semPdf) await showAlert(`${semPdf} PDF(s) não puderam ser incluídos no backup.`, '⚠️');
}
function importarDados(event) {
    const file = event.target.files[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = async e => {
        try {
            const dados = JSON.parse(e.target.result);
            if (!dados.clientes || !dados.catalogo || !dados.pedidos) { await showAlert('Arquivo inválido: estrutura não reconhecida.', '⚠️'); return; }
            const dataExp = dados.exportado_em ? new Date(dados.exportado_em).toLocaleDateString('pt-BR') : 'desconhecida';
            if (!await showConfirm(`Importar backup de ${dataExp}?\n\nTodos os dados atuais serão substituídos. Esta ação não pode ser desfeita.`, '⚠️', 'Importar', 'Cancelar')) return;
            db.clientes   = dados.clientes   || [];
            db.catalogo   = dados.catalogo   || [];
            db.pedidos    = dados.pedidos    || [];
            db.estoque    = dados.estoque    || [];
            db.materiais  = dados.materiais  || [];
            db.kits       = dados.kits       || [];
            db.movimentos = dados.movimentos || [];
            db.vendedores    = dados.vendedores    || [];
            db.fornecedores  = dados.fornecedores  || [];
            db.pedidos_compra = dados.pedidos_compra || [];
            db.carrinhos      = Array.isArray(dados.carrinhos) ? CarrinhoCore.removerVazios(dados.carrinhos) : [];
            db.contas_receber = dados.contas_receber || [];
            db.contas_pagar   = dados.contas_pagar   || [];
            db.despesas_fixas = dados.despesas_fixas || [];
            db.medicoes       = dados.medicoes       || [];
            db.rotas          = Array.isArray(dados.rotas) ? dados.rotas : [];
            db.agenda_eventos = Array.isArray(dados.agenda_eventos) ? dados.agenda_eventos : [];
            db.contas_fin     = dados.contas_fin     || [];
            db.meios_pag      = dados.meios_pag      || [];
            db.movimentos_fin = dados.movimentos_fin || [];
            db.fechamentos_fin = Array.isArray(dados.fechamentos_fin) ? dados.fechamentos_fin : [];
            // Categorias da DRE do arquivo; backup antigo (sem elas) volta as padrao.
            const catOk = c => c && typeof c === 'object' && Array.isArray(c.categorias) && Array.isArray(c.subgrupos);
            db.fin_categorias = catOk(dados.fin_categorias) ? dados.fin_categorias : FinCatCore.categoriasPadrao();
            db.fin_excluidos  = Array.isArray(dados.fin_excluidos) ? dados.fin_excluidos : [];
            db.fin_extrato    = Array.isArray(dados.fin_extrato) ? dados.fin_extrato : [];
            db.fin_extrato_imp = Array.isArray(dados.fin_extrato_imp) ? dados.fin_extrato_imp : [];
            db.notas_fiscais  = Array.isArray(dados.notas_fiscais) ? dados.notas_fiscais.filter(n => n && typeof n === 'object') : [];
            // PDFs das notas (do arquivo, inline) vao para o IndexedDB depois da gravacao; no sc_nf ficam so os dados.
            const pdfsNotas = typeof NfArquivos !== 'undefined' ? NfArquivos.separarDoBackup(db.notas_fiscais) : [];
            // Tudo numa gravacao so (dados, marca da Fase 0, metas, orcamentos, empresa e
            // planos): se faltar espaco no meio, o que ja foi gravado volta ao anterior e a
            // migracao nunca roda sobre dados misturados.
            // Backup antigo (sem a marca fin_fase0) passa pela migracao do Financeiro
            // ao recarregar; com a marca, ja esta migrado.
            const extras = [['sc_fin_migracao', dados.fin_fase0 ? '1' : null]];
            // Backup sem a versao 4 do Financeiro passa pela migracao v4 ao recarregar (com copia nova).
            extras.push([CHAVE_FIN_VERSAO, Number(dados.fin_versao) >= 4 ? String(dados.fin_versao) : null]);
            // Backup sem a marca das comissoes (contas de comissao em aberto) passa pela migracao ao recarregar.
            extras.push(['sc_comissao_v2', dados.comissao_v2 ? '1' : null]);
            // Ajustes por mes do Resultado: backup antigo (sem eles) volta ao padrao vazio.
            ['fin_metas', 'fin_orcamento_mes'].forEach(k => {
                const o = dados[k];
                extras.push(['sc_' + k, JSON.stringify(o && typeof o === 'object' && !Array.isArray(o) ? o : {})]);
            });
            // Acesso e numeracao. Backup antigo (sem usuarios/papeis) deixa os atuais como estao.
            // Com usuarios no arquivo: quem importou continua entrando pelo mesmo e-mail; se o
            // arquivo nao tem administrador ativo, quem importou vira administrador (ativo) para
            // ninguem ficar trancado fora. Se nao ha como manter a sessao, ela e encerrada
            // depois da gravacao e a pessoa entra pela tela de login (nunca vira outro usuario).
            // So o Administrador importa usuarios e papeis: para os demais eles ficam como estao.
            let sessaoNova = null, encerrarSessao = false;
            const usuariosAtuais = db.usuarios.slice();
            const importaAcessos = ehAdministrador();
            const acessosIgnorados = !importaAcessos &&
                ((Array.isArray(dados.papeis) && dados.papeis.length > 0) || (Array.isArray(dados.usuarios) && dados.usuarios.length > 0));
            if (importaAcessos && Array.isArray(dados.papeis) && dados.papeis.length) db.papeis = dados.papeis;
            if (importaAcessos && Array.isArray(dados.usuarios) && dados.usuarios.length) {
                db.usuarios = dados.usuarios;
                encerrarSessao = true;
                const mesmoId = (a, b) => String(a) === String(b);
                const maiorId = lista => lista.reduce((m, x) => Math.max(m, Number(x.id) || 0), 0);
                // papeis e usuarios precisam combinar: papel que falta volta do padrao; sem padrao,
                // o usuario fica com o papel Vendedor/Atendimento (o de menos acesso entre os padroes com login).
                const padroes = papeisPadrao();
                db.usuarios.forEach(u => {
                    if (db.papeis.some(p => mesmoId(p.id, u.papel_id))) return;
                    let p = padroes.find(x => mesmoId(x.id, u.papel_id)) || padroes.find(x => x.id === 3);
                    if (!db.papeis.some(x => mesmoId(x.id, p.id))) db.papeis.push(p);
                    u.papel_id = p.id;
                });
                let sess = null;
                try { sess = JSON.parse(sessionStorage.getItem('sc_user') || 'null'); } catch (e1) { sess = null; }
                const atual = sess && usuariosAtuais.find(u => mesmoId(u.id, sess.id));
                if (atual) {
                    let eu = db.usuarios.find(u => String(u.email || '').toLowerCase() === String(atual.email || '').toLowerCase());
                    let papelAdmin = db.papeis.find(p => p.nome === 'Administrador');
                    const temAdmin = () => db.usuarios.some(u => u.ativo && papelAdmin && mesmoId(u.papel_id, papelAdmin.id));
                    if (!temAdmin()) {
                        if (!papelAdmin) {
                            const padrao = padroes.find(p => p.nome === 'Administrador');
                            papelAdmin = db.papeis.some(p => mesmoId(p.id, padrao.id)) ? Object.assign({}, padrao, { id: maiorId(db.papeis) + 1 }) : padrao;
                            db.papeis.push(papelAdmin);
                        }
                        if (!eu) {
                            eu = Object.assign({}, atual, { id: maiorId(db.usuarios) + 1 });
                            db.usuarios.push(eu);
                        }
                        eu.ativo = true;
                        eu.papel_id = papelAdmin.id;
                    }
                    if (eu && eu.ativo) { sessaoNova = { id: eu.id, nome: nomeExibicao(eu), email: eu.email }; encerrarSessao = false; }
                }
            }
            // Contadores: o do backup quando existe; sem ele (backup antigo) o proximo numero
            // sai do maior pedido existente.
            extras.push(['sc_ped_seq', Number.isFinite(dados.ped_seq) ? String(Math.max(0, Math.floor(dados.ped_seq))) : null]);
            extras.push(['sc_pc_seq',  Number.isFinite(dados.pc_seq)  ? String(Math.max(0, Math.floor(dados.pc_seq)))  : null]);
            // Layout dos documentos, etiquetas, galeria, alertas, cards, agenda: com a secao
            // config_ls no arquivo, o que nao veio volta ao padrao; backup antigo (sem a secao)
            // mantem os atuais.
            if (Array.isArray(dados.import_perfis)) db.import_perfis = dados.import_perfis;
            if (dados.config_ls && typeof dados.config_ls === 'object' && !Array.isArray(dados.config_ls)) {
                CHAVES_CONFIG_BACKUP.forEach(k => {
                    // a marca do papel Gerente e parte dos papeis: so o Administrador a troca
                    if (k === CHAVE_PAPEL_GERENTE && !importaAcessos) return;
                    const v = dados.config_ls[k];
                    extras.push([k, typeof v === 'string' ? v : null]);
                });
            }
            // Backup antigo (sem empresa/formas) mantem as atuais.
            if (dados.empresa && typeof dados.empresa === 'object') extras.push(['sc_empresa', JSON.stringify(dados.empresa)]);
            if (Array.isArray(dados.formas_pag) && dados.formas_pag.length) extras.push(['sc_formas_pag', JSON.stringify(dados.formas_pag)]);
            // Sem espaco, a copia da Fase 0 (a chave grande) sai e tenta de novo; se ainda
            // falhar, ela volta.
            const copiaAntes = localStorage.getItem('sc_fin_backup_fase0');
            const copiaV3Antes = localStorage.getItem(CHAVE_FIN_BACKUP_V3);
            try { _syncDBBruto(extras); }
            catch (e1) {
                if (!_erroDeEspaco(e1) || (copiaAntes === null && copiaV3Antes === null)) throw e1;
                localStorage.removeItem('sc_fin_backup_fase0');
                localStorage.removeItem(CHAVE_FIN_BACKUP_V3);
                try { _syncDBBruto(extras); }
                catch (e2) {
                    if (copiaAntes !== null) _gravarSemFalhar('sc_fin_backup_fase0', copiaAntes);
                    if (copiaV3Antes !== null) _gravarSemFalhar(CHAVE_FIN_BACKUP_V3, copiaV3Antes);
                    throw e2;
                }
            }
            // Gravou: o que era dos dados anteriores (copia, revisao e avisos) sai.
            ['sc_fin_backup_fase0', 'sc_fin_revisar', 'sc_fin_backup_falhou', 'sc_fin_migracao_erro', CHAVE_FIN_BACKUP_V3, CHAVE_FIN_V4_FALHOU, CHAVE_FIN_V4_ERRO].forEach(k => localStorage.removeItem(k));
            // Sem PDFs a guardar nem a manter, so limpa os antigos (sem esperar, para a recarga nao atrasar).
            if (typeof NfArquivos !== 'undefined' && !pdfsNotas.length && !(pdfsNotas.manter || []).length) NfArquivos.limpar().catch(() => {});
            else if (typeof NfArquivos !== 'undefined') {
                const falhas = await NfArquivos.gravarVarios(pdfsNotas, pdfsNotas.manter);
                if (falhas.length) {
                    db.notas_fiscais.forEach(n => { if (falhas.some(id => String(id) === String(n.id))) { n.tem_pdf = false; n.pdf_nome = ''; delete n.pdf_tamanho; } });
                    _gravarChaves(['sc_nf'], { silencioso: true });
                    await showAlert(`${falhas.length} PDF(s) não puderam ser guardados neste navegador.`, '⚠️');
                }
            }
            if (sessaoNova) sessionStorage.setItem('sc_user', JSON.stringify(sessaoNova));
            else if (encerrarSessao) sessionStorage.removeItem('sc_user');
            if (acessosIgnorados) await showAlert('Dados importados. Usuários e acessos não foram importados: só o Administrador importa usuários.', 'ℹ️');
            toastReload('Dados importados com sucesso!', 'info');
            window.location.reload();
        } catch (err) {
            // Sem espaco: o navegador ficou com os dados antigos; recarrega para a tela mostrar o que esta salvo.
            if (_erroDeEspaco(err)) { await showAlert('A importação não foi concluída. ' + MSG_SEM_ESPACO, '⚠️'); window.location.reload(); }
            else await showAlert('Erro ao ler o arquivo. Certifique-se que é um backup válido do SCTech.', '❌');
        }
    };
    reader.readAsText(file);
    event.target.value = '';
}

// --- RELATÓRIOS ---
let _chartRelFat, _chartRelRec, _chartRelVend;

function renderRelatorios() {
    renderRelFaturamento();
    renderRelRecebiveis();
    renderRelVendedores();
}
function renderRelFaturamento() {
    const tb = document.getElementById('tb-rel-fat');
    if (!tb) return;
    const meses = [];
    const agora = new Date();
    for (let i = 5; i >= 0; i--) {
        const d = new Date(agora.getFullYear(), agora.getMonth() - i, 1);
        meses.push({ mes: d.getMonth(), ano: d.getFullYear(), label: d.toLocaleString('pt-BR', { month: 'short', year: '2-digit' }) });
    }
    const fatPorMes = [], recPorMes = [];
    tb.innerHTML = meses.map(m => {
        const pedsMes  = db.pedidos.filter(p => {
            if (normalizarStatus(p.status) !== 'Instalado') return false;
            const d = new Date(p.data_instalado || p.id);
            return d.getMonth() === m.mes && d.getFullYear() === m.ano;
        });
        const total    = pedsMes.reduce((s, p) => s + (p.valor || 0), 0);
        const recebido = pedsMes.reduce((s, p) => s + (p.valor_recebido || 0), 0);
        const ticket   = pedsMes.length ? total / pedsMes.length : 0;
        fatPorMes.push(total); recPorMes.push(recebido);
        return `<tr>
            <td style="text-transform:capitalize">${m.label}</td>
            <td style="text-align:center">${pedsMes.length}</td>
            <td>R$ ${total.toFixed(2)}</td>
            <td>R$ ${recebido.toFixed(2)}</td>
            <td>R$ ${ticket.toFixed(2)}</td>
        </tr>`;
    }).join('') || '<tr><td colspan="5" style="text-align:center;color:#999;padding:20px">Nenhum dado.</td></tr>';

    const ctx = document.getElementById('chart-rel-fat');
    if (ctx && typeof Chart !== 'undefined') {
        if (_chartRelFat) _chartRelFat.destroy();
        _chartRelFat = new Chart(ctx, {
            type: 'bar',
            data: {
                labels: meses.map(m => m.label),
                datasets: [
                    { label: 'Faturamento', data: fatPorMes, backgroundColor: 'rgba(0, 93, 59, 0.85)', borderColor: '#005D3B', borderWidth: 1.5, borderRadius: 6 },
                    { label: 'Recebido',    data: recPorMes, backgroundColor: 'rgba(201, 247, 117, 0.85)', borderColor: '#005D3B', borderWidth: 1.5, borderRadius: 6 }
                ]
            },
            options: {
                responsive: true, maintainAspectRatio: true,
                plugins: { legend: { position: 'top', labels: { font: { size: 12 } } } },
                scales: {
                    y: { beginAtZero: true, ticks: { callback: v => 'R$ ' + v.toLocaleString('pt-BR') }, grid: { color: 'rgba(0,0,0,0.05)' } },
                    x: { grid: { display: false } }
                }
            }
        });
    }
}
function renderRelRecebiveis() {
    const tb = document.getElementById('tb-rel-rec');
    if (!tb) return;
    const hoje = new Date(); hoje.setHours(0,0,0,0);
    const pendentes = db.pedidos.filter(p => {
        const saldo = (p.valor || 0) - (p.valor_recebido || 0);
        return saldo > 0.01 && normalizarStatus(p.status) !== 'Orçamento';
    }).map(p => {
        const cli   = db.clientes.find(c => c.id == p.clienteId);
        const saldo = (p.valor || 0) - (p.valor_recebido || 0);
        // Data real do pedido (o numero e sequencial, nao e data).
        const criado = typeof p.data_criacao === 'number' ? p.data_criacao : (typeof p.id === 'number' && p.id > 1e11 ? p.id : Date.now());
        const dias  = Math.max(0, Math.floor((hoje - new Date(criado)) / (1000 * 60 * 60 * 24)));
        return { ...p, _cli: cli?.nome || '—', _saldo: saldo, _dias: dias };
    }).sort((a, b) => b._dias - a._dias);
    if (!pendentes.length) {
        tb.innerHTML = '<tr><td colspan="6" style="text-align:center;color:#599;padding:20px">Nenhum valor pendente.</td></tr>';
        return;
    }
    tb.innerHTML = pendentes.map(p => {
        const faixa = p._dias > 90 ? '<span class="badge-pendente">+90 dias</span>'
            : p._dias > 60 ? '<span class="badge-parcial">61–90 dias</span>'
            : p._dias > 30 ? '<span style="background:var(--warn-bg);color:var(--warn-text);font-size:11px;font-weight:bold;padding:2px 8px;border-radius:10px">31–60 dias</span>'
            : '<span style="background:var(--info-bg);color:var(--info-text);font-size:11px;font-weight:bold;padding:2px 8px;border-radius:10px">≤30 dias</span>';
        const cls = COR_STATUS[normalizarStatus(p.status)] || 'st-orcamento';
        return `<tr>
            <td style="font-size:12px">#${formatPedidoId(p.id)}</td>
            <td>${escapeHtml(p._cli)}</td>
            <td>R$ ${(p.valor||0).toFixed(2)}</td>
            <td style="color:#F43927;font-weight:bold">R$ ${p._saldo.toFixed(2)}</td>
            <td><span class="status-tag ${cls}" style="font-size:11px">${normalizarStatus(p.status)}</span></td>
            <td>${faixa}</td>
        </tr>`;
    }).join('');
    const totalPendente = pendentes.reduce((s, p) => s + p._saldo, 0);
    const tfootEl = document.getElementById('tfoot-rel-rec');
    if (tfootEl) tfootEl.innerHTML = `<tr><td colspan="3" style="text-align:right;font-weight:bold;color:var(--text-soft)">Total a receber:</td><td style="font-weight:bold;color:#F43927">R$ ${totalPendente.toFixed(2)}</td><td colspan="2"></td></tr>`;

    // Gráfico aging por faixa
    const agingBuckets = { '≤ 30 dias': 0, '31–60 dias': 0, '61–90 dias': 0, '> 90 dias': 0 };
    pendentes.forEach(p => {
        if      (p._dias <= 30) agingBuckets['≤ 30 dias']  += p._saldo;
        else if (p._dias <= 60) agingBuckets['31–60 dias'] += p._saldo;
        else if (p._dias <= 90) agingBuckets['61–90 dias'] += p._saldo;
        else                    agingBuckets['> 90 dias']  += p._saldo;
    });
    const ctx = document.getElementById('chart-rel-rec');
    if (ctx && typeof Chart !== 'undefined') {
        if (_chartRelRec) _chartRelRec.destroy();
        _chartRelRec = new Chart(ctx, {
            type: 'bar',
            data: {
                labels: Object.keys(agingBuckets),
                datasets: [{ label: 'Saldo a receber (R$)', data: Object.values(agingBuckets),
                    backgroundColor: ['rgba(45,119,193,0.75)','rgba(242,201,36,0.75)','rgba(255,127,8,0.75)','rgba(244,57,39,0.75)'],
                    borderColor:     ['#2D77C1','#F2C924','#FF7F08','#F43927'],
                    borderWidth: 1.5, borderRadius: 5 }]
            },
            options: {
                indexAxis: 'y', responsive: true, maintainAspectRatio: true,
                plugins: { legend: { display: false } },
                scales: {
                    x: { beginAtZero: true, ticks: { callback: v => 'R$ ' + v.toLocaleString('pt-BR') }, grid: { color: 'rgba(0,0,0,0.05)' } },
                    y: { grid: { display: false } }
                }
            }
        });
    }
}
function renderRelVendedores() {
    const tb = document.getElementById('tb-rel-vend');
    if (!tb) return;
    const map = {};
    db.pedidos.forEach(p => {
        const v = p.vendedor_nome || p.vendedor || '(sem vendedor)';
        if (!map[v]) map[v] = { qtd: 0, total: 0, instalados: 0, fat: 0 };
        map[v].qtd++;
        map[v].total += (p.valor || 0);
        if (normalizarStatus(p.status) === 'Instalado') { map[v].instalados++; map[v].fat += (p.valor || 0); }
    });
    const lista = Object.entries(map).sort((a, b) => b[1].fat - a[1].fat);
    tb.innerHTML = lista.map(([v, d]) => `<tr>
        <td><strong>${escapeHtml(v)}</strong></td>
        <td style="text-align:center">${d.qtd}</td>
        <td style="text-align:center">${d.instalados}</td>
        <td>R$ ${d.total.toFixed(2)}</td>
        <td style="color:var(--primary-text);font-weight:bold">R$ ${d.fat.toFixed(2)}</td>
    </tr>`).join('') || '<tr><td colspan="5" style="text-align:center;color:#999;padding:20px">Nenhum dado.</td></tr>';

    const ctx = document.getElementById('chart-rel-vend');
    if (ctx && typeof Chart !== 'undefined' && lista.length) {
        if (_chartRelVend) _chartRelVend.destroy();
        const CORES = ['#005D3B','#2D77C1','#F2C924','#9B31C8','#FF575F','#17E8FF'];
        _chartRelVend = new Chart(ctx, {
            type: 'bar',
            data: {
                labels: lista.map(([v]) => v),
                datasets: [
                    { label: 'Faturado (R$)',    data: lista.map(([,d]) => d.fat),   backgroundColor: lista.map((_,i) => CORES[i % CORES.length] + 'cc'), borderColor: lista.map((_,i) => CORES[i % CORES.length]), borderWidth: 1.5, borderRadius: 5 },
                    { label: 'Em carteira (R$)', data: lista.map(([,d]) => d.total - d.fat), backgroundColor: 'rgba(0,0,0,0.06)', borderColor: 'rgba(0,0,0,0.15)', borderWidth: 1.5, borderRadius: 5 }
                ]
            },
            options: {
                responsive: true, maintainAspectRatio: true,
                plugins: { legend: { position: 'top', labels: { font: { size: 12 } } } },
                scales: {
                    x: { stacked: false, grid: { display: false } },
                    y: { beginAtZero: true, ticks: { callback: v => 'R$ ' + v.toLocaleString('pt-BR') }, grid: { color: 'rgba(0,0,0,0.05)' } }
                }
            }
        });
    }
}
function mostrarTabRel(tab) {
    if (_curTabRel !== tab) { _prevTabRel = _curTabRel; _curTabRel = tab; }
    document.querySelectorAll('#tab-rel-faturamento,#tab-rel-recebiveis,#tab-rel-vendedores').forEach(el => el.classList.remove('active'));
    document.querySelectorAll('[data-tab]').forEach(btn => { if (['faturamento','recebiveis','vendedores'].includes(btn.dataset.tab)) btn.classList.remove('active'); });
    document.getElementById(`tab-rel-${tab}`)?.classList.add('active');
    document.querySelector(`[data-tab="${tab}"]`)?.classList.add('active');
    if (tab === 'faturamento') renderRelFaturamento();
    if (tab === 'recebiveis')  renderRelRecebiveis();
    if (tab === 'vendedores')  renderRelVendedores();
    _tabBackBtn('.tab-nav', _prevTabRel, () => mostrarTabRel(_prevTabRel));
}

// --- VENDEDORES / ARQUITETOS ---
// Os dois vivem na mesma lista (db.vendedores) e se distinguem pelo campo
// tipo. Cadastro antigo nao tem tipo: e vendedor. Assim comissao, pagamento,
// relatorio e o campo do pedido funcionam igual para os dois.
const TIPOS_VENDEDOR = {
    vendedor:  { um: 'Vendedor',  varios: 'Vendedores' },
    arquiteto: { um: 'Arquiteto', varios: 'Arquitetos' },
};
let _tipoVend = 'vendedor';
function tipoDoVendedor(v) { return v && v.tipo === 'arquiteto' ? 'arquiteto' : 'vendedor'; }
function vendedoresDoTipo(tipo) { return (db.vendedores || []).filter(v => tipoDoVendedor(v) === tipo); }

// Opcoes dos campos Vendedor e Arquiteto do pedido: cada um so o seu tipo.
function opcoesCadastroPedido(tipo) {
    return vendedoresDoTipo(tipo)
        .map(v => `<option value="${v.id}">${escapeHtml(v.nome)} (${v.comissao_pct || 0}%)</option>`).join('');
}

// Comissao que o cadastro gera sobre um valor (0 quando nao ha cadastro).
function comissaoDoCadastro(id, valor) {
    const v = id ? (db.vendedores || []).find(x => x.id == id) : null;
    const pct = v ? (v.comissao_pct || 0) : 0;
    return { pct, valor: pct > 0 ? Math.round(valor * pct / 100 * 100) / 100 : 0 };
}

function _rotulosTipoVendedores() {
    const t = TIPOS_VENDEDOR[_tipoVend];
    document.querySelectorAll('.vend-col-nome').forEach(th => { th.textContent = t.um; });
    const tit = document.getElementById('vend-form-titulo');
    if (tit) tit.textContent = (editandoIdVendedor ? 'Editar ' : 'Cadastrar ') + t.um;
    const btn = document.getElementById('vend-btn-salvar');
    if (btn) btn.textContent = editandoIdVendedor ? 'Salvar Alterações' : 'Salvar ' + t.um;
}

function mostrarTipoVendedores(tipo) {
    if (!TIPOS_VENDEDOR[tipo]) tipo = 'vendedor';
    if (_tipoVend !== tipo) cancelarEdicaoVendedor();
    _tipoVend = tipo;
    _vendLembrarNaUrl('tipo', tipo);
    document.querySelectorAll('.vend-tipo-btn').forEach(b => b.classList.toggle('active', b.dataset.tipo === tipo));
    _rotulosTipoVendedores();
    mostrarTabVendedores(_curTabVend || 'lista');
}

async function salvarVendedor() {
    const t = TIPOS_VENDEDOR[_tipoVend];
    const nome = document.getElementById('vend-nome')?.value.trim();
    if (!nome) { await showAlert(`Informe o nome do ${t.um.toLowerCase()}.`, '⚠️'); return; }
    const comissao_pct = parseFloat(document.getElementById('vend-comissao')?.value) || 0;
    const tel = document.getElementById('vend-tel')?.value.trim() || '';
    const usuario_id = parseInt(document.getElementById('vend-usuario')?.value) || null;
    if (editandoIdVendedor) {
        const idx = db.vendedores.findIndex(v => v.id == editandoIdVendedor);
        if (idx !== -1) db.vendedores[idx] = { ...db.vendedores[idx], nome, comissao_pct, tel, usuario_id };
        cancelarEdicaoVendedor();
        salvarERecarregar(`${t.um} atualizado!`);
    } else {
        // Nome repetido e barrado entre os dois tipos: no pedido eles dividem o
        // mesmo campo, e dois "Studio M" seriam indistinguiveis.
        const dup = db.vendedores.find(v => v.nome.trim().toLowerCase() === nome.toLowerCase());
        if (dup) { await showAlert(`Já existe um cadastro com o nome "${dup.nome}" (${TIPOS_VENDEDOR[tipoDoVendedor(dup)].um.toLowerCase()}).`, '⚠️'); return; }
        db.vendedores.push({ id: Date.now(), tipo: _tipoVend, nome, comissao_pct, tel, usuario_id });
        salvarERecarregar(`${t.um} cadastrado!`);
    }
}

function editarVendedor(id) {
    const v = db.vendedores.find(x => x.id == id);
    if (!v) return;
    editandoIdVendedor = id;
    document.getElementById('vend-nome').value      = v.nome || '';
    document.getElementById('vend-comissao').value  = v.comissao_pct || 0;
    document.getElementById('vend-tel').value       = v.tel || '';
    const selUsu = document.getElementById('vend-usuario');
    if (selUsu) selUsu.value = v.usuario_id ? String(v.usuario_id) : '';
    const tit = document.getElementById('vend-form-titulo');
    const btn = document.getElementById('vend-btn-salvar');
    const cnc = document.getElementById('vend-btn-cancelar');
    if (tit) tit.textContent = 'Editar ' + TIPOS_VENDEDOR[tipoDoVendedor(v)].um;
    if (btn) btn.textContent = 'Salvar Alterações';
    if (cnc) cnc.style.display = 'inline-block';
    document.getElementById('vend-nome').focus();
    document.querySelector('.card')?.scrollIntoView({ behavior: 'smooth' });
}

function cancelarEdicaoVendedor() {
    editandoIdVendedor = null;
    ['vend-nome','vend-tel','vend-usuario'].forEach(id => { const el = document.getElementById(id); if (el) el.value = ''; });
    const comEl = document.getElementById('vend-comissao');
    if (comEl) comEl.value = '0';
    const tit = document.getElementById('vend-form-titulo');
    const btn = document.getElementById('vend-btn-salvar');
    const cnc = document.getElementById('vend-btn-cancelar');
    if (tit) tit.textContent = 'Cadastrar ' + TIPOS_VENDEDOR[_tipoVend].um;
    if (btn) btn.textContent = 'Salvar ' + TIPOS_VENDEDOR[_tipoVend].um;
    if (cnc) cnc.style.display = 'none';
}

async function excluirVendedor(id) {
    const v = db.vendedores.find(x => x.id == id);
    if (!v) return;
    const usados = db.pedidos.filter(p => p.vendedor_id == id || p.arq_id == id);
    if (usados.length) { await showAlert(`Não é possível excluir: ${escapeHtml(v.nome)} está associado a ${usados.length} pedido(s).`, '🚫'); return; }
    const um = TIPOS_VENDEDOR[tipoDoVendedor(v)].um;
    if (!await showConfirm(`Excluir o ${um.toLowerCase()} "${v.nome}"?`, '🗑️', 'Excluir', 'Cancelar')) return;
    db.vendedores = db.vendedores.filter(x => x.id != id);
    salvarERecarregar(`${um} excluído.`);
}

// Salvar recarrega a pagina; a aba aberta vai no endereco para voltar a ela.
function _vendLembrarNaUrl(chave, valor) {
    try {
        const u = new URL(window.location.href);
        u.searchParams.set(chave, valor);
        history.replaceState(null, '', u);
    } catch (e) { /* sem history (ex.: file:// restrito): so nao lembra */ }
}

function renderTabelaVendedores() {
    const tb = document.getElementById('tb-vendedores');
    if (!tb) return;
    const c = CAMPOS_COMISSAO[_tipoVend];
    const lista = vendedoresDoTipo(_tipoVend);
    if (!lista.length) {
        tb.innerHTML = `<tr><td colspan="6" style="text-align:center;color:#999;padding:20px;">Nenhum ${TIPOS_VENDEDOR[_tipoVend].um.toLowerCase()} cadastrado.</td></tr>`;
        return;
    }
    tb.innerHTML = lista.map(v => {
        const pedidos        = db.pedidos.filter(p => p[c.id] == v.id);
        const totalComissoes = pedidos.reduce((s, p) => s + (p[c.valor] || 0), 0);
        const comissoesPagas = pedidos.filter(p => p[c.paga]).reduce((s, p) => s + (p[c.valor] || 0), 0);
        const pendente       = totalComissoes - comissoesPagas;
        return `<tr>
            <td><strong>${escapeHtml(v.nome)}</strong></td>
            <td style="text-align:center">${v.comissao_pct || 0}%</td>
            <td>${escapeHtml(v.tel || '—')}</td>
            <td style="text-align:center">${pedidos.length}</td>
            <td>${pendente > 0.01 ? `<span class="badge-comissao-pendente">R$ ${pendente.toFixed(2)} pendente</span>` : '<span class="badge-comissao-paga">Em dia</span>'}</td>
            <td class="td-acoes">${menuAcoesHtml([
                { icone: '✏️', rotulo: 'Editar', onclick: `editarVendedor(${v.id})` },
                { icone: '🗑️', rotulo: 'Excluir', onclick: `excluirVendedor(${v.id})`, perigo: true }
            ])}</td>
        </tr>`;
    }).join('');
}

// --- TELA VENDEDORES > COMISSOES ---
// Filtros Vendedor (todos, vendedores e arquitetos) e Mes (data de instalacao); a tabela e os cartoes saem de
// FinanceiroCore.linhasComissoes/totaisComissoes. Pagar = registrarPagamentoComissoes (movimento de saida, sem conta a pagar).
const _COM_STATUS_ROTULO = { registrada: 'Registrada', pendente: 'Pendente', em_cp: 'Em Contas a Pagar', paga: 'Paga' };
const _COM_STATUS_CLASSE = { registrada: 'fin-badge-gray', pendente: 'fin-badge-pending', em_cp: 'fin-badge-pending', paga: 'fin-badge-green' };
let _comLinhasVisiveis = [];

function _comMesLabel(m) {
    const [a, mm] = m.split('-');
    return ['janeiro', 'fevereiro', 'março', 'abril', 'maio', 'junho', 'julho', 'agosto', 'setembro', 'outubro', 'novembro', 'dezembro'][Number(mm) - 1] + ' de ' + a;
}

function _preencherFiltrosComissoes() {
    const selV = document.getElementById('com-filtro-vend');
    const selM = document.getElementById('com-filtro-mes');
    if (!selV || !selM) return;
    const atualV = selV.value, atualM = selM.value;
    const lista = (db.vendedores || []).slice().sort((a, b) => String(a.nome).localeCompare(String(b.nome), 'pt-BR'));
    selV.innerHTML = '<option value="">Todos</option>' + lista.map(v => `<option value="${escapeHtml(String(v.id))}">${escapeHtml(v.nome)}${tipoDoVendedor(v) === 'arquiteto' ? ' (arquiteto)' : ''}</option>`).join('');
    selV.value = [...selV.options].some(o => o.value === atualV) ? atualV : '';
    const meses = new Set();
    FinanceiroCore.linhasComissoes(db.pedidos, db.vendedores, {}).forEach(l => { if (l.data) meses.add(l.data.slice(0, 7)); });
    selM.innerHTML = '<option value="">Todos</option>' + [...meses].sort().reverse().map(m => `<option value="${m}">${_comMesLabel(m)}</option>`).join('');
    selM.value = [...selM.options].some(o => o.value === atualM) ? atualM : '';
}

function _comLinhasFiltradas() {
    const vendedorId = document.getElementById('com-filtro-vend')?.value || '';
    const mes = document.getElementById('com-filtro-mes')?.value || '';
    const linhas = FinanceiroCore.linhasComissoes(db.pedidos, db.vendedores, { vendedorId, mes, contasPagar: db.contas_pagar });
    linhas.sort((a, b) => String(b.data || '').localeCompare(String(a.data || '')) || (b.pedidoId - a.pedidoId));
    return linhas;
}

function renderComissoes() {
    const tb = document.getElementById('tb-comissoes');
    if (!tb) return;
    if (!document.getElementById('com-filtro-vend').options.length) _preencherFiltrosComissoes();
    const pode = _permiteGerirComissoes();
    const linhas = _comLinhasFiltradas();
    _comLinhasVisiveis = linhas;
    const tot = FinanceiroCore.totaisComissoes(linhas);
    const cartoes = Object.values(tot.porVendedor).sort((a, b) => String(a.nome).localeCompare(String(b.nome), 'pt-BR'));
    document.getElementById('com-cartoes').innerHTML = cartoes.map(t => {
        const chave = String(t.vendedorId != null ? t.vendedorId : 'nome:' + t.nome);
        return `<div class="card com-cartao" data-vend="${escapeHtml(chave)}" style="flex:1 1 240px;margin:0">
            <h4 style="margin:0 0 8px;font-size:15px">${escapeHtml(t.nome || '—')}</h4>
            <div style="display:flex;justify-content:space-between;font-size:13px;padding:2px 0"><span>Acumulado</span><strong class="com-acumulado">${_finBrl(t.acumulado)}</strong></div>
            <div style="display:flex;justify-content:space-between;font-size:13px;padding:2px 0"><span>A pagar</span><strong class="com-apagar" style="color:#F43927">${_finBrl(t.aPagar)}</strong></div>
            <div style="display:flex;justify-content:space-between;font-size:13px;padding:2px 0"><span>Pago</span><strong class="com-pago" style="color:var(--ok-text)">${_finBrl(t.pago)}</strong></div>
            ${pode && t.pagavel > 0 ? `<button class="btn btn-sm btn-success com-pagar-todos" style="margin-top:8px;width:100%">Pagar todos os pendentes de ${escapeHtml(t.nome || '—')}</button>` : ''}
        </div>`;
    }).join('');
    document.getElementById('com-sel-todos').style.visibility = pode ? 'visible' : 'hidden';
    document.getElementById('com-sel-todos').checked = false;
    document.getElementById('com-btn-pagar').style.display = pode ? '' : 'none';
    if (!linhas.length) {
        tb.innerHTML = '<tr><td colspan="11" style="text-align:center;color:#999;padding:20px;">Nenhuma comissão encontrada.</td></tr>';
        _comAtualizarSelecao();
        return;
    }
    tb.innerHTML = linhas.map((l, i) => {
        const acoes = pode && l.status === 'paga' ? menuAcoesHtml([{ icone: '↩', rotulo: 'Desfazer pagamento', onclick: `desfazerPagamentoComissaoTela(${l.pedidoId},'${l.papel}')` }]) : '';
        return `<tr data-ped="${l.pedidoId}" data-papel="${l.papel}" data-status="${l.status}">
            <td style="width:30px">${pode && l.status === 'pendente' ? `<input type="checkbox" class="com-sel" data-i="${i}" onchange="_comAtualizarSelecao()">` : ''}</td>
            <td style="font-size:12px;white-space:nowrap">${l.data ? _finDataBR(l.data) : '—'}</td>
            <td style="font-size:12px"><span style="cursor:pointer;color:var(--primary);font-weight:bold;text-decoration:underline" onclick="abrirPedidoDaComissao(${l.pedidoId})" title="Abrir pedido">#${formatPedidoId(l.pedidoId)}</span></td>
            <td>${escapeHtml(l.clienteNome || '—')}</td>
            <td>${escapeHtml(l.nome || '—')}${l.papel === 'arquiteto' ? ' <span style="color:#888;font-size:11px">(arquiteto)</span>' : ''}</td>
            <td>${_finBrl(l.valorPedido)}</td>
            <td>${l.pct}%</td>
            <td><strong>${_finBrl(l.valor)}</strong></td>
            <td><span class="fin-badge ${_COM_STATUS_CLASSE[l.status] || ''}">${_COM_STATUS_ROTULO[l.status] || l.status}</span></td>
            <td style="font-size:12px;white-space:nowrap">${l.pagoEm ? _finDataBR(l.pagoEm) : '—'}</td>
            <td class="td-acoes">${acoes}</td>
        </tr>`;
    }).join('');
    _comAtualizarSelecao();
}

function _comSelecionadas() {
    return [...document.querySelectorAll('#tb-comissoes .com-sel:checked')].map(cb => _comLinhasVisiveis[Number(cb.dataset.i)]).filter(Boolean);
}

function _comAtualizarSelecao() {
    const sel = _comSelecionadas();
    const total = sel.reduce((s, l) => s + l.valor, 0);
    const el = document.getElementById('com-sel-resumo');
    if (el) el.textContent = sel.length ? `${sel.length} selecionada(s): ${_finBrl(total)}` : '';
    const btn = document.getElementById('com-btn-pagar');
    if (btn) btn.disabled = !sel.length;
}

function comSelecionarTodos(marcado) {
    document.querySelectorAll('#tb-comissoes .com-sel').forEach(cb => { cb.checked = marcado; });
    _comAtualizarSelecao();
}

// A chave do cartao fica no data-vend (nunca dentro de um onclick: o nome e texto livre).
document.addEventListener('click', e => {
    const b = e.target.closest && e.target.closest('.com-pagar-todos');
    if (b) pagarTodosPendentesComissao(b.closest('.com-cartao').dataset.vend);
});

function abrirPedidoDaComissao(pedidoId) { editarPedido(pedidoId); }

async function _pagarLinhasComissao(linhas, titulo) {
    if (!_permiteGerirComissoes()) { await showAlert('Você não tem permissão para realizar esta ação.', '🚫'); return; }
    const alvos = linhas.filter(l => l.status === 'pendente');
    if (!alvos.length) { await showAlert('Nenhuma comissão pendente para pagar.', 'ℹ️'); return; }
    const r = await abrirModalPagarComissoes({ titulo, itens: alvos.map(l => ({ descricao: `#${formatPedidoId(l.pedidoId)} — ${l.nome}`, valor: l.valor })) });
    if (!r) return;
    const res = registrarPagamentoComissoes({ itens: alvos.map(l => ({ pedidoId: l.pedidoId, papel: l.papel })), contaId: r.contaId, data: r.data });
    if (!res.ok) { await showAlert(res.erro, '⚠️'); return; }
    salvarERecarregar(res.pagos > 1 ? 'Comissões pagas!' : 'Comissão paga!');
}

function registrarPagamentoComissoesSelecionadas() { return _pagarLinhasComissao(_comSelecionadas(), 'Registrar pagamento'); }

function pagarTodosPendentesComissao(chave) {
    const linhas = _comLinhasVisiveis.filter(l => String(l.vendedorId != null ? l.vendedorId : 'nome:' + l.nome) === chave && l.status === 'pendente');
    const nome = linhas[0] ? linhas[0].nome : '';
    return _pagarLinhasComissao(linhas, `Pagar todos os pendentes de ${nome}`);
}

async function desfazerPagamentoComissaoTela(pedidoId, papel) {
    if (!_permiteGerirComissoes()) { await showAlert('Você não tem permissão para realizar esta ação.', '🚫'); return; }
    if (!await showConfirm('Desfazer este pagamento? A comissão volta a ficar pendente.', '↩', 'Desfazer pagamento', 'Cancelar')) return;
    const res = desfazerPagamentoComissao({ pedidoId, papel });
    if (!res.ok) { await showAlert(res.erro, '⚠️'); return; }
    salvarERecarregar('Pagamento desfeito.');
}

function mostrarTabVendedores(tab) {
    if (_curTabVend !== tab) { _prevTabVend = _curTabVend; _curTabVend = tab; }
    document.querySelectorAll('#tab-vend-lista,#tab-vend-comissoes').forEach(el => el.classList.remove('active'));
    document.querySelectorAll('.vend-tab-btn').forEach(b => b.classList.remove('active'));
    document.getElementById('tab-vend-' + tab)?.classList.add('active');
    document.querySelector(`.vend-tab-btn[data-tab="${tab}"]`)?.classList.add('active');
    _vendLembrarNaUrl('aba', tab);
    if (tab === 'lista')     renderTabelaVendedores();
    if (tab === 'comissoes') renderComissoes();
    document.querySelector('.vend-tipo-nav')?.classList.toggle('vend-oculto', tab === 'comissoes');
    _tabBackBtn('.vend-sub-nav', _prevTabVend, () => mostrarTabVendedores(_prevTabVend));
}

// --- FORNECEDORES ---
// Mascara de maiusculas: converte enquanto digita sem pular o cursor.
function mascaraMaiuscula(el) {
    const ini = el.selectionStart, fim = el.selectionEnd;
    const novo = el.value.toLocaleUpperCase('pt-BR');
    if (novo === el.value) return;
    el.value = novo;
    if (ini != null && document.activeElement === el) el.setSelectionRange(ini, fim);
}

function mascaraCPF(el) {
    let v = el.value.replace(/\D/g, '').slice(0, 11);
    if (v.length > 9)      v = v.replace(/^(\d{3})(\d{3})(\d{3})(\d{0,2})/, '$1.$2.$3-$4');
    else if (v.length > 6) v = v.replace(/^(\d{3})(\d{3})(\d{0,3})/, '$1.$2.$3');
    else if (v.length > 3) v = v.replace(/^(\d{3})(\d{0,3})/, '$1.$2');
    el.value = v;
}

function mascaraCNPJ(el) {
    let v = el.value.replace(/\D/g, '').slice(0, 14);
    if (v.length > 12)     v = v.replace(/^(\d{2})(\d{3})(\d{3})(\d{4})(\d{0,2})/, '$1.$2.$3/$4-$5');
    else if (v.length > 8) v = v.replace(/^(\d{2})(\d{3})(\d{3})(\d{0,4})/,        '$1.$2.$3/$4');
    else if (v.length > 5) v = v.replace(/^(\d{2})(\d{3})(\d{0,3})/,               '$1.$2.$3');
    else if (v.length > 2) v = v.replace(/^(\d{2})(\d{0,3})/,                       '$1.$2');
    el.value = v;
}

// Consulta a mesma base publica usada no cadastro de fornecedor. Devolve o
// par (razao social, estabelecimento) ja decodificado, ou lanca { tipo }.
// Uma implementacao so: a tela de empresa e a de fornecedor consomem esta.
async function consultarCNPJ(digitos) {
    const res = await fetch(`https://publica.cnpj.ws/cnpj/${digitos}`);
    if (!res.ok) throw { tipo: res.status === 404 ? 'nao_encontrado' : 'erro_http' };
    const d = await res.json();
    return { razao_social: d.razao_social || '', est: d.estabelecimento || {} };
}

function _cnpjMensagemDeErro(e) {
    return e && e.tipo === 'nao_encontrado'
        ? '<span style="color:#F43927">❌ CNPJ não encontrado na base de dados.</span>'
        : '<span style="color:#F43927">❌ Erro ao consultar. Verifique sua conexão.</span>';
}

async function buscarCNPJ() {
    const cnpjRaw = document.getElementById('forn-cnpj')?.value.replace(/\D/g, '');
    const statusEl = document.getElementById('forn-cnpj-status');
    const btn = document.getElementById('forn-btn-buscar-cnpj');

    if (!cnpjRaw || cnpjRaw.length !== 14) {
        statusEl.innerHTML = '<span style="color:#F43927">⚠️ Informe um CNPJ válido com 14 dígitos.</span>';
        return;
    }
    statusEl.innerHTML = '<span style="color:#8F8F8F">⏳ Consultando...</span>';
    if (btn) btn.disabled = true;

    try {
        const { razao_social, est } = await consultarCNPJ(cnpjRaw);
        const d = { razao_social };

        const set = (id, val) => { if (!val) return; const el = document.getElementById(id); if (el) el.value = val; };

        set('forn-nome',          d.razao_social || '');
        set('forn-nome-fantasia', est.nome_fantasia || '');

        const logr = [est.tipo_logradouro, est.logradouro].filter(Boolean).join(' ');
        set('forn-end',    logr);
        set('forn-num',    est.numero || '');
        set('forn-cidade', est.cidade?.nome || '');
        set('forn-estado', est.estado?.sigla || '');

        if (est.ddd1 && est.telefone1) set('forn-tel', `(${est.ddd1}) ${est.telefone1}`);
        set('forn-email', est.email || '');

        const ie = est.inscricoes_estaduais?.[0]?.inscricao_estadual;
        if (ie) set('forn-ie', ie);

        statusEl.innerHTML = '<span style="color:var(--primary-text)">✅ Dados preenchidos!</span>';
        setTimeout(() => { statusEl.innerHTML = ''; }, 4000);
    } catch (e) {
        statusEl.innerHTML = _cnpjMensagemDeErro(e);
    } finally {
        if (btn) btn.disabled = false;
    }
}

// ── Empresa: o CNPJ preenche o resto sozinho ────────────────────────────────
// Dispara quando os 14 digitos ficam completos, sem botao. `oninput` dispara a
// cada tecla e tambem quando a mascara reescreve o campo, entao o numero ja
// consultado fica guardado para nao repetir a chamada. Apagar um digito limpa
// essa memoria de proposito: quem apaga esta corrigindo, e a correcao precisa
// poder consultar de novo. Campo ja preenchido a mao nao e' sobrescrito.
let _empCnpjConsultado = '';

async function empresaCnpjMudou(el) {
    mascaraCNPJ(el);
    const digitos = el.value.replace(/\D/g, '');
    const statusEl = document.getElementById('emp-cnpj-status');
    if (digitos.length !== 14) {
        _empCnpjConsultado = '';
        if (statusEl) statusEl.innerHTML = '';
        return;
    }
    if (digitos === _empCnpjConsultado) return;
    _empCnpjConsultado = digitos;

    if (statusEl) statusEl.innerHTML = '<span style="color:#8F8F8F">⏳ Consultando...</span>';
    try {
        const { razao_social, est } = await consultarCNPJ(digitos);
        // So preenche o que estiver vazio: o que voce digitou manda.
        const set = (id, val) => {
            if (!val) return;
            const campo = document.getElementById(id);
            if (campo && !campo.value.trim()) campo.value = val;
        };
        set('emp-razao', String(razao_social || '').toLocaleUpperCase('pt-BR'));
        set('emp-fantasia', String(est.nome_fantasia || '').toLocaleUpperCase('pt-BR'));
        set('emp-end', _empEnderecoCompleto(est));
        set('emp-cidade', est.cidade?.nome || '');
        set('emp-uf', est.estado?.sigla || '');
        if (est.ddd1 && est.telefone1) set('emp-tel', `(${est.ddd1}) ${est.telefone1}`);
        set('emp-email', est.email || '');
        if (statusEl) {
            statusEl.innerHTML = '<span style="color:var(--primary-text)">✅ Dados preenchidos!</span>';
            setTimeout(() => { if (statusEl) statusEl.innerHTML = ''; }, 4000);
        }
    } catch (e) {
        _empCnpjConsultado = '';   // deixa tentar de novo
        if (statusEl) statusEl.innerHTML = _cnpjMensagemDeErro(e);
    }
}

// O formulario da empresa tem um campo unico de endereco; a API devolve em
// partes, entao elas sao juntadas aqui no formato que a tela mostra.
function _empEnderecoCompleto(est) {
    const logr = [est.tipo_logradouro, est.logradouro].filter(Boolean).join(' ');
    const ruaNum = [logr, est.numero].filter(Boolean).join(', ');
    const cidadeUf = [est.cidade?.nome, est.estado?.sigla].filter(Boolean).join(' — ');
    return [ruaNum, est.bairro, cidadeUf, est.cep].filter(Boolean).join(', ');
}

async function salvarFornecedor() {
    const cnpj = document.getElementById('forn-cnpj')?.value.trim() || '';
    const nome = document.getElementById('forn-nome')?.value.trim() || '';
    if (!cnpj) { await showAlert('Informe o CNPJ do fornecedor.', '⚠️'); return; }
    if (!nome) { await showAlert('Informe a Razão Social do fornecedor.', '⚠️'); return; }

    const cnpjNorm = cnpj.replace(/\D/g, '');
    const dupCnpj  = db.fornecedores.find(f => f.cnpj && f.cnpj.replace(/\D/g,'') === cnpjNorm && f.id != editandoIdFornecedor);
    if (dupCnpj) { await showAlert(`CNPJ já cadastrado.\nFornecedor: ${dupCnpj.nome}`, '⚠️'); return; }

    const dados = {
        nome,
        cnpj,
        nome_fantasia: document.getElementById('forn-nome-fantasia')?.value.trim() || '',
        end:    document.getElementById('forn-end')?.value.trim()    || '',
        num:    document.getElementById('forn-num')?.value.trim()    || '',
        cidade: document.getElementById('forn-cidade')?.value.trim() || '',
        estado: document.getElementById('forn-estado')?.value.trim().toUpperCase() || '',
        tel:    document.getElementById('forn-tel')?.value.trim()    || '',
        tel_vendedor: document.getElementById('forn-tel-vendedor')?.value.trim() || '',
        email:  document.getElementById('forn-email')?.value.trim()  || '',
        ie:     document.getElementById('forn-ie')?.value.trim()     || '',
        obs:    document.getElementById('forn-obs')?.value.trim()    || '',
    };

    if (editandoIdFornecedor) {
        const idx = db.fornecedores.findIndex(f => f.id == editandoIdFornecedor);
        if (idx !== -1) db.fornecedores[idx] = { ...db.fornecedores[idx], ...dados };
        cancelarEdicaoFornecedor();
        salvarERecarregar('Fornecedor atualizado!');
    } else {
        db.fornecedores.push({ id: Date.now(), ...dados });
        salvarERecarregar('Fornecedor cadastrado!');
    }
}

function editarFornecedor(id) {
    const f = db.fornecedores.find(x => x.id == id);
    if (!f) return;
    editandoIdFornecedor = id;
    const set = (elId, val) => { const el = document.getElementById(elId); if (el) el.value = val || ''; };
    set('forn-cnpj',         f.cnpj);
    set('forn-nome',         f.nome);
    set('forn-nome-fantasia', f.nome_fantasia);
    set('forn-end',          f.end);
    set('forn-num',          f.num);
    set('forn-cidade',       f.cidade);
    set('forn-estado',       f.estado);
    set('forn-tel',          f.tel);
    set('forn-tel-vendedor', f.tel_vendedor);
    set('forn-email',        f.email);
    set('forn-ie',           f.ie);
    set('forn-obs',          f.obs);
    const tit = document.getElementById('forn-form-titulo');
    const btn = document.getElementById('forn-btn-salvar');
    const cnc = document.getElementById('forn-btn-cancelar');
    if (tit) tit.textContent = 'Editar Fornecedor';
    if (btn) btn.textContent = 'Salvar Alterações';
    if (cnc) cnc.style.display = 'inline-block';
    document.getElementById('forn-nome').focus();
    document.querySelector('.card')?.scrollIntoView({ behavior: 'smooth' });
}

function cancelarEdicaoFornecedor() {
    editandoIdFornecedor = null;
    ['forn-cnpj','forn-nome','forn-nome-fantasia','forn-end','forn-num',
     'forn-cidade','forn-estado','forn-tel','forn-tel-vendedor','forn-email','forn-ie','forn-obs',
     'forn-cnpj-status'].forEach(id => {
        const el = document.getElementById(id);
        if (el) { el.tagName === 'SPAN' ? el.innerHTML = '' : el.value = ''; }
    });
    const tit = document.getElementById('forn-form-titulo');
    const btn = document.getElementById('forn-btn-salvar');
    const cnc = document.getElementById('forn-btn-cancelar');
    if (tit) tit.textContent = 'Cadastrar Fornecedor';
    if (btn) btn.textContent = 'Salvar Fornecedor';
    if (cnc) cnc.style.display = 'none';
}

async function excluirFornecedor(id) {
    const f = db.fornecedores.find(x => x.id == id);
    if (!f) return;
    const matUsando = db.materiais.filter(m => m.fornecedor_id == id);
    const catUsando = db.catalogo.filter(c => c.fornecedor_id == id);
    if (matUsando.length || catUsando.length) {
        await showAlert(`Não é possível excluir: ${escapeHtml(f.nome)} está vinculado a ${matUsando.length} material(is) e ${catUsando.length} tecido(s).`, '🚫');
        return;
    }
    const car = _carrinhoDe(id);
    if (car && CarrinhoCore.contarItens(car) > 0) {
        const nItens = CarrinhoCore.contarItens(car);
        await showAlert(`Este fornecedor tem um carrinho aberto com ${nItens} ${nItens === 1 ? 'item' : 'itens'}. Feche ou esvazie o carrinho antes.`, '🚫');
        return;
    }
    if (!await showConfirm(`Excluir o fornecedor "${f.nome}"?`, '🗑️', 'Excluir', 'Cancelar')) return;
    db.fornecedores = db.fornecedores.filter(x => x.id != id);
    db.carrinhos = db.carrinhos.filter(c => c.fornecedor_id != id);
    salvarERecarregar('Fornecedor excluído.');
}

// --- CARRINHO POR FORNECEDOR (ver, editar, fechar) ---
function _carrinhoDe(fornecedorId) {
    return db.carrinhos.find(c => c.fornecedor_id == fornecedorId) || null;
}

// Quantos carrinhos tem item novo que ninguem viu ainda (o selo "novo").
// E' o numero do botao "Abrir carrinhos" e da bolinha em Fornecedores no menu.
function contarCarrinhosNovos() {
    return (db.carrinhos || []).filter(c => c.novo && CarrinhoCore.contarItens(c) > 0).length;
}

function atualizarContagemCarrinhos() {
    const n = contarCarrinhosNovos();
    document.querySelectorAll('#carrinhos-contagem, #nav-selo-carrinhos').forEach(el => {
        el.textContent = n;
        el.hidden = !n;
    });
    const btn = document.getElementById('btn-abrir-carrinhos');
    if (btn) btn.classList.toggle('com-novo', n > 0);
}

// Janela "Abrir carrinhos": um cartao por fornecedor com carrinho cheio.
function abrirListaCarrinhos() {
    if (!temAcesso('fornecedores', 'visualizar')) return;
    document.getElementById('carrinhos-lista-modal')?.remove();
    const cheios = (db.carrinhos || [])
        .filter(c => CarrinhoCore.contarItens(c) > 0)
        .map(c => ({ c, forn: db.fornecedores.find(f => f.id == c.fornecedor_id) }))
        .filter(x => x.forn)
        .sort((a, b) => (b.c.novo ? 1 : 0) - (a.c.novo ? 1 : 0) || String(a.forn.nome).localeCompare(String(b.forn.nome)));
    const o = document.createElement('div');
    o.id = 'carrinhos-lista-modal';
    o.className = 'sc-modal-overlay';
    o.style.display = 'flex';
    o.innerHTML = `<div class="sc-modal-box" style="text-align:left;max-width:560px;width:95%">
        <h3 style="margin:0 0 12px;font-size:16px">🛒 Carrinhos</h3>
        <div class="carrinhos-lista">${cheios.length ? cheios.map(({ c, forn }) => {
            const n = CarrinhoCore.contarItens(c);
            return `<button type="button" class="carrinhos-lista-item${c.novo ? ' novo' : ''}" onclick="document.getElementById('carrinhos-lista-modal')?.remove(); abrirCarrinho(${forn.id})">
                <span class="carrinhos-lista-nome"><strong>${escapeHtml(forn.nome)}</strong>${c.novo ? '<span class="carrinho-selo-novo">novo</span>' : ''}
                    <small>${n} ${n === 1 ? 'item' : 'itens'}</small></span>
                <span class="carrinhos-lista-total">${_histMoeda(CarrinhoCore.totalCarrinho(c))}</span>
            </button>`;
        }).join('') : `<p style="color:#8F8F8F;font-size:13px;margin:8px 0 4px">Nenhum carrinho com itens. Adicione itens pelo 🛒 no Estoque ou no Catálogo.</p>`}</div>
        <div style="text-align:right;margin-top:12px"><button type="button" class="btn btn-outline btn-sm" onclick="document.getElementById('carrinhos-lista-modal')?.remove()">Fechar</button></div>
    </div>`;
    o.addEventListener('click', e => { if (e.target === o) o.remove(); });
    document.body.appendChild(o);
}

let _carFornId = null;
let _carFechando = false;

function _carPodeEditar() { return temAcesso('fornecedores', 'completo'); }

function abrirCarrinho(fornecedorId) {
    if (!temAcesso('fornecedores', 'visualizar')) return;
    const forn = db.fornecedores.find(f => f.id == fornecedorId);
    if (!forn || document.getElementById('carrinho-modal')) return;
    _carFornId = forn.id;
    const car = _carrinhoDe(forn.id);
    if (car && car.novo) {
        car.novo = false;
        syncDB();
        renderTabelaFornecedores();
        atualizarContagemCarrinhos();
    }
    const o = document.createElement('div');
    o.id = 'carrinho-modal';
    o.className = 'sc-modal-overlay';
    o.style.display = 'flex';
    o.innerHTML = `<div class="sc-modal-box" style="text-align:left;max-width:720px;width:95%">
        <h3 style="margin:0 0 10px;font-size:16px">🛒 Carrinho — ${escapeHtml(forn.nome)}</h3>
        <div id="carrinho-corpo"></div>
    </div>`;
    o.addEventListener('click', e => { if (e.target === o) _carFecharJanela(); });
    document.body.appendChild(o);
    _carRender();
}

function _carFecharJanela() {
    document.getElementById('carrinho-modal')?.remove();
    _carFornId = null;
}
document.addEventListener('keydown', e => {
    if (e.key !== 'Escape') return;
    // o Escape do aviso/confirmacao aberto por cima nao fecha o carrinho junto
    const aviso = document.getElementById('sc-modal-overlay');
    if (aviso && aviso.style.display === 'flex') return;
    _carFecharJanela();
});

function _carRender() {
    const corpo = document.getElementById('carrinho-corpo');
    if (!corpo) return;
    const car = _carrinhoDe(_carFornId) || { itens: [] };
    const edita = _carPodeEditar();
    const vazio = !CarrinhoCore.contarItens(car);
    const th = 'padding:6px';
    const fmtQ = q => String(q).replace('.', ',');
    const linhas = car.itens.map((i, idx) => {
        const sem = !(Number(i.preco_unit) > 0);
        const chave = `'${i.tipo}',${Number(i.item_id)},${escapeHtml(_carJsStr(i.unidade || ''))}`;
        const qtd = edita
            ? `<input type="text" inputmode="decimal" class="car-qtd" value="${fmtQ(i.quantidade)}" style="width:70px;padding:4px;border:1px solid var(--border-strong);border-radius:4px;text-align:right" onchange="_carAlterarQtd(${chave},this.value)"> ${escapeHtml(i.unidade || '')}`
            : `${fmtQ(i.quantidade)} ${escapeHtml(i.unidade || '')}`;
        return `<tr style="border-top:1px solid var(--border)" data-lin="${idx}">
            <td style="${th}"><strong>${escapeHtml(i.item_nome)}</strong>${i.referencia ? `<br><small style="color:#888">${escapeHtml(i.referencia)}</small>` : ''}</td>
            <td style="white-space:nowrap">${qtd}</td>
            <td style="text-align:right">${sem ? '<span style="color:var(--danger-text)">sem preço</span>' : _histMoeda(i.preco_unit)}</td>
            <td class="car-sub" style="text-align:right">${sem ? '—' : _histMoeda(i.subtotal)}</td>
            <td style="text-align:center">${edita ? `<button type="button" class="car-remover btn btn-outline btn-sm" title="Tirar do carrinho" aria-label="Tirar do carrinho" onclick="_carRemover(${chave})">✕</button>` : ''}</td>
        </tr>`;
    }).join('') || `<tr><td colspan="5" style="text-align:center;color:#999;padding:16px">O carrinho está vazio.</td></tr>`; // 5 = colunas da tabela abaixo
    corpo.innerHTML = `<div style="max-height:50vh;overflow:auto;border:1px solid var(--border);border-radius:4px">
            <table style="width:100%;border-collapse:collapse;font-size:13px">
                <thead><tr style="text-align:left;background:var(--surface-3)"><th style="${th}">Item</th><th>Quantidade</th><th style="text-align:right">Preço</th><th style="text-align:right">Subtotal</th><th></th></tr></thead>
                <tbody>${linhas}</tbody>
            </table>
        </div>
        <div class="car-total" style="text-align:right;font-weight:bold;margin:10px 0">Total: ${_histMoeda(CarrinhoCore.totalCarrinho(car))}</div>
        <div style="display:flex;gap:8px;justify-content:flex-end;flex-wrap:wrap">
            ${edita ? `<button type="button" class="btn btn-outline btn-sm" onclick="esvaziarCarrinho(${_carFornId})"${vazio ? ' disabled' : ''}>Esvaziar</button>` : ''}
            <button type="button" class="btn btn-outline btn-sm" onclick="_carFecharJanela()">Voltar</button>
            ${edita ? `<button type="button" class="btn btn-success btn-sm" id="car-fechar-btn" onclick="fecharCarrinho(${_carFornId})"${vazio ? ' disabled' : ''}>Fechar e gerar pedido</button>` : ''}
        </div>`;
}

// Texto como literal JS entre aspas simples (para ir dentro de um onclick).
function _carJsStr(s) { return "'" + String(s).replace(/\\/g, '\\\\').replace(/'/g, "\\'") + "'"; }

// emPlace: so atualiza os numeros na tela, sem refazer a tabela — assim o clique
// no ✕ logo depois de editar a quantidade (o campo perde o foco e salva antes do
// clique) nao cai num botao que acabou de ser trocado.
function _carSalvar(carNovo, emPlace) {
    const i = db.carrinhos.findIndex(c => c.fornecedor_id == carNovo.fornecedor_id);
    carNovo.atualizado_em = Date.now();
    // carrinho sem item nao fica gravado
    if (!CarrinhoCore.contarItens(carNovo)) { if (i >= 0) db.carrinhos.splice(i, 1); }
    else if (i >= 0) db.carrinhos[i] = carNovo; else db.carrinhos.push(carNovo);
    syncDB();
    renderTabelaFornecedores();
    if (emPlace && CarrinhoCore.contarItens(carNovo)) _carAtualizarNumeros(carNovo); else _carRender();
}

function _carAtualizarNumeros(car) {
    document.querySelectorAll('#carrinho-corpo tr[data-lin]').forEach(tr => {
        const i = car.itens[Number(tr.dataset.lin)];
        if (!i) return;
        const campo = tr.querySelector('.car-qtd');
        if (campo && document.activeElement !== campo) campo.value = String(i.quantidade).replace('.', ',');
        const sub = tr.querySelector('.car-sub');
        if (sub) sub.textContent = !(Number(i.preco_unit) > 0) ? '—' : _histMoeda(i.subtotal);
    });
    const tot = document.querySelector('#carrinho-corpo .car-total');
    if (tot) tot.textContent = 'Total: ' + _histMoeda(CarrinhoCore.totalCarrinho(car));
}

function _carAlterarQtd(tipo, itemId, unidade, texto) {
    if (!_carPodeEditar()) return;
    const car = _carrinhoDe(_carFornId);
    if (!car) return;
    // mesma leitura dos valores em R$: "1.000" = mil, "1,5" = 1,5, "1250.5" = 1250,5
    const q = _valorDigitadoBaixa(texto, NaN);
    if (!isFinite(q)) { _carRender(); return; }
    _carSalvar(CarrinhoCore.alterarQuantidade(car, tipo, itemId, q, unidade), q > 0);
}

function _carRemover(tipo, itemId, unidade) {
    if (!_carPodeEditar()) return;
    const car = _carrinhoDe(_carFornId);
    if (!car) return;
    _carSalvar(CarrinhoCore.removerItem(car, tipo, itemId, unidade));
}

async function esvaziarCarrinho(fornecedorId) {
    if (!_carPodeEditar()) return;
    const car = _carrinhoDe(fornecedorId);
    if (!car || !CarrinhoCore.contarItens(car)) return;
    if (!await showConfirm('Esvaziar o carrinho? Todos os itens serão removidos.', '🗑️', 'Esvaziar', 'Cancelar')) return;
    db.carrinhos = db.carrinhos.filter(c => c.fornecedor_id != fornecedorId);
    syncDB();
    _carFecharJanela();
    renderTabelaFornecedores();
}

async function fecharCarrinho(fornecedorId) {
    if (!_carPodeEditar() || _carFechando) return;
    const car = _carrinhoDe(fornecedorId);
    const forn = db.fornecedores.find(f => f.id == fornecedorId);
    if (!car || !forn || !CarrinhoCore.contarItens(car)) return;
    _carFechando = true;
    const btn = document.getElementById('car-fechar-btn');
    if (btn) btn.disabled = true;
    try {
        // todos os itens sem preço: o pedido sairia com R$ 0,00 — pergunta antes
        const semPreco = car.itens.every(i => !(Number(i.preco_unit) > 0));
        const ok = await showConfirm(semPreco
            ? 'Os itens deste carrinho estão sem preço: o pedido sai com valor R$ 0,00. Continuar?'
            : `Fechar o carrinho de ${forn.nome} e gerar o pedido de compra de ${_histMoeda(CarrinhoCore.totalCarrinho(car))}?\n\nO pedido vai para Pedidos de Compra, de onde você envia ao fornecedor.`, '📋', 'Fechar e gerar pedido', 'Cancelar');
        if (!ok) { if (btn) btn.disabled = false; return; }
        const atual = _carrinhoDe(fornecedorId);
        if (!atual || !CarrinhoCore.contarItens(atual)) return;
        const pc = {
            id: gerarNumeroPedidoCompra(),
            data_criacao: Date.now(),
            status: 'Rascunho',
            data_envio: null,
            fornecedor_id: forn.id,
            fornecedor_nome: forn.nome,
            itens: atual.itens.map(i => ({ ...i })),
            observacoes: ''
        };
        db.pedidos_compra.push(pc);
        db.carrinhos = db.carrinhos.filter(c => c.fornecedor_id != fornecedorId);
        syncDB();
        _carFecharJanela();
        renderTabelaFornecedores();
        atualizarContagemCarrinhos();
        mostrarTabFornecedores('pedidos');
        destacarPedidoCompra(pc.id);
        toast(`Pedido #${formatPedidoId(pc.id)} gerado. Envie ao fornecedor pelo botão 📨 Enviar.`, 'success', 4000);
    } finally {
        _carFechando = false;
    }
}

function renderTabelaFornecedores() {
    atualizarContagemCarrinhos();
    const tb = document.getElementById('tb-fornecedores');
    if (!tb) return;
    if (!db.fornecedores.length) {
        tb.innerHTML = '<tr><td colspan="7" style="text-align:center;color:#999;padding:20px;">Nenhum fornecedor cadastrado.</td></tr>';
        return;
    }
    tb.innerHTML = db.fornecedores.map(f => {
        const nMat = db.materiais.filter(m => m.fornecedor_id == f.id).length;
        const nCat = db.catalogo.filter(c => c.fornecedor_id == f.id).length;
        const vinc = [nMat > 0 ? `${nMat} mat.` : '', nCat > 0 ? `${nCat} tec.` : ''].filter(Boolean).join(' · ') || '—';
        const cidadeUF = [f.cidade, f.estado].filter(Boolean).join(' / ') || '—';
        const nomeFantasia = f.nome_fantasia ? `<br><small style="color:#888;font-size:12px">${escapeHtml(f.nome_fantasia)}</small>` : '';
        return `<tr>
            <td><strong>${escapeHtml(f.nome)}</strong>${nomeFantasia}</td>
            <td style="font-size:13px">${escapeHtml(f.cnpj || '—')}</td>
            <td style="font-size:13px">${escapeHtml(cidadeUF)}</td>
            <td style="font-size:13px">${escapeHtml(f.tel || '—')}${f.tel_vendedor ? `<br><small style="color:#888;font-size:12px">Vendedor: ${escapeHtml(f.tel_vendedor)}</small>` : ''}</td>
            <td style="font-size:13px">${escapeHtml(f.email || '—')}</td>
            <td style="font-size:12px;color:var(--text-soft)">${vinc}</td>
            <td class="td-acoes">${menuAcoesHtml([
                { icone: '🛒', rotulo: 'Novo pedido de compra', onclick: `criarPCParaFornecedor(${f.id})` },
                { icone: '📜', rotulo: 'Histórico de pedidos', onclick: `abrirHistoricoFornecedor(${f.id})`, oculto: !temAcesso('fornecedores', 'visualizar') },
                { icone: '✏️', rotulo: 'Editar fornecedor', onclick: `editarFornecedor(${f.id})` },
                { icone: '🗑️', rotulo: 'Excluir fornecedor', onclick: `excluirFornecedor(${f.id})`, perigo: true }
            ])}</td>
        </tr>`;
    }).join('');
}

// --- PEDIDOS DE COMPRA ---
function ultimoPrecoTecido(tecidoId) {
    const c = db.catalogo.find(x => x.id == tecidoId);
    return c?.preco_custo || 0;
}

// Opções do select de fornecedor do pedido de compra. A última, de valor 0,
// é o pedido genérico — sem fornecedor, para mandar a vários como orçamento.
function _pcOpcoesFornecedorHTML(lista) {
    return '<option value="">— Selecione o fornecedor —</option>' +
        lista.map(f => `<option value="${f.id}">${escapeHtml(f.nome)}${f.cnpj ? ' · ' + f.cnpj : ''}</option>`).join('') +
        '<option value="0">— Sem fornecedor (orçamento para vários) —</option>';
}

function filtrarFornecedorPorCNPJ(val) {
    const busca = val.replace(/\D/g, '');
    const sel = document.getElementById('pc-fornecedor');
    if (!sel) return;
    const filtrados = busca
        ? db.fornecedores.filter(f => (f.cnpj || '').replace(/\D/g, '').includes(busca))
        : db.fornecedores;
    sel.innerHTML = _pcOpcoesFornecedorHTML(filtrados);
    if (busca && filtrados.length === 1) sel.value = filtrados[0].id;
}

async function adicionarItemPC() {
    const tipo   = document.getElementById('pc-item-tipo')?.value || 'material';
    const itemId = parseInt(document.getElementById('pc-item-id')?.value);
    const qtd    = parseFloat(document.getElementById('pc-item-qtd')?.value) || 1;
    const obsEl  = document.getElementById('pc-item-obs');
    const observacao = (obsEl?.value || '').trim();
    if (!itemId) { await showAlert('Selecione o item.', '⚠️'); return; }
    if (qtd <= 0) { await showAlert('Informe uma quantidade válida.', '⚠️'); return; }
    let item_nome, unidade, preco_unit;
    let referencia = '';
    if (tipo === 'material') {
        const m = db.materiais.find(x => x.id === itemId);
        if (!m) return;
        item_nome = m.nome; unidade = m.unidade; preco_unit = m.preco_custo || 0; referencia = m.referencia || '';
    } else if (tipo === 'kit') {
        const k = _pcKitsCompraveis().find(x => x.id === itemId);
        if (!k) return;
        item_nome = k.nome; unidade = 'un'; preco_unit = k.preco_custo || 0; referencia = k.referencia || '';
    } else {
        const c = db.catalogo.find(x => x.id === itemId);
        if (!c) return;
        unidade    = document.getElementById('pc-item-unidade')?.value || 'm';
        item_nome  = c.nome;
        preco_unit = ultimoPrecoTecido(itemId);
        referencia = c.referencia || '';
    }
    // O mesmo item com outra observacao (outra cor, outra largura) e' outra linha.
    const chave = `${tipo}|${itemId}|${unidade}|${observacao}`;
    const existing = pcDraftItens.find(i => `${i.tipo}|${i.item_id}|${i.unidade}|${(i.observacao || '').trim()}` === chave);
    if (existing) { existing.quantidade += qtd; existing.subtotal = existing.quantidade * existing.preco_unit; }
    else { pcDraftItens.push({ tipo, item_id: itemId, item_nome, referencia, unidade, quantidade: qtd, preco_unit, subtotal: qtd * preco_unit, observacao }); }
    if (obsEl) obsEl.value = '';
    renderItensPCDraft();
}

// Escolher o item preenche o codigo dele; o campo de codigo continua achando
// o item. Os dois sentidos: antes, escolher um item APAGAVA o codigo.
function preencherCodigoItemPC() {
    const tipo = document.getElementById('pc-item-tipo')?.value || 'material';
    const sel  = document.getElementById('pc-item-id');
    const codigoEl = document.getElementById('pc-item-codigo');
    if (!sel || !codigoEl) return;
    sel.style.borderColor = '';
    const id = parseInt(sel.value);
    const item = id ? _pcListaDoTipo(tipo).find(x => x.id === id) : null;
    codigoEl.value = item ? (item.referencia || '') : '';
}

// Escolher o fornecedor preenche o CNPJ dele; o campo de CNPJ continua
// filtrando a lista. Antes, escolher um fornecedor APAGAVA o CNPJ.
function preencherCNPJFornecedorPC() {
    const sel = document.getElementById('pc-fornecedor');
    const cnpjEl = document.getElementById('pc-busca-cnpj');
    if (!sel || !cnpjEl) return;
    const id = parseInt(sel.value);
    const forn = id ? db.fornecedores.find(f => f.id === id) : null;
    cnpjEl.value = forn ? (forn.cnpj || '') : '';
}

const _PC_ROTULO_TIPO = { tecido: 'Tecido', kit: 'Kit', material: 'Material' };
function _pcRotuloTipo(tipo) { return _PC_ROTULO_TIPO[tipo] || 'Material'; }

function removerItemPC(idx) {
    pcDraftItens.splice(idx, 1);
    renderItensPCDraft();
}

function atualizarQtdPC(idx, val) {
    const qtd = parseFloat(val) || 0;
    if (qtd <= 0) return;
    pcDraftItens[idx].quantidade = qtd;
    pcDraftItens[idx].subtotal   = qtd * pcDraftItens[idx].preco_unit;
    renderItensPCDraft();
}

function atualizarObsItemPC(idx, val) {
    if (pcDraftItens[idx]) pcDraftItens[idx].observacao = String(val || '').trim();
}

function renderItensPCDraft() {
    const tb = document.getElementById('tb-pc-draft');
    if (!tb) return;
    if (!pcDraftItens.length) {
        tb.innerHTML = '<tr><td colspan="6" style="text-align:center;color:#999;padding:12px;font-size:13px">Nenhum item adicionado.</td></tr>';
        return;
    }
    const total = pcDraftItens.reduce((s, i) => s + i.subtotal, 0);
    tb.innerHTML = pcDraftItens.map((i, idx) => {
        const precoLabel = i.preco_unit > 0
            ? `R$ ${i.preco_unit.toFixed(2)}/${i.tipo === 'tecido' ? 'm' : i.unidade}`
            : `<span style="color:#8F8F8F;font-size:12px">sem registro</span>`;
        return `<tr>
            <td>${escapeHtml(i.item_nome)} <span style="font-size:11px;color:#888">(${_pcRotuloTipo(i.tipo)})</span></td>
            <td><input type="text" class="pc-draft-obs" value="${escapeHtml(i.observacao || '')}" placeholder="Observações sobre este item..." onchange="atualizarObsItemPC(${idx},this.value)" aria-label="Observações de ${escapeHtml(i.item_nome)}"></td>
            <td><input type="number" value="${i.quantidade}" step="0.01" min="0.01" style="width:80px;padding:4px 6px;border:1px solid var(--border-strong);border-radius:4px;font-size:13px" onchange="atualizarQtdPC(${idx},this.value)"></td>
            <td>${i.unidade}</td>
            <td>${precoLabel}</td>
            <td><button class="btn btn-outline btn-sm btn-danger" onclick="removerItemPC(${idx})">✕</button></td>
        </tr>`;
    }).join('') + `<tr style="background:var(--surface-2)"><td colspan="4" style="text-align:right;font-weight:bold;color:var(--text-soft);padding:10px 12px">Total estimado:</td><td style="font-weight:bold;padding:10px 12px">${total > 0 ? 'R$ ' + total.toFixed(2) : '<span style="color:#8F8F8F;font-size:12px">—</span>'}</td><td></td></tr>`;
}

// So kit PRONTO entra num pedido de compra: o kit de montagem e' feito aqui
// dentro, a partir dos materiais, e nao e' comprado do fornecedor.
function _pcKitsCompraveis() {
    return db.kits.filter(ehKitPronto);
}

function atualizarSelectItemPC() {
    const tipo = document.getElementById('pc-item-tipo')?.value || 'material';
    const sel  = document.getElementById('pc-item-id');
    const unidadeGroup = document.getElementById('pc-unidade-group');
    const codigoEl = document.getElementById('pc-item-codigo');
    if (!sel) return;
    if (codigoEl) codigoEl.value = '';
    sel.style.borderColor = '';
    if (tipo === 'material') {
        sel.innerHTML = '<option value="">— Selecione o material —</option>' +
            db.materiais.map(m => `<option value="${m.id}">${escapeHtml(m.nome)} (${m.unidade})</option>`).join('');
        if (unidadeGroup) unidadeGroup.style.display = 'none';
    } else if (tipo === 'kit') {
        const kits = _pcKitsCompraveis();
        sel.innerHTML = kits.length
            ? '<option value="">— Selecione o kit —</option>' +
              kits.map(k => `<option value="${k.id}">${escapeHtml(k.nome)}${k.medida ? ' — ' + escapeHtml(k.medida) : ''}</option>`).join('')
            : '<option value="">— Nenhum kit pronto cadastrado —</option>';
        if (unidadeGroup) unidadeGroup.style.display = 'none';
    } else {
        sel.innerHTML = '<option value="">— Selecione o tecido —</option>' +
            db.catalogo.map(c => {
                const ult = ultimoPrecoTecido(c.id);
                const precoRef = ult > 0 ? ` — últ. custo R$ ${ult.toFixed(2)}/m` : '';
                return `<option value="${c.id}">${escapeHtml(c.nome)}${precoRef}</option>`;
            }).join('');
        if (unidadeGroup) unidadeGroup.style.display = '';
    }
}

// A lista de onde cada tipo de item sai. Uma fonte so, para o seletor, a busca
// por codigo e o preenchimento do codigo nao divergirem.
function _pcListaDoTipo(tipo) {
    if (tipo === 'material') return db.materiais;
    if (tipo === 'kit') return _pcKitsCompraveis();
    return db.catalogo;
}

function buscarItemPorCodigoPC(val) {
    const codigo = val.trim().toLowerCase();
    const tipo = document.getElementById('pc-item-tipo')?.value || 'material';
    const sel  = document.getElementById('pc-item-id');
    if (!sel) return;
    if (!codigo) { sel.style.borderColor = ''; return; }
    const encontrado = _pcListaDoTipo(tipo).find(x => (x.referencia || '').toLowerCase() === codigo);
    if (encontrado) {
        sel.value = encontrado.id;
        sel.style.borderColor = '#159912';
        sel.style.transition = 'border-color .3s';
        setTimeout(() => { sel.style.borderColor = ''; sel.style.transition = ''; }, 2000);
    } else {
        sel.value = '';
        sel.style.borderColor = '#F43927';
    }
}

const PC_SEM_FORNECEDOR = 'Orçamento — sem fornecedor definido';

async function salvarPedidoCompra() {
    // "" = nada escolhido; "0" = pedido genérico, de propósito sem fornecedor.
    const bruto = document.getElementById('pc-fornecedor')?.value ?? '';
    if (bruto === '') { await showAlert('Selecione o fornecedor — ou escolha “Sem fornecedor” para um orçamento.', '⚠️'); return; }
    if (!pcDraftItens.length) { await showAlert('Adicione pelo menos um item ao pedido.', '⚠️'); return; }
    const fornId = parseInt(bruto, 10) || 0;
    const forn = db.fornecedores.find(f => f.id === fornId);
    // fornecedor_id/nome do item so servem para agrupar no catalogo.
    const itens = pcDraftItens.map(({ fornecedor_id, fornecedor_nome, ...i }) => i);
    const dados = {
        fornecedor_id:   fornId,
        fornecedor_nome: forn ? forn.nome : (fornId ? '' : PC_SEM_FORNECEDOR),
        itens,
        observacoes:     document.getElementById('pc-obs')?.value.trim() || ''
    };
    // Veio de "Importar de pedido": guarda o pedido de venda de origem.
    const origem = editandoPCId === null ? _pcLerOrigem() : null;
    if (origem) {
        dados.pedido_venda_id = origem.pedido_venda_id;
        const pv = db.pedidos.find(p => p.id == origem.pedido_venda_id);
        dados.pedido_venda_cliente = pv?.clienteNome || origem.cliente || '';
        // Medidas e confeccao de cada ambiente, para o fornecedor. Copia do
        // momento da compra: o documento nao muda se o pedido mudar depois.
        if (pv) dados.especificacoes = _pcEspecificacoesDoPedido(pv);
    }

    if (editandoPCId !== null) {
        const alvo = db.pedidos_compra.find(p => p.id === editandoPCId);
        if (!alvo) { await showAlert('O pedido que você estava editando não existe mais.', '⚠️'); cancelarEdicaoPC(); return; }
        if (pcBloqueado(alvo)) { await showAlert(`O pedido #${formatPedidoId(alvo.id)} está ${alvo.status} e não pode mais ser editado.`, '🔒'); cancelarEdicaoPC(); return; }
        // Rascunho importado: atualiza cliente e especificacoes do pedido de venda.
        if (alvo.pedido_venda_id) {
            const pv = db.pedidos.find(p => p.id == alvo.pedido_venda_id);
            if (pv) { dados.pedido_venda_cliente = pv.clienteNome || alvo.pedido_venda_cliente || ''; dados.especificacoes = _pcEspecificacoesDoPedido(pv); }
        }
        // Numero, data e status sao do pedido, nao do formulario: editar o
        // conteudo nao pode renumerar nem reabrir um pedido ja enviado.
        Object.assign(alvo, dados);
        editandoPCId = null;
        pcDraftItens = [];
        irParaPedidosCompra(`Pedido de compra #${formatPedidoId(alvo.id)} atualizado!`);
        return;
    }

    db.pedidos_compra.push(Object.assign({
        id:           gerarNumeroPedidoCompra(),
        data_criacao: Date.now(),
        status:       'Rascunho',
        data_envio:   null
    }, dados));
    pcDraftItens = [];

    const fila = lerFilaPC();
    if (fila) {
        fila.restantes.shift();
        fila.feitos++;
        if (fila.restantes.length) {
            localStorage.setItem('sc_pc_fila', JSON.stringify(fila));
            salvarERecarregar(`Pedido ${fila.feitos} de ${fila.total} salvo. Agora: ${fila.restantes[0].fornecedor_nome}.`);
        } else {
            // Acabou a fila: leva para a lista, onde os pedidos estão.
            localStorage.removeItem('sc_pc_fila');
            localStorage.removeItem('sc_pc_origem');
            irParaPedidosCompra(`${fila.total} pedidos de compra criados!`);
        }
        return;
    }
    localStorage.removeItem('sc_pc_origem');
    irParaPedidosCompra('Pedido de compra criado!');
}

// Depois de salvar, leva para a aba "Pedidos de Compra", onde o pedido aparece.
function irParaPedidosCompra(msg) {
    syncDB();
    toastReload(msg);
    window.location.href = 'fornecedores.html?tab=pedidos';
}

// Desiste dos pedidos que ainda faltam na fila.
async function cancelarFilaPC() {
    const fila = lerFilaPC();
    if (!fila) return;
    if (!await showConfirm(`Cancelar os ${fila.restantes.length} pedido(s) que ainda faltam? Os ${fila.feitos} já salvos continuam.`, '⚠️', 'Cancelar os restantes', 'Voltar')) return;
    localStorage.removeItem('sc_pc_fila');
    localStorage.removeItem('sc_pc_origem');
    pcDraftItens = [];
    salvarERecarregar('Fila de pedidos cancelada.');
}

// Faixa no topo do formulário indicando em que ponto da fila estamos.
function renderBannerFilaPC() {
    const el = document.getElementById('pc-fila-banner');
    if (!el) return;
    const fila = lerFilaPC();
    if (!fila) { el.style.display = 'none'; el.innerHTML = ''; return; }
    el.style.display = '';
    el.innerHTML = `<span>🛒 <strong>Pedido ${fila.feitos + 1} de ${fila.total}</strong> — ${escapeHtml(fila.restantes[0].fornecedor_nome)} (${fila.restantes[0].itens.length} item(ns)). Salve para ir ao próximo.</span>
        <button class="btn btn-outline btn-sm" onclick="cancelarFilaPC()">Cancelar os restantes</button>`;
}

function renderListaPedidosCompra() {
    const tb = document.getElementById('tb-pedidos-compra');
    if (!tb) return;
    const filtroForn   = document.getElementById('filtro-pc-forn')?.value   || '';
    const filtroStatus = document.getElementById('filtro-pc-status')?.value || '';
    const busca = _buscaNormaliza(document.getElementById('filtro-pc-busca')?.value);
    let lista = [...db.pedidos_compra].sort((a, b) => b.data_criacao - a.data_criacao);
    if (filtroForn)   lista = lista.filter(p => p.fornecedor_id == filtroForn);
    if (filtroStatus) lista = lista.filter(p => p.status === filtroStatus);
    if (busca)        lista = lista.filter(p => _pcCasaBusca(p, busca));
    if (!lista.length) {
        tb.innerHTML = '<tr><td colspan="7" style="text-align:center;color:#999;padding:20px;">Nenhum pedido de compra encontrado.</td></tr>';
        return;
    }
    const COR_PC = { 'Rascunho': 'st-orcamento', 'Enviado': 'st-costura', 'Recebido': 'st-faturado' };
    tb.innerHTML = lista.map(p => {
        const data  = new Date(p.data_criacao).toLocaleDateString('pt-BR');
        const total = p.itens.reduce((s, i) => s + i.subtotal, 0);
        const cls   = COR_PC[p.status] || 'st-orcamento';
        return `<tr data-pc-id="${p.id}">
            <td style="font-size:12px">${pcBloqueado(p)
                ? `<button class="pc-num-btn" onclick="abrirPedidoCompra(${p.id})" title="${escapeHtml(p.status)}: somente leitura">🔒 #${formatPedidoId(p.id)}</button>`
                : `<button class="pc-num-btn" onclick="editarPedidoCompra(${p.id})" title="Abrir para editar ou acrescentar itens">#${formatPedidoId(p.id)}</button>`}</td>
            <td><strong>${escapeHtml(p.fornecedor_nome)}</strong>${p.pedido_venda_id ? `<div class="pc-origem" title="Itens importados do pedido de venda">↳ ${escapeHtml(_pcTextoOrigem(p))}</div>` : ''}</td>
            <td style="font-size:12px;color:#8F8F8F;white-space:nowrap">${data}</td>
            <td style="text-align:center">${p.itens.length}</td>
            <td>R$ ${total.toFixed(2)}</td>
            <td><span class="status-tag ${cls}">${p.status}</span>${p.status === 'Recebido' && !p.conta_pagar_gerada
                ? `<div style="font-size:11px;color:#F43927;margin-top:4px">sem conta a pagar</div>` : ''}</td>
            <td>
                ${p.status === 'Recebido' && !p.conta_pagar_gerada ? `<button class="btn btn-success btn-sm" onclick="gerarContaPagarPCManual(${p.id})" style="margin-right:4px">Gerar conta</button>` : ''}
                ${p.status === 'Rascunho' ? `<button class="btn btn-success btn-sm pc-enviar-btn" onclick="enviarPedidoCompra(${p.id})" style="margin-right:4px">📨 Enviar</button>` : ''}
                <select onchange="atualizarStatusPC(${p.id},this.value)" style="padding:4px 6px;border:1px solid var(--border-strong);border-radius:4px;font-size:12px;margin-right:4px">
                    <option${p.status==='Rascunho'?' selected':''}>Rascunho</option>
                    <option${p.status==='Enviado'?' selected':''}>Enviado</option>
                    <option${p.status==='Recebido'?' selected':''}>Recebido</option>
                </select>
                <button class="btn btn-outline btn-sm" onclick="abrirPedidoCompra(${p.id})" title="Baixar PDF">📄 PDF</button>
                <button class="btn btn-outline btn-sm btn-danger" onclick="excluirPedidoCompra(${p.id})">🗑️</button>
            </td>
        </tr>`;
    }).join('');
}

// Pedido recem-gerado pelo carrinho: destaca a linha na lista por uns segundos.
function destacarPedidoCompra(id) {
    const tr = document.querySelector(`#tb-pedidos-compra tr[data-pc-id="${id}"]`);
    if (!tr) return;
    tr.classList.add('pc-destaque');
    tr.scrollIntoView({ block: 'center', behavior: 'smooth' });
    setTimeout(() => tr.classList.remove('pc-destaque'), 6000);
}

// "📨 Enviar" do pedido em Rascunho: abre o pedido com o menu de envio aberto.
// Depois de enviar, o envio pergunta se marca o pedido como Enviado.
function enviarPedidoCompra(id) {
    abrirPedidoCompra(id);
    const btn = document.getElementById('btn-enviar-doc');
    if (btn && typeof abrirMenuEnviar === 'function') setTimeout(() => abrirMenuEnviar(btn), 50);
}

async function marcarPedidoCompraEnviado(id) {
    const pc = db.pedidos_compra.find(p => p.id == id);
    if (!pc || pc.status !== 'Rascunho') return;
    if (!await showConfirm(`Marcar o pedido #${formatPedidoId(pc.id)} como Enviado?`, '📨', 'Marcar como Enviado', 'Agora não')) return;
    await atualizarStatusPC(pc.id, 'Enviado');
}

// Ao fechar o pedido depois de usar o Enviar: confirma se foi mesmo enviado.
async function perguntarPedidoCompraEnviado(id) {
    const pc = db.pedidos_compra.find(p => p.id == id);
    if (!pc || pc.status !== 'Rascunho') return;
    if (!await showConfirm(`O pedido #${formatPedidoId(pc.id)} foi realmente enviado ao fornecedor?`, '📨', 'Sim, foi enviado', 'Não')) return;
    await atualizarStatusPC(pc.id, 'Enviado');
}

// Enviado ou Recebido: o pedido ja saiu para o fornecedor e nao se edita
// mais. Para corrigir, volta para Rascunho (com confirmacao).
function pcBloqueado(pc) {
    return !!pc && (pc.status === 'Enviado' || pc.status === 'Recebido');
}

// Cliente do pedido de venda de origem: o gravado na compra; nas compras
// antigas, o do pedido de venda.
function _pcClienteOrigem(pc) {
    if (pc.pedido_venda_cliente) return pc.pedido_venda_cliente;
    return db.pedidos.find(p => p.id == pc.pedido_venda_id)?.clienteNome || '';
}
function _pcTextoOrigem(pc) {
    const cli = _pcClienteOrigem(pc);
    return `Pedido #${formatPedidoId(pc.pedido_venda_id)}${cli ? ' — ' + cli : ''}`;
}

// Busca da lista: numero da compra, cliente do pedido de origem ou data
// (dd/mm/aaaa, ou parte dela, como "05/11").
function _pcCasaBusca(pc, termo) {
    const num = termo.replace(/^#/, '');
    if (num && String(pc.id).includes(num)) return true;
    if (pc.pedido_venda_id && _buscaNormaliza(_pcClienteOrigem(pc)).includes(termo)) return true;
    const data = pc.data_criacao ? new Date(pc.data_criacao).toLocaleDateString('pt-BR') : '';
    return !!data && data.includes(termo);
}

async function atualizarStatusPC(id, status) {
    const pc = db.pedidos_compra.find(p => p.id == id);
    if (!pc) return;
    if (pcBloqueado(pc) && status === 'Rascunho'
        && !await showConfirm(`Voltar o pedido #${formatPedidoId(pc.id)} para Rascunho? Ele volta a poder ser editado.`, '↩', 'Voltar para Rascunho', 'Cancelar')) {
        renderListaPedidosCompra();
        return;
    }
    // Pedido que ja foi Recebido antes da entrada automatica existir: tem a conta a pagar,
    // mas nunca passou pela janela de entrada (nem a marca de entrada feita).
    const recebidoAntes = status === 'Recebido' && !!pc.conta_pagar_gerada && !pc.entrada_estoque_data && !pc.entrada_estoque_vista;
    pc.status = status;
    if (status === 'Enviado') pc.data_envio = hojeLocal();
    else if (status === 'Rascunho') pc.data_envio = null;
    syncDB();
    toast('Status atualizado!', 'success', 1500);
    renderListaPedidosCompra();
    // Recebeu a mercadoria: a conta a pagar nasce aqui, uma vez so.
    if (status === 'Recebido' && !pc.conta_pagar_gerada) await abrirModalContaPagarPC(pc);
    // Depois da conta a pagar: a mercadoria que chegou entra no estoque.
    if (status === 'Recebido') await abrirEntradaEstoquePC(pc, { perguntarSeJaLancou: recebidoAntes });
}

// --- ENTRADA NO ESTOQUE AO RECEBER O PEDIDO DE COMPRA ---

// Codigo sugerido para o rolo: o codigo do tecido; se ja existe rolo com ele
// (ou ja existe o "<codigo>-A"), "<codigo>-A", "<codigo>-B"... o primeiro livre.
function _sugerirCodigoRolo(tec, usados) {
    const base = tec.referencia || tec.nome || 'ROLO';
    const jaTem = new Set((db.estoque || []).filter(r => r.tecido_id == tec.id).map(r => String(r.lote || '').toLowerCase()));
    usados.forEach(u => jaTem.add(String(u).toLowerCase()));
    if (!jaTem.has(base.toLowerCase()) && !jaTem.has(`${base}-A`.toLowerCase())) return base;
    for (let n = 0; n < 26 * 26; n++) {
        const letra = n < 26 ? String.fromCharCode(65 + n) : String.fromCharCode(65 + Math.floor(n / 26) - 1) + String.fromCharCode(65 + n % 26);
        if (!jaTem.has(`${base}-${letra}`.toLowerCase())) return `${base}-${letra}`;
    }
    return `${base}-${Date.now()}`;
}

// Monta as linhas da janela a partir dos itens do pedido. Item sem cadastro
// (texto livre ou cadastro apagado) vira linha "sem cadastro"; item sem controle
// de estoque (infinito) vira linha desmarcada e travada: nunca entra.
function _linhasEntradaPC(pc) {
    const usados = [];
    return (pc.itens || []).map((it, idx) => {
        const qtd = Number(it.quantidade) || 0;
        const custo = Number(it.preco_unit) || 0;
        if (it.tipo === 'tecido') {
            const tec = (db.catalogo || []).find(c => c.id == it.item_id);
            if (!tec) return { idx, nome: it.item_nome, semCadastro: true };
            if (temEstoqueInfinito(tec)) return { idx, nome: tec.nome, infinito: true };
            let metros = qtd, custoM = custo;
            if (it.unidade === 'rolo') {
                // Pedido em rolos: a metragem vem do ultimo rolo desse tecido, se houver.
                const ult = (db.estoque || []).filter(r => r.tecido_id == tec.id).sort((a, b) => b.id - a.id)[0];
                metros = ult ? qtd * (ult.metragem_inicial || 0) : 0;
                custoM = metros > 0 ? Math.round(custo * qtd / metros * 100) / 100 : 0;
            }
            const lote = _sugerirCodigoRolo(tec, usados);
            usados.push(lote);
            const margem = tec.preco_custo > 0 && tec.preco > 0 ? Math.round(((tec.preco / tec.preco_custo) - 1) * 100) : '';
            return { idx, tipo: 'tecido', id: tec.id, nome: tec.nome, lote, metros, custo: custoM, margem, unidadePedido: it.unidade };
        }
        if (it.tipo === 'kit') {
            const kit = (db.kits || []).find(k => k.id == it.item_id);
            if (!kit) return { idx, nome: it.item_nome, semCadastro: true };
            if (temEstoqueInfinito(kit)) return { idx, nome: kit.nome, infinito: true };
            return { idx, tipo: 'kit', id: kit.id, nome: kit.nome, qtd, unidade: 'un' };
        }
        const mat = (db.materiais || []).find(m => m.id == it.item_id);
        if (!mat) return { idx, nome: it.item_nome, semCadastro: true };
        if (temEstoqueInfinito(mat)) return { idx, nome: mat.nome, infinito: true };
        const margem = mat.preco_custo > 0 && mat.preco > 0 ? Math.round(((mat.preco / mat.preco_custo) - 1) * 100) : '';
        return { idx, tipo: 'material', id: mat.id, nome: mat.nome, qtd, unidade: mat.unidade || 'un', custo, margem };
    });
}

// Janela "Entrada no estoque — Pedido #N". Resolve quando fecha. "Lançar depois"
// so fecha (o status ja mudou); "Confirmar entrada" grava como a entrada manual.
async function abrirEntradaEstoquePC(pc, { perguntarSeJaLancou = false } = {}) {
    if (pc.entrada_estoque_data) {
        const d = new Date(pc.entrada_estoque_data + 'T12:00:00').toLocaleDateString('pt-BR');
        await showAlert(`A entrada deste pedido já foi feita em ${d}.`, 'ℹ️');
        return;
    }
    const linhas = _linhasEntradaPC(pc);
    if (!linhas.length) return;
    if (!linhas.some(l => !l.semCadastro && !l.infinito)) {
        if (linhas.some(l => l.semCadastro)) await showAlert('Os itens deste pedido não têm cadastro no estoque: lance a entrada à mão no Estoque.', 'ℹ️');
        else await showAlert('Os itens deste pedido não têm controle de estoque: não há entrada a lançar.', 'ℹ️');
        return;
    }
    if (!temAcesso('estoque', 'completo')) {
        await showAlert('O pedido foi marcado como Recebido. A entrada no estoque precisa de alguém com permissão de Estoque.', 'ℹ️');
        return;
    }
    // Pedido Recebido de antes desta janela existir: a entrada pode ja ter sido feita a mao.
    if (perguntarSeJaLancou && await showConfirm('Este pedido já estava como Recebido antes. A entrada no estoque já foi lançada à mão?', '📦', 'Sim, já lancei', 'Não, lançar agora')) {
        pc.entrada_estoque_data = hojeLocal();
        pc.entrada_estoque_manual = true;
        syncDB();
        return;
    }
    // A janela ja abriu para este pedido: daqui em diante ele nao e mais "de antes".
    pc.entrada_estoque_vista = true;
    syncDB({ silencioso: true });
    return new Promise(resolve => {
        if (document.getElementById('pcent-modal')) { resolve(); return; }
        const o = document.createElement('div');
        o.id = 'pcent-modal';
        o.className = 'sc-modal-overlay';
        o.style.display = 'flex';
        const inp = 'padding:5px;border:1px solid var(--border-strong);border-radius:4px;width:100%';
        const campo = (rot, html) => `<div style="flex:1;min-width:90px"><label style="display:block;font-size:11px;color:#8F8F8F;margin-bottom:2px">${rot}</label>${html}</div>`;
        const num = (cls, v, step) => `<input type="number" class="${cls}" step="${step}" min="0" value="${v === '' ? '' : v}" style="${inp}">`;
        const html = linhas.map(l => {
            if (l.semCadastro) {
                return `<div class="pcent-linha pcent-sem" style="padding:8px 0;border-top:1px solid var(--border-strong);font-size:13px;color:#8F8F8F"><strong>${escapeHtml(l.nome || 'Item')}</strong> — sem cadastro — lance à mão</div>`;
            }
            if (l.infinito) {
                return `<div class="pcent-linha pcent-infinito" style="padding:8px 0;border-top:1px solid var(--border-strong);font-size:13px;color:#8F8F8F"><label style="display:flex;gap:8px;align-items:center"><input type="checkbox" class="pcent-marca" disabled><strong>${escapeHtml(l.nome)}</strong> — sem controle de estoque</label></div>`;
            }
            let campos;
            if (l.tipo === 'tecido') {
                campos = campo('Código do rolo', `<input type="text" class="pcent-lote" value="${escapeHtml(l.lote)}" style="${inp}">`)
                    + campo('Metragem (m)', num('pcent-metros', l.metros, '0.01'))
                    + campo('Custo (R$/m)', num('pcent-custo', l.custo, '0.01'))
                    + campo('Margem (%)', num('pcent-margem', l.margem, '1'));
            } else if (l.tipo === 'material') {
                campos = campo(`Quantidade (${escapeHtml(l.unidade)})`, num('pcent-qtd', l.qtd, '0.001'))
                    + campo('Custo (R$)', num('pcent-custo', l.custo, '0.01'))
                    + campo('Margem (%)', num('pcent-margem', l.margem, '1'));
            } else {
                campos = campo('Quantidade (un)', num('pcent-qtd', l.qtd, '1'));
            }
            const rotuloTipo = l.tipo === 'tecido' ? 'Tecido' : l.tipo === 'kit' ? 'Kit pronto' : 'Material';
            return `<div class="pcent-linha" data-idx="${l.idx}" data-tipo="${l.tipo}" data-id="${l.id}" style="padding:8px 0;border-top:1px solid var(--border-strong)">
                <label style="display:flex;gap:8px;align-items:center;font-size:13px;margin-bottom:6px"><input type="checkbox" class="pcent-marca" checked><strong>${escapeHtml(l.nome)}</strong><span style="color:#8F8F8F">(${rotuloTipo})</span></label>
                <div style="display:flex;gap:8px;flex-wrap:wrap">${campos}</div></div>`;
        }).join('');
        o.innerHTML = `<div class="sc-modal-box" style="text-align:left;max-width:640px;max-height:90vh;overflow:auto">
            <h3 style="margin:0 0 4px;font-size:16px">Entrada no estoque — Pedido #${formatPedidoId(pc.id)}</h3>
            <div style="font-size:12px;color:#8F8F8F;margin-bottom:8px">${escapeHtml(pc.fornecedor_nome || '')} · Confira o que chegou e desmarque o que não entra agora.</div>
            <div style="margin-bottom:8px"><label style="font-size:12px;margin-right:6px">Data da entrada</label><input type="date" id="pcent-data" value="${hojeLocal()}" style="padding:4px;border:1px solid var(--border-strong);border-radius:4px"></div>
            ${html}
            <div id="pcent-erro" style="display:none;color:#F43927;font-size:12px;margin:8px 0"></div>
            <div class="sc-modal-btns" style="margin-top:10px"><button class="btn btn-outline" id="pcent-depois">Lançar depois</button><button class="btn btn-success" id="pcent-ok">Confirmar entrada</button></div>
        </div>`;
        document.body.appendChild(o);
        const fechar = () => { document.removeEventListener('keydown', esc); o.remove(); resolve(); };
        const esc = e => {
            const alerta = document.getElementById('sc-modal-overlay');
            if (e.key === 'Escape' && !(alerta && alerta.style.display !== 'none')) fechar();
        };
        document.addEventListener('keydown', esc);
        const erroEl = o.querySelector('#pcent-erro');
        const erro = msg => { erroEl.textContent = msg; erroEl.style.display = ''; };
        o.querySelector('#pcent-depois').onclick = fechar;
        o.querySelector('#pcent-ok').onclick = async () => {
            erroEl.style.display = 'none';
            const data = o.querySelector('#pcent-data').value || hojeLocal();
            const val = (el, c) => parseFloat(el.querySelector(c)?.value);
            const marcadas = [...o.querySelectorAll('.pcent-linha[data-idx]')].filter(el => el.querySelector('.pcent-marca').checked);
            if (!marcadas.length) { erro('Marque pelo menos um item, ou toque em "Lançar depois".'); return; }
            const entradas = [];
            for (const el of marcadas) {
                const tipo = el.dataset.tipo, id = parseInt(el.dataset.id, 10);
                const nome = el.querySelector('strong').textContent;
                const custo = val(el, '.pcent-custo') || 0;
                const margemTxt = el.querySelector('.pcent-margem')?.value;
                const markup = margemTxt === undefined || margemTxt === '' ? null : parseFloat(margemTxt);
                if (tipo === 'tecido') {
                    const lote = el.querySelector('.pcent-lote').value.trim();
                    const metros = val(el, '.pcent-metros');
                    if (!lote) { erro(`Informe o código do rolo de ${nome}.`); return; }
                    if (!metros || metros <= 0) { erro(`Informe a metragem de ${nome}.`); return; }
                    entradas.push({ tipo, id, lote, metros, custo, markup });
                } else {
                    const qtd = val(el, '.pcent-qtd');
                    if (!qtd || qtd <= 0) { erro(`Informe a quantidade de ${nome}.`); return; }
                    entradas.push({ tipo, id, qtd, custo, markup });
                }
            }
            entradas.forEach(e => {
                if (e.tipo === 'tecido') _aplicarEntradaTecido({ tecidoId: e.id, lote: e.lote, metros: e.metros, data, custo: e.custo, markup: e.markup });
                else if (e.tipo === 'material') _aplicarEntradaMaterial({ mat: db.materiais.find(m => m.id === e.id), qtd: e.qtd, data, custo: e.custo, markup: e.markup });
                else _aplicarEntradaKit({ kit: db.kits.find(k => k.id === e.id), qtd: e.qtd, data });
            });
            pc.entrada_estoque_data = data;
            // Sem espaco: nada foi gravado. Avisa e recarrega para a tela mostrar o que esta
            // salvo (a marca de entrada nao fica so na memoria).
            if (!syncDB({ silencioso: true })) {
                fechar();
                await showAlert('A entrada no estoque não foi salva. ' + MSG_SEM_ESPACO, '⚠️');
                window.location.reload();
                return;
            }
            toast('Entrada no estoque registrada!', 'success', 2000);
            fechar();
        };
    });
}

// Total do pedido de compra (soma dos subtotais dos itens).
function _pcTotal(pc) {
    return FinanceiroCore.arredondar((pc.itens || []).reduce((s, i) => s + (Number(i.subtotal) || 0), 0));
}

// Modal "Gerar conta a pagar" do pedido de compra recebido: valor, forma
// (a vista / boleto ou prazo unico / parcelado) e botoes. "Agora nao" so fecha:
// a lista continua avisando e oferecendo "Gerar conta".
function abrirModalContaPagarPC(pc) {
    return new Promise(resolve => {
        if (document.getElementById('pcp-modal')) { resolve(); return; }
        // Sem permissao nem abre a janela: avisa antes (o pedido continua oferecendo "Gerar conta" ao financeiro).
        if (!temAcesso('financeiro.pagar', 'completo')) {
            showAlert('Você não tem permissão para gerar contas a pagar. O pedido fica marcado como "sem conta a pagar" para o financeiro gerar depois.', '🚫').then(() => resolve());
            return;
        }
        const hoje = new Date().toLocaleDateString('sv-SE');
        const o = document.createElement('div');
        o.id = 'pcp-modal';
        o.className = 'sc-modal-overlay';
        o.style.display = 'flex';
        const inp = 'width:100%;padding:7px;border:1px solid var(--border-strong);border-radius:4px;margin-bottom:10px';
        o.innerHTML = `<div class="sc-modal-box" style="text-align:left;max-width:440px">
            <h3 style="margin:0 0 4px;font-size:16px">Gerar conta a pagar</h3>
            <div style="font-size:12px;color:#8F8F8F;margin-bottom:12px">Pedido #${formatPedidoId(pc.id)} — ${escapeHtml(pc.fornecedor_nome || '')}</div>
            <label style="display:block;font-size:12px;margin-bottom:4px">Valor a pagar (R$)</label>
            <input type="number" id="pcp-valor" step="0.01" min="0" value="${_pcTotal(pc).toFixed(2)}" style="${inp}">
            <label style="display:flex;gap:8px;align-items:center;font-size:13px;margin-bottom:6px"><input type="radio" name="pcp-modo" value="avista" checked> À vista (hoje)</label>
            <label style="display:flex;gap:8px;align-items:center;font-size:13px;margin-bottom:6px"><input type="radio" name="pcp-modo" value="prazo"> Boleto ou prazo único</label>
            <div id="pcp-bloco-prazo" style="display:none;margin-left:24px"><label style="display:block;font-size:12px;margin-bottom:4px">Vencimento</label><input type="date" id="pcp-venc" value="${hoje}" style="${inp}"></div>
            <label style="display:flex;gap:8px;align-items:center;font-size:13px;margin-bottom:6px"><input type="radio" name="pcp-modo" value="parcelado"> Parcelado</label>
            <div id="pcp-bloco-parc" style="display:none;margin-left:24px;gap:10px">
                <div style="flex:1"><label style="display:block;font-size:12px;margin-bottom:4px">Nº de parcelas</label><input type="number" id="pcp-parcelas" min="2" max="48" value="2" style="${inp}"></div>
                <div style="flex:1"><label style="display:block;font-size:12px;margin-bottom:4px">A cada (dias)</label><input type="number" id="pcp-intervalo" min="1" value="30" style="${inp}"></div>
            </div>
            <div id="pcp-erro" style="display:none;color:#F43927;font-size:12px;margin-bottom:8px"></div>
            <div class="sc-modal-btns" style="margin-top:8px"><button class="btn btn-outline" id="pcp-agora">Agora não</button><button class="btn btn-success" id="pcp-ok">Gerar conta a pagar</button></div>
        </div>`;
        document.body.appendChild(o);
        const modo = () => o.querySelector('input[name="pcp-modo"]:checked').value;
        const mostrar = () => {
            o.querySelector('#pcp-bloco-prazo').style.display = modo() === 'prazo' ? '' : 'none';
            o.querySelector('#pcp-bloco-parc').style.display = modo() === 'parcelado' ? 'flex' : 'none';
        };
        o.querySelectorAll('input[name="pcp-modo"]').forEach(r => r.addEventListener('change', mostrar));
        const fechar = () => { document.removeEventListener('keydown', esc); o.remove(); resolve(); };
        // Escape com um alerta/confirmacao aberto fecha so o alerta, nao este modal.
        const esc = e => {
            const alerta = document.getElementById('sc-modal-overlay');
            if (e.key === 'Escape' && !(alerta && alerta.style.display !== 'none')) fechar();
        };
        document.addEventListener('keydown', esc);
        const erroEl = o.querySelector('#pcp-erro');
        const erro = msg => { erroEl.textContent = msg; erroEl.style.display = ''; };
        o.querySelector('#pcp-agora').onclick = fechar;
        o.querySelector('#pcp-ok').onclick = () => {
            erroEl.style.display = 'none';
            if (!temAcesso('financeiro.pagar', 'completo')) { erro('Você não tem permissão para gerar contas a pagar. O pedido fica marcado como "sem conta a pagar" para o financeiro gerar depois.'); return; }
            const valor = FinanceiroCore.arredondar(parseFloat(o.querySelector('#pcp-valor').value) || 0);
            const m = modo();
            const venc = o.querySelector('#pcp-venc').value;
            const n = parseInt(o.querySelector('#pcp-parcelas').value, 10) || 0;
            const intervalo = parseInt(o.querySelector('#pcp-intervalo').value, 10) || 30;
            if (valor <= 0) { erro('Informe o valor a pagar.'); return; }
            if (m === 'prazo' && !venc) { erro('Informe a data de vencimento.'); return; }
            if (m === 'parcelado' && n < 2) { erro('Informe 2 ou mais parcelas.'); return; }
            gerarContaPagarPC(pc, { valor, modo: m, hoje, vencimento: venc, numParcelas: n, intervaloDias: intervalo });
            fechar();
        };
    });
}

// Cria a(s) conta(s) a pagar do pedido de compra e marca o pedido como gerado.
function gerarContaPagarPC(pc, opcoes) {
    if (pc.conta_pagar_gerada) return;
    const forn = db.fornecedores.find(f => f.id == pc.fornecedor_id);
    const parcelas = FinanceiroCore.parcelasCompra(opcoes);
    const categoria = (pc.itens || []).some(i => i.tipo === 'tecido') ? 'tecido' : 'outro';
    const usados = new Set((db.contas_pagar || []).map(c => c.id));
    let proximoId = Date.now();
    const novoId = () => { while (usados.has(proximoId)) proximoId++; usados.add(proximoId); return proximoId; };
    const rotulo = `Pedido de compra #${formatPedidoId(pc.id)}`;
    const paiId = parcelas.length > 1 ? novoId() : null;
    // Competencia: a data do pedido de compra.
    const dataCompra = pc.data_criacao ? dataLocal(pc.data_criacao) : null;
    parcelas.forEach(pa => {
        db.contas_pagar.push(finCompletarLancamento('cp', {
            id: novoId(), pedido_id: null, pedido_compra_id: pc.id,
            tipo: 'variavel', categoria,
            descricao: parcelas.length > 1 ? `${rotulo} (parcela ${pa.parcela_atual}/${pa.numero_parcelas})` : rotulo,
            credor_nome: forn?.nome || pc.fornecedor_nome || '',
            cnpj_fornecedor: forn?.cnpj || null,
            ...(forn ? { fornecedor_id: forn.id } : {}),
            valor: pa.valor, data_vencimento: pa.data_vencimento, data_pagamento: null, status: 'Pendente',
            ...(paiId ? { lancamento_pai_id: paiId, parcelado: true, numero_parcelas: pa.numero_parcelas, parcela_atual: pa.parcela_atual } : {})
        }, { origem: 'compra', dataCompra }, `Gerado pelo ${rotulo.charAt(0).toLowerCase() + rotulo.slice(1)}`));
    });
    pc.conta_pagar_gerada = true;
    syncDB();
    toast('Conta a pagar gerada!', 'success', 2000);
    renderListaPedidosCompra();
}

async function gerarContaPagarPCManual(id) {
    const pc = db.pedidos_compra.find(p => p.id == id);
    if (!pc || pc.conta_pagar_gerada) return;
    if (!await exigirPermissao('financeiro.pagar', 'completo')) return;
    await abrirModalContaPagarPC(pc);
}

async function excluirPedidoCompra(id) {
    const contas = (db.contas_pagar || []).filter(c => c.pedido_compra_id != null && c.pedido_compra_id == id);
    if (contas.some(c => c.status === 'Pago')) {
        await showAlert('Este pedido tem conta paga. Estorne o pagamento antes de excluir.', '⚠️');
        return;
    }
    if (contas.length) {
        const n = contas.length;
        const msg = `Excluir o pedido #${formatPedidoId(id)} e ${n === 1 ? 'a conta a pagar dele' : `as ${n} contas a pagar dele`}?`;
        if (!await showConfirm(msg, '🗑️', 'Excluir', 'Cancelar')) return;
        db.contas_pagar = db.contas_pagar.filter(c => !(c.pedido_compra_id != null && c.pedido_compra_id == id));
    } else if (!await showConfirm('Excluir este pedido de compra?', '🗑️', 'Excluir', 'Cancelar')) return;
    db.pedidos_compra = db.pedidos_compra.filter(p => p.id != id);
    salvarERecarregar('Pedido excluído.');
}

// --- HISTORICO DE PEDIDOS DO FORNECEDOR ---
let _histFornId = null;

// Carregador unico do SheetJS (so baixa quando alguem pede uma planilha). Serve ao
// historico do fornecedor (aqui) e ao importador de tabelas (js/importador-ui.js).
// `nomeDoRecurso` so entra na mensagem de erro ("o gerador de planilhas" / "o leitor...").
const _CDN_SHEETJS = 'https://cdn.jsdelivr.net/npm/xlsx@0.18.5/dist/xlsx.full.min.js';
let _sheetJsPronto = null;
async function garantirSheetJs(nomeDoRecurso) {
    if (window.XLSX) return;
    if (!_sheetJsPronto) {
        _sheetJsPronto = new Promise((resolve, reject) => {
            const s = document.createElement('script');
            s.src = _CDN_SHEETJS;
            s.onload = resolve;
            s.onerror = () => { _sheetJsPronto = null; reject(new Error('Não foi possível carregar ' + (nomeDoRecurso || 'o gerador de planilhas') + ' — verifique sua conexão.')); };
            document.head.appendChild(s);
        });
    }
    await _sheetJsPronto;
}
async function _histGarantirSheetJs() { return garantirSheetJs('o gerador de planilhas'); }

function _histMoeda(v) { return 'R$ ' + (Number(v) || 0).toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 }); }
function _histData(iso) { const [a, m, d] = String(iso || '').split('-'); return d ? `${d}/${m}/${a}` : ''; }

function _histFiltro() {
    return {
        de: document.getElementById('hist-forn-de')?.value || '',
        ate: document.getElementById('hist-forn-ate')?.value || ''
    };
}
function _histDados(filtro) {
    return CarrinhoCore.historicoFornecedor(db.pedidos_compra, _histFornId, filtro || _histFiltro());
}

function abrirHistoricoFornecedor(fornecedorId, filtro) {
    if (!temAcesso('fornecedores', 'visualizar')) return;
    const forn = db.fornecedores.find(f => f.id == fornecedorId);
    if (!forn || document.getElementById('hist-forn-modal')) return;
    _histFornId = forn.id;
    const o = document.createElement('div');
    o.id = 'hist-forn-modal';
    o.className = 'sc-modal-overlay';
    o.style.display = 'flex';
    const inp = 'padding:6px;border:1px solid var(--border-strong);border-radius:4px';
    o.innerHTML = `<div class="sc-modal-box" style="text-align:left;max-width:640px;width:95%">
        <h3 style="margin:0 0 10px;font-size:16px">Histórico de pedidos — ${escapeHtml(forn.nome)}</h3>
        <div style="display:flex;gap:12px;flex-wrap:wrap;align-items:flex-end;margin-bottom:10px">
            <label style="font-size:12px">De<br><input type="date" id="hist-forn-de" style="${inp}" oninput="_histRender()"></label>
            <label style="font-size:12px">Até<br><input type="date" id="hist-forn-ate" style="${inp}" oninput="_histRender()"></label>
        </div>
        <div style="max-height:50vh;overflow:auto;border:1px solid var(--border);border-radius:4px">
            <table style="width:100%;border-collapse:collapse;font-size:13px">
                <thead><tr style="text-align:left;background:var(--surface-3)"><th style="padding:6px">Nº</th><th>Data de envio</th><th>Situação</th><th style="text-align:right;padding-right:8px">Valor</th></tr></thead>
                <tbody id="hist-forn-corpo"></tbody>
            </table>
        </div>
        <div id="hist-forn-total" style="text-align:right;font-weight:bold;margin:10px 0"></div>
        <div style="display:flex;gap:8px;justify-content:flex-end;flex-wrap:wrap">
            <button type="button" class="btn btn-outline btn-sm" onclick="exportarHistoricoExcel()">📊 Excel</button>
            <button type="button" class="btn btn-outline btn-sm" onclick="exportarHistoricoPDF()">📄 PDF</button>
            <button type="button" class="btn btn-sm" onclick="fecharHistoricoFornecedor()">Fechar</button>
        </div>
    </div>`;
    o.addEventListener('click', e => { if (e.target === o) fecharHistoricoFornecedor(); });
    document.body.appendChild(o);
    if (filtro) {
        o.querySelector('#hist-forn-de').value = filtro.de || '';
        o.querySelector('#hist-forn-ate').value = filtro.ate || '';
    }
    _histRender();
}

function fecharHistoricoFornecedor() { document.getElementById('hist-forn-modal')?.remove(); }
document.addEventListener('keydown', e => {
    if (e.key !== 'Escape') return;
    // o Escape do aviso/confirmacao aberto por cima nao fecha o historico junto
    const aviso = document.getElementById('sc-modal-overlay');
    if (aviso && aviso.style.display === 'flex') return;
    fecharHistoricoFornecedor();
});

function _histRender() {
    const corpo = document.getElementById('hist-forn-corpo');
    if (!corpo) return;
    const { linhas, total } = _histDados();
    corpo.innerHTML = linhas.length ? linhas.map(l => `<tr style="cursor:pointer;border-top:1px solid var(--border)" onclick="_histAbrirPedido(${l.id})" title="Abrir o pedido">
            <td style="padding:6px">#${formatPedidoId(l.id)}</td><td>${_histData(l.data_envio)}</td><td>${escapeHtml(l.status)}</td>
            <td style="text-align:right;padding-right:8px">${_histMoeda(l.valor)}</td></tr>`).join('')
        : '<tr><td colspan="4" style="text-align:center;color:#999;padding:16px">Nenhum pedido enviado neste período.</td></tr>';
    document.getElementById('hist-forn-total').textContent = 'Total: ' + _histMoeda(total);
}

// Abre o PDF do pedido; ao fechar o PDF volta ao historico com o mesmo filtro.
function _histAbrirPedido(id) {
    const fornId = _histFornId, filtro = _histFiltro();
    fecharHistoricoFornecedor();
    _docAoFecharUmaVez = null;
    try { abrirPedidoCompra(id); } catch (e) { console.error(e); }
    // so arma a volta se o PDF abriu de verdade
    if (document.getElementById('doc-modal-overlay')?.classList.contains('active')) {
        _docAoFecharUmaVez = () => abrirHistoricoFornecedor(fornId, filtro);
    } else {
        abrirHistoricoFornecedor(fornId, filtro);
    }
}

function _histNomeArquivo(forn, filtro) {
    const nome = String(forn.nome || 'fornecedor').trim().replace(/[\\/:*?"<>|]/g, '').replace(/\s+/g, '_');
    return `historico_${nome}_${filtro.de || 'todos'}_${filtro.ate || 'todos'}.xlsx`;
}

async function exportarHistoricoExcel() {
    const forn = db.fornecedores.find(f => f.id == _histFornId);
    if (!forn) return;
    const filtro = _histFiltro();
    const { linhas, total } = _histDados(filtro);
    try { await _histGarantirSheetJs(); } catch (e) { await showAlert(e.message, '⚠️'); return; }
    const aoa = [['Nº', 'Data de envio', 'Situação', 'Valor']]
        .concat(linhas.map(l => [l.id, _histData(l.data_envio), l.status, l.valor]))
        .concat([['Total', '', '', total]]);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, XLSX.utils.aoa_to_sheet(aoa), 'Histórico');
    XLSX.writeFile(wb, _histNomeArquivo(forn, filtro));
}

function exportarHistoricoPDF() {
    const forn = db.fornecedores.find(f => f.id == _histFornId);
    if (!forn) return;
    const filtro = _histFiltro();
    const { linhas, total } = _histDados(filtro);
    const periodo = (!filtro.de && !filtro.ate) ? 'Todo o período'
        : `${filtro.de ? _histData(filtro.de) : 'início'} a ${filtro.ate ? _histData(filtro.ate) : 'hoje'}`;
    const td = 'padding:6px 8px;border-bottom:1px solid #ddd';
    const corpo = linhas.map(l => `<tr><td style="${td}">#${formatPedidoId(l.id)}</td><td style="${td}">${_histData(l.data_envio)}</td><td style="${td}">${escapeHtml(l.status)}</td><td style="${td};text-align:right">${_histMoeda(l.valor)}</td></tr>`).join('')
        || `<tr><td colspan="4" style="${td};text-align:center;color:#999">Nenhum pedido no período.</td></tr>`;
    const html = `<div style="padding:24px">
        <div class="doc-cab">${buildEmpresaHeaderHTML(52)}</div>
        <h2 style="margin:16px 0 4px">Histórico de pedidos de compra</h2>
        <div style="font-size:13px;margin-bottom:2px"><strong>Fornecedor:</strong> ${escapeHtml(forn.nome)}</div>
        <div style="font-size:13px;margin-bottom:12px"><strong>Período:</strong> ${escapeHtml(periodo)}</div>
        <table style="width:100%;border-collapse:collapse;font-size:13px">
            <thead><tr style="text-align:left;background:#f0f0f0"><th style="${td}">Nº</th><th style="${td}">Data de envio</th><th style="${td}">Situação</th><th style="${td};text-align:right">Valor</th></tr></thead>
            <tbody>${corpo}</tbody>
        </table>
        <div style="text-align:right;font-weight:bold;font-size:15px;margin-top:12px">Total: ${_histMoeda(total)}</div>
    </div>`;
    fecharHistoricoFornecedor();
    abrirDocModal(html, 'Histórico de pedidos — ' + forn.nome, '', envioHistoricoFornecedor(forn, periodo));
}

function abrirPedidoCompra(id) {
    abrirDocModal(gerarHTMLPedidoCompra(id), 'Pedido de Compra', '', envioPedidoCompra(id));
}

// Clicar no numero do pedido abre ele no formulario, para corrigir os itens ou
// acrescentar outros. Nenhum status de pedido de compra mexe em estoque, entao
// editar um ja enviado nao desfaz movimento nenhum.
function editarPedidoCompra(id) {
    const pc = db.pedidos_compra.find(p => p.id == id);
    if (!pc) return;
    if (pcBloqueado(pc)) { abrirPedidoCompra(pc.id); return; }
    editandoPCId = pc.id;
    pcDraftItens = (pc.itens || []).map(i => ({ ...i }));

    mostrarTabFornecedores('novo');
    const fornSel = document.getElementById('pc-fornecedor');
    if (fornSel) fornSel.value = String(pc.fornecedor_id || 0);
    preencherCNPJFornecedorPC();
    const obsEl = document.getElementById('pc-obs');
    if (obsEl) obsEl.value = pc.observacoes || '';

    renderItensPCDraft();
    _pcPintarModoEdicao(pc);
    document.getElementById('pc-fornecedor')?.scrollIntoView({ behavior: 'smooth', block: 'center' });
}

function cancelarEdicaoPC() {
    editandoPCId = null;
    pcDraftItens = [];
    const fornSel = document.getElementById('pc-fornecedor');
    if (fornSel) fornSel.value = '';
    const cnpjEl = document.getElementById('pc-busca-cnpj');
    if (cnpjEl) cnpjEl.value = '';
    const obsEl = document.getElementById('pc-obs');
    if (obsEl) obsEl.value = '';
    const obsItemEl = document.getElementById('pc-item-obs');
    if (obsItemEl) obsItemEl.value = '';
    renderItensPCDraft();
    _pcPintarModoEdicao(null);
}

// O formulario e' o mesmo para criar e editar: o titulo e o botao dizem em
// qual dos dois voce esta, senao da' para salvar um pedido achando que esta
// criando outro.
function _pcPintarModoEdicao(pc) {
    const titulo = document.getElementById('pc-form-titulo');
    if (titulo) titulo.textContent = pc
        ? `Editando Pedido de Compra #${formatPedidoId(pc.id)}`
        : 'Novo Pedido de Compra';
    const botao = document.getElementById('pc-btn-salvar');
    if (botao) botao.textContent = pc ? '💾 Salvar Alterações' : '💾 Salvar Pedido';
    const cancelar = document.getElementById('pc-btn-cancelar-edicao');
    if (cancelar) cancelar.style.display = pc ? '' : 'none';
}

function criarPCParaFornecedor(fornId) {
    localStorage.setItem('sc_pc_prefill_forn', fornId);
    mostrarTabFornecedores('novo');
    const pcFornSel = document.getElementById('pc-fornecedor');
    if (pcFornSel) pcFornSel.value = fornId;
}

// ─── Carrinho de compras: adicionar itens ────────────────────────────────
// Exige acesso completo ao Estoque. O item vai para o carrinho do fornecedor
// do cadastro; sem fornecedor, a janela pergunta e a escolha fica gravada no
// cadastro (para nao perguntar de novo). Quantidade na unidade do item.

function podeAdicionarAoCarrinho() { return temAcesso('estoque', 'completo'); }

function botaoAdicionarAoCarrinho(tipo, id) {
    if (!podeAdicionarAoCarrinho()) return '';
    return `<button type="button" class="btn btn-outline btn-sm" onclick="event.stopPropagation();abrirAdicionarAoCarrinho('${tipo}',${Number(id)})" title="Adicionar ao carrinho" aria-label="Adicionar ao carrinho">🛒</button>`;
}

function _cadastroDoCarrinho(tipo, id) {
    return (tipo === 'tecido' ? db.catalogo : db.materiais).find(x => x.id == id) || null;
}
function _unidadeNoCarrinho(tipo, cad) { return tipo === 'tecido' ? 'm' : (cad.unidade || 'un'); }

// "1,5", "2" e "1.000" (milhar) valem — a mesma leitura dos valores digitados
// na baixa. Vazio, zero, negativo ou texto: NaN.
function _quantidadeCarrinho(texto) {
    const q = _valorDigitadoBaixa(texto);
    return Number.isFinite(q) && q > 0 ? q : NaN;
}

function abrirAdicionarAoCarrinho(tipo, id) {
    return _abrirModalCarrinho(tipo, [id], false);
}

function adicionarSelecaoAoCarrinho(tipo) {
    return _abrirModalCarrinho(tipo, [...catSelecao[tipo]], true);
}

let _carAdd = null; // { tipo, cads, daSelecao, resolve } da janela aberta

function _abrirModalCarrinho(tipo, ids, daSelecao) {
    return new Promise(resolve => {
        if (!podeAdicionarAoCarrinho() || document.getElementById('carrinho-add-modal')) { resolve(); return; }
        const cads = ids.map(id => _cadastroDoCarrinho(tipo, id)).filter(Boolean);
        if (!cads.length) { resolve(); return; }
        _carAdd = { tipo, cads, daSelecao, resolve };

        const opcoesForn = db.fornecedores.slice()
            .sort((a, b) => String(a.nome || '').localeCompare(String(b.nome || ''), 'pt-BR'))
            .map(f => `<option value="${escapeHtml(String(f.id))}">${escapeHtml(f.nome || '')}</option>`).join('');
        const inp = 'padding:6px 8px;border:1px solid var(--border-strong);border-radius:4px';
        const linhas = cads.map((c, i) => {
            const forn = _pcFornecedorDoCadastro(c);
            const fornHtml = forn.fornecedor_id
                ? `<span style="font-size:14px">${escapeHtml(forn.fornecedor_nome)}</span>`
                : `<select class="car-add-forn" style="${inp};max-width:100%"><option value="">Escolha o fornecedor…</option>${opcoesForn}</select>`;
            return `<div class="car-add-linha" data-i="${i}" style="padding:10px 0;${i ? 'border-top:1px solid var(--border)' : ''}">
                <div style="font-weight:600">${c.referencia ? `<span style="color:#8F8F8F;font-weight:400">${escapeHtml(c.referencia)}</span> ` : ''}${escapeHtml(c.nome)}</div>
                <div style="display:flex;gap:12px;flex-wrap:wrap;align-items:flex-end;margin-top:6px">
                    <label style="font-size:12px;flex:1 1 180px">Fornecedor<br>${fornHtml}</label>
                    <label style="font-size:12px">Quantidade<br><input type="text" inputmode="decimal" autocomplete="off" class="car-add-qtd" style="${inp};width:110px"> <span class="car-add-un">${escapeHtml(_unidadeNoCarrinho(tipo, c))}</span></label>
                </div>
                <div class="car-add-erro" style="color:var(--danger-text);font-size:12px;margin-top:4px"></div>
            </div>`;
        }).join('');

        const o = document.createElement('div');
        o.id = 'carrinho-add-modal';
        o.className = 'sc-modal-overlay';
        o.style.display = 'flex';
        o.innerHTML = `<div class="sc-modal-box" style="text-align:left;max-width:520px;width:95%">
            <h3 style="margin:0 0 6px;font-size:16px">🛒 Adicionar ao carrinho${cads.length > 1 ? ` — ${cads.length} itens` : ''}</h3>
            <div style="max-height:60vh;overflow:auto">${linhas}</div>
            <div style="display:flex;gap:8px;justify-content:flex-end;margin-top:12px">
                <button type="button" class="btn btn-outline btn-sm" onclick="_fecharModalCarrinho()">Cancelar</button>
                <button type="button" class="btn btn-sm" onclick="_confirmarModalCarrinho()">Adicionar</button>
            </div>
        </div>`;
        o.addEventListener('click', e => { if (e.target === o) _fecharModalCarrinho(); });
        o.addEventListener('keydown', e => {
            if (e.key !== 'Enter' || !e.target.matches('.car-add-qtd, .car-add-forn')) return;
            e.preventDefault();
            _confirmarModalCarrinho();
        });
        document.body.appendChild(o);
        o.querySelector('.car-add-qtd')?.focus();
    });
}

function _fecharModalCarrinho() {
    document.getElementById('carrinho-add-modal')?.remove();
    const pendente = _carAdd;
    _carAdd = null;
    if (pendente) pendente.resolve();
}
document.addEventListener('keydown', e => { if (e.key === 'Escape' && _carAdd) _fecharModalCarrinho(); });

function _confirmarModalCarrinho() {
    const o = document.getElementById('carrinho-add-modal');
    if (!o || !_carAdd) return;
    const { tipo, cads, daSelecao } = _carAdd;
    let primeiroErro = null;
    const lidos = cads.map((c, i) => {
        const linha = o.querySelector(`.car-add-linha[data-i="${i}"]`);
        const campoQtd = linha.querySelector('.car-add-qtd');
        const sel = linha.querySelector('.car-add-forn');
        const erros = [];
        const quantidade = _quantidadeCarrinho(campoQtd.value);
        if (Number.isNaN(quantidade)) erros.push('Informe a quantidade (maior que zero).');
        const forn = sel
            ? db.fornecedores.find(f => String(f.id) === sel.value) || null
            : db.fornecedores.find(f => f.id == c.fornecedor_id) || null;
        if (!forn) erros.push(db.fornecedores.length ? 'Escolha o fornecedor.' : 'Nenhum fornecedor cadastrado — cadastre em Fornecedores.');
        linha.querySelector('.car-add-erro').textContent = erros.join(' ');
        if (erros.length && !primeiroErro) primeiroErro = Number.isNaN(quantidade) ? campoQtd : sel;
        return { c, quantidade, forn, gravarForn: !!sel };
    });
    if (primeiroErro) { primeiroErro.focus?.(); return; }

    let carrinhos = db.carrinhos;
    let mudouCadastro = false;
    lidos.forEach(({ c, quantidade, forn, gravarForn }) => {
        if (gravarForn) { c.fornecedor_id = forn.id; c.fornecedor_nome = forn.nome || ''; mudouCadastro = true; }
        carrinhos = CarrinhoCore.adicionarAoCarrinho(carrinhos, {
            fornecedor_id: forn.id,
            item: {
                tipo, item_id: c.id, item_nome: c.nome, referencia: c.referencia || '',
                unidade: _unidadeNoCarrinho(tipo, c), quantidade, preco_unit: Number(c.preco_custo) || 0
            }
        });
    });
    db.carrinhos = carrinhos;
    syncDB();
    atualizarContagemCarrinhos();

    const nForn = new Set(lidos.map(l => String(l.forn.id))).size;
    const msg = lidos.length === 1
        ? `Adicionado ao carrinho de ${lidos[0].forn.nome}`
        : `${lidos.length} itens adicionados em ${nForn} ${nForn === 1 ? 'carrinho' : 'carrinhos'}`;
    _fecharModalCarrinho();
    if (daSelecao) catSelecao[tipo].clear();
    if (daSelecao || mudouCadastro) _rerenderTabelasDoCarrinho(tipo);
    toast(msg);
}

function _rerenderTabelasDoCarrinho(tipo) {
    if (tipo === 'tecido') {
        renderCatalogoTecidos();
        renderEstoque();
    } else {
        renderMateriais();
        if (document.getElementById('tb-estoque-mat')) renderEstoqueMateriais();
    }
}

// ─── Pedido de compra a partir de um pedido de venda ─────────────────────
// Para quem nao mantem estoque: abre um pedido de cortina em aberto, marca os
// itens que vai comprar (tecidos pelo consumo calculado, materiais e kits
// prontos pela quantidade do pedido) e gera a compra. Itens de fornecedores
// diferentes: um pedido por fornecedor ou um generico com tudo. O pedido de
// compra guarda de qual pedido de venda veio (pedido_venda_id).

// So pedidos antes da producao (Orcamento ou Medicao) entram na importacao:
// de Aguardando Tecido em diante a compra ja foi feita.
const PC_STATUS_IMPORTAVEIS = ['Orçamento', 'Medição'];
function _pcPedidosVendaAbertos() {
    return db.pedidos
        .filter(p => PC_STATUS_IMPORTAVEIS.includes(normalizarStatus(p.status)))
        .sort((a, b) => b.id - a.id);
}

function _pcMetros(n) {
    return n.toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 3 }) + ' m';
}

// Panos de um tecido em cada ambiente: "Sala: 3 panos de 2,75 m".
function _pcTextoPanos(lista) {
    return lista.filter(x => x.num_panos > 0)
        .map(x => `${x.amb ? x.amb + ': ' : ''}${x.num_panos} pano${x.num_panos > 1 ? 's' : ''}${x.alt_corte > 0 ? ' de ' + _pcMetros(x.alt_corte) : ''}`)
        .join('; ');
}

// Medidas e confeccao de cada ambiente do pedido de venda (vai no PDF).
function _pcEspecificacoesDoPedido(ped) {
    return normalizarAmbientes(ped).map((a, i) => ({
        amb: a.amb || `Ambiente ${i + 1}`,
        largura: a.largura || null, altura: a.altura || null,
        abertura: a.abertura || '', acionamento: a.acionamento || '', altura_acionamento: a.altura_acionamento || null,
        tecidos: (a.tecidos || []).filter(t => t.tecidoId).map(t => ({
            tecido_id: t.tecidoId, tecido_nome: t.tecidoNome || db.catalogo.find(c => c.id == t.tecidoId)?.nome || '',
            prega: t.prega || '', fator: t.fator ?? null, num_panos: t.num_panos || 0, alt_corte: t.alt_corte || 0,
        })),
    }));
}

function _pcFornecedorDoCadastro(item) {
    const id = item?.fornecedor_id || null;
    const f = id ? db.fornecedores.find(x => x.id == id) : null;
    return { fornecedor_id: f ? f.id : null, fornecedor_nome: f ? f.nome : '' };
}

// Itens compraveis do pedido de venda, somados por item (o mesmo tecido em
// dois ambientes vira uma linha). Preco = custo, como no formulario manual.
function itensCompraDoPedidoVenda(ped) {
    const linhas = new Map();
    const somar = (chave, base, qtd) => {
        if (!(qtd > 0)) return null;
        const l = linhas.get(chave);
        if (l) { l.quantidade += qtd; return l; }
        const nova = { ...base, quantidade: qtd };
        linhas.set(chave, nova);
        return nova;
    };
    for (const a of normalizarAmbientes(ped)) {
        for (const t of (a.tecidos || [])) {
            if (!t.tecidoId) continue;
            const c = db.catalogo.find(x => x.id == t.tecidoId);
            const linha = somar(`tecido|${t.tecidoId}`, {
                tipo: 'tecido', item_id: c ? c.id : t.tecidoId, item_nome: c?.nome || t.tecidoNome || 'Tecido',
                referencia: c?.referencia || '', unidade: 'm', preco_unit: ultimoPrecoTecido(t.tecidoId),
                ..._pcFornecedorDoCadastro(c),
            }, +t.consumo_linear || 0);
            if (linha) (linha._panos = linha._panos || []).push({ amb: a.amb || '', num_panos: +t.num_panos || 0, alt_corte: +t.alt_corte || 0 });
        }
    }
    for (const i of (ped.itens || [])) {
        if (i.kitId) {
            const k = db.kits.find(x => x.id == i.kitId);
            somar(`kit|${i.kitId}`, {
                tipo: 'kit', item_id: k ? k.id : i.kitId, item_nome: k?.nome || i.nome || 'Kit',
                referencia: k?.referencia || '', unidade: 'un', preco_unit: k?.preco_custo || 0,
                ..._pcFornecedorDoCadastro(k),
            }, +i.quantidade || 0);
            continue;
        }
        const m = db.materiais.find(x => x.id == i.materialId);
        somar(`material|${i.materialId}`, {
            tipo: 'material', item_id: m ? m.id : i.materialId, item_nome: m?.nome || i.nome || 'Material',
            referencia: m?.referencia || '', unidade: m?.unidade || i.unidade || 'un', preco_unit: m?.preco_custo || 0,
            ..._pcFornecedorDoCadastro(m),
        }, +i.quantidade || 0);
    }
    return [...linhas.values()].map(({ _panos, ...l }) => {
        const quantidade = Math.round(l.quantidade * 100) / 100;
        const item = { ...l, quantidade, subtotal: Math.round(quantidade * l.preco_unit * 100) / 100 };
        // Tecido: quantidade e metragem dos panos viram a observacao da linha.
        const panos = _panos ? _pcTextoPanos(_panos) : '';
        if (panos) item.observacao = panos;
        return item;
    });
}

// Pedidos de compra ja feitos para este pedido de venda que trazem o item.
function _pcComprasDoItem(pedId, item) {
    return db.pedidos_compra
        .filter(pc => pc.pedido_venda_id == pedId && (pc.itens || []).some(i => i.tipo === item.tipo && i.item_id == item.item_id))
        .map(pc => pc.id);
}

function _pcEstoqueTexto(item) {
    if (item.tipo === 'tecido') {
        if (tecidoTemEstoqueInfinito(item.item_id)) return '∞';
        return `${estoqueDisponivel(item.item_id).toFixed(2)} m`;
    }
    const alvo = item.tipo === 'kit' ? db.kits.find(k => k.id == item.item_id) : db.materiais.find(m => m.id == item.item_id);
    if (!alvo) return '—';
    if (temEstoqueInfinito(alvo)) return '∞';
    return `${(alvo.estoque_atual || 0).toFixed(2)} ${item.unidade}`;
}

let _pcImport = null;   // { pedId, itens }

function abrirImportarPedidoVenda() {
    _pcImport = null;
    const abertos = _pcPedidosVendaAbertos();
    document.getElementById('pc-import-overlay')?.remove();
    // Filtros so com o que existe nos pedidos em aberto, na ordem do fluxo.
    const status = STATUS_PIPELINE.filter(st => abertos.some(p => normalizarStatus(p.status) === st));
    const vendedores = [...new Set(abertos.map(_pcVendedorDoPedido).filter(Boolean))].sort((x, y) => x.localeCompare(y, 'pt-BR'));
    const overlay = document.createElement('div');
    overlay.className = 'modal-overlay';
    overlay.id = 'pc-import-overlay';
    overlay.innerHTML = `<div class="modal-box pc-import-box">
        <div class="modal-header">
            <h3>Importar itens de um pedido</h3>
            <button class="modal-close" onclick="fecharImportarPedidoVenda()" aria-label="Fechar">×</button>
        </div>
        <div class="modal-body">
            ${abertos.length ? `
            <div id="pc-import-etapa-pedido">
                <div class="pc-import-filtros">
                    <div class="form-group pc-import-f-busca">
                        <label for="pc-import-busca">Buscar</label>
                        <input type="text" id="pc-import-busca" autocomplete="off" placeholder="🔍 Nº do pedido ou cliente..." oninput="renderPedidosVendaImport()">
                    </div>
                    <div class="form-group">
                        <label for="pc-import-f-status">Status</label>
                        <select id="pc-import-f-status" onchange="renderPedidosVendaImport()">
                            <option value="">Todos</option>
                            ${status.map(st => `<option value="${escapeHtml(st)}">${escapeHtml(st)}</option>`).join('')}
                        </select>
                    </div>
                    <div class="form-group">
                        <label for="pc-import-f-vend">Vendedor / arquiteto</label>
                        <select id="pc-import-f-vend" onchange="renderPedidosVendaImport()">
                            <option value="">Todos</option>
                            ${vendedores.map(v => `<option value="${escapeHtml(v)}">${escapeHtml(v)}</option>`).join('')}
                        </select>
                    </div>
                    <div class="form-group">
                        <label for="pc-import-f-entrega">Entrega até</label>
                        <input type="date" id="pc-import-f-entrega" onchange="renderPedidosVendaImport()">
                    </div>
                    <button type="button" class="btn btn-outline pc-import-limpar" onclick="limparFiltrosImport()">✕ Limpar</button>
                </div>
                <div class="pc-import-rolagem"><table class="pc-import-tabela pc-import-pedidos">
                    <thead><tr>
                        <th>Pedido</th><th>Cliente</th><th>Vendedor</th><th>Status</th><th>Entrega</th>
                        <th style="text-align:center">Itens</th><th>Compras feitas</th>
                    </tr></thead>
                    <tbody id="pc-import-pedidos-tb"></tbody>
                </table></div>
            </div>
            <div id="pc-import-etapa-itens" hidden>
                <div class="pc-import-escolhido">
                    <div id="pc-import-escolhido-info"></div>
                    <button type="button" class="btn btn-outline btn-sm" onclick="voltarParaPedidosImport()">← Trocar pedido</button>
                </div>
                <div id="pc-import-itens"></div>
            </div>`
            : `<p class="pc-import-vazio">Nenhum pedido para importar. Só pedidos em Orçamento ou Medição aparecem aqui.</p>`}
        </div>
        <div class="pc-import-rodape">
            <span id="pc-import-resumo"></span>
            <div class="pc-import-botoes">
                <button class="btn btn-outline" onclick="fecharImportarPedidoVenda()">Cancelar</button>
                <button class="btn btn-success" id="pc-import-gerar" onclick="gerarCompraDoPedidoVenda()" disabled>Gerar pedido de compra</button>
            </div>
        </div>
    </div>`;
    document.body.appendChild(overlay);
    overlay.addEventListener('click', e => { if (e.target === overlay) fecharImportarPedidoVenda(); });
    renderPedidosVendaImport();
    document.getElementById('pc-import-busca')?.focus();
}

function _pcVendedorDoPedido(p) {
    return p.vendedor_nome || p.arq_nome || '';
}

function limparFiltrosImport() {
    ['pc-import-busca', 'pc-import-f-status', 'pc-import-f-vend', 'pc-import-f-entrega'].forEach(id => {
        const el = document.getElementById(id);
        if (el) el.value = '';
    });
    renderPedidosVendaImport();
}

function _pcEscolherComTeclado(e, id) {
    if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); selecionarPedidoVendaImport(id); }
}

// Tabela de pedidos em aberto com os filtros aplicados. Clicar na linha
// escolhe o pedido e mostra os itens dele.
function renderPedidosVendaImport() {
    const tb = document.getElementById('pc-import-pedidos-tb');
    if (!tb) return;
    const termo = _buscaNormaliza(document.getElementById('pc-import-busca')?.value);
    const num = termo.replace(/^#/, '');
    const fStatus = document.getElementById('pc-import-f-status')?.value || '';
    const fVend = document.getElementById('pc-import-f-vend')?.value || '';
    const fAte = document.getElementById('pc-import-f-entrega')?.value || '';
    const lista = _pcPedidosVendaAbertos().filter(p => {
        if (termo && !_buscaNormaliza(p.clienteNome).includes(termo) && !String(p.id).includes(num)) return false;
        if (fStatus && normalizarStatus(p.status) !== fStatus) return false;
        if (fVend && _pcVendedorDoPedido(p) !== fVend) return false;
        if (fAte && (!p.data_entrega || p.data_entrega > fAte)) return false;
        return true;
    });
    if (!lista.length) {
        tb.innerHTML = '<tr><td colspan="7" class="pc-import-vazio">Nenhum pedido encontrado com esses filtros.</td></tr>';
        return;
    }
    tb.innerHTML = lista.map(p => {
        const nItens = itensCompraDoPedidoVenda(p).length;
        const compras = db.pedidos_compra.filter(pc => pc.pedido_venda_id == p.id).map(pc => '#' + formatPedidoId(pc.id));
        const st = normalizarStatus(p.status);
        return `<tr class="pc-import-ped" data-ped="${p.id}" tabindex="0" role="button" title="Ver os itens deste pedido"
                    onclick="selecionarPedidoVendaImport(${p.id})" onkeydown="_pcEscolherComTeclado(event, ${p.id})">
            <td class="pc-import-num">#${formatPedidoId(p.id)}</td>
            <td class="pc-import-cli">${escapeHtml(p.clienteNome || 'Sem cliente')}</td>
            <td>${escapeHtml(_pcVendedorDoPedido(p) || '—')}</td>
            <td><span class="status-tag ${COR_STATUS[st] || 'st-orcamento'}">${escapeHtml(st)}</span></td>
            <td class="pc-import-est">${p.data_entrega ? new Date(p.data_entrega + 'T12:00:00').toLocaleDateString('pt-BR') : '—'}</td>
            <td style="text-align:center">${nItens}</td>
            <td class="pc-import-compras">${compras.length ? compras.join(', ') : '—'}</td>
        </tr>`;
    }).join('');
}

function voltarParaPedidosImport() {
    _pcImport = null;
    document.getElementById('pc-import-etapa-itens').hidden = true;
    document.getElementById('pc-import-etapa-pedido').hidden = false;
    _pcImportResumo();
    renderPedidosVendaImport();
}

function fecharImportarPedidoVenda() {
    document.getElementById('pc-import-overlay')?.remove();
    _pcImport = null;
}

function selecionarPedidoVendaImport(id) {
    const ped = db.pedidos.find(p => p.id == id);
    const box = document.getElementById('pc-import-itens');
    if (!box) return;
    if (!ped) { voltarParaPedidosImport(); return; }
    document.getElementById('pc-import-etapa-pedido').hidden = true;
    document.getElementById('pc-import-etapa-itens').hidden = false;
    const st = normalizarStatus(ped.status);
    document.getElementById('pc-import-escolhido-info').innerHTML =
        `<strong>Pedido #${formatPedidoId(ped.id)}</strong> · ${escapeHtml(ped.clienteNome || 'Sem cliente')} <span class="status-tag ${COR_STATUS[st] || 'st-orcamento'}">${escapeHtml(st)}</span>`;
    const itens = itensCompraDoPedidoVenda(ped).map(i => {
        const compras = _pcComprasDoItem(ped.id, i);
        // Item que ja foi comprado para este pedido vem desmarcado.
        return { ...i, marcado: !compras.length, compras };
    });
    _pcImport = { pedId: ped.id, itens };
    if (!itens.length) {
        box.innerHTML = `<p class="pc-import-vazio">Este pedido não tem itens para comprar (tecido com consumo calculado, materiais ou kits).</p>`;
        _pcImportResumo();
        return;
    }
    box.innerHTML = `<div class="pc-import-rolagem"><table class="pc-import-tabela">
        <thead><tr>
            <th style="width:34px"><input type="checkbox" id="pc-import-todos" onchange="marcarTodosImport(this.checked)" aria-label="Marcar todos"></th>
            <th>Código</th><th>Item</th><th>Tipo</th><th>Fornecedor</th><th style="width:130px">Quantidade</th><th>Em estoque</th>
        </tr></thead>
        <tbody>${itens.map((i, n) => `<tr class="${i.marcado ? '' : 'pc-import-off'}" data-n="${n}">
            <td><input type="checkbox" class="pc-import-chk" ${i.marcado ? 'checked' : ''} onchange="marcarItemImport(${n}, this.checked)" aria-label="Comprar ${escapeHtml(i.item_nome)}"></td>
            <td class="pc-import-cod">${escapeHtml(i.referencia || '—')}</td>
            <td>
                <div class="pc-import-nome">${escapeHtml(i.item_nome)}</div>
                ${i.observacao ? `<div class="pc-import-panos">${escapeHtml(i.observacao)}</div>` : ''}
                ${i.compras.length ? `<div class="pc-import-ja">Já comprado para este pedido: ${i.compras.map(c => '#' + formatPedidoId(c)).join(', ')}</div>` : ''}
            </td>
            <td class="pc-import-tipo">${_pcRotuloTipo(i.tipo)}</td>
            <td class="pc-import-forn${i.fornecedor_id ? '' : ' pc-import-semforn'}">${escapeHtml(i.fornecedor_nome || 'Sem fornecedor')}</td>
            <td><div class="pc-import-qtd"><input type="number" value="${i.quantidade}" step="0.01" min="0.01" onchange="qtdItemImport(${n}, this.value)" aria-label="Quantidade de ${escapeHtml(i.item_nome)}"> <span>${escapeHtml(i.unidade)}</span></div></td>
            <td class="pc-import-est">${_pcEstoqueTexto(i)}</td>
        </tr>`).join('')}</tbody>
    </table></div>`;
    _pcImportResumo();
}

function marcarItemImport(n, on) {
    if (!_pcImport?.itens[n]) return;
    _pcImport.itens[n].marcado = !!on;
    const tr = document.querySelector(`.pc-import-tabela tr[data-n="${n}"]`);
    if (tr) {
        tr.classList.toggle('pc-import-off', !on);
        const chk = tr.querySelector('.pc-import-chk');
        if (chk) chk.checked = !!on;
    }
    _pcImportResumo();
}

function marcarTodosImport(on) {
    if (!_pcImport) return;
    _pcImport.itens.forEach((_, n) => marcarItemImport(n, on));
}

function qtdItemImport(n, val) {
    const it = _pcImport?.itens[n];
    if (!it) return;
    const q = parseFloat(val);
    if (q > 0) it.quantidade = q;
}

function _pcImportResumo() {
    const marcados = _pcImport ? _pcImport.itens.filter(i => i.marcado) : [];
    const res = document.getElementById('pc-import-resumo');
    const btn = document.getElementById('pc-import-gerar');
    const todos = document.getElementById('pc-import-todos');
    if (todos && _pcImport) {
        todos.checked = marcados.length === _pcImport.itens.length;
        todos.indeterminate = marcados.length > 0 && marcados.length < _pcImport.itens.length;
    }
    if (btn) btn.disabled = !marcados.length;
    if (!res) return;
    if (!marcados.length) {
        res.textContent = !_pcImport ? 'Clique em um pedido para ver os itens.'
            : _pcImport.itens.length ? 'Nenhum item marcado' : '';
        return;
    }
    const forns = new Set(marcados.map(i => String(i.fornecedor_id || ''))).size;
    res.textContent = `${marcados.length} item(ns) marcado(s) · ${forns} fornecedor(es)`;
}

async function gerarCompraDoPedidoVenda() {
    if (!_pcImport) return;
    const ped = db.pedidos.find(p => p.id == _pcImport.pedId);
    const itens = _pcImport.itens.filter(i => i.marcado)
        .map(({ marcado, compras, ...i }) => ({ ...i, subtotal: Math.round(i.quantidade * i.preco_unit * 100) / 100 }));
    if (!ped || !itens.length) return;
    const origem = { pedido_venda_id: ped.id, cliente: ped.clienteNome || '' };
    // O modal sai da frente para a pergunta aparecer; volta se cancelar.
    const overlay = document.getElementById('pc-import-overlay');
    if (overlay) overlay.style.display = 'none';
    const ok = await iniciarPedidoDeCompra(itens, {
        origem,
        opcoes: ['separados', 'generico'],
        texto: g => `Os ${itens.length} itens marcados do pedido #${formatPedidoId(ped.id)} são de ${g.length} fornecedores diferentes:\n\n${g.map(x => `• ${x.fornecedor_nome}: ${x.itens.length} item(ns)`).join('\n')}\n\nComo você quer gerar a compra?`,
    });
    if (!ok && overlay) overlay.style.display = '';
}

// Origem (pedido de venda) do pedido de compra em montagem. Sobrevive as
// recargas da fila; sai quando a fila termina ou e' cancelada.
function _pcLerOrigem() {
    try { return JSON.parse(localStorage.getItem('sc_pc_origem') || 'null'); } catch { return null; }
}
function _pcObsDaOrigem(o) {
    return o ? `Compra para o pedido #${formatPedidoId(o.pedido_venda_id)}${o.cliente ? ' — ' + o.cliente : ''}` : '';
}

function mostrarTabFornecedores(tab) {
    if (_curTabForn !== tab) { _prevTabForn = _curTabForn; _curTabForn = tab; }
    document.querySelectorAll('#tab-forn-lista,#tab-forn-pedidos,#tab-forn-novo').forEach(el => el.classList.remove('active'));
    document.querySelectorAll('.forn-tab-btn').forEach(b => b.classList.remove('active'));
    document.getElementById('tab-forn-' + tab)?.classList.add('active');
    document.querySelector(`.forn-tab-btn[data-tab="${tab}"]`)?.classList.add('active');
    if (tab === 'lista')   renderTabelaFornecedores();
    if (tab === 'pedidos') renderListaPedidosCompra();
    if (tab === 'novo')    atualizarSelectItemPC();
    _tabBackBtn('.tab-nav', _prevTabForn, () => mostrarTabFornecedores(_prevTabForn));
}

// --- PEDIDO DE COMPRA (documento imprimível) ---
function gerarHTMLPedidoCompra(id, layout) {
    const pc = db.pedidos_compra.find(p => p.id == id);
    if (!pc) return '<p style="text-align:center;color:#999;padding:40px;">Pedido não encontrado.</p>';
    return _htmlPedidoCompra(pc, db.fornecedores.find(f => f.id == pc.fornecedor_id), layout);
}

function _htmlPedidoCompra(pc, forn, layout) {
    layout = layout || getLayoutDocumento('compra');
    const hoje  = new Date().toLocaleDateString('pt-BR');
    const total = pc.itens.reduce((s, i) => s + i.subtotal, 0);
    const valores = Object.assign(valoresComunsEmpresa(), {
        fornecedor: forn ? forn.nome : (pc.fornecedor_nome || ''),
        numero: formatPedidoId(pc.id), data_emissao: hoje, total: 'R$ ' + total.toFixed(2),
        cliente_origem: pc.pedido_venda_id ? (_pcClienteOrigem(pc) || '') : '',
        pedido_venda: pc.pedido_venda_id ? '#' + formatPedidoId(pc.pedido_venda_id) : '',
        origem: pc.pedido_venda_id ? _pcTextoOrigem(pc) : ''
    });
    const tit = id => textoDoc(blocoDoLayout(layout, id).titulo, valores);
    const linhas = pc.itens.map(i => {
        let ref = i.referencia || '';
        if (!ref && i.item_id) {
            ref = _pcListaDoTipo(i.tipo).find(x => x.id == i.item_id)?.referencia || '';
        }
        return `<tr>
        <td style="font-size:12px;color:#555;white-space:nowrap">${ref ? escapeHtml(ref) : '<span style="color:#ccc">—</span>'}</td>
        <td>${escapeHtml(i.item_nome)}${i.observacao ? `<div class="pc-item-obs">Obs.: ${escapeHtml(i.observacao)}</div>` : ''}</td>
        <td style="text-align:center">${_pcRotuloTipo(i.tipo)}</td>
        <td style="text-align:right">${i.quantidade}</td>
        <td>${i.unidade}</td>
        <td style="text-align:right">R$ ${i.preco_unit.toFixed(2)}</td>
        <td style="text-align:right"><strong>R$ ${i.subtotal.toFixed(2)}</strong></td>
    </tr>`;
    }).join('');
    const assin = legendasAssinaturas(blocoDoLayout(layout, 'assinaturas'), 'compra');
    const blocos = {
        cabecalho: `
        <div class="pc-header doc-cab">
            ${buildEmpresaHeaderHTML(52)}
            <div style="text-align:right">
                <div style="font-size:20px;font-weight:bold;color:var(--dark)">${textoDoc(layout.titulo, valores)}</div>
                <div style="font-size:13px;color:#888">Nº ${formatPedidoId(pc.id)} · Emitido em ${hoje}</div>
                <div style="margin-top:4px"><span class="status-tag ${pc.status==='Recebido'?'st-faturado':pc.status==='Enviado'?'st-costura':'st-orcamento'}">${pc.status}</span></div>
            </div>
        </div>`,
        cliente: pc.pedido_venda_id ? `<div class="pc-section pc-cliente">
            <div class="pc-section-title">${tit('cliente')}</div>
            <table class="pc-table">
                <tr><td class="pc-th">Cliente</td><td><strong>${escapeHtml(_pcClienteOrigem(pc) || '—')}</strong></td><td class="pc-th" style="width:130px">Pedido de venda</td><td>#${escapeHtml(String(formatPedidoId(pc.pedido_venda_id)))}</td></tr>
            </table>
        </div>` : '',
        fornecedor: `
        <div class="pc-section">
            <div class="pc-section-title">${tit('fornecedor')}</div>
            ${pc.fornecedor_id ? `<table class="pc-table">
                <tr><td class="pc-th">Razão Social / Nome</td><td><strong>${forn ? escapeHtml(forn.nome) : escapeHtml(pc.fornecedor_nome)}</strong></td><td class="pc-th" style="width:100px">CNPJ</td><td>${forn ? escapeHtml(forn.cnpj || '—') : '—'}</td></tr>
                <tr><td class="pc-th">Telefone</td><td>${forn ? escapeHtml(forn.tel || '—') : '—'}</td><td class="pc-th">E-mail</td><td>${forn ? escapeHtml(forn.email || '—') : '—'}</td></tr>
                ${forn?.end ? `<tr><td class="pc-th">Endereço</td><td colspan="3">${escapeHtml(forn.end)}</td></tr>` : ''}
            </table>` : `<table class="pc-table">
                <tr><td class="pc-th">Razão Social / Nome</td><td colspan="3" style="height:26px"></td></tr>
                <tr><td class="pc-th">Telefone</td><td style="height:26px"></td><td class="pc-th" style="width:100px">E-mail</td><td></td></tr>
            </table>
            <div style="font-size:11px;color:#888;margin-top:5px">Solicitação de orçamento — preencher os dados do fornecedor.</div>`}
        </div>`,
        itens: `
        <div class="pc-section">
            <div class="pc-section-title">${tit('itens')}</div>
            <table class="pc-table">
                <thead><tr><th style="width:100px">Código</th><th>Descrição</th><th style="text-align:center">Tipo</th><th style="text-align:right;width:80px">Qtd</th><th style="width:50px">Un.</th><th style="text-align:right;width:100px">R$/Un.</th><th style="text-align:right;width:110px">Subtotal</th></tr></thead>
                <tbody>${linhas}</tbody>
                <tfoot><tr style="background:#FAFAFA"><td colspan="6" style="text-align:right;font-weight:bold;padding:10px 8px;color:#242424">Total Estimado:</td><td style="text-align:right;font-weight:bold;padding:10px 8px">R$ ${total.toFixed(2)}</td></tr></tfoot>
            </table>
        </div>`,
        especificacoes: _pcEspecificacoesHTML(pc, tit('especificacoes')),
        observacoes: pc.observacoes ? `<div class="pc-section"><div class="pc-section-title">${tit('observacoes')}</div><div style="padding:10px 14px;border:1px solid #E0E0E0;border-radius:4px;font-size:14px;min-height:50px">${escapeHtml(pc.observacoes)}</div></div>` : '',
        assinaturas: `
        <div class="pc-assinaturas">
            ${assin.map(a => `<div><div class="pc-section-title">${textoDoc(a.titulo, valores)}</div><div class="pc-linha"></div><small>${textoDoc(a.legenda, valores)}</small></div>`).join('')}
        </div>`
    };
    return montarDocumentoLayout('compra', layout, blocos, valores);
}

// Especificacoes dos ambientes do pedido de venda de origem: medidas da
// parede, abertura, acionamento e, por tecido, prega, fator e panos. Com
// tecido no pedido de compra, mostra so os tecidos que estao nele.
function _pcEspecificacoesHTML(pc, tituloHtml) {
    if (!pc.pedido_venda_id) return '';
    let specs = pc.especificacoes;
    if (!specs) {
        const pv = db.pedidos.find(p => p.id == pc.pedido_venda_id);
        specs = pv ? _pcEspecificacoesDoPedido(pv) : [];
    }
    const tecidosDaCompra = new Set((pc.itens || []).filter(i => i.tipo === 'tecido').map(i => String(i.item_id)));
    const filtrar = tecidosDaCompra.size > 0;
    const m = v => v > 0 ? _pcMetros(Math.round(v * 1000) / 1000) : '—';
    const linhas = [];
    for (const a of specs) {
        const tecidos = filtrar ? a.tecidos.filter(t => tecidosDaCompra.has(String(t.tecido_id))) : a.tecidos;
        if (filtrar && !tecidos.length) continue;
        const base = `<td><strong>${escapeHtml(a.amb)}</strong></td>
            <td style="white-space:nowrap">${m(a.largura)} × ${m(a.altura)}</td>
            <td>${escapeHtml(a.abertura ? rotuloAbertura(a.abertura) : '—')}</td>
            <td>${escapeHtml(textoAcionamento(a))}</td>`;
        if (!tecidos.length) { linhas.push(`<tr>${base}<td colspan="4" style="color:#999">—</td></tr>`); continue; }
        for (const t of tecidos) linhas.push(`<tr>${base}
            <td>${escapeHtml(t.tecido_nome || '—')}</td>
            <td>${escapeHtml(t.prega || '—')}</td>
            <td style="text-align:center">${t.fator ? t.fator + 'x' : '—'}</td>
            <td style="white-space:nowrap">${t.num_panos > 0 ? t.num_panos + (t.alt_corte > 0 ? ' × ' + m(t.alt_corte) : '') : '—'}</td>
        </tr>`);
    }
    if (!linhas.length) return '';
    return `<div class="pc-section pc-especificacoes">
        <div class="pc-section-title">${tituloHtml != null ? tituloHtml : 'Especificações — ' + escapeHtml(_pcTextoOrigem(pc))}</div>
        <table class="pc-table">
            <thead><tr><th>Ambiente</th><th>Parede (L × A)</th><th>Abertura</th><th>Acionamento</th><th>Tecido</th><th>Prega</th><th style="text-align:center">Fator</th><th>Panos</th></tr></thead>
            <tbody>${linhas.join('')}</tbody>
        </table>
    </div>`;
}

function renderPedidoCompraDoc() {
    const container = document.getElementById('pedido-compra-container');
    if (!container) return;
    container.innerHTML = gerarHTMLPedidoCompra(localStorage.getItem('sc_pc_id'));
    if (typeof definirEnvioDoc === 'function') definirEnvioDoc(envioPedidoCompra(localStorage.getItem('sc_pc_id')));
    setTimeout(() => esperarFontesDocumento().then(() => window.print()), 500);
}

// --- AGENDA DE INSTALAÇÕES ---
// =============================================
// MÓDULO MEDIÇÕES
// =============================================

function toggleTipoClienteMedicao() {
    const tipo = document.querySelector('input[name="med-tipo"]:checked')?.value || 'existente';
    document.getElementById('med-grupo-existente').style.display = tipo === 'existente' ? '' : 'none';
    document.getElementById('med-grupo-novo').style.display      = tipo === 'novo'      ? '' : 'none';
}

function onMedClienteChange() {
    const sel = document.getElementById('med-cliente-id');
    if (!sel || !sel.value) return;
    const cli = db.clientes.find(c => c.id == sel.value);
    if (!cli || !(cli.end || cli.rua)) return;   // cliente sem endereco nao apaga o que ja foi digitado
    enderecoPreencher('med', _partesDoCliente(cli));
}

// Partes do endereco do cliente; cliente antigo (sem "rua") vira Rua = texto antigo inteiro.
function _partesDoCliente(cli) {
    if (!cli) return EnderecoCore.partesDeRegistroAntigo('', '');
    return cli.rua === undefined ? EnderecoCore.partesDeRegistroAntigo(cli.end, cli.cidade) : cli;
}
// Monta os campos de endereco das telas de agendamento (medicao e instalacao).
function _agdMontarEnderecosMed() {
    const m = document.getElementById('med-end-campos');
    if (m && !document.getElementById('med-rua')) { m.innerHTML = enderecoCamposHtml('med', { obrigRua: true, ir: true }); enderecoAnexar('med'); }
}
function _agdMontarEnderecosInst() {
    const i = document.getElementById('inst-end-campos');
    if (i && !document.getElementById('inst-rua')) { i.innerHTML = enderecoCamposHtml('inst', { obrigRua: false, ir: true }); enderecoAnexar('inst'); }
}

// Pedido ligado ao agendamento de medicao. O vinculo vale nos dois sentidos
// (medicao.pedido_id e pedido.medicao_id); um pedido excluido desfaz o vinculo.
function _medPedidoVinculado(m) {
    if (!m) return null;
    return (m.pedido_id && db.pedidos.find(p => p.id == m.pedido_id))
        || db.pedidos.find(p => p.medicao_id != null && p.medicao_id == m.id)
        || null;
}

// Abre o fluxo de pedido com o cliente preenchido. Se o agendamento ja tem
// pedido, abre esse pedido para edicao em vez de criar outro.
async function criarPedidoDaMedicao(medicaoId) {
    const m = (db.medicoes || []).find(x => x.id == medicaoId);
    if (!m) return;
    const ped = _medPedidoVinculado(m);
    if (ped) { editarPedido(ped.id); return; }
    if (!await exigirPermissao('pedidos', 'completo')) return;
    localStorage.removeItem('sc_editando_id');
    localStorage.setItem('sc_novo_pedido_pre', JSON.stringify({
        clienteId:   m.clienteId   || null,
        clienteNome: m.clienteNome || '',
        medicaoId:   m.id,
    }));
    window.location.href = 'pedido.html';
}

// Chamado ao salvar um pedido novo vindo de "Criar Pedido": liga os dois e,
// se a visita ainda estava agendada, ela passa para Realizados sozinha.
function _medVincularPedido(m, ped) {
    m.pedido_id = ped.id;
    ped.medicao_id = m.id;
    if (!m.historico) m.historico = [];
    _agdRegistrar(m.historico, 'pedido', { pedido: ped.id });
    if (m.status === 'Agendado') {
        m.status = 'Realizado';
        m.realizado_em  = Date.now();
        m.realizado_por = getUsuarioLogado()?.id || null;
        m.realizado_via = 'pedido';
    }
}

// Um salvamento por vez: a conferencia de deslocamento demora (rede) e um 2o clique
// nao pode gravar de novo.
let _agdSalvando = false;
async function _agdSemDuplo(fn) {
    if (_agdSalvando) return;
    _agdSalvando = true;
    try { return await fn(); } finally { _agdSalvando = false; }
}

function salvarMedicao() { return _agdSemDuplo(_salvarMedicao); }
async function _salvarMedicao() {
    const tipo = document.querySelector('input[name="med-tipo"]:checked')?.value || 'existente';
    let clienteId = null, clienteNome = '', clienteTel = '';
    let clienteCpf = '', clienteEmail = '';

    if (tipo === 'existente') {
        clienteId = parseInt(document.getElementById('med-cliente-id')?.value) || null;
        if (!clienteId) { await showAlert('Selecione o cliente.', '⚠️'); return; }
        const cli = db.clientes.find(c => c.id == clienteId);
        if (cli) {
            clienteNome = cli.nome;
            clienteTel  = cli.tel || '';
            if (!enderecoLer('med').rua && cli.end) enderecoPreencher('med', _partesDoCliente(cli));
        }
    } else {
        clienteNome  = (document.getElementById('med-novo-nome')?.value || '').trim();
        clienteTel   = (document.getElementById('med-novo-tel')?.value || '').trim();
        clienteCpf   = (document.getElementById('med-novo-cpf')?.value || '').trim();
        clienteEmail = (document.getElementById('med-novo-email')?.value || '').trim();
        if (!clienteNome) { await showAlert('Informe o nome do cliente.', '⚠️'); return; }
        if (clienteCpf) {
            const cpfDigitos = clienteCpf.replace(/\D/g, '');
            const duplicado = db.clientes.find(c => c.cpf && c.cpf.replace(/\D/g, '') === cpfDigitos);
            if (duplicado) { await showAlert(`CPF já cadastrado para o cliente "${duplicado.nome}".`, '⚠️'); return; }
        }
    }

    const data = (document.getElementById('med-data')?.value || '').trim();
    const hora = (document.getElementById('med-hora')?.value || '').trim();
    const partes = enderecoLer('med');
    const end  = EnderecoCore.textoEndereco(partes);
    const cidade = partes.cidade;
    const obs  = (document.getElementById('med-obs')?.value  || '').trim();
    const dur  = parseInt(document.getElementById('med-dur')?.value) || _agdDurPadrao('med');
    const prof = _agdLerProf('med-prof');
    if (!data) { await showAlert('Informe a data da visita.', '⚠️'); return; }
    if (!partes.rua) { await showAlert('Informe o endereço da visita.', '⚠️'); return; }

    // Com profissional definido a visita ocupa a agenda dele: precisa de
    // horário e é conferida de novo contra instalações e medições já gravadas.
    if (prof.chave && !hora) {
        document.getElementById('med-hora')?.classList.add('agd-erro');
        await showAlert('Informe o horário: ele reserva a agenda do profissional.', '⚠️');
        return;
    }
    document.getElementById('med-hora')?.classList.remove('agd-erro');
    if (!await _agdValidarDisp({ prof: prof.chave, profNome: prof.pessoa.nome, data, hora, dur, partes })) { _medAtualizarDisp(); return; }

    // Só depois de tudo validado o novo cliente é cadastrado.
    if (tipo === 'novo') {
        const novoCli = { id: Date.now(), nome: clienteNome, tel: clienteTel, email: clienteEmail, cpf: clienteCpf, ...partes, end };
        db.clientes.push(novoCli);
        clienteId = novoCli.id;
        const sel = document.getElementById('med-cliente-id');
        if (sel) sel.innerHTML = '<option value="">— Selecione —</option>' +
            db.clientes.map(c => `<option value="${c.id}">${escapeHtml(c.nome)}</option>`).join('');
    }

    const med = { id: Date.now(), clienteId, clienteNome, clienteTel, ...partes, endereco: end, data, hora, duracao: dur, obs, status: 'Agendado',
        agendado_por: getUsuarioLogado()?.id || null, agendado_em: Date.now() };
    _medDefinirResponsavel(med, prof.pessoa);
    _aceiteAplicar(med, 'aceite', null, med.usuario_id, data, hora);
    db.medicoes.push(med);

    const nomeEl  = document.getElementById('med-novo-nome');  if (nomeEl)  nomeEl.value  = '';
    const telEl   = document.getElementById('med-novo-tel');   if (telEl)   telEl.value   = '';
    const cpfEl   = document.getElementById('med-novo-cpf');   if (cpfEl)   cpfEl.value   = '';
    const emailEl = document.getElementById('med-novo-email'); if (emailEl) emailEl.value = '';
    document.getElementById('med-data').value = _agdHoje();
    _agdPickerFechar();
    document.getElementById('med-hora').value = '';
    enderecoPreencher('med', {});
    document.getElementById('med-obs').value  = '';
    _agdPreencherProf('med-prof', '', '— A definir —');
    _agdPreencherDur('med-dur', 'med');
    document.querySelectorAll('input[name="med-tipo"]').forEach(r => { r.checked = r.value === 'existente'; });
    toggleTipoClienteMedicao();

    syncDB();
    toast(_agdNotaDesloc(tipo === 'novo' ? 'Cliente cadastrado e visita agendada!' : 'Visita agendada!'), 'success');
    renderMedicoes();
    renderDashboardMedicoes();
    renderAgenda();
}

function imprimirAgendamentoMedicao(id) {
    const v = db.medicoes.find(x => x.id == id);
    if (!v) return;
    abrirDocModal(gerarHTMLAgendamentoMedicao(v), 'Agendamento de Medição', '', envioAgendamentoMedicao(v));
}

// Pares rotulo/valor de um bloco de dados, nas tres arrumacoes do layout:
// lista (tabela, como sempre foi), duas colunas ou faixa compacta.
function _htmlParesDoc(pares, variante) {
    pares = pares.filter(([, val]) => val);
    if (!pares.length) return '';
    if (variante === 'colunas') return `<div class="med-dados med-colunas">${pares.map(([l, val]) =>
        `<div><span class="med-rot">${l}</span><span>${val}</span></div>`).join('')}</div>`;
    if (variante === 'faixa') return `<div class="med-dados med-faixa">${pares.map(([l, val]) =>
        `<span><span class="med-rot">${l}:</span> ${val}</span>`).join('')}</div>`;
    return `<table class="med-dados" style="width:100%;border-collapse:collapse">${pares.map(([l, val]) => `<tr>
            <td style="padding:8px 12px;font-weight:600;color:#555;width:180px;border-bottom:1px solid #E0E0E0">${l}</td>
            <td style="padding:8px 12px;border-bottom:1px solid #E0E0E0">${val}</td>
           </tr>`).join('')}</table>`;
}

function gerarHTMLAgendamentoMedicao(v, layout) {
    layout = layout || getLayoutDocumento('medicao');
    const cli = v.clienteId ? db.clientes.find(c => c.id == v.clienteId) : null;
    const d   = new Date(v.data + 'T12:00:00');
    const dataFmt = d.toLocaleDateString('pt-BR', { weekday: 'long', day: '2-digit', month: 'long', year: 'numeric' });
    const horaFmt = v.hora ? _agdPeriodo(v.hora, +v.duracao || _agdDurPadrao('med')) : '—';
    const badgeBg  = v.status === 'Realizado' ? '#E3F7E2' : '#E4EFF9';
    const badgeClr = v.status === 'Realizado' ? '#0F6B0D' : '#1F5A96';
    const valores = Object.assign(valoresComunsEmpresa(), {
        cliente: v.clienteNome || '', cliente_telefone: v.clienteTel || '',
        data_visita: d.toLocaleDateString('pt-BR'), horario: v.hora ? horaFmt : '',
        responsavel: _medNomeResp(v), endereco_visita: _endImpMed(v), id: v.id
    });
    const secTitle = id => {
        const t = blocoDoLayout(layout, id).titulo;
        return (t || '').trim() ? `<div style="font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:.6px;color:#8F8F8F;margin:20px 0 8px;padding-bottom:4px;border-bottom:1px solid #E0E0E0">${textoDoc(t, valores)}</div>` : '';
    };
    const dados = (id, pares) => {
        const html = _htmlParesDoc(pares, blocoDoLayout(layout, id).variante);
        return html ? secTitle(id) + html : '';
    };
    const rodape = String(blocoDoLayout(layout, 'rodape').corpo || '').split('\n').filter(l => l.trim());
    const blocos = {
        cabecalho: `
        <div class="doc-cab" style="display:flex;justify-content:space-between;align-items:flex-start;border-bottom:3px solid var(--doc-cor,#005D3B);padding-bottom:16px;margin-bottom:24px">
            <div>${buildEmpresaHeaderHTML(52)}</div>
            <div style="text-align:right">
                <div style="font-size:16px;font-weight:700;color:#242424">${textoDoc(layout.titulo, valores)}</div>
                <div style="font-size:12px;color:#8F8F8F;margin-top:2px">Emitido em ${new Date().toLocaleString('pt-BR')}</div>
                <span style="display:inline-block;margin-top:6px;padding:3px 12px;border-radius:12px;font-size:12px;font-weight:700;background:${badgeBg};color:${badgeClr}">${escapeHtml(v.status)}</span>
            </div>
        </div>`,
        cliente: dados('cliente', [
            ['Nome', escapeHtml(v.clienteNome || '—')],
            ['Telefone / WhatsApp', escapeHtml(v.clienteTel || '')],
            ['E-mail', escapeHtml(cli?.email || '')],
            ['CPF / CNPJ', escapeHtml(cli?.cpf || '')],
            ['Endereço cadastrado', escapeHtml(cli ? _endImpCliente(cli) : '')]
        ]),
        agendamento: dados('agendamento', [
            ['Data da visita', dataFmt],
            ['Horário', horaFmt],
            ['Responsável', escapeHtml(_medNomeResp(v))],
            ['Endereço da visita', escapeHtml(_endImpMed(v))],
            ['Observações', escapeHtml(v.obs || '')]
        ]),
        assinatura: `
        <div style="margin-top:48px;text-align:center">
            <div style="border-top:1px solid #242424;width:260px;margin:0 auto 6px"></div>
            <p style="font-size:12px;color:#8F8F8F">${textoDoc(blocoDoLayout(layout, 'assinatura').corpo, valores)}</p>
        </div>`,
        rodape: rodape.length ? `
        <div style="margin-top:40px;padding-top:16px;border-top:1px solid #E0E0E0;font-size:12px;color:#8F8F8F;display:flex;justify-content:space-between;gap:12px;flex-wrap:wrap">
            ${rodape.map(l => `<span>${textoDoc(l.trim(), valores)}</span>`).join('')}
        </div>` : ''
    };
    return montarDocumentoLayout('medicao', layout, blocos, valores);
}

// --- AGENDAS DA PRODUCAO (Medicoes e Instalacoes) ---------------------------
// As duas abas tem o mesmo desenho: coluna de pendentes (data mais proxima
// primeiro) e coluna de realizados (mais recente primeiro), cada uma com a sua
// busca. A linha so mostra o resumo; as acoes ficam no detalhe, aberto pela
// seta. Toda acao regrava e redesenha as listas, sem recarregar a pagina.
const _AGD_SVG = {
    cal:     '<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M16 3v4M8 3v4M3 10h18"/>',
    relogio: '<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',
    tel:     '<path d="M22 16.9v3a2 2 0 0 1-2.2 2 19.8 19.8 0 0 1-8.6-3.1 19.5 19.5 0 0 1-6-6A19.8 19.8 0 0 1 2.1 4.2 2 2 0 0 1 4.1 2h3a2 2 0 0 1 2 1.7c.1.9.4 1.8.7 2.7a2 2 0 0 1-.5 2.1L8 9.8a16 16 0 0 0 6 6l1.3-1.3a2 2 0 0 1 2.1-.4c.9.3 1.8.6 2.7.7a2 2 0 0 1 1.7 2z"/>',
    pin:     '<path d="M12 22s7-6.2 7-12a7 7 0 0 0-14 0c0 5.8 7 12 7 12z"/><circle cx="12" cy="10" r="2.5"/>',
    user:    '<circle cx="12" cy="8" r="4"/><path d="M4 21c0-4 3.6-7 8-7s8 3 8 7"/>',
    seta:    '<path d="m9 6 6 6-6 6"/>',
    caixa:   '<path d="M21 8 12 3 3 8v8l9 5 9-5z"/><path d="m3 8 9 5 9-5M12 13v8"/>',
};
function _agdIco(nome, tam) {
    const t = tam || 14;
    return `<svg viewBox="0 0 24 24" width="${t}" height="${t}" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${_AGD_SVG[nome] || ''}</svg>`;
}

let _agdBusca = { medPend: '', medReal: '', instPend: '', instReal: '' };

// Dia de hoje no fuso do usuario (toISOString daria o dia em UTC, que vira o
// dia seguinte a noite no Brasil).
function _agdHoje() { return new Date().toLocaleDateString('sv-SE'); }
function _agdDiaLocal(ts) { return new Date(ts).toLocaleDateString('sv-SE'); }
function _agdFmtData(d) { return d ? new Date(d + 'T12:00:00').toLocaleDateString('pt-BR') : '—'; }
function _agdFmtMomento(ts) {
    return new Date(ts).toLocaleString('pt-BR', { day: '2-digit', month: '2-digit', year: 'numeric', hour: '2-digit', minute: '2-digit' });
}
// Chave de ordenacao: sem data vai para o fim; sem horario, para o fim do dia.
function _agdChave(data, hora) { return (data || '9999-12-31') + ' ' + (hora || '99:99'); }
function _agdCmp(a, b) { return a < b ? -1 : a > b ? 1 : 0; }
function _agdNorm(s) { return String(s || '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase().trim(); }

const _AGD_PILLS = {
    agendado:  ['Agendado',          'agd-pill-azul'],
    atrasado:  ['Atrasado',          'agd-pill-verm'],
    realizado: ['Realizado',         'agd-pill-verde'],
    instalado: ['Instalado',         'agd-pill-verde'],
    pagamento: ['Aguard. financeiro', 'agd-pill-amar'],
    semdata:   ['Sem data',          'agd-pill-cinza'],
    aceite:    ['Aguardando aceite', 'agd-pill-amar'],
    reagendar: ['A reagendar',       'agd-pill-verm'],
};
function _agdPill(tipo) {
    const [txt, cls] = _AGD_PILLS[tipo] || _AGD_PILLS.agendado;
    return `<span class="agd-pill ${cls}">${txt}</span>`;
}

function _agdLinha(o) {
    return `<div class="agd-item" role="button" tabindex="0" onclick="${o.onclick}" onkeydown="if(event.target===this&&(event.key==='Enter'||event.key===' ')){event.preventDefault();this.click()}" title="Ver detalhes">
        <span class="agd-avatar">${_agdIco('user', 18)}</span>
        <span class="agd-info">
            <span class="agd-nome">${escapeHtml(o.nome || '—')}</span>
            ${o.sub ? `<span class="agd-linha agd-sub">${escapeHtml(o.sub)}</span>` : ''}
            ${o.tel ? `<span class="agd-linha">${_agdIco('tel', 12)}${escapeHtml(o.tel)}</span>` : ''}
            ${o.end ? `<span class="agd-linha">${_agdIco('pin', 12)}${escapeHtml(o.end)}</span>` : ''}
        </span>
        <span class="agd-quando">
            <span class="agd-quando-linha">
                <span class="agd-linha">${_agdIco('cal', 13)}${o.data ? _agdFmtData(o.data) : 'Sem data'}</span>
                <span class="agd-linha">${_agdIco('relogio', 13)}${escapeHtml(o.hora || '--:--')}</span>
            </span>
            <span class="agd-status">${_agdPill(o.pill)}${o.end ? linkIrParaHtml(o.end, 'agd-ir') : ''}</span>
        </span>
        <span class="agd-seta">${_agdIco('seta', 16)}</span>
    </div>`;
}

// "📍 Ir": abre o Google Maps com o caminho ate o endereco, saindo de onde a
// pessoa esta. Clicar no link nao abre o card em que ele esta.
function _agdEnd(endereco, cidade) {
    return typeof RotasCore !== 'undefined' ? RotasCore.enderecoCompleto(endereco, cidade) : String(endereco || '').trim();
}
// Endereco que vai ao mapa: registro com partes usa as partes; antigo, texto + cidade como sempre.
function _partesMedMapa(m) { return m && m.rua !== undefined ? m : null; }
function _partesInstMapa(p, cli) {
    if (_instVazia(p)) return cli && cli.rua !== undefined ? cli : null;
    if (p.inst_rua !== undefined) return _instPartes(p, cli);
    if (!p.inst_endereco && cli && cli.rua !== undefined) return cli;
    return null;
}
// Para conferir o deslocamento: registro antigo (sem partes) usa o texto do endereco + cidade, como as Rotas.
function _partesMedConferir(m) { return _partesMedMapa(m) || EnderecoCore.partesDeRegistroAntigo(m.endereco, m.cidade); }
function _partesInstConferir(p, cli) {
    const pt = _partesInstMapa(p, cli);
    if (pt) return pt;
    if (_instVazia(p)) return EnderecoCore.partesDeRegistroAntigo(cli && cli.end, cli && cli.cidade);
    return EnderecoCore.partesDeRegistroAntigo(p.inst_endereco || (cli && cli.end), _instCidade(p, cli));
}
function _endMed(m) {
    const pt = _partesMedMapa(m);
    return pt && typeof RotasCore !== 'undefined' ? RotasCore.enderecoDePartes(pt) : _agdEnd(m.endereco, m.cidade);
}
function _endInst(p, cli) {
    if (_instVazia(p)) return cli ? _endCliente(cli) : '';
    const pt = _partesInstMapa(p, cli);
    return pt && typeof RotasCore !== 'undefined' ? RotasCore.enderecoDePartes(pt) : _agdEnd(p.inst_endereco || cli?.end, _instCidade(p, cli));
}
function _endCliente(cli) {
    return cli.rua !== undefined && typeof RotasCore !== 'undefined' ? RotasCore.enderecoDePartes(cli) : _agdEnd(cli.end, cli.cidade);
}
function linkIrParaHtml(endereco, classe) {
    const url = typeof RotasCore !== 'undefined' ? RotasCore.linkIrPara(_agdEnd(endereco)) : '';
    if (!url) return '';
    return `<a class="${classe || 'agd-ir'}" href="${escapeHtml(url)}" target="_blank" rel="noopener" onclick="event.stopPropagation()" onkeydown="event.stopPropagation()" title="Abrir o caminho no Google Maps">📍 Ir</a>`;
}
// --- Endereco em partes (CEP, rua, numero, complemento, bairro, cidade, estado) ---
// Usado no cliente, na medicao, na instalacao e no formulario da agenda. Tudo pelo prefixo dos ids.
function enderecoCamposHtml(prefixo, opts) {
    opts = opts || {};
    const p = prefixo;
    const ufs = '<option value=""></option>' + EnderecoCore.UFS.map(u => `<option value="${u}">${u}</option>`).join('');
    const ir = opts.ir ? `<button type="button" class="btn btn-outline btn-ir-end" id="${p}-ir" onclick="irParaEnderecoPartes('${p}')" title="Abrir o caminho no Google Maps">📍 Ir para endereço</button>` : '';
    return `<div class="end-campos">
        <div class="form-group end-cep"><label for="${p}-cep">CEP</label>
            <div class="campo-com-botao"><input type="text" id="${p}-cep" inputmode="numeric" autocomplete="postal-code" placeholder="00000-000"><button type="button" class="btn btn-outline" id="${p}-buscar-cep" style="display:none" onclick="buscarEnderecoCep('${p}')">Buscar endereço</button></div>
            <div class="rota-status end-status" id="${p}-cep-status" role="status" aria-live="polite"></div></div>
        <div class="form-group end-rua"><label for="${p}-rua">Rua${opts.obrigRua ? ' *' : ''}</label><div class="campo-com-botao"><input type="text" id="${p}-rua" placeholder="Ex.: Rua das Flores">${ir}</div></div>
        <div class="form-group"><label for="${p}-numero">Número</label><input type="text" id="${p}-numero" placeholder="Ex.: 100"></div>
        <div class="form-group"><label for="${p}-complemento">Complemento</label><input type="text" id="${p}-complemento" placeholder="Ex.: apto 12"></div>
        <div class="form-group"><label for="${p}-bairro">Bairro</label><input type="text" id="${p}-bairro"></div>
        <div class="form-group"><label for="${p}-cidade">Cidade</label><input type="text" id="${p}-cidade" placeholder="Ex.: Curitiba"></div>
        <div class="form-group"><label for="${p}-uf">Estado</label><select id="${p}-uf">${ufs}</select></div>
    </div>`;
}
function _enderecoBotaoCep(p) {
    const cep = document.getElementById(p + '-cep'), b = document.getElementById(p + '-buscar-cep');
    if (b && cep) b.style.display = String(cep.value).replace(/\D/g, '').length === 8 ? '' : 'none';
}
function enderecoAnexar(prefixo) {
    const cep = document.getElementById(prefixo + '-cep');
    if (!cep || cep.dataset.endLigado) return;
    cep.dataset.endLigado = '1';
    cep.addEventListener('input', () => {
        const m = EnderecoCore.mascaraCep(cep.value);
        if (m !== cep.value) cep.value = m;
        const st = document.getElementById(prefixo + '-cep-status');
        if (st) st.textContent = '';
        _enderecoBotaoCep(prefixo);
    });
    cep.addEventListener('keydown', e => {
        if (e.key === 'Enter') { e.preventDefault(); e.stopPropagation(); buscarEnderecoCep(prefixo); }
    });
    _enderecoBotaoCep(prefixo);
}
function enderecoLer(prefixo) {
    const v = id => (document.getElementById(prefixo + '-' + id)?.value || '').trim();
    return { cep: EnderecoCore.soDigitosCep(v('cep')), rua: v('rua'), numero: v('numero'), complemento: v('complemento'),
        bairro: v('bairro'), cidade: v('cidade'), uf: v('uf').toUpperCase() };
}
function enderecoPreencher(prefixo, partes) {
    partes = partes || {};
    const set = (id, val) => { const el = document.getElementById(prefixo + '-' + id); if (el) el.value = val == null ? '' : val; };
    set('cep', EnderecoCore.mascaraCep(partes.cep));
    ['rua', 'numero', 'complemento', 'bairro', 'cidade'].forEach(k => set(k, partes[k]));
    set('uf', String(partes.uf || '').toUpperCase());
    const st = document.getElementById(prefixo + '-cep-status');
    if (st) st.textContent = '';
    _enderecoBotaoCep(prefixo);
}
async function _cepConsulta(url, interpretar, tratar404) {
    const r = await fetch(url, { signal: AbortSignal.timeout(8000) });
    if (r.status === 404 && tratar404) return { ok: false, motivo: 'nao-encontrado' };
    if (!r.ok) throw new Error('HTTP ' + r.status);
    return interpretar(await r.json());
}
async function buscarEnderecoCep(prefixo) {
    const cepEl = document.getElementById(prefixo + '-cep'), st = document.getElementById(prefixo + '-cep-status');
    if (!cepEl) return;
    const dig = String(cepEl.value).replace(/\D/g, '');
    if (dig.length !== 8) return;
    if (st) st.textContent = 'Buscando…';
    let r;
    try { r = await _cepConsulta(`https://viacep.com.br/ws/${dig}/json/`, EnderecoCore.interpretarViaCep, false); }
    catch (e1) {
        try { r = await _cepConsulta(`https://brasilapi.com.br/api/cep/v1/${dig}`, EnderecoCore.interpretarBrasilApi, true); }
        catch (e2) { r = null; }
    }
    // A pessoa trocou o CEP (ou fechou a tela) enquanto esperava: essa resposta nao vale mais.
    if (!cepEl.isConnected || String(cepEl.value).replace(/\D/g, '') !== dig) return;
    const msg = t => { if (st) st.textContent = t; };
    if (!r) { msg('Não deu para buscar o endereço agora. Preencha à mão.'); return; }
    if (!r.ok) { msg('CEP não encontrado. Confira os números ou preencha o endereço à mão.'); return; }
    const set = (id, val) => { const el = document.getElementById(prefixo + '-' + id); if (el && val) el.value = val; };
    set('rua', r.rua); set('bairro', r.bairro); set('cidade', r.cidade);
    if (r.uf && EnderecoCore.UFS.includes(r.uf)) set('uf', r.uf);
    if (r.cidadeToda) { msg('Esse CEP é da cidade toda: preencha a rua e o bairro.'); document.getElementById(prefixo + '-rua')?.focus(); }
    else { msg(''); document.getElementById(prefixo + '-numero')?.focus(); }
}
// Botao "Ir para endereco" ao lado da Rua: usa as partes digitadas.
async function irParaEnderecoPartes(prefixo) {
    const p = enderecoLer(prefixo);
    if (!p.rua && !p.cep) { await showAlert('Digite o endereço primeiro.', '📍'); return; }
    window.open(RotasCore.linkIrPara(RotasCore.enderecoDePartes(p)), '_blank', 'noopener');
}

// unidade: [singular, plural] escreve "4 agendamentos"; sem ela, so o numero.
function _agdPreencher(prefixo, linhas, total, vazio, busca, unidade) {
    const lista = document.getElementById(prefixo + '-lista');
    const cont  = document.getElementById(prefixo + '-count');
    const sufixo = unidade ? ' ' + unidade[total === 1 ? 0 : 1] : '';
    if (cont) cont.textContent = (busca ? `${linhas.length} de ${total}` : String(total)) + sufixo;
    if (lista) lista.innerHTML = linhas.length
        ? linhas.join('')
        : `<div class="agd-vazio">${busca ? 'Nenhum resultado para essa busca.' : vazio}</div>`;
}

// A busca so redesenha as listas; o campo digitado nao e recriado e nao perde o foco.
function buscarAgenda(chave, valor) {
    _agdBusca[chave] = valor || '';
    if (chave.startsWith('med')) renderMedicoes(); else renderAgenda();
}

// --- Modal de detalhe/formulario (um por vez) ---
let _agdModalEl = null;
function _agdEsc(e) { if (e.key === 'Escape') fecharModalAgenda(); }
function fecharModalAgenda() {
    _agdPickerFechar();
    if (!_agdModalEl) return;
    _agdModalEl.remove();
    _agdModalEl = null;
    document.removeEventListener('keydown', _agdEsc);
    if (typeof _agendaRedesenhar === 'function') _agendaRedesenhar();   // a Agenda aberta por baixo mostra o que mudou
}
function _agdAbrirModal(titulo, corpo, rodape) {
    fecharModalAgenda();
    const o = document.createElement('div');
    o.className = 'agd-modal-overlay';
    o.innerHTML = `<div class="agd-modal" role="dialog" aria-modal="true" aria-label="${escapeHtml(titulo)}">
        <div class="agd-modal-head">
            <h3>${escapeHtml(titulo)}</h3>
            <button type="button" class="agd-modal-x" onclick="fecharModalAgenda()" aria-label="Fechar">×</button>
        </div>
        <div class="agd-modal-corpo">${corpo}</div>
        ${rodape ? `<div class="agd-modal-acoes">${rodape}</div>` : ''}
    </div>`;
    o.addEventListener('click', e => { if (e.target === o) fecharModalAgenda(); });
    document.body.appendChild(o);
    _agdModalEl = o;
    document.addEventListener('keydown', _agdEsc);
    return o;
}

// pares: [rotulo, html ja escapado]; null e ignorado.
function _agdCampos(pares) {
    return `<dl class="agd-det">${pares.filter(Boolean).map(([k, v]) => `<dt>${k}</dt><dd>${v}</dd>`).join('')}</dl>`;
}

function _agdDescHist(x) {
    const fmt = o => o && o.data ? _agdFmtData(o.data) + (o.hora ? ' ' + o.hora : '') : 'sem data';
    const por = x.por ? ` (${nomeUsuario(x.por) || 'usuário removido'})` : '';
    const quando = _agdFmtMomento(x.em);
    if (x.acao === 'agendado')   return `${quando}: agendado para ${fmt(x.para)}${x.prof ? ' com ' + x.prof : ''}${por}`;
    if (x.acao === 'reagendado') return `${quando}: reagendado de ${fmt(x.de)} para ${fmt(x.para)}${por}`;
    if (x.acao === 'desmarcado') return `${quando}: data desmarcada, era ${fmt(x.de)}${por}`;
    if (x.acao === 'cancelado')  return `${quando}: agendamento cancelado${x.de ? ', era ' + fmt(x.de) : ''}${por}`;
    if (x.acao === 'aceito')     return `${quando}: aceito${por}`;
    if (x.acao === 'recusado')   return `${quando}: recusado${x.motivo ? ' — ' + x.motivo : ''}${x.de && x.de.data ? ', era ' + fmt(x.de) : ''}${por}`;
    if (x.acao === 'pedido')     return `${quando}: pedido #${formatPedidoId(x.pedido)} criado a partir deste agendamento${por}`;
    return `${quando}: ${x.acao}${por}`;
}
function _agdHistorico(h) {
    if (!h || !h.length) return '';
    return `<div class="agd-hist"><div class="agd-hist-tit">Histórico</div>${
        h.map(x => `<div>• ${escapeHtml(_agdDescHist(x))}</div>`).join('')}</div>`;
}
function _agdRegistrar(lista, acao, extra) {
    lista.push({ acao, em: Date.now(), por: getUsuarioLogado()?.id || null, ...(extra || {}) });
}

// campos: { id, label, tipo: date|time|text|textarea|usuario|pessoa|profissional|duracao, valor, obrig, largo, placeholder }
// onSalvar(valores) grava; se devolver false, o formulario continua aberto.
// opts.disp = { tipo: 'inst'|'med', ignorar: { tipo, id }, exigeHora }: mostra o
// painel de disponibilidade do profissional (campos usu/data/hora/dur) e,
// ao salvar, confere de novo a agenda gravada antes de chamar onSalvar.
function _agdFormulario(titulo, campos, onSalvar, voltar, opts) {
    const disp = opts && opts.disp;
    const corpo = `<div class="agd-form">${campos.map(c => {
        const id  = 'agdf-' + c.id;
        const req = c.obrig ? ' <span style="color:var(--danger)">*</span>' : '';
        const ph  = c.placeholder ? ` placeholder="${escapeHtml(c.placeholder)}"` : '';
        let input;
        if (c.tipo === 'textarea')          input = `<textarea id="${id}" rows="3"${ph}>${escapeHtml(c.valor || '')}</textarea>`;
        else if (c.tipo === 'usuario')      input = `<select id="${id}"></select>`;
        else if (c.tipo === 'pessoa')       input = htmlCampoPessoa(id, c.valor, 'A definir — selecione ou digite um nome');
        else if (c.tipo === 'profissional') input = `<select id="${id}"></select><input type="text" id="${id}-outro" class="agd-prof-outro" placeholder="Nome do profissional" autocomplete="off" hidden>`;
        else if (c.tipo === 'duracao')      input = `<select id="${id}"></select>`;
        else if (c.tipo === 'endereco')     return `<div class="agd-form-largo">${enderecoCamposHtml(id, { obrigRua: c.obrig, ir: true })}</div>`;
        else                                input = `<input type="${c.tipo}" id="${id}" value="${escapeHtml(c.valor || '')}"${ph}>`;
        return `<div class="form-group${c.largo ? ' agd-form-largo' : ''}"><label for="${id}">${escapeHtml(c.label)}${req}</label>${input}</div>`;
    }).join('')}</div>${disp ? '<div class="agd-disp agd-disp-modal" id="agdf-disp" aria-live="polite"></div>' : ''}`;
    const rodape = `<button type="button" class="btn btn-outline btn-sm" id="agdf-voltar">Voltar</button>
        <button type="button" class="btn btn-success btn-sm" id="agdf-salvar">Salvar</button>`;
    const o = _agdAbrirModal(titulo, corpo, rodape);
    campos.filter(c => c.tipo === 'usuario').forEach(c => {
        preencherSelectUsuarios('agdf-' + c.id, '— A definir —');
        const s = document.getElementById('agdf-' + c.id);
        if (s) s.value = c.valor ? String(c.valor) : '';
    });
    campos.filter(c => c.tipo === 'profissional').forEach(c => _agdPreencherProf('agdf-' + c.id, c.valor, c.vazio || '— A definir —'));
    campos.filter(c => c.tipo === 'duracao').forEach(c => _agdPreencherDur('agdf-' + c.id, c.servico || (disp && disp.tipo) || 'inst', c.valor));
    campos.filter(c => c.tipo === 'endereco').forEach(c => { enderecoPreencher('agdf-' + c.id, c.valor); enderecoAnexar('agdf-' + c.id); });

    const lerValores = () => {
        const v = {};
        for (const c of campos) {
            const el = document.getElementById('agdf-' + c.id);
            if (c.tipo === 'endereco')          v[c.id] = enderecoLer('agdf-' + c.id);
            else if (c.tipo === 'usuario')      v[c.id] = parseInt(el.value) || null;
            else if (c.tipo === 'profissional') v[c.id] = _agdLerProf('agdf-' + c.id);
            else if (c.tipo === 'duracao')      v[c.id] = parseInt(el.value) || null;
            else                                v[c.id] = el.value.trim();
        }
        return v;
    };
    const consulta = (v = lerValores()) => {
        return { tipo: disp.tipo, prof: v.usu ? v.usu.chave : '', profNome: v.usu ? v.usu.pessoa.nome : '', data: v.data, hora: v.hora, dur: v.dur || _agdDurPadrao(disp.tipo), ignorar: disp.ignorar };
    };
    // Editar/Reagendar: o que importa para o deslocamento (profissional, dia, hora, duracao, endereco).
    const chaveDesloc = v => JSON.stringify([v.usu ? v.usu.chave : '', v.data, v.hora, v.dur || _agdDurPadrao(disp.tipo), v.end || null]);
    const inicial = disp && disp.ignorar ? chaveDesloc(lerValores()) : null;
    const atualizarDisp = () => {
        if (!disp) return;
        _agdDispCtx['agdf-disp'] = Object.assign(_agdDispCtx['agdf-disp'] || {}, { onHora: (d, h) => {
            const de = document.getElementById('agdf-data'), he = document.getElementById('agdf-hora');
            if (de) de.value = d;
            if (he) { he.value = h; he.classList.remove('agd-erro'); }
            atualizarDisp();
        }, onProf: ch => {
            const sel = document.getElementById('agdf-usu');
            _agdPreencherProf('agdf-usu', ch, sel && sel.options[0] ? sel.options[0].text : '— A definir —');
            atualizarDisp();
        } });
        _agdRenderDisp('agdf-disp', consulta());
    };
    if (disp) {
        _agdPickerAnexar(document.getElementById('agdf-hora'), () => { const { hora, ...q } = consulta(); return q; });
        const prof = document.getElementById('agdf-usu');
        if (prof) prof.addEventListener('change', () => { _agdProfMudou('agdf-usu'); atualizarDisp(); });
        document.getElementById('agdf-usu-outro')?.addEventListener('input', atualizarDisp);
        ['data', 'dur'].forEach(k => document.getElementById('agdf-' + k)?.addEventListener('change', atualizarDisp));
        document.getElementById('agdf-hora')?.addEventListener('input', atualizarDisp);
        atualizarDisp();
    }

    o.querySelector('#agdf-voltar').onclick = voltar || fecharModalAgenda;
    o.querySelector('#agdf-salvar').onclick = () => _agdSemDuplo(async () => {
        for (const c of campos) {
            if (c.tipo === 'endereco') {
                const rua = document.getElementById('agdf-' + c.id + '-rua');
                rua.classList.remove('agd-erro');
                if (c.obrig && !rua.value.trim()) { rua.classList.add('agd-erro'); rua.focus(); return; }
                continue;
            }
            const el = document.getElementById('agdf-' + c.id);
            el.classList.remove('agd-erro');
            const vazio = c.tipo === 'profissional' ? !_agdLerProf('agdf-' + c.id).chave : !el.value.trim();
            if (c.obrig && vazio) { el.classList.add('agd-erro'); el.focus(); return; }
        }
        // Os valores sao lidos uma vez, no clique: a conferencia de deslocamento espera a rede
        // e o que se digita (ou o formulario que se abre) nesse meio-tempo nao muda o que sera salvo.
        const vals = lerValores();
        vals._semMudanca = inicial !== null && chaveDesloc(vals) === inicial;
        if (disp) {
            const q = consulta(vals);
            const horaEl = document.getElementById('agdf-hora');
            if (q.prof && q.data && !q.hora && horaEl) {
                horaEl.classList.add('agd-erro'); horaEl.focus();
                await showAlert('Informe o horário: ele reserva a agenda do profissional.', '⚠️');
                return;
            }
            if (disp.partes && !vals._semMudanca) q.partes = disp.partes(vals);
            if (!await _agdValidarDisp(q)) { atualizarDisp(); _agdRedesenharAgendas(); return; }
        }
        await onSalvar(vals);
    });
    o.querySelector('input:not([hidden]), select, textarea')?.focus();
}

// --- DISPONIBILIDADE COMPARTILHADA (Instalacoes + Medicoes) -----------------
// O profissional e um so nas duas agendas: tudo o que esta agendado ocupa o
// periodo [horario, horario + duracao) dele -- instalacao de pedido Pronto p/
// Instalacao ja agendada e medicao com status Agendado. Concluido (Instalado,
// Aguardando Financeiro, medicao Realizada) e cancelado nao ocupam nada.
const _AGD_CFG_PADRAO = { dur_inst: 120, dur_med: 60, inicio: '08:00', fim: '18:00', passo: 60 };
const _AGD_DURACOES = [30, 60, 90, 120, 150, 180, 240, 300, 360, 480];

function getAgendaConfig() {
    let c = {};
    try { c = JSON.parse(localStorage.getItem('sc_agd_cfg') || '{}') || {}; } catch (e) { c = {}; }
    return { ..._AGD_CFG_PADRAO, ...c };
}
function _agdDurPadrao(tipo) { const c = getAgendaConfig(); return +(tipo === 'med' ? c.dur_med : c.dur_inst) || 60; }
function _agdMin(h) { const m = /^(\d{1,2}):(\d{2})/.exec(h || ''); return m ? (+m[1]) * 60 + (+m[2]) : null; }
function _agdHHMM(min) { return String(Math.floor(min / 60)).padStart(2, '0') + ':' + String(min % 60).padStart(2, '0'); }
function _agdFmtDur(min) {
    min = +min || 0;
    const h = Math.floor(min / 60), m = min % 60;
    if (!h) return m + ' min';
    if (!m) return h + (h === 1 ? ' hora' : ' horas');
    return h + 'h' + String(m).padStart(2, '0');
}
function _agdPeriodo(hora, dur) {
    const i = _agdMin(hora);
    return i === null ? '' : `${_agdHHMM(i)} – ${_agdHHMM(i + (+dur || 0))}`;
}

// Profissional = usuario do sistema (u:<id>) ou nome digitado (n:<nome>).
function _profChave(id, nome) {
    if (id) return 'u:' + id;
    const n = _agdNorm(nome);
    return n ? 'n:' + n : '';
}
function _instProf(p) { return _profChave(p.usuario_instalacao_id, p.instalador_nome); }
function _medProf(m)  { return _profChave(m.usuario_id, m.responsavel_nome); }
function _medNomeResp(m) { return nomeUsuario(m.usuario_id) || m.responsavel_nome || ''; }
function _medDefinirResponsavel(m, pessoa) {
    m.usuario_id = pessoa.id || null;
    m.responsavel_nome = pessoa.id ? '' : (pessoa.nome || '');
}

// --- ACEITE de medicao/instalacao destinada a outro usuario ---------------------------
// Dados: medicao.aceite / pedido.inst_aceite = { status: 'pendente'|'aceito', por: quem destinou,
// em, resp_em }; recusa: medicao.recusa / pedido.inst_recusa = { por: quem recusou, para: quem
// destinou, motivo, em }. Pendente reserva o horario (tracejado na agenda). Responsavel que e o
// proprio usuario ou profissional externo (sem usuario) vale direto: sem campo de aceite.
function _aceitePend(a) { return !!a && a.status === 'pendente'; }
// Pedido de aceite vencido: o horario marcado ja chegou sem resposta (sem hora: o fim do dia).
function _aceiteVencido(data, hora) {
    const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(String(data || ''));
    if (!m) return false;
    const ini = _agdMin(hora);
    return Date.now() >= new Date(+m[1], +m[2] - 1, +m[3], 0, ini === null ? 1440 : ini).getTime();
}
function _aceiteQuando(data, hora, curto) {
    const [, m, d] = String(data || '').split('-');
    const dm = d ? `${d}/${m}` : 'sem data';
    return hora ? dm + (curto ? ' ' : ' às ') + hora : dm;
}
function _aceiteAcoes(tipo, id) {
    return [{ rotulo: 'Aceitar', fn: `aceitarAgendamento('${tipo}',${id})` },
            { rotulo: 'Recusar', fn: `recusarAgendamento('${tipo}',${id})`, sec: true }];
}
// antes: { uid, data, hora } gravados antes da edicao (null = registro novo ou refeito).
// So pede aceite quando o responsavel e outro usuario e algo mudou (responsavel, data ou hora).
// O proprio destinado editando um pedido de aceite ainda pendente = aceitou (quem destinou
// recebe "aceitou"), em vez de o pedido sumir sem resposta.
function _aceiteAplicar(reg, campo, antes, uid, data, hora) {
    const eu = getUsuarioLogado()?.id || null;
    uid = uid || null; hora = hora || '';
    if (uid && uid !== eu) {
        const mudou = !antes || antes.uid !== uid || antes.data !== data || (antes.hora || '') !== hora;
        if (mudou) reg[campo] = { status: 'pendente', por: eu, em: Date.now() };
    } else if (uid && antes && antes.uid === eu && _aceitePend(reg[campo])) {
        reg[campo].status = 'aceito';
        reg[campo].resp_em = Date.now();
        const hist = campo === 'aceite' ? 'historico' : 'inst_historico';
        if (!reg[hist]) reg[hist] = [];
        _agdRegistrar(reg[hist], 'aceito');
    } else delete reg[campo];
}
function _aceiteBuscar(tipo, id) {
    _agdRecarregar();
    const eu = getUsuarioLogado();
    const med = tipo === 'med';
    const reg = med ? (db.medicoes || []).find(x => x.id == id) : db.pedidos.find(x => x.id == id);
    const campo = med ? 'aceite' : 'inst_aceite';
    const ativo = reg && (med ? reg.status === 'Agendado' : _instPendente(reg));
    const dest = reg && (med ? reg.usuario_id : reg.usuario_instalacao_id);
    if (!eu || !ativo || !_aceitePend(reg[campo]) || dest !== eu.id) {
        toast('Este pedido de aceite já foi respondido ou mudou.', 'info');
        Notif.atualizar();
        return null;
    }
    if (med ? _aceiteVencido(reg.data, reg.hora) : _aceiteVencido(reg.data_entrega, reg.inst_hora)) {
        toast('O horário deste agendamento já passou. Quem destinou vai reagendar.', 'info');
        Notif.atualizar();
        return null;
    }
    return { reg, campo, med, eu, hist: med ? 'historico' : 'inst_historico' };
}
// Grava so a chave tocada (sc_med ou sc_ped): o aceite pode vir do sino em qualquer
// pagina, aberta ha tempo -- syncDB() regravaria clientes, financeiro etc. velhos.
function _aceiteRedesenhar(med) {
    _gravarChaves([med ? 'sc_med' : 'sc_ped']);
    renderMedicoes();
    renderAgenda();
    if (med) renderDashboardMedicoes();
    else {
        if (document.getElementById('kanban-board')) renderKanban();
        renderDashboardInstalacoes();
    }
    Notif.atualizar();
}
function aceitarAgendamento(tipo, id) {
    const r = _aceiteBuscar(tipo, id);
    if (!r) return;
    const a = r.reg[r.campo];
    a.status = 'aceito'; a.resp_em = Date.now();
    if (!r.reg[r.hist]) r.reg[r.hist] = [];
    _agdRegistrar(r.reg[r.hist], 'aceito');
    _aceiteRedesenhar(r.med);
    toast('Agendamento aceito.', 'success');
}
function recusarAgendamento(tipo, id) {
    const r = _aceiteBuscar(tipo, id);
    if (!r) return;
    const m = r.reg;
    const quando = r.med ? _aceiteQuando(m.data, m.hora) : _aceiteQuando(m.data_entrega, m.inst_hora);
    const titulo = r.med ? `a medição de ${m.clienteNome || 'cliente'}` : `a instalação do pedido #${formatPedidoId(m.id)} (${m.clienteNome || 'cliente'})`;
    const corpo = `<p style="margin:0 0 12px">Recusar ${escapeHtml(titulo)} em ${escapeHtml(quando)}?</p>
        <div class="form-group"><label for="aceite-motivo">Motivo <span style="color:var(--danger)">*</span></label>
        <textarea id="aceite-motivo" rows="3" placeholder="Diga por que não dá para atender"></textarea></div>`;
    _agdAbrirModal('Recusar agendamento', corpo,
        `<button type="button" class="btn btn-outline btn-sm" onclick="fecharModalAgenda()">Voltar</button>
         <button type="button" class="btn btn-outline btn-sm btn-danger" id="aceite-confirmar" disabled>Recusar</button>`);
    const txt = document.getElementById('aceite-motivo'), ok = document.getElementById('aceite-confirmar');
    txt.addEventListener('input', () => { ok.disabled = !txt.value.trim(); });
    ok.addEventListener('click', () => _aceiteConfirmarRecusa(tipo, id, txt.value.trim()));
    txt.focus();
}
function _aceiteConfirmarRecusa(tipo, id, motivo) {
    if (!motivo) return;
    fecharModalAgenda();
    const r = _aceiteBuscar(tipo, id);   // relido: outro usuario/aba pode ter mexido enquanto digitava
    if (!r) return;
    const m = r.reg, agora = Date.now();
    if (!m[r.hist]) m[r.hist] = [];
    if (r.med) {
        _agdRegistrar(m.historico, 'recusado', { motivo, de: { data: m.data, hora: m.hora || '' } });
        m.recusa = { por: r.eu.id, para: m.aceite.por, motivo, em: agora };
        m.status = 'A reagendar';
        delete m.aceite;
        delete m.aviso_cliente;
        m.usuario_id = null; m.responsavel_nome = '';
        m.data = ''; m.hora = '';
    } else {
        _agdRegistrar(m.inst_historico, 'recusado', { motivo, de: { data: m.data_entrega || '', hora: m.inst_hora || '' } });
        m.inst_recusa = { por: r.eu.id, para: m.inst_aceite.por, motivo, em: agora };
        delete m.inst_aceite;
        delete m.inst_aviso_cliente;
        m.inst_agendado = false;
        m.data_entrega = null;
        m.inst_hora = '';
        definirInstalador(m, { id: null, nome: '' });
    }
    _aceiteRedesenhar(r.med);
    toast('Agendamento recusado. Quem destinou foi avisado.', 'info');
}
// "Reagendar" do aviso de recusa: abre o formulario com os dados que ficaram.
function aceiteReagendar(tipo, id) {
    if (tipo === 'med') {
        if (document.getElementById('medicoes-container')) { mostrarViewPCP('medicoes'); editarMedicao(id); }
        else window.location.href = 'pcp.html?view=medicoes&reagendarmed=' + encodeURIComponent(id);
        return;
    }
    // Instalacao ainda agendada (aceite vencido): abre o reagendamento dela.
    const p = db.pedidos.find(x => x.id == id);
    if (!p || !_instPendente(p)) { irParaAgendaInstalacao(id); return; }
    if (document.getElementById('inst-form')) { mostrarViewPCP('agenda'); reagendarInstalacao(id); }
    else window.location.href = 'pcp.html?view=agenda&pedido=' + encodeURIComponent(id) + '&reagendar=1';
}

// Usuarios ativos e os nomes avulsos ja usados em instalacoes e medicoes.
function _agdProfissionais() {
    const lista = db.usuarios.filter(u => u.ativo).map(u => {
        const papel = (db.papeis || []).find(p => p.id === u.papel_id);
        return { chave: 'u:' + u.id, nome: u.nome, sub: papel ? papel.nome : 'Instalações e Medições' };
    });
    const vistos = new Set(lista.map(x => x.chave));
    const avulso = nome => {
        const pessoa = resolverPessoa(nome);
        const ch = _profChave(pessoa.id, pessoa.nome);
        if (!ch || vistos.has(ch)) return;
        vistos.add(ch);
        lista.push({ chave: ch, nome: String(nome).trim(), sub: 'Profissional externo' });
    };
    db.pedidos.forEach(p => { if (!p.usuario_instalacao_id && p.instalador_nome) avulso(p.instalador_nome); });
    (db.medicoes || []).forEach(m => { if (!m.usuario_id && m.responsavel_nome) avulso(m.responsavel_nome); });
    return lista;
}
// nomeDigitado: o texto de "Outro" ainda nao gravado (a chave perde acentos).
function _agdProfInfo(chave, nomeDigitado) {
    if (!chave) return null;
    const achado = _agdProfissionais().find(x => x.chave === chave);
    if (achado) return achado;
    if (chave.startsWith('u:')) return { chave, nome: nomeUsuario(+chave.slice(2)) || 'Usuário removido', sub: 'Usuário inativo' };
    return { chave, nome: (nomeDigitado || '').trim() || chave.slice(2), sub: 'Profissional externo' };
}

// Seletor de profissional: lista + "Outro" (nome digitado, ex.: terceirizado).
function _agdPreencherProf(id, chaveAtual, vazio) {
    const sel = document.getElementById(id);
    if (!sel) return;
    const lista = _agdProfissionais();
    if (chaveAtual && !lista.some(x => x.chave === chaveAtual)) lista.push(_agdProfInfo(chaveAtual));
    sel.innerHTML = `<option value="">${escapeHtml(vazio || 'Selecione')}</option>` +
        lista.map(x => `<option value="${escapeHtml(x.chave)}">${escapeHtml(x.nome)}</option>`).join('') +
        '<option value="__outro">+ Outro (digitar nome)…</option>';
    sel.value = chaveAtual || '';
    const outro = document.getElementById(id + '-outro');
    if (outro) { outro.value = ''; outro.hidden = true; }
}
function _agdProfMudou(id) {
    const sel = document.getElementById(id), outro = document.getElementById(id + '-outro');
    if (!sel || !outro) return;
    outro.hidden = sel.value !== '__outro';
    if (!outro.hidden) outro.focus();
}
function _agdLerProf(id) {
    const nada = { chave: '', pessoa: { id: null, nome: '' } };
    const sel = document.getElementById(id);
    if (!sel || !sel.value) return nada;
    if (sel.value === '__outro') {
        const pessoa = resolverPessoa(document.getElementById(id + '-outro')?.value);
        return { chave: _profChave(pessoa.id, pessoa.nome), pessoa };
    }
    if (sel.value.startsWith('u:')) return { chave: sel.value, pessoa: { id: +sel.value.slice(2), nome: '' } };
    const info = _agdProfInfo(sel.value);
    return { chave: sel.value, pessoa: { id: null, nome: info ? info.nome : sel.value.slice(2) } };
}

// Duracao: o padrao do tipo de servico vem marcado; da para ajustar por agendamento.
function _agdPreencherDur(id, tipo, valor) {
    const sel = document.getElementById(id);
    if (!sel) return;
    const padrao = _agdDurPadrao(tipo);
    const opcoes = [...new Set([..._AGD_DURACOES, padrao, ...(valor ? [+valor] : [])])].sort((a, b) => a - b);
    sel.innerHTML = opcoes.map(m => `<option value="${m}">${_agdFmtDur(m)}${m === padrao ? ' (padrão)' : ''}</option>`).join('');
    sel.value = String(valor || padrao);
}

// Acesso a agenda de medicoes ('med') ou de instalacoes ('inst') na Producao (pcp.html):
// o mesmo que da acesso a essa agenda la.
function _agdTemAcessoProducao(tipo) {
    return temAcesso(tipo === 'med' ? 'producao.medicoes' : 'producao.agenda', 'visualizar');
}

// Tudo o que ocupa a agenda de algum profissional.
// Medicao/instalacao que o usuario nao veria hoje (sem acesso a agenda dela na Producao,
// sem o painel completo e sem ser dele) vem `restrito`: so "Medicao"/"Instalacao", sem cliente.
function _agdCompromissos() {
    const cfg = getAgendaConfig();
    const out = [];
    const painel = vePainelCompleto();
    const veInst = painel || _agdTemAcessoProducao('inst'), veMed = painel || _agdTemAcessoProducao('med');
    db.pedidos.forEach(p => {
        if (normalizarStatus(p.status) !== 'Pronto p/ Instalação' || !_instAgendada(p)) return;
        const ini = _agdMin(p.inst_hora), prof = _instProf(p);
        if (!p.data_entrega || ini === null || !prof) return;
        const restrito = !veInst && !pedidoEhMeu(p);
        out.push({ tipo: 'inst', id: p.id, prof, data: p.data_entrega, ini, fim: ini + (+p.inst_duracao || +cfg.dur_inst),
            rotulo: restrito ? 'Instalação' : `Instalação #${formatPedidoId(p.id)}`, cliente: restrito ? '' : p.clienteNome || '',
            pendente: _aceitePend(p.inst_aceite), restrito });
    });
    (db.medicoes || []).forEach(m => {
        if (m.status !== 'Agendado') return;
        const ini = _agdMin(m.hora), prof = _medProf(m);
        if (!m.data || ini === null || !prof) return;
        const restrito = !veMed && !medicaoEhMinha(m);
        out.push({ tipo: 'med', id: m.id, prof, data: m.data, ini, fim: ini + (+m.duracao || +cfg.dur_med),
            rotulo: 'Medição', cliente: restrito ? '' : m.clienteNome || '', pendente: _aceitePend(m.aceite), restrito });
    });
    // Compromissos e bloqueios da propria agenda: o rotulo ja vem com a privacidade
    // aplicada (quem nao e o dono nem Administrador nao ve descricao nem motivo).
    const uid = getUsuarioLogado()?.id, adm = ehAdministrador();
    (db.agenda_eventos || []).forEach(ev => {
        if (!ev || !ev.prof) return;
        const v = AgendaCore.visivel(ev, uid, adm);
        const dono = AgendaCore.podeGerenciar(ev.prof, uid, adm);
        const rotulo = !dono ? v.titulo
            : ev.tipo === 'compromisso' ? 'Compromisso' + (v.descricao ? ': ' + v.descricao : '')
            : 'Bloqueio: ' + (v.descricao || _AGD_BLOQ_ROTULOS[ev.bloqueio] || 'Bloqueio');
        AgendaCore.ocupacoesDoEvento(ev, cfg).forEach(o =>
            out.push({ tipo: ev.tipo === 'compromisso' ? 'comp' : 'bloq', id: ev.id, prof: ev.prof, data: o.data, ini: o.ini, fim: o.fim, rotulo, cliente: '' }));
    });
    return out;
}
const _AGD_BLOQ_ROTULOS = { horario: 'Horário', dia: 'Dia inteiro', folga: 'Folga', ferias: 'Férias' };
function _agdDoDia(prof, data, ignorar) {
    return _agdCompromissos()
        .filter(c => c.prof === prof && c.data === data && !(ignorar && c.tipo === ignorar.tipo && c.id == ignorar.id))
        .sort((a, b) => a.ini - b.ini);
}
// Compromissos do profissional que se sobrepoem a [hora, hora + dur).
function _agdConflitos(q) {
    const ini = _agdMin(q.hora);
    if (!q.prof || !q.data || ini === null) return [];
    const fim = ini + (+q.dur || 0);
    return _agdDoDia(q.prof, q.data, q.ignorar).filter(c => c.ini < fim && ini < c.fim);
}
function _agdDescComp(c) {
    return `${c.rotulo}${c.cliente ? ' — ' + c.cliente : ''} (${_agdHHMM(c.ini)}–${_agdHHMM(c.fim)})`;
}

// Grade do dia. Verde: cabe a duracao escolhida. Vermelho: horario ocupado.
// Cinza: passado, fora do expediente ou a duracao esbarra em outro compromisso.
function _agdDisponibilidade(q) {
    const cfg = getAgendaConfig();
    const ini = _agdMin(cfg.inicio) ?? 480, fimDia = _agdMin(cfg.fim) ?? 1080, passo = +cfg.passo || 60;
    const dur = +q.dur || passo;
    const hoje = _agdHoje();
    const agora = new Date(), agoraMin = agora.getHours() * 60 + agora.getMinutes();
    const comps = q.prof && q.data ? _agdDoDia(q.prof, q.data, q.ignorar) : [];
    const slots = [];
    for (let s = ini; s + passo <= fimDia; s += passo) {
        let estado = 'livre', motivo = 'Disponível';
        const ocup = comps.find(c => c.ini < s + passo && s < c.fim);
        if (q.data < hoje || (q.data === hoje && s <= agoraMin)) { estado = 'indisp'; motivo = 'Horário já passou'; }
        else if (ocup) { estado = 'ocupado'; motivo = 'Ocupado: ' + _agdDescComp(ocup); }
        else if (s + dur > fimDia) { estado = 'indisp'; motivo = `${_agdFmtDur(dur)} passam do fim do expediente (${cfg.fim})`; }
        else {
            const c = comps.find(x => x.ini < s + dur && s < x.fim);
            if (c) { estado = 'indisp'; motivo = `Não cabem ${_agdFmtDur(dur)}: esbarra em ${_agdDescComp(c)}`; }
        }
        slots.push({ hora: _agdHHMM(s), estado, motivo });
    }
    return { slots, livres: slots.filter(x => x.estado === 'livre').map(x => x.hora), compromissos: comps };
}
function _agdSomarDias(data, n) {
    const d = new Date(data + 'T12:00:00'); d.setDate(d.getDate() + n);
    return d.toLocaleDateString('sv-SE');
}
// Primeiro dia (depois de q.data, ate 30 dias) com horario livre.
function _agdProximoDiaLivre(q) {
    let d = q.data < _agdHoje() ? _agdHoje() : q.data;
    for (let i = 0; i < 30; i++) {
        d = _agdSomarDias(d, 1);
        const r = _agdDisponibilidade({ ...q, data: d });
        if (r.livres.length) return { data: d, horas: r.livres };
    }
    return null;
}

// Releitura do que esta gravado (outra aba/usuario pode ter agendado) e
// conferencia final. Devolve false e avisa quando ha conflito.
// So troca um array quando o texto gravado mudou desde a ultima leitura/gravacao desta aba.
function _agdRecarregar() {
    ['sc_ped', 'sc_med', 'sc_agd_ev'].forEach(_dbRecarregarChave);
}
async function _agdValidarDisp(q) {
    _agdDeslocNota = false;
    if (!q.prof || !q.data || !q.hora) return true;
    _agdRecarregar();
    let c = _agdConflitos(q);
    if (c.length) return _agdAvisoConflito(q, c);
    if (q.partes !== undefined) {
        if (!await _agdConferirDeslocamento(q)) return false;
        // A conferencia (rede, janela aberta) demorou: outra aba pode ter ocupado o horario.
        _agdRecarregar();
        c = _agdConflitos(q);
        if (c.length) return _agdAvisoConflito(q, c);
    }
    return true;
}
async function _agdAvisoConflito(q, c) {
    const nome = _agdProfInfo(q.prof, q.profNome)?.nome || 'O profissional';
    await showAlert(`${nome} já tem compromisso nesse período (${_agdFmtData(q.data)}, ${_agdPeriodo(q.hora, q.dur)}):\n\n${
        c.map(x => '• ' + _agdDescComp(x)).join('\n')}\n\nEscolha outro horário — os livres aparecem em verde.`, '⛔');
    return false;
}

// --- Aviso de deslocamento ao agendar ---------------------------------------
// Depois da conferencia de sobreposicao (que bloqueia), olha a visita anterior e a
// proxima do mesmo profissional no dia: da tempo de ir de uma a outra (com a folga)?
// Se nao der, avisa e deixa escolher; sem rede ou sem localizar, nao avisa nada.
let _agdDeslocNota = false;   // true: o deslocamento nao pode ser conferido (vira nota no aviso de sucesso)
function _agdNotaDesloc(msg) { return _agdDeslocNota ? msg + ' Não deu para conferir o deslocamento.' : msg; }

// Enquanto a conferencia espera a rede: Salvar/Agendar ficam travados e dizem o que esta acontecendo.
function _agdConferindo(on) {
    const modal = document.getElementById('agdf-salvar');
    const ids = modal ? ['agdf-salvar', 'agdf-voltar'] : ['inst-btn-agendar', 'med-btn-agendar'];
    ids.forEach(id => {
        const el = document.getElementById(id);
        if (!el) return;
        if (on) {
            if (el.dataset.rotulo === undefined) el.dataset.rotulo = el.textContent;
            el.disabled = true;
            if (id !== 'agdf-voltar') el.textContent = 'Conferindo deslocamento…';
        } else {
            el.disabled = false;
            if (el.dataset.rotulo !== undefined) { el.textContent = el.dataset.rotulo; delete el.dataset.rotulo; }
        }
    });
}

function _agdVisitaEndereco(c) {
    if (c.tipo === 'med') {
        const m = (db.medicoes || []).find(x => x.id == c.id);
        const end = m ? _endMed(m) : '';
        return end ? { end, partes: _partesMedMapa(m) } : null;
    }
    if (c.tipo === 'inst') {
        const p = db.pedidos.find(x => x.id == c.id);
        const cli = p ? db.clientes.find(x => x.id == p.clienteId) : null;
        const end = p ? _endInst(p, cli) : '';
        return end ? { end, partes: _partesInstMapa(p, cli) } : null;
    }
    return null;
}

async function _agdMinutosEntre(a, b) {
    const ga = await _rotaGeo(a.end, a.partes), gb = await _rotaGeo(b.end, b.partes);
    if (!ga || !gb) return null;
    const t = RotasCore.trechosDaRota(await _rotaOsrm('route', [ga, gb]));
    return t && t[0] ? Math.round(t[0].segundos / 60) : null;
}

async function _agdConferirDeslocamento(q) {
    const ini = _agdMin(q.hora), dur = +q.dur || 0, fim = ini + dur;
    if (ini === null) return true;
    const vizinhos = _agdDoDia(q.prof, q.data, q.ignorar).filter(c => c.tipo === 'med' || c.tipo === 'inst')
        .map(c => ({ c, e: _agdVisitaEndereco(c) })).filter(x => x.e);
    const ant = vizinhos.filter(x => x.c.fim <= ini).sort((a, b) => b.c.fim - a.c.fim)[0];
    const prox = vizinhos.filter(x => x.c.ini >= fim).sort((a, b) => a.c.ini - b.c.ini)[0];
    if (!ant && !prox) return true;   // nada para conferir: sem nota
    // Ha vizinho com endereco mas nao da para conferir (sem rotas.js, sem endereco novo): so a nota.
    const novo = typeof RotasCore !== 'undefined' && q.partes ? { end: RotasCore.enderecoDePartes(q.partes), partes: q.partes } : { end: '' };
    if (typeof _rotaGeo !== 'function' || typeof _rotaOsrm !== 'function' || !novo.end) { _agdDeslocNota = true; return true; }

    let desloc = null, timer;
    _agdConferindo(true);
    try {
        desloc = await Promise.race([
            (async () => ({
                antesMin: ant ? await _agdMinutosEntre(ant.e, novo) : null,
                depoisMin: prox ? await _agdMinutosEntre(novo, prox.e) : null,
            }))(),
            new Promise((_, rej) => { timer = setTimeout(() => rej(new Error('tempo')), 8000); }),
        ]);
    } catch (e) { desloc = null; } finally { clearTimeout(timer); _agdConferindo(false); }
    if (!desloc || (ant && desloc.antesMin == null) || (prox && desloc.depoisMin == null)) _agdDeslocNota = true;
    if (!desloc) return true;

    const sit = RotasCore.situacaoEncaixe({
        antes: ant ? { fimMin: ant.c.fim } : null, depois: prox ? { agendadoMin: prox.c.ini } : null,
        novo: { agendadoMin: ini, durMin: dur }, desloc });
    const nome = c => c.rotulo + (c.cliente ? ' — ' + c.cliente : '');
    const msgs = [];
    if (sit.chegaTarde) msgs.push(`Não dá tempo de chegar: ${nome(ant.c)} termina ${RotasCore.hhmm(ant.c.fim)} e o deslocamento até aqui leva ~${desloc.antesMin} min (chegada ${RotasCore.hhmm(sit.chegadaMin)}, folga de ${RotasCore.FOLGA_MIN} min).`);
    if (sit.atrasaProxima) msgs.push(`Não dá tempo de chegar: esta visita termina ${RotasCore.hhmm(sit.chegadaProximaMin - desloc.depoisMin)} e o deslocamento até ${nome(prox.c)} leva ~${desloc.depoisMin} min (chegada ${RotasCore.hhmm(sit.chegadaProximaMin)}, folga de ${RotasCore.FOLGA_MIN} min).`);
    if (!msgs.length) return true;
    return showConfirm(msgs.join('\n\n'), '🚗', 'Agendar mesmo assim', 'Escolher outro horário');
}
function _agdRedesenharAgendas() {
    renderAgenda();
    renderMedicoes();
}

// --- Painel "Disponibilidade do profissional" ---
const _agdDispCtx = {};
function _agdDispEscolher(elId, data, hora) {
    const ctx = _agdDispCtx[elId];
    if (ctx && ctx.onHora) ctx.onHora(data, hora);
}
function _agdDispExpandir(elId) {
    const ctx = _agdDispCtx[elId] || (_agdDispCtx[elId] = {});
    ctx.expandido = true;
    if (ctx.q) _agdRenderDisp(elId, ctx.q);
}
// Sem profissional escolhido o painel mostra todos (usuarios ativos e nomes
// avulsos ja usados), com a situacao de cada um no dia; clicar seleciona.
// Quem tem papel ligado ao servico (instal.../medi...) vem primeiro.
function _agdListaProfissionais(elId, q) {
    const lista = _agdProfissionais();
    if (!lista.length) return '<div class="agd-disp-vazio">' + _agdIco('user', 22) + '<span>Nenhum profissional cadastrado. Cadastre em Configurações → Usuários ou use "+ Outro" no campo Profissional.</span></div>';
    const data = q.data || _agdHoje();
    const alvo = q.tipo === 'med' ? 'medi' : q.tipo === 'inst' ? 'instal' : '';
    const peso = x => (alvo && _agdNorm(x.sub).includes(alvo) ? 0 : 1);
    lista.sort((a, b) => peso(a) - peso(b) || a.nome.localeCompare(b.nome, 'pt-BR'));
    const itens = lista.map(x => {
        const d = _agdDisponibilidade({ ...q, prof: x.chave, data });
        let [txt, cls] = d.livres.length ? [d.livres.length + (d.livres.length === 1 ? ' horário livre' : ' horários livres'), 'agd-pill-verde']
            : d.compromissos.length ? ['Agenda cheia', 'agd-pill-verm'] : ['Indisponível', 'agd-pill-cinza'];
        if (!d.livres.length) {   // dia sem vaga: mostra quando ha a proxima
            const n = _agdProximoDiaLivre({ ...q, prof: x.chave, data });
            if (n) { txt = 'Próx. vaga: ' + _agdFmtData(n.data).slice(0, 5); }
        }
        return `<button type="button" class="agd-disp-prof agd-disp-prof-btn" onclick="_agdDispEscolherProf('${elId}', '${escapeHtml(x.chave).replace(/'/g, '&#39;')}')" title="Ver a disponibilidade de ${escapeHtml(x.nome)}">
            <span class="agd-avatar">${_agdIco('user', 18)}</span>
            <span class="agd-disp-prof-info"><strong>${escapeHtml(x.nome)}</strong><small>${escapeHtml(x.sub)}</small></span>
            <span class="agd-pill ${cls}">${txt}</span>
        </button>`;
    }).join('');
    return `<div class="agd-disp-dia">${data === _agdHoje() ? 'Hoje' : _agdFmtData(data)} · escolha o profissional</div><div class="agd-disp-lista">${itens}</div>`;
}
function _agdDispEscolherProf(elId, chave) {
    const ctx = _agdDispCtx[elId];
    if (ctx && ctx.onProf) ctx.onProf(chave);
}

// Recarrega usuarios/papeis (cadastro feito em outra aba) e atualiza os
// seletores de profissional sem perder o que ja estava escolhido.
function _agdAtualizarListaProf() {
    _dbRecarregarChave('sc_usr');
    _dbRecarregarChave('sc_pap');
    [['inst-prof', 'Selecione'], ['med-prof', '— A definir —'], ['agdf-usu', '— A definir —']].forEach(([id, vazio]) => {
        const sel = document.getElementById(id);
        if (!sel || sel.value === '__outro') return;
        const vazioAtual = sel.options[0] ? sel.options[0].text : vazio;
        _agdPreencherProf(id, sel.value, vazioAtual);
    });
}

function _agdRenderDisp(elId, q) {
    const el = document.getElementById(elId);
    if (!el) return;
    const ctx = _agdDispCtx[elId] || (_agdDispCtx[elId] = {});
    const chaveCtx = (q.prof || '') + '|' + (q.data || '') + '|' + (q.dur || '');
    if (ctx.chave !== chaveCtx) { ctx.expandido = false; ctx.chave = chaveCtx; }
    ctx.q = q;
    const cab = `<div class="agd-disp-tit"><span class="agd-disp-tit-ico">${_agdIco('user', 15)}</span>Disponibilidade do profissional</div>`;
    if (!q.prof) { el.innerHTML = cab + _agdListaProfissionais(elId, q); return; }
    if (!q.data) {
        el.innerHTML = cab + `<div class="agd-disp-vazio">${_agdIco('cal', 22)}<span>Selecione a data para ver os horários livres.</span></div>`;
        return;
    }
    const info = _agdProfInfo(q.prof, q.profNome);
    const d = _agdDisponibilidade(q);
    const hoje = _agdHoje();
    const rotDia = q.data === hoje ? 'Hoje'
        : new Date(q.data + 'T12:00:00').toLocaleDateString('pt-BR', { weekday: 'long' }).replace(/^./, c => c.toUpperCase());
    const ocupados = d.compromissos.length;
    const [badgeTxt, badgeCls] = d.livres.length ? ['Disponível', 'agd-pill-verde']
        : ocupados ? ['Agenda cheia', 'agd-pill-verm'] : ['Indisponível', 'agd-pill-cinza'];

    const grade = d.slots.map(s => {
        const sel = q.hora && s.hora === _agdHHMM(_agdMin(q.hora)) ? ' agd-slot-sel' : '';
        const tit = escapeHtml(`${s.hora} · ${s.motivo}`);
        return s.estado === 'livre'
            ? `<button type="button" class="agd-slot agd-slot-livre${sel}" title="${tit}" onclick="_agdDispEscolher('${elId}','${q.data}','${s.hora}')">${s.hora}</button>`
            : `<span class="agd-slot agd-slot-${s.estado}${sel}" title="${tit}" aria-disabled="true">${s.hora}</span>`;
    }).join('');

    let prox = d.livres.map(h => ({ data: q.data, hora: h })), proxNota = '';
    if (!prox.length) {
        const n = _agdProximoDiaLivre(q);
        if (n) { prox = n.horas.map(h => ({ data: n.data, hora: h })); proxNota = `Sem horário livre neste dia. Próximo dia com vaga: ${_agdFmtData(n.data)}`; }
        else proxNota = 'Nenhum horário livre nos próximos 30 dias.';
    }
    const visiveis = ctx.expandido ? prox : prox.slice(0, 4);
    const resto = prox.length - visiveis.length;
    const chips = visiveis.map(x => `<button type="button" class="agd-chip" onclick="_agdDispEscolher('${elId}','${x.data}','${x.hora}')" title="${escapeHtml(_agdFmtData(x.data) + ' às ' + x.hora)}">${x.data !== q.data ? _agdFmtData(x.data).slice(0, 5) + ' ' : ''}${x.hora}</button>`).join('')
        + (resto > 0 ? `<button type="button" class="agd-chip agd-chip-mais" onclick="_agdDispExpandir('${elId}')" title="Ver todos os horários livres">+${resto}</button>` : '');

    const conflitos = q.hora ? _agdConflitos(q) : [];
    const aviso = conflitos.length
        ? `<div class="agd-disp-aviso" role="alert">⛔ ${escapeHtml(_agdPeriodo(q.hora, q.dur))} conflita com ${escapeHtml(conflitos.map(_agdDescComp).join('; '))}</div>`
        : (q.hora ? `<div class="agd-disp-ok">✓ ${escapeHtml(_agdPeriodo(q.hora, q.dur))} livre para ${escapeHtml(info.nome)}</div>` : '');

    const lista = ocupados
        ? `<div class="agd-disp-comp"><div class="agd-disp-sub">Compromissos do dia</div>${d.compromissos.map(c =>
            `<div class="agd-disp-comp-item"><span class="agd-pill ${c.tipo === 'inst' ? 'agd-pill-azul' : c.tipo === 'bloq' ? 'agd-pill-verm' : 'agd-pill-amar'}">${c.tipo === 'inst' ? 'Instalação' : c.tipo === 'bloq' ? 'Bloqueio' : c.tipo === 'comp' ? 'Compromisso' : 'Medição'}</span><span>${_agdHHMM(c.ini)}–${_agdHHMM(c.fim)}</span><span class="agd-disp-comp-cli">${escapeHtml(c.cliente || c.rotulo)}</span></div>`).join('')}</div>`
        : '';

    el.innerHTML = cab + `
        <div class="agd-disp-prof">
            <span class="agd-avatar">${_agdIco('user', 18)}</span>
            <span class="agd-disp-prof-info"><strong>${escapeHtml(info.nome)}</strong><small>${escapeHtml(info.sub)}</small></span>
            <span class="agd-pill ${badgeCls}">${badgeTxt}</span>
        </div>
        <div class="agd-disp-dia">${escapeHtml(rotDia)} - ${_agdFmtData(q.data)} <small>· ${escapeHtml(_agdFmtDur(q.dur))} por serviço</small></div>
        <div class="agd-disp-leg">
            <span><i class="agd-dot agd-dot-livre"></i>Horários disponíveis</span>
            <span><i class="agd-dot agd-dot-ocupado"></i>Horários ocupados</span>
            <span><i class="agd-dot agd-dot-indisp"></i>Não disponível</span>
        </div>
        <div class="agd-disp-grade">${grade}</div>
        ${aviso}
        <div class="agd-disp-sub">Próximos horários livres:</div>
        ${proxNota ? `<div class="agd-disp-nota">${escapeHtml(proxNota)}</div>` : ''}
        <div class="agd-disp-prox">${chips}</div>
        ${lista}`;
}

// --- Lista de horarios no campo Horario (medicao e instalacao) ---------------
// Reusa _agdDisponibilidade: livres clicaveis; ocupados e indisponiveis riscados.
// O campo continua digitavel (ex.: 10:30). getQ() devolve {tipo, prof, data, dur, ignorar}.
let _agdPickerEl = null;
function _agdPickerFechar() {
    if (_agdPickerEl) { _agdPickerEl.remove(); _agdPickerEl = null; }
}
let _agdPickerAbertoEm = 0;
function _agdPickerAbrir(input, getQ) {
    _agdPickerFechar();
    _agdPickerAbertoEm = Date.now();
    let q;
    try { q = getQ(); } catch (e) { return; }
    const d = _agdDisponibilidade({ ...q, data: q.data || _agdHoje() });
    const pop = document.createElement('div');
    pop.className = 'agd-hpick';
    pop.setAttribute('role', 'listbox');
    pop.innerHTML = d.slots.map(s => {
        const tit = escapeHtml(`${s.hora} · ${s.motivo}`);
        return s.estado === 'livre'
            ? `<button type="button" class="agd-hpick-item agd-hpick-livre" data-hora="${s.hora}" role="option" title="${tit}">${s.hora}</button>`
            : `<span class="agd-hpick-item agd-hpick-${s.estado}" data-hora="${s.hora}" role="option" aria-disabled="true" title="${tit}">${s.hora}</span>`;
    }).join('') || '<span class="agd-hpick-vazio">Sem horários no expediente.</span>';
    pop.addEventListener('mousedown', e => e.preventDefault());   // mantem o foco no campo
    pop.addEventListener('click', e => {
        const b = e.target.closest('.agd-hpick-livre');
        if (!b) return;
        input.value = b.dataset.hora;
        input.classList.remove('agd-erro');
        _agdPickerFechar();
        input.dispatchEvent(new Event('input', { bubbles: true }));
        input.dispatchEvent(new Event('change', { bubbles: true }));
    });
    document.body.appendChild(pop);
    const r = input.getBoundingClientRect();
    pop.style.left = r.left + 'px';
    pop.style.minWidth = Math.max(r.width, 200) + 'px';
    const alt = pop.offsetHeight;
    const abaixo = window.innerHeight - r.bottom;
    pop.style.top = (abaixo >= Math.min(alt, 240) || r.top < alt ? r.bottom + 4 : r.top - alt - 4) + 'px';
    pop._input = input;
    _agdPickerEl = pop;
}
function _agdPickerAnexar(input, getQ) {
    if (!input || input.dataset.agdPicker) return;
    input.dataset.agdPicker = '1';
    const abrir = () => _agdPickerAbrir(input, getQ);
    input.addEventListener('focus', abrir);
    input.addEventListener('click', abrir);
    input.addEventListener('blur', () => setTimeout(() => { if (_agdPickerEl && _agdPickerEl._input === input) _agdPickerFechar(); }, 120));
    ['input', 'change'].forEach(ev => input.addEventListener(ev, () => { if (_agdPickerEl && _agdPickerEl._input === input) _agdPickerAbrir(input, getQ); }));
    input.addEventListener('keydown', e => {
        if (e.key === 'Escape') { if (_agdPickerEl) { _agdPickerFechar(); e.stopPropagation(); } return; }
        if (!['ArrowDown', 'ArrowUp', 'Enter'].includes(e.key)) return;
        if (!_agdPickerEl) { if (e.key === 'ArrowDown') { abrir(); e.preventDefault(); } return; }
        const itens = [..._agdPickerEl.querySelectorAll('.agd-hpick-livre')];
        const at = _agdPickerEl.querySelector('.agd-hpick-ativo');
        let i = itens.indexOf(at);
        if (e.key === 'Enter') { if (at) { e.preventDefault(); at.click(); } return; }
        // Seta sem item destacado: deixa o campo de hora nativo (digitar 10:30 pelo teclado);
        // so a 1a seta para baixo passa a navegar na lista.
        if (!at && e.key === 'ArrowUp') return;
        e.preventDefault();
        if (!itens.length) return;
        i = e.key === 'ArrowDown' ? (i + 1) % itens.length : (i <= 0 ? itens.length - 1 : i - 1);
        at && at.classList.remove('agd-hpick-ativo');
        itens[i].classList.add('agd-hpick-ativo');
        itens[i].scrollIntoView({ block: 'nearest' });
    });
}
document.addEventListener('mousedown', e => {
    if (_agdPickerEl && !_agdPickerEl.contains(e.target) && e.target !== _agdPickerEl._input) _agdPickerFechar();
});
// No celular o teclado virtual dispara resize/scroll logo ao abrir: ignora esses 300 ms.
const _agdPickerRecente = () => Date.now() - _agdPickerAbertoEm < 300;
window.addEventListener('resize', () => { if (!_agdPickerRecente()) _agdPickerFechar(); });
document.addEventListener('scroll', e => { if (_agdPickerEl && !_agdPickerEl.contains(e.target) && !_agdPickerRecente()) _agdPickerFechar(); }, true);

// Duracao padrao por tipo de servico e expediente usado na grade.
function abrirConfigAgenda() {
    const c = getAgendaConfig();
    const opt = sel => _AGD_DURACOES.map(m => `<option value="${m}"${m === +sel ? ' selected' : ''}>${_agdFmtDur(m)}</option>`).join('');
    const corpo = `<div class="agd-form">
        <div class="form-group"><label for="agdc-inst">Duração padrão — Instalação</label><select id="agdc-inst">${opt(c.dur_inst)}</select></div>
        <div class="form-group"><label for="agdc-med">Duração padrão — Medição</label><select id="agdc-med">${opt(c.dur_med)}</select></div>
        <div class="form-group"><label for="agdc-ini">Início do expediente</label><input type="time" id="agdc-ini" value="${escapeHtml(c.inicio)}"></div>
        <div class="form-group"><label for="agdc-fim">Fim do expediente</label><input type="time" id="agdc-fim" value="${escapeHtml(c.fim)}"></div>
        <div class="form-group agd-form-largo"><label for="agdc-passo">Intervalo entre horários da grade</label>
            <select id="agdc-passo"><option value="30"${+c.passo === 30 ? ' selected' : ''}>30 min</option><option value="60"${+c.passo === 60 ? ' selected' : ''}>1 hora</option></select></div>
    </div>
    <small class="agd-form-dica">A duração padrão vem marcada em cada novo agendamento e pode ser ajustada individualmente. Vale para as duas agendas.</small>`;
    const o = _agdAbrirModal('Duração padrão dos serviços', corpo,
        `<button type="button" class="btn btn-outline btn-sm" onclick="fecharModalAgenda()">Cancelar</button>
         <button type="button" class="btn btn-success btn-sm" id="agdc-salvar">Salvar</button>`);
    o.querySelector('#agdc-salvar').onclick = async () => {
        const ini = document.getElementById('agdc-ini').value, fim = document.getElementById('agdc-fim').value;
        if (!ini || !fim || _agdMin(fim) <= _agdMin(ini)) { await showAlert('O fim do expediente precisa ser depois do início.', '⚠️'); return; }
        localStorage.setItem('sc_agd_cfg', JSON.stringify({
            dur_inst: +document.getElementById('agdc-inst').value,
            dur_med:  +document.getElementById('agdc-med').value,
            inicio: ini, fim, passo: +document.getElementById('agdc-passo').value,
        }));
        fecharModalAgenda();
        // Os formularios abertos passam a sugerir a nova duracao padrao.
        _agdPreencherDur('inst-dur', 'inst');
        _agdPreencherDur('med-dur', 'med');
        _agdRedesenharAgendas();
        toast('Duração padrão salva!', 'success');
    };
}

// --- MEDICOES ---------------------------------------------------------------
function _medPill(m, hoje) {
    if (m.status === 'Realizado') return 'realizado';
    if (m.status === 'A reagendar') return 'reagendar';
    if (m.data && m.data < hoje) return 'atrasado';
    return _aceitePend(m.aceite) ? 'aceite' : 'agendado';
}

function _medAtualizar() {
    syncDB();
    renderMedicoes();
    renderDashboardMedicoes();
    renderAgenda();   // a disponibilidade e compartilhada
}

// Painel ao lado do formulario "Agendar Visita de Medicao".
function _medAtualizarDisp() {
    if (!document.getElementById('med-disp')) return;
    _agdDispCtx['med-disp'] = Object.assign(_agdDispCtx['med-disp'] || {}, { onHora: (d, h) => {
        document.getElementById('med-data').value = d;
        document.getElementById('med-hora').value = h;
        _medAtualizarDisp();
    } });
    const prof = _agdLerProf('med-prof');
    _agdPickerAnexar(document.getElementById('med-hora'), () => {
        const p = _agdLerProf('med-prof');
        return { tipo: 'med', prof: p.chave, profNome: p.pessoa.nome, data: document.getElementById('med-data')?.value || '',
            dur: parseInt(document.getElementById('med-dur')?.value) || _agdDurPadrao('med') };
    });
    _agdDispCtx['med-disp'].onProf = ch => { _agdPreencherProf('med-prof', ch, '— A definir —'); _medAtualizarDisp(); };
    _agdRenderDisp('med-disp', {
        tipo: 'med', prof: prof.chave, profNome: prof.pessoa.nome,
        data: document.getElementById('med-data')?.value || '',
        hora: document.getElementById('med-hora')?.value || '',
        dur:  parseInt(document.getElementById('med-dur')?.value) || _agdDurPadrao('med'),
    });
}

function renderMedicoes() {
    if (!document.getElementById('med-pend-lista')) return;
    const hoje  = _agdHoje();
    const todas = db.medicoes || [];
    const pend  = todas.filter(m => m.status === 'Agendado' || m.status === 'A reagendar');   // recusadas ficam no topo, "A reagendar"
    const real  = todas.filter(m => m.status === 'Realizado');
    const filtra = (lista, chave) => {
        const b = _agdNorm(_agdBusca[chave]);
        return b ? lista.filter(m => _agdNorm(m.clienteNome).includes(b)) : lista;
    };
    const linha = m => _agdLinha({
        onclick: `abrirDetalheMedicao(${m.id})`,
        nome: m.clienteNome, tel: m.clienteTel, end: _endMed(m),
        data: m.data, hora: m.hora, pill: _medPill(m, hoje),
    });
    const pendF = filtra(pend, 'medPend').sort((a, b) => (b.status === 'A reagendar') - (a.status === 'A reagendar')
        || _agdCmp(_agdChave(a.data, a.hora), _agdChave(b.data, b.hora)));
    const realF = filtra(real, 'medReal').sort((a, b) =>
        _agdCmp(_agdChave(b.data, b.hora), _agdChave(a.data, a.hora)) || (b.realizado_em || 0) - (a.realizado_em || 0));
    _agdPreencher('med-pend', pendF.map(linha), pend.length, 'Nenhuma visita agendada. Use o formulário acima para agendar.', _agdBusca.medPend, ['agendamento', 'agendamentos']);
    _agdPreencher('med-real', realF.map(linha), real.length, 'Nenhuma medição realizada ainda.', _agdBusca.medReal);
    _medAtualizarDisp();
}

function _aceiteLinhasDetalhe(aceite, recusa) {
    const l = [];
    if (_aceitePend(aceite)) l.push(['Aceite', 'Aguardando aceite']);
    else if (aceite && aceite.status === 'aceito') l.push(['Aceite', 'Aceito' + (aceite.resp_em ? ' em ' + _agdFmtMomento(aceite.resp_em) : '')]);
    if (recusa) l.push(['Recusada', escapeHtml(`${nomeUsuario(recusa.por)}: ${recusa.motivo}`)]);
    return l;
}

// opts.soLeitura: so os dados, sem botoes de acao (aberto pela Agenda por quem nao
// tem acesso a agenda de medicoes da Producao).
function abrirDetalheMedicao(id, opts) {
    const soLeitura = !!(opts && opts.soLeitura);
    const m = (db.medicoes || []).find(x => x.id == id);
    if (!m) return;
    const pend = m.status === 'Agendado';
    const reag = m.status === 'A reagendar';
    const ped  = _medPedidoVinculado(m);
    const tel  = m.clienteTel
        ? `<a href="https://wa.me/55${m.clienteTel.replace(/\D/g, '')}" target="_blank" rel="noopener">${escapeHtml(m.clienteTel)}</a>`
        : '—';
    const dur = +m.duracao || _agdDurPadrao('med');
    const corpo = `<div class="agd-det-topo">${_agdPill(_medPill(m, _agdHoje()))}</div>` + _agdCampos([
        ['Cliente',     escapeHtml(m.clienteNome || '—')],
        ['Telefone',    tel],
        ['Endereço',    escapeHtml(_endMed(m) || '—') + linkIrParaHtml(_endMed(m), 'agd-ir agd-ir-det')],
        ['Data',        _agdFmtData(m.data)],
        ['Horário',     escapeHtml(m.hora ? _agdPeriodo(m.hora, dur) : '—')],
        ['Duração',     escapeHtml(_agdFmtDur(dur))],
        ['Responsável', escapeHtml(_medNomeResp(m) || 'A definir')],
        ..._aceiteLinhasDetalhe(m.aceite, m.recusa),
        m.agendado_por ? ['Agendado por', escapeHtml(nomeUsuario(m.agendado_por))] : null,
        ['Observações', escapeHtml(m.obs || '—')],
        m.realizado_em ? ['Confirmada em', _agdFmtMomento(m.realizado_em) + (m.realizado_via === 'pedido' ? ' (ao salvar o pedido)' : '')] : null,
        ped ? ['Pedido', `#${formatPedidoId(ped.id)}`] : null,
    ]) + _agdHistorico(m.historico);
    // Com pedido ja criado o botao abre esse pedido: o agendamento nunca gera dois.
    const btnPedido = ped
        ? `<button class="btn btn-outline btn-sm" onclick="criarPedidoDaMedicao(${m.id})" title="Abre o pedido criado a partir deste agendamento">📄 Abrir Pedido #${formatPedidoId(ped.id)}</button>`
        : (pend ? `<button class="btn btn-sm" onclick="criarPedidoDaMedicao(${m.id})" title="Abre o formulário de pedido com o cliente já preenchido. Ao salvar, a medição vai para Realizados.">+ Criar Pedido</button>` : '');
    const rodape = soLeitura ? ''
        : reag
        ? `<button class="btn btn-outline btn-sm btn-danger" onclick="excluirMedicao(${m.id})">🗑️ Excluir</button>
           <button class="btn btn-success btn-sm" onclick="editarMedicao(${m.id})">📅 Reagendar</button>`
        : pend
        ? `<button class="btn btn-outline btn-sm btn-danger" onclick="cancelarMedicao(${m.id})">✕ Cancelar agendamento</button>
           <button class="btn btn-outline btn-sm" onclick="fecharModalAgenda();imprimirAgendamentoMedicao(${m.id})">🖨️ Documento</button>
           <button class="btn btn-outline btn-sm" onclick="editarMedicao(${m.id})">✏️ Editar</button>
           <button class="btn btn-outline btn-sm" onclick="reagendarMedicao(${m.id})">📅 Reagendar</button>
           ${btnPedido}
           <button class="btn btn-success btn-sm" onclick="confirmarMedicao(${m.id})">✓ Confirmar medição</button>`
        : `<button class="btn btn-outline btn-sm btn-danger" onclick="excluirMedicao(${m.id})">🗑️ Excluir</button>
           <button class="btn btn-outline btn-sm" onclick="fecharModalAgenda();imprimirAgendamentoMedicao(${m.id})">🖨️ Documento</button>
           ${btnPedido}`;
    _agdAbrirModal('Visita de medição', corpo, rodape);
}

// Estado de responsavel/data/hora antes de editar (medicao recusada conta como nova).
function _medAntesAceite(m) {
    return m.status === 'A reagendar' ? null : { uid: m.usuario_id || null, data: m.data, hora: m.hora || '' };
}
// Medicao recusada que recebe novo horario volta para Agendado.
function _medFecharReagendar(m) {
    if (m.status !== 'A reagendar') return;
    m.status = 'Agendado';
    delete m.recusa;
}

function _medDisp(id) {
    return { disp: { tipo: 'med', ignorar: { tipo: 'med', id }, partes: v => {
        if (v.end) return v.end;
        const m = (db.medicoes || []).find(x => x.id == id);
        return m ? _partesMedConferir(m) : null;
    } } };
}

function editarMedicao(id) {
    const m = (db.medicoes || []).find(x => x.id == id);
    if (!m) return;
    _agdFormulario('Editar agendamento', [
        { id: 'tel',  label: 'Telefone',    tipo: 'text', valor: m.clienteTel },
        { id: 'end',  tipo: 'endereco', valor: m.rua === undefined ? EnderecoCore.partesDeRegistroAntigo(m.endereco, m.cidade) : m, obrig: true },
        { id: 'usu',  label: 'Responsável pela medição', tipo: 'profissional', valor: _medProf(m) },
        { id: 'data', label: 'Data da visita', tipo: 'date', valor: m.data, obrig: true },
        { id: 'hora', label: 'Horário',     tipo: 'time', valor: m.hora },
        { id: 'dur',  label: 'Duração do serviço', tipo: 'duracao', valor: m.duracao },
        { id: 'obs',  label: 'Observações', tipo: 'textarea', valor: m.obs, largo: true },
    ], v => {
        const atual = (db.medicoes || []).find(x => x.id == id);   // relido na validacao
        if (!atual) return;
        const antes = _medAntesAceite(atual);
        atual.clienteTel = v.tel; Object.assign(atual, v.end, { endereco: EnderecoCore.textoEndereco(v.end) }); atual.data = v.data; atual.hora = v.hora;
        atual.duracao = v.dur; atual.obs = v.obs;
        _medDefinirResponsavel(atual, v.usu.pessoa);
        _medFecharReagendar(atual);
        _aceiteAplicar(atual, 'aceite', antes, atual.usuario_id, atual.data, atual.hora);
        _medAtualizar();
        toast(_agdNotaDesloc('Agendamento atualizado!'), 'success');
        abrirDetalheMedicao(id);
    }, () => abrirDetalheMedicao(id), _medDisp(id));
}

function reagendarMedicao(id) {
    const m = (db.medicoes || []).find(x => x.id == id);
    if (!m) return;
    _agdFormulario('Reagendar visita', [
        { id: 'usu',  label: 'Responsável pela medição', tipo: 'profissional', valor: _medProf(m) },
        { id: 'dur',  label: 'Duração do serviço', tipo: 'duracao', valor: m.duracao },
        { id: 'data', label: 'Nova data', tipo: 'date', valor: m.data, obrig: true },
        { id: 'hora', label: 'Horário',   tipo: 'time', valor: m.hora },
        { id: 'obs',  label: 'Observações', tipo: 'textarea', valor: m.obs, largo: true },
    ], v => {
        const atual = (db.medicoes || []).find(x => x.id == id);
        if (!atual) return;
        const antes = _medAntesAceite(atual);
        if (v.data !== atual.data || v.hora !== (atual.hora || '')) {
            if (!atual.historico) atual.historico = [];
            _agdRegistrar(atual.historico, 'reagendado', { de: { data: atual.data, hora: atual.hora || '' }, para: { data: v.data, hora: v.hora } });
        }
        atual.data = v.data; atual.hora = v.hora; atual.duracao = v.dur; atual.obs = v.obs;
        _medDefinirResponsavel(atual, v.usu.pessoa);
        _medFecharReagendar(atual);
        _aceiteAplicar(atual, 'aceite', antes, atual.usuario_id, atual.data, atual.hora);
        _medAtualizar();
        toast(_agdNotaDesloc('Visita reagendada!'), 'success');
        abrirDetalheMedicao(id);
    }, () => abrirDetalheMedicao(id), _medDisp(id));
}

async function confirmarMedicao(id) {
    const m = (db.medicoes || []).find(x => x.id == id);
    if (!m || m.status !== 'Agendado') return;
    fecharModalAgenda();
    const ok = await showConfirm(`Confirmar que a medição de ${m.clienteNome || 'cliente'} foi realizada?\n\nEla sai de Agendamentos e vai para Realizados.`, '✅', 'Confirmar', 'Voltar');
    if (!ok) { abrirDetalheMedicao(id); return; }
    m.status = 'Realizado';
    m.realizado_em  = Date.now();
    m.realizado_por = getUsuarioLogado()?.id || null;
    _medAtualizar();
    toast('Medição confirmada!', 'success');
}

// Cancelar nao apaga: o registro fica com status Cancelado e o momento, fora
// das duas colunas e fora da contagem de realizadas. O horario do
// profissional fica livre de novo.
async function cancelarMedicao(id) {
    const m = (db.medicoes || []).find(x => x.id == id);
    if (!m || m.status !== 'Agendado') return;
    fecharModalAgenda();
    const ok = await showConfirm(`Cancelar a visita de ${m.clienteNome || 'cliente'} em ${_agdFmtData(m.data)}?\n\nO horário do profissional fica livre.`, '⚠️', 'Sim, cancelar', 'Não');
    if (!ok) { abrirDetalheMedicao(id); return; }
    if (!m.historico) m.historico = [];
    _agdRegistrar(m.historico, 'cancelado');
    m.status = 'Cancelado';
    delete m.aviso_cliente;
    m.cancelado_em = Date.now();
    _medAtualizar();
    toast('Agendamento cancelado.', 'info');
}

async function excluirMedicao(id) {
    fecharModalAgenda();
    if (!await showConfirm('Excluir este registro de medição?\nEsta ação não pode ser desfeita.', '🗑️', 'Excluir', 'Cancelar')) { abrirDetalheMedicao(id); return; }
    db.medicoes = db.medicoes.filter(x => x.id != id);
    _medAtualizar();
    toast('Registro excluído.', 'info');
}

function renderDashboardMedicoes() {
    const container = document.getElementById('dashboard-medicoes');
    if (!container) return;

    const hojeStr = new Date().toISOString().split('T')[0];
    const hoje = new Date(); hoje.setHours(0, 0, 0, 0);

    const atrasadas = filtrarMedicoesVisiveis(db.medicoes)
        .filter(m => m.status === 'Agendado' && m.data < hojeStr)
        .sort((a, b) => (a.data + (a.hora || '99:99')) > (b.data + (b.hora || '99:99')) ? -1 : 1);

    const proximas = filtrarMedicoesVisiveis(db.medicoes)
        .filter(m => m.status === 'Agendado' && m.data >= hojeStr)
        .sort((a, b) => (a.data + (a.hora || '99:99')) < (b.data + (b.hora || '99:99')) ? -1 : 1)
        .slice(0, 6);

    if (!atrasadas.length && !proximas.length) { container.style.display = 'none'; return; }
    container.style.display = '';

    function makeCard(v, atrasada) {
        const d    = new Date(v.data + 'T00:00:00');
        const diff = Math.round((d - hoje) / (1000 * 60 * 60 * 24));
        let label, bg, bord, acc, clrL;
        if (atrasada) {
            const dias = Math.abs(diff);
            label = dias === 1 ? 'Ontem' : `${dias}d atrás`;
            bg = 'var(--danger-bg)'; bord = '#F79B90'; acc = '#F43927'; clrL = '#F43927';
        } else {
            label = diff === 0 ? 'Hoje' : diff === 1 ? 'Amanhã' : d.toLocaleDateString('pt-BR', { weekday: 'short', day: '2-digit', month: '2-digit' });
            bg    = diff === 0 ? 'var(--info-bg)' : 'var(--surface-2)';
            bord  = diff === 0 ? '#9FC4E5' : 'var(--border)';
            acc   = diff === 0 ? '#2D77C1' : 'var(--primary-text)';
            clrL  = diff === 0 ? '#2D77C1' : '#8F8F8F';
        }
        return `<div class="index-card-3d index-card-click" onclick="location.href='pcp.html?view=medicoes'" style="cursor:pointer;background:${bg};border:1px solid ${acc};border-radius:8px;padding:12px 16px;min-width:155px;flex:1;max-width:200px">
            <div style="font-size:11px;font-weight:700;color:${clrL};text-transform:uppercase;letter-spacing:0.05em;margin-bottom:4px">${label}</div>
            <div style="font-weight:700;font-size:14px;color:var(--dark);margin-bottom:2px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis" title="${escapeHtml(v.clienteNome)}">${escapeHtml(v.clienteNome)}</div>
            ${v.hora ? `<div style="font-size:12px;color:var(--dark)">🕐 ${v.hora}</div>` : ''}
            ${v.clienteTel ? `<div style="font-size:12px;color:#8F8F8F;margin-top:2px">${escapeHtml(v.clienteTel)}</div>` : ''}
            ${linkIrParaHtml(_endMed(v), 'agd-ir agd-ir-card')}
        </div>`;
    }

    let sections = '';

    if (atrasadas.length) {
        sections += `<div style="margin-bottom:${proximas.length ? '18px' : '0'}">
            <div style="font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:0.5px;color:#F43927;margin-bottom:8px">⚠️ Atrasadas (${atrasadas.length})</div>
            <div style="display:flex;gap:12px;flex-wrap:wrap">${atrasadas.map(v => makeCard(v, true)).join('')}</div>
        </div>`;
    }

    if (proximas.length) {
        sections += `<div>
            ${atrasadas.length ? `<div style="font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:0.5px;color:#8F8F8F;margin-bottom:8px">📐 Próximas</div>` : ''}
            <div style="display:flex;gap:12px;flex-wrap:wrap">${proximas.map(v => makeCard(v, false)).join('')}</div>
        </div>`;
    }

    const titleColor = atrasadas.length ? '#F43927' : 'var(--text-strong)';
    const titleText  = atrasadas.length
        ? `⚠️ Medições — ${atrasadas.length} atrasada${atrasadas.length > 1 ? 's' : ''}`
        : '📐 Próximas Medições';

    container.innerHTML = `<div class="card" style="margin-bottom:20px">
        <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:14px">
            <h3 style="color:${titleColor};font-size:15px;margin:0">${titleText}</h3>
            <a href="pcp.html?view=medicoes" class="btn btn-outline btn-sm">Ver agenda completa</a>
        </div>
        ${sections}
    </div>`;
}

function renderDashboardInstalacoes() {
    const container = document.getElementById('dashboard-instalacoes');
    if (!container) return;

    const hojeStr = new Date().toISOString().split('T')[0];
    const hoje    = new Date(); hoje.setHours(0, 0, 0, 0);
    const statuses = ['Pronto p/ Instalação', 'Aguardando Financeiro'];

    const atrasados = filtrarPedidosVisiveis(db.pedidos)
        .filter(p => statuses.includes(normalizarStatus(p.status)) && p.data_entrega && p.data_entrega < hojeStr)
        .sort((a, b) => b.data_entrega < a.data_entrega ? -1 : 1);

    const proximos = filtrarPedidosVisiveis(db.pedidos)
        .filter(p => statuses.includes(normalizarStatus(p.status)) && p.data_entrega && p.data_entrega >= hojeStr)
        .sort((a, b) => a.data_entrega < b.data_entrega ? -1 : 1)
        .slice(0, 6);

    const semData = filtrarPedidosVisiveis(db.pedidos)
        .filter(p => statuses.includes(normalizarStatus(p.status)) && !p.data_entrega)
        .slice(0, 3);

    if (!atrasados.length && !proximos.length && !semData.length) { container.style.display = 'none'; return; }
    container.style.display = '';

    function makeCard(p) {
        const d    = p.data_entrega ? new Date(p.data_entrega + 'T00:00:00') : null;
        const diff = d ? Math.round((d - hoje) / (1000 * 60 * 60 * 24)) : null;
        const atrasado = diff !== null && diff < 0;
        let label, bg, bord, acc, clrL;
        if (diff === null) {
            label = 'Sem data'; bg = 'var(--surface-2)'; bord = 'var(--border)'; acc = '#8F8F8F'; clrL = '#8F8F8F';
        } else if (atrasado) {
            const dias = Math.abs(diff);
            label = dias === 1 ? 'Ontem' : `${dias}d atrás`;
            bg = 'var(--danger-bg)'; bord = '#F79B90'; acc = '#F43927'; clrL = '#F43927';
        } else {
            label = diff === 0 ? 'Hoje' : diff === 1 ? 'Amanhã' : d.toLocaleDateString('pt-BR', { weekday: 'short', day: '2-digit', month: '2-digit' });
            bg    = diff === 0 ? 'var(--info-bg)' : 'var(--surface-2)';
            bord  = diff === 0 ? '#9FC4E5' : 'var(--border)';
            acc   = diff === 0 ? '#2D77C1' : 'var(--primary-text)';
            clrL  = diff === 0 ? '#2D77C1' : '#8F8F8F';
        }
        return `<div class="index-card-3d index-card-click" onclick="location.href='pcp.html?view=agenda'" style="cursor:pointer;background:${bg};border:1px solid ${acc};border-radius:8px;padding:12px 16px;min-width:155px;flex:1;max-width:200px">
            <div style="font-size:11px;font-weight:700;color:${clrL};text-transform:uppercase;letter-spacing:0.05em;margin-bottom:4px">${label}</div>
            <div style="font-weight:700;font-size:14px;color:var(--dark);margin-bottom:2px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis" title="${escapeHtml(p.clienteNome)}">${escapeHtml(p.clienteNome||'—')}</div>
            <div style="font-size:11px;color:#8F8F8F">#${formatPedidoId(p.id)}</div>
            ${p.inst_hora     ? `<div style="font-size:12px;color:var(--dark);margin-top:2px">🕐 ${p.inst_hora}</div>` : ''}
            ${(() => { const t = _endInst(p, db.clientes.find(c => c.id == p.clienteId)); return (p.inst_endereco || _instVazia(p)) && t ? `<div style="font-size:11px;color:#8F8F8F;margin-top:2px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis" title="${escapeHtml(t)}">📍 ${escapeHtml(t)}</div>` : ''; })()}
            ${(() => { const c = db.clientes.find(c => c.id == p.clienteId); return linkIrParaHtml(_endInst(p, c), 'agd-ir agd-ir-card'); })()}
        </div>`;
    }

    let sections = '';
    if (atrasados.length) {
        sections += `<div style="margin-bottom:${(proximos.length || semData.length) ? '18px' : '0'}">
            <div style="font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:0.5px;color:#F43927;margin-bottom:8px">⚠️ Atrasados (${atrasados.length})</div>
            <div style="display:flex;gap:12px;flex-wrap:wrap">${atrasados.map(makeCard).join('')}</div>
        </div>`;
    }
    if (proximos.length) {
        sections += `<div style="margin-bottom:${semData.length ? '18px' : '0'}">
            ${atrasados.length ? `<div style="font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:0.5px;color:#8F8F8F;margin-bottom:8px">🔧 Próximas Instalações</div>` : ''}
            <div style="display:flex;gap:12px;flex-wrap:wrap">${proximos.map(makeCard).join('')}</div>
        </div>`;
    }
    if (semData.length) {
        sections += `<div>
            <div style="font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:0.5px;color:#8F8F8F;margin-bottom:8px">Sem data definida (${semData.length})</div>
            <div style="display:flex;gap:12px;flex-wrap:wrap">${semData.map(makeCard).join('')}</div>
        </div>`;
    }

    const titleColor = atrasados.length ? '#F43927' : 'var(--text-strong)';
    const titleText  = atrasados.length
        ? `⚠️ Instalações — ${atrasados.length} atrasada${atrasados.length > 1 ? 's' : ''}`
        : '🔧 Agenda de Instalações';

    container.innerHTML = `<div class="card" style="margin-bottom:20px">
        <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:14px">
            <h3 style="color:${titleColor};font-size:15px;margin:0">${titleText}</h3>
            <a href="pcp.html?view=agenda" class="btn btn-outline btn-sm">Ver agenda completa</a>
        </div>
        ${sections}
    </div>`;
}

// --- INSTALACOES --------------------------------------------------------------
// O agendamento vive no proprio pedido (um pedido = no maximo uma instalacao),
// entao nao ha como duplicar. Fluxo:
//   Na Costura -> Pronto p/ Instalacao  => card em "Pedidos Prontos para Instalacao"
//   Agendar (profissional/data/horario) => coluna "Agendamentos de Instalacao"
//   Confirmar instalacao                => coluna "Realizados" (Aguardando
//                                          Financeiro; o financeiro leva a Instalado)
// A data da instalacao e a data_entrega do pedido (a mesma do Kanban).

// Pedido antigo (antes do campo inst_agendado) conta como agendado se ja
// tinha data -- era assim que a agenda o tratava.
function _instAgendada(p) {
    if (!p) return false;
    if (p.inst_agendado !== undefined) return !!p.inst_agendado;
    return !!p.data_entrega;
}
function _instPendente(p) { return normalizarStatus(p.status) === 'Pronto p/ Instalação' && _instAgendada(p); }
function _instRealizada(p) { const s = normalizarStatus(p.status); return s === 'Instalado' || s === 'Aguardando Financeiro'; }
function _instProntos() { return db.pedidos.filter(p => normalizarStatus(p.status) === 'Pronto p/ Instalação' && !_instAgendada(p)); }
function _instDur(p) { return +p.inst_duracao || _agdDurPadrao('inst'); }

function _instPill(p, hoje) {
    const s = normalizarStatus(p.status);
    if (s === 'Instalado') return 'instalado';
    if (s === 'Aguardando Financeiro') return 'pagamento';
    if (!p.data_entrega) return 'semdata';
    if (p.data_entrega < hoje) return 'atrasado';
    return _aceitePend(p.inst_aceite) ? 'aceite' : 'agendado';
}

// Data mostrada no Realizado: o dia em que foi confirmada; pedido antigo sem
// esse registro usa a data agendada.
function _instDiaRealizado(p) {
    const ts = p.inst_confirmada_em || p.data_instalado;
    return ts ? _agdDiaLocal(ts) : (p.data_entrega || '');
}

// A agenda e o Kanban ficam na mesma pagina: o que muda o pedido aqui
// (agendar, confirmar, reagendar, cancelar) redesenha os dois, sem recarregar.
function _instAtualizar() {
    syncDB();
    renderAgenda();
    renderMedicoes();   // a disponibilidade e compartilhada
    renderKanban();
    renderDashboardInstalacoes();
}

// Botao do Kanban ("📅 Agendar") e links de outras telas: abre a agenda de
// instalacoes com o pedido ja selecionado no formulario.
function irParaAgendaInstalacao(id) {
    if (!document.getElementById('inst-form')) {
        window.location.href = 'pcp.html?view=agenda&pedido=' + encodeURIComponent(id);
        return;
    }
    mostrarViewPCP('agenda');
    const p = db.pedidos.find(x => x.id == id);
    if (p && _instPendente(p)) { abrirDetalheInstalacao(p.id); return; }
    selecionarPedidoInstalacao(id);
    document.getElementById('inst-form')?.scrollIntoView({ behavior: 'smooth', block: 'start' });
}

// --- Cards "Pedidos Prontos para Instalacao" + formulario "Agendar Instalacao" ---
let _instSelId = null;

function _instRenderProntos() {
    const lista = document.getElementById('inst-prontos-lista');
    if (!lista) return;
    const prontos = _instProntos().sort((a, b) => _agdCmp(_agdChave(a.data_entrega, ''), _agdChave(b.data_entrega, '')) || a.id - b.id);
    if (_instSelId && !prontos.some(p => p.id == _instSelId)) _instLimparForm();
    const cont = document.getElementById('inst-prontos-count');
    if (cont) cont.textContent = prontos.length + (prontos.length === 1 ? ' pedido' : ' pedidos');
    lista.innerHTML = prontos.length ? prontos.map(p => `
        <button type="button" class="agd-pronto${p.id == _instSelId ? ' agd-pronto-sel' : ''}" onclick="selecionarPedidoInstalacao(${p.id})" title="Agendar a instalação deste pedido">
            <span class="agd-pronto-ico">${_agdIco('caixa', 18)}</span>
            <span class="agd-pronto-info">
                <span class="agd-pronto-top"><strong>#${formatPedidoId(p.id)}</strong><span class="agd-pill agd-pill-verde">Pronto para Instalação</span>${p.inst_recusa ? '<span class="agd-pill agd-pill-verm" title="' + escapeHtml('Recusada: ' + p.inst_recusa.motivo) + '">A reagendar</span>' : ''}</span>
                <span class="agd-pronto-linha"><em>Cliente:</em> ${escapeHtml(p.clienteNome || '—')}</span>
                <span class="agd-pronto-linha"><em>Produto:</em> ${escapeHtml(p.amb || '—')}</span>
                <span class="agd-pronto-linha"><em>Entrega:</em> ${p.data_entrega ? _agdFmtData(p.data_entrega) : 'a definir'}</span>
            </span>
            <span class="agd-seta">${_agdIco('seta', 16)}</span>
        </button>`).join('')
        : '<div class="agd-vazio agd-prontos-vazio">Nenhum pedido aguardando agendamento. Ao passar um pedido de "Na Costura" para "Pronto p/ Instalação" ele aparece aqui.</div>';

    const sel = document.getElementById('inst-pedido');
    if (sel) {
        sel.innerHTML = '<option value="">Selecione um pedido pronto para instalação</option>' +
            prontos.map(p => `<option value="${p.id}">#${formatPedidoId(p.id)} - ${escapeHtml(p.clienteNome || '')}</option>`).join('');
        sel.value = _instSelId ? String(_instSelId) : '';
    }
}

// Cidade da instalacao: a do pedido ou, sem ela, a do cliente.
// Sem cidade propria, usa a do cliente so quando o endereco da instalacao e o do cliente
// (ou esta vazio): outro endereco pode ser de outra cidade.
function _instCidade(p, cli) {
    if (p && p.inst_cidade !== undefined && p.inst_cidade !== null) return p.inst_cidade;
    if (!cli || !cli.cidade) return '';
    const n = s => (typeof RotasCore !== 'undefined' ? RotasCore.normalizarEndereco(s) : String(s || '').trim().toLowerCase());
    return (!p || !p.inst_endereco || n(p.inst_endereco) === n(cli.end)) ? cli.cidade : '';
}

// Partes do endereco da instalacao: as do pedido; pedido antigo com endereco proprio vira
// Rua = texto antigo (cidade nao herdada do cliente); senao, as do cliente.
// Instalacao com partes mas sem rua, numero e CEP nao tem endereco proprio: segue o cliente.
function _instVazia(p) {
    return p.inst_rua !== undefined && !['inst_rua', 'inst_numero', 'inst_cep'].some(k => String(p[k] == null ? '' : p[k]).trim());
}
function _instPartes(p, cli) {
    if (_instVazia(p)) return _partesDoCliente(cli);
    if (p.inst_rua !== undefined) {
        return { cep: p.inst_cep, rua: p.inst_rua, numero: p.inst_numero, complemento: p.inst_complemento,
            bairro: p.inst_bairro, cidade: p.inst_cidade, uf: p.inst_uf };
    }
    const n = s => RotasCore.normalizarEndereco(s);
    if (p.inst_endereco && n(p.inst_endereco) !== n(cli?.end)) return EnderecoCore.partesDeRegistroAntigo(p.inst_endereco, _instCidade(p, cli));
    return _partesDoCliente(cli);
}
function _instGravarPartes(p, partes) {
    p.inst_cep = partes.cep; p.inst_rua = partes.rua; p.inst_numero = partes.numero; p.inst_complemento = partes.complemento;
    p.inst_bairro = partes.bairro; p.inst_cidade = partes.cidade; p.inst_uf = partes.uf;
    p.inst_endereco = EnderecoCore.textoEndereco(partes);
}

function _instLimparForm() {
    _instSelId = null;
    _agdPickerFechar();
    const set = (id, v) => { const el = document.getElementById(id); if (el) { el.value = v; el.classList.remove('agd-erro'); } };
    set('inst-pedido', '');
    set('inst-data', _agdHoje());
    set('inst-hora', '');
    enderecoPreencher('inst', {});
    set('inst-obs', '');
    _agdPreencherProf('inst-prof', '', 'Selecione');
    _agdPreencherDur('inst-dur', 'inst');
    const sub = document.getElementById('inst-pedido-sub'); if (sub) sub.innerHTML = '';
    const cli = document.getElementById('inst-cliente');
    if (cli) cli.innerHTML = '<span class="agd-cli-vazio">Preenchido ao selecionar o pedido</span>';
}

// Seleciona o pedido e preenche cliente, telefone, endereco e o que o pedido
// ja tiver (instalador, observacoes, duracao).
function selecionarPedidoInstalacao(id) {
    const p = id ? db.pedidos.find(x => x.id == id) : null;
    if (!p) { _instLimparForm(); _instRenderProntos(); _instAtualizarDisp(); return; }
    if (normalizarStatus(p.status) !== 'Pronto p/ Instalação' || _instAgendada(p)) {
        toast(_instAgendada(p) ? `O pedido #${formatPedidoId(p.id)} já está agendado.` : `O pedido #${formatPedidoId(p.id)} não está pronto para instalação.`, 'info');
        return;
    }
    _instSelId = p.id;
    const cli = db.clientes.find(c => c.id == p.clienteId);
    const hoje = _agdHoje();
    const set = (eid, v) => { const el = document.getElementById(eid); if (el) { el.value = v; el.classList.remove('agd-erro'); } };
    enderecoPreencher('inst', _instPartes(p, cli));
    set('inst-obs', p.inst_obs || '');
    set('inst-data', p.data_entrega && p.data_entrega >= hoje ? p.data_entrega : hoje);
    set('inst-hora', '');
    _agdPreencherProf('inst-prof', _instProf(p), 'Selecione');
    _agdPreencherDur('inst-dur', 'inst', p.inst_duracao);
    const sub = document.getElementById('inst-pedido-sub');
    if (sub) sub.innerHTML = `<span class="agd-pill agd-pill-verde">Pronto para Instalação</span>${p.inst_recusa ? `<span class="agd-pill agd-pill-verm">A reagendar</span><span>Recusada por ${escapeHtml(nomeUsuario(p.inst_recusa.por))}: ${escapeHtml(p.inst_recusa.motivo)}</span>` : ''}<span>Produto: ${escapeHtml(p.amb || '—')}</span>`;
    const box = document.getElementById('inst-cliente');
    if (box) box.innerHTML = `<strong>${escapeHtml(p.clienteNome || '—')}</strong>` +
        (cli?.tel ? `<span class="agd-linha">${_agdIco('tel', 12)}${escapeHtml(cli.tel)}</span>` : '');
    _instRenderProntos();
    _instAtualizarDisp();
}

function _instAtualizarDisp() {
    if (!document.getElementById('inst-disp')) return;
    _agdDispCtx['inst-disp'] = Object.assign(_agdDispCtx['inst-disp'] || {}, { onHora: (d, h) => {
        document.getElementById('inst-data').value = d;
        document.getElementById('inst-hora').value = h;
        document.getElementById('inst-hora').classList.remove('agd-erro');
        _instAtualizarDisp();
    } });
    const prof = _agdLerProf('inst-prof');
    _agdPickerAnexar(document.getElementById('inst-hora'), () => {
        const p = _agdLerProf('inst-prof');
        return { tipo: 'inst', prof: p.chave, profNome: p.pessoa.nome, data: document.getElementById('inst-data')?.value || '',
            dur: parseInt(document.getElementById('inst-dur')?.value) || _agdDurPadrao('inst') };
    });
    _agdDispCtx['inst-disp'].onProf = ch => { _agdPreencherProf('inst-prof', ch, 'Selecione'); _instAtualizarDisp(); };
    _agdRenderDisp('inst-disp', {
        tipo: 'inst', prof: prof.chave, profNome: prof.pessoa.nome,
        data: document.getElementById('inst-data')?.value || '',
        hora: document.getElementById('inst-hora')?.value || '',
        dur:  parseInt(document.getElementById('inst-dur')?.value) || _agdDurPadrao('inst'),
    });
}

function salvarAgendamentoInstalacao() { return _agdSemDuplo(_salvarAgendamentoInstalacao); }
async function _salvarAgendamentoInstalacao() {
    const campos = {
        pedido: document.getElementById('inst-pedido'),
        prof:   document.getElementById('inst-prof'),
        data:   document.getElementById('inst-data'),
        hora:   document.getElementById('inst-hora'),
    };
    Object.values(campos).forEach(el => el && el.classList.remove('agd-erro'));
    const prof = _agdLerProf('inst-prof');
    const v = {
        id:   parseInt(campos.pedido?.value) || null,
        data: campos.data?.value || '',
        hora: campos.hora?.value || '',
        dur:  parseInt(document.getElementById('inst-dur')?.value) || _agdDurPadrao('inst'),
        end:  enderecoLer('inst'),
        obs:  (document.getElementById('inst-obs')?.value || '').trim(),
    };
    const faltando = [];
    if (!v.id)       faltando.push(['pedido', 'o pedido']);
    if (!prof.chave) faltando.push(['prof', 'o profissional']);
    if (!v.data)     faltando.push(['data', 'a data']);
    if (!v.hora)     faltando.push(['hora', 'o horário']);
    if (faltando.length) {
        faltando.forEach(([k]) => campos[k]?.classList.add('agd-erro'));
        campos[faltando[0][0]]?.focus();
        await showAlert(`Informe ${faltando.map(f => f[1]).join(', ')}.`, '⚠️');
        return;
    }

    // Confere de novo contra o que esta gravado: outro usuario/aba pode ter
    // agendado o pedido ou ocupado o horario desde que a tela foi aberta.
    if (!await _agdValidarDisp({ prof: prof.chave, profNome: prof.pessoa.nome, data: v.data, hora: v.hora, dur: v.dur, partes: v.end })) { _agdRedesenharAgendas(); return; }
    const p = db.pedidos.find(x => x.id == v.id);
    if (!p || normalizarStatus(p.status) !== 'Pronto p/ Instalação') {
        await showAlert('Este pedido não está mais em "Pronto p/ Instalação".', '⚠️');
        _instLimparForm(); _agdRedesenharAgendas(); return;
    }
    if (_instAgendada(p)) {
        const quem = p.inst_agendado_por ? ` por ${nomeUsuario(p.inst_agendado_por)}` : '';
        await showAlert(`O pedido #${formatPedidoId(p.id)} já foi agendado${quem} para ${_agdFmtData(p.data_entrega)}${p.inst_hora ? ' às ' + p.inst_hora : ''}.\n\nNenhum agendamento novo foi criado.`, 'ℹ️');
        _instLimparForm(); _agdRedesenharAgendas(); return;
    }

    p.data_entrega   = v.data;
    p.inst_hora      = v.hora;
    p.inst_duracao   = v.dur;
    _instGravarPartes(p, v.end);
    p.inst_obs       = v.obs;
    definirInstalador(p, prof.pessoa);
    _aceiteAplicar(p, 'inst_aceite', null, p.usuario_instalacao_id, v.data, v.hora);
    delete p.inst_recusa;   // ja ficou no historico
    p.inst_agendado     = true;
    p.inst_agendado_por = getUsuarioLogado()?.id || null;
    p.inst_agendado_em  = Date.now();
    if (!p.inst_historico) p.inst_historico = [];
    _agdRegistrar(p.inst_historico, 'agendado', { para: { data: v.data, hora: v.hora }, prof: nomeInstalador(p) });

    _instLimparForm();
    _instAtualizar();
    toast(_agdNotaDesloc(`Instalação do pedido #${formatPedidoId(p.id)} agendada!`), 'success');
}

function renderAgenda() {
    if (!document.getElementById('inst-pend-lista')) return;
    _instRenderProntos();
    const hoje = _agdHoje();
    const pend = db.pedidos.filter(_instPendente);
    const real = db.pedidos.filter(_instRealizada);
    const filtra = (lista, chave) => {
        const b = _agdNorm(_agdBusca[chave]);
        if (!b) return lista;
        const dig = b.replace(/\D/g, '');
        return lista.filter(p => _agdNorm(p.clienteNome).includes(b) || (dig && String(p.id).includes(dig)));
    };
    const linha = (p, realizado) => {
        const cli = db.clientes.find(c => c.id == p.clienteId);
        return _agdLinha({
            onclick: `abrirDetalheInstalacao(${p.id})`,
            nome: p.clienteNome,
            sub:  `Pedido #${formatPedidoId(p.id)}${p.amb ? ' · ' + p.amb : ''}${nomeInstalador(p) ? ' · ' + nomeInstalador(p) : ''}`,
            tel:  cli?.tel,
            end:  _endInst(p, cli),
            data: realizado ? _instDiaRealizado(p) : p.data_entrega,
            hora: p.inst_hora,
            pill: _instPill(p, hoje),
        });
    };
    const pendF = filtra(pend, 'instPend').sort((a, b) =>
        _agdCmp(_agdChave(a.data_entrega, a.inst_hora), _agdChave(b.data_entrega, b.inst_hora)));
    const realF = filtra(real, 'instReal').sort((a, b) =>
        (b.inst_confirmada_em || b.data_instalado || 0) - (a.inst_confirmada_em || a.data_instalado || 0)
        || _agdCmp(_agdChave(b.data_entrega, b.inst_hora), _agdChave(a.data_entrega, a.inst_hora)));
    _agdPreencher('inst-pend', pendF.map(p => linha(p, false)), pend.length, 'Nenhuma instalação agendada. Selecione um pedido pronto acima para agendar.', _agdBusca.instPend, ['agendamento', 'agendamentos']);
    _agdPreencher('inst-real', realF.map(p => linha(p, true)), real.length, 'Nenhuma instalação realizada ainda.', _agdBusca.instReal);
    _instAtualizarDisp();
}

// opts.soLeitura: so os dados, sem botoes de acao (aberto pela Agenda por quem nao
// tem acesso a agenda de instalacoes da Producao).
function abrirDetalheInstalacao(id, opts) {
    const soLeitura = !!(opts && opts.soLeitura);
    const p = db.pedidos.find(x => x.id == id);
    if (!p) return;
    const cli   = db.clientes.find(c => c.id == p.clienteId);
    const pend  = _instPendente(p);
    const pagto = statusPagamento(p);
    const tel   = cli?.tel
        ? `<a href="https://wa.me/55${cli.tel.replace(/\D/g, '')}" target="_blank" rel="noopener">${escapeHtml(cli.tel)}</a>`
        : '—';
    const corpo = `<div class="agd-det-topo">${_agdPill(_instPill(p, _agdHoje()))}</div>` + _agdCampos([
        ['Pedido',      '#' + formatPedidoId(p.id)],
        ['Cliente',     escapeHtml(p.clienteNome || '—')],
        ['Telefone',    tel],
        ['Endereço',    escapeHtml(_endInst(p, cli) || '—') + linkIrParaHtml(_endInst(p, cli), 'agd-ir agd-ir-det')],
        ['Data',        _agdFmtData(p.data_entrega)],
        ['Horário',     escapeHtml(p.inst_hora ? _agdPeriodo(p.inst_hora, _instDur(p)) : '—')],
        ['Duração',     escapeHtml(_agdFmtDur(_instDur(p)))],
        ['Instalador',  escapeHtml(nomeInstalador(p) || 'A definir')],
        ..._aceiteLinhasDetalhe(p.inst_aceite, p.inst_recusa),
        p.inst_agendado_por ? ['Agendado por', escapeHtml(nomeUsuario(p.inst_agendado_por))] : null,
        p.vendedor_nome ? ['Vendedor', escapeHtml(p.vendedor_nome)] : null,
        ['Ambientes',   escapeHtml(p.amb || '—')],
        ['Valor',       'R$ ' + (p.valor || 0).toFixed(2)],
        ['Pagamento',   escapeHtml(pagto.label || '—')],
        ['Observações', escapeHtml(p.inst_obs || '—')],
        p.inst_confirmada_em ? ['Confirmada em', _agdFmtMomento(p.inst_confirmada_em)] : null,
        p.data_instalado ? ['Instalado em', _agdFmtMomento(p.data_instalado)] : null,
    ]) + _agdHistorico(p.inst_historico);
    const rodape = soLeitura ? ''
        : pend
        ? `<button class="btn btn-outline btn-sm btn-danger" onclick="cancelarAgendamentoInstalacao(${p.id})">✕ Cancelar agendamento</button>
           <button class="btn btn-outline btn-sm" onclick="fecharModalAgenda();abrirOS(${p.id})">📋 OS</button>
           <button class="btn btn-outline btn-sm" onclick="editarInstalacao(${p.id})">✏️ Editar</button>
           <button class="btn btn-outline btn-sm" onclick="reagendarInstalacao(${p.id})">📅 Reagendar</button>
           <button class="btn btn-success btn-sm" onclick="confirmarInstalacao(${p.id})">✓ Confirmar instalação</button>`
        : `<button class="btn btn-outline btn-sm" onclick="fecharModalAgenda();abrirOS(${p.id})">📋 OS</button>`;
    _agdAbrirModal('Instalação', corpo, rodape);
}

// A data da instalacao e a do pedido: mudar exige confirmacao, como antes.
async function _instConfirmarNovaData(p, novaData) {
    if (!p.data_entrega || novaData === p.data_entrega) return true;
    return showConfirm(
        `Alterar a data de instalação do pedido #${formatPedidoId(p.id)}?\n\nData atual: ${_agdFmtData(p.data_entrega)}\nNova data:  ${_agdFmtData(novaData)}\n\nA alteração reflete no pedido.`,
        '📅', 'Confirmar', 'Cancelar');
}

function _instDispOpts(id) { return { disp: { tipo: 'inst', ignorar: { tipo: 'inst', id } } }; }

// Grava a edicao/reagendamento: o pedido e relido depois da validacao da agenda.
async function _instGravarEdicao(id, v, titulo) {
    let p = db.pedidos.find(x => x.id == id);
    if (!p || !_instPendente(p)) { await showAlert('Esta instalação não está mais agendada.', '⚠️'); fecharModalAgenda(); _agdRedesenharAgendas(); return; }
    if (!await _instConfirmarNovaData(p, v.data)) return false;
    // A confirmacao demorou: relê o gravado e confere o conflito de novo antes de gravar.
    const cliEd = db.clientes.find(c => c.id == p.clienteId);
    // Nada que mude o deslocamento (so telefone/observacao): nao confere de novo.
    const partesEd = v._semMudanca ? undefined : v.end !== undefined ? v.end : _partesInstConferir(p, cliEd);
    if (v.usu && v.usu.chave && !await _agdValidarDisp({ prof: v.usu.chave, profNome: v.usu.pessoa.nome, data: v.data, hora: v.hora, dur: v.dur || _agdDurPadrao('inst'), ignorar: { tipo: 'inst', id }, partes: partesEd })) { _agdRedesenharAgendas(); return false; }
    p = db.pedidos.find(x => x.id == id);
    if (!p || !_instPendente(p)) { await showAlert('Esta instalação não está mais agendada.', '⚠️'); fecharModalAgenda(); _agdRedesenharAgendas(); return; }
    const antes = { uid: p.usuario_instalacao_id || null, data: p.data_entrega, hora: p.inst_hora || '' };
    if (v.data !== p.data_entrega || v.hora !== (p.inst_hora || '')) {
        if (!p.inst_historico) p.inst_historico = [];
        _agdRegistrar(p.inst_historico, 'reagendado', { de: { data: p.data_entrega || '', hora: p.inst_hora || '' }, para: { data: v.data, hora: v.hora } });
    }
    if (v.end !== undefined) _instGravarPartes(p, v.end);
    p.data_entrega = v.data;
    p.inst_hora    = v.hora;
    p.inst_duracao = v.dur || _agdDurPadrao('inst');
    p.inst_obs     = v.obs;
    definirInstalador(p, v.usu.pessoa);
    _aceiteAplicar(p, 'inst_aceite', antes, p.usuario_instalacao_id, v.data, v.hora);
    _instAtualizar();
    toast(_agdNotaDesloc(titulo), 'success');
    _lembreteInstVoltar(() => abrirDetalheInstalacao(id));
}

function editarInstalacao(id) {
    const p = db.pedidos.find(x => x.id == id);
    if (!p) return;
    const cli = db.clientes.find(c => c.id == p.clienteId);
    _agdFormulario('Editar instalação', [
        { id: 'end',  tipo: 'endereco', valor: _instPartes(p, cli) },
        { id: 'usu',  label: 'Profissional', tipo: 'profissional', valor: _instProf(p), obrig: true, vazio: 'Selecione' },
        { id: 'dur',  label: 'Duração do serviço', tipo: 'duracao', valor: p.inst_duracao },
        { id: 'data', label: 'Data de instalação', tipo: 'date', valor: p.data_entrega, obrig: true },
        { id: 'hora', label: 'Horário', tipo: 'time', valor: p.inst_hora, obrig: true },
        { id: 'obs',  label: 'Observações', tipo: 'textarea', valor: p.inst_obs, largo: true },
    ], v => _instGravarEdicao(id, v, 'Instalação atualizada!'), () => abrirDetalheInstalacao(id), _instDispOpts(id));
}

function reagendarInstalacao(id) {
    const p = db.pedidos.find(x => x.id == id);
    if (!p) return;
    _agdFormulario('Reagendar instalação', [
        { id: 'usu',  label: 'Profissional', tipo: 'profissional', valor: _instProf(p), obrig: true, vazio: 'Selecione' },
        { id: 'dur',  label: 'Duração do serviço', tipo: 'duracao', valor: p.inst_duracao },
        { id: 'data', label: 'Nova data', tipo: 'date', valor: p.data_entrega, obrig: true },
        { id: 'hora', label: 'Horário', tipo: 'time', valor: p.inst_hora, obrig: true },
        { id: 'obs',  label: 'Observações', tipo: 'textarea', valor: p.inst_obs, largo: true },
    ], v => _instGravarEdicao(id, v, 'Instalação reagendada!'), () => _lembreteInstVoltar(() => abrirDetalheInstalacao(id)), _instDispOpts(id));
}

// Cancela o agendamento: o horario do profissional fica livre e o pedido volta
// para os cards "Pedidos Prontos para Instalacao", pronto para ser agendado de
// novo. O que havia fica no historico.
async function cancelarAgendamentoInstalacao(id) {
    const p = db.pedidos.find(x => x.id == id);
    if (!p || !_instPendente(p)) return;
    fecharModalAgenda();
    const ok = await showConfirm(`Cancelar a instalação do pedido #${formatPedidoId(p.id)}${p.data_entrega ? ' em ' + _agdFmtData(p.data_entrega) : ''}?\n\nO horário do profissional fica livre e o pedido volta para "Pedidos Prontos para Instalação".`, '⚠️', 'Sim, cancelar', 'Voltar');
    if (!ok) { abrirDetalheInstalacao(id); return; }
    if (!p.inst_historico) p.inst_historico = [];
    _agdRegistrar(p.inst_historico, 'cancelado', { de: { data: p.data_entrega || '', hora: p.inst_hora || '' } });
    p.inst_agendado = false;
    p.data_entrega  = null;
    p.inst_hora     = '';
    delete p.inst_aceite;
    delete p.inst_aviso_cliente;
    _instAtualizar();
    toast('Agendamento cancelado. O pedido voltou para os prontos.', 'info');
}

// Mesmo desfecho do Kanban: pago ou com saldo, o pedido vai para Aguardando
// Financeiro (com saldo, marcado como pendente). A instalacao foi feita: vai
// para Realizados.
// aoTerminar(confirmou): quem chama de fora da agenda (o lembrete de confirmar)
// segue dali; sem ele, desistir volta para o detalhe da instalacao.
function confirmarInstalacao(id, aoTerminar) {
    const p = db.pedidos.find(x => x.id == id);
    if (!p || !_instPendente(p)) { if (aoTerminar) aoTerminar(false); return; }
    fecharModalAgenda();
    mostrarModalPagamento(p, resultado => {
        if (!resultado) { if (aoTerminar) aoTerminar(false); else abrirDetalheInstalacao(id); return; }
        aplicarConfirmacaoEntrega(p, resultado);
        _instAtualizar();
        toast(resultado === 'pago' ? 'Instalação confirmada. Pedido em Aguardando Financeiro.' : 'Instalação confirmada. Pedido em Aguardando Financeiro, com pagamento pendente.', 'info');
        if (aoTerminar) aoTerminar(true);
    });
}

// --- LEMBRETE DE CONFIRMAR A INSTALACAO ----------------------------------------
// Passou o fim de uma instalacao agendada (data + horario + duracao; sem
// horario, o fim do expediente) e ninguem confirmou: o instalador designado e
// quem criou o pedido sao lembrados. Ao abrir o sistema aparece uma janela,
// uma vez por dia por pessoa (sc_lembrete_inst_<id> = dia em que viu); na
// Pagina Inicial fica um aviso fixo enquanto houver o que confirmar.
function _instFimMs(p) {
    const [a, m, d] = String(p.data_entrega).split('-').map(Number);
    const ini = _agdMin(p.inst_hora);
    const fim = ini !== null ? ini + _instDur(p) : (_agdMin(getAgendaConfig().fim) ?? 18 * 60);
    return new Date(a, m - 1, d, 0, fim).getTime();
}

function instalacoesParaConfirmar(usuario) {
    const u = usuario === undefined ? getUsuarioLogado() : usuario;
    if (!u) return [];
    const agora = Date.now();
    return (db.pedidos || [])
        .filter(p => _instPendente(p) && p.data_entrega
            // o instalador que nunca aceitou nao e perguntado "Foi instalado?"; quem criou o pedido, sim
            && (p.criado_por == u.id || (p.usuario_instalacao_id == u.id && !_aceitePend(p.inst_aceite)))
            && agora > _instFimMs(p))
        .sort((a, b) => _instFimMs(a) - _instFimMs(b) || a.id - b.id);
}

function _lembreteInstChave(u) { return 'sc_lembrete_inst_' + u.id; }

function _lembreteInstPergunta(p) {
    const [, m, d] = String(p.data_entrega).split('-');
    return `O pedido #${formatPedidoId(p.id)} (${p.clienteNome || '—'}) devia ter sido instalado em ${d}/${m}${p.inst_hora ? ' às ' + p.inst_hora : ''}. Foi instalado?`;
}

// Ao abrir a pagina (depois do login): mostra a janela se houver o que
// confirmar e a pessoa ainda nao a viu hoje.
function _paginaDeDocumento() {
    const arq = (window.location.pathname.split('/').pop() || '').toLowerCase();
    return ['os.html', 'proposta.html', 'pedido-compra.html'].includes(arq)
        || !!document.querySelector('.os-wrapper, .proposta-wrapper, #pedido-compra-container');
}

function lembrarInstalacoesAoAbrir() {
    if (_paginaDeDocumento()) return;   // paginas de impressao nao ganham janela
    const u = getUsuarioLogado();
    if (!u || !instalacoesParaConfirmar(u).length) return;
    const hoje = _agdHoje();
    try { if (localStorage.getItem(_lembreteInstChave(u)) === hoje) return; } catch (e) {}
    try { localStorage.setItem(_lembreteInstChave(u), hoje); } catch (e) {}
    abrirLembreteInstalacoes();
}

// "Ainda não" troca os dois botoes do pedido por "Reagendar" / "Lembrar amanhã";
// "Lembrar amanhã" tira o pedido da janela (ela volta amanha).
// Reagendar: o que ficou de fora volta a ser lembrado depois de salvar (ou cancelar)
// o reagendamento, mesmo em outra pagina -- por isso o estado vai no sessionStorage.
let _lembreteInstAdiados = [];
const _LEMBRETE_VOLTAR = 'sc_lembrete_inst_voltar';
// Depois do reagendamento: reabre a janela com o que resta; sem pendencia, segue o fluxo normal.
function _lembreteInstVoltar(fallback) {
    let fila = null;
    try { fila = sessionStorage.getItem(_LEMBRETE_VOLTAR); sessionStorage.removeItem(_LEMBRETE_VOLTAR); } catch (e) {}
    if (fila === null) { fallback(); return; }
    let ja = [];
    try { ja = JSON.parse(fila) || []; } catch (e) {}
    _lembreteInstAdiados = ja.slice(0, -1);   // o ultimo e o reagendado (ja fora da fila se foi salvo)
    if (instalacoesParaConfirmar().some(p => !_lembreteInstAdiados.includes(p.id) && p.id !== ja[ja.length - 1])) abrirLembreteInstalacoes();
    else fallback();
}
function abrirLembreteInstalacoes() {
    const lista = instalacoesParaConfirmar().filter(p => !_lembreteInstAdiados.includes(p.id));
    if (!lista.length) { fecharModalAgenda(); return; }
    const corpo = lista.map(p => `<div class="lembrete-inst-item" data-id="${p.id}">
            <p class="lembrete-inst-txt">${escapeHtml(_lembreteInstPergunta(p))}</p>
            <div class="lembrete-inst-btns">
                <button type="button" class="btn btn-outline btn-sm" onclick="_lembreteInstAindaNao(${p.id})">Ainda não</button>
                <button type="button" class="btn btn-success btn-sm" onclick="_lembreteInstSim(${p.id})">Sim, foi instalado</button>
            </div>
        </div>`).join('');
    const o = _agdAbrirModal(lista.length === 1 ? 'Instalação para confirmar' : 'Instalações para confirmar', corpo, '');
    o.classList.add('lembrete-inst-overlay');
    o.querySelector('.agd-modal').classList.add('lembrete-inst-modal');
}

function _lembreteInstSim(id) {
    confirmarInstalacao(id, () => {
        renderAvisoInstConfirmar();
        if (document.getElementById('tb-pedidos')) renderDashboard();
        abrirLembreteInstalacoes();
    });
}

function _lembreteInstAindaNao(id) {
    const btns = document.querySelector(`.lembrete-inst-item[data-id="${id}"] .lembrete-inst-btns`);
    if (!btns) return;
    btns.innerHTML = `<button type="button" class="btn btn-outline btn-sm" onclick="_lembreteInstAmanha(${id})">Lembrar amanhã</button>
        ${_lembreteInstPodeReagendar() ? `<button type="button" class="btn btn-sm" onclick="_lembreteInstReagendar(${id})">📅 Reagendar</button>` : ''}`;
}

// Reagendar abre a agenda de instalacoes (Producao): so para quem tem acesso a essa pagina.
function _lembreteInstPodeReagendar() {
    const exigidos = PAGINA_MODULO['pcp.html'];
    const lista = Array.isArray(exigidos) ? exigidos : [exigidos];
    return lista.some(m => temAcessoAlgumaSub(m, 'visualizar'));
}

function _lembreteInstAmanha(id) {
    _lembreteInstAdiados.push(id);
    abrirLembreteInstalacoes();
}

// Reagendar e o da agenda de instalacoes (pcp.html); de outra tela, vai ate la.
function _lembreteInstReagendar(id) {
    fecharModalAgenda();
    // Guarda o que ja foi adiado + este pedido (ultimo): ao terminar o reagendamento a janela volta com o resto.
    try { sessionStorage.setItem(_LEMBRETE_VOLTAR, JSON.stringify(_lembreteInstAdiados.concat([id]))); } catch (e) {}
    if (!document.getElementById('inst-form')) {
        window.location.href = 'pcp.html?view=agenda&pedido=' + encodeURIComponent(id) + '&reagendar=1';
        return;
    }
    mostrarViewPCP('agenda');
    reagendarInstalacao(id);
}

// Pagina Inicial: aviso fixo (toda vez, enquanto houver o que confirmar).
function renderAvisoInstConfirmar() {
    const el = document.getElementById('aviso-inst-confirmar');
    if (!el) return;
    const lista = instalacoesParaConfirmar();
    if (!lista.length) { el.style.display = 'none'; el.innerHTML = ''; return; }
    const n = lista.length;
    el.innerHTML = `<div class="aviso-inst-tit">⚠ ${n} ${n === 1 ? 'instalação' : 'instalações'} aguardando confirmação</div>` +
        lista.map(p => `<div class="aviso-inst-item">
            <span>${escapeHtml(_lembreteInstPergunta(p))}</span>
            <button type="button" class="btn btn-success btn-sm" onclick="_lembreteInstConfirmarAviso(${p.id})">Confirmar</button>
        </div>`).join('');
    el.style.display = '';
}

function _lembreteInstConfirmarAviso(id) {
    confirmarInstalacao(id, () => {
        renderAvisoInstConfirmar();
        if (document.getElementById('tb-pedidos')) renderDashboard();
    });
}

// --- PCP VIEW TOGGLE ---
let _prevViewPCP = null, _curViewPCP = 'kanban';
function mostrarViewPCP(view) {
    if (_curViewPCP !== view) { _prevViewPCP = _curViewPCP; _curViewPCP = view; }
    document.getElementById('pcp-view-kanban').style.display   = view === 'kanban'   ? '' : 'none';
    document.getElementById('pcp-view-agenda').style.display   = view === 'agenda'   ? '' : 'none';
    document.getElementById('pcp-view-medicoes').style.display = view === 'medicoes' ? '' : 'none';
    const vRotas = document.getElementById('pcp-view-rotas');
    if (vRotas) vRotas.style.display = view === 'rotas' ? '' : 'none';
    const tRotas = document.getElementById('tab-btn-rotas');
    if (tRotas) tRotas.className = 'tab-btn' + (view === 'rotas' ? ' active' : '');
    document.getElementById('tab-btn-kanban').className   = 'tab-btn' + (view === 'kanban'   ? ' active' : '');
    document.getElementById('tab-btn-agenda').className   = 'tab-btn' + (view === 'agenda'   ? ' active' : '');
    document.getElementById('tab-btn-medicoes').className = 'tab-btn' + (view === 'medicoes' ? ' active' : '');
    if (view === 'kanban')   renderKanban();
    if (view === 'agenda' || view === 'medicoes') _agdAtualizarListaProf();
    if (view === 'agenda')   renderAgenda();
    if (view === 'medicoes') renderMedicoes();
    if (view === 'rotas')    renderRotas();
    _tabBackBtn('.tab-nav', _prevViewPCP, () => mostrarViewPCP(_prevViewPCP));
}

// --- TEMA CLARO / ESCURO ---
// O tema e uma preferencia do usuario (Configuracoes > Preferencias); sc_tema
// guarda a ultima escolha neste navegador para o <head> pintar sem piscar.
function aplicarTema(tema) {
    tema = tema === 'dark' ? 'dark' : 'light';
    document.documentElement.setAttribute('data-theme', tema);
    try { localStorage.setItem('sc_tema', tema); } catch (e) {}
    atualizarIconeTema();
}
// Configuracoes > Preferencias > Tema: escolher ja aplica e ja grava, sem
// esperar o "Salvar preferências" (que continua valendo para o resto).
function escolherTema(tema) {
    tema = tema === 'dark' ? 'dark' : 'light';
    _gravarMeuUsuario(u => { u.preferencias = Object.assign({}, u.preferencias, { tema }); });
    aplicarTema(tema);
}
function carregarTema() {
    const u = getUsuarioLogado();
    const pref = u && u.preferencias && u.preferencias.tema;
    const tema = pref === 'dark' || pref === 'light' ? pref : (localStorage.getItem('sc_tema') || 'light');
    document.documentElement.setAttribute('data-theme', tema);
    if (pref && localStorage.getItem('sc_tema') !== tema) { try { localStorage.setItem('sc_tema', tema); } catch (e) {} }
    atualizarIconeTema();
}
// Mantem o seletor de Configuracoes > Preferencias marcado no tema em uso.
function atualizarIconeTema() {
    const tema = document.documentElement.getAttribute('data-theme') === 'dark' ? 'dark' : 'light';
    document.querySelectorAll('input[name="pref-tema"]').forEach(r => { r.checked = r.value === tema; });
}

// --- INICIALIZAÇÃO ---
document.addEventListener('DOMContentLoaded', () => {
    // Pedidos antigos ganham parcelas; depois, a migracao unica da Fase 0.
    // Um erro aqui nao pode impedir a pagina de abrir.
    try {
        _migrarFinanceiroPedidos();
        _migrarFinanceiroFase0();
    } catch (e) { console.error('Migração do Financeiro falhou:', e); }
    // Financeiro novo (v4), so depois da Fase 0 (que ainda cria e tira contas); um erro aqui nao impede a pagina.
    try { if (localStorage.getItem(CHAVE_FIN_MIGRACAO) === '1') _migrarFinanceiroV4(); }
    catch (e) { console.error('Migração do Financeiro (v4) falhou:', e); }
    // Comissao como registro do pedido (depois da Fase 0, que ainda cria contas de comissao).
    try { _migrarComissoesV2(); _sincronizarComissoesEmCP(); }
    catch (e) { console.error('Migração das comissões falhou:', e); }

    if (!document.getElementById('login-usuario')) {
        // Lembrete de confirmar instalacao: depois de a pagina montar.
        if (checkAuth()) setTimeout(() => { try { lembrarInstalacoesAoAbrir(); } catch (e) { console.error(e); } }, 0);
        carregarTema();
        renderDashboardsButton();
        renderMenuExtrasEstoque();
        renderBellIndicator();
        initPageNavigation();
        if (typeof iniciarLembretesAgenda === 'function') iniciarLembretesAgenda();
        const popupUserEl = document.getElementById('popup-user-name');
        if (popupUserEl) {
            const u = getUsuarioLogado() || JSON.parse(sessionStorage.getItem('sc_user') || '{}');
            popupUserEl.textContent = nomeExibicao(u) || u.email || '—';
        }
    }

    // Pending toast from previous action
    const pt = sessionStorage.getItem('sc_pending_toast');
    if (pt) { try { const { msg, tipo } = JSON.parse(pt); sessionStorage.removeItem('sc_pending_toast'); setTimeout(() => toast(msg, tipo), 200); } catch {} }

    if (document.getElementById('tb-pedidos')) {
        localStorage.removeItem('sc_editando_id');
        const arquivoAtual = (window.location.pathname.split('/').pop() || 'index.html').toLowerCase();
        const telaFiltro = arquivoAtual === 'pedidos.html' ? 'pedidos' : 'painel_acompanhamento';
        inicializarFiltroVendedorTela(telaFiltro);
        const rolagemPedidos = lembrarListaPedidosAoRecarregar(telaFiltro);
        // Vindo do Financeiro ("Abrir pedido"): a lista ja chega buscando o numero do pedido.
        const buscaUrl = new URLSearchParams(window.location.search).get('busca');
        if (buscaUrl && arquivoAtual === 'pedidos.html') { const t = document.getElementById('filtro-texto'); if (t) t.value = buscaUrl; }
        renderDashboard();
        if (rolagemPedidos) rolagemPedidos();
    }

    if (document.getElementById('tb-catalogo')) {
        const catFornSel = document.getElementById('cat-fornecedor');
        if (catFornSel) catFornSel.innerHTML = '<option value="">— Sem fornecedor —</option>' +
            db.fornecedores.map(f => `<option value="${f.id}">${f.nome}</option>`).join('');
        renderCatalogoTecidos();
        lembrarAbaAoRecarregar('catalogo', () => _curTabCatalogo, mostrarTabCatalogo, t => ['tecidos', 'materiais', 'kits'].includes(t));
    }

    if (document.getElementById('tb-clientes')) {
        if (!temAcesso('clientes', 'completo')) document.getElementById('cli-form-card')?.style.setProperty('display', 'none');
        const cliCampos = document.getElementById('cli-end-campos');
        if (cliCampos) { cliCampos.innerHTML = enderecoCamposHtml('cli', { obrigRua: false, ir: true }); enderecoAnexar('cli'); }
        renderTabelaClientes(db.clientes);
    }

    // Formulário de Pedido
    if (document.getElementById('ped-cliente')) {
        if (!temAcesso('pedidos', 'completo')) {
            toastReload('Você não tem permissão para criar ou editar pedidos.', 'info');
            window.location.replace('pedidos.html');
            return;
        }
        filtrarClientes();

        const vendSel = document.getElementById('ped-vendedor');
        if (vendSel) vendSel.innerHTML = '<option value="">— Sem vendedor —</option>' + opcoesCadastroPedido('vendedor');
        const arqSel = document.getElementById('ped-arquiteto');
        if (arqSel) arqSel.innerHTML = '<option value="">— Sem arquiteto —</option>' + opcoesCadastroPedido('arquiteto');

        const kitSel = document.getElementById('ped-kit');
        // Kit pronto aparece com medida e preço; kit de montagem, só o nome.
        if (kitSel) kitSel.innerHTML = '<option value="">— Selecione um kit —</option>' +
            db.kits.map(k => {
                const extra = ehKitPronto(k)
                    ? `${k.medida ? ' · ' + k.medida : ''} · R$ ${(k.preco || 0).toFixed(2)}`
                    : (ehKitFixacao(k) ? ' (fixação)' : ' (montagem)');
                return `<option value="${k.id}">${escapeHtml(k.nome)}${escapeHtml(extra)}</option>`;
            }).join('');

        const matSel = document.getElementById('ped-item-mat');
        if (matSel) matSel.innerHTML = '<option value="">— Selecione o material —</option>' +
            db.materiais.map(m=>`<option value="${m.id}">${m.nome} (${m.unidade}) · estoque: ${(m.estoque_atual||0).toFixed(1)}</option>`).join('');

        preencherSelectFormaPagamento();   // pedido novo: a primeira da lista
        preencherSelectsMeioPedido();
        const idParaEditar = localStorage.getItem('sc_editando_id');
        if (idParaEditar) {
            editandoIdPedido = parseInt(idParaEditar);
            document.getElementById('titulo-pagina-pedido').innerText = `Editando Pedido #${formatPedidoId(editandoIdPedido)}`;
            carregarPedidoParaEdicao(editandoIdPedido);
            bloquearPedidoAprovado();
        } else {
            adicionarAmbiente();
            renderItensPedido();
            aplicarDescontoDaFormaPagamento();   // desconto da forma que vem marcada
            // Pré-preenche cliente quando vindo de "Criar Pedido" na medição
            const prePed = localStorage.getItem('sc_novo_pedido_pre');
            if (prePed) {
                localStorage.removeItem('sc_novo_pedido_pre');
                try {
                    const d = JSON.parse(prePed);
                    pedidoMedicaoId = d.medicaoId || null;
                    if (d.clienteId || d.clienteNome) {
                        const buscaEl = document.getElementById('ped-cliente-busca');
                        if (buscaEl && d.clienteNome) buscaEl.value = d.clienteNome;
                        filtrarClientes();
                        const sel = document.getElementById('ped-cliente');
                        if (sel && d.clienteId) sel.value = String(d.clienteId);
                    }
                } catch(e) {}
            }
        }
    }

    // Estoque (aba de tecidos)
    if (document.getElementById('tb-estoque')) {
        // O campo de tecido e' de busca: a lista sai de db.catalogo na hora de
        // digitar, entao nao ha <option> para montar aqui.
        const dataEl = document.getElementById('est-data');
        if (dataEl) dataEl.value = new Date().toISOString().split('T')[0];
        renderEstoque();
        const _savedEstTab = sessionStorage.getItem('sc_restore_tab_estoque');
        if (_savedEstTab) {
            sessionStorage.removeItem('sc_restore_tab_estoque');
            setTimeout(() => mostrarTabEstoque(_savedEstTab), 0);
        }
        window.addEventListener('beforeunload', () => {
            sessionStorage.setItem('sc_restore_tab_estoque', _curTabEstoque);
        });
    }

    // Estoque (aba de entrada de materiais)
    if (document.getElementById('tb-estoque-mat')) {
        const dataEl = document.getElementById('est-mat-data');
        if (dataEl) dataEl.value = new Date().toISOString().split('T')[0];
        renderEstoqueMateriais();
    }

    // Catálogo (aba de materiais)
    if (document.getElementById('tb-materiais')) {
        const matFornSel = document.getElementById('mat-fornecedor');
        if (matFornSel) matFornSel.innerHTML = '<option value="">— Sem fornecedor —</option>' +
            db.fornecedores.map(f => `<option value="${f.id}">${f.nome}</option>`).join('');
        renderMateriais();
    }

    // Aba de kits — existe no Estoque (montagem) e no Catálogo (kit pronto)
    if (document.getElementById('tb-kits')) {
        const matSel = document.getElementById('kit-item-mat');
        if (matSel) matSel.innerHTML = '<option value="">— Selecione o material —</option>' +
            db.materiais.map(m=>`<option value="${m.id}">${m.nome} (${m.unidade})</option>`).join('');
        renderKitDraftItens();
        renderKits();
        renderCfgKitPronto();
    }

    // Cartões de margem e estoque do cadastro de tecido e de material
    if (document.getElementById('cat-cfg')) renderCartoesConfig('cat');
    if (document.getElementById('mat-cfg')) renderCartoesConfig('mat');

    if (document.getElementById('tb-historico')) renderHistorico();

    if (document.getElementById('proposta-container')) renderProposta();
    if (document.getElementById('kanban-board')) {
        const kfVend = document.getElementById('kf-vendedor');
        if (kfVend) kfVend.innerHTML = '<option value="">Todos</option>' +
            db.vendedores.map(v => `<option value="${escapeHtml(v.nome)}">${escapeHtml(v.nome)}</option>`).join('');
        const kfTec = document.getElementById('kf-tecido');
        if (kfTec) kfTec.innerHTML = '<option value="">Todos</option>' +
            db.catalogo.map(c => `<option value="${c.id}">${escapeHtml(c.nome)}</option>`).join('');
        _kanbanRestaurarFiltro();
        renderKanban();
    }
    if (document.getElementById('os-container'))       renderOS();
    if (document.getElementById('agenda-container')) {
        _agdMontarEnderecosInst();
        _instLimparForm();
        renderAgenda();
    }
    if (document.getElementById('tb-rel-fat')) {
        renderRelatorios();
        lembrarAbaAoRecarregar('relatorios', () => _curTabRel, mostrarTabRel, t => ['faturamento', 'recebiveis', 'vendedores'].includes(t));
    }

    // Medições
    if (document.getElementById('medicoes-container')) {
        const sel = document.getElementById('med-cliente-id');
        if (sel) sel.innerHTML = '<option value="">— Selecione —</option>' +
            db.clientes.map(c => `<option value="${c.id}">${escapeHtml(c.nome)}</option>`).join('');
        const dataEl = document.getElementById('med-data');
        if (dataEl) dataEl.value = _agdHoje();
        _agdMontarEnderecosMed();
        _agdPreencherProf('med-prof', '', '— A definir —');
        _agdPreencherDur('med-dur', 'med');
        renderMedicoes();
        const params  = new URLSearchParams(window.location.search);
        const urlView = params.get('view');
        if (urlView) mostrarViewPCP(urlView);
        lembrarAbaAoRecarregar('pcp', () => _curViewPCP, mostrarViewPCP,
            t => !params.get('pedido') && ['kanban', 'agenda', 'medicoes', 'rotas'].includes(t));
        // Vindo do aviso de recusa de medicao ("Reagendar"): abre o formulario de editar.
        if (urlView === 'medicoes' && params.get('reagendarmed')) {
            editarMedicao(params.get('reagendarmed'));
            try { params.delete('reagendarmed'); const qs = params.toString(); history.replaceState(null, '', window.location.pathname + (qs ? '?' + qs : '') + window.location.hash); } catch (e) {}
        }
        // Vindo de outra tela com ?pedido=: o pedido ja chega selecionado.
        if (urlView === 'agenda' && params.get('pedido')) {
            irParaAgendaInstalacao(params.get('pedido'));
            // Vindo do lembrete de confirmar ("Ainda não" > "Reagendar").
            const pReag = params.get('reagendar') && db.pedidos.find(x => x.id == params.get('pedido'));
            if (pReag && _instPendente(pReag)) reagendarInstalacao(pReag.id);
            // Recarregar a pagina nao reabre o reagendamento.
            if (params.get('reagendar')) {
                try { params.delete('reagendar'); const qs = params.toString(); history.replaceState(null, '', window.location.pathname + (qs ? '?' + qs : '') + window.location.hash); } catch (e) {}
            }
        }

        // Outra aba/usuario mexeu nas agendas: a disponibilidade se atualiza aqui.
        window.addEventListener('storage', e => {
            if (e.key === 'sc_usr' || e.key === 'sc_pap') { _agdAtualizarListaProf(); _agdRedesenharAgendas(); return; }
            if (e.key !== 'sc_ped' && e.key !== 'sc_med' && e.key !== 'sc_agd_cfg' && e.key !== 'sc_agd_ev') return;
            _agdRecarregar();
            _agdRedesenharAgendas();
            if (document.getElementById('kanban-board')) renderKanban();
        });
    }

    if (document.getElementById('tb-vendedores')) {
        preencherSelectUsuarios('vend-usuario', '— Sem conta de acesso —');
        const url = new URLSearchParams(window.location.search);
        const aba = url.get('aba');
        if (['lista', 'comissoes'].includes(aba)) _curTabVend = aba;
        else if (['pendentes', 'historico'].includes(aba)) _curTabVend = 'comissoes'; // links antigos
        mostrarTipoVendedores(url.get('tipo') === 'arquiteto' ? 'arquiteto' : 'vendedor');
    }

    if (document.getElementById('cfg-perfil')) iniciarConfiguracoes();

    if (document.getElementById('tb-fornecedores')) {
        const pcFornSel = document.getElementById('pc-fornecedor');
        if (pcFornSel) pcFornSel.innerHTML = _pcOpcoesFornecedorHTML(db.fornecedores);
        const filtroFornEl = document.getElementById('filtro-pc-forn');
        if (filtroFornEl) filtroFornEl.innerHTML = '<option value="">Todos os fornecedores</option>' +
            db.fornecedores.map(f => `<option value="${f.id}">${f.nome}</option>`).join('');
        const urlTab = new URLSearchParams(window.location.search).get('tab');

        // Fila de "um pedido por fornecedor": cada recarga carrega o próximo.
        const fila = lerFilaPC();
        if (fila && !localStorage.getItem('sc_pc_prefill')) {
            const g = fila.restantes[0];
            localStorage.setItem('sc_pc_prefill', JSON.stringify(g.itens));
            localStorage.setItem('sc_pc_prefill_forn', String(g.fornecedor_id || 0));
        }

        const prefillItem = localStorage.getItem('sc_pc_prefill');
        // A origem (pedido de venda) so vale para o pedido que chega pronto
        // (importado ou da fila); um formulario aberto a mao nao a herda.
        if (!prefillItem) localStorage.removeItem('sc_pc_origem');
        if (urlTab === 'novo' || prefillItem) {
            mostrarTabFornecedores('novo');
            if (prefillItem) {
                try {
                    const bruto = JSON.parse(prefillItem);
                    // Formato antigo: um item só, fora de lista.
                    const itens = Array.isArray(bruto) ? bruto : [bruto];
                    pcDraftItens = itens.map(({ fornecedor_id, fornecedor_nome, ...i }) => {
                        const quantidade = i.quantidade || 1;
                        return { ...i, quantidade, subtotal: quantidade * (i.preco_unit || 0) };
                    });
                    renderItensPCDraft();
                    const tipoSel = document.getElementById('pc-item-tipo');
                    if (tipoSel && itens[0]) { tipoSel.value = itens[0].tipo; atualizarSelectItemPC(); }
                } catch {}
                localStorage.removeItem('sc_pc_prefill');
            }
            const prefillForn = localStorage.getItem('sc_pc_prefill_forn');
            if (prefillForn !== null && pcFornSel) { pcFornSel.value = prefillForn; localStorage.removeItem('sc_pc_prefill_forn'); }
            if (prefillItem) {
                const obsEl = document.getElementById('pc-obs');
                const o = _pcLerOrigem();
                if (o && obsEl && !obsEl.value) obsEl.value = _pcObsDaOrigem(o);
            }
            renderBannerFilaPC();
        } else {
            mostrarTabFornecedores(urlTab === 'pedidos' ? 'pedidos' : 'lista');
        }
        const _abaPronta = !!(urlTab === 'novo' || prefillItem);
        lembrarAbaAoRecarregar('fornecedores', () => _curTabForn, mostrarTabFornecedores,
            t => !_abaPronta && ['lista', 'novo', 'pedidos'].includes(t));
    }

    if (document.getElementById('pedido-compra-container')) renderPedidoCompraDoc();

    if (document.getElementById('fin-resumo')) {
        atualizarStatusVencimentos();
        renderAvisoCopiaFinanceiro();
        renderAvisoRevisaoFinanceiro();
        // So as 4 abas novas (e as antigas cujo recurso foi religado) aparecem, conforme a permissao.
        _finMontarAbasAntigas();
        const abasVisiveis = Object.keys(FIN_TAB_MODULO).filter(t => finAbaVisivel(t) && (FIN_ABAS_NOVAS.includes(t) || FIN_ABA_ANTIGA_RECURSO[t]));
        document.querySelectorAll('.fin-tab-btn').forEach(b => {
            b.style.setProperty('display', finAbaVisivel(b.dataset.tab) ? '' : 'none');
        });
        // Sem nenhuma aba permitida: mesmo comportamento de quem nao tem acesso ao Financeiro.
        if (!abasVisiveis.length) { window.location.replace('index.html'); return; }
        const abaInicial = FIN_ABAS_NOVAS.find(t => abasVisiveis.includes(t)) || abasVisiveis[0];
        mostrarTabFinanceiro(abaInicial);
        lembrarAbaAoRecarregar('financeiro', () => _curTabFin, mostrarTabFinanceiro, t => abasVisiveis.some(x => x === t));
        // Link de um alerta do sino/card (financeiro.html?aba=receber) ou link antigo (?tab=hoje, #hoje):
        // abre a aba que hoje cuida do assunto, se o usuario pode ve-la.
        const _qs = new URLSearchParams(window.location.search);
        const abaLink = _qs.get('aba') || _qs.get('tab') || _qs.get('view') || (window.location.hash || '').replace('#', '');
        if (abaLink && FIN_TAB_MODULO[abaLink]) {
            const dest = finAbaDestino(abaLink);
            if (abasVisiveis.includes(dest.tab)) mostrarTabFinanceiro(dest.tab, dest.lado);
        }
        // Usou o link: tira ?aba= do endereco, senao ele ganharia da aba lembrada no F5.
        if (abaLink) { try { const u = new URL(window.location.href); ['aba', 'tab', 'view'].forEach(k => u.searchParams.delete(k)); history.replaceState(null, '', u.pathname + u.search + u.hash); } catch (e) {} }
        if (!temAcesso('financeiro.pagar', 'completo')) document.getElementById('cp-toolbar')?.style.setProperty('display', 'none');
        if (!temAcesso('financeiro.fixas', 'completo')) document.getElementById('df-form-card')?.style.setProperty('display', 'none');
    }
});

// =============================================
// CATÁLOGO — TABS
// =============================================

// Mostruario da Galeria (sc_mostruario): so ids das imagens; os bytes ficam
// em GaleriaImagens. Os trilhos partem dos kits de fixacao da empresa.
function nomesTrilhosMostruario() {
    const kits = (db.kits || []).filter(k => k && k.fixacao === true && k.nome).map(k => k.nome);
    return kits.length ? kits : KITS_FIXACAO_PADRAO.slice();
}
function lerMostruarioSalvo() {
    let bruto = null;
    try { bruto = JSON.parse(localStorage.getItem('sc_mostruario')); } catch (e) { bruto = null; }
    return GaleriaCore.lerMostruario(bruto, nomesTrilhosMostruario());
}
function gravarMostruario(m) {
    localStorage.setItem('sc_mostruario', JSON.stringify(m));
}

// Configurar Empresa: abas Dados, Preferencias, Layout dos Documentos,
// Etiquetas e Galeria e Mostruario. A aba aberta vai para o endereco (#layout), para o recarregar
// e os atalhos voltarem nela.
const ABAS_EMPRESA = ['dados', 'preferencias', 'layout', 'etiquetas', 'galeria'];
function mostrarTabEmpresa(tab) {
    if (!ABAS_EMPRESA.includes(tab)) tab = 'dados';
    document.querySelectorAll('.emp-tab-panel').forEach(p => p.classList.toggle('active', p.id === 'tab-emp-' + tab));
    document.querySelectorAll('.emp-tab-btn').forEach(b => b.classList.toggle('active', b.dataset.tab === tab));
    const btn = document.querySelector(`.emp-tab-btn[data-tab="${tab}"]`);
    if (btn && btn.scrollIntoView) btn.scrollIntoView({ block: 'nearest', inline: 'nearest' });
    if (location.hash.slice(1) !== tab && (tab !== 'dados' || location.hash)) history.replaceState(null, '', '#' + tab);
    // os editores medem a largura da tela (escondidos, mediram zero), e a
    // logo pode ter mudado na aba Dados
    if (tab === 'layout' && typeof atualizarEditorLayouts === 'function') atualizarEditorLayouts();
    if (tab === 'etiquetas' && typeof _etqRender === 'function') _etqRender();
}

function mostrarTabCatalogo(tab) {
    if (_curTabCatalogo !== tab) { _prevTabCatalogo = _curTabCatalogo; _curTabCatalogo = tab; }
    document.querySelectorAll('.tab-panel').forEach(p => p.classList.remove('active'));
    document.querySelectorAll('.tab-btn').forEach(b => b.classList.remove('active'));
    document.getElementById('tab-cat-' + tab)?.classList.add('active');
    document.querySelector(`.tab-btn[data-tab="cat-${tab}"]`)?.classList.add('active');
    if (tab === 'materiais') renderMateriais();
    if (tab === 'kits') renderKits();
    _tabBackBtn('.tab-nav', _prevTabCatalogo, () => mostrarTabCatalogo(_prevTabCatalogo));
}

// =============================================
// ESTOQUE — ENTRADA DE MATERIAL
// =============================================

function autoFillEntradaMaterialPorRef() {
    const ref = document.getElementById('est-mat-ref')?.value.trim();
    if (!ref || ref.length < 2) return;
    const mat = db.materiais.find(m => m.referencia && m.referencia.toLowerCase() === ref.toLowerCase());
    if (!mat) return;
    if (!document.getElementById('est-mat-id')) return;
    buscaDefinir('est-mat-id', mat.id);
    autoFillEntradaMaterialById();
}

function calcularPrecoVendaMat() { _calcularPrecoVenda('est-mat-preco-custo', 'est-mat-markup', 'est-mat-preco-venda-display'); }

async function salvarEntradaMaterial() {
    const matId  = parseInt(document.getElementById('est-mat-id')?.value);
    const qtd    = parseFloat(document.getElementById('est-mat-qtd')?.value);
    const data   = document.getElementById('est-mat-data')?.value;
    const custo  = parseFloat(document.getElementById('est-mat-preco-custo')?.value) || 0;
    const markup = parseFloat(document.getElementById('est-mat-markup')?.value) || 0;
    if (!matId) { await showAlert('Escolha o material na lista de sugestões.', '⚠️'); return; }
    if (!qtd || qtd <= 0) { await showAlert('Informe uma quantidade válida.', '⚠️'); return; }
    const mat = db.materiais.find(m => m.id === matId);
    if (!mat) return;
    const precoVendaMatConf = custo > 0 ? (custo * (1 + markup / 100)).toFixed(2) : null;
    const linhaPrecoMat = custo > 0 ? `\nCusto: R$ ${custo.toFixed(2)}  →  Venda: R$ ${precoVendaMatConf}` : '';
    if (!await showConfirm(`Confirmar entrada de material?\n\nMaterial: ${mat.nome}\nQuantidade: ${qtd} ${mat.unidade}${linhaPrecoMat}`, '📦', 'Confirmar Entrada', 'Cancelar')) return;
    _aplicarEntradaMaterial({ mat, qtd, data, custo, markup });
    salvarERecarregar('Entrada de material registrada!');
}

// Grava a entrada de material: saldo, custo/preco e o movimento "Entrada".
// Usada pela entrada manual e pela do pedido de compra Recebido.
function _aplicarEntradaMaterial({ mat, qtd, data, custo, markup }) {
    mat.estoque_atual = Math.round(((mat.estoque_atual || 0) + qtd) * 1000) / 1000;
    if (custo > 0) {
        mat.preco_custo = custo;
        if (markup !== null) mat.preco = Math.round(custo * (1 + markup / 100) * 100) / 100;
    }
    const refData = data ? `Entrada ${new Date(data + 'T12:00:00').toLocaleDateString('pt-BR')}` : 'Entrada manual';
    registrarMovimento('Entrada', mat.nome, 'material', qtd, mat.unidade, refData);
}

// Entrada de kit pronto (so pelo pedido de compra Recebido).
function _aplicarEntradaKit({ kit, qtd, data }) {
    kit.estoque_atual = Math.round(((kit.estoque_atual || 0) + qtd) * 1000) / 1000;
    const refData = data ? `Entrada ${new Date(data + 'T12:00:00').toLocaleDateString('pt-BR')}` : 'Entrada manual';
    registrarMovimento('Entrada', kit.nome, 'kit', qtd, 'un', refData);
}

// ─── CONSULTA DE ESTOQUE ─────────────────────────────────────────────────────
// Lista compacta de consulta rapida: uma linha por produto, com os detalhes
// (fornecedor, custo, minimo e os rolos do tecido) escondidos ate o clique.

// Qual linha esta expandida agora. So uma por vez.
let _consultaAberto = null;

function _consultaMoeda(v) {
    return v != null && v > 0
        ? 'R$ ' + Number(v).toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 })
        : '—';
}

function _consultaNum(v, casas) {
    return Number(v || 0).toLocaleString('pt-BR', {
        minimumFractionDigits: casas === undefined ? 2 : casas,
        maximumFractionDigits: casas === undefined ? 2 : casas
    });
}

// Busca tolerante: ignora caixa e acento, para "trico" achar "TRICÔ".
function _consultaNormaliza(s) {
    return String(s === null || s === undefined ? '' : s)
        .normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase().trim();
}

// Monta a lista unificada de tecidos e materiais no mesmo formato, para a
// tela nao precisar saber de qual dos dois cadastros veio cada linha.
function _consultaItens() {
    const itens = [];

    (db.catalogo || []).forEach(tec => {
        const rolos = (db.estoque || []).filter(r => r.tecido_id == tec.id);
        const disponivel = rolos.reduce((s, r) => s + (r.metragem_atual || 0), 0);
        const ultimo = rolos.filter(r => r.data_entrada)
            .sort((a, b) => b.data_entrada.localeCompare(a.data_entrada))[0];
        itens.push({
            tipo: 'tecido',
            id: tec.id,
            unidade: 'm',
            codigo: tec.referencia || '',
            nome: tec.nome || '',
            precoTxt: tec.preco > 0 ? _consultaMoeda(tec.preco) + '/m' : '—',
            estoqueTxt: temEstoqueInfinito(tec) ? '∞' : _consultaNum(disponivel) + ' m',
            abaixoMin: !temEstoqueInfinito(tec) && tec.min_estoque > 0 && disponivel < tec.min_estoque,
            ultimaEntrada: ultimo ? new Date(ultimo.data_entrada + 'T12:00:00').toLocaleDateString('pt-BR') : '—',
            registro: tec,
            rolos
        });
    });

    (db.materiais || []).forEach(mat => {
        const entradas = (db.movimentos || []).filter(mv =>
            mv.tipo === 'Entrada' && mv.item_tipo === 'material' && mv.item_nome === mat.nome);
        const ultimo = entradas.length ? entradas.sort((a, b) => b.data - a.data)[0] : null;
        itens.push({
            tipo: 'material',
            id: mat.id,
            unidade: mat.unidade || 'un',
            codigo: mat.referencia || '',
            nome: mat.nome || '',
            precoTxt: mat.preco > 0 ? _consultaMoeda(mat.preco) : '—',
            estoqueTxt: temEstoqueInfinito(mat) ? '∞' : _consultaNum(mat.estoque_atual) + ' ' + (mat.unidade || ''),
            abaixoMin: !temEstoqueInfinito(mat) && mat.min_estoque > 0 && (mat.estoque_atual || 0) < mat.min_estoque,
            ultimaEntrada: ultimo ? new Date(ultimo.data).toLocaleDateString('pt-BR') : '—',
            registro: mat,
            rolos: null
        });
    });

    (db.kits || []).forEach(kit => {
        // Ultima entrada vem do historico de movimentos, igual ao material.
        // Kit de montagem nao tem preco nem saldo proprios: ele e explodido
        // nos materiais no pedido, entao esses campos ficam em branco.
        const entradas = (db.movimentos || []).filter(mv =>
            mv.tipo === 'Entrada' && mv.item_tipo === 'kit' && mv.item_nome === kit.nome);
        const ultimo = entradas.length ? entradas.sort((a, b) => b.data - a.data)[0] : null;
        const pronto = ehKitPronto(kit);
        itens.push({
            tipo: 'kit',
            id: kit.id,
            unidade: 'un',
            codigo: kit.referencia || '',
            nome: kit.nome || '',
            precoTxt: pronto && kit.preco > 0 ? _consultaMoeda(kit.preco) : '—',
            estoqueTxt: temEstoqueInfinito(kit) ? '∞'
                : (pronto ? _consultaNum(kit.estoque_atual) + ' un' : '—'),
            abaixoMin: false,
            ultimaEntrada: ultimo ? new Date(ultimo.data).toLocaleDateString('pt-BR') : '—',
            registro: kit,
            rolos: null
        });
    });

    // Ordem por codigo, com comparacao numerica para 0002 vir antes de 0010.
    return itens.sort((a, b) =>
        String(a.codigo).localeCompare(String(b.codigo), 'pt-BR', { numeric: true, sensitivity: 'base' })
        || String(a.nome).localeCompare(String(b.nome), 'pt-BR'));
}

// Aplica os tres filtros juntos: codigo E nome E tipo.
function _consultaFiltrar(itens) {
    const codigo = _consultaNormaliza(document.getElementById('consulta-codigo')?.value);
    const nome   = _consultaNormaliza(document.getElementById('consulta-busca')?.value);
    const tipo   = document.getElementById('consulta-tipo')?.value || '';
    return itens.filter(i =>
        (!tipo   || i.tipo === tipo) &&
        (!codigo || _consultaNormaliza(i.codigo).includes(codigo)) &&
        (!nome   || _consultaNormaliza(i.nome).includes(nome)));
}

function _consultaChave(item) { return item.tipo + '-' + item.id; }

function _consultaDetalheHTML(item) {
    const r = item.registro;
    const campo = (rotulo, valor) =>
        `<div class="consulta-info-item"><span class="consulta-info-label">${rotulo}</span><span>${valor}</span></div>`;

    // O preco de custo NAO aparece aqui — a consulta e de venda e de saldo.
    // O valor continua gravado no registro e visivel nas telas de cadastro.
    let campos = campo('Fornecedor', escapeHtml(r.fornecedor_nome || '—'));

    if (item.tipo === 'kit') {
        campos += campo('Tipo de kit', ehKitPronto(r) ? 'Kit pronto' : 'Kit de montagem');
        campos += campo('Medida', escapeHtml(r.medida || '—'));
        if (r.descricao) campos += campo('Descrição', escapeHtml(r.descricao));
        if (!ehKitPronto(r)) {
            const comp = (r.itens || []).map(i => `${escapeHtml(i.nome)}: ${i.quantidade} ${i.unidade}`).join(' · ');
            campos += campo('Composição', comp || '—');
        }
    } else if (item.tipo === 'tecido') {
        campos += campo('Estoque mínimo', textoMinimo(r, 'm'));
        campos += campo('Largura do rolo', r.largura_rolo ? _consultaNum(r.largura_rolo) + ' m' : '—');
    } else {
        campos += campo('Estoque mínimo', textoMinimo(r, r.unidade));
        campos += campo('Unidade', escapeHtml(r.unidade || '—'));
    }

    let rolosHtml = '';
    if (item.tipo === 'tecido') {
        rolosHtml = item.rolos.length ? `
        <table>
            <thead><tr>
                <th>Código</th><th>Metragem inicial</th>
                <th>Disponível</th><th>Data de entrada</th><th>Status</th>
            </tr></thead>
            <tbody>${item.rolos.map(ro => {
                const pct = ro.metragem_inicial > 0 ? Math.round((ro.metragem_atual / ro.metragem_inicial) * 100) : 0;
                const cor = pct > 40 ? 'var(--primary)' : pct > 15 ? 'var(--kpi-yellow)' : 'var(--danger)';
                const status = ro.metragem_atual <= 0
                    ? '<span class="badge-esgotado">Esgotado</span>'
                    : `<span style="color:${cor};font-weight:600">${pct}% restante</span>`;
                return `<tr>
                    <td>${escapeHtml(ro.lote || '—')}</td>
                    <td>${_consultaNum(ro.metragem_inicial)} m</td>
                    <td><strong>${_consultaNum(ro.metragem_atual, 3)} m</strong></td>
                    <td>${ro.data_entrada ? new Date(ro.data_entrada + 'T12:00:00').toLocaleDateString('pt-BR') : '—'}</td>
                    <td>${status}</td>
                </tr>`;
            }).join('')}</tbody>
        </table>`
            : '<p style="font-size:12px;color:var(--muted);margin-top:12px">Nenhum rolo em estoque.</p>';
    }

    return `<div class="consulta-detalhe">
        <div class="consulta-detalhe-grid">${campos}</div>
        ${rolosHtml}
    </div>`;
}

function renderConsultaEstoque() {
    const container = document.getElementById('consulta-resultados');
    if (!container) return;

    const itens = _consultaFiltrar(_consultaItens());

    if (!itens.length) {
        container.innerHTML = `<div class="consulta-lista"><div class="consulta-vazio">
            Nenhum item encontrado com esses filtros.
        </div></div>`;
        return;
    }

    const linhas = itens.map(item => {
        const chave = _consultaChave(item);
        const aberto = _consultaAberto === chave;
        const tag = item.tipo === 'tecido' ? '<span class="consulta-tag tec">TEC</span>'
            : item.tipo === 'kit' ? '<span class="consulta-tag kit">KIT</span>'
            : '<span class="consulta-tag mat">MAT</span>';
        return `<div class="consulta-linha ${aberto ? 'aberta' : ''}" onclick="toggleConsultaDetalhe('${chave}')">
                <span class="consulta-cod">${escapeHtml(item.codigo || '—')}</span>
                <span class="consulta-nome">${tag}${escapeHtml(item.nome)}</span>
                <span class="consulta-un">${escapeHtml(item.unidade || '—')}</span>
                <span class="consulta-preco">${item.precoTxt}</span>
                <span class="consulta-qtd ${item.abaixoMin ? 'baixo' : ''}">${item.estoqueTxt}${item.abaixoMin ? ' ⚠' : ''}</span>
                <span class="consulta-data">${item.ultimaEntrada}</span>
                <span class="consulta-seta">${aberto ? '▲' : '▼'}</span>
            </div>
            ${aberto ? _consultaDetalheHTML(item) : ''}`;
    }).join('');

    container.innerHTML = `<div class="consulta-lista">
        <div class="consulta-cab">
            <span>Código</span><span>Nome</span><span>Unidade</span><span>Preço de venda</span>
            <span>Estoque</span><span>Última entrada</span><span></span>
        </div>
        ${linhas}
    </div>
    <p style="font-size:12px;color:var(--muted);margin:10px 2px">${itens.length} item(ns). Clique numa linha para ver fornecedor e detalhes.</p>`;
}

function toggleConsultaDetalhe(chave) {
    _consultaAberto = _consultaAberto === chave ? null : chave;
    renderConsultaEstoque();
}

// ── Vinculo entre os campos Codigo e Nome ───────────────────────────────────
// Digitar em um deles sugere os itens correspondentes; escolher uma sugestao
// preenche os dois. Enquanto o usuario nao escolhe, nada e preenchido sozinho:
// preencher no meio da digitacao faria os dois filtros brigarem entre si.

function consultaFiltroMudou(campo) {
    consultaSugerir(campo);
    renderConsultaEstoque();
}

function consultaSugerir(campo) {
    const idCampo = campo === 'codigo' ? 'consulta-codigo' : 'consulta-busca';
    const caixa = document.getElementById(campo === 'codigo' ? 'consulta-sug-codigo' : 'consulta-sug-nome');
    if (!caixa) return;

    const termo = _consultaNormaliza(document.getElementById(idCampo)?.value);
    _consultaFecharSugestoes(campo === 'codigo' ? 'nome' : 'codigo');

    if (!termo) { caixa.classList.remove('aberta'); caixa.innerHTML = ''; return; }

    const tipo = document.getElementById('consulta-tipo')?.value || '';
    const achados = _consultaItens().filter(i =>
        (!tipo || i.tipo === tipo) &&
        _consultaNormaliza(campo === 'codigo' ? i.codigo : i.nome).includes(termo)
    ).slice(0, 12);

    if (!achados.length) { caixa.classList.remove('aberta'); caixa.innerHTML = ''; return; }

    caixa.innerHTML = achados.map(i => `
        <div class="consulta-sug-item" onclick="consultaEscolherSugestao('${_consultaChave(i)}')">
            <span class="consulta-sug-cod">${escapeHtml(i.codigo || '—')}</span>
            <span class="consulta-sug-nome">${escapeHtml(i.nome)}</span>
        </div>`).join('');
    caixa.classList.add('aberta');
}

function consultaEscolherSugestao(chave) {
    const item = _consultaItens().find(i => _consultaChave(i) === chave);
    if (!item) return;
    const campoCodigo = document.getElementById('consulta-codigo');
    const campoNome   = document.getElementById('consulta-busca');
    if (campoCodigo) campoCodigo.value = item.codigo;
    if (campoNome)   campoNome.value = item.nome;
    _consultaFecharSugestoes('codigo');
    _consultaFecharSugestoes('nome');
    renderConsultaEstoque();
}

function _consultaFecharSugestoes(campo) {
    const caixa = document.getElementById(campo === 'codigo' ? 'consulta-sug-codigo' : 'consulta-sug-nome');
    if (caixa) { caixa.classList.remove('aberta'); caixa.innerHTML = ''; }
}

// Clique fora fecha as sugestoes abertas.
document.addEventListener('click', e => {
    if (e.target.closest && e.target.closest('.consulta-campo')) return;
    _consultaFecharSugestoes('codigo');
    _consultaFecharSugestoes('nome');
});

function renderEstoqueMateriais() {
    const alertBox = document.getElementById('alertas-mat-min');
    if (alertBox) {
        const criticos = db.materiais.filter(m => !temEstoqueInfinito(m) && m.min_estoque > 0 && (m.estoque_atual || 0) < m.min_estoque);
        alertBox.innerHTML = criticos.length
            ? criticos.map(m => `<div class="alerta-item">⚠ <strong>${escapeHtml(m.nome)}</strong>: ${(m.estoque_atual||0).toFixed(2)} ${m.unidade} — mínimo: ${m.min_estoque} ${m.unidade}</div>`).join('')
            : '';
        alertBox.style.display = criticos.length ? 'block' : 'none';
    }
    const tb = document.getElementById('tb-estoque-mat');
    if (!tb) return;
    if (!db.materiais.length) {
        tb.innerHTML = '<tr><td colspan="7" style="text-align:center;color:#999;padding:24px">Nenhum material cadastrado. <a href="catalogo.html">Cadastre em Catálogo</a>.</td></tr>';
        return;
    }
    const buscaMat = textoBuscaEstoque('busca-est-materiais');
    const lista = ordenarLista(db.materiais, matSortState, valorOrdenacaoMaterial).filter(m => passaBuscaEstoque(m, buscaMat));
    pintarCabecalhoOrdenacao('#tabela-est-materiais', matSortState);
    if (!lista.length) { tb.innerHTML = linhaNadaEncontrado(7); return; }
    tb.innerHTML = lista.map(m => {
        const abaixoMin = !temEstoqueInfinito(m) && m.min_estoque > 0 && (m.estoque_atual || 0) < m.min_estoque;
        const cor = abaixoMin ? '#F43927' : 'var(--primary-text)';
        return `<tr>
            <td class="col-codigo" title="${escapeHtml(m.referencia||'')}">${escapeHtml(m.referencia||'—')}</td>
            <td class="col-nome" title="${escapeHtml(m.nome)}"><strong>${escapeHtml(m.nome)}</strong>${abaixoMin?`<span class="badge-alerta" style="margin-left:6px">⚠</span>`:''}</td>
            <td class="col-un">${m.unidade}</td>
            <td class="col-num" style="color:${cor}" title="${temEstoqueInfinito(m) || !(m.min_estoque > 0) ? '' : 'Mínimo: ' + m.min_estoque + ' ' + (m.unidade || '')}">${temEstoqueInfinito(m)
                ? '<strong title="Estoque infinito">∞</strong>'
                : `<strong>${(m.estoque_atual||0).toFixed(2)}</strong>`}</td>
            <td class="col-num" style="color:var(--primary-text);font-weight:600">${m.preco > 0 ? 'R$ '+m.preco.toFixed(2) : '—'}</td>
            <td class="col-forn" title="${escapeHtml(m.fornecedor_nome||'')}">${escapeHtml(m.fornecedor_nome||'—')}</td>
            <td class="col-acoes">${botaoAdicionarAoCarrinho('material', m.id)}${menuAcoesHtml([
                { icone: '±', rotulo: 'Ajustar estoque', onclick: `mostrarAjusteForm(${m.id})` }
            ])}</td>
        </tr>
        <tr id="ajuste-${m.id}" class="ajuste-form" style="display:none">
            <td colspan="7" class="baixa-form-cell">
                <strong>${escapeHtml(m.nome)}</strong> — saldo: <strong>${(m.estoque_atual||0).toFixed(2)} ${m.unidade}</strong> &emsp;
                Quantidade (+ entrada / − saída):
                <input type="number" id="ajuste-qtd-${m.id}" placeholder="Ex: +10 ou -3" step="0.01" style="width:130px;padding:5px 8px;border:1px solid var(--border-strong);border-radius:4px;margin:0 8px">
                <button class="btn btn-sm" style="background:#005D3B" onclick="confirmarAjuste(${m.id})">Confirmar</button>
                <button class="btn btn-outline btn-sm" onclick="cancelarAjuste()">Cancelar</button>
            </td>
        </tr>`;
    }).join('');
}

// =============================================
// MÓDULO FINANCEIRO
// =============================================

// Datas do Financeiro sempre no fuso local ('YYYY-MM-DD'). toISOString() e UTC:
// depois das 21h no Brasil ja e o dia seguinte.
function dataLocal(ms) { return FinanceiroCore.dataLocalISO(ms == null ? Date.now() : ms); }
function hojeLocal() { return dataLocal(Date.now()); }

// --- Financeiro novo (v4): categorias, competencia, historico, cancelado ---
// Conta a receber/pagar ainda em aberto: nem paga, nem cancelada. Cancelado fica
// fora de totais, previsao, avisos e sino.
function finAberta(x) { return !!x && x.status !== 'Pago' && x.status !== 'Cancelado'; }

function _finQuem() {
    const u = getUsuarioLogado();
    return u ? { por: u.id, porNome: nomeExibicao(u) || u.email || '' } : { por: null, porNome: 'Sistema' };
}

// Acrescenta uma linha ao historico do lancamento, em nome de quem esta logado.
function finHist(reg, acao, detalhe) {
    if (!reg) return reg;
    return FinCatCore.registrarHistorico(reg, Object.assign({ acao, detalhe: detalhe || '', em: new Date().toISOString() }, _finQuem()));
}

function _finBrl(v) {
    return 'R$ ' + (Number(v) || 0).toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
}
function _finDataBR(d) { return d ? String(d).split('-').reverse().join('/') : ''; }

// Lancamento novo gerado pelo sistema ou digitado: grava categoria_id (pelo codigo
// antigo), data_competencia (FinCatCore.competenciaPadrao; guia de imposto pela
// referencia), cliente_id/fornecedor_id quando der para saber (mesma regra da
// migracao: pedido, CNPJ ou nome exato unico) e o historico "criado".
// `tipo`: 'cr' | 'cp'. `comp`: { origem, dataAprovacao, dataCompra, mesOcorrencia }.
function finCompletarLancamento(tipo, reg, comp, detalhe) {
    const ehCR = tipo === 'cr';
    if (!reg.categoria_id) { reg.categoria_id = FinCatCore.categoriaDoLegado(reg, ehCR ? 'receber' : 'pagar'); reg.categoria_auto = true; }
    if (!reg.data_competencia) {
        const c = reg.mes_referencia ? { origem: 'imposto', mesReferencia: reg.mes_referencia } : Object.assign({ origem: 'manual' }, comp || {});
        c.vencimento = reg.data_vencimento;
        const d = FinCatCore.competenciaPadrao(c);
        if (d) reg.data_competencia = d;
    }
    const campo = ehCR ? 'cliente_id' : 'fornecedor_id';
    if (reg[campo] == null || reg[campo] === '') {
        const copia = Object.assign({}, reg, { historico: [] });
        delete copia.categoria_id; delete copia.data_competencia; delete copia[campo];
        const plano = FinCatCore.planoMigracaoV4(ehCR
            ? { contas_receber: [copia], pedidos: db.pedidos, clientes: db.clientes }
            : { contas_pagar: [copia], fornecedores: db.fornecedores });
        const item = (ehCR ? plano.cr : plano.cp)[0];
        if (item && item.set[campo] !== undefined) reg[campo] = item.set[campo];
    }
    if (!Array.isArray(reg.historico) || !reg.historico.length) {
        reg.historico = [];
        finHist(reg, 'criado', detalhe);
    }
    return reg;
}

// Marca o lancamento como Cancelado (com quem, quando, motivo e historico). Nao grava.
function _finMarcarCancelado(reg, motivo) {
    const q = _finQuem();
    reg.status = 'Cancelado';
    reg.cancelado_em = new Date().toISOString();
    reg.cancelado_por = q.por;
    reg.motivo_cancelamento = motivo || '';
    finHist(reg, 'cancelado', motivo || '');
}

// Cancela um lancamento em aberto (pago precisa de estorno antes). Devolve true se
// cancelou. Nao grava: quem chama grava (syncDB/salvarERecarregar).
function cancelarLancamento(tipo, id, motivo) {
    const lista = tipo === 'cr' ? db.contas_receber : tipo === 'cp' ? db.contas_pagar : null;
    const reg = (lista || []).find(x => CaixaCore.mesmoId(x.id, id));
    if (!reg || !FinCatCore.podeCancelar(reg).ok) return false;
    _finMarcarCancelado(reg, motivo);
    return true;
}

// Anexo (dataURL) nao vai para copias e registros: fica a marca (nome e tipo do arquivo ficam).
const MARCA_ANEXO_NAO_COPIADO = '[anexo não copiado]';
function _finSemAnexos(reg) {
    if (!reg || typeof reg !== 'object') return reg;
    let o = reg;
    Object.keys(reg).forEach(k => {
        if (typeof reg[k] === 'string' && reg[k].startsWith('data:')) {
            if (o === reg) o = Object.assign({}, reg);
            o[k] = MARCA_ANEXO_NAO_COPIADO;
        }
    });
    return o;
}

// Lancamento excluido: fica o registro com o lancamento (sem o anexo) e quem excluiu.
function _finRegistrarExcluidos(tipo, regs) {
    if (!Array.isArray(db.fin_excluidos)) db.fin_excluidos = [];
    const q = _finQuem();
    const em = new Date().toISOString();
    (regs || []).forEach(r => db.fin_excluidos.push({ tipo, em, por: q.por, porNome: q.porNome, lancamento: JSON.parse(JSON.stringify(_finSemAnexos(r))) }));
}

// Saldo da conta bancaria mexido agora (baixa, estorno, ajuste).
function _finContaTocada(contaId) {
    const c = _contaFinPorId(contaId);
    // Data e hora locais 'AAAA-MM-DDTHH:MM' (valores antigos so com a data continuam valendo).
    if (c) { const d = new Date(), z = n => String(n).padStart(2, '0'); c.saldo_atualizado_em = hojeLocal() + 'T' + z(d.getHours()) + ':' + z(d.getMinutes()); }
}

// Tipo da conta no cadastro novo (corrente/poupanca/caixa/cartao), a partir do tipo
// de uso de hoje (caixa/banco/maquininha), que continua valendo para meios e cartao.
function _finTipoContaPadrao(tipo) {
    return tipo === 'caixa' ? 'caixa' : tipo === 'maquininha' ? 'cartao' : 'corrente';
}

// Campos novos da conta bancaria que faltam (so os que faltam).
function _finCamposContaPadrao(c, movimentos) {
    const set = {};
    if (c.banco === undefined) set.banco = null;
    if (c.agencia === undefined) set.agencia = '';
    if (c.numero_conta === undefined) set.numero_conta = '';
    if (c.tipo_conta === undefined) set.tipo_conta = _finTipoContaPadrao(c.tipo);
    if (c.conexao === undefined) set.conexao = 'manual';
    if (c.saldo_atualizado_em === undefined) {
        const hoje = hojeLocal();
        const datas = (movimentos || []).filter(m => m && CaixaCore.mesmoId(m.conta_id, c.id) && typeof m.data === 'string' && m.data <= hoje).map(m => m.data.slice(0, 10));
        set.saldo_atualizado_em = datas.length ? datas.reduce((a, b) => (b > a ? b : a)) : null;
    }
    return set;
}

// Migracao unica para o Financeiro novo (sc_fin_versao 4): categorias, competencia,
// cliente/fornecedor, historico, data de aprovacao do pedido e campos da conta
// bancaria (FinCatCore.planoMigracaoV4). Antes de mexer, guarda copia de sc_cr,
// sc_cp, sc_df, sc_contas_fin e sc_mov_fin em sc_fin_backup_v3 (sem os anexos, que a
// migracao nao toca). Sem espaco para a copia ou para salvar: a copia sai, nada muda,
// marca sc_fin_v4_falhou e o aviso no topo do Financeiro oferece baixar a copia e seguir
// (como na Fase 0). Sem espaco mesmo sem a copia: marca sc_fin_v4_erro.
const CHAVE_FIN_VERSAO = 'sc_fin_versao';
const CHAVE_FIN_BACKUP_V3 = 'sc_fin_backup_v3';
const CHAVE_FIN_V4_FALHOU = 'sc_fin_v4_falhou';
const CHAVE_FIN_V4_ERRO = 'sc_fin_v4_erro';
function _finCopiaV4(semAnexos) {
    const l = lista => (lista || []).map(r => (semAnexos ? _finSemAnexos(r) : r));
    return { em: new Date().toISOString(), sc_cr: l(db.contas_receber), sc_cp: l(db.contas_pagar), sc_df: l(db.despesas_fixas),
        sc_contas_fin: l(db.contas_fin), sc_mov_fin: l(db.movimentos_fin) };
}
function _removerSemFalhar(chave) { try { localStorage.removeItem(chave); } catch (e) { /* sem storage */ } }
function _migrarFinanceiroV4({ semCopia = false } = {}) {
    if (Number(localStorage.getItem(CHAVE_FIN_VERSAO)) >= 4) return true;
    const plano = FinCatCore.planoMigracaoV4({
        contas_receber: db.contas_receber, contas_pagar: db.contas_pagar, despesas_fixas: db.despesas_fixas,
        pedidos: db.pedidos, clientes: db.clientes, fornecedores: db.fornecedores, agoraISO: new Date().toISOString()
    });
    const contas = getContasFin().map(c => ({ c, set: _finCamposContaPadrao(c, db.movimentos_fin) })).filter(x => Object.keys(x.set).length);
    const temDados = plano.cr.length || plano.cp.length || plano.df.length || plano.pedidos.length || contas.length;
    const antes = JSON.stringify({ contas_receber: db.contas_receber, contas_pagar: db.contas_pagar, despesas_fixas: db.despesas_fixas,
        contas_fin: db.contas_fin, pedidos: db.pedidos, fin_categorias: db.fin_categorias });
    // semCopia: quem chama ja baixou a copia em arquivo (sem espaco no navegador).
    if (temDados && !semCopia && localStorage.getItem(CHAVE_FIN_BACKUP_V3) == null) {
        try { localStorage.setItem(CHAVE_FIN_BACKUP_V3, JSON.stringify(_finCopiaV4(true))); }
        catch (e) {
            console.warn('Migração do Financeiro (v4) adiada: não foi possível guardar a cópia de segurança.', e);
            _removerSemFalhar(CHAVE_FIN_BACKUP_V3);
            _gravarSemFalhar(CHAVE_FIN_V4_FALHOU, '1');
            return false;
        }
    }
    // Aplica cada `set` no registro do mesmo id, na ordem (ids repetidos: um set por registro).
    const aplicar = (lista, itens) => {
        const fila = new Map();
        itens.forEach(it => { const k = String(it.id); if (!fila.has(k)) fila.set(k, []); fila.get(k).push(it.set); });
        (lista || []).forEach(r => {
            const f = r && fila.get(String(r.id));
            if (f && f.length) Object.assign(r, f.shift());
        });
    };
    aplicar(db.contas_receber, plano.cr);
    aplicar(db.contas_pagar, plano.cp);
    aplicar(db.despesas_fixas, plano.df);
    aplicar(db.pedidos, plano.pedidos);
    contas.forEach(x => Object.assign(x.c, x.set));
    if (!db.fin_categorias) db.fin_categorias = FinCatCore.categoriasPadrao();
    if (plano.avisos.length) console.info('Migração do Financeiro (v4):', plano.avisos.join(' '));
    try {
        _syncDBBruto([[CHAVE_FIN_VERSAO, '4']]);
    } catch (e) {
        console.warn('Migração do Financeiro (v4) não pôde ser salva.', e);
        const orig = JSON.parse(antes);
        Object.assign(db, orig);
        // A copia nao fica ocupando espaco: sai antes de devolver os dados.
        _removerSemFalhar(CHAVE_FIN_BACKUP_V3);
        [['sc_cr', db.contas_receber], ['sc_cp', db.contas_pagar], ['sc_df', db.despesas_fixas], ['sc_contas_fin', db.contas_fin], ['sc_ped', db.pedidos]]
            .forEach(([k, v]) => _gravarSemFalhar(k, JSON.stringify(v)));
        if (semCopia) _gravarSemFalhar(CHAVE_FIN_V4_ERRO, String(Date.now()));
        else _gravarSemFalhar(CHAVE_FIN_V4_FALHOU, '1');
        return false;
    }
    _removerSemFalhar(CHAVE_FIN_V4_FALHOU);
    _removerSemFalhar(CHAVE_FIN_V4_ERRO);
    return true;
}

// Migracao unica das comissoes (sc_comissao_v2): a comissao passa a ser registro do pedido.
// Conta a pagar de comissao EM ABERTO sai do Financeiro (guardada em fin_excluidos) e o pedido fica
// pendente/registrada; conta PAGA continua como esta (o pedido fica pago). Roda depois da Fase 0
// (que ainda cria contas de comissao). Sem espaco para salvar: volta ao que era e tenta na proxima.
const CHAVE_COMISSAO_V2 = 'sc_comissao_v2';
function _migrarComissoesV2() {
    if (localStorage.getItem(CHAVE_COMISSAO_V2) === '1') return true;
    if (localStorage.getItem(CHAVE_FIN_MIGRACAO) !== '1') return false;
    const plano = FinanceiroCore.planoMigracaoComissao({ pedidos: db.pedidos, contas_pagar: db.contas_pagar, movimentos: db.movimentos_fin });
    if (plano.removerCP.length || plano.pedidos.length) {
        const antes = JSON.stringify({ contas_pagar: db.contas_pagar, pedidos: db.pedidos, fin_excluidos: db.fin_excluidos || [] });
        const sair = new Set(plano.removerCP.map(String));
        const removidas = db.contas_pagar.filter(cp => sair.has(String(cp.id)));
        const em = new Date().toISOString();
        if (!Array.isArray(db.fin_excluidos)) db.fin_excluidos = [];
        removidas.forEach(cp => db.fin_excluidos.push({ tipo: 'cp', em, por: null, porNome: 'Sistema', motivo: FinanceiroCore.MOTIVO_COMISSAO_V2, lancamento: JSON.parse(JSON.stringify(_finSemAnexos(cp))) }));
        db.contas_pagar = db.contas_pagar.filter(cp => !sair.has(String(cp.id)));
        plano.pedidos.forEach(it => {
            const ped = db.pedidos.find(p => p.id == it.id);
            if (!ped) return;
            Object.assign(ped, it.set);
            Object.keys(FinanceiroCore.CAMPOS_COMISSAO_REG).forEach(papel => {
                const r = FinanceiroCore.CAMPOS_COMISSAO_REG[papel];
                if (it.set[r.status] === undefined) return;
                if (!Array.isArray(ped[r.hist])) ped[r.hist] = [];
                ped[r.hist].push({ acao: 'migrada', detalhe: `Comissão passou a ser registro do pedido (${it.set[r.status]})`, em, por: null, porNome: 'Sistema' });
            });
        });
        try { _syncDBBruto([[CHAVE_COMISSAO_V2, '1']]); }
        catch (e) {
            console.warn('Migração das comissões não pôde ser salva.', e);
            const orig = JSON.parse(antes);
            db.contas_pagar = orig.contas_pagar; db.pedidos = orig.pedidos; db.fin_excluidos = orig.fin_excluidos;
            return false;
        }
        return true;
    }
    return _gravarSemFalhar(CHAVE_COMISSAO_V2, '1');
}

// Comissao 'em_cp' (conta antiga em aberto): ao abrir o app, paga se a conta foi paga e volta a pendente se a conta saiu.
function _sincronizarComissoesEmCP() {
    if (localStorage.getItem(CHAVE_COMISSAO_V2) !== '1') return;
    const campos = Object.values(FinanceiroCore.CAMPOS_COMISSAO_REG);
    let mudou = false;
    (db.pedidos || []).forEach(p => {
        const tem = campos.some(r => p[r.status] === 'em_cp');
        if (tem && sincronizarComissoesPedido(p).length) mudou = true;
    });
    if (mudou) _gravarChaves(['sc_ped'], { silencioso: true });
}

// Sem espaco para a copia da migracao v4: baixa a copia em arquivo (as mesmas chaves,
// com os anexos) e migra sem a copia no navegador.
function baixarCopiaEMigrarFinanceiroV4() {
    _baixarJSON(_finCopiaV4(false), `sctech_copia_financeiro_v3_${hojeLocal()}.json`);
    let ok = false;
    try { ok = _migrarFinanceiroV4({ semCopia: true }) !== false; }
    catch (e) { console.error('Migração do Financeiro (v4) falhou:', e); _gravarSemFalhar(CHAVE_FIN_V4_ERRO, String(Date.now())); }
    _avisoRecarregar(ok ? 'Cópia baixada. Os dados do Financeiro foram atualizados.'
        : 'Cópia baixada, mas não deu para atualizar os dados: o navegador está sem espaço. Libere espaço e abra de novo.');
    setTimeout(() => window.location.reload(), 1500);
}

const PLANOS_PAGAMENTO = {
    'avista': [{ descricao: 'Pagamento à vista', pct: 100, dias: 0 }],
    '50_50':  [{ descricao: 'Entrada (50%)', pct: 50, dias: 0 }, { descricao: 'Saldo na instalação (50%)', pct: 50, dias: -1 }],
    '30_70':  [{ descricao: 'Entrada (30%)', pct: 30, dias: 0 }, { descricao: 'Saldo na instalação (70%)', pct: 70, dias: -1 }],
    '40_60':  [{ descricao: 'Entrada (40%)', pct: 40, dias: 0 }, { descricao: 'Saldo na instalação (60%)', pct: 60, dias: -1 }],
};

// Pedido com forma de pagamento (so um nome, definida pela empresa): um unico
// lancamento com o valor todo, vencendo na aprovacao. Pedido antigo, gravado
// com o codigo de um plano, continua dividido como era.
function _planoPagamento(ped) {
    if (ped.forma_pagamento) return [{ descricao: `Pagamento (${ped.forma_pagamento})`, pct: 100, dias: 0 }];
    return PLANOS_PAGAMENTO[ped.tipo_pagamento || '50_50'] || PLANOS_PAGAMENTO['50_50'];
}

function _migrarFinanceiroPedidos() {
    const pendentes = db.pedidos.filter(p =>
        !p.financeiro_gerado &&
        normalizarStatus(p.status) !== 'Orçamento' &&
        (p.valor || 0) > 0
    );
    if (!pendentes.length) return;
    const usadosCR = new Set(db.contas_receber.map(c => c.id));
    let nextId = Date.now();
    const novoIdCR = () => { while (usadosCR.has(nextId)) nextId++; usadosCR.add(nextId); return nextId; };
    pendentes.forEach(ped => {
        const inicio = db.contas_receber.length;
        if (normalizarStatus(ped.status) === 'Instalado' && (ped.valor_recebido || 0) >= (ped.valor || 0)) {
            const dataPgto = dataLocal(ped.data_instalado) || hojeLocal();
            db.contas_receber.push({
                id: novoIdCR(),
                pedido_id: ped.id,
                cliente_nome: ped.clienteNome || '',
                descricao: `Pagamento — Pedido #${formatPedidoId(ped.id)}`,
                valor: ped.valor,
                data_vencimento: dataPgto,
                data_pagamento: dataPgto,
                status: 'Pago'
            });
        } else {
            const plano = _planoPagamento(ped);
            const hoje = hojeLocal();
            plano.forEach((parcela, i) => {
                const valor = Math.round(ped.valor * parcela.pct / 100 * 100) / 100;
                const vencimento = parcela.dias === -1
                    ? (ped.data_entrega || FinanceiroCore.somarDias(hoje, 30))
                    : FinanceiroCore.somarDias(hoje, parcela.dias);
                db.contas_receber.push({
                    id: novoIdCR(),
                    pedido_id: ped.id,
                    cliente_nome: ped.clienteNome || '',
                    descricao: `${parcela.descricao} — Pedido #${formatPedidoId(ped.id)}`,
                    valor,
                    data_vencimento: vencimento,
                    data_pagamento: null,
                    status: 'Pendente'
                });
            });
        }
        // Competencia (como na migracao v4): a data de aprovacao do pedido; sem ela, o menor vencimento.
        const novas = db.contas_receber.slice(inicio);
        if (!ped.data_aprovacao && novas.length) ped.data_aprovacao = novas.map(c => c.data_vencimento).filter(Boolean).sort()[0] || hojeLocal();
        novas.forEach(cr => finCompletarLancamento('cr', cr, { origem: 'pedido', dataAprovacao: ped.data_aprovacao }, `Gerado pelo pedido #${formatPedidoId(ped.id)}`));
        ped.financeiro_gerado = true;
    });
    syncDB();
}

// Migracao unica dos dados antigos para a Fase 0 (ver FinanceiroCore.planoMigracaoFase0).
// Antes de mexer em qualquer coisa guarda uma copia em sc_fin_backup_fase0; os
// pedidos que precisam de conferencia manual ficam em sc_fin_revisar. Sem espaco
// para a copia, nao migra: marca sc_fin_backup_falhou e o aviso no topo do Financeiro oferece
// baixar a copia e seguir. Erro ao salvar o resultado desfaz tudo, deixa a marca
// sem gravar (tenta de novo na proxima abertura) e marca sc_fin_migracao_erro.
const CHAVE_FIN_MIGRACAO = 'sc_fin_migracao';
const CHAVE_FIN_BACKUP = 'sc_fin_backup_fase0';
const CHAVE_FIN_BACKUP_FALHOU = 'sc_fin_backup_falhou';
const CHAVE_FIN_MIGRACAO_ERRO = 'sc_fin_migracao_erro';

function _gravarSemFalhar(chave, valor) {
    try { localStorage.setItem(chave, valor); return true; } catch (e) { return false; }
}

// Devolve true quando a migracao esta feita (agora ou antes).
function _migrarFinanceiroFase0({ semCopia = false } = {}) {
    if (localStorage.getItem(CHAVE_FIN_MIGRACAO) === '1') return true;
    // Acertos antigos do pedido antes de planejar: o arquiteto que estava no campo
    // de vendedor vai para arq_* (senao a comissao dele nasceria como de vendedor).
    migrarArquitetoDosPedidos();
    migrarStatusAguardandoFinanceiro();
    const plano = FinanceiroCore.planoMigracaoFase0({
        pedidos: db.pedidos, contas_receber: db.contas_receber, contas_pagar: db.contas_pagar,
        vendedores: db.vendedores, hoje: hojeLocal(),
        rotuloPedido: p => '#' + formatPedidoId(p.id)
    });
    const vazio = Object.values(plano).every(l => !l.length);
    if (!vazio) {
        const antes = JSON.stringify({ contas_receber: db.contas_receber, contas_pagar: db.contas_pagar, pedidos: db.pedidos });
        // Uma copia so: numa nova tentativa ela ja guarda o estado de antes de tudo.
        // semCopia: quem chama ja baixou a copia em arquivo (sem espaco no navegador).
        if (!semCopia && localStorage.getItem(CHAVE_FIN_BACKUP) == null) {
            try {
                localStorage.setItem(CHAVE_FIN_BACKUP, '{"criado_em":' + Date.now() + ',' + antes.slice(1));
            } catch (e) {
                console.warn('Migração do Financeiro adiada: não foi possível guardar a cópia de segurança.', e);
                _gravarSemFalhar(CHAVE_FIN_BACKUP_FALHOU, '1');
                return false;   // sem copia, nao migra; o aviso no topo do Financeiro oferece baixar a copia
            }
        }
        const agora = Date.now();
        const tocados = new Set();
        // Valor que estava digitado no pedido, antes de sincronizar com o Financeiro.
        const revisar = plano.revisar.map(r => {
            const ped = db.pedidos.find(p => p.id == r.pedido_id) || {};
            return { ...r, rotulo: '#' + formatPedidoId(r.pedido_id), cliente: ped.clienteNome || '',
                     valor_digitado: Number(ped.valor_recebido) || 0,
                     valor_financeiro: FinanceiroCore.totalRecebido(db.contas_receber, r.pedido_id) };
        });
        plano.baixarCR.forEach(b => {
            const cr = db.contas_receber.find(x => x.id == b.id);
            if (!cr || !finAberta(cr)) return;
            Object.assign(cr, { status: 'Pago', data_pagamento: b.data_pagamento, baixado_por: b.baixado_por, baixado_em: agora });
            if (cr.pedido_id) tocados.add(cr.pedido_id);
        });
        const remover = new Set(plano.removerCR.map(String));
        db.contas_receber = db.contas_receber.filter(c => !remover.has(String(c.id)));
        plano.marcarCRPedidoExcluido.forEach(id => {
            const cr = db.contas_receber.find(x => x.id == id);
            if (cr) cr.pedido_excluido = true;
        });
        const usados = new Set((db.contas_pagar || []).map(c => c.id));
        let proximoId = Date.now();
        plano.criarCP.forEach(cp => {
            while (usados.has(proximoId)) proximoId++;
            usados.add(proximoId);
            db.contas_pagar.push({ id: proximoId, ...cp, ...(cp.status === 'Pago' ? { baixado_em: agora } : {}) });
        });
        // Pedido sem parcelas: o valor digitado fica no pedido (so o aviso).
        plano.revisar.forEach(r => { if (!r.sem_lancamento) tocados.add(r.pedido_id); });
        tocados.forEach(sincronizarRecebidoPedido);
        try {
            _syncDBBruto();
            if (revisar.length) localStorage.setItem('sc_fin_revisar', JSON.stringify(revisar));
            localStorage.setItem(CHAVE_FIN_MIGRACAO, '1');
        } catch (e) {
            // Volta ao que era (na memoria e, no que couber, no navegador) e avisa.
            console.warn('Migração do Financeiro não pôde ser salva.', e);
            const orig = JSON.parse(antes);
            db.contas_receber = orig.contas_receber; db.contas_pagar = orig.contas_pagar; db.pedidos = orig.pedidos;
            _gravarSemFalhar('sc_ped', JSON.stringify(db.pedidos));
            _gravarSemFalhar('sc_cr', JSON.stringify(db.contas_receber));
            _gravarSemFalhar('sc_cp', JSON.stringify(db.contas_pagar));
            localStorage.removeItem('sc_fin_revisar');
            _gravarSemFalhar(CHAVE_FIN_MIGRACAO_ERRO, String(Date.now()));
            return false;
        }
    } else if (!_gravarSemFalhar(CHAVE_FIN_MIGRACAO, '1')) {
        _gravarSemFalhar(CHAVE_FIN_MIGRACAO_ERRO, String(Date.now()));
        return false;
    }
    localStorage.removeItem(CHAVE_FIN_BACKUP_FALHOU);
    localStorage.removeItem(CHAVE_FIN_MIGRACAO_ERRO);
    return true;
}

// Aviso no topo do Financeiro (em todas as abas) sobre a copia de seguranca da migracao: sem espaco para
// guarda-la (baixar e seguir), erro ao salvar, ou copia guardada (baixar/descartar).
function renderAvisoCopiaFinanceiro() {
    const el = document.getElementById('fin-backup');
    if (!el) return;
    const falhou = localStorage.getItem(CHAVE_FIN_BACKUP_FALHOU) === '1';
    // Migracao v4 sem espaco (so quando a Fase 0 ja esta feita: as duas nunca pedem ao mesmo tempo).
    const falhouV4 = !falhou && localStorage.getItem(CHAVE_FIN_V4_FALHOU) === '1' && Number(localStorage.getItem(CHAVE_FIN_VERSAO)) < 4;
    const erro = localStorage.getItem(CHAVE_FIN_MIGRACAO_ERRO) != null || localStorage.getItem(CHAVE_FIN_V4_ERRO) != null;
    const temCopia = localStorage.getItem(CHAVE_FIN_BACKUP) != null || localStorage.getItem(CHAVE_FIN_BACKUP_V3) != null;
    const blocos = [];
    if (falhou || falhouV4) blocos.push(`<div class="fin-alerta fin-alerta-warning" style="align-items:flex-start">
        <span style="font-size:18px;flex-shrink:0">⚠️</span>
        <div style="flex:1">
            <strong>Não foi possível guardar a cópia de segurança no navegador. Baixe a cópia para continuar.</strong>
            Os dados do Financeiro ainda não foram atualizados. A cópia fica salva no seu computador.
            <div style="margin-top:8px"><button class="btn btn-success btn-sm" onclick="${falhou ? 'baixarCopiaEMigrarFinanceiro()' : 'baixarCopiaEMigrarFinanceiroV4()'}">Baixar cópia e corrigir dados</button></div>
        </div>
    </div>`);
    if (erro) blocos.push(`<div class="fin-alerta fin-alerta-warning" style="align-items:flex-start">
        <span style="font-size:18px;flex-shrink:0">⚠️</span>
        <div style="flex:1">
            <strong>Não foi possível salvar a atualização do Financeiro.</strong> O espaço do navegador está cheio e nada foi alterado.
            Libere espaço${temCopia ? ' (por exemplo, baixe e descarte a cópia de segurança abaixo)' : ''} e abra o Financeiro de novo.
        </div>
    </div>`);
    if (temCopia) blocos.push(`<div class="fin-alerta fin-alerta-info" style="align-items:flex-start">
        <span style="font-size:18px;flex-shrink:0">💾</span>
        <div style="flex:1">
            Há uma cópia de segurança dos dados de antes da atualização do Financeiro guardada neste navegador.
            <strong>Esta cópia é parcial: serve para consulta, não para Importar.</strong>
            <div style="margin-top:8px;display:flex;gap:8px;flex-wrap:wrap">
                <button class="btn btn-outline btn-sm" onclick="baixarCopiaFinanceiro()">Baixar cópia</button>
                <button class="btn btn-outline btn-sm btn-danger" onclick="descartarCopiaFinanceiro()">Descartar cópia</button>
            </div>
        </div>
    </div>`);
    el.innerHTML = blocos.join('');
}

// Sem espaco para a copia no navegador: baixa a copia em arquivo (no formato do
// backup, importavel) e migra sem a copia interna.
function baixarCopiaEMigrarFinanceiro() {
    _baixarJSON(_dadosExportacao(false), `sctech_backup_antes_fase0_${hojeLocal()}.json`);
    try { _migrarFinanceiroFase0({ semCopia: true }); }
    catch (e) { console.error('Migração do Financeiro falhou:', e); _gravarSemFalhar(CHAVE_FIN_MIGRACAO_ERRO, String(Date.now())); }
    // Da tempo de o download comecar; quem quiser pode recarregar antes.
    _avisoRecarregar('Cópia baixada. Os dados do Financeiro foram atualizados.');
    setTimeout(() => window.location.reload(), 1500);
}

function _avisoRecarregar(msg) {
    let el = document.getElementById('sc-aviso-recarregar');
    if (!el) { el = document.createElement('div'); el.id = 'sc-aviso-recarregar'; document.body.appendChild(el); }
    el.style.cssText = 'position:fixed;left:50%;bottom:24px;transform:translateX(-50%);z-index:10000;background:var(--white);border:1px solid var(--border-strong);border-radius:8px;padding:12px 16px;box-shadow:0 4px 16px rgba(0,0,0,.25);display:flex;gap:12px;align-items:center;max-width:90vw';
    el.innerHTML = '<span></span><button class="btn btn-success btn-sm" type="button" onclick="window.location.reload()">Recarregar agora</button>';
    el.firstChild.textContent = msg + ' A página recarrega em instantes.';
}

// Copias guardadas no navegador: a da Fase 0 e a da migracao v4 (cada uma no seu arquivo).
function baixarCopiaFinanceiro() {
    let baixou = false;
    [[CHAVE_FIN_BACKUP, 'sctech_copia_financeiro_'], [CHAVE_FIN_BACKUP_V3, 'sctech_copia_financeiro_v3_']].forEach(([chave, nome]) => {
        const copia = localStorage.getItem(chave);
        if (copia == null) return;
        let dados;
        try { dados = JSON.parse(copia); } catch (e) { dados = copia; }
        _baixarJSON(dados, `${nome}${hojeLocal()}.json`);
        baixou = true;
    });
    if (baixou) toast('Esta cópia é parcial: serve para consulta, não para Importar.', 'warning', 6000);
}

async function descartarCopiaFinanceiro() {
    if (!await showConfirm('Descartar a cópia de segurança de antes da atualização do Financeiro? Baixe a cópia antes se quiser guardá-la.', '🗑️', 'Descartar', 'Cancelar')) return;
    localStorage.removeItem(CHAVE_FIN_BACKUP);
    localStorage.removeItem(CHAVE_FIN_BACKUP_V3);
    renderAvisoCopiaFinanceiro();
}

// Aviso no topo do Financeiro (em todas as abas): pedidos que a migracao nao conseguiu acertar sozinha.
function renderAvisoRevisaoFinanceiro() {
    const el = document.getElementById('fin-revisar');
    if (!el) return;
    let lista = [];
    try { lista = JSON.parse(localStorage.getItem('sc_fin_revisar') || '[]') || []; } catch (e) { lista = []; }
    if (!Array.isArray(lista) || !lista.length) { el.innerHTML = ''; return; }
    const fmt = v => (Number(v) || 0).toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
    el.innerHTML = `<div class="fin-alerta fin-alerta-warning" style="align-items:flex-start">
        <span style="font-size:18px;flex-shrink:0">🔎</span>
        <div style="flex:1">
            <strong>Confira estes pedidos.</strong> Na atualização do Financeiro eles não puderam ser acertados sozinhos. Agora vale o que está no Financeiro; acerte as parcelas se precisar.
            <ul style="margin:6px 0 8px 18px;padding:0">${lista.map(r => `<li>Pedido ${escapeHtml(String(r.rotulo || '#' + r.pedido_id))}${r.cliente ? ' — ' + escapeHtml(String(r.cliente)) : ''}: ${escapeHtml(String(r.motivo || ''))}${r.valor_digitado != null ? ` (no pedido R$ ${fmt(r.valor_digitado)}, no Financeiro R$ ${fmt(r.valor_financeiro)})` : ''}${r.sem_lancamento ? ' — ao aprovar, o Financeiro não desconta esse valor: registre o recebimento no Financeiro.' : ''}</li>`).join('')}</ul>
            <button class="btn btn-outline btn-sm" id="fin-revisar-ok" onclick="marcarRevisaoFinanceiroFeita()">Marcar como revisado</button>
        </div>
    </div>`;
}

function marcarRevisaoFinanceiroFeita() {
    localStorage.removeItem('sc_fin_revisar');
    renderAvisoRevisaoFinanceiro();
}

// Guarda o custo do material no momento da aprovacao: mudar o preco do tecido
// depois nao altera o resultado de um pedido ja aprovado. Refeito a cada reaprovacao.
// Pedido de formato antigo (tecido no ambiente ou no proprio pedido) passa por
// normalizarAmbientes so para o calculo; o pedido guardado nao muda.
function registrarCustoPedido(ped) {
    ped.custo_snapshot = {
        ...FinanceiroCore.custoSnapshotPedido({ ...ped, ambientes: normalizarAmbientes(ped) }, { catalogo: db.catalogo, materiais: db.materiais, kits: db.kits }),
        data: hojeLocal()
    };
}

function _copiaMeioPrevisto(mp) {
    return mp && mp.meio_id != null ? { meio_id: mp.meio_id, vezes: mp.vezes || 1, antecipar: !!mp.antecipar } : null;
}

// Devolve { pago, valor } quando o cliente ja pagou mais que o valor do pedido
// (reaprovacao com valor menor); nesse caso nao ha o que gerar.
function gerarFinanceiroPedido(ped) {
    if (ped.financeiro_gerado) return null;
    const num = formatPedidoId(ped.id);
    const hoje = hojeLocal();
    const jaPago = FinanceiroCore.totalRecebido(db.contas_receber, ped.id);
    const pagoAMais = Math.round(jaPago * 100) > Math.round((Number(ped.valor) || 0) * 100)
        ? { pago: jaPago, valor: Number(ped.valor) || 0 } : null;
    let parcelas;
    if (ped.forma_pagamento || !ped.tipo_pagamento) {
        const pct = Number.isFinite(ped.entrada_pct) ? ped.entrada_pct : entradaDaFormaPagamento(ped.forma_pagamento);
        // Entrada paga em parte: o % da descricao e o que ainda falta pagar, nao o da forma.
        const pctEntradaRestante = p => (jaPago > 0 && Number(ped.valor) > 0)
            ? Math.round(p.valor / Number(ped.valor) * 1000) / 10 : pct;
        parcelas = FinanceiroCore.planejarParcelas({
            valor: ped.valor || 0, entradaPct: pct,
            jaPago, dataAprovacao: hoje, dataEntrega: ped.data_entrega
        }).map(p => ({
            ...p,
            descricao: p.tipo === 'entrada' ? `Entrada (${String(pctEntradaRestante(p)).replace('.', ',')}%) — Pedido #${num}`
                : p.tipo === 'saldo' ? `Saldo na instalação — Pedido #${num}`
                : `Pagamento — Pedido #${num}`
        }));
    } else {
        // Pedido antigo, gravado com o codigo de um plano: mesma divisao (entrada
        // do plano), descontando o que ja foi pago, com as descricoes de sempre.
        const plano = _planoPagamento(ped);
        parcelas = FinanceiroCore.planejarParcelas({
            valor: ped.valor || 0, entradaPct: plano[0].pct,
            jaPago, dataAprovacao: hoje, dataEntrega: ped.data_entrega
        }).map(p => ({ ...p, descricao: `${(p.tipo === 'saldo' ? plano[plano.length - 1] : plano[0]).descricao} — Pedido #${num}` }));
    }
    // Data de aprovacao: gravada na 1a vez e nunca mudada (pedido que voltou para
    // Orcamento e foi aprovado de novo continua com a receita no mesmo mes).
    if (!ped.data_aprovacao) ped.data_aprovacao = hoje;
    const usados = new Set((db.contas_receber || []).map(c => c.id));
    let proximoId = Date.now();
    parcelas.forEach(p => {
        while (usados.has(proximoId)) proximoId++;
        usados.add(proximoId);
        db.contas_receber.push(finCompletarLancamento('cr', {
            id: proximoId,
            pedido_id: ped.id,
            cliente_nome: ped.clienteNome || '',
            descricao: p.descricao,
            valor: p.valor,
            data_vencimento: p.data_vencimento,
            data_pagamento: null,
            status: 'Pendente',
            parcela_tipo: p.tipo,
            meio_previsto: _copiaMeioPrevisto(p.tipo === 'saldo' ? ped.meio_saldo : ped.meio_entrada)
        }, { origem: 'pedido', dataAprovacao: ped.data_aprovacao }, `Gerado pelo pedido #${num}`));
    });
    ped.financeiro_gerado = true;
    return pagoAMais;
}

// Aviso da reaprovacao com valor pago maior que o novo valor do pedido.
async function avisarPagoAMais(r) {
    if (!r) return;
    const brl = v => 'R$ ' + (Number(v) || 0).toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
    await showAlert(`O cliente já pagou ${brl(r.pago)}, mais que o novo valor do pedido (${brl(r.valor)}). Devolva ${brl(r.pago - r.valor)} ou ajuste o pedido.`, '⚠️');
}

// Vencimento para a tela; conta sem data mostra "sem vencimento" (nunca conta como atrasada).
function _fmtVenc(d) {
    return d ? new Date(d + 'T12:00:00').toLocaleDateString('pt-BR') : 'sem vencimento';
}

function atualizarStatusVencimentos() {
    const hoje = hojeLocal();
    let changed = false;
    [...db.contas_receber, ...db.contas_pagar].forEach(item => {
        if (item.status === 'Pendente' && item.data_vencimento && item.data_vencimento < hoje) {
            item.status = 'Atrasado';
            changed = true;
        }
    });
    if (changed) syncDB();
}

// Valor recebido do pedido = soma das parcelas pagas (fonte unica).
function sincronizarRecebidoPedido(pedidoId) {
    const ped = db.pedidos.find(p => p.id == pedidoId);
    if (!ped) return;
    if (!db.contas_receber.some(c => c.pedido_id == pedidoId)) {
        // Sem parcelas: o pedido que ja teve financeiro nao recebeu nada; o que
        // nunca teve mantem o valor antigo (vai para a revisao da migracao).
        if (ped.financeiro_gerado) ped.valor_recebido = 0;
        return;
    }
    ped.valor_recebido = FinanceiroCore.totalRecebido(db.contas_receber, pedidoId);
}

// Meios oferecidos na baixa. Sem meios configurados, uma lista simples sem
// conta (a baixa vale, mas nao gera movimento).
function _meiosDaBaixa(permiteCartao) {
    const cartao = t => t === 'cartao_debito' || t === 'cartao_credito';
    const meios = getMeiosPag();
    const lista = meios.length
        ? meios.map(m => ({ chave: String(m.id), id: m.id, nome: m.nome || '', tipo: m.tipo, conta_id: m.conta_id == null ? null : m.conta_id }))
        : ['Dinheiro', 'PIX', 'Cartão', 'Transferência'].filter(n => permiteCartao || n !== 'Cartão').map(n => ({ chave: 'nome:' + n, id: null, nome: n, tipo: 'outro', conta_id: null }));
    return permiteCartao ? lista : lista.filter(m => !cartao(m.tipo));
}

function _contaFinPorId(id) {
    return id == null || id === '' ? null : (getContasFin().find(c => CaixaCore.mesmoId(c.id, id)) || null);
}

// Valor em dinheiro digitado (baixa, saldo inicial, transferencia): alem do
// _numeroBR, "1.000" e "1.000.000" (so ponto de milhar) valem mil e um
// milhao, e nao 1. Aceita negativo ("-1.500", "-1.234,56") e o sinal "−" (U+2212).
// Vazio devolve o padrao. Nao serve para taxa nem dias.
function _valorDigitadoBaixa(t, padrao) {
    const s = String(t == null ? '' : t).trim().replace(/^\u2212/, '-');
    return _numeroBR(/^-?\d{1,3}(\.\d{3})+$/.test(s) ? s.replace(/\./g, '') : s, padrao === undefined ? NaN : padrao);
}

const AVISO_CONTA_BAIXA = 'Esta conta ainda não está configurada / data anterior ao saldo inicial — não entra no saldo';

// Modal de baixa: uma linha por parcela (marcar, valor, meio, conta e, no
// cartao de credito, vezes e antecipar). Data unica. Devolve
// { data, linhas: [{ id, valor, meio_id, meio_nome, conta_id, cartao }] } ou null.
function abrirModalBaixa({ titulo, itens, comData = true, permiteParcial = false, permiteCartao = true, formaPadrao = '', permiteNenhum = false }) {
    return new Promise(resolve => {
        const hoje = hojeLocal();
        const meios = _meiosDaBaixa(permiteCartao);
        const contas = getContasFin().filter(c => c.ativo !== false);
        const semContas = !getContasFin().length;
        const brl = v => 'R$ ' + (Number(v) || 0).toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
        const meioInicial = it => {
            const mp = it.meio_previsto;
            const porId = mp && meios.find(m => m.id != null && CaixaCore.mesmoId(m.id, mp.meio_id));
            if (porId) return porId;
            const nome = String(it.forma_padrao || formaPadrao || '').trim().toLowerCase();
            return (nome && meios.find(m => m.nome.trim().toLowerCase() === nome)) || null;
        };
        const contaDe = m => (m && m.conta_id != null && _contaFinPorId(m.conta_id)) ? String(m.conta_id) : '';
        // Conta de saida/entrada: a do meio; sem ela, a conta prevista do lancamento (se ainda valer).
        const contaInicial = (it, m) => contaDe(m) || ((it && it.conta_prevista != null && _contaFinPorId(it.conta_prevista)) ? String(it.conta_prevista) : '');
        const ehCartao = m => !!m && (m.tipo === 'cartao_debito' || m.tipo === 'cartao_credito');
        // Cartao so cai em conta de maquininha.
        const contasDoMeio = m => ehCartao(m) ? contas.filter(c => c.tipo === 'maquininha') : contas;
        const opcoesConta = (m, escolhida) => '<option value="">— sem conta —</option>' + contasDoMeio(m).map(c => `<option value="${escapeHtml(String(c.id))}" ${String(c.id) === escolhida ? 'selected' : ''}>${escapeHtml(c.nome || '')}</option>`).join('');
        const sel = 'width:100%;padding:6px;border:1px solid var(--border-strong);border-radius:4px;font-size:13px;box-sizing:border-box';
        const o = document.createElement('div');
        o.id = 'baixa-modal';
        o.className = 'sc-modal-overlay';
        o.style.display = 'flex';
        o.innerHTML = `<div class="sc-modal-box" style="text-align:left;max-width:560px;width:calc(100% - 32px)">
            <h3 style="margin:0 0 12px;font-size:16px">${escapeHtml(titulo || 'Registrar recebimento')}</h3>
            ${comData ? `<label style="display:block;font-size:12px;margin-bottom:4px">Data</label><input type="date" id="baixa-data" value="${hoje}" max="${hoje}" style="${sel};margin-bottom:10px"><div id="baixa-erro-data" style="display:none;color:var(--danger-text);font-size:12px;margin:-6px 0 10px"></div>` : ''}
            ${semContas ? `<div id="baixa-aviso-geral" style="background:var(--warn-bg);color:var(--warn-text);font-size:12px;padding:8px;border-radius:4px;margin-bottom:10px">Contas ainda não configuradas (Empresa › Preferências) — esta baixa não entra no saldo.</div>` : ''}
            <div style="max-height:50vh;overflow:auto;margin-bottom:12px">${itens.map((it, idx) => {
                const m = meioInicial(it) || {};
                const mp = it.meio_previsto || {};
                const vezes = Math.min(12, Math.max(1, Math.floor(Number(mp.vezes) || 1)));
                return `<div class="baixa-linha" data-idx="${idx}" style="padding:8px 0;border-bottom:1px solid var(--border);font-size:13px">
                    <label style="display:flex;align-items:center;gap:8px;cursor:pointer">
                        <input type="checkbox" class="baixa-check" data-id="${escapeHtml(String(it.id))}" ${it.marcado ? 'checked' : ''}>
                        <span style="flex:1">${escapeHtml(it.descricao || '')}</span>
                        <strong>${brl(it.valor)}</strong>
                    </label>
                    <div class="baixa-detalhe" style="display:flex;flex-wrap:wrap;gap:6px;margin:6px 0 0 24px">
                        <input type="text" inputmode="decimal" class="baixa-valor" title="Valor recebido" value="${(Number(it.valor) || 0).toFixed(2).replace('.', ',')}" ${permiteParcial ? '' : 'readonly'} style="${sel};flex:1 1 90px;${permiteParcial ? '' : 'background:var(--surface-3)'}">
                        <select class="baixa-meio" title="Meio" style="${sel};flex:2 1 130px">${m.chave ? '' : '<option value="" selected>Escolha o meio</option>'}${meios.map(x => `<option value="${escapeHtml(x.chave)}" ${x === m ? 'selected' : ''}>${escapeHtml(x.nome)}</option>`).join('')}</select>
                        <select class="baixa-conta" title="Conta" style="${sel};flex:2 1 130px;${semContas ? 'display:none' : ''}">${opcoesConta(m, contaInicial(it, m))}</select>
                        <div class="baixa-cartao" style="display:none;flex:1 1 100%;gap:10px;align-items:center">
                            <label style="font-size:12px">Vezes <select class="baixa-vezes" style="padding:4px;border:1px solid var(--border-strong);border-radius:4px">${Array.from({ length: 12 }, (_, i) => `<option value="${i + 1}" ${i + 1 === vezes ? 'selected' : ''}>${i + 1}x</option>`).join('')}</select></label>
                            <label style="font-size:12px;cursor:pointer"><input type="checkbox" class="baixa-antecipar" ${mp.antecipar ? 'checked' : ''}> Antecipar</label>
                        </div>
                        <div class="baixa-aviso" style="display:none;flex:1 1 100%;color:var(--warn-text);font-size:12px"></div>
                        <div class="baixa-erro" style="display:none;flex:1 1 100%;color:var(--danger-text);font-size:12px"></div>
                    </div>
                </div>`;
            }).join('')}</div>
            <div id="baixa-erro-nenhum" style="display:none;color:var(--danger-text);font-size:12px;margin:-6px 0 8px">Marque pelo menos um item.</div>
            <div style="display:flex;justify-content:space-between;font-size:14px;margin-bottom:12px"><span>Total marcado</span><strong id="baixa-total">R$ 0,00</strong></div>
            <div class="sc-modal-btns"><button class="btn btn-outline" id="baixa-cancel">Cancelar</button><button class="btn btn-success" id="baixa-ok">Confirmar</button></div>
        </div>`;
        document.body.appendChild(o);
        const linhas = [...o.querySelectorAll('.baixa-linha')];
        let tentou = false;
        const dataAtual = () => o.querySelector('#baixa-data')?.value || hoje;
        // Data vazia ou depois de hoje nao vale (a baixa registra o que ja aconteceu).
        const erroDaData = () => comData ? _erroDataBaixa(o.querySelector('#baixa-data')?.value || '') : '';
        const meioDa = l => meios.find(x => x.chave === l.querySelector('.baixa-meio').value) || null;
        // Valor da linha: numero ou NaN; mensagem de erro ou ''.
        const lerLinha = l => {
            const it = itens[Number(l.dataset.idx)];
            const max = CaixaCore.arredondar(Number(it.valor) || 0);
            const v = CaixaCore.arredondar(_valorDigitadoBaixa(l.querySelector('.baixa-valor').value));
            let erro = '';
            if (!(v > 0)) erro = 'Informe um valor maior que zero.';
            else if (v > max) erro = 'O valor não pode passar de ' + brl(max) + '.';
            return { it, v, erro };
        };
        const atualizarLinha = l => {
            const marcada = l.querySelector('.baixa-check').checked;
            l.querySelector('.baixa-detalhe').style.display = marcada ? 'flex' : 'none';
            const m = meioDa(l);
            l.querySelector('.baixa-cartao').style.display = m && m.tipo === 'cartao_credito' ? 'flex' : 'none';
            const conta = _contaFinPorId(l.querySelector('.baixa-conta').value);
            const aviso = l.querySelector('.baixa-aviso');
            const mostrar = !semContas && !CaixaCore.contaAceitaMovimento(conta, dataAtual());
            aviso.textContent = mostrar ? AVISO_CONTA_BAIXA : '';
            aviso.style.display = mostrar ? 'block' : 'none';
            let { erro } = lerLinha(l);
            if (!erro && !m && tentou) erro = 'Escolha o meio.';
            const e = l.querySelector('.baixa-erro');
            e.textContent = erro;
            e.style.display = marcada && erro ? 'block' : 'none';
        };
        const atualizar = () => {
            const ed = o.querySelector('#baixa-erro-data');
            if (ed) { const m = erroDaData(); ed.textContent = m; ed.style.display = m ? 'block' : 'none'; }
            linhas.forEach(atualizarLinha);
            const t = linhas.filter(l => l.querySelector('.baixa-check').checked)
                .reduce((s, l) => { const { v } = lerLinha(l); return s + (v > 0 ? v : 0); }, 0);
            o.querySelector('#baixa-total').textContent = brl(t);
            // Nada marcado: Confirmar fica desabilitado e a janela avisa (nao fecha sozinha).
            // Exceto com permiteNenhum (confirmar o pagamento do pedido: o cliente pode nao ter pago nada).
            const nenhum = linhas.length > 0 && !permiteNenhum && !linhas.some(l => l.querySelector('.baixa-check').checked);
            o.querySelector('#baixa-erro-nenhum').style.display = nenhum ? 'block' : 'none';
            o.querySelector('#baixa-ok').disabled = nenhum;
        };
        linhas.forEach(l => {
            l.querySelector('.baixa-meio').addEventListener('change', () => {
                const m = meioDa(l);
                l.querySelector('.baixa-conta').innerHTML = opcoesConta(m, contaInicial(itens[Number(l.dataset.idx)], m));
                atualizar();
            });
            l.querySelectorAll('.baixa-check,.baixa-conta').forEach(x => x.addEventListener('change', atualizar));
            l.querySelector('.baixa-valor').addEventListener('input', atualizar);
        });
        o.querySelector('#baixa-data')?.addEventListener('change', atualizar);
        o.querySelector('#baixa-data')?.addEventListener('input', atualizar);
        atualizar();
        const fechar = val => { document.removeEventListener('keydown', esc); o.remove(); resolve(val); };
        const esc = e => { if (e.key === 'Escape') fechar(null); };
        document.addEventListener('keydown', esc);
        o.querySelector('#baixa-cancel').onclick = () => fechar(null);
        o.querySelector('#baixa-ok').onclick = () => {
            tentou = true;
            atualizar();
            if (erroDaData()) return;
            const marcadas = linhas.filter(l => l.querySelector('.baixa-check').checked);
            if (marcadas.some(l => lerLinha(l).erro || !meioDa(l))) return;
            fechar({
                data: dataAtual(),
                linhas: marcadas.map(l => {
                    const { it, v } = lerLinha(l);
                    const m = meioDa(l) || {};
                    const conta = _contaFinPorId(l.querySelector('.baixa-conta').value);
                    let cartao = null;
                    if (m.tipo === 'cartao_debito') cartao = { tipo: 'debito', vezes: 1, antecipar: false };
                    if (m.tipo === 'cartao_credito') cartao = {
                        tipo: 'credito',
                        vezes: Math.min(12, Math.max(1, Number(l.querySelector('.baixa-vezes').value) || 1)),
                        antecipar: l.querySelector('.baixa-antecipar').checked
                    };
                    return { id: it.id, valor: v, meio_id: m.id == null ? null : m.id, meio_nome: m.nome || '', conta_id: conta ? conta.id : null, cartao };
                })
            });
        };
    });
}

function _novosIdsFin(colecao) {
    const usados = new Set((colecao || []).map(x => x.id));
    return () => _novoIdCfgFin(usados);
}

function _erroDataBaixa(data) {
    if (!/^\d{4}-\d{2}-\d{2}$/.test(String(data == null ? '' : data))) return 'Informe a data.';
    if (data > hojeLocal()) return 'A data não pode ser depois de hoje.';
    return '';
}

// Baixa de recebimentos, linha a linha. Valor menor que a parcela divide a
// parcela (a parte paga vira uma conta nova). Gera movimentos so se a conta
// aceita (existe, ativa e data >= saldo inicial). Cartao: uma entrada bruta
// por repasse e uma conta a pagar de taxa ja paga com a sua saida.
// Valida data e valores antes de mexer em qualquer coisa. Devolve { ok, erro }.
function baixarContasReceber(data, linhas) {
    const erroData = _erroDataBaixa(data);
    if (erroData) return { ok: false, erro: erroData };
    for (const linha of (linhas || [])) {
        const cr = db.contas_receber.find(x => CaixaCore.mesmoId(x.id, linha.id));
        if (!finAberta(cr) || linha.valor == null) continue;
        const v = CaixaCore.arredondar(linha.valor);
        const max = CaixaCore.arredondar(cr.valor);
        if (!(v > 0)) return { ok: false, erro: 'Informe um valor maior que zero.' };
        if (v > max) return { ok: false, erro: 'O valor não pode passar de R$ ' + max.toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 }) + '.' };
    }
    const usuario = getUsuarioLogado();
    const agora = Date.now();
    const peds = new Set();
    if (!Array.isArray(db.movimentos_fin)) db.movimentos_fin = [];
    const novoIdCR = _novosIdsFin(db.contas_receber);
    const novoIdCP = _novosIdsFin(db.contas_pagar);
    const novoIdMov = _novosIdsFin(db.movimentos_fin);
    (linhas || []).forEach(linha => {
        let cr = db.contas_receber.find(x => CaixaCore.mesmoId(x.id, linha.id));
        if (!finAberta(cr)) return;
        const valor = linha.valor == null ? CaixaCore.arredondar(cr.valor) : CaixaCore.arredondar(linha.valor);
        if (valor < CaixaCore.arredondar(cr.valor)) {
            const { pago, resto } = CaixaCore.dividirParcela(cr, valor);
            const parte = { ...cr, id: novoIdCR(), valor: pago, parcela_origem_id: cr.id };
            if (Array.isArray(cr.historico)) parte.historico = cr.historico.map(h => ({ ...h }));
            ['estornado_por', 'estornado_em', 'ultima_cobranca'].forEach(k => delete parte[k]);
            cr.valor = resto;
            finHist(cr, 'editado', `Parcela dividida: ${_finBrl(pago)} recebido à parte; ficou ${_finBrl(resto)} em aberto`);
            db.contas_receber.push(parte);
            cr = parte;
        }
        const meio = linha.meio_id == null ? null : getMeiosPag().find(m => CaixaCore.mesmoId(m.id, linha.meio_id));
        const conta = _contaFinPorId(linha.conta_id);
        cr.status = 'Pago';
        cr.data_pagamento = data;
        cr.meio_id = meio ? meio.id : null;
        cr.conta_id = conta ? conta.id : null;
        cr.cartao = linha.cartao ? { tipo: linha.cartao.tipo, vezes: linha.cartao.vezes || 1, antecipar: !!linha.cartao.antecipar } : null;
        cr.forma_pagamento = meio ? meio.nome : (linha.meio_nome || null);
        cr.baixado_por = usuario?.id || null;
        cr.baixado_em = agora;
        finHist(cr, 'baixa', `Recebido ${_finBrl(cr.valor)} em ${_finDataBR(data)}${cr.forma_pagamento ? ' (' + cr.forma_pagamento + ')' : ''}${conta ? ' — ' + (conta.nome || '') : ''}`);
        if (cr.pedido_id) peds.add(cr.pedido_id);
        const aceita = CaixaCore.contaAceitaMovimento(conta, data);
        if (aceita) _finContaTocada(conta.id);
        // Conta que nao aceita movimento: sem movimento, mas a taxa de cartao continua sendo despesa (gera so a conta de taxa).
        if (!aceita && !cr.cartao) return;
        const grupo = novoIdMov();
        const desc = cr.descricao || 'Recebimento';
        const entrada = (d, v, descricao) => aceita && db.movimentos_fin.push({ id: novoIdMov(), conta_id: conta.id, data: d, sentido: 'entrada', valor: v, origem: 'cr', origem_id: cr.id, grupo_id: grupo, descricao });
        if (!cr.cartao) { entrada(data, cr.valor, desc); return; }
        const repasses = CaixaCore.repassesCartao({ valor: cr.valor, data, conta, tipo: cr.cartao.tipo, vezes: cr.cartao.vezes, antecipar: cr.cartao.antecipar });
        // Sem movimento, o Resultado e a Visao Geral leem as datas dos repasses daqui (as da maquininha na baixa).
        if (!aceita) cr.cartao.repasses = repasses.map(r => ({ data: r.data, bruto: r.bruto }));
        repasses.forEach((r, i) => {
            entrada(r.data, r.bruto, repasses.length > 1 ? `${desc} (cartão ${i + 1}/${repasses.length})` : `${desc} (cartão)`);
            if (!(r.taxa > 0)) return;
            const cp = finCompletarLancamento('cp', {
                id: novoIdCP(), tipo: 'variavel', categoria: 'taxa_cartao', descricao: 'Taxa de cartão — ' + desc,
                credor_nome: (conta && conta.nome) || '', valor: r.taxa, data_vencimento: r.data, data_pagamento: r.data, status: 'Pago',
                conta_id: conta ? conta.id : null, origem_cr_id: cr.id, baixado_por: usuario?.id || null, baixado_em: agora
            }, null, 'Taxa do cartão do recebimento: ' + desc);
            finHist(cp, 'baixa', `Pago ${_finBrl(cp.valor)} em ${_finDataBR(r.data)} (descontado no repasse do cartão)`);
            db.contas_pagar.push(cp);
            if (!aceita) return;
            db.movimentos_fin.push({ id: novoIdMov(), conta_id: conta.id, data: r.data, sentido: 'saida', valor: r.taxa, origem: 'cp', origem_id: cp.id, grupo_id: grupo, descricao: cp.descricao });
        });
    });
    peds.forEach(id => {
        sincronizarRecebidoPedido(id);
        // Tudo recebido de novo (depois de um estorno, por exemplo): nao ha mais pendencia.
        const ped = db.pedidos.find(p => p.id == id);
        if (ped && ped.pagamento_pendente && FinanceiroCore.saldoEmAberto(db.contas_receber, id) <= 0.01) ped.pagamento_pendente = false;
    });
    return { ok: true };
}

// O que a baixa de um recebimento gerou: entradas dele, contas de taxa de
// cartao e as saidas delas. `caidos` = entradas com data <= hoje.
function _movimentosDaBaixaCR(crId) {
    const hoje = hojeLocal();
    const taxas = (db.contas_pagar || []).filter(cp => cp.categoria === 'taxa_cartao' && CaixaCore.mesmoId(cp.origem_cr_id, crId));
    const movs = (db.movimentos_fin || []).filter(m =>
        (m.origem === 'cr' && CaixaCore.mesmoId(m.origem_id, crId)) ||
        (m.origem === 'cp' && taxas.some(t => CaixaCore.mesmoId(t.id, m.origem_id))));
    const caidos = movs.filter(m => m.origem === 'cr' && m.data <= hoje);
    return { taxas, movs, caidos };
}

function removerMovimentosDaBaixaCR(crId) {
    const { taxas, movs, caidos } = _movimentosDaBaixaCR(crId);
    if (movs.length) db.movimentos_fin = db.movimentos_fin.filter(m => !movs.includes(m));
    if (taxas.length) db.contas_pagar = db.contas_pagar.filter(cp => !taxas.includes(cp));
    return { removidos: movs.length, caidos };
}

// A comissao e um registro do pedido (registrada -> pendente -> paga), sem conta a pagar.
// Poe o status certo de cada comissao do pedido pela etapa dele (aprovado = registrada,
// Instalado = pendente, voltou de Instalado = registrada; paga continua paga). Idempotente; nao grava.
function sincronizarComissoesPedido(ped) {
    const textos = {
        registrada: de => (de === 'pendente' ? 'Pedido saiu de Instalado: a comissão voltou a ficar registrada' : 'Comissão registrada com a aprovação do pedido'),
        pendente: () => 'Pedido instalado: comissão a pagar',
        em_cp: () => 'Comissão antiga com conta em aberto: fica em Contas a Pagar até ser paga',
        paga: () => 'Comissão paga'
    };
    return FinanceiroCore.sincronizarStatusComissoes(ped, (papel, de, para) =>
        Object.assign({ acao: para === 'registrada' && de === 'pendente' ? 'voltou' : para, detalhe: textos[para](de), em: new Date().toISOString() }, _finQuem()), db.contas_pagar);
}

// Pedido instalado: as comissoes ficam pendentes (sem criar conta a pagar). Idempotente.
function gerarComissoesPedido(ped) {
    // Pedido que voltou a ser Instalado: a marca "pedido cancelado" da comissao
    // ja paga (antiga conta a pagar) nao vale mais.
    (db.contas_pagar || []).forEach(cp => {
        if (cp.pedido_id == ped.id && cp.papel_comissao && cp.pedido_cancelado) delete cp.pedido_cancelado;
    });
    sincronizarComissoesPedido(ped);
}

// Linha de extrato conciliada cujo movimento sumiu volta a pendente (sem gravar; quem chama grava sc_fin_extrato).
// Igual a rotina do Fluxo, mas vale em qualquer tela (fin-fluxo.js nao carrega em todas).
function _desligarExtratoSumido() {
    if (!Array.isArray(db.fin_extrato) || typeof ConciliacaoCore === 'undefined') return [];
    const iv = ConciliacaoCore.indiceVinculos({ movimentos: db.movimentos_fin || [], contasReceber: db.contas_receber || [], contasPagar: db.contas_pagar || [] });
    const ids = [];
    db.fin_extrato.forEach(l => {
        if (!ConciliacaoCore.linhaOrfa(l, iv)) return;
        l.situacao = 'pendente'; l.mov_id = null;
        ['mov_ids', 'vinculos', 'conc_desc', 'conc_em', 'conc_por', 'transf_grupo', 'criado', 'datas_antes'].forEach(k => { delete l[k]; });
        ids.push(l.id);
    });
    return ids;
}

function _permiteGerirComissoes() { return temAcesso('vendedores', 'completo') || temAcesso('financeiro.pagar', 'completo'); }

// Paga comissoes pendentes: um movimento de saida por comissao (origem 'comissao', categoria Comissoes) na conta
// escolhida, e a comissao vira paga. itens: [{ pedidoId, papel: 'vendedor'|'arquiteto' }]. Valida tudo antes de mexer.
// Devolve { ok, erro, pagos, total }. Grava (pedidos, movimentos e saldo da conta).
function registrarPagamentoComissoes({ itens, contaId, data } = {}) {
    if (!_permiteGerirComissoes()) return { ok: false, erro: 'Você não tem permissão para realizar esta ação.' };
    const erroData = _erroDataBaixa(data);
    if (erroData) return { ok: false, erro: erroData };
    const conta = _contaFinPorId(contaId);
    if (!conta) return { ok: false, erro: 'Escolha a conta.' };
    if (!CaixaCore.contaAceitaMovimento(conta, data)) return { ok: false, erro: 'A conta está inativa ou a data é anterior ao saldo inicial dela.' };
    const alvos = [];
    for (const it of (itens || [])) {
        const ped = db.pedidos.find(p => p.id == it.pedidoId);
        const c = CAMPOS_COMISSAO[it.papel], r = FinanceiroCore.CAMPOS_COMISSAO_REG[it.papel];
        if (!ped || !c || !FinanceiroCore.temComissao(ped, it.papel) || (ped[r.status] || FinanceiroCore.statusEsperadoComissao(ped, it.papel, db.contas_pagar)) !== 'pendente')
            return { ok: false, erro: `A comissão do pedido #${formatPedidoId(it.pedidoId)} não está pendente.` };
        if (!alvos.some(a => a.ped === ped && a.papel === it.papel)) alvos.push({ ped, papel: it.papel, c, r });
    }
    if (!alvos.length) return { ok: false, erro: 'Nenhuma comissão pendente para pagar.' };
    if (!Array.isArray(db.movimentos_fin)) db.movimentos_fin = [];
    const novoIdMov = _novosIdsFin(db.movimentos_fin);
    // Para voltar ao que era se faltar espaco para gravar.
    const antes = { peds: alvos.map(a => [a.ped, JSON.parse(JSON.stringify(a.ped))]), nMov: db.movimentos_fin.length, saldoEm: conta.saldo_atualizado_em };
    const quando = new Date(data + 'T12:00:00').getTime();
    let total = 0;
    alvos.forEach(({ ped, papel, c, r }) => {
        const valor = CaixaCore.arredondar(ped[c.valor]);
        const v = (db.vendedores || []).find(x => x.id == ped[c.id]);
        const nome = (v && v.nome) || ped[c.nome] || '';
        const mov = { id: novoIdMov(), conta_id: conta.id, data, sentido: 'saida', valor, origem: 'comissao', origem_id: ped.id, papel, grupo_id: null,
            descricao: `Comissão ${nome} — Pedido #${formatPedidoId(ped.id)}`, categoria_id: 'cat_comissoes' };
        db.movimentos_fin.push(mov);
        ped[r.status] = 'paga'; ped[c.paga] = true; ped[c.data] = quando; ped[r.mov] = mov.id; ped[r.conta] = conta.id;
        if (!Array.isArray(ped[r.hist])) ped[r.hist] = [];
        ped[r.hist].push(Object.assign({ acao: 'paga', detalhe: `Pago ${_finBrl(valor)} em ${_finDataBR(data)} — ${conta.nome || ''}`, em: new Date().toISOString() }, _finQuem()));
        total += valor;
    });
    _finContaTocada(conta.id);
    if (!_gravarChaves(['sc_ped', 'sc_mov_fin', 'sc_contas_fin'], { silencioso: true })) {
        antes.peds.forEach(([p, copia]) => { Object.keys(p).forEach(k => { delete p[k]; }); Object.assign(p, copia); });
        db.movimentos_fin.length = antes.nMov;
        conta.saldo_atualizado_em = antes.saldoEm;
        return { ok: false, erro: MSG_SEM_ESPACO };
    }
    return { ok: true, pagos: alvos.length, total: CaixaCore.arredondar(total) };
}

// Desfaz o pagamento de uma comissao: tira o movimento (o saldo da conta volta) e a comissao volta a pendente
// (ou a registrada, se o pedido ja saiu de Instalado). Pagamento antigo, feito por conta a pagar, estorna a conta
// e a tira do Financeiro (a comissao agora e do pedido). Devolve { ok, erro }.
function desfazerPagamentoComissao({ pedidoId, papel } = {}) {
    if (!_permiteGerirComissoes()) return { ok: false, erro: 'Você não tem permissão para realizar esta ação.' };
    const ped = db.pedidos.find(p => p.id == pedidoId);
    const c = CAMPOS_COMISSAO[papel], r = FinanceiroCore.CAMPOS_COMISSAO_REG[papel];
    if (!ped || !c || (ped[r.status] || FinanceiroCore.statusEsperadoComissao(ped, papel)) !== 'paga') return { ok: false, erro: 'Esta comissão não está paga.' };
    const mov = ped[r.mov] != null ? (db.movimentos_fin || []).find(m => CaixaCore.mesmoId(m.id, ped[r.mov])) : null;
    // Para voltar ao que era se faltar espaco para gravar (pedido, listas e saldo das contas tocadas).
    const antesD = { ped: JSON.parse(JSON.stringify(ped)), movs: (db.movimentos_fin || []).slice(), cps: (db.contas_pagar || []).map(x => [x, JSON.parse(JSON.stringify(x))]),
        cpLista: (db.contas_pagar || []).slice(), exc: (db.fin_excluidos || []).slice(), extrato: JSON.stringify(db.fin_extrato || []), contas: JSON.stringify(getContasFin()) };
    const dataPgto = FinanceiroCore.dataLocalISO(ped[c.data]);
    if (mov && mov.origem === 'comissao') {
        db.movimentos_fin = db.movimentos_fin.filter(m => m !== mov);
        _finContaTocada(mov.conta_id);
    } else {
        const cp = (db.contas_pagar || []).find(x => x.pedido_id == ped.id && x.status === 'Pago' && FinanceiroCore.papelDaContaComissao(x) === papel);
        if (cp) {
            _estornarCPDados(cp);
            _finRegistrarExcluidos('cp', [cp]);
            db.fin_excluidos[db.fin_excluidos.length - 1].motivo = FinanceiroCore.MOTIVO_COMISSAO_V2;
            db.contas_pagar = db.contas_pagar.filter(x => x !== cp);
        }
    }
    ped[c.paga] = false; ped[c.data] = null;
    delete ped[r.mov]; delete ped[r.conta]; delete ped[r.status];
    sincronizarComissoesPedido(ped);
    if (!Array.isArray(ped[r.hist])) ped[r.hist] = [];
    ped[r.hist].push(Object.assign({ acao: 'pagamento_desfeito', detalhe: `Pagamento de ${_finBrl(ped[c.valor])}${dataPgto ? ' em ' + _finDataBR(dataPgto) : ''} desfeito`, em: new Date().toISOString() }, _finQuem()));
    _desligarExtratoSumido();
    if (!_gravarChaves(['sc_ped', 'sc_mov_fin', 'sc_contas_fin', 'sc_cp', 'sc_fin_excluidos', 'sc_fin_extrato'], { silencioso: true })) {
        Object.keys(ped).forEach(k => { delete ped[k]; }); Object.assign(ped, antesD.ped);
        db.movimentos_fin = antesD.movs;
        db.contas_pagar = antesD.cpLista; antesD.cps.forEach(([x, copia]) => { Object.keys(x).forEach(k => { delete x[k]; }); Object.assign(x, copia); });
        db.fin_excluidos = antesD.exc;
        db.fin_extrato = JSON.parse(antesD.extrato);
        const cs = JSON.parse(antesD.contas); getContasFin().forEach((c, i) => { Object.keys(c).forEach(k => { delete c[k]; }); Object.assign(c, cs[i]); });
        return { ok: false, erro: MSG_SEM_ESPACO };
    }
    return { ok: true };
}

// Janela do pagamento de comissoes: conta*, data* (hoje) e o total. Devolve { contaId, data } ou null.
// itens: [{ descricao, valor }].
function abrirModalPagarComissoes({ titulo, itens }) {
    return new Promise(resolve => {
        const hoje = hojeLocal();
        const contas = getContasFin().filter(c => c.ativo !== false);
        const total = (itens || []).reduce((s, i) => s + (Number(i.valor) || 0), 0);
        const sel = 'width:100%;padding:6px;border:1px solid var(--border-strong);border-radius:4px;font-size:13px;box-sizing:border-box';
        const o = document.createElement('div');
        o.id = 'com-pag-modal';
        o.className = 'sc-modal-overlay';
        o.style.display = 'flex';
        o.innerHTML = `<div class="sc-modal-box" style="text-align:left;max-width:460px;width:calc(100% - 32px)">
            <h3 style="margin:0 0 12px;font-size:16px">${escapeHtml(titulo || 'Registrar pagamento')}</h3>
            <div style="max-height:30vh;overflow:auto;margin-bottom:10px;font-size:13px">${(itens || []).map(i => `<div style="display:flex;justify-content:space-between;gap:8px;padding:3px 0"><span>${escapeHtml(i.descricao || '')}</span><strong>${_finBrl(i.valor)}</strong></div>`).join('')}</div>
            <label style="display:block;font-size:12px;margin-bottom:4px">Conta *</label>
            <select id="com-pag-conta" style="${sel};margin-bottom:10px"><option value="">Escolha a conta</option>${contas.map(c => `<option value="${escapeHtml(String(c.id))}">${escapeHtml(c.nome || '')}</option>`).join('')}</select>
            <label style="display:block;font-size:12px;margin-bottom:4px">Data *</label>
            <input type="date" id="com-pag-data" value="${hoje}" max="${hoje}" style="${sel};margin-bottom:10px">
            <div id="com-pag-erro" style="display:none;color:var(--danger-text);font-size:12px;margin-bottom:8px"></div>
            <div style="display:flex;justify-content:space-between;font-size:14px;margin-bottom:12px"><span>Total</span><strong id="com-pag-total">${_finBrl(total)}</strong></div>
            <div class="sc-modal-btns"><button class="btn btn-outline" id="com-pag-cancel">Cancelar</button><button class="btn btn-success" id="com-pag-ok">Registrar pagamento</button></div>
        </div>`;
        document.body.appendChild(o);
        if (!contas.length) {
            const e0 = o.querySelector('#com-pag-erro');
            e0.textContent = 'Cadastre uma conta em Configurar Empresa para registrar o pagamento.';
            e0.style.display = 'block';
            o.querySelector('#com-pag-ok').disabled = true;
        }
        const fechar = v => { o.remove(); resolve(v); };
        const erro = t => { const e = o.querySelector('#com-pag-erro'); e.textContent = t; e.style.display = 'block'; };
        o.querySelector('#com-pag-cancel').onclick = () => fechar(null);
        o.addEventListener('click', e => { if (e.target === o) fechar(null); });
        o.querySelector('#com-pag-ok').onclick = () => {
            const contaId = o.querySelector('#com-pag-conta').value;
            const data = o.querySelector('#com-pag-data').value;
            if (!contaId) return erro('Escolha a conta.');
            const e = _erroDataBaixa(data);
            if (e) return erro(e);
            const conta = _contaFinPorId(contaId);
            if (!CaixaCore.contaAceitaMovimento(conta, data)) return erro('A data é anterior ao saldo inicial da conta.');
            fechar({ contaId, data });
        };
    });
}

// Papel da comissao de uma conta a pagar: o gravado nela ou, na antiga
// 'comissao_rt' (sem papel), o arquiteto. Outras contas: null.
function _papelDaComissao(cp) {
    if (cp.papel_comissao) return cp.papel_comissao;
    return cp.categoria === 'comissao_rt' ? 'arquiteto' : null;
}

// Baixa de pagamentos, linha a linha: grava meio e conta e gera uma saida se a
// conta aceita. A comissao so e marcada como paga aqui (Fase 0).
function baixarContasPagar(data, linhas) {
    const erroData = _erroDataBaixa(data);
    if (erroData) return { ok: false, erro: erroData };
    const usuario = getUsuarioLogado();
    if (!Array.isArray(db.movimentos_fin)) db.movimentos_fin = [];
    const novoIdMov = _novosIdsFin(db.movimentos_fin);
    (linhas || []).forEach(linha => {
        const cp = db.contas_pagar.find(x => CaixaCore.mesmoId(x.id, linha.id));
        if (!finAberta(cp)) return;
        const meio = linha.meio_id == null ? null : getMeiosPag().find(m => CaixaCore.mesmoId(m.id, linha.meio_id));
        const conta = _contaFinPorId(linha.conta_id);
        cp.status = 'Pago';
        cp.data_pagamento = data;
        cp.meio_id = meio ? meio.id : null;
        cp.conta_id = conta ? conta.id : null;
        cp.forma_pagamento = meio ? meio.nome : (linha.meio_nome || null);
        cp.baixado_por = usuario?.id || null;
        cp.baixado_em = Date.now();
        finHist(cp, 'baixa', `Pago ${_finBrl(cp.valor)} em ${_finDataBR(data)}${cp.forma_pagamento ? ' (' + cp.forma_pagamento + ')' : ''}${conta ? ' — ' + (conta.nome || '') : ''}`);
        const papelCom = _papelDaComissao(cp);
        if (papelCom && cp.pedido_id) {
            const ped = db.pedidos.find(p => p.id == cp.pedido_id);
            const c = CAMPOS_COMISSAO[papelCom];
            if (ped && c && (cp.papel_comissao || ped[c.id])) {
                ped[c.paga] = true;
                ped[c.data] = new Date(data + 'T12:00:00').getTime();
                sincronizarComissoesPedido(ped);   // conta toda paga: a comissao fica paga
            }
        }
        if (!CaixaCore.contaAceitaMovimento(conta, data)) return;
        db.movimentos_fin.push({ id: novoIdMov(), conta_id: conta.id, data, sentido: 'saida', valor: CaixaCore.arredondar(cp.valor), origem: 'cp', origem_id: cp.id, grupo_id: null, descricao: cp.descricao || 'Pagamento' });
        _finContaTocada(conta.id);
    });
    return { ok: true };
}

// Tira os movimentos da baixa de uma conta a pagar (o estorno usa). Devolve quantos saíram.
function removerMovimentosDaBaixaCP(cpId) {
    const antes = (db.movimentos_fin || []).length;
    db.movimentos_fin = (db.movimentos_fin || []).filter(m => !(m.origem === 'cp' && CaixaCore.mesmoId(m.origem_id, cpId)));
    return antes - db.movimentos_fin.length;
}

// Desfaz o pagamento de uma conta a pagar (a taxa de cartao sai pelo estorno
// do recebimento). Comissao volta a ficar pendente no pedido.
async function estornarCP(id) {
    if (!await exigirPermissao('financeiro.pagar', 'completo')) return;
    const cp = db.contas_pagar.find(x => CaixaCore.mesmoId(x.id, id));
    if (!cp || cp.status !== 'Pago') return;
    if (cp.categoria === 'taxa_cartao') { await showAlert('A taxa do cartão sai pelo estorno do recebimento.', 'ℹ️'); return; }
    if (FinanceiroCore.papelDaContaComissao(cp) && cp.pedido_id != null) {
        await showAlert('Esta comissão foi paga antes da mudança. Para desfazer, use Vendedores › Comissões.', 'ℹ️'); return;
    }
    if (!await showConfirm('Estornar este pagamento? A conta volta a ficar em aberto.', '↩', 'Estornar', 'Cancelar')) return;
    _estornarCPDados(cp);
    _desligarExtratoSumido();
    salvarERecarregar('Pagamento estornado.');
}

// O estorno de uma conta a pagar paga, sem perguntas nem gravacao (estornarCP e o Desfazer da conciliacao usam).
function _estornarCPDados(cp) {
    const contasMov = (db.movimentos_fin || []).filter(m => m.origem === 'cp' && CaixaCore.mesmoId(m.origem_id, cp.id)).map(m => m.conta_id);
    removerMovimentosDaBaixaCP(cp.id);
    contasMov.forEach(_finContaTocada);
    finHist(cp, 'estorno', `Pagamento de ${_finBrl(cp.valor)} em ${_finDataBR(cp.data_pagamento)} estornado`);
    const hoje = hojeLocal();
    cp.status = (cp.data_vencimento && cp.data_vencimento < hoje) ? 'Atrasado' : 'Pendente';
    ['data_pagamento', 'forma_pagamento', 'meio_id', 'baixado_por', 'baixado_em'].forEach(k => { cp[k] = null; });
    cp.estornado_por = getUsuarioLogado()?.id || null;
    cp.estornado_em = Date.now();
    const papelCom = _papelDaComissao(cp);
    if (papelCom && cp.pedido_id) {
        const ped = db.pedidos.find(p => p.id == cp.pedido_id);
        const c = CAMPOS_COMISSAO[papelCom];
        if (ped && c && (cp.papel_comissao || ped[c.id])) { ped[c.paga] = false; ped[c.data] = null; sincronizarComissoesPedido(ped); }
    }
}

// Mesma regra do excluirCR: conta paga so sai pelo estorno; taxa de
// cartao nunca sai por aqui. Devolve true se bloqueou.
async function _bloqueiaExclusaoCP(cps) {
    if (cps.some(cp => cp.categoria === 'taxa_cartao')) { await showAlert('A taxa do cartão sai pelo estorno do recebimento.', 'ℹ️'); return true; }
    if (cps.some(cp => cp.status === 'Pago')) {
        await showAlert('Esta conta já foi paga. Estorne o pagamento antes de excluir.', '⚠️'); return true;
    }
    return false;
}

async function marcarCRPago(id) {
    if (!await exigirPermissao('financeiro.receber', 'completo')) return;
    const cr = db.contas_receber.find(x => x.id == id);
    if (!cr) return;
    const ped = db.pedidos.find(p => p.id == cr.pedido_id);
    const r = await abrirModalBaixa({
        titulo: 'Registrar recebimento',
        itens: [{ id: cr.id, descricao: cr.descricao, valor: cr.valor, marcado: true, meio_previsto: cr.meio_previsto || null, conta_prevista: cr.conta_id != null ? cr.conta_id : null }],
        formaPadrao: formaPagamentoDoPedido(ped) || cr.forma_pagamento || '',
        permiteParcial: true
    });
    if (!r || !r.linhas.length) return;
    const baixa = baixarContasReceber(r.data, r.linhas);
    if (!baixa.ok) { await showAlert(baixa.erro, '⚠️'); return; }
    salvarERecarregar('Recebimento registrado!');
}

async function estornarCR(id) {
    if (!await exigirPermissao('financeiro.receber', 'completo')) return;
    const cr = db.contas_receber.find(x => x.id == id);
    if (!cr || cr.status !== 'Pago') return;
    // Parte paga de uma parcela dividida: volta a se juntar a parte em aberto.
    const origem = cr.parcela_origem_id != null ? db.contas_receber.find(x => CaixaCore.mesmoId(x.id, cr.parcela_origem_id)) : null;
    const juntar = !!origem && origem !== cr && finAberta(origem);
    let msg = juntar
        ? 'Estornar este recebimento? O valor volta para a parcela em aberto.'
        : 'Estornar este recebimento? A parcela volta a ficar em aberto.';
    const { caidos } = _movimentosDaBaixaCR(cr.id);
    if (cr.cartao && caidos.length) {
        const nomes = [...new Set(caidos.map(m => (_contaFinPorId(m.conta_id) || {}).nome).filter(Boolean))];
        if (nomes.length) msg += ` Isso muda o saldo de hoje da conta ${nomes.join(', ')}.`;
    }
    if (!await showConfirm(msg, '↩', 'Estornar', 'Cancelar')) return;
    _estornarCRDados(cr);
    _desligarExtratoSumido();
    salvarERecarregar('Recebimento estornado.');
}

// O estorno de um recebimento pago, sem perguntas nem gravacao (estornarCR e o Desfazer da conciliacao usam):
// tira os movimentos e as taxas de cartao da baixa; parte paga de parcela dividida volta para a parcela em aberto.
function _estornarCRDados(cr) {
    const origem = cr.parcela_origem_id != null ? db.contas_receber.find(x => CaixaCore.mesmoId(x.id, cr.parcela_origem_id)) : null;
    const juntar = !!origem && origem !== cr && finAberta(origem);
    const contasMov = _movimentosDaBaixaCR(cr.id).movs.map(m => m.conta_id);
    removerMovimentosDaBaixaCR(cr.id);
    contasMov.forEach(_finContaTocada);
    const usuarioId = getUsuarioLogado()?.id || null;
    if (juntar) {
        finHist(origem, 'estorno', `Recebimento de ${_finBrl(cr.valor)} em ${_finDataBR(cr.data_pagamento)} estornado; o valor voltou para esta parcela`);
        origem.valor = CaixaCore.arredondar(Number(origem.valor) + Number(cr.valor));
        origem.estornado_por = usuarioId;
        origem.estornado_em = Date.now();
        db.contas_receber = db.contas_receber.filter(x => x !== cr);
    } else {
        finHist(cr, 'estorno', `Recebimento de ${_finBrl(cr.valor)} em ${_finDataBR(cr.data_pagamento)} estornado`);
        const hoje = hojeLocal();
        cr.status = (cr.data_vencimento && cr.data_vencimento < hoje) ? 'Atrasado' : 'Pendente';
        cr.data_pagamento = null;
        cr.forma_pagamento = null;
        cr.meio_id = null;
        cr.cartao = null;
        cr.baixado_por = null;
        cr.baixado_em = null;
        cr.estornado_por = usuarioId;
        cr.estornado_em = Date.now();
    }
    if (cr.pedido_id) {
        sincronizarRecebidoPedido(cr.pedido_id);
        // O pedido deixa de estar quitado: a migracao da Fase 0 (por exemplo, ao
        // importar um backup antigo) nao pode baixar esta parcela de novo.
        const ped = db.pedidos.find(p => p.id == cr.pedido_id);
        if (ped) ped.pagamento_pendente = true;
    }
}

async function excluirCR(id) {
    if (!await exigirPermissao('financeiro.receber', 'completo')) return;
    const cr = db.contas_receber.find(x => x.id == id);
    if (!cr) return;
    // Recebimento so sai pelo estorno (que registra quem desfez e quando).
    if (cr.status === 'Pago') { await showAlert('Estorne o recebimento antes de excluir.', '⚠️'); return; }
    // Parcela em aberto que ja teve partes pagas: as partes perderiam a origem.
    if (db.contas_receber.some(x => x !== cr && x.status === 'Pago' && CaixaCore.mesmoId(x.parcela_origem_id, cr.id))) {
        await showAlert('Esta parcela tem partes pagas. Estorne as partes antes de excluir.', '⚠️'); return;
    }
    if (!await showConfirm('Remover este lançamento a receber?', '🗑️', 'Remover', 'Cancelar')) return;
    _finRegistrarExcluidos('cr', db.contas_receber.filter(x => x.id == id));
    db.contas_receber = db.contas_receber.filter(x => x.id != id);
    if (cr.pedido_id) sincronizarRecebidoPedido(cr.pedido_id);
    salvarERecarregar('Lançamento removido.');
}

// --- CONTAS A PAGAR: validação de CNPJ (dígitos verificadores) ---
function validarCNPJ(cnpj) {
    const d = String(cnpj || '').replace(/\D/g, '');
    if (d.length !== 14 || /^(\d)\1{13}$/.test(d)) return false;
    const calcDV = (base) => {
        let pos = base.length - 7, soma = 0;
        for (let i = 0; i < base.length; i++) { soma += parseInt(base[i]) * pos--; if (pos < 2) pos = 9; }
        const resto = soma % 11;
        return resto < 2 ? 0 : 11 - resto;
    };
    const dv1 = calcDV(d.slice(0, 12));
    const dv2 = calcDV(d.slice(0, 12) + dv1);
    return d === d.slice(0, 12) + String(dv1) + String(dv2);
}

// --- CONTAS A PAGAR: decodificação de linha digitável (padrão FEBRABAN) ---
// Referência: manual de padrões da FEBRABAN para código de barras de arrecadação e boletos bancários.
const BANCOS_COMPENSACAO = {
    '001': 'Banco do Brasil', '033': 'Santander', '077': 'Inter', '104': 'Caixa Econômica Federal',
    '237': 'Bradesco', '260': 'Nubank', '341': 'Itaú', '399': 'HSBC', '422': 'Safra',
    '070': 'BRB', '745': 'Citibank', '212': 'Banco Original', '336': 'C6 Bank', '655': 'Neon',
};
function bancoPorCodigo(codigo) { return BANCOS_COMPENSACAO[codigo] || `Banco ${codigo}`; }

function _mod10Boleto(digits) {
    let soma = 0, peso = 2;
    for (let i = digits.length - 1; i >= 0; i--) {
        let prod = parseInt(digits[i]) * peso;
        if (prod > 9) prod -= 9;
        soma += prod;
        peso = peso === 2 ? 1 : 2;
    }
    const resto = soma % 10;
    return resto === 0 ? 0 : 10 - resto;
}
function _mod11BoletoGeral(digits43) {
    let soma = 0, peso = 2;
    for (let i = digits43.length - 1; i >= 0; i--) {
        soma += parseInt(digits43[i]) * peso;
        peso = peso === 9 ? 2 : peso + 1;
    }
    const resto = soma % 11;
    let dv = 11 - resto;
    if (dv === 0 || dv === 10 || dv === 11) dv = 1;
    return dv;
}
function _mod11ConvenioBloco(digits) {
    let soma = 0, peso = 2;
    for (let i = digits.length - 1; i >= 0; i--) {
        soma += parseInt(digits[i]) * peso;
        peso = peso === 9 ? 2 : peso + 1;
    }
    const resto = soma % 11;
    let dv = 11 - resto;
    if (dv >= 10) dv = 0;
    return dv;
}
// Fator de vencimento: dias corridos desde uma data-base. A FEBRABAN trocou a base em 22/02/2025
// (a base de 1997 estava perto de estourar o campo de 4 dígitos). Escolhemos a base cujo resultado
// cai numa janela plausível (evita confundir uma data de 1998 com uma de 2028, por exemplo).
function _fatorParaData(fator) {
    if (!fator) return null;
    const baseClassica = new Date(Date.UTC(1997, 9, 7));
    const baseNova = new Date(Date.UTC(2022, 1, 22));
    const dClassica = new Date(baseClassica.getTime() + fator * 86400000);
    const dNova = new Date(baseNova.getTime() + fator * 86400000);
    const hoje = new Date();
    const dentroFaixa = dt => { const anos = (dt - hoje) / (365 * 86400000); return anos > -3 && anos < 6; };
    if (dentroFaixa(dNova)) return dNova.toISOString().split('T')[0];
    if (dentroFaixa(dClassica)) return dClassica.toISOString().split('T')[0];
    return dNova.toISOString().split('T')[0];
}
function _decodificarBoletoBancario(d) {
    const c1 = d.slice(0, 9), dv1 = d[9];
    const c2 = d.slice(10, 20), dv2 = d[20];
    const c3 = d.slice(21, 31), dv3 = d[31];
    const dvGeral = d[32];
    const fatorVenc = d.slice(33, 37);
    const valorStr = d.slice(37, 47);
    if (_mod10Boleto(c1) !== parseInt(dv1)) return { ok: false, motivo: 'Dígito verificador do 1º campo não confere — revise a linha digitável.' };
    if (_mod10Boleto(c2) !== parseInt(dv2)) return { ok: false, motivo: 'Dígito verificador do 2º campo não confere — revise a linha digitável.' };
    if (_mod10Boleto(c3) !== parseInt(dv3)) return { ok: false, motivo: 'Dígito verificador do 3º campo não confere — revise a linha digitável.' };
    const banco = c1.slice(0, 3);
    const moeda = c1[3];
    const campoLivre = c1.slice(4, 9) + c2 + c3;
    const barcode43 = banco + moeda + fatorVenc + valorStr + campoLivre;
    if (_mod11BoletoGeral(barcode43) !== parseInt(dvGeral)) return { ok: false, motivo: 'Dígito verificador geral não confere — revise a linha digitável.' };
    return { ok: true, tipo: 'boleto', bancoCodigo: banco, banco: bancoPorCodigo(banco), valor: parseInt(valorStr, 10) / 100, vencimento: _fatorParaData(parseInt(fatorVenc, 10)) };
}
function _decodificarConvenio(d) {
    const blocos = [d.slice(0, 12), d.slice(12, 24), d.slice(24, 36), d.slice(36, 48)];
    const indicadorValor = d[2];
    const usaMod10 = indicadorValor === '6' || indicadorValor === '7';
    const checar = usaMod10 ? _mod10Boleto : _mod11ConvenioBloco;
    let barcode = '';
    for (const bloco of blocos) {
        const corpo = bloco.slice(0, 11), dv = bloco[11];
        if (checar(corpo) !== parseInt(dv)) return { ok: false, motivo: 'Dígito verificador não confere — revise a linha digitável de convênio.' };
        barcode += corpo;
    }
    const valorEfetivo = indicadorValor === '6' || indicadorValor === '8';
    const valorStr = barcode.slice(4, 15);
    return { ok: true, tipo: 'convenio', valor: valorEfetivo ? parseInt(valorStr, 10) / 100 : null, valorReferencia: !valorEfetivo, vencimento: null };
}
function decodificarLinhaDigitavel(raw) {
    const d = String(raw || '').replace(/\D/g, '');
    if (d.length === 47) return _decodificarBoletoBancario(d);
    if (d.length === 48) return _decodificarConvenio(d);
    if (d.length === 44) return { ok: false, motivo: 'Isso parece um código de barras (44 dígitos) — cole a linha digitável impressa no boleto (47 ou 48 dígitos), não o código de barras.' };
    return { ok: false, motivo: null };
}

// Busca um lançamento anterior pelo número do documento (não há API pública gratuita para isso —
// só encontra o que já foi lançado/importado antes neste mesmo sistema).
function buscarNumeroDocumentoHistorico(numero, cnpjDigits) {
    const num = String(numero || '').replace(/\D/g, '');
    if (!num) return null;
    return db.contas_pagar.find(cp => cp.numero_documento && cp.numero_documento.replace(/\D/g, '') === num
        && (!cnpjDigits || (cp.cnpj_fornecedor || '').replace(/\D/g, '') === cnpjDigits)) || null;
}

// Gera as datas de vencimento futuras de uma despesa recorrente, respeitando data-fim (se houver)
// e um teto de segurança de 60 meses a partir do início (não dá pra gerar "para sempre").
// Mesma regra das parcelas (FinanceiroCore.somarMesesData): cada ocorrência conta da data inicial
// e dia que não existe no mês vira o último dia dele (31/01 → 28/02 → 31/03).
function gerarOcorrenciasRecorrentes(dataInicioStr, periodicidade, dataFimStr) {
    const passosMeses = { mensal: 1, bimestral: 2, trimestral: 3, semestral: 6, anual: 12 };
    const datas = [];
    const limiteMax = FinanceiroCore.somarMesesData(dataInicioStr, 60);
    const limite = dataFimStr && dataFimStr < limiteMax ? dataFimStr : limiteMax;
    const meses = passosMeses[periodicidade] || 1;
    for (let i = 0; i < 240; i++) {
        const atual = periodicidade === 'quinzenal' ? FinanceiroCore.somarDias(dataInicioStr, 15 * i) : FinanceiroCore.somarMesesData(dataInicioStr, meses * i);
        if (atual > limite) break;
        datas.push(atual);
    }
    return datas;
}

async function marcarCPPago(id) {
    if (!await exigirPermissao('financeiro.pagar', 'completo')) return;
    const cp = db.contas_pagar.find(x => x.id == id);
    if (!finAberta(cp)) return;
    const r = await abrirModalBaixa({
        titulo: 'Registrar pagamento',
        itens: [{ id: cp.id, descricao: cp.descricao, valor: cp.valor, marcado: true, conta_prevista: cp.conta_id != null ? cp.conta_id : null }],
        formaPadrao: cp.forma_pagamento || '',
        permiteCartao: false, permiteParcial: false
    });
    if (!r || !r.linhas.length) return;
    const baixa = baixarContasPagar(r.data, r.linhas);
    if (!baixa.ok) { await showAlert(baixa.erro, '⚠️'); return; }
    salvarERecarregar('Pagamento registrado!');
}

async function excluirCP(id) {
    if (!await exigirPermissao('financeiro.pagar', 'completo')) return;
    if (await _bloqueiaExclusaoCP(db.contas_pagar.filter(x => x.id == id))) return;
    if (!await showConfirm('Remover este lançamento a pagar?', '🗑️', 'Remover', 'Cancelar')) return;
    _finRegistrarExcluidos('cp', db.contas_pagar.filter(x => x.id == id));
    db.contas_pagar = db.contas_pagar.filter(x => x.id != id);
    salvarERecarregar('Lançamento removido.');
}

async function excluirGrupoCP(paiId) {
    if (!await exigirPermissao('financeiro.pagar', 'completo')) return;
    const grupo = db.contas_pagar.filter(x => x.lancamento_pai_id === paiId);
    if (!grupo.length) return;
    if (await _bloqueiaExclusaoCP(grupo)) return;
    if (!await showConfirm(`Remover todos os ${grupo.length} lançamentos deste grupo (parcelas ou recorrência)?\n\nEsta ação não pode ser desfeita.`, '🗑️', 'Remover grupo', 'Cancelar')) return;
    _finRegistrarExcluidos('cp', grupo);
    db.contas_pagar = db.contas_pagar.filter(x => x.lancamento_pai_id !== paiId);
    db.despesas_fixas = db.despesas_fixas.filter(x => x.id !== paiId);
    salvarERecarregar('Grupo removido.');
}

async function salvarDespesaFixa() {
    if (!await exigirPermissao('financeiro.fixas', 'completo')) return;
    const descricao = document.getElementById('df-descricao')?.value.trim();
    const valor = parseFloat(document.getElementById('df-valor')?.value) || 0;
    const dia = parseInt(document.getElementById('df-dia')?.value) || 1;
    const categoria = document.getElementById('df-categoria')?.value || 'outro';
    if (!descricao) { await showAlert('Informe a descrição da despesa.', '⚠️'); return; }
    if (!valor) { await showAlert('Informe o valor da despesa.', '⚠️'); return; }
    db.despesas_fixas.push({ id: Date.now(), descricao, valor, dia_vencimento: dia, categoria, categoria_id: FinCatCore.categoriaDoLegado({ categoria }, 'pagar'), ativo: true });
    salvarERecarregar('Despesa fixa cadastrada!');
}

async function excluirDespesaFixa(id) {
    if (!await exigirPermissao('financeiro.fixas', 'completo')) return;
    if (!await showConfirm('Remover esta despesa fixa recorrente?', '🗑️', 'Remover', 'Cancelar')) return;
    db.despesas_fixas = db.despesas_fixas.filter(x => x.id != id);
    salvarERecarregar('Despesa removida.');
}

async function gerarContasPagarDoMes() {
    if (!await exigirPermissao('financeiro.pagar', 'completo')) return;
    const hoje = new Date();
    const mes = String(hoje.getMonth() + 1).padStart(2, '0');
    const ano = hoje.getFullYear();
    let geradas = 0;
    db.despesas_fixas.filter(df => df.ativo && !df.periodicidade).forEach(df => {
        // Recorrencia criada no Lancamentos so vale a partir do mes do primeiro vencimento.
        if (df.data_inicio && `${ano}-${mes}` < String(df.data_inicio).slice(0, 7)) return;
        // Dia 29-31 vale o ultimo dia do mes quando ele nao existe (31 -> 28/29 em fevereiro).
        const dia = Math.min(Number(df.dia_vencimento) || 1, new Date(ano, Number(mes), 0).getDate());
        const vencStr = `${ano}-${mes}-${String(dia).padStart(2, '0')}`;
        const jaExiste = db.contas_pagar.some(cp => !cp.pedido_id && cp.descricao === df.descricao && cp.data_vencimento === vencStr)
            || db.contas_pagar.some(cp => cp.despesa_fixa_id != null && cp.despesa_fixa_id === df.id && String(cp.data_vencimento || '').slice(0, 7) === `${ano}-${mes}`);
        if (!jaExiste) {
            db.contas_pagar.push(finCompletarLancamento('cp', {
                id: Date.now() + geradas, pedido_id: null,
                tipo: 'fixo', categoria: df.categoria,
                ...(df.categoria_id ? { categoria_id: df.categoria_id } : {}),
                descricao: df.descricao, credor_nome: '', despesa_fixa_id: df.id,
                valor: df.valor, data_vencimento: vencStr,
                data_pagamento: null, status: 'Pendente',
                ...(df.categoria === 'imposto' ? { mes_referencia: _mesRefImposto(vencStr) } : {})
            }, { origem: 'recorrencia', mesOcorrencia: vencStr.slice(0, 7) }, 'Despesa fixa do mês'));
            geradas++;
        }
    });
    if (geradas) salvarERecarregar(`${geradas} despesa(s) gerada(s) para o mês!`);
    else await showAlert('Todas as despesas fixas do mês já foram geradas (ou nenhuma cadastrada).', 'ℹ️');
}

// --- CONTAS A PAGAR: menu "+ Nova Conta a Pagar" ---
function toggleMenuContaPagar(e) {
    e.stopPropagation();
    const dd = document.getElementById('cp-menu-dropdown');
    if (!dd) return;
    dd.style.display = dd.style.display === 'block' ? 'none' : 'block';
}
document.addEventListener('click', (e) => {
    const dd = document.getElementById('cp-menu-dropdown');
    if (dd && dd.style.display === 'block' && !dd.contains(e.target) && e.target.id !== 'cp-menu-btn') dd.style.display = 'none';
});

function abrirModalContaPagar(modo, manterAnexoPendente) {
    const dropdown = document.getElementById('cp-menu-dropdown');
    if (dropdown) dropdown.style.display = 'none';
    if (modo === 'arquivo') {
        abrirModalImportarNota();
        return;
    }
    if (!manterAnexoPendente) _anexoPendenteCP = null;
    const overlay = document.createElement('div');
    overlay.className = 'modal-overlay';
    overlay.innerHTML = `<div class="modal-box" style="max-width:640px">
        <div class="modal-header">
            <h3>Lançar Conta a Pagar</h3>
            <button class="modal-close" onclick="this.closest('.modal-overlay').remove()">×</button>
        </div>
        <div class="modal-body">
            <div class="grid">
                <div class="form-group" style="grid-column:span 2">
                    <label>Descrição <span style="color:#F43927">*</span></label>
                    <input type="text" id="cpm-descricao" placeholder="Ex: Compra de tecido, salário costureira…">
                </div>
                <div class="form-group">
                    <label>CNPJ do Fornecedor <span class="info-tag">opcional</span></label>
                    <input type="text" id="cpm-cnpj" placeholder="00.000.000/0000-00" maxlength="18" oninput="mascaraCNPJ(this); onCnpjContaPagarInput();">
                    <div id="cpm-cnpj-status" style="font-size:11px;margin-top:3px;min-height:14px"></div>
                </div>
                <div class="form-group">
                    <label>Credor / Fornecedor</label>
                    <input type="text" id="cpm-credor" placeholder="Nome do credor">
                </div>
                <div class="form-group">
                    <label>Valor (R$) <span style="color:#F43927">*</span></label>
                    <input type="text" inputmode="decimal" id="cpm-valor" placeholder="0,00">
                </div>
                <div class="form-group">
                    <label>Vencimento <span style="color:#F43927">*</span></label>
                    <input type="date" id="cpm-vencimento" oninput="atualizarMesRefImposto()">
                </div>
                <div class="form-group" style="grid-column:span 2">
                    <label>Nº da Nota ou Linha Digitável do Boleto <span class="info-tag">opcional</span></label>
                    <input type="text" id="cpm-doc" placeholder="Cole a linha digitável (boleto/convênio) ou digite o nº da nota" oninput="onDocContaPagarInput()">
                    <div id="cpm-doc-help" style="font-size:11px;margin-top:3px;color:#8F8F8F;min-height:14px"></div>
                </div>
            </div>
            <div style="display:flex;gap:24px;flex-wrap:wrap;margin:6px 0 14px;padding:12px 14px;background:var(--surface-2);border:1px solid var(--border);border-radius:8px">
                <div style="display:flex;align-items:center;gap:10px">
                    <label class="toggle-switch"><input type="checkbox" id="cpm-recorrente" onchange="onToggleRecorrenteCP()"><span class="toggle-slider"></span></label>
                    <span style="font-size:13px;font-weight:600">Recorrente?</span>
                </div>
                <div style="display:flex;align-items:center;gap:10px">
                    <label class="toggle-switch"><input type="checkbox" id="cpm-parcelado" onchange="onToggleParceladoCP()"><span class="toggle-slider"></span></label>
                    <span style="font-size:13px;font-weight:600">Parcelado?</span>
                </div>
            </div>
            <div id="cpm-recorrente-fields" class="grid" style="display:none">
                <div class="form-group">
                    <label>Periodicidade</label>
                    <select id="cpm-periodicidade">
                        <option value="mensal">Mensal</option>
                        <option value="quinzenal">Quinzenal</option>
                        <option value="bimestral">Bimestral</option>
                        <option value="trimestral">Trimestral</option>
                        <option value="semestral">Semestral</option>
                        <option value="anual">Anual</option>
                    </select>
                </div>
                <div class="form-group">
                    <label>Data Fim <span class="info-tag">vazio = sem fim (máx. 60 meses)</span></label>
                    <input type="date" id="cpm-data-fim">
                </div>
            </div>
            <div id="cpm-parcelado-fields" class="grid" style="display:none">
                <div class="form-group">
                    <label>Número de Parcelas</label>
                    <input type="number" id="cpm-parcelas" min="2" step="1" placeholder="Ex: 3">
                </div>
            </div>
            <div class="grid">
                <div class="form-group">
                    <label>Categoria</label>
                    <select id="cpm-categoria" onchange="atualizarMesRefImposto(true)">
                        ${_opcoesCategoria(CATEGORIAS_CONTA_PAGAR)}
                    </select>
                </div>
                <div class="form-group" id="cpm-mes-ref-grupo" style="display:none">
                    <label>Mês de referência <span class="info-tag">mês a que a guia se refere</span></label>
                    <input type="month" id="cpm-mes-ref" oninput="this.dataset.editado = '1'">
                </div>
                <div class="form-group">
                    <label>Vincular a Pedido</label>
                    <select id="cpm-pedido"></select>
                </div>
            </div>
        </div>
        <div style="display:flex;gap:10px;padding:16px 24px;border-top:1px solid var(--border)">
            <button class="btn btn-success" onclick="adicionarContaPagarManual()">Lançar Conta a Pagar</button>
            <button class="btn btn-outline" onclick="this.closest('.modal-overlay').remove()">Cancelar</button>
        </div>
    </div>`;
    document.body.appendChild(overlay);
    overlay.addEventListener('click', e => { if (e.target === overlay) overlay.remove(); });
    const pedSel = overlay.querySelector('#cpm-pedido');
    if (pedSel) pedSel.innerHTML = '<option value="">— Sem vínculo de pedido —</option>' +
        db.pedidos.filter(p => normalizarStatus(p.status) !== 'Orçamento')
        .map(p => `<option value="${p.id}">#${formatPedidoId(p.id)} ${escapeHtml(p.clienteNome || '')}</option>`).join('');
}

// Guia de imposto: mes de referencia = mes anterior ao vencimento (YYYY-MM).
function _mesRefImposto(vencimento) {
    return /^\d{4}-\d{2}/.test(vencimento || '') ? ResultadoCore.somarMeses(String(vencimento).slice(0, 7), -1) : '';
}
// Mostra o campo so para Imposto e o recalcula pelo vencimento, salvo se o usuario o editou.
function atualizarMesRefImposto(mudouCategoria) {
    const grupo = document.getElementById('cpm-mes-ref-grupo'), campo = document.getElementById('cpm-mes-ref');
    if (!grupo || !campo) return;
    const imposto = document.getElementById('cpm-categoria')?.value === 'imposto';
    grupo.style.display = imposto ? '' : 'none';
    if (!imposto) { campo.value = ''; delete campo.dataset.editado; return; }
    if (campo.dataset.editado !== '1' || !campo.value) {
        campo.value = _mesRefImposto(document.getElementById('cpm-vencimento')?.value);
        if (!campo.value) delete campo.dataset.editado;
    }
}

function onToggleRecorrenteCP() {
    const chkR = document.getElementById('cpm-recorrente'), chkP = document.getElementById('cpm-parcelado');
    const on = chkR?.checked;
    document.getElementById('cpm-recorrente-fields').style.display = on ? 'grid' : 'none';
    if (on && chkP?.checked) { chkP.checked = false; document.getElementById('cpm-parcelado-fields').style.display = 'none'; }
}
function onToggleParceladoCP() {
    const chkP = document.getElementById('cpm-parcelado'), chkR = document.getElementById('cpm-recorrente');
    const on = chkP?.checked;
    document.getElementById('cpm-parcelado-fields').style.display = on ? 'grid' : 'none';
    if (on && chkR?.checked) { chkR.checked = false; document.getElementById('cpm-recorrente-fields').style.display = 'none'; }
}

async function onCnpjContaPagarInput() {
    const el = document.getElementById('cpm-cnpj');
    const statusEl = document.getElementById('cpm-cnpj-status');
    if (!el || !statusEl) return;
    const digits = el.value.replace(/\D/g, '');
    if (digits.length !== 14) { statusEl.textContent = ''; return; }
    if (!validarCNPJ(digits)) { statusEl.innerHTML = '<span style="color:#F43927">⚠️ CNPJ inválido — confira os dígitos.</span>'; return; }
    statusEl.innerHTML = '<span style="color:#8F8F8F">⏳ Consultando...</span>';
    try {
        const res = await fetch(`https://publica.cnpj.ws/cnpj/${digits}`);
        if (!res.ok) throw new Error(res.status === 404 ? 'nao_encontrado' : 'erro');
        const d = await res.json();
        const est = d.estabelecimento || {};
        const credorEl = document.getElementById('cpm-credor');
        if (credorEl) credorEl.value = est.nome_fantasia || d.razao_social || credorEl.value;
        statusEl.innerHTML = '<span style="color:var(--primary-text)">✅ Fornecedor encontrado e preenchido.</span>';
    } catch (e) {
        statusEl.innerHTML = e.message === 'nao_encontrado'
            ? '<span style="color:#8F8F8F">CNPJ não encontrado — preencha o credor manualmente.</span>'
            : '<span style="color:#8F8F8F">Não foi possível consultar agora — preencha o credor manualmente.</span>';
    }
}

function onDocContaPagarInput() {
    const raw = document.getElementById('cpm-doc')?.value || '';
    const helpEl = document.getElementById('cpm-doc-help');
    if (!helpEl) return;
    const digits = raw.replace(/\D/g, '');
    if (!digits) { helpEl.textContent = ''; return; }

    if (digits.length === 44) {
        helpEl.style.color = '#8F8F8F';
        helpEl.textContent = 'Chave de acesso de NF-e detectada (44 dígitos). A busca automática por chave completa ainda não está disponível — use "Exportar nota/boleto" (em breve) ou preencha manualmente.';
        return;
    }
    if (digits.length === 47 || digits.length === 48) {
        const res = decodificarLinhaDigitavel(digits);
        if (res.ok) {
            if (res.valor) document.getElementById('cpm-valor').value = res.valor.toFixed(2).replace('.', ',');
            if (res.vencimento) document.getElementById('cpm-vencimento').value = res.vencimento;
            const descEl = document.getElementById('cpm-descricao');
            if (descEl && !descEl.value.trim()) descEl.value = res.tipo === 'boleto' ? `Boleto ${res.banco}` : 'Conta de consumo (convênio)';
            helpEl.style.color = 'var(--primary-text)';
            helpEl.textContent = res.tipo === 'boleto'
                ? `Boleto identificado — ${res.banco}${res.valor ? `, valor R$ ${res.valor.toFixed(2)}` : ''}${res.vencimento ? `, vencimento ${new Date(res.vencimento + 'T12:00:00').toLocaleDateString('pt-BR')}` : ''}.`
                : `Linha de convênio identificada${res.valorReferencia ? ' (valor de referência — confirme o valor real a pagar)' : ''}. Este tipo de linha não codifica vencimento — informe manualmente.`;
        } else if (res.motivo) {
            helpEl.style.color = '#F43927';
            helpEl.textContent = res.motivo;
        }
        return;
    }
    if (digits.length >= 6 && digits.length <= 20) {
        const cnpjDigits = (document.getElementById('cpm-cnpj')?.value || '').replace(/\D/g, '');
        const achado = buscarNumeroDocumentoHistorico(digits, cnpjDigits);
        if (achado) {
            const credorEl = document.getElementById('cpm-credor');
            const valorEl = document.getElementById('cpm-valor');
            if (credorEl && !credorEl.value.trim()) credorEl.value = achado.credor_nome || '';
            if (valorEl && !valorEl.value) valorEl.value = achado.valor.toFixed(2).replace('.', ',');
            helpEl.style.color = 'var(--primary-text)';
            helpEl.textContent = `Encontrado no histórico: lançamento anterior de "${achado.credor_nome || '—'}" com este número de documento.`;
        } else {
            helpEl.style.color = '#8F8F8F';
            helpEl.textContent = 'Busca automática só pelo número da nota não é garantida — não existe API pública gratuita para isso. Use "Exportar nota/boleto" ou informe a chave de acesso completa (44 dígitos).';
        }
        return;
    }
    helpEl.textContent = '';
}

async function adicionarContaPagarManual() {
    if (!await exigirPermissao('financeiro.pagar', 'completo')) return;
    const descricao   = document.getElementById('cpm-descricao')?.value.trim();
    const cnpjFornecedor = document.getElementById('cpm-cnpj')?.value.trim() || '';
    const credor      = document.getElementById('cpm-credor')?.value.trim() || '';
    const valor       = _valorDigitadoBaixa(document.getElementById('cpm-valor')?.value, 0);
    const vencimento  = document.getElementById('cpm-vencimento')?.value;
    const categoria   = document.getElementById('cpm-categoria')?.value || 'outro';
    const mesRefDigitado = document.getElementById('cpm-mes-ref')?.value || '';
    const pedidoId    = document.getElementById('cpm-pedido')?.value || '';
    const docRaw      = document.getElementById('cpm-doc')?.value.trim() || '';
    const docDigits   = docRaw.replace(/\D/g, '');
    const ehLinhaDigitavel = docDigits.length === 47 || docDigits.length === 48;
    const recorrente  = document.getElementById('cpm-recorrente')?.checked || false;
    const periodicidade = document.getElementById('cpm-periodicidade')?.value || 'mensal';
    const dataFim     = document.getElementById('cpm-data-fim')?.value || '';
    const parcelado   = document.getElementById('cpm-parcelado')?.checked || false;
    const numParcelas = parseInt(document.getElementById('cpm-parcelas')?.value) || 1;

    if (!descricao)  { await showAlert('Informe a descrição.', '⚠️'); return; }
    if (!(valor > 0)) { await showAlert('Informe o valor.', '⚠️'); return; }
    if (!vencimento) { await showAlert('Informe a data de vencimento.', '⚠️'); return; }
    if (cnpjFornecedor.replace(/\D/g, '').length === 14 && !validarCNPJ(cnpjFornecedor)) {
        if (!await showConfirm('O CNPJ informado parece inválido (dígito verificador não confere). Deseja lançar mesmo assim?', '⚠️', 'Lançar mesmo assim', 'Corrigir')) return;
    }
    if (parcelado && numParcelas < 2) { await showAlert('Informe um número de parcelas maior que 1.', '⚠️'); return; }

    const chaveAcesso = _anexoPendenteCP?.chaveAcesso || null;
    const numeroDocumento = (!ehLinhaDigitavel && docRaw) ? docRaw : null;
    let tipoLancamento = 'manual';
    if (ehLinhaDigitavel) tipoLancamento = 'boleto';
    else if (chaveAcesso || numeroDocumento) tipoLancamento = 'nota';

    // Nota/boleto importado do mesmo fornecedor e valor de uma compra ja lancada:
    // oferece juntar na conta existente em vez de pagar duas vezes.
    if (tipoLancamento !== 'manual' && !parcelado && !recorrente) {
        const dup = FinanceiroCore.acharContaDuplicadaNota(db.contas_pagar, { cnpj: cnpjFornecedor, valor });
        if (dup) {
            const escolha = await showEscolha(
                `Já existe uma conta a pagar desta compra (${dup.descricao}, R$ ${Number(dup.valor).toFixed(2)}). Esta nota é a mesma compra?`,
                '🔗',
                [{ rotulo: 'Vincular à conta existente', valor: 'vincular', destaque: true }, { rotulo: 'Lançar como nova conta', valor: 'nova' }]);
            if (!escolha) return;
            if (escolha === 'vincular') {
                const grupo = dup.lancamento_pai_id != null
                    ? db.contas_pagar.filter(x => x.lancamento_pai_id == dup.lancamento_pai_id && x.pedido_compra_id)
                    : [dup];
                grupo.forEach(c => {
                    c.tipo_lancamento = tipoLancamento;
                    if (chaveAcesso) c.chave_acesso = chaveAcesso;
                    if (numeroDocumento) c.numero_documento = numeroDocumento;
                    if (ehLinhaDigitavel) c.linha_digitavel = docDigits;
                });
                if (_anexoPendenteCP) {
                    const alvo = grupo[0];
                    alvo.arquivo_anexo_url = _anexoPendenteCP.dataUrl || null;
                    alvo.arquivo_anexo_nome = _anexoPendenteCP.nome || null;
                    alvo.arquivo_anexo_tipo = _anexoPendenteCP.tipo || null;
                }
                _anexoPendenteCP = null;
                salvarERecarregar('Nota vinculada à conta existente!');
                return;
            }
        }
    }

    // Imposto: mes de referencia de cada guia. Parcelas e recorrencias mantem o
    // mesmo deslocamento (em meses) entre vencimento e referencia da primeira.
    const mesRefPadrao = _mesRefImposto(vencimento);
    const mesRefBase = categoria === 'imposto' ? (mesRefDigitado || mesRefPadrao) : '';
    const mesRefDe = venc => {
        if (categoria !== 'imposto') return {};
        const [a, b] = [mesRefBase, mesRefPadrao].map(m => Number(m.slice(0, 4)) * 12 + Number(m.slice(5, 7)));
        return { mes_referencia: ResultadoCore.somarMeses(_mesRefImposto(venc), a - b) };
    };
    const camposDoc = {
        cnpj_fornecedor: cnpjFornecedor || null,
        linha_digitavel: ehLinhaDigitavel ? docDigits : null,
        numero_documento: numeroDocumento,
        chave_acesso: chaveAcesso,
        tipo_lancamento: tipoLancamento,
        arquivo_anexo_url: _anexoPendenteCP?.dataUrl || null,
        arquivo_anexo_nome: _anexoPendenteCP?.nome || null,
        arquivo_anexo_tipo: _anexoPendenteCP?.tipo || null,
    };
    _anexoPendenteCP = null;
    const detalheCriado = tipoLancamento === 'nota' ? 'Lançado de nota importada' : tipoLancamento === 'boleto' ? 'Lançado de boleto' : 'Lançamento manual';

    if (parcelado) {
        const valorParcela = Math.round((valor / numParcelas) * 100) / 100;
        const paiId = Date.now();
        let somaLancada = 0;
        for (let i = 0; i < numParcelas; i++) {
            // Mesma regra do simulador: dia que nao existe no mes vira o ultimo dia dele (31/01 -> 28/02 -> 31/03).
            const vencParcela = FinanceiroCore.somarMesesData(vencimento, i);
            const isUltima = i === numParcelas - 1;
            const valorFinal = isUltima ? Math.round((valor - somaLancada) * 100) / 100 : valorParcela;
            somaLancada += valorFinal;
            db.contas_pagar.push(finCompletarLancamento('cp', {
                id: paiId + i + 1, pedido_id: pedidoId ? parseInt(pedidoId) : null,
                tipo: 'variavel', categoria, descricao: `${descricao} (parcela ${i + 1}/${numParcelas})`,
                credor_nome: credor, valor: valorFinal, data_vencimento: vencParcela,
                data_pagamento: null, status: 'Pendente',
                lancamento_pai_id: paiId, parcelado: true, numero_parcelas: numParcelas, parcela_atual: i + 1,
                ...mesRefDe(vencParcela), ...camposDoc
            }, null, detalheCriado));
        }
        salvarERecarregar(`${numParcelas} parcelas lançadas!`);
        return;
    }

    if (recorrente) {
        const dfId = Date.now();
        db.despesas_fixas.push({
            id: dfId, descricao, valor, dia_vencimento: new Date(vencimento + 'T12:00:00').getDate(),
            categoria, categoria_id: FinCatCore.categoriaDoLegado({ categoria }, 'pagar'), ativo: true, periodicidade, data_inicio: vencimento, data_fim: dataFim || null,
            credor_nome: credor, cnpj_fornecedor: cnpjFornecedor || null
        });
        const ocorrencias = gerarOcorrenciasRecorrentes(vencimento, periodicidade, dataFim);
        ocorrencias.forEach((venc, i) => {
            db.contas_pagar.push(finCompletarLancamento('cp', {
                id: dfId + i + 1, pedido_id: pedidoId ? parseInt(pedidoId) : null,
                tipo: 'fixo', categoria, descricao, credor_nome: credor,
                valor, data_vencimento: venc, data_pagamento: null, status: 'Pendente',
                lancamento_pai_id: dfId, recorrente: true, periodicidade,
                ...mesRefDe(venc), ...camposDoc
            }, { origem: 'recorrencia', mesOcorrencia: venc.slice(0, 7) }, 'Recorrência: ' + descricao));
        });
        salvarERecarregar(`Despesa recorrente cadastrada — ${ocorrencias.length} lançamento(s) gerado(s)!`);
        return;
    }

    db.contas_pagar.push(finCompletarLancamento('cp', {
        id: Date.now(), pedido_id: pedidoId ? parseInt(pedidoId) : null,
        tipo: 'variavel', categoria, descricao, credor_nome: credor,
        valor, data_vencimento: vencimento, data_pagamento: null, status: 'Pendente',
        ...mesRefDe(vencimento), ...camposDoc
    }, null, detalheCriado));
    salvarERecarregar('Conta a pagar registrada!');
}

// --- CONTAS A PAGAR: importar nota/boleto (XML de NF-e e PDF com texto) ---
// Guarda o anexo lido enquanto o usuário revisa os campos extraídos no modal manual;
// só vira parte do lançamento de fato quando o usuário confirma em "Lançar Conta a Pagar".
let _anexoPendenteCP = null;
let _pdfJsPronto = null; // Promise compartilhada p/ não carregar a lib mais de uma vez

function abrirModalImportarNota() {
    const overlay = document.createElement('div');
    overlay.className = 'modal-overlay';
    overlay.innerHTML = `<div class="modal-box" style="max-width:520px">
        <div class="modal-header">
            <h3>Exportar Nota / Boleto</h3>
            <button class="modal-close" onclick="this.closest('.modal-overlay').remove()">×</button>
        </div>
        <div class="modal-body">
            <p style="font-size:12.5px;color:#8F8F8F;margin-bottom:14px">Envie o arquivo original — os campos serão extraídos automaticamente quando possível. Você sempre revisa e confirma antes de lançar.</p>
            <div id="cpi-dropzone" style="border:2px dashed var(--border);border-radius:10px;padding:36px 20px;text-align:center;cursor:pointer;transition:border-color .2s,background .2s">
                <div style="font-size:32px;margin-bottom:8px">📎</div>
                <div style="font-weight:600;color:var(--dark);margin-bottom:4px">Clique para selecionar ou arraste o arquivo aqui</div>
                <div style="font-size:12px;color:#8F8F8F">PDF, XML, JPG ou PNG · Máx. 4 MB</div>
            </div>
            <input type="file" id="cpi-file-input" accept=".pdf,.xml,.jpg,.jpeg,.png" style="display:none">
            <div id="cpi-status" style="margin-top:14px;font-size:13px"></div>
        </div>
    </div>`;
    document.body.appendChild(overlay);
    overlay.addEventListener('click', e => { if (e.target === overlay) overlay.remove(); });

    const dz = overlay.querySelector('#cpi-dropzone');
    const input = overlay.querySelector('#cpi-file-input');
    dz.addEventListener('click', () => input.click());
    input.addEventListener('change', () => onArquivoContaPagarSelecionado(input.files?.[0]));
    ['dragover', 'dragleave', 'drop'].forEach(evt => dz.addEventListener(evt, e => e.preventDefault()));
    dz.addEventListener('dragover', () => { dz.style.borderColor = 'var(--primary)'; dz.style.background = 'var(--info-bg)'; });
    dz.addEventListener('dragleave', () => { dz.style.borderColor = 'var(--border)'; dz.style.background = ''; });
    dz.addEventListener('drop', e => {
        dz.style.borderColor = 'var(--border)'; dz.style.background = '';
        const file = e.dataTransfer?.files?.[0];
        if (file) onArquivoContaPagarSelecionado(file);
    });
}

function _lerArquivoComoDataUrl(file) {
    return new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.onload = () => resolve(reader.result);
        reader.onerror = () => reject(new Error('Falha ao ler o arquivo.'));
        reader.readAsDataURL(file);
    });
}

async function onArquivoContaPagarSelecionado(file) {
    if (!file) return;
    const statusEl = document.getElementById('cpi-status');
    const MAX_BYTES = 4 * 1024 * 1024;
    if (file.size > MAX_BYTES) {
        if (statusEl) statusEl.innerHTML = '<span style="color:#F43927">⚠️ Arquivo muito grande (máx. 4 MB) — o navegador guarda os anexos junto com o resto dos dados do sistema.</span>';
        return;
    }
    const ext = (file.name.split('.').pop() || '').toLowerCase();
    if (!['pdf', 'xml', 'jpg', 'jpeg', 'png'].includes(ext)) {
        if (statusEl) statusEl.innerHTML = '<span style="color:#F43927">⚠️ Formato não suportado. Envie PDF, XML, JPG ou PNG.</span>';
        return;
    }
    if (statusEl) statusEl.innerHTML = '<span style="color:#8F8F8F">⏳ Lendo arquivo...</span>';

    let dataUrl = null;
    try { dataUrl = await _lerArquivoComoDataUrl(file); }
    catch { if (statusEl) statusEl.innerHTML = '<span style="color:#F43927">⚠️ Não foi possível ler o arquivo.</span>'; return; }

    const mostrarProgressoOcr = pct => {
        if (statusEl) statusEl.innerHTML = `<span style="color:#8F8F8F">🔍 Lendo por OCR (pode levar alguns segundos)... ${pct}%</span>`;
    };

    let extraidos = { ok: false, motivo: 'erro' };
    try {
        if (ext === 'xml') {
            extraidos = await _extrairDadosXmlNFe(file);
        } else if (ext === 'pdf') {
            extraidos = await _extrairDadosPdf(file);
            if (!extraidos.ok && extraidos.motivo === 'pdf_sem_texto') {
                extraidos = await _extrairDadosPdfEscaneadoOcr(file, mostrarProgressoOcr);
            }
        } else {
            extraidos = await _extrairDadosImagemOcr(dataUrl, mostrarProgressoOcr);
        }
    } catch (err) {
        extraidos = { ok: false, motivo: 'erro', detalhe: err.message };
    }

    if (statusEl) statusEl.innerHTML = extraidos.ok
        ? '<span style="color:var(--primary-text)">✅ Dados extraídos! Abrindo para revisão...</span>'
        : '<span style="color:#8F8F8F">Não foi possível extrair automaticamente. Abrindo para preenchimento manual...</span>';

    await new Promise(r => setTimeout(r, 500));
    document.querySelectorAll('.modal-overlay').forEach(o => o.remove());

    _anexoPendenteCP = { nome: file.name, tipo: file.type || ext, dataUrl, chaveAcesso: extraidos.chaveAcesso || null };
    abrirModalContaPagar('manual', true);
    _preencherModalComExtracao(extraidos, file.name);
}

function _preencherModalComExtracao(dados, nomeArquivo) {
    const set = (id, val) => { if (val === undefined || val === null || val === '') return; const el = document.getElementById(id); if (el) el.value = val; };
    if (dados.ok) {
        if (dados.cnpj) { set('cpm-cnpj', dados.cnpj); const el = document.getElementById('cpm-cnpj'); if (el) mascaraCNPJ(el); }
        set('cpm-credor', dados.credor || '');
        if (dados.valor != null) set('cpm-valor', dados.valor.toFixed(2).replace('.', ','));
        set('cpm-vencimento', dados.vencimento || '');
        set('cpm-descricao', dados.credor ? `Nota/Boleto ${dados.credor}` : (dados.tipo === 'nota' ? 'Nota fiscal importada' : 'Boleto importado'));
        const docEl = document.getElementById('cpm-doc');
        if (docEl) docEl.value = dados.linhaDigitavel || dados.numeroDocumento || dados.chaveAcesso || '';
    } else {
        set('cpm-descricao', `Documento importado — ${nomeArquivo}`);
    }
    const helpEl = document.getElementById('cpm-doc-help');
    if (!helpEl) return;
    if (dados.ok) {
        helpEl.style.color = 'var(--primary-text)';
        helpEl.textContent = `Preenchido a partir de "${nomeArquivo}". Revise os campos antes de lançar.`;
        if (dados.dupInfo) helpEl.textContent += ` Esta nota possui ${dados.dupInfo} parcela(s) de cobrança — marque "Parcelado?" abaixo se quiser lançar todas.`;
    } else if (dados.motivo === 'ocr_falhou') {
        helpEl.style.color = '#F43927';
        helpEl.textContent = `Não foi possível processar a leitura automática (OCR)${dados.detalhe ? ' — ' + dados.detalhe : ''}. O arquivo foi anexado; preencha manualmente.`;
    } else if (dados.motivo === 'ocr_sem_texto') {
        helpEl.style.color = '#8F8F8F';
        helpEl.textContent = 'Não conseguimos reconhecer texto neste arquivo (qualidade baixa ou imagem ilegível). O arquivo foi anexado; preencha manualmente.';
    } else if (dados.motivo === 'ocr_sem_campos') {
        helpEl.style.color = '#8F8F8F';
        helpEl.textContent = 'A leitura automática por OCR não encontrou CNPJ, valor ou linha digitável neste documento — a extração por OCR é aproximada e nem sempre reconhece todos os documentos. O arquivo foi anexado; confira e preencha manualmente.';
    } else if (dados.motivo === 'xml_invalido' || dados.motivo === 'xml_sem_nfe') {
        helpEl.style.color = '#F43927';
        helpEl.textContent = 'Este XML não parece ser uma NF-e válida. O arquivo foi anexado; preencha manualmente.';
    } else {
        helpEl.style.color = '#F43927';
        helpEl.textContent = `Não foi possível ler os dados automaticamente${dados.detalhe ? ' (' + dados.detalhe + ')' : ''}. O arquivo foi anexado; preencha manualmente.`;
    }
}

// --- Extração: XML de NF-e ---
async function _extrairDadosXmlNFe(file) {
    const texto = await file.text();
    const doc = new DOMParser().parseFromString(texto, 'application/xml');
    if (doc.querySelector('parsererror')) return { ok: false, motivo: 'xml_invalido' };
    const infNFe = doc.querySelector('infNFe');
    if (!infNFe) return { ok: false, motivo: 'xml_sem_nfe' };
    const get = sel => infNFe.querySelector(sel)?.textContent?.trim() || '';

    const cnpj = get('emit > CNPJ');
    const credor = get('emit > xFant') || get('emit > xNome');
    const valorStr = get('total > ICMSTot > vNF');
    const valor = valorStr ? parseFloat(valorStr) : null;
    const numeroDocumento = get('ide > nNF');

    let chaveAcesso = (infNFe.getAttribute('Id') || '').replace(/^NFe/i, '');
    if (!/^\d{44}$/.test(chaveAcesso)) chaveAcesso = doc.querySelector('protNFe infProt chNFe')?.textContent?.trim() || '';

    const duplicatas = Array.from(infNFe.querySelectorAll('cobr > dup'));
    let vencimento = duplicatas[0]?.querySelector('dVenc')?.textContent?.trim() || '';
    if (!vencimento) vencimento = (get('ide > dhEmi') || get('ide > dEmi')).slice(0, 10);

    if (!cnpj && !valor) return { ok: false, motivo: 'xml_sem_campos' };
    return {
        ok: true, tipo: 'nota', cnpj: cnpj || null, credor: credor || null, valor, vencimento: vencimento || null,
        numeroDocumento: numeroDocumento || null, chaveAcesso: chaveAcesso || null,
        dupInfo: duplicatas.length > 1 ? duplicatas.length : null,
    };
}

// --- Extração: PDF com camada de texto (boleto ou DANFE) ---
async function _garantirPdfJs() {
    if (window.pdfjsLib) return;
    if (!_pdfJsPronto) {
        _pdfJsPronto = new Promise((resolve, reject) => {
            const s = document.createElement('script');
            s.src = 'https://cdn.jsdelivr.net/npm/pdfjs-dist@3.11.174/build/pdf.min.js';
            s.onload = resolve;
            s.onerror = () => reject(new Error('Não foi possível carregar o leitor de PDF — verifique sua conexão.'));
            document.head.appendChild(s);
        }).then(() => {
            window.pdfjsLib.GlobalWorkerOptions.workerSrc = 'https://cdn.jsdelivr.net/npm/pdfjs-dist@3.11.174/build/pdf.worker.min.js';
        });
    }
    await _pdfJsPronto;
}

async function _extrairTextoPdf(file) {
    await _garantirPdfJs();
    const buf = await file.arrayBuffer();
    const pdf = await window.pdfjsLib.getDocument({ data: buf }).promise;
    let texto = '';
    for (let i = 1; i <= pdf.numPages; i++) {
        const pagina = await pdf.getPage(i);
        const conteudo = await pagina.getTextContent();
        texto += conteudo.items.map(it => it.str).join(' ') + '\n';
    }
    return texto;
}

// Extrai os campos (linha digitável, chave de acesso, CNPJ, valor) de um texto já
// obtido por qualquer via (camada de texto do PDF OU saída de OCR). Compartilhado
// entre o caminho de PDF-com-texto e os caminhos de OCR (imagem e PDF escaneado).
async function _extrairCamposGenericos(texto) {
    if (!texto || texto.replace(/\s/g, '').length < 10) return { ok: false, motivo: 'sem_texto' };

    // 1) linha digitável (boleto bancário ou convênio) em qualquer lugar do texto.
    // Janela generosa: alguns PDFs (ex.: quando o campo usa letter-spacing p/ alinhamento
    // visual) fazem o pdf.js extrair um espaço entre CADA dígito, dobrando o tamanho do trecho.
    const candidatosLinha = texto.match(/\d[\d.\s]{35,200}\d/g) || [];
    for (const cand of candidatosLinha) {
        const digitos = cand.replace(/\D/g, '');
        if (digitos.length === 47 || digitos.length === 48) {
            const dec = decodificarLinhaDigitavel(digitos);
            if (dec.ok) return { ok: true, tipo: 'boleto', valor: dec.valor, vencimento: dec.vencimento, linhaDigitavel: digitos, credor: dec.banco ? `Boleto ${dec.banco}`.replace('Boleto ', '') : null, cnpj: null };
        }
    }

    // 2) chave de acesso de NF-e (44 dígitos) — indica DANFE (mesma observação da janela acima)
    let chaveAcesso = null;
    for (const cand of (texto.match(/\d[\d.\s]{40,180}\d/g) || [])) {
        const d = cand.replace(/\D/g, '');
        if (d.length === 44) { chaveAcesso = d; break; }
    }

    // 3) CNPJ do emitente — se achar, consulta a mesma API pública já usada no lançamento manual
    let cnpj = null, credor = null;
    const cnpjMatch = texto.match(/\d{2}[.\s]?\d{3}[.\s]?\d{3}[\/\s]?\d{4}[-\s]?\d{2}/);
    if (cnpjMatch) {
        const digitos = cnpjMatch[0].replace(/\D/g, '');
        if (validarCNPJ(digitos)) {
            cnpj = digitos;
            try {
                const res = await fetch(`https://publica.cnpj.ws/cnpj/${digitos}`);
                if (res.ok) { const d = await res.json(); credor = d.estabelecimento?.nome_fantasia || d.razao_social || null; }
            } catch { /* segue sem nome — usuário preenche */ }
        }
    }

    // 4) valor em reais no texto (ex.: "R$ 1.234,56") — só usado se não veio de linha digitável
    let valor = null;
    const valorMatch = texto.match(/R\$\s*([\d.]+,\d{2})/);
    if (valorMatch) valor = parseFloat(valorMatch[1].replace(/\./g, '').replace(',', '.'));

    if (!cnpj && !valor && !chaveAcesso) return { ok: false, motivo: 'sem_campos' };
    return { ok: true, tipo: chaveAcesso ? 'nota' : 'boleto', cnpj, credor, valor, vencimento: null, chaveAcesso };
}

async function _extrairDadosPdf(file) {
    const texto = await _extrairTextoPdf(file);
    const r = await _extrairCamposGenericos(texto);
    if (!r.ok && r.motivo === 'sem_texto') return { ok: false, motivo: 'pdf_sem_texto' };
    if (!r.ok && r.motivo === 'sem_campos') return { ok: false, motivo: 'pdf_sem_campos' };
    return r;
}

// --- Extração: OCR (Tesseract.js) para imagens e PDFs escaneados sem camada de texto ---
let _tesseractPronto = null;
async function _garantirTesseract() {
    if (window.Tesseract) return;
    if (!_tesseractPronto) {
        _tesseractPronto = new Promise((resolve, reject) => {
            const s = document.createElement('script');
            s.src = 'https://cdn.jsdelivr.net/npm/tesseract.js@5.1.1/dist/tesseract.min.js';
            s.onload = resolve;
            s.onerror = () => reject(new Error('Não foi possível carregar o leitor de OCR — verifique sua conexão.'));
            document.head.appendChild(s);
        });
    }
    await _tesseractPronto;
}

// Roda OCR sobre uma imagem (data URL, <canvas> ou File/Blob) e devolve o texto reconhecido.
async function _ocrImagem(fonte, onProgresso) {
    await _garantirTesseract();
    const worker = await window.Tesseract.createWorker('por', 1, {
        logger: m => { if (onProgresso && m.status === 'recognizing text') onProgresso(Math.round((m.progress || 0) * 100)); }
    });
    try {
        const { data } = await worker.recognize(fonte);
        return data.text || '';
    } finally {
        await worker.terminate();
    }
}

// Renderiza as páginas de um PDF (sem camada de texto) como canvases, para servir de entrada ao OCR.
// Limitado às 3 primeiras páginas — boletos/notas cabem nisso e o custo de OCR cresce rápido por página.
async function _renderizarPaginasPdfComoImagens(file) {
    await _garantirPdfJs();
    const buf = await file.arrayBuffer();
    const pdf = await window.pdfjsLib.getDocument({ data: buf }).promise;
    const canvases = [];
    const maxPaginas = Math.min(pdf.numPages, 3);
    for (let i = 1; i <= maxPaginas; i++) {
        const pagina = await pdf.getPage(i);
        const viewport = pagina.getViewport({ scale: 2 }); // resolução maior ajuda a precisão do OCR
        const canvas = document.createElement('canvas');
        canvas.width = viewport.width; canvas.height = viewport.height;
        await pagina.render({ canvasContext: canvas.getContext('2d'), viewport }).promise;
        canvases.push(canvas);
    }
    return canvases;
}

async function _extrairDadosImagemOcr(dataUrl, onProgresso) {
    let texto;
    try { texto = await _ocrImagem(dataUrl, onProgresso); }
    catch (e) { return { ok: false, motivo: 'ocr_falhou', detalhe: e.message }; }
    const r = await _extrairCamposGenericos(texto);
    if (!r.ok && r.motivo === 'sem_texto') return { ok: false, motivo: 'ocr_sem_texto' };
    if (!r.ok && r.motivo === 'sem_campos') return { ok: false, motivo: 'ocr_sem_campos' };
    return r;
}

async function _extrairDadosPdfEscaneadoOcr(file, onProgresso) {
    let canvases;
    try { canvases = await _renderizarPaginasPdfComoImagens(file); }
    catch (e) { return { ok: false, motivo: 'ocr_falhou', detalhe: e.message }; }
    let textoTotal = '';
    for (let i = 0; i < canvases.length; i++) {
        const texto = await _ocrImagem(canvases[i], pct => onProgresso && onProgresso(Math.round((i + pct / 100) / canvases.length * 100)));
        textoTotal += texto + '\n';
    }
    const r = await _extrairCamposGenericos(textoTotal);
    if (!r.ok && r.motivo === 'sem_texto') return { ok: false, motivo: 'ocr_sem_texto' };
    if (!r.ok && r.motivo === 'sem_campos') return { ok: false, motivo: 'ocr_sem_campos' };
    return r;
}

// --- Visualizar anexo original de um lançamento (auditoria) ---
function verAnexoCP(id) {
    const cp = db.contas_pagar.find(x => x.id == id);
    if (!cp || !cp.arquivo_anexo_url) return;
    const tipo = cp.arquivo_anexo_tipo || '';
    if (tipo.includes('pdf') || tipo.startsWith('image/')) {
        const w = window.open('', '_blank');
        if (!w) { toast('Permita pop-ups para visualizar o anexo.', 'info'); return; }
        const nome = escapeHtml(cp.arquivo_anexo_nome || 'Anexo');
        w.document.write(tipo.includes('pdf')
            ? `<title>${nome}</title><embed src="${cp.arquivo_anexo_url}" type="application/pdf" style="width:100%;height:100vh;border:none">`
            : `<title>${nome}</title><body style="margin:0;background:#111;display:flex;align-items:center;justify-content:center;height:100vh"><img src="${cp.arquivo_anexo_url}" style="max-width:100%;max-height:100vh"></body>`);
    } else {
        const a = document.createElement('a');
        a.href = cp.arquivo_anexo_url; a.download = cp.arquivo_anexo_nome || 'anexo';
        document.body.appendChild(a); a.click(); a.remove();
    }
}

// --- FINANCEIRO: ESTADO E HELPERS ---
let _finPeriodo = 'mes';
let _finDataIni = '', _finDataFim = '';
let _finMetas = {};
let _chartFinCombo = null, _chartFinRec = null, _chartFinDesp = null;
let _chartFinEvolucao = null, _chartFinAging = null, _chartFinTopClientes = null, _chartFinFunil = null;
let _chartFinProjecao = null;
let _finProjDias = 30;
let _finSortRec = { col: 'venc', dir: 1 };
let _finSortPag = { col: 'venc', dir: 1 };

function setFinProjPeriodo(dias) {
    _finProjDias = dias;
    renderDashboardFinanceiro();
}

function toggleFinMetaEdit() {
    const row = document.getElementById('fin-meta-edit-row');
    if (row) row.style.display = row.style.display === 'none' ? 'flex' : 'none';
}

function toggleFinIndicadores() {
    const aberto = localStorage.getItem('sc_fin_indicadores_abertos') === 'true';
    localStorage.setItem('sc_fin_indicadores_abertos', aberto ? 'false' : 'true');
    aplicarEstadoFinAccordion();
}

function aplicarEstadoFinAccordion() {
    const el = document.getElementById('fin-accordion-indicadores');
    if (!el) return;
    const aberto = localStorage.getItem('sc_fin_indicadores_abertos') === 'true';
    el.classList.toggle('open', aberto);
}

const _finCenterTextPlugin = {
    id: 'finCenterText',
    afterDraw(chart) {
        const cfg = chart.options.plugins?.centerText;
        if (!cfg?.text) return;
        const { ctx, chartArea } = chart;
        const cx = (chartArea.left + chartArea.right) / 2;
        const cy = (chartArea.top + chartArea.bottom) / 2;
        ctx.save();
        ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
        ctx.font = 'bold 13px system-ui,sans-serif'; ctx.fillStyle = '#242424';
        ctx.fillText(cfg.text, cx, cy - (cfg.subtext ? 8 : 0));
        if (cfg.subtext) {
            ctx.font = '10px system-ui,sans-serif'; ctx.fillStyle = '#8F8F8F';
            ctx.fillText(cfg.subtext, cx, cy + 9);
        }
        ctx.restore();
    }
};

function _finSortToggle(which, col) {
    const s = which === 'rec' ? _finSortRec : _finSortPag;
    if (s.col === col) s.dir *= -1; else { s.col = col; s.dir = 1; }
    renderDashboardFinanceiro();
}

function getFinPeriodo() {
    const hoje = new Date();
    const hojeStr = hojeLocal();
    if (_finPeriodo === 'hoje') return { ini: hojeStr, fim: hojeStr, label: 'Hoje' };
    if (_finPeriodo === '7d') {
        const d = new Date(hoje); d.setDate(d.getDate() - 6);
        return { ini: dataLocal(d.getTime()), fim: hojeStr, label: 'Últimos 7 dias' };
    }
    if (_finPeriodo === '30d') {
        const d = new Date(hoje); d.setDate(d.getDate() - 29);
        return { ini: dataLocal(d.getTime()), fim: hojeStr, label: 'Últimos 30 dias' };
    }
    if (_finPeriodo === 'mes') {
        const ini = `${hoje.getFullYear()}-${String(hoje.getMonth()+1).padStart(2,'0')}-01`;
        const nome = hoje.toLocaleString('pt-BR', { month: 'long', year: 'numeric' });
        return { ini, fim: hojeStr, label: nome.charAt(0).toUpperCase() + nome.slice(1) };
    }
    const dIni = _finDataIni.split('-').reverse().join('/');
    const dFim = _finDataFim.split('-').reverse().join('/');
    return { ini: _finDataIni, fim: _finDataFim, label: `${dIni} – ${dFim}` };
}

// "inclui R$ X a cair até dd/mm" para entradas com data depois de hoje (cartao a cair); '' se nao houver.
function textoACairFin(itensEntrada) {
    const hoje = hojeLocal();
    const futuros = (itensEntrada || []).filter(i => i.data > hoje);
    if (!futuros.length) return '';
    const total = CaixaCore.arredondar(futuros.reduce((s, i) => s + i.valor, 0));
    const ultima = futuros.reduce((m, i) => i.data > m ? i.data : m, '');
    return `inclui ${_resBrl(total)} a cair até ${ultima.slice(8, 10)}/${ultima.slice(5, 7)}`;
}

// Dinheiro que entrou/saiu no periodo da Visao Geral, pela mesma regra do Resultado do mes
// (pela data em que o dinheiro entra; imposto pela referencia, so de meses inteiros).
// "Este mes" vale o mes inteiro (inclui o cartao a cair), como o Resultado do mes e o Extrato.
function dinheiroDoPeriodoFin() {
    const { ini, fim } = getFinPeriodo();
    const ate = _finPeriodo === 'mes' ? _resUltimoDia(ini.slice(0, 7)) : fim;
    const res = ResultadoCore.resultadoDoPeriodo({ de: ini, ate, ...dadosFinanceirosBase() });
    const crPorId = new Map((db.contas_receber || []).map(cr => [String(cr.id), cr]));
    const pedPagos = new Set();
    res.itensEntrada.forEach(i => { const cr = crPorId.get(String(i.cr_id)); if (cr && cr.pedido_id) pedPagos.add(cr.pedido_id); });
    const aCair = textoACairFin(res.itensEntrada);
    const lucroSub = 'recebido − saídas (imposto pela referência)' + (res.imposto.estimado ? ' (imposto estimado)' : '')
        + (res.imposto.foraIncompleto ? ' · sem o imposto de meses incompletos' : '');
    const impostoJaContado = cp => cp.categoria === 'imposto' && Object.prototype.hasOwnProperty.call(res.imposto.porMes, ResultadoCore.referenciaGuia(cp));
    return { res, ate, recebido: res.entradas, totalPago: res.saidas, lucro: res.resultado, pedPagos, ticketMedio: pedPagos.size ? res.entradas / pedPagos.size : 0, impostoJaContado, aCair, lucroSub };
}

function setFinPeriodo(tipo) {
    _finPeriodo = tipo;
    document.querySelectorAll('.fin-periodo-btn').forEach(b => b.classList.toggle('active', b.dataset.p === tipo));
    const cr = document.getElementById('fin-custom-range');
    if (cr) cr.style.display = tipo === 'custom' ? 'flex' : 'none';
    if (tipo !== 'custom') renderDashboardFinanceiro();
}

function aplicarFiltroCustom() {
    const ini = document.getElementById('fin-custom-ini')?.value;
    const fim = document.getElementById('fin-custom-fim')?.value;
    if (!ini || !fim || ini > fim) { showAlert('Selecione um intervalo de datas válido.', '⚠️'); return; }
    _finDataIni = ini; _finDataFim = fim;
    renderDashboardFinanceiro();
}

function salvarMetaMes() {
    if (!temAcesso('financeiro.dashboard', 'completo')) { showAlert('Você não tem permissão para realizar esta ação.', '🚫'); return; }
    const hoje = new Date();
    const key = `${hoje.getFullYear()}-${String(hoje.getMonth()+1).padStart(2,'0')}`;
    const val = parseFloat(document.getElementById('fin-meta-valor')?.value) || 0;
    // 0 ou vazio = sem ajuste neste mes (vale a meta padrao da empresa).
    if (val > 0) _finMetas[key] = val; else delete _finMetas[key];
    localStorage.setItem('sc_fin_metas', JSON.stringify(_finMetas));
    renderDashboardFinanceiro();
}

function _finGerarBuckets(ini, fim) {
    const iniD = new Date(ini + 'T00:00:00');
    const fimD = new Date(fim + 'T00:00:00');
    const dias = Math.round((fimD - iniD) / 86400000) + 1;
    if (dias <= 35) {
        return Array.from({ length: dias }, (_, i) => {
            const d = new Date(iniD); d.setDate(d.getDate() + i);
            const ds = dataLocal(d.getTime());
            return { label: d.toLocaleDateString('pt-BR', { day:'2-digit', month:'2-digit' }), ini: ds, fim: ds };
        });
    }
    const buckets = [];
    let cur = new Date(iniD);
    while (cur <= fimD) {
        const we = new Date(cur); we.setDate(we.getDate() + 6);
        if (we > fimD) we.setTime(fimD.getTime());
        buckets.push({
            label: cur.toLocaleDateString('pt-BR', { day:'2-digit', month:'2-digit' }),
            ini: dataLocal(cur.getTime()),
            fim: dataLocal(we.getTime())
        });
        cur.setDate(cur.getDate() + 7);
    }
    return buckets;
}

function gerarHTMLRelatorioFinanceiro(layout, opcoes) {
    layout = layout || getLayoutDocumento('financeiro');
    const { ini, fim, label } = getFinPeriodo();
    const inRange = d => d && d >= ini && d <= fim;
    const fmt = v => (v||0).toLocaleString('pt-BR', { minimumFractionDigits:2, maximumFractionDigits:2 });
    const fmtDate = s => s ? new Date(s+'T12:00:00').toLocaleDateString('pt-BR') : '—';

    // Recebido/pago pela mesma regra do Resultado do mes (pela data em que o dinheiro entra).
    const { res: resPer, ate: atePer, recebido, totalPago, lucro, pedPagos, ticketMedio, impostoJaContado, aCair, lucroSub } = dinheiroDoPeriodoFin();
    // A receber/a pagar na mesma janela do recebido/pago ("Este mes" = ate o fim do mes).
    const naJanela = d => d && d >= ini && d <= atePer;
    const aReceber  = db.contas_receber.filter(cr=>finAberta(cr)&&naJanela(cr.data_vencimento)).reduce((s,cr)=>s+cr.valor,0);
    const aPagar    = db.contas_pagar.filter(cp=>finAberta(cp)&&naJanela(cp.data_vencimento)).reduce((s,cp)=>s+cp.valor,0);
    // Guia de imposto em aberto ja contada nas saidas (imposto pela referencia) nao entra duas vezes no saldo.
    const aPagarDup = db.contas_pagar.filter(cp=>finAberta(cp)&&naJanela(cp.data_vencimento)&&impostoJaContado(cp)).reduce((s,cp)=>s+cp.valor,0);
    const saldoPrev = (recebido+aReceber)-(totalPago+aPagar-aPagarDup);

    const kpiBox = (lbl, val, sub, cor) =>
        `<div style="background:${cor};border-radius:8px;padding:14px 16px;color:white">
            <div style="font-size:10px;font-weight:700;text-transform:uppercase;letter-spacing:.5px;opacity:.85;margin-bottom:4px">${lbl}</div>
            <div style="font-size:18px;font-weight:700">${val}</div>
            ${sub?`<div style="font-size:10px;opacity:.7;margin-top:2px">${sub}</div>`:''}
         </div>`;

    const proxRec = db.contas_receber.filter(cr=>finAberta(cr)).sort((a,b)=>(a.data_vencimento||'9999').localeCompare(b.data_vencimento||'9999')).slice(0,10);
    const proxPag = db.contas_pagar.filter(cp=>finAberta(cp)).sort((a,b)=>(a.data_vencimento||'9999').localeCompare(b.data_vencimento||'9999')).slice(0,10);

    const comboImg = document.getElementById('chart-fin-combo')?.toDataURL?.('image/png') || null;
    const recImg   = document.getElementById('chart-fin-rec')?.toDataURL?.('image/png') || null;
    const despImg  = document.getElementById('chart-fin-desp')?.toDataURL?.('image/png') || null;
    const evolImg  = document.getElementById('chart-fin-evolucao')?.toDataURL?.('image/png') || null;
    const agingImg = document.getElementById('chart-fin-aging')?.toDataURL?.('image/png') || null;
    const topImg   = document.getElementById('chart-fin-top-clientes')?.toDataURL?.('image/png') || null;
    const funilImg = document.getElementById('chart-fin-funil')?.toDataURL?.('image/png') || null;
    const empresa  = getEmpresa();

    const thStyle = 'padding:6px 8px;text-align:left;border:1px solid #E0E0E0;background:#FAFAFA;font-size:11px';
    const tdStyle = 'padding:5px 8px;border:1px solid #E0E0E0;font-size:12px';

    const mkTable = (rows, headers, emptyMsg) => `
        <table style="width:100%;border-collapse:collapse;margin-bottom:16px">
            <thead><tr>${headers.map(h=>`<th style="${thStyle}${h.right?';text-align:right':''}">${h.label}</th>`).join('')}</tr></thead>
            <tbody>${rows.length ? rows : `<tr><td colspan="${headers.length}" style="${tdStyle};text-align:center;color:#8F8F8F">${emptyMsg}</td></tr>`}</tbody>
        </table>`;

    const rowsRec = proxRec.map(cr => {
        const at = cr.status==='Atrasado';
        return `<tr style="background:${at?'#FEF4F2':''}">
            <td style="${tdStyle}${at?';color:#F43927;font-weight:700':''}">${fmtDate(cr.data_vencimento)}</td>
            <td style="${tdStyle}">${escapeHtml(cr.cliente_nome)}</td>
            <td style="${tdStyle};color:#8F8F8F;font-size:11px">${escapeHtml(cr.descricao)}</td>
            <td style="${tdStyle};text-align:right;font-weight:700">R$ ${fmt(cr.valor)}</td>
            <td style="${tdStyle}">${cr.status}</td>
        </tr>`;
    });
    const rowsPag = proxPag.map(cp => {
        const at = cp.status==='Atrasado';
        return `<tr style="background:${at?'#FEF4F2':''}">
            <td style="${tdStyle}${at?';color:#F43927;font-weight:700':''}">${fmtDate(cp.data_vencimento)}</td>
            <td style="${tdStyle}">${escapeHtml(cp.credor_nome||cp.categoria||'—')}</td>
            <td style="${tdStyle};color:#8F8F8F;font-size:11px">${escapeHtml(cp.descricao)}</td>
            <td style="${tdStyle};text-align:right;font-weight:700">R$ ${fmt(cp.valor)}</td>
            <td style="${tdStyle}">${cp.status}</td>
        </tr>`;
    });

    const agora = new Date();
    const valores = Object.assign(valoresComunsEmpresa(), { periodo: label, data_geracao: agora.toLocaleString('pt-BR') });
    const titFin = id => textoDoc(blocoDoLayout(layout, id).titulo, valores);
    const rodape = String(blocoDoLayout(layout, 'rodape').corpo || '').split('\n').filter(l => l.trim());
    const blocos = {
        cabecalho: `
    <div class="fin-cab doc-cab" style="display:flex;justify-content:space-between;align-items:flex-start;border-bottom:2px solid var(--doc-cor,#005D3B);padding-bottom:14px;margin-bottom:20px">
        <div>${empresa.logo_base64?`<img src="${escapeHtml(empresa.logo_base64)}" alt="" style="height:32px;margin-bottom:4px;display:block">`:''}
            <h1 style="color:var(--doc-cor,#005D3B);margin:0;font-size:20px">${escapeHtml(empresa.nome_fantasia||empresa.razao_social||'SCTech')}</h1>
            <p style="margin:2px 0 0;color:#8F8F8F;font-size:12px">${textoDoc(layout.titulo, valores)}</p>
        </div>
        <div style="text-align:right;font-size:11px;color:#8F8F8F">
            <div>Gerado em ${agora.toLocaleDateString('pt-BR')}</div>
            <div>${ini.split('-').reverse().join('/')} – ${fim.split('-').reverse().join('/')}</div>
        </div>
    </div>`,
        indicadores: `
    <div style="display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin-bottom:20px">
        ${kpiBox('Total Recebido', 'R$ '+fmt(recebido), escapeHtml(label) + (aCair ? ' · ' + escapeHtml(aCair) : '') + (resPer.taxas > 0 ? `<br><span class="fin-recebido-liquido">R$ ${fmt(resPer.faturamento)} líquido (sem a taxa do cartão)</span>` : ''), '#005D3B')}
        ${kpiBox('A Receber', 'R$ '+fmt(aReceber), 'vence no período', '#2D77C1')}
        ${kpiBox('A Pagar', 'R$ '+fmt(aPagar), 'vence no período', '#F2C924')}
        ${kpiBox('Saldo Previsto', 'R$ '+fmt(saldoPrev), 'receb.+a receber−despesas', saldoPrev>=0?'#17E8FF':'#F43927')}
        ${kpiBox('Lucro (Caixa)', 'R$ '+fmt(lucro), escapeHtml(lucroSub), lucro>=0?'#159912':'#F43927')}
        ${kpiBox('Ticket Médio', ticketMedio>0?'R$ '+fmt(ticketMedio):'—', pedPagos.size+' pedido(s)', '#9B31C8')}
    </div>`,
        graficos: `
    ${evolImg?`<h3 style="font-size:13px;color:#242424;margin:0 0 6px">Evolução Mensal (12 meses)</h3><img src="${evolImg}" style="width:100%;border-radius:6px;margin-bottom:14px">`:''}
    ${comboImg?`<h3 style="font-size:13px;color:#242424;margin:0 0 6px">Entradas × Saídas × Saldo (período)</h3><img src="${comboImg}" style="width:100%;border-radius:6px;margin-bottom:14px">`:''}
    ${(agingImg||topImg||funilImg)?`<div style="display:grid;grid-template-columns:1fr 1fr 1fr;gap:10px;margin-bottom:14px">
        ${agingImg?`<div><h3 style="font-size:12px;color:#242424;margin:0 0 4px">Aging de Recebíveis</h3><img src="${agingImg}" style="width:100%"></div>`:''}
        ${topImg?`<div><h3 style="font-size:12px;color:#242424;margin:0 0 4px">Top 10 Clientes</h3><img src="${topImg}" style="width:100%"></div>`:''}
        ${funilImg?`<div><h3 style="font-size:12px;color:#242424;margin:0 0 4px">Funil de Pedidos</h3><img src="${funilImg}" style="width:100%"></div>`:''}
    </div>`:''}
    ${(recImg||despImg)?`<div style="display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-bottom:16px">
        ${recImg?`<div><h3 style="font-size:13px;color:#242424;margin:0 0 4px">Recebimentos</h3><img src="${recImg}" style="width:100%"></div>`:''}
        ${despImg?`<div><h3 style="font-size:13px;color:#242424;margin:0 0 4px">Despesas por Categoria</h3><img src="${despImg}" style="width:100%"></div>`:''}
    </div>`:''}
    ${(opcoes && opcoes.previa && !(evolImg||comboImg||agingImg||topImg||funilImg||recImg||despImg)) ? '<div class="doc-graficos-reserva">Os gráficos do período aparecem aqui ao gerar o relatório pela tela do Financeiro.</div>' : ''}`,
        recebimentos: `
    <h3 style="font-size:13px;color:#242424;margin:8px 0 6px;border-bottom:1px solid #E0E0E0;padding-bottom:4px">${titFin('recebimentos')}</h3>
    ${mkTable(rowsRec, [{label:'Vencimento'},{label:'Cliente'},{label:'Descrição'},{label:'Valor',right:true},{label:'Status'}], 'Nenhum recebimento pendente.')}`,
        pagamentos: `
    <h3 style="font-size:13px;color:#242424;margin:8px 0 6px;border-bottom:1px solid #E0E0E0;padding-bottom:4px">${titFin('pagamentos')}</h3>
    ${mkTable(rowsPag, [{label:'Vencimento'},{label:'Credor'},{label:'Descrição'},{label:'Valor',right:true},{label:'Status'}], 'Nenhum pagamento pendente.')}`,
        rodape: rodape.length ? `
    <div style="margin-top:20px;padding-top:10px;border-top:1px solid #E0E0E0;font-size:10px;color:#8F8F8F;text-align:center">
        ${rodape.map(l => textoDoc(l.trim(), valores)).join('<br>')}
    </div>` : ''
    };
    const html = `<div style="max-width:800px;margin:0 auto;padding:20px;color:#242424">${montarDocumentoLayout('financeiro', layout, blocos, valores)}</div>`;
    return { html, label };
}

function gerarRelatorioFinanceiro() {
    const { html, label } = gerarHTMLRelatorioFinanceiro();
    abrirDocModal(html, `Relatório Financeiro — ${label}`, '', envioDocumentoInterno(`Relatório financeiro — ${label}`, `Relatorio-financeiro-${label}`));
}

// Categorias das contas a pagar e das despesas fixas: uma lista so; o Imposto vem de CATEGORIA_IMPOSTO.
const CATEGORIA_IMPOSTO = ['imposto', 'Imposto'];
const CATEGORIAS_CONTA_PAGAR = [['tecido', 'Tecido / Material'], ['instalador', 'Instalador'], ['costureira', 'Costureira'], ['aluguel', 'Aluguel'],
    ['salario', 'Salário'], ['conta', 'Conta (luz, internet…)'], ['comissao_rt', 'Comissão RT'], CATEGORIA_IMPOSTO, ['outro', 'Outro']];
const CATEGORIAS_DESPESA_FIXA = [['aluguel', 'Aluguel'], ['salario', 'Salário'], ['conta', 'Conta (luz, internet…)'], CATEGORIA_IMPOSTO, ['outro', 'Outro']];
function _opcoesCategoria(lista) {
    return lista.map(([valor, rotulo]) => `<option value="${valor}">${escapeHtml(rotulo)}</option>`).join('');
}
// Os selects de categoria da pagina vem vazios no HTML; preenche uma vez.
function preencherCategoriasFinanceiro() {
    [['df-categoria', CATEGORIAS_DESPESA_FIXA, null], ['sim-categoria', CATEGORIAS_CONTA_PAGAR, 'outro']].forEach(([id, lista, padrao]) => {
        const el = document.getElementById(id);
        if (!el || el.options.length) return;
        el.innerHTML = _opcoesCategoria(lista);
        if (padrao) el.value = padrao;
    });
}

// Botoes das telas antigas religadas em FIN_RECURSOS_ANTIGOS (desligadas, nem existem na barra).
const _FIN_ROTULO_ANTIGA = { hoje: '☀️ Hoje', dashboard: '📊 Visão Geral', resultado: '📅 Resultado do mês', simulador: '🧮 Simular compra', drepedido: '📈 DRE por Pedido' };
function _finMontarAbasAntigas() {
    const nav = document.querySelector('.tab-nav');
    if (!nav) return;
    Object.keys(_FIN_ROTULO_ANTIGA).forEach(tab => {
        if (!FIN_RECURSOS_ANTIGOS[FIN_ABA_ANTIGA_RECURSO[tab]] || nav.querySelector(`.fin-tab-btn[data-tab="${tab}"]`)) return;
        const b = document.createElement('button');
        b.className = 'tab-btn fin-tab-btn';
        b.dataset.tab = tab;
        b.textContent = _FIN_ROTULO_ANTIGA[tab];
        b.onclick = () => mostrarTabFinanceiro(tab);
        nav.appendChild(b);
    });
}

// `lado` (so Lancamentos): 'pagar' | 'receber' | 'fixas'. Nomes antigos de aba (receber, pagar, fixas,
// hoje, extrato...) levam para a aba que hoje cuida do assunto (ver finAbaDestino).
function mostrarTabFinanceiro(tab, lado) {
    const dest = finAbaDestino(tab);
    tab = dest.tab; lado = dest.lado || lado;
    preencherCategoriasFinanceiro();
    if (_curTabFin !== tab) { _prevTabFin = _curTabFin; _curTabFin = tab; }
    document.querySelectorAll('.fin-tab-btn').forEach(b => b.classList.remove('active'));
    document.querySelectorAll('.fin-panel').forEach(p => p.classList.remove('active'));
    document.querySelector(`.fin-tab-btn[data-tab="${tab}"]`)?.classList.add('active');
    document.getElementById(`fin-${tab}`)?.classList.add('active');
    if (tab === 'resumo') renderFinResumo();
    else if (tab === 'lancamentos') renderFinLancamentos(lado);
    else if (tab === 'fluxo')   renderFinFluxo();
    else if (tab === 'dre')     renderFinDre();
    else if (tab === 'dashboard') renderDashboardFinanceiro();
    else if (tab === 'drepedido') renderDRE();
    else if (tab === 'hoje')    renderHoje();
    else if (tab === 'resultado') renderResultadoMes(_resMesAtual);
    else if (tab === 'simulador') renderSimulador();
    _tabBackBtn('.tab-nav', _prevTabFin, () => mostrarTabFinanceiro(_prevTabFin));
}

// =============================================
// FINANCEIRO — RESULTADO DO MES
// =============================================

const _resBrl = v => 'R$ ' + (Number(v) || 0).toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
let _resMesAtual = '';

function _resLerLS(chave) {
    try { const o = JSON.parse(localStorage.getItem(chave) || '{}'); return (o && typeof o === 'object' && !Array.isArray(o)) ? o : {}; } catch (e) { return {}; }
}

function _resUltimoDia(mes) {
    return mes + '-' + String(new Date(Number(mes.slice(0, 4)), Number(mes.slice(5, 7)), 0).getDate()).padStart(2, '0');
}

// Pedidos aprovados nos ultimos 90 dias, no formato da margem por pedido (so usado sem historico).
function _resPedidosFallback() {
    const corte = Date.now() - 90 * 86400000;
    const cad = { catalogo: db.catalogo, materiais: db.materiais, kits: db.kits };
    const out = [];
    (db.pedidos || []).forEach(p => {
        if (normalizarStatus(p.status) === 'Orçamento') return;
        const tl = (p.timeline || []).filter(t => t && t.status !== 'Orçamento' && typeof t.data === 'number').map(t => t.data);
        const quando = tl.length ? Math.min(...tl) : (typeof p.data_producao === 'number' ? p.data_producao : (typeof p.data_criacao === 'number' ? p.data_criacao : (typeof p.id === 'number' && p.id > 1e11 ? p.id : 0)));
        if (!(quando >= corte)) return;
        const r = FinanceiroCore.resultadoPedido({ ...p, ambientes: normalizarAmbientes(p) }, db.contas_pagar, cad);
        out.push({ receita: r.receita, custo_material: r.custo_material, custos_vinculados: r.custos_vinculados, comissoes: r.comissoes });
    });
    return out;
}

// Dados de entrada do ResultadoCore (os mesmos para Resultado do mes, Visao Geral e Hoje).
// `contas`: para o recebimento no cartao sem movimento cair nas datas de repasse da maquininha.
function dadosFinanceirosBase() {
    return { contasReceber: db.contas_receber, contasPagar: db.contas_pagar, movimentos: db.movimentos_fin, aliquota: getEmpresa().aliquota_estimada, contas: getContasFin(), categorias: db.fin_categorias };
}
function resultadoFinanceiroDoMes(mes, ateData) {
    return ResultadoCore.resultadoDoMes({ mes, ...dadosFinanceirosBase(), ateData });
}
// Meta do mes: ajuste do mes (sc_fin_metas, > 0) ou o padrao da empresa.
function metaFinanceiraDoMes(mes) {
    return ResultadoCore.metaDoMes(mes, { padrao: getEmpresa().meta_faturamento_padrao, ajustes: _resLerLS('sc_fin_metas') });
}
// Orcamento do mes: limites padrao + ajuste do mes (sc_fin_orcamento_mes) contra o gasto por grupo.
function orcamentoFinanceiroDoMes(mes, porGrupo) {
    const limites = Object.assign({}, getEmpresa().orcamento_padrao || {}, (_resLerLS('sc_fin_orcamento_mes')[mes]) || {});
    return ResultadoCore.statusOrcamento({ limites, gastos: porGrupo });
}

// Historico de 12 meses da margem: so recalcula quando o mes ou os dados de que ele depende mudam.
const _resMemoMargem = ResultadoCore.criarMemo();
function _resMargemHistorico(mes, base) {
    const chave = JSON.stringify([mes, base.aliquota, base.contasReceber, base.contasPagar, base.movimentos, base.contas]);
    return _resMemoMargem(chave, () => {
        const dadosPorMes = m => ResultadoCore.resultadoDoMes({ mes: m, ...base });
        return ResultadoCore.margemContribuicao({ mesAtual: mes, dadosPorMes, pedidosFallback: [], aliquota: base.aliquota });
    });
}

// Tudo o que a tela e o PDF mostram, para um mes.
function _resDados(mes) {
    const base = dadosFinanceirosBase();
    const aliquota = base.aliquota;
    const r = ResultadoCore.resultadoDoMes({ mes, ...base });
    const meta = metaFinanceiraDoMes(mes);
    const fixas = ResultadoCore.despesasFixasDoMes({ mes, contasPagar: db.contas_pagar, despesasFixas: db.despesas_fixas });
    let margem = _resMargemHistorico(mes, base);
    // Sem historico (nenhum dos 12 meses teve faturamento): margem pelos pedidos, sem refazer os 12 meses.
    if (margem.base === null) margem = ResultadoCore.margemContribuicao({ mesAtual: mes, dadosPorMes: () => ({}), pedidosFallback: _resPedidosFallback(), aliquota });
    const equilibrio = ResultadoCore.pontoEquilibrio(fixas, margem.pct);
    const orcamento = orcamentoFinanceiroDoMes(mes, r.porGrupo);
    return { r, meta, fixas, margem, equilibrio, orcamento, aliquota };
}

// Entradas e saidas ainda previstas ate o ultimo dia do mes (hoje em diante). O que ja foi baixado e cai depois
// de hoje (cartao a cair e a taxa dele) vem de ResultadoCore.aCairNoMes, pelas regras do Resultado do mes
// (transferencias entre contas nao contam). O que esta em aberto vem do motor da previsao semanal: entradas,
// saidas e despesas fixas filtradas ate o fim do mes; os repasses de cartao previstos sao calculados a parte
// para nao contar o que cai depois do fim do mes. Guias de imposto (e despesas fixas antigas de imposto) ficam
// de fora: o imposto conta pela referencia e e refeito em ResultadoCore.previstoDoMes.
function _resPrevisto(mes) {
    const hoje = hojeLocal();
    const fim = _resUltimoDia(mes);
    const meios = getMeiosPag();
    const contas = getContasFin();
    const meioCartao = cr => { const mp = cr.meio_previsto; const m = mp ? meios.find(x => CaixaCore.mesmoId(x.id, mp.meio_id)) : null; return (m && (m.tipo === 'cartao_credito' || m.tipo === 'cartao_debito')) ? m : null; };
    const abertos = (db.contas_receber || []).filter(c => finAberta(c));
    const comum = abertos.filter(c => !meioCartao(c) && c.data_vencimento <= fim);
    // Guia de imposto, de qualquer referencia, fica fora da previsao: a deste mes ja esta no resultado e a do
    // mes anterior (vencendo agora) e daquele mes.
    const cps = (db.contas_pagar || []).filter(c => c && c.data_vencimento <= fim && c.categoria !== 'imposto');
    const atrasados = comum.some(c => c.data_vencimento < hoje) || abertos.filter(meioCartao).some(c => c.data_vencimento < hoje)
        || cps.some(c => finAberta(c) && c.data_vencimento < hoje);
    let cartao = 0;
    abertos.filter(meioCartao).forEach(cr => {
        const m = meioCartao(cr);
        const data = cr.data_vencimento > hoje ? cr.data_vencimento : hoje;
        const conta = contas.find(c => CaixaCore.mesmoId(c.id, m.conta_id));
        CaixaCore.repassesCartao({ valor: Number(cr.valor) || 0, data, conta, tipo: m.tipo === 'cartao_debito' ? 'debito' : 'credito', vezes: cr.meio_previsto.vezes, antecipar: !!cr.meio_previsto.antecipar })
            .forEach(x => { if (x.data <= fim) cartao += x.liquido; });
    });
    const dias = Math.round((new Date(fim + 'T00:00:00') - new Date(hoje + 'T00:00:00')) / 86400000) + 1;
    const semanas = CaixaCore.previsaoSemanal({
        hoje, saldoHoje: 0,
        movimentos: [],
        contasReceber: comum,
        contasPagar: cps,
        despesasFixas: (db.despesas_fixas || []).filter(df => df && df.categoria !== 'imposto').map(df => ({ ...df, data_fim: (df.data_fim && df.data_fim < fim) ? df.data_fim : fim })),
        contas, meios, semanas: Math.max(1, Math.ceil(dias / 7))
    });
    const aCair = ResultadoCore.aCairNoMes({ mes, hoje, ...dadosFinanceirosBase() });
    const entradas = CaixaCore.arredondar(semanas.reduce((s, w) => s + w.entradas, 0) + cartao + aCair.entradas);
    // Comissoes pendentes saem do caixa ate o fim do mes (pagamento manual): contam como saida prevista.
    const comissoesPrev = FinanceiroCore.comissoesPendentesPrevistas(db.pedidos, db.contas_pagar, db.vendedores).reduce((s, c) => s + c.valor, 0);
    const saidas = CaixaCore.arredondar(semanas.reduce((s, w) => s + w.saidas, 0) + aCair.saidas + comissoesPrev);
    // Taxas de cartao ainda previstas (CPs em aberto e as dos repasses ja baixados que ainda vao cair): saem do faturamento previsto.
    const taxas = CaixaCore.arredondar(cps.filter(c => finAberta(c) && c.categoria === 'taxa_cartao').reduce((s, c) => s + (Number(c.valor) || 0), 0) + aCair.taxas);
    return { entradas, saidas, taxas, atrasados };
}

// Frase, linha e aviso do ponto de equilibrio (tela e PDF).
function _resTextosEquilibrio(d) {
    const r = d.r;
    if (d.equilibrio.valor != null) {
        return {
            frase: `Para pagar as contas do mês você precisa faturar ${_resBrl(d.equilibrio.valor)}.`,
            linha: `empate ${_resBrl(d.equilibrio.valor)}` + (d.meta > 0 ? ` · meta ${_resBrl(d.meta)}` : '') + ` · faturado ${_resBrl(r.faturamento)}`,
            aviso: (d.margem.base === 'pedidos' || d.margem.meses.length < 3) ? 'estimativa — poucos meses de histórico' : ''
        };
    }
    if (d.equilibrio.motivo === 'sem_fixas') return { frase: 'Cadastre as despesas fixas para calcular o ponto de equilíbrio', linha: '', aviso: '' };
    if (d.equilibrio.motivo === 'margem_negativa') return { frase: 'Com a margem atual não há ponto de equilíbrio — os custos variáveis passam do faturamento.', linha: '', aviso: '' };
    return { frase: 'Ainda não há histórico para calcular o ponto de equilíbrio.', linha: '', aviso: '' };
}

// Mes em andamento: resultado ate hoje e previsto ate o fim do mes (so para o mes atual).
function _resAndamento(mes, d) {
    if (mes !== hojeLocal().slice(0, 7)) return null;
    const hoje = hojeLocal();
    const prev = _resPrevisto(mes);
    const rHoje = resultadoFinanceiroDoMes(mes, hoje);
    const previsto = ResultadoCore.previstoDoMes({ mes, ateHoje: rHoje, entradasPrevistas: prev.entradas, saidasPrevistas: prev.saidas, taxasPrevistas: prev.taxas, contasPagar: db.contas_pagar, aliquota: d.aliquota });
    return { ateHoje: rHoje.resultado, previsto: previsto.valor, atrasados: prev.atrasados };
}

function _resPctTxt(o) { return String(o.pct).replace('.', ',') + '%'; }
function _resSituacao(o) {
    return o.faixa === 'estourou' ? `estourou ${_resBrl(-o.falta)}` : (o.faixa === 'perto' ? 'perto do limite' : 'dentro do limite');
}

function renderResultadoMes(mes) {
    const painel = document.getElementById('fin-resultado');
    if (!painel || typeof ResultadoCore === 'undefined') return;
    const hoje = hojeLocal();
    if (!/^\d{4}-\d{2}$/.test(mes || '')) mes = _resMesAtual || hoje.slice(0, 7);
    _resMesAtual = mes;
    const inp = document.getElementById('res-mes');
    if (inp && inp.value !== mes) inp.value = mes;
    const podeEditar = temAcesso('financeiro.resultado', 'completo');
    const d = _resDados(mes);
    const r = d.r;
    const set = (id, txt) => { const el = document.getElementById(id); if (el) el.textContent = txt; };

    set('res-entradas', _resBrl(r.entradas));
    const elACair = document.getElementById('res-entradas-a-cair');
    if (elACair) {
        const txt = textoACairFin(ResultadoCore.entradasDoMes({ mes, ...dadosFinanceirosBase() }).itens);
        elACair.textContent = txt;
        elACair.style.display = txt ? '' : 'none';
    }
    set('res-saidas', _resBrl(r.saidas));
    set('res-saldo', _resBrl(r.resultado));
    document.getElementById('res-saldo').className = r.resultado < 0 ? 'res-neg' : 'res-pos';

    // Meta
    const elMeta = document.getElementById('res-meta');
    let txtMeta = `Faturamento líquido ${_resBrl(r.faturamento)}`;
    if (d.meta > 0) {
        const falta = CaixaCore.arredondar(d.meta - r.faturamento);
        txtMeta += ` · meta ${_resBrl(d.meta)} — ` + (falta <= 0 ? 'bateu a meta' : `faltou ${_resBrl(falta)}`);
    } else txtMeta += ' · sem meta definida';
    elMeta.innerHTML = `<span>${escapeHtml(txtMeta)}</span>` + (podeEditar ? ' <button class="fin-meta-edit-btn" id="res-meta-edit" onclick="ajustarMetaMes(_resMesAtual)" title="Ajustar a meta deste mês">✏️</button>' : '');

    // Saidas por grupo
    document.getElementById('res-grupos').innerHTML = ResultadoCore.GRUPOS.map(g => {
        const est = g.id === 'imposto' && r.imposto.estimado ? ' <small style="color:#888">(estimado)</small>' : '';
        return `<tr data-grupo="${g.id}"><td>${escapeHtml(g.rotulo)}${est}</td><td style="text-align:right">${_resBrl(r.porGrupo[g.id])}</td></tr>`;
    }).join('');
    const elAv = document.getElementById('res-imposto-aviso');
    let avImp = '';
    if (r.imposto.estimado) avImp = r.imposto.semAliquota ? 'Informe a alíquota em Empresa para estimar o imposto' : `guia ainda não lançada — estimativa ${_resBrl(r.imposto.valor)}`;
    elAv.textContent = avImp;
    elAv.style.display = avImp ? '' : 'none';

    // Ponto de equilibrio
    const frase = document.getElementById('res-equilibrio-frase');
    const linha = document.getElementById('res-equilibrio-linha');
    const aviso = document.getElementById('res-equilibrio-aviso');
    aviso.style.display = 'none';
    linha.textContent = '';
    const eq = _resTextosEquilibrio(d);
    frase.textContent = eq.frase;
    linha.textContent = eq.linha;
    if (eq.aviso) { aviso.textContent = eq.aviso; aviso.style.display = ''; }

    // Orcamento
    document.getElementById('res-orcamento').innerHTML = d.orcamento.map(o => {
        return `<tr data-orc="${o.grupo}"><td>${escapeHtml(o.rotulo)}</td><td style="text-align:right">${_resBrl(o.limite)}</td><td style="text-align:right">${_resBrl(o.gasto)}</td><td style="text-align:right">${_resBrl(Math.max(0, o.falta))}</td><td style="text-align:right">${_resPctTxt(o)}</td><td class="res-faixa-${o.faixa}">${escapeHtml(_resSituacao(o))}</td><td>${podeEditar ? `<button class="res-ed" onclick="ajustarOrcamentoMes(_resMesAtual, '${o.grupo}')" title="Ajustar o limite só deste mês">✏️</button>` : ''}</td></tr>`;
    }).join('');
    document.getElementById('res-orcamento-vazio').style.display = d.orcamento.length ? 'none' : '';
    const addBox = document.getElementById('res-orc-add');
    // O "+ Limite so neste mes" so faz sentido com algum orcamento definido (padrao ou ajuste deste mes, mesmo que 0).
    const padraoOrc = getEmpresa().orcamento_padrao || {};
    const temOrcamento = Object.values(padraoOrc).some(v => Number(v) > 0) || Object.keys(_resLerLS('sc_fin_orcamento_mes')[mes] || {}).length > 0;
    addBox.style.display = podeEditar && temOrcamento ? 'flex' : 'none';
    const selGrupo = document.getElementById('res-orc-grupo');
    if (selGrupo && !selGrupo.options.length) selGrupo.innerHTML = ResultadoCore.GRUPOS.map(g => `<option value="${g.id}">${escapeHtml(g.rotulo)}</option>`).join('');

    // Mes aberto
    const aberto = document.getElementById('res-aberto');
    const and = _resAndamento(mes, d);
    if (and) {
        set('res-ate-hoje', _resBrl(and.ateHoje));
        set('res-previsto', _resBrl(and.previsto));
        set('res-aberto-legenda', and.atrasados ? 'inclui atrasados' : '');
        aberto.style.display = '';
    } else aberto.style.display = 'none';

    renderFechamentoCard(mes);
}

// Janelinha de ajuste de um valor (meta ou limite do mes). Vazio remove o ajuste.
function _resAbrirAjuste({ titulo, dica, atual, aoSalvar, sugestao }) {
    document.getElementById('res-ajuste-modal')?.remove();
    const o = document.createElement('div');
    o.id = 'res-ajuste-modal';
    o.className = 'sc-modal-overlay';
    o.style.display = 'flex';
    o.innerHTML = `<div class="sc-modal-box" style="text-align:left;max-width:380px;width:92%">
        <h3 style="margin:0 0 10px;font-size:16px">${escapeHtml(titulo)}</h3>
        <div class="form-group"><label for="res-ajuste-valor">Valor (R$)</label>
            <input type="text" inputmode="decimal" id="res-ajuste-valor" value="${atual != null ? escapeHtml(String(atual).replace('.', ',')) : ''}" placeholder="${escapeHtml(sugestao || 'ex: 30.000')}">
            <small style="color:#888">${escapeHtml(dica)}</small></div>
        <div id="res-ajuste-erro" style="color:#F43927;font-size:13px;min-height:16px"></div>
        <div style="display:flex;gap:8px;justify-content:flex-end;margin-top:8px">
            <button class="btn btn-outline" id="res-ajuste-cancelar">Cancelar</button>
            <button class="btn btn-primary" id="res-ajuste-ok">Salvar</button></div></div>`;
    const fechar = () => o.remove();
    o.addEventListener('click', e => { if (e.target === o) fechar(); });
    o.querySelector('#res-ajuste-cancelar').onclick = fechar;
    const salvar = () => {
        const t = o.querySelector('#res-ajuste-valor').value.trim();
        let v = null;
        if (t) {
            v = _valorDigitadoBaixa(t);
            if (Number.isNaN(v) || v < 0) { o.querySelector('#res-ajuste-erro').textContent = 'Informe só números (ex: 30.000 ou 30.000,50).'; return; }
            v = CaixaCore.arredondar(v);
        }
        aoSalvar(v);
        fechar();
    };
    o.querySelector('#res-ajuste-ok').onclick = salvar;
    o.querySelector('#res-ajuste-valor').addEventListener('keydown', e => { if (e.key === 'Enter') salvar(); });
    document.body.appendChild(o);
    o.querySelector('#res-ajuste-valor').focus();
}
document.addEventListener('keydown', e => {
    if (e.key !== 'Escape') return;
    const aviso = document.getElementById('sc-modal-overlay');
    if (aviso && aviso.style.display === 'flex') return;
    document.getElementById('res-ajuste-modal')?.remove();
});

function ajustarMetaMes(mes) {
    if (!temAcesso('financeiro.resultado', 'completo')) { showAlert('Você não tem permissão para realizar esta ação.', '🚫'); return; }
    const atual = _resLerLS('sc_fin_metas')[mes] > 0 ? _resLerLS('sc_fin_metas')[mes] : null;
    const padrao = Number(getEmpresa().meta_faturamento_padrao);
    _resAbrirAjuste({
        titulo: 'Meta de faturamento deste mês', dica: 'Vale só para este mês. Vazio volta à meta padrão da Empresa.', atual,
        sugestao: padrao > 0 ? padrao.toLocaleString('pt-BR', { maximumFractionDigits: 2 }) : '',
        aoSalvar: v => {
            const metas = _resLerLS('sc_fin_metas');
            if (v != null && v > 0) metas[mes] = v; else delete metas[mes];
            localStorage.setItem('sc_fin_metas', JSON.stringify(metas));
            _finMetas = metas;
            renderResultadoMes(mes);
        }
    });
}

function ajustarOrcamentoMes(mes, grupo) {
    if (!temAcesso('financeiro.resultado', 'completo')) { showAlert('Você não tem permissão para realizar esta ação.', '🚫'); return; }
    const g = ResultadoCore.GRUPOS.find(x => x.id === grupo);
    if (!g) return;
    const ov = (_resLerLS('sc_fin_orcamento_mes')[mes]) || {};
    const atual = Object.prototype.hasOwnProperty.call(ov, grupo) ? Number(ov[grupo]) : null;
    _resAbrirAjuste({
        titulo: `Limite de ${g.rotulo} neste mês`, dica: 'Vale só para este mês. Vazio volta ao limite padrão da Empresa; 0 tira o limite deste mês.', atual,
        aoSalvar: v => {
            const todos = _resLerLS('sc_fin_orcamento_mes');
            const mm = Object.assign({}, todos[mes] || {});
            if (v != null) mm[grupo] = v; else delete mm[grupo];
            if (Object.keys(mm).length) todos[mes] = mm; else delete todos[mes];
            localStorage.setItem('sc_fin_orcamento_mes', JSON.stringify(todos));
            renderResultadoMes(mes);
        }
    });
}

function exportarResultadoPDF(mes) {
    if (!/^\d{4}-\d{2}$/.test(mes || '')) mes = _resMesAtual || hojeLocal().slice(0, 7);
    const d = _resDados(mes);
    const r = d.r;
    const rotuloMes = mes.slice(5, 7) + '/' + mes.slice(0, 4);
    const td = 'padding:6px 8px;border-bottom:1px solid #ddd';
    const grupos = ResultadoCore.GRUPOS.map(g => `<tr><td style="${td}">${escapeHtml(g.rotulo)}${g.id === 'imposto' && r.imposto.estimado ? ' (estimado)' : ''}</td><td style="${td};text-align:right">${_resBrl(r.porGrupo[g.id])}</td></tr>`).join('');
    let meta = `Faturamento líquido ${_resBrl(r.faturamento)}`;
    if (d.meta > 0) { const f = CaixaCore.arredondar(d.meta - r.faturamento); meta += ` · meta ${_resBrl(d.meta)} — ` + (f <= 0 ? 'bateu a meta' : `faltou ${_resBrl(f)}`); }
    let imp = '';
    if (r.imposto.estimado) imp = r.imposto.semAliquota ? 'Informe a alíquota em Empresa para estimar o imposto' : `guia ainda não lançada — estimativa ${_resBrl(r.imposto.valor)}`;
    const eq = _resTextosEquilibrio(d);
    const orc = d.orcamento.map(o => `<tr><td style="${td}">${escapeHtml(o.rotulo)}</td><td style="${td};text-align:right">${_resBrl(o.limite)}</td><td style="${td};text-align:right">${_resBrl(o.gasto)}</td><td style="${td};text-align:right">${_resBrl(Math.max(0, o.falta))}</td><td style="${td};text-align:right">${_resPctTxt(o)}</td><td style="${td}">${escapeHtml(_resSituacao(o))}</td></tr>`).join('');
    const and = _resAndamento(mes, d);
    const html = `<div style="padding:24px;color:#242424">
        <div class="doc-cab">${buildEmpresaHeaderHTML(52)}</div>
        <h2 style="margin:16px 0 4px">Resultado do mês — ${escapeHtml(rotuloMes)}</h2>
        <div style="display:flex;gap:32px;margin:12px 0;font-size:14px">
            <div>Entradas<br><strong style="font-size:18px">${_resBrl(r.entradas)}</strong></div>
            <div>Saídas<br><strong style="font-size:18px">${_resBrl(r.saidas)}</strong></div>
            <div>Resultado<br><strong style="font-size:18px;color:${r.resultado < 0 ? '#F43927' : '#005D3B'}">${_resBrl(r.resultado)}</strong></div>
        </div>
        <div style="font-size:13px;margin-bottom:12px">${escapeHtml(meta)}</div>
        <table style="width:100%;border-collapse:collapse;font-size:13px"><thead><tr style="text-align:left;background:#f0f0f0"><th style="${td}">Saídas por grupo</th><th style="${td};text-align:right">Valor</th></tr></thead><tbody>${grupos}</tbody></table>
        <div style="font-size:12px;color:#666;margin-top:4px">Imposto contado pelo mês de referência da guia (não pela data de pagamento).</div>
        ${imp ? `<div style="font-size:12px;color:#B26A00;margin-top:6px">${escapeHtml(imp)}</div>` : ''}
        <div style="font-size:14px;font-weight:600;margin-top:14px">${escapeHtml(eq.frase)}</div>
        ${eq.linha ? `<div style="font-size:13px;margin-top:4px">${escapeHtml(eq.linha)}</div>` : ''}
        ${eq.aviso ? `<div style="font-size:12px;color:#B26A00;margin-top:4px">${escapeHtml(eq.aviso)}</div>` : ''}
        ${orc ? `<table style="width:100%;border-collapse:collapse;font-size:13px;margin-top:14px"><thead><tr style="text-align:left;background:#f0f0f0"><th style="${td}">Orçamento</th><th style="${td};text-align:right">Limite</th><th style="${td};text-align:right">Gasto</th><th style="${td};text-align:right">Falta</th><th style="${td};text-align:right">% usado</th><th style="${td}">Situação</th></tr></thead><tbody>${orc}</tbody></table>` : ''}
        ${and ? `<div style="margin-top:14px;font-size:14px"><strong>Mês em andamento</strong><br>Até hoje: ${_resBrl(and.ateHoje)} · Previsto até o fim do mês: ${_resBrl(and.previsto)}${and.atrasados ? ' (inclui atrasados)' : ''}</div>` : ''}
    </div>`;
    abrirDocModal(html, 'Resultado do mês — ' + rotuloMes, '', envioDocumentoInterno('Resultado do mês — ' + rotuloMes, 'Resultado-do-mes-' + rotuloMes));
}

// =============================================
// FINANCEIRO — FECHAMENTO DO MES
// =============================================
// Passo a passo (conferir o dinheiro -> pendencias -> resumo), foto em
// db.fechamentos_fin, aviso de mudanca depois do fechamento e documento.

const _fechMaiusc = s => String(s || '').charAt(0).toUpperCase() + String(s || '').slice(1);
const _fechDataBR = iso => { const d = new Date(iso); return isNaN(d) ? '' : d.toLocaleDateString('pt-BR'); };
const _fechDiaBR = d => String(d || '').split('-').reverse().join('/');
// Diferenca com sinal: "−R$ 20,00" / "+R$ 20,00" / "R$ 0,00".
const _fechDifTxt = v => { const c = Math.round((Number(v) || 0) * 100); return (c < 0 ? '−' : c > 0 ? '+' : '') + _resBrl(Math.abs(c) / 100); };

function fechamentoDoMes(mes) {
    return (Array.isArray(db.fechamentos_fin) ? db.fechamentos_fin : []).find(f => f && f.mes === mes) || null;
}

// O que mudou no mes desde a foto: resultado de agora e saldo de agora (no ultimo dia) de cada conta da foto.
function mudancasDoFechamento(mes) {
    const foto = fechamentoDoMes(mes);
    if (!foto || typeof FechamentoCore === 'undefined') return [];
    const ultimo = FechamentoCore.ultimoDiaMes(mes);
    const movs = Array.isArray(db.movimentos_fin) ? db.movimentos_fin : [];
    const saldos = {};
    (foto.contas || []).forEach(c => {
        const conta = _contaFinPorId(c.conta_id);
        if (conta) saldos[c.conta_id] = CaixaCore.saldoConta(conta, movs, ultimo);
    });
    return FechamentoCore.mudancasDesdeFoto(foto, { r: resultadoFinanceiroDoMes(mes), saldos });
}

function _fechTextosMudanca(mes, mudancas) {
    const pre = `⚠ ${_fechMaiusc(FechamentoCore.rotuloMes(mes))} mudou depois do fechamento: `;
    return _fechSoMudancas(mudancas).map(x => pre + (x.tipo === 'resultado'
        ? `resultado era ${_resBrl(x.antes)}, agora é ${_resBrl(x.agora)}`
        : `saldo de ${x.nome} era ${_resBrl(x.antes)}, agora ${_resBrl(x.agora)}`));
}

// Guia de imposto lancada depois do fechamento: so informa (nao e aviso de mudanca).
const _fechSoMudancas = ms => (ms || []).filter(x => x.tipo !== 'guia');
function _fechTextosGuia(mudancas) {
    return (mudancas || []).filter(x => x.tipo === 'guia')
        .map(x => `Guia de imposto lançada: ${_resBrl(x.agora)} (estimado era ${_resBrl(x.antes)})`);
}

// Card do fechamento no topo do Resultado do mes (so para meses que ja terminaram).
function renderFechamentoCard(mes) {
    const el = document.getElementById('res-fechamento');
    if (!el) return;
    const esconder = () => { el.style.display = 'none'; el.innerHTML = ''; };
    if (!FIN_RECURSOS_ANTIGOS.fechamento) return esconder();
    if (typeof FechamentoCore === 'undefined' || !/^\d{4}-\d{2}$/.test(mes || '') || mes >= hojeLocal().slice(0, 7)) return esconder();
    const pode = temAcesso('financeiro.resultado', 'completo');
    const rot = FechamentoCore.rotuloMes(mes);
    const foto = fechamentoDoMes(mes);
    if (!foto) {
        if (!pode) return esconder();
        el.innerHTML = `<div class="fech-card-linha"><span class="fech-card-txt">Confira o dinheiro, veja o que ficou pendente e guarde o resumo do mês.</span>
            <button class="btn btn-primary" id="fech-btn-fechar" onclick="abrirFechamentoMes('${mes}')">🔒 Fechar ${escapeHtml(rot)}</button></div>`;
    } else {
        const mudancas = mudancasDoFechamento(mes);
        const avisos = _fechTextosMudanca(mes, mudancas);
        const guia = _fechTextosGuia(mudancas);
        el.innerHTML = `<div class="fech-card-linha"><span class="fech-selo">🔒 Fechado em ${escapeHtml(_fechDataBR(foto.fechado_em))} por ${escapeHtml(foto.fechado_por || '')}</span>
            <span class="fech-card-botoes"><button class="btn btn-outline btn-sm" onclick="verFechamentoMes('${mes}')">Ver fechamento</button>${pode
                ? `<button class="btn btn-outline btn-sm" onclick="refazerFechamentoMes('${mes}')">Refazer fechamento</button>` : ''}</span></div>`
            + (avisos.length ? `<div class="fech-mudou">${avisos.map(t => `<div>${escapeHtml(t)}</div>`).join('')}</div>` : '')
            + (guia.length ? `<div class="fech-info">${guia.map(t => `<div>${escapeHtml(t)}</div>`).join('')}</div>` : '');
    }
    el.style.display = '';
}

function _fechAtalho(tab) {
    document.getElementById('fech-modal')?.remove();
    mostrarTabFinanceiro(tab);
}

// Passo a passo do fechamento (3 telas). Os valores digitados ficam em "linhas" ao trocar de tela.
function abrirFechamentoMes(mes) {
    if (!FIN_RECURSOS_ANTIGOS.fechamento) return;
    if (!temAcesso('financeiro.resultado', 'completo')) { showAlert('Você não tem permissão para realizar esta ação.', '🚫'); return; }
    if (typeof FechamentoCore === 'undefined' || !/^\d{4}-\d{2}$/.test(mes || '') || mes >= hojeLocal().slice(0, 7)) return;
    if (fechamentoDoMes(mes)) { verFechamentoMes(mes); return; }
    document.getElementById('fech-modal')?.remove();
    const rot = FechamentoCore.rotuloMes(mes);
    const ultimo = FechamentoCore.ultimoDiaMes(mes);
    const linhas = FechamentoCore.contasDaConferencia({
        mes, contas: getContasFin(), movimentos: db.movimentos_fin || [], saldoConta: CaixaCore.saldoConta, ignorarAjustesDe: null
    }).map(c => ({ ...c, texto: '', acao: 'anotado', motivo: '' }));
    const st = { passo: 1, anotacoes: '' };
    // Extrato digitado: null = nao conferida, NaN = invalido.
    const extratoDe = l => { const t = String(l.texto || '').trim(); return t ? _valorDigitadoBaixa(t, NaN) : null; };
    const difDe = l => { const e = extratoDe(l); return e == null || Number.isNaN(e) ? null : CaixaCore.arredondar(e - l.esperado); };
    const temDif = l => { const d = difDe(l); return d != null && Math.round(d * 100) !== 0; };

    const o = document.createElement('div');
    o.id = 'fech-modal';
    o.className = 'sc-modal-overlay fech-overlay';
    o.style.display = 'flex';
    o.innerHTML = '<div class="sc-modal-box fech-box"></div>';
    const box = o.querySelector('.fech-box');
    const fechar = () => o.remove();
    // Sem fechar pelo fundo nem pelo Esc (perderia o que foi digitado). Cancelar pergunta antes, se ha algo digitado.
    const cancelar = async () => {
        const digitou = linhas.some(l => String(l.texto || '').trim() || String(l.motivo || '').trim()) || String(st.anotacoes || '').trim();
        if (digitou && !(await showConfirm('Cancelar o fechamento? O que você digitou será perdido.', '🔒', 'Cancelar fechamento', 'Continuar fechando'))) return;
        fechar();
    };
    const pagarLink = temAcesso('financeiro.pagar', 'visualizar') ? `<a href="#" class="fech-link" onclick="_fechAtalho('pagar');return false">A Pagar</a>` : 'A Pagar';
    const receberLink = temAcesso('financeiro.receber', 'visualizar') ? `<a href="#" class="fech-link" onclick="_fechAtalho('receber');return false">A Receber</a>` : 'A Receber';
    const titulo = n => `<h3 class="fech-titulo">🔒 Fechar ${escapeHtml(rot)}</h3><div class="fech-passos">Passo ${n} de 3 · ${['Conferir o dinheiro', 'O que ficou pendente', 'Resumo do mês'][n - 1]}</div>`;
    const BOTAO_CANCELAR = '<button class="btn btn-outline" data-acao="cancelar">Cancelar</button>';
    const rodape = (voltar, avancar) => `<div class="fech-erro"></div><div class="fech-botoes">${voltar}${avancar}</div>`;

    const pend = () => FechamentoCore.pendenciasDoMes({ mes, contasPagar: db.contas_pagar, contasReceber: db.contas_receber, impostoEstimado: resultadoFinanceiroDoMes(mes).imposto.estimado });

    function passo1() {
        const corpo = linhas.length ? `<div class="fech-tabela-wrap"><table class="fech-tabela"><thead><tr><th>Conta</th><th style="text-align:right">Esperado</th><th>Saldo no extrato</th><th>Diferença</th></tr></thead><tbody>${linhas.map((l, i) => `
            <tr data-conta="${escapeHtml(String(l.conta_id))}" data-i="${i}"><td>${escapeHtml(l.nome || '')}</td><td style="text-align:right">${_resBrl(l.esperado)}</td>
                <td><input type="text" inputmode="decimal" class="fech-extrato" value="${escapeHtml(l.texto)}" placeholder="não conferida" aria-label="Saldo no extrato de ${escapeHtml(l.nome || '')}"></td>
                <td><div class="fech-dif"></div><div class="fech-acao" style="display:none">
                    <label><input type="radio" name="fech-acao-${i}" value="ajuste"${l.acao === 'ajuste' ? ' checked' : ''}> Lançar ajuste</label>
                    <label><input type="radio" name="fech-acao-${i}" value="anotado"${l.acao !== 'ajuste' ? ' checked' : ''}> Deixar anotado</label>
                    <input type="text" class="fech-motivo" placeholder="Motivo do ajuste" value="${escapeHtml(l.motivo)}"${l.acao === 'ajuste' ? '' : ' style="display:none"'}>
                </div></td></tr>`).join('')}</tbody></table></div>`
            : '<p class="fech-vazio">Nenhuma conta para conferir neste mês.</p>';
        box.innerHTML = titulo(1)
            + `<p class="fech-texto">Digite o saldo que aparece no extrato de cada conta em ${_fechDiaBR(ultimo)}. Em branco, a conta fica como não conferida.</p>`
            + corpo
            + `<div class="fech-dica">Se a diferença é uma conta que você esqueceu de lançar, lance no ${pagarLink} / ${receberLink} em vez de ajustar.</div>`
            + rodape(BOTAO_CANCELAR, '<button class="btn btn-primary" data-acao="continuar">Continuar</button>');
        box.querySelectorAll('tr[data-i]').forEach(tr => {
            const l = linhas[Number(tr.dataset.i)];
            const atualizar = () => {
                const e = extratoDe(l), d = difDe(l);
                const dif = tr.querySelector('.fech-dif');
                dif.textContent = e == null ? 'não conferida' : (Number.isNaN(e) ? 'valor inválido' : _fechDifTxt(d));
                dif.className = 'fech-dif' + (d != null && Math.round(d * 100) < 0 ? ' res-neg' : '');
                tr.querySelector('.fech-acao').style.display = temDif(l) ? '' : 'none';
                tr.querySelector('.fech-motivo').style.display = l.acao === 'ajuste' ? '' : 'none';
            };
            tr.querySelector('.fech-extrato').addEventListener('input', e => { l.texto = e.target.value; atualizar(); });
            tr.querySelectorAll('input[type="radio"]').forEach(r => r.addEventListener('change', () => { if (r.checked) { l.acao = r.value; atualizar(); } }));
            tr.querySelector('.fech-motivo').addEventListener('input', e => { l.motivo = e.target.value; });
            atualizar();
        });
        box.querySelector('[data-acao="cancelar"]').onclick = cancelar;
        box.querySelector('[data-acao="continuar"]').onclick = () => {
            const erro = t => { box.querySelector('.fech-erro').textContent = t; };
            const invalida = linhas.find(l => Number.isNaN(extratoDe(l)));
            if (invalida) return erro(`Saldo do extrato de ${invalida.nome} inválido. Use só números (ex: 1.234,56).`);
            if (linhas.some(l => temDif(l) && l.acao === 'ajuste' && !String(l.motivo || '').trim())) return erro('Informe o motivo do ajuste.');
            st.passo = 2; mostrar();
        };
    }

    function passo2() {
        const p = pend();
        const venc = x => ` · vence ${_fechDiaBR(x.data_vencimento)}`;
        const veAba = { pagar: temAcesso('financeiro.pagar', 'visualizar'), receber: temAcesso('financeiro.receber', 'visualizar') };
        const item = (desc, valor, tab, rotuloBotao) => `<div class="fech-pend-item"><span class="fech-pend-desc">${desc}</span>${valor != null ? `<strong>${_resBrl(valor)}</strong>` : ''}${veAba[tab] ? `<button class="btn btn-outline btn-sm" onclick="_fechAtalho('${tab}')">${rotuloBotao}</button>` : ''}</div>`;
        let html = '';
        if (p.pagar.length) html += `<h4 class="fech-sub">Contas a pagar em aberto (${p.pagar_qtd} · ${_resBrl(p.pagar_valor)})</h4>`
            + p.pagar.map(x => { const cred = x.credor_nome || x.fornecedor || ''; return item(escapeHtml(x.descricao || '') + `<small>${escapeHtml(cred)}${cred ? ' · ' : ''}${venc(x).slice(3)}</small>`, x.valor, 'pagar', 'Abrir A Pagar'); }).join('');
        if (p.receber.length) html += `<h4 class="fech-sub">Clientes que não pagaram (${p.receber_qtd} · ${_resBrl(p.receber_valor)})</h4>`
            + p.receber.map(x => item(escapeHtml(x.cliente_nome || '') + `<small>${escapeHtml(x.descricao || '')}${venc(x)}</small>`, x.valor, 'receber', 'Abrir A Receber')).join('');
        if (p.guia_pendente) html += `<h4 class="fech-sub">Imposto</h4>` + item(`Guia de imposto de ${escapeHtml(rot)} não lançada<small>o resultado usa o imposto estimado</small>`, null, 'pagar', 'Abrir A Pagar');
        box.innerHTML = titulo(2)
            + (html ? `<p class="fech-texto">Nada aqui impede fechar; os números vão para a foto do mês.</p>${html}` : '<p class="fech-vazio">Nada pendente neste mês.</p>')
            + rodape(BOTAO_CANCELAR + '<button class="btn btn-outline" data-acao="voltar">Voltar</button>', '<button class="btn btn-primary" data-acao="continuar">Continuar</button>');
        box.querySelector('[data-acao="cancelar"]').onclick = cancelar;
        box.querySelector('[data-acao="voltar"]').onclick = () => { st.passo = 1; mostrar(); };
        box.querySelector('[data-acao="continuar"]').onclick = () => { st.passo = 3; mostrar(); };
    }

    // Numeros e sugestoes do mes (os mesmos do Resultado do mes).
    function resumo() {
        const d = _resDados(mes);
        const ant = FechamentoCore.mesAnterior(mes);
        const rAnt = resultadoFinanceiroDoMes(ant);
        const p = pend();
        const sugestoes = FechamentoCore.sugestoesDoMes({
            resultado: d.r.resultado, entradas: d.r.faturamento, meta: d.meta, equilibrio: d.equilibrio, orcamento: d.orcamento,
            porGrupo: d.r.porGrupo, porGrupoAnterior: rAnt.porGrupo, rotuloAnterior: FechamentoCore.rotuloMes(ant),
            pendencias: p, impostoEstimado: d.r.imposto.estimado, rotuloMes: rot, grupos: ResultadoCore.GRUPOS
        });
        return { d, ant, rAnt, p, sugestoes };
    }

    function passo3() {
        const { d, ant, rAnt, sugestoes } = resumo();
        const r = d.r;
        const comp = (rotulo, atual, anterior) => {
            const dif = CaixaCore.arredondar(atual - anterior);
            // Porcentagem arredondada a 0% (ou diferenca zero) tambem e "igual ao mes anterior", nunca "+0%".
            const pctArred = Math.round(anterior * 100) !== 0 ? Math.round(Math.abs(dif / anterior) * 100) : null;
            if (Math.round(dif * 100) === 0 || pctArred === 0) return `<li>${rotulo}: ${_resBrl(atual)} × ${_resBrl(anterior)} em ${escapeHtml(FechamentoCore.rotuloMes(ant))} — igual ao mês anterior</li>`;
            const pct = pctArred != null ? ` (${dif >= 0 ? '+' : '−'}${pctArred}%)` : '';
            return `<li>${rotulo}: ${_resBrl(atual)} × ${_resBrl(anterior)} em ${escapeHtml(FechamentoCore.rotuloMes(ant))} — ${_fechDifTxt(dif)}${pct}</li>`;
        };
        const meta = d.meta > 0 ? ` · meta ${_resBrl(d.meta)} (${Math.round(r.faturamento / d.meta * 100)}% da meta)` : ' · sem meta definida';
        const maiores = FechamentoCore.maioresGastos(r.porGrupo, 3, ResultadoCore.GRUPOS);
        const estourados = d.orcamento.filter(o => o.faixa === 'estourou');
        box.innerHTML = titulo(3)
            + `<div class="fech-kpis"><div><span>Entradas</span><strong>${_resBrl(r.entradas)}</strong></div><div><span>Saídas</span><strong>${_resBrl(r.saidas)}</strong></div><div><span>Resultado</span><strong class="${r.resultado < 0 ? 'res-neg' : 'res-pos'}">${_resBrl(r.resultado)}</strong></div></div>`
            + `<div class="fech-texto">Imposto ${r.imposto.estimado ? 'estimado' : 'lançado'}: ${_resBrl(r.imposto.valor)} · faturamento líquido ${_resBrl(r.faturamento)}${meta}</div>`
            + `<h4 class="fech-sub">Saídas por grupo</h4><table class="fech-tabela"><tbody>${ResultadoCore.GRUPOS.map(g => `<tr><td>${escapeHtml(g.rotulo)}${g.id === 'imposto' && r.imposto.estimado ? ' <small class="fech-vazio">(estimado)</small>' : ''}</td><td style="text-align:right">${_resBrl(r.porGrupo[g.id])}</td></tr>`).join('')}</tbody></table>`
            + `<h4 class="fech-sub">Comparação com ${escapeHtml(FechamentoCore.rotuloMes(ant))}</h4><ul class="fech-lista">${comp('Resultado', r.resultado, rAnt.resultado)}${comp('Entradas', r.entradas, rAnt.entradas)}</ul>`
            + `<h4 class="fech-sub">Maiores gastos</h4>${maiores.length ? `<ul class="fech-lista">${maiores.map(m => `<li>${escapeHtml(m.rotulo)}: ${_resBrl(m.valor)}</li>`).join('')}</ul>` : '<p class="fech-vazio">Nenhum gasto no mês.</p>'}`
            + `<h4 class="fech-sub">Orçamentos estourados</h4>${estourados.length ? `<ul class="fech-lista">${estourados.map(o => `<li class="res-faixa-estourou">${escapeHtml(o.rotulo)}: estourou ${_resBrl(-o.falta)}</li>`).join('')}</ul>` : '<p class="fech-vazio">Nenhum orçamento estourado.</p>'}`
            + `<h4 class="fech-sub">Sugestões para o próximo mês</h4><ul class="fech-lista fech-sugestoes">${sugestoes.map(s => `<li>${escapeHtml(s)}</li>`).join('')}</ul>`
            + `<div class="form-group" style="margin-top:12px"><label for="fech-anotacoes">Anotações</label><textarea id="fech-anotacoes" rows="3">${escapeHtml(st.anotacoes)}</textarea></div>`
            + rodape(BOTAO_CANCELAR + '<button class="btn btn-outline" data-acao="voltar">Voltar</button>', `<button class="btn btn-primary" id="fech-confirmar">🔒 Fechar ${escapeHtml(rot)}</button>`);
        box.querySelector('#fech-anotacoes').addEventListener('input', e => { st.anotacoes = e.target.value; });
        box.querySelector('[data-acao="cancelar"]').onclick = cancelar;
        box.querySelector('[data-acao="voltar"]').onclick = () => { st.passo = 2; mostrar(); };
        box.querySelector('#fech-confirmar').onclick = confirmar;
    }

    let gravando = false;
    function confirmar() {
        if (gravando) return;
        gravando = true;
        const btn = document.getElementById('fech-confirmar');
        if (btn) btn.disabled = true;
        if (fechamentoDoMes(mes)) { fechar(); renderResultadoMes(mes); return; }
        if (!Array.isArray(db.movimentos_fin)) db.movimentos_fin = [];
        const novoId = _novosIdsFin(db.movimentos_fin);
        const contas = linhas.map(l => {
            const extrato = extratoDe(l);
            const conferida = extrato != null && !Number.isNaN(extrato);
            const dif = conferida ? difDe(l) : null;
            const acao = conferida && temDif(l) ? l.acao : null;
            const motivo = acao === 'ajuste' ? String(l.motivo || '').trim() : '';
            if (acao === 'ajuste') {
                db.movimentos_fin.push({
                    id: novoId(), conta_id: l.conta_id, data: ultimo, sentido: dif < 0 ? 'saida' : 'entrada', valor: CaixaCore.arredondar(Math.abs(dif)),
                    origem: 'ajuste', origem_id: null, grupo_id: null, fechamento_mes: mes,
                    descricao: `Ajuste da conferência de ${_fechMaiusc(rot)}: ${motivo}`
                });
                _finContaTocada(l.conta_id);
            }
            return { conta_id: l.conta_id, nome: l.nome, esperado: l.esperado, extrato: conferida ? CaixaCore.arredondar(extrato) : null, diferenca: dif, acao, motivo };
        });
        const { d, p, sugestoes } = resumo();
        const foto = FechamentoCore.montarFoto({
            mes, agoraISO: new Date().toISOString(), usuario: nomeExibicao(getUsuarioLogado()), r: d.r, meta: d.meta, contas,
            pendencias: { pagar_qtd: p.pagar_qtd, pagar_valor: p.pagar_valor, receber_qtd: p.receber_qtd, receber_valor: p.receber_valor, guia_pendente: p.guia_pendente },
            sugestoes, anotacoes: String(st.anotacoes || '').trim()
        });
        db.fechamentos_fin = (Array.isArray(db.fechamentos_fin) ? db.fechamentos_fin : []).filter(f => f && f.mes !== mes);
        db.fechamentos_fin.push(foto);
        syncDB();
        fechar();
        renderResultadoMes(mes);
        verFechamentoMes(mes);
    }

    function mostrar() {
        if (st.passo === 1) passo1(); else if (st.passo === 2) passo2(); else passo3();
        box.scrollTop = 0;
    }
    document.body.appendChild(o);
    mostrar();
    box.querySelector('.fech-extrato')?.focus();
}

// Apaga a foto e os ajustes lancados por este fechamento e reabre o passo a passo.
async function refazerFechamentoMes(mes) {
    if (!temAcesso('financeiro.resultado', 'completo')) { showAlert('Você não tem permissão para realizar esta ação.', '🚫'); return; }
    if (!fechamentoDoMes(mes)) return;
    const ok = await showConfirm(`Refazer o fechamento de ${FechamentoCore.rotuloMes(mes)}? A foto e os ajustes lançados nele serão apagados.`, '🔒', 'Refazer', 'Cancelar');
    if (!ok) return;
    db.fechamentos_fin = (db.fechamentos_fin || []).filter(f => f && f.mes !== mes);
    (db.movimentos_fin || []).filter(m => m && m.origem === 'ajuste' && m.fechamento_mes === mes).forEach(m => _finContaTocada(m.conta_id));
    db.movimentos_fin = (db.movimentos_fin || []).filter(m => !(m && m.origem === 'ajuste' && m.fechamento_mes === mes));
    syncDB();
    renderResultadoMes(mes);
    abrirFechamentoMes(mes);
}

// Documento do fechamento: sempre a foto (o que foi fechado), com o aviso se o mes mudou depois.
function verFechamentoMes(mes) {
    if (!temAcesso('financeiro.resultado', 'visualizar')) { showAlert('Você não tem permissão para realizar esta ação.', '🚫'); return; }
    const foto = fechamentoDoMes(mes);
    if (!foto) return;
    const rot = FechamentoCore.rotuloMes(mes);
    const n = foto.numeros || {};
    const td = 'padding:6px 8px;border-bottom:1px solid #ddd';
    const th = `${td};text-align:left;background:#f0f0f0`;
    const mudancas = mudancasDoFechamento(mes);
    const avisos = _fechTextosMudanca(mes, mudancas);
    const guia = _fechTextosGuia(mudancas);
    const grupos = ResultadoCore.GRUPOS.map(g => `<tr><td style="${td}">${escapeHtml(g.rotulo)}${g.id === 'imposto' && n.imposto_estimado ? ' (estimado)' : ''}</td><td style="${td};text-align:right">${_resBrl((n.por_grupo || {})[g.id])}</td></tr>`).join('');
    const situacao = c => c.extrato == null ? 'não conferida'
        : (c.acao === 'ajuste' ? `ajuste lançado — ${c.motivo || ''}` : (c.acao === 'anotado' ? 'diferença anotada' : 'confere'));
    const contas = (foto.contas || []).map(c => `<tr><td style="${td}">${escapeHtml(c.nome || '')}</td><td style="${td};text-align:right">${_resBrl(c.esperado)}</td><td style="${td};text-align:right">${c.extrato == null ? '—' : _resBrl(c.extrato)}</td><td style="${td};text-align:right">${c.diferenca == null ? '—' : _fechDifTxt(c.diferenca)}</td><td style="${td}">${escapeHtml(situacao(c))}</td></tr>`).join('');
    const pd = foto.pendencias || {};
    const pend = [];
    if (pd.pagar_qtd) pend.push(`${pd.pagar_qtd} ${pd.pagar_qtd === 1 ? 'conta' : 'contas'} a pagar em aberto (${_resBrl(pd.pagar_valor)})`);
    if (pd.receber_qtd) pend.push(`${pd.receber_qtd} ${pd.receber_qtd === 1 ? 'conta' : 'contas'} a receber em aberto (${_resBrl(pd.receber_valor)})`);
    if (pd.guia_pendente) pend.push('Guia de imposto do mês não lançada (imposto estimado)');
    const meta = Number(n.meta) > 0 ? `Meta ${_resBrl(n.meta)}` : 'Sem meta definida';
    const html = `<div style="padding:24px;color:#242424">
        <div class="doc-cab">${buildEmpresaHeaderHTML(52)}</div>
        <h2 style="margin:16px 0 4px">Fechamento de ${escapeHtml(rot)}</h2>
        ${avisos.length ? `<div class="index-card-3d" style="background:#FFF6DB;border:1px solid #B26A00;border-radius:6px;color:#7A4A00;padding:8px 12px;margin:10px 0;font-size:13px">${avisos.map(t => `<div>${escapeHtml(t)}</div>`).join('')}</div>` : ''}
        ${guia.length ? `<div class="fech-info-doc index-card-3d" style="background:#F0F4F8;border:1px solid #8A9BB0;border-radius:6px;color:#33475B;padding:8px 12px;margin:10px 0;font-size:13px">${guia.map(t => `<div>${escapeHtml(t)}</div>`).join('')}</div>` : ''}
        <div style="display:flex;gap:32px;margin:12px 0;font-size:14px;flex-wrap:wrap">
            <div>Entradas<br><strong style="font-size:18px">${_resBrl(n.entradas)}</strong></div>
            <div>Saídas<br><strong style="font-size:18px">${_resBrl(n.saidas)}</strong></div>
            <div>Resultado<br><strong style="font-size:18px;color:${Number(n.resultado) < 0 ? '#F43927' : '#005D3B'}">${_resBrl(n.resultado)}</strong></div>
        </div>
        <div style="font-size:13px;margin-bottom:12px">Imposto ${n.imposto_estimado ? 'estimado' : 'lançado'}: ${_resBrl(n.imposto)} · ${meta}</div>
        <table style="width:100%;border-collapse:collapse;font-size:13px"><thead><tr><th style="${th}">Saídas por grupo</th><th style="${th};text-align:right">Valor</th></tr></thead><tbody>${grupos}</tbody></table>
        <h3 style="margin:18px 0 6px;font-size:15px">Conferência das contas</h3>
        ${contas ? `<table style="width:100%;border-collapse:collapse;font-size:13px"><thead><tr><th style="${th}">Conta</th><th style="${th};text-align:right">Esperado</th><th style="${th};text-align:right">Extrato</th><th style="${th};text-align:right">Diferença</th><th style="${th}">Situação</th></tr></thead><tbody>${contas}</tbody></table>` : '<div style="font-size:13px">Nenhuma conta conferida.</div>'}
        <h3 style="margin:18px 0 6px;font-size:15px">Pendências</h3>
        <div style="font-size:13px">${pend.length ? pend.map(t => `<div>${escapeHtml(t)}</div>`).join('') : 'Nada pendente neste mês.'}</div>
        <h3 style="margin:18px 0 6px;font-size:15px">Sugestões para o próximo mês</h3>
        <ul style="font-size:13px;margin:0;padding-left:20px">${(foto.sugestoes || []).map(s => `<li>${escapeHtml(s)}</li>`).join('')}</ul>
        ${foto.anotacoes ? `<h3 style="margin:18px 0 6px;font-size:15px">Anotações</h3><div style="font-size:13px;white-space:pre-wrap">${escapeHtml(foto.anotacoes)}</div>` : ''}
        <div style="font-size:12px;color:#666;margin-top:18px">Fechado em ${escapeHtml(_fechDataBR(foto.fechado_em))} por ${escapeHtml(foto.fechado_por || '')}</div>
    </div>`;
    const tit = 'Fechamento de ' + rot;
    abrirDocModal(html, tit, '', envioDocumentoInterno(tit, 'Fechamento-' + mes));
}

// =============================================
// FINANCEIRO — TELA "HOJE"
// =============================================

let _chartHoje = null;

// Tarefas do dia (esquerda) + saldos e previsao das proximas semanas (direita).
// Recebi/Cobrar/Paguei recarregam a pagina (salvarERecarregar), que reabre em Hoje.
function renderHoje() {
    const elT = document.getElementById('hoje-tarefas');
    if (!elT) return;
    const hoje = hojeLocal();
    const brl = v => 'R$ ' + (Number(v) || 0).toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
    const fmtData = d => String(d || '').split('-').reverse().join('/');
    const ddmm = d => d.slice(8, 10) + '/' + d.slice(5, 7);
    const todasContas = getContasFin();
    const movs = Array.isArray(db.movimentos_fin) ? db.movimentos_fin : [];
    const t = CaixaCore.tarefasHoje({ hoje, contasReceber: db.contas_receber, contasPagar: db.contas_pagar, movimentos: movs, contas: todasContas });

    const podeReceber = temAcesso('financeiro.receber', 'completo');
    const podePagar = temAcesso('financeiro.pagar', 'completo');
    const jid = id => escapeHtml(JSON.stringify(id));
    const grupo = (chave, titulo, cor, itens, linha) => itens.length
        ? `<div class="hoje-grupo hoje-${cor}" data-grupo="${chave}"><h4>${titulo}</h4>${itens.map(linha).join('')}</div>` : '';
    const linhaCR = cr => `<div class="hoje-item">
        <div class="hoje-item-desc">${escapeHtml(cr.cliente_nome || '')}<small>${escapeHtml(cr.descricao || '')} · vence ${fmtData(cr.data_vencimento)}</small></div>
        <div class="hoje-item-valor">${brl(cr.valor)}</div>
        ${cr.ultima_cobranca === hoje ? '<small style="color:var(--muted);white-space:nowrap">cobrado hoje</small>' : ''}
        ${podeReceber ? `<button class="btn btn-outline btn-sm btn-whats" onclick='cobrarNoWhatsApp(${jid(cr.id)})' title="Enviar por WhatsApp">${iconeWhatsApp(16)}<span>Cobrar</span></button>
        <button class="btn btn-success btn-sm" onclick='marcarCRPago(${jid(cr.id)})'>✓ Recebi</button>` : ''}</div>`;
    const credorCP = cp => cp.credor_nome || cp.fornecedor || '';
    const linhaCP = cp => `<div class="hoje-item">
        <div class="hoje-item-desc">${escapeHtml(cp.descricao || '')}<small>${escapeHtml(credorCP(cp))}${credorCP(cp) ? ' · ' : ''}vence ${fmtData(cp.data_vencimento)}</small></div>
        <div class="hoje-item-valor">${brl(cp.valor)}</div>
        ${podePagar ? `<button class="btn btn-success btn-sm" onclick='marcarCPPago(${jid(cp.id)})'>✓ Paguei</button>` : ''}</div>`;
    const linhaCartao = m => {
        const c = todasContas.find(x => CaixaCore.mesmoId(x.id, m.conta_id));
        return `<div class="hoje-item"><div class="hoje-item-desc">${escapeHtml(m.descricao || 'Repasse do cartão')}<small>${escapeHtml(c ? c.nome : '')}</small></div><div class="hoje-item-valor">${brl(m.liquido != null ? m.liquido : m.valor)} <small style="color:var(--muted)">líquido</small></div></div>`;
    };
    // As tarefas seguem a permissao de ver: quem nao ve A Receber/A Pagar nao ve as tarefas de la.
    const veReceber = temAcesso('financeiro.receber', 'visualizar');
    const vePagar = temAcesso('financeiro.pagar', 'visualizar');
    const html = grupo('receber-atrasados', 'A receber — atrasados', 'vermelho', veReceber ? t.receberAtrasados : [], linhaCR)
        + grupo('receber-hoje', 'A receber hoje', 'amarelo', veReceber ? t.receberHoje : [], linhaCR)
        + grupo('pagar-atrasados', 'A pagar — atrasados', 'vermelho', vePagar ? t.pagarAtrasados : [], linhaCP)
        + grupo('pagar-proximos', 'A pagar nos próximos 7 dias', 'cinza', vePagar ? t.pagarProximos : [], linhaCP)
        + grupo('cartao-hoje', 'Cartão que cai hoje', 'info', t.cartaoHoje, linhaCartao);
    // Orcamento estourado no mes atual (mesma regra do Resultado do mes), so para quem ve o Resultado.
    let avisoOrc = '';
    if (typeof ResultadoCore !== 'undefined' && temAcesso('financeiro.resultado', 'visualizar')) {
        const mesAt = hoje.slice(0, 7);
        const estourados = orcamentoFinanceiroDoMes(mesAt, resultadoFinanceiroDoMes(mesAt).porGrupo).filter(o => o.faixa === 'estourou');
        if (estourados.length) avisoOrc = `<div id="hoje-orcamento">${estourados.map(o =>
            `<div class="hoje-orcamento-linha" data-grupo="${escapeHtml(o.grupo)}">Orçamento de ${escapeHtml(o.rotulo)} estourado: ${brl(-o.falta)} acima</div>`).join('')}</div>`;
    }
    // Fechamento do mes anterior: lembrete de fechar, ou aviso se o mes fechado mudou depois.
    let avisoFech = '';
    if (FIN_RECURSOS_ANTIGOS.fechamento && typeof FechamentoCore !== 'undefined' && temAcesso('financeiro.resultado', 'visualizar')) {
        const pode = temAcesso('financeiro.resultado', 'completo');
        const mesFech = FechamentoCore.mesParaFechar({ hoje, fechamentos: db.fechamentos_fin, temContas: todasContas.length > 0 });
        let linha = '';
        if (mesFech) {
            const acao = pode ? `mostrarTabFinanceiro('resultado');renderResultadoMes('${mesFech}');abrirFechamentoMes('${mesFech}')`
                : `mostrarTabFinanceiro('resultado');renderResultadoMes('${mesFech}')`;
            linha = `<div class="hoje-fechamento-linha"><span>Feche o mês de ${escapeHtml(FechamentoCore.rotuloMes(mesFech))}</span>
                <button class="btn btn-primary btn-sm" onclick="${acao}">${pode ? 'Fechar agora' : 'Ver'}</button></div>`;
        } else {
            const mesAnt = FechamentoCore.mesAnterior(hoje.slice(0, 7));
            const mudancas = fechamentoDoMes(mesAnt) ? mudancasDoFechamento(mesAnt) : [];
            const ver = `<button class="btn btn-outline btn-sm" onclick="mostrarTabFinanceiro('resultado');renderResultadoMes('${mesAnt}')">Ver</button>`;
            if (_fechSoMudancas(mudancas).length) {
                linha = `<div class="hoje-fechamento-linha hoje-fechamento-mudou"><span>⚠ ${escapeHtml(_fechMaiusc(FechamentoCore.rotuloMes(mesAnt)))} mudou depois do fechamento</span>
                    ${ver}</div>`;
            }
            linha += _fechTextosGuia(mudancas).map(t => `<div class="hoje-fechamento-linha hoje-fechamento-info"><span>${escapeHtml(t)}</span>${ver}</div>`).join('');
        }
        if (linha) avisoFech = `<div id="hoje-fechamento">${linha}</div>`;
    }
    elT.innerHTML = avisoFech + avisoOrc + (html || '<p style="color:#888;margin:0">Tudo em dia 👍</p>');

    // Lado direito: so com permissao de ver o Extrato.
    const lado = document.getElementById('hoje-lado');
    const grid = document.querySelector('#fin-hoje .hoje-grid');
    const veLado = temAcesso('financeiro.fluxo', 'visualizar');
    if (lado) lado.classList.toggle('hoje-sem-lado', !veLado);
    if (grid) grid.classList.toggle('hoje-sem-lado-grid', !veLado);
    if (_chartHoje) { _chartHoje.destroy(); _chartHoje = null; }
    if (!veLado) return;

    const contas = todasContas.filter(c => c.ativo !== false);
    const elS = document.getElementById('hoje-saldos');
    const convite = document.getElementById('hoje-convite');
    const cardPrev = document.getElementById('hoje-previsao-card');
    if (!contas.length) {
        elS.innerHTML = '';
        convite.style.display = '';
        convite.innerHTML = '<p style="margin:0 0 8px">Configure suas contas para ver quanto você tem</p><a class="btn btn-primary btn-sm" href="empresa.html#preferencias">Configurar contas</a>';
        if (cardPrev) cardPrev.style.display = 'none';
        return;
    }
    convite.style.display = 'none';
    if (cardPrev) cardPrev.style.display = '';
    const sd = CaixaCore.saldosHoje(contas, movs, hoje);
    elS.innerHTML = `<div class="hoje-total">Total <span id="hoje-total">${brl(sd.total)}</span></div>` + sd.contas.map(c =>
        `<div class="hoje-conta" role="button" tabindex="0" onclick='abrirExtratoDaConta(${jid(c.id)})' onkeydown="if(event.key==='Enter'||event.key===' '){event.preventDefault();abrirExtratoDaConta(${jid(c.id)})}"><span>${escapeHtml(c.nome || '')}${c.a_cair > 0 ? `<small>${brl(c.a_cair)} a cair</small>` : ''}</span><strong>${brl(c.saldo)}</strong></div>`).join('');

    const semanas = CaixaCore.previsaoSemanal({ hoje, saldoHoje: sd.total, movimentos: movs, contasReceber: db.contas_receber, contasPagar: db.contas_pagar, despesasFixas: db.despesas_fixas, contas: todasContas, meios: getMeiosPag(), semanas: 8 });
    const neg = CaixaCore.primeiraSemanaNegativa(semanas);
    document.getElementById('hoje-previsao-aviso').textContent = neg ? `Semana de ${ddmm(neg.inicio)}: falta ${brl(neg.falta)}` : '';
    document.getElementById('hoje-previsao-legenda').textContent = semanas.some(s => s.inclui_atrasados) ? '* inclui atrasados' : '';
    const cv = document.getElementById('chart-hoje-previsao');
    if (cv && typeof Chart !== 'undefined') {
        _chartHoje = new Chart(cv, {
            type: 'bar',
            data: {
                labels: semanas.map(s => ddmm(s.inicio) + (s.inclui_atrasados ? '*' : '')),
                datasets: [{ label: 'Saldo no fim da semana', data: semanas.map(s => s.saldo_final), backgroundColor: semanas.map(s => s.saldo_final < 0 ? '#F43927' : '#159912') }]
            },
            options: { responsive: true, maintainAspectRatio: false, plugins: { legend: { display: false }, tooltip: { callbacks: { label: ctx => brl(ctx.parsed.y) } } } }
        });
    }
}

// =============================================
// FINANCEIRO — SIMULAR COMPRA
// =============================================

// Ultima simulacao valida (o que "Lancar no A Pagar" grava). null = nada para lancar.
let _simUltima = null;
let _simLancando = false;
const _SIM_VAZIO = 'Preencha a compra e clique em Simular para ver se cabe no caixa das próximas 8 semanas.';

function _simForma() {
    const r = document.querySelector('input[name="sim-forma"]:checked');
    return r ? r.value : 'avista';
}

function simAtualizarForma() {
    const forma = _simForma();
    const mostra = (id, sim) => { const el = document.getElementById(id); if (el) el.style.display = sim ? '' : 'none'; };
    mostra('sim-parcelas-grupo', forma !== 'avista');
    mostra('sim-primeira-grupo', forma !== 'avista');
    mostra('sim-entrada-grupo', forma === 'entrada');
}

function _simSomarDias(data, dias) {
    return dataLocal(new Date(Number(data.slice(0, 4)), Number(data.slice(5, 7)) - 1, Number(data.slice(8, 10)) + dias).getTime());
}

// A 1a parcela acompanha a data da compra (+30 dias) ate o usuario mexer nela.
let _simPrimeiraManual = false;
let _simEventosLigados = false;

// Mudou algo que entra na conta: a simulacao mostrada ficou velha (some o resultado e o Lancar).
function _simInvalidar() {
    if (!_simUltima && !document.getElementById('sim-lancar') && !document.querySelector('#sim-resultado .sim-veredito')) return;
    _simUltima = null;
    _simSaidaVazia('Os dados da compra mudaram. Clique em Simular para ver de novo.');
}

function _simLigarEventos() {
    if (_simEventosLigados) return;
    _simEventosLigados = true;
    ['sim-valor', 'sim-parcelas', 'sim-entrada', 'sim-data', 'sim-primeira', 'sim-ganho'].forEach(id => {
        const el = document.getElementById(id);
        if (!el) return;
        el.addEventListener('input', _simInvalidar);
        el.addEventListener('change', _simInvalidar);
    });
    document.querySelectorAll('input[name="sim-forma"]').forEach(r => r.addEventListener('change', _simInvalidar));
    const primeira = document.getElementById('sim-primeira');
    if (primeira) primeira.addEventListener('input', () => { _simPrimeiraManual = true; });
    const data = document.getElementById('sim-data');
    const segue = () => {
        if (_simPrimeiraManual || !primeira || !/^\d{4}-\d{2}-\d{2}$/.test(data.value)) return;
        primeira.value = _simSomarDias(data.value, 30);
    };
    if (data) { data.addEventListener('input', segue); data.addEventListener('change', segue); }
}

function renderSimulador() {
    if (!document.getElementById('fin-simulador')) return;
    _simLigarEventos();
    const hoje = hojeLocal();
    const data = document.getElementById('sim-data');
    const primeira = document.getElementById('sim-primeira');
    if (data && !data.value) data.value = hoje;
    if (primeira && !primeira.value) primeira.value = _simSomarDias(data && data.value ? data.value : hoje, 30);
    simAtualizarForma();
    // Ao entrar na aba, nada de resultado velho (os dados do caixa podem ter mudado).
    _simUltima = null;
    _simMostrarErro('');
    _simSaidaVazia(_SIM_VAZIO);
}

// As 8 semanas da tela Hoje (mesma chamada), com pagamentos extras como contas a pagar em aberto.
function _simPrevisao(pagamentosExtras) {
    const hoje = hojeLocal();
    const contas = getContasFin().filter(c => c.ativo !== false);
    const movs = Array.isArray(db.movimentos_fin) ? db.movimentos_fin : [];
    const sd = CaixaCore.saldosHoje(contas, movs, hoje);
    const extras = pagamentosExtras && pagamentosExtras.length ? SimuladorCore.pagamentosComoContas(pagamentosExtras) : [];
    return CaixaCore.previsaoSemanal({ hoje, saldoHoje: sd.total, movimentos: movs, contasReceber: db.contas_receber, contasPagar: (db.contas_pagar || []).concat(extras), despesasFixas: db.despesas_fixas, contas: getContasFin(), meios: getMeiosPag(), semanas: 8 });
}

// Media do resultado dos 3 meses mais recentes antes do atual que tiveram movimento (ate 12 para tras).
function _simResultadoMedio(mesAtual) {
    const resultados = [];
    for (let i = 1; i <= 12 && resultados.length < 3; i++) {
        const r = resultadoFinanceiroDoMes(ResultadoCore.somarMeses(mesAtual, -i));
        if (r.entradas !== 0 || r.saidas !== 0) resultados.push(r.resultado);
    }
    return SimuladorCore.resultadoMedio(resultados);
}

function _simMostrarErro(msg) {
    const e = document.getElementById('sim-erro');
    if (e) { e.textContent = msg || ''; e.style.display = msg ? '' : 'none'; }
}

function _simSaidaVazia(texto) {
    const saida = document.getElementById('sim-resultado');
    if (saida) saida.innerHTML = `<p class="sim-vazio">${escapeHtml(texto)}</p>`;
}

const _simEhAvulsa = p => p.rotulo === 'À vista' || p.rotulo === 'Entrada';

function simularCompra() {
    const saida = document.getElementById('sim-resultado');
    if (!saida) return;
    _simUltima = null;
    if (!getContasFin().some(c => c.ativo !== false)) {
        _simMostrarErro('');
        saida.innerHTML = '<p class="sim-vazio" id="sim-sem-contas">Configure suas contas para simular.</p><a class="btn btn-primary btn-sm" href="empresa.html#preferencias">Configurar contas</a>';
        return;
    }
    const val = id => (document.getElementById(id)?.value || '').trim();
    const ddmm = d => d.slice(8, 10) + '/' + d.slice(5, 7);
    const ehData = d => /^\d{4}-\d{2}-\d{2}$/.test(d);
    const descricao = val('sim-desc');
    const forma = _simForma();
    const dataCompra = val('sim-data');
    const dataPrimeira = val('sim-primeira');
    const valorTotal = _valorDigitadoBaixa(val('sim-valor'), NaN);
    let erro = '';
    if (!descricao) erro = 'Informe a descrição da compra.';
    else if (!['avista', 'parcelado', 'entrada'].includes(forma)) erro = 'Escolha a forma de pagamento.';
    else if (!ehData(dataCompra)) erro = 'Informe a data da compra.';
    else if (forma !== 'avista' && !ehData(dataPrimeira)) erro = 'Informe a data da 1ª parcela.';
    let r = null;
    if (!erro) {
        r = SimuladorCore.pagamentosDaCompra({
            valor: valorTotal, forma,
            parcelas: val('sim-parcelas') === '' ? NaN : Number(val('sim-parcelas')),
            entrada: _valorDigitadoBaixa(val('sim-entrada'), NaN),
            dataCompra, dataPrimeira
        });
        if (!r.ok) erro = r.erro;
    }
    if (erro) {
        _simMostrarErro(erro);
        _simSaidaVazia('Corrija o formulário e clique em Simular.');
        return;
    }
    _simMostrarErro('');
    const pagamentos = r.pagamentos;
    const hoje = hojeLocal();
    const semanasSem = _simPrevisao([]);
    const semanasCom = _simPrevisao(pagamentos);
    const fim = semanasCom.length ? semanasCom[semanasCom.length - 1].fim : hoje;
    const ganho = _valorDigitadoBaixa(val('sim-ganho'), NaN);
    const parcelas = pagamentos.filter(p => !_simEhAvulsa(p));
    const v = SimuladorCore.veredito({
        semanasSem, semanasCom,
        folga: ResultadoCore.despesasFixasDoMes({ mes: hoje.slice(0, 7), contasPagar: db.contas_pagar, despesasFixas: db.despesas_fixas }) / 2,
        parcelaMensal: parcelas.length ? parcelas[0].valor : pagamentos[0].valor,
        temParcelaAlem: pagamentos.some(p => p.data > fim),
        resultadoMedio: _simResultadoMedio(hoje.slice(0, 7)),
        ganhoMensal: ganho > 0 ? ganho : 0,
        valorTotal
    });
    const frases = v.frases.slice();
    // Caixa ja negativo sem a compra: a frase do veredito explica; procurar data so confundiria.
    if (v.cor === 'vermelho' && !v.jaNegativoSem) {
        const quando = SimuladorCore.melhorData({ hoje, pagamentos, prever: _simPrevisao });
        const frase = quando ? 'Comprando a partir de ' + ddmm(quando) + ', cabe.' : 'Nas próximas 8 semanas não cabe — tente parcelar em mais vezes ou dar uma entrada menor.';
        const iPay = frases.findIndex(f => f.startsWith('Se paga em'));
        if (iPay >= 0) frases.splice(iPay, 0, frase); else frases.push(frase);
    }
    _simUltima = { forma, pagamentos, qtdParcelas: parcelas.length };
    const celula = x => `<td class="sim-num${x < 0 ? ' res-neg' : ''}">${escapeHtml(_resBrl(x))}</td>`;
    const linhas = semanasCom.map((s, i) => `<tr><td>${ddmm(s.inicio)} a ${ddmm(s.fim)}</td>${celula(semanasSem[i].saldo_final)}${celula(s.saldo_final)}</tr>`).join('');
    const pode = temAcesso('financeiro.simulador', 'completo');
    saida.innerHTML = `<div class="sim-veredito sim-${v.cor}">
            <h3 id="sim-titulo" class="sim-titulo sim-${v.cor}">${escapeHtml(v.titulo)}</h3>
            <ul id="sim-frases" class="sim-frases">${frases.map(f => `<li>${escapeHtml(f)}</li>`).join('')}</ul>
        </div>
        <div class="sim-tabela-wrap"><table class="sim-tabela">
            <thead><tr><th>Semana</th><th class="sim-num">Saldo sem a compra</th><th class="sim-num">Saldo com a compra</th></tr></thead>
            <tbody>${linhas}</tbody>
        </table></div>
        ${pode ? '<div class="sim-botoes"><button class="btn btn-success" id="sim-lancar" onclick="lancarSimulacaoNoPagar()">Lançar no A Pagar</button></div>' : ''}`;
}

function limparSimulador() {
    _simUltima = null;
    ['sim-desc', 'sim-valor', 'sim-parcelas', 'sim-entrada', 'sim-ganho', 'sim-credor', 'sim-data', 'sim-primeira'].forEach(id => { const el = document.getElementById(id); if (el) el.value = ''; });
    const cat = document.getElementById('sim-categoria'); if (cat) cat.value = 'outro';
    const av = document.querySelector('input[name="sim-forma"][value="avista"]'); if (av) av.checked = true;
    _simPrimeiraManual = false;
    renderSimulador();
}

// Cria as contas a pagar como o parcelado do A Pagar: entrada/a vista avulsa, parcelas agrupadas.
async function lancarSimulacaoNoPagar() {
    if (!temAcesso('financeiro.simulador', 'completo')) return;
    if (_simLancando || !_simUltima) return;
    // Descricao, categoria e credor nao mudam a conta: valem os do formulario na hora de lancar.
    const val = id => (document.getElementById(id)?.value || '').trim();
    const descricao = val('sim-desc');
    if (!descricao) { _simMostrarErro('Informe a descrição da compra.'); return; }
    _simMostrarErro('');
    const sim = { ..._simUltima, descricao, categoria: val('sim-categoria') || 'outro', credor: val('sim-credor') };
    const ultima = _simUltima;
    const btn = document.getElementById('sim-lancar');
    _simLancando = true;
    if (btn) btn.disabled = true;
    try {
        const n = sim.qtdParcelas;
        const msg = sim.forma === 'avista' ? 'Lançar 1 conta no A Pagar?'
            : sim.forma === 'parcelado' ? `Lançar ${n} parcelas no A Pagar?`
            : `Lançar 1 entrada + ${n} parcelas no A Pagar?`;
        if (!(await showConfirm(msg, '🧮', 'Lançar')) || _simUltima !== ultima) return;
        const paiId = Date.now();
        const base = { pedido_id: null, tipo: 'variavel', categoria: sim.categoria, credor_nome: sim.credor, data_pagamento: null, status: 'Pendente' };
        const mesRefDe = venc => (sim.categoria === 'imposto' ? { mes_referencia: _mesRefImposto(venc) } : {});
        let i = 0;
        sim.pagamentos.forEach(p => {
            if (_simEhAvulsa(p)) {
                // Avulsa: id depois das parcelas, para nunca coincidir com o lancamento_pai_id.
                db.contas_pagar.push(finCompletarLancamento('cp', { id: paiId + n + 1, ...base, descricao: sim.descricao, valor: p.valor, data_vencimento: p.data, ...mesRefDe(p.data) }, null, 'Lançado pelo simulador'));
            } else {
                i++;
                db.contas_pagar.push(finCompletarLancamento('cp', {
                    id: paiId + i, ...base, descricao: `${sim.descricao} (parcela ${i}/${n})`, valor: p.valor, data_vencimento: p.data,
                    lancamento_pai_id: paiId, parcelado: true, numero_parcelas: n, parcela_atual: i, ...mesRefDe(p.data)
                }, null, 'Lançado pelo simulador'));
            }
        });
        _simUltima = null;
        syncDB();
        toast('Compra lançada no A Pagar.');
        _simSaidaVazia('Compra lançada. Preencha outra compra e clique em Simular.');
    } finally {
        _simLancando = false;
        if (btn && btn.isConnected) btn.disabled = false;
    }
}

// =============================================
// FINANCEIRO — TRANSFERENCIAS (a tela do Fluxo de caixa fica em js/fin-fluxo.js)
// =============================================

// Abre o Fluxo de caixa ja filtrado numa conta (usado pela tela "Hoje", desligada).
function abrirExtratoDaConta(contaId) {
    if (typeof finFluxo !== 'undefined') finFluxo.contaId = contaId == null ? '' : String(contaId);
    mostrarTabFinanceiro('fluxo');
}

// Transferencia entre contas: duas linhas (saida na origem, entrada no destino)
// ligadas pelo mesmo grupo_id. Nao muda o total, so a distribuicao.
async function abrirModalTransferencia() {
    if (!await exigirPermissao('financeiro.fluxo', 'completo')) return;
    document.getElementById('transf-modal')?.remove();
    const contas = getContasFin().filter(c => c.ativo !== false);
    const opts = contas.map(c => `<option value="${escapeHtml(String(c.id))}">${escapeHtml(c.nome || '')}</option>`).join('');
    const campo = 'width:100%;padding:6px;border:1px solid var(--border-strong);border-radius:4px;font-size:13px;box-sizing:border-box;margin-bottom:10px';
    const o = document.createElement('div');
    o.id = 'transf-modal';
    o.className = 'sc-modal-overlay';
    o.style.display = 'flex';
    o.innerHTML = `<div class="sc-modal-box" style="text-align:left;max-width:420px;width:calc(100% - 32px)">
        <h3 style="margin:0 0 12px;font-size:16px">Transferir entre contas</h3>
        <label style="display:block;font-size:12px;margin-bottom:4px" for="transf-de">De</label>
        <select id="transf-de" style="${campo}">${opts}</select>
        <label style="display:block;font-size:12px;margin-bottom:4px" for="transf-para">Para</label>
        <select id="transf-para" style="${campo}"><option value="">Selecione…</option>${opts}</select>
        <label style="display:block;font-size:12px;margin-bottom:4px" for="transf-valor">Valor</label>
        <input type="text" inputmode="decimal" id="transf-valor" placeholder="0,00" style="${campo}">
        <label style="display:block;font-size:12px;margin-bottom:4px" for="transf-data">Data</label>
        <input type="date" id="transf-data" value="${hojeLocal()}" max="${hojeLocal()}" style="${campo}">
        <div id="transf-erro" style="display:none;color:var(--danger-text);font-size:12px;margin-bottom:10px"></div>
        <div class="sc-modal-btns"><button class="btn btn-outline" id="transf-cancel">Cancelar</button><button class="btn btn-success" id="transf-ok">Transferir</button></div>
    </div>`;
    document.body.appendChild(o);
    const para = o.querySelector('#transf-para');
    const erroEl = o.querySelector('#transf-erro');
    const erro = msg => { erroEl.textContent = msg; erroEl.style.display = msg ? 'block' : 'none'; };
    const fechar = () => { document.removeEventListener('keydown', esc); o.remove(); };
    const esc = e => { if (e.key === 'Escape') fechar(); };
    document.addEventListener('keydown', esc);
    o.querySelector('#transf-cancel').onclick = fechar;
    o.querySelector('#transf-ok').onclick = () => {
        const deId = o.querySelector('#transf-de').value, paraId = para.value;
        const valor = _valorDigitadoBaixa(o.querySelector('#transf-valor').value);
        const data = o.querySelector('#transf-data').value;
        const de = _contaFinPorId(deId), dest = _contaFinPorId(paraId);
        if (!de) return erro('Escolha a conta de origem.');
        if (!dest) return erro('Escolha a conta de destino.');
        if (CaixaCore.mesmoId(de.id, dest.id)) return erro('Escolha uma conta de destino diferente da origem.');
        if (!(valor > 0)) return erro('Informe um valor maior que zero.');
        if (!data) return erro('Informe a data.');
        if (data > hojeLocal()) return erro('A data não pode ser depois de hoje.');
        if (!CaixaCore.contaAceitaMovimento(de, data) || !CaixaCore.contaAceitaMovimento(dest, data))
            return erro('A data é anterior ao saldo inicial de uma das contas.');
        criarTransferenciaFin(de, dest, valor, data);
        syncDB();
        fechar();
        if (typeof renderFinFluxo === 'function') renderFinFluxo();
    };
    o.querySelector('#transf-valor').focus();
}

// Cria o par de movimentos da transferencia (saida na origem, entrada no destino, mesmo grupo_id). Sem validar
// nem gravar (quem chama valida). Devolve { grupo, saida, entrada } (os dois movimentos).
function criarTransferenciaFin(de, dest, valor, data) {
    if (!Array.isArray(db.movimentos_fin)) db.movimentos_fin = [];
    const novoId = _novosIdsFin(db.movimentos_fin);
    const grupo = _novoIdCfgFin(new Set(db.movimentos_fin.map(m => m.grupo_id).filter(g => g != null)));
    const v = CaixaCore.arredondar(valor);
    const saida = { id: novoId(), conta_id: de.id, data, sentido: 'saida', valor: v, origem: 'transferencia', origem_id: null, grupo_id: grupo, descricao: 'Transferência para ' + (dest.nome || '') };
    const entrada = { id: novoId(), conta_id: dest.id, data, sentido: 'entrada', valor: v, origem: 'transferencia', origem_id: null, grupo_id: grupo, descricao: 'Transferência de ' + (de.nome || '') };
    db.movimentos_fin.push(saida, entrada);
    _finContaTocada(de.id);
    _finContaTocada(dest.id);
    return { grupo, saida, entrada };
}

async function excluirTransferencia(grupoId) {
    if (!await exigirPermissao('financeiro.fluxo', 'completo')) return;
    const lados = (db.movimentos_fin || []).filter(m => m.origem === 'transferencia' && m.grupo_id != null && String(m.grupo_id) === String(grupoId));
    if (!lados.length) return;
    if (!await showConfirm('Excluir esta transferência? Os dois lados saem do extrato e os saldos voltam ao que eram.', '🗑️', 'Excluir')) return;
    lados.forEach(m => _finContaTocada(m.conta_id));
    db.movimentos_fin = db.movimentos_fin.filter(m => !lados.includes(m));
    // Linha de extrato que estava ligada a esta transferencia volta a ficar pendente.
    _desligarExtratoSumido();
    syncDB();
    if (typeof renderFinFluxo === 'function') renderFinFluxo();
}

// Alertas do Financeiro (vencimento, atraso, tendencia, meta, gap): a Visao Geral do Financeiro,
// o sino e o card do Painel leem esta mesma lista. Cada item respeita o liga/desliga do seu tipo
// (ALERTAS_TIPOS: fin_*). cor: danger | warning | success | info; aba: onde abrir no Financeiro;
// id: muda quando o conteudo do alerta muda de verdade (e o que faz o sino contar de novo).
function finAlertasCalcular(hojeStr) {
    const fmt = v => (v||0).toLocaleString('pt-BR', { minimumFractionDigits:2, maximumFractionDigits:2 });
    const out = [];
    const add = (tipo, cor, icone, html, aba, id) => out.push({ tipo, cor, icone, html, aba, id });
    // Conta pendente ja vencida conta como atrasada mesmo antes de a tela do Financeiro marcar o status.
    const atrasada = c => c.status === 'Atrasado' || (c.status === 'Pendente' && c.data_vencimento && c.data_vencimento < hojeStr);

    // Vencimentos misturam os dois lados: cada lado so entra para quem pode ver aquela lista.
    const veRec = temAcesso('financeiro.receber', 'visualizar'), vePag = temAcesso('financeiro.pagar', 'visualizar');
    if (alertaAtivo('fin_vencimento')) {
        const venHojeRec = veRec ? db.contas_receber.filter(cr=>cr.status==='Pendente'&&cr.data_vencimento===hojeStr) : [];
        const venHojePag = vePag ? db.contas_pagar.filter(cp=>cp.status==='Pendente'&&cp.data_vencimento===hojeStr) : [];
        if (venHojeRec.length+venHojePag.length) {
            const partes = [];
            if (veRec) partes.push(`${venHojeRec.length} a receber (R$ ${fmt(venHojeRec.reduce((s,x)=>s+x.valor,0))})`);
            if (vePag) partes.push(`${venHojePag.length} a pagar (R$ ${fmt(venHojePag.reduce((s,x)=>s+x.valor,0))})`);
            add('fin_vencimento','warning','⏰',`<strong>${venHojeRec.length+venHojePag.length} conta(s) vencem hoje</strong> — ${partes.join(' · ')}`,
                'lancamentos', 'venc-hoje:' + hojeStr + ':' + venHojeRec.map(x=>x.id).concat(venHojePag.map(x=>'p'+x.id)).join(','));
        }
    }

    if (alertaAtivo('fin_atraso')) {
        const atRec = db.contas_receber.filter(atrasada);
        if (atRec.length)
            add('fin_atraso','danger','❌',`<strong>${atRec.length} recebimento(s) em atraso</strong> — R$ ${fmt(atRec.reduce((s,x)=>s+x.valor,0))} de ${new Set(atRec.map(x=>x.cliente_nome)).size} cliente(s)`,
                'receber', 'atraso-rec:' + atRec.map(x=>x.id).join(','));
        const atPag = db.contas_pagar.filter(atrasada);
        if (atPag.length)
            add('fin_atraso','danger','💸',`<strong>${atPag.length} pagamento(s) em atraso</strong> — R$ ${fmt(atPag.reduce((s,x)=>s+x.valor,0))}`,
                'pagar', 'atraso-pag:' + atPag.map(x=>x.id).join(','));
    }

    const hoje2 = new Date();
    const mesAtStr = `${hoje2.getFullYear()}-${String(hoje2.getMonth()+1).padStart(2,'0')}`;
    const mesAntD  = new Date(hoje2.getFullYear(), hoje2.getMonth()-1, 1);
    const mesAntStr = `${mesAntD.getFullYear()}-${String(mesAntD.getMonth()+1).padStart(2,'0')}`;
    // Meta e tendencia pertencem a Visao Geral/Resultado do mes: desligados com elas.
    const metaTendOk = FIN_RECURSOS_ANTIGOS.visaoGeral || FIN_RECURSOS_ANTIGOS.resultado;
    const precisaFat = metaTendOk && (alertaAtivo('fin_tendencia') || alertaAtivo('fin_meta'));
    const fatAt = precisaFat ? resultadoFinanceiroDoMes(mesAtStr).faturamento : 0;
    const fatAnt = metaTendOk && alertaAtivo('fin_tendencia') ? resultadoFinanceiroDoMes(mesAntStr).faturamento : 0;
    if (metaTendOk && alertaAtivo('fin_tendencia') && fatAnt>0) {
        const pct = ((fatAt-fatAnt)/fatAnt*100).toFixed(1);
        // Igual tambem quando a porcentagem mostrada arredonda para 0,0% (nunca "+0.0%").
        const igual = Math.round(fatAt * 100) === Math.round(fatAnt * 100) || Math.abs(Number(pct)) === 0;
        add('fin_tendencia', fatAt>=fatAnt?'success':'warning', fatAt>=fatAnt?'📈':'📉',
            `Faturamento deste mês <strong>${igual ? 'igual ao mês anterior' : (fatAt>=fatAnt?'+':'') + pct + '% vs. mês anterior'}</strong> (R$ ${fmt(fatAt)} × R$ ${fmt(fatAnt)})`,
            'resumo', 'tendencia:' + mesAtStr + ':' + (fatAt>=fatAnt ? 'alta' : 'queda'));
    }

    const metaMes = metaTendOk && alertaAtivo('fin_meta') ? metaFinanceiraDoMes(mesAtStr) : 0;
    if (metaTendOk && alertaAtivo('fin_meta') && metaMes>0) {
        const pctMeta = (fatAt/metaMes*100).toFixed(1);
        if (fatAt>=metaMes)
            add('fin_meta','success','🏆',`Meta do mês atingida! <strong>${pctMeta}%</strong> — R$ ${fmt(fatAt)} de R$ ${fmt(metaMes)}`, 'resumo', 'meta:' + mesAtStr + ':atingida');
        else if (fatAt>=metaMes*0.8)
            add('fin_meta','info','🎯',`Faltam <strong>R$ ${fmt(metaMes-fatAt)}</strong> para atingir a meta (${pctMeta}% concluído)`, 'resumo', 'meta:' + mesAtStr + ':perto');
    }

    const em7 = new Date(hojeStr+'T00:00:00'); em7.setDate(em7.getDate()+7);
    const em7Str = dataLocal(em7.getTime());
    const proxVenc = (veRec ? db.contas_receber.filter(cr=>finAberta(cr)&&cr.data_vencimento>hojeStr&&cr.data_vencimento<=em7Str).length : 0)
                   + (vePag ? db.contas_pagar.filter(cp=>finAberta(cp)&&cp.data_vencimento>hojeStr&&cp.data_vencimento<=em7Str).length : 0);
    if (alertaAtivo('fin_vencimento') && proxVenc>=3)
        add('fin_vencimento','info','📋',`<strong>${proxVenc} conta(s)</strong> vencem nos próximos 7 dias`, 'lancamentos', 'venc-7d:' + hojeStr + ':' + proxVenc);

    const _ent7 = db.contas_receber.filter(cr=>finAberta(cr)&&cr.data_vencimento>=hojeStr&&cr.data_vencimento<=em7Str).reduce((s,cr)=>s+cr.valor,0);
    const _sai7 = db.contas_pagar.filter(cp=>finAberta(cp)&&cp.data_vencimento>=hojeStr&&cp.data_vencimento<=em7Str).reduce((s,cp)=>s+cp.valor,0);
    if (alertaAtivo('fin_gap') && _sai7 > _ent7 && _sai7 > 0)
        add('fin_gap','danger','⚠️',`Gap de caixa: saídas superam entradas nos próximos 7 dias em <strong>R$ ${fmt(_sai7-_ent7)}</strong> (entradas: R$ ${fmt(_ent7)} · saídas: R$ ${fmt(_sai7)})`, 'fluxo', 'gap:' + hojeStr);
    return out;
}

function renderDashboardFinanceiro() {
    renderAvisoCopiaFinanceiro();
    renderAvisoRevisaoFinanceiro();
    if (typeof Chart === 'undefined') return;
    _migrarFinanceiroPedidos();
    atualizarStatusVencimentos();
    document.getElementById('fin-meta-edit-btn')?.style.setProperty('display', temAcesso('financeiro.dashboard', 'completo') ? '' : 'none');
    try { _finMetas = JSON.parse(localStorage.getItem('sc_fin_metas') || '{}'); } catch(e) { _finMetas = {}; }

    const { ini, fim, label } = getFinPeriodo();
    const inRange = d => d && d >= ini && d <= fim;
    const hojeStr = hojeLocal();
    const fmt = v => (v||0).toLocaleString('pt-BR', { minimumFractionDigits:2, maximumFractionDigits:2 });
    const kpiBox = (lbl, val, sub, cor) =>
        `<div class="fin-kpi fin-kpi-${cor}"><div class="fin-kpi-label">${lbl}</div><div class="fin-kpi-value">${val}</div>${sub?`<div class="fin-kpi-sub">${sub}</div>`:''}</div>`;

    const periodoLabelEl = document.getElementById('fin-periodo-label');
    if (periodoLabelEl) periodoLabelEl.textContent = label;

    // ── KPIs ──────────────────────────────────────────────────────
    // Recebido/pago pela mesma regra do Resultado do mes (pela data em que o dinheiro entra).
    const { res: resPer, ate: atePer, recebido, totalPago, lucro, pedPagos, ticketMedio, impostoJaContado, aCair, lucroSub } = dinheiroDoPeriodoFin();
    // A receber/a pagar na mesma janela do recebido/pago ("Este mes" = ate o fim do mes, como o recebido).
    const naJanela = d => d && d >= ini && d <= atePer;
    const aReceber  = db.contas_receber.filter(cr=>finAberta(cr)&&naJanela(cr.data_vencimento)).reduce((s,cr)=>s+cr.valor,0);
    const aPagar    = db.contas_pagar.filter(cp=>finAberta(cp)&&naJanela(cp.data_vencimento)).reduce((s,cp)=>s+cp.valor,0);
    // Guia de imposto em aberto ja contada nas saidas (imposto pela referencia) nao entra duas vezes no saldo.
    const aPagarDup = db.contas_pagar.filter(cp=>finAberta(cp)&&naJanela(cp.data_vencimento)&&impostoJaContado(cp)).reduce((s,cp)=>s+cp.valor,0);
    const saldoPrev = (recebido+aReceber)-(totalPago+aPagar-aPagarDup);
    // Periodo que pega so um pedaco de algum mes: o imposto (pela referencia) so entra nos meses inteiros.
    const notaImpEl = document.getElementById('fin-nota-imposto');
    if (notaImpEl) {
        notaImpEl.textContent = resPer.imposto.cortaMes ? 'O imposto entra só nos meses inteiros do período' : '';
        notaImpEl.style.display = resPer.imposto.cortaMes ? '' : 'none';
    }
    // Recebido liquido (sem a taxa do cartao), o mesmo valor que cai na conta (Hoje/Extrato).
    const recebidoLiquido = resPer.faturamento;

    // ── 4 CARDS PRINCIPAIS ──────────────────────────────────────────
    // Só Saldo Previsto e Inadimplência usam cor de fundo com significado;
    // A Receber/A Pagar são fatos neutros (não são "bons" nem "ruins").
    const totalCR      = db.contas_receber.filter(cr=>finAberta(cr)).reduce((s,cr)=>s+cr.valor,0);
    const totalAtr     = db.contas_receber.filter(cr=>cr.status==='Atrasado').reduce((s,cr)=>s+cr.valor,0);
    const inadimplPct  = totalCR > 0 ? totalAtr/totalCR*100 : 0;
    const corInadimpl  = inadimplPct > 10 ? 'fin-kpi-red' : 'fin-kpi-neutral';

    const kpiEl = document.getElementById('fin-kpis');
    if (kpiEl) kpiEl.innerHTML = `
        <div class="fin-kpi ${saldoPrev>=0?'fin-kpi-green':'fin-kpi-red'}"><div class="fin-kpi-label">Saldo Previsto</div><div class="fin-kpi-value">R$ ${fmt(saldoPrev)}</div><div class="fin-kpi-sub">receb. + a receber − despesas</div></div>
        <div class="fin-kpi fin-kpi-neutral"><div class="fin-kpi-label">A Receber</div><div class="fin-kpi-value">R$ ${fmt(aReceber)}</div><div class="fin-kpi-sub">vence no período</div></div>
        <div class="fin-kpi fin-kpi-neutral"><div class="fin-kpi-label">A Pagar</div><div class="fin-kpi-value">R$ ${fmt(aPagar)}</div><div class="fin-kpi-sub">vence no período</div></div>
        <div class="fin-kpi ${corInadimpl}"><div class="fin-kpi-label">Inadimplência</div><div class="fin-kpi-value">${inadimplPct.toFixed(1)}%</div><div class="fin-kpi-sub">R$ ${fmt(totalAtr)} atrasado</div></div>`;

    // ── INDICADORES DETALHADOS (seção colapsável) ───────────────────
    // Neutros por padrão; só o Lucro carrega cor (confirmação positiva/negativa real).
    const kpis2El = document.getElementById('fin-kpis2');
    if (kpis2El) {
        let pmrSoma = 0, pmrN = 0;
        db.pedidos.filter(p=>normalizarStatus(p.status)==='Instalado'&&p.data_instalado).forEach(p => {
            const criacao = typeof p.data_criacao==='number' ? p.data_criacao : (typeof p.id==='number' && p.id > 1e11 ? p.id : 0);
            const dias = Math.round((p.data_instalado - criacao) / 86400000);
            if (dias > 0 && dias < 730) { pmrSoma += dias; pmrN++; }
        });
        const pmr = pmrN > 0 ? Math.round(pmrSoma/pmrN) : 0;

        const margemPct = recebido > 0 ? lucro/recebido*100 : 0;

        const pedAndamento = db.pedidos.filter(p=>{ const s=normalizarStatus(p.status); return s!=='Instalado'&&s!=='Orçamento'; });
        const valPipeline  = pedAndamento.reduce((s,p)=>s+(p.valor||0),0);

        const totalPeds    = db.pedidos.length;
        const pConvertidos = db.pedidos.filter(p=>normalizarStatus(p.status)!=='Orçamento').length;
        const taxaConv     = totalPeds > 0 ? pConvertidos/totalPeds*100 : 0;

        kpis2El.innerHTML =
            kpiBox('Total Recebido', 'R$ '+fmt(recebido), escapeHtml(label) + (resPer.taxas > 0 ? `<br><span class="fin-recebido-liquido">R$ ${fmt(recebidoLiquido)} líquido (sem a taxa do cartão)</span>` : '') + (aCair ? `<br><span class="fin-a-cair">${escapeHtml(aCair)}</span>` : ''), 'neutral') +
            kpiBox('Lucro (Caixa)', 'R$ '+fmt(lucro), escapeHtml(lucroSub), lucro>=0?'green':'red') +
            kpiBox('Ticket Médio', ticketMedio>0?'R$ '+fmt(ticketMedio):'—', `${pedPagos.size} pedido(s) com recebimento`, 'neutral') +
            kpiBox('PMR', pmr > 0 ? pmr+' dias' : '—', pmrN ? `${pmrN} pedidos concluídos` : 'Sem dados', 'neutral') +
            kpiBox('Margem Líquida', (margemPct>=0?'':'-')+Math.abs(margemPct).toFixed(1)+'%', escapeHtml(label), 'neutral') +
            kpiBox('Pipeline', 'R$ '+fmt(valPipeline), `${pedAndamento.length} em andamento`, 'neutral') +
            kpiBox('Conversão', taxaConv.toFixed(1)+'%', `${pConvertidos}/${totalPeds} pedidos`, 'neutral');
    }
    aplicarEstadoFinAccordion();

    // ── PROJEÇÃO DE FLUXO: bloco único com seletor 30/60/90 ─────────
    document.querySelectorAll('.fin-proj-btn').forEach(b => b.classList.toggle('active', Number(b.dataset.d) === _finProjDias));
    const horizStr = FinanceiroCore.somarDias(hojeStr, _finProjDias);
    const projBuckets = _finGerarBuckets(hojeStr, horizStr);
    // Mesmo motor da previsao da tela Hoje: cartao pelas datas de repasse e pelo liquido (o que ja foi baixado
    // e ainda vai cair, e o cartao previsto nas contas em aberto); atrasados entram hoje.
    // Transferencias entre contas somam zero: ficam fora das barras de entrada e saida.
    const projLanc = CaixaCore.lancamentosPrevistos({ hoje: hojeStr, limite: horizStr, movimentos: (db.movimentos_fin || []).filter(m => m.origem !== 'transferencia'), contasReceber: db.contas_receber,
        contasPagar: db.contas_pagar, despesasFixas: db.despesas_fixas, contas: getContasFin(), meios: getMeiosPag() });
    const projSoma = (b, sentido) => CaixaCore.arredondar(projLanc.filter(l => l.sentido === sentido && l.data >= b.ini && l.data <= b.fim).reduce((s, l) => s + l.valor, 0));
    const projEnt = projBuckets.map(b => projSoma(b, 'entrada'));
    const projSai = projBuckets.map(b => projSoma(b, 'saida'));
    const projEntTotal = CaixaCore.arredondar(projEnt.reduce((s,v)=>s+v,0));
    const projSaiTotal = CaixaCore.arredondar(projSai.reduce((s,v)=>s+v,0));
    const projSaldoTotal = projEntTotal - projSaiTotal;

    const ctxProj = document.getElementById('chart-fin-projecao');
    if (ctxProj) {
        if (_chartFinProjecao) _chartFinProjecao.destroy();
        _chartFinProjecao = new Chart(ctxProj, {
            data: { labels: projBuckets.map(b=>b.label), datasets: [
                { type:'bar',  label:'Entradas', data:projEnt, backgroundColor:'#8FD98Dcc', borderColor:'#159912', borderWidth:1, borderRadius:3, yAxisID:'y' },
                { type:'bar',  label:'Saídas',   data:projSai, backgroundColor:'#F79B90cc', borderColor:'#F43927', borderWidth:1, borderRadius:3, yAxisID:'y' },
                { type:'line', label:'Saldo',    data:projEnt.map((e,i)=>e-projSai[i]), borderColor:'#005D3B', backgroundColor:'rgba(0,93,59,0.06)', borderWidth:2, pointRadius:3, fill:true, tension:0.35, yAxisID:'y' }
            ]},
            options: { responsive:true, maintainAspectRatio:false,
                plugins:{ legend:{ position:'top', labels:{ font:{size:11}, boxWidth:10, padding:8 }}},
                scales:{ y:{ ticks:{ callback:v=>'R$'+v.toLocaleString('pt-BR'), font:{size:10}}, grid:{color:'rgba(0,0,0,0.05)'}},
                          x:{ grid:{display:false}, ticks:{ font:{size:10}}}}
            }
        });
    }
    const resumoEl = document.getElementById('fin-proj-resumo');
    if (resumoEl) resumoEl.innerHTML = `
        <div class="fp-item"><span class="fp-label">▲ Entradas totais</span><span class="fp-val" style="color:#159912">R$ ${fmt(projEntTotal)}</span></div>
        <div class="fp-item"><span class="fp-label">▼ Saídas totais</span><span class="fp-val" style="color:#F43927">R$ ${fmt(projSaiTotal)}</span></div>
        <div class="fp-item"><span class="fp-label">Saldo líquido previsto</span><span class="fp-val" style="color:${projSaldoTotal>=0?'var(--primary-text)':'#F43927'}">${projSaldoTotal>=0?'+':''}R$ ${fmt(projSaldoTotal)}</span></div>`;

    // ── ALERTAS ───────────────────────────────────────────────────
    // Mesma lista que vai para o sino e para o card do Painel (finAlertasCalcular).
    const alertasEl = document.getElementById('fin-alertas');
    if (alertasEl) {
        alertasEl.innerHTML = finAlertasCalcular(hojeStr).map(a =>
            `<div class="fin-alerta fin-alerta-${a.cor}"><span style="font-size:18px;flex-shrink:0">${a.icone}</span><span>${a.html}</span></div>`).join('');
    }

    // ── META ──────────────────────────────────────────────────────
    const hoje3 = new Date();
    const mesKey = `${hoje3.getFullYear()}-${String(hoje3.getMonth()+1).padStart(2,'0')}`;
    // Meta = ajuste do mes ou padrao da empresa; comparada com o faturamento liquido (como no Resultado do mes).
    const metaValor  = metaFinanceiraDoMes(mesKey);
    const fatMesAt   = resultadoFinanceiroDoMes(mesKey).faturamento;
    const metaInputEl = document.getElementById('fin-meta-valor');
    if (metaInputEl && !metaInputEl._userEditing) metaInputEl.value = Number(_finMetas[mesKey]) > 0 ? _finMetas[mesKey] : '';
    // Sem ajuste no mes, a sugestao e a meta padrao da Empresa (como no Resultado do mes).
    if (metaInputEl) {
        const metaPadrao = Number(getEmpresa().meta_faturamento_padrao);
        metaInputEl.placeholder = metaPadrao > 0 ? metaPadrao.toLocaleString('pt-BR', { maximumFractionDigits: 2 }) : 'Ex: 15000';
    }
    const nomeMes = hoje3.toLocaleString('pt-BR',{month:'long',year:'numeric'});
    const labelMetaEl = document.getElementById('fin-meta-mes-label');
    if (labelMetaEl) labelMetaEl.textContent = nomeMes.charAt(0).toUpperCase()+nomeMes.slice(1);
    const progressEl = document.getElementById('fin-meta-progress');
    if (progressEl) {
        if (!metaValor) {
            progressEl.innerHTML = '<p style="color:#8F8F8F;font-size:13px;text-align:center;padding:8px 0">Defina uma meta acima (ou a meta padrão em Empresa) para acompanhar seu progresso.</p>';
        } else {
            const pctRaw = Math.min(100, fatMesAt/metaValor*100);
            const pctStr = pctRaw.toFixed(1);
            const cor = pctRaw>=100?'var(--primary-text)':pctRaw>=70?'#159912':pctRaw>=40?'#F2C924':'#F43927';
            progressEl.innerHTML = `
                <div style="display:flex;justify-content:space-between;font-size:13px;margin-bottom:6px">
                    <span style="color:#8F8F8F">Faturado: <strong>R$ ${fmt(fatMesAt)}</strong></span>
                    <span style="color:#8F8F8F">Meta: <strong>R$ ${fmt(metaValor)}</strong></span>
                    <span style="font-weight:700;color:${cor}">${pctStr}%</span>
                </div>
                <div style="background:var(--surface-3);border-radius:8px;height:22px;overflow:hidden">
                    <div style="height:100%;width:${pctStr}%;background:linear-gradient(90deg,${cor},${cor}cc);border-radius:8px;transition:width .5s;display:flex;align-items:center;justify-content:flex-end;padding-right:${pctRaw>10?8:0}px">
                        ${pctRaw>12?`<span style="font-size:11px;font-weight:700;color:#fff">${pctStr}%</span>`:''}
                    </div>
                </div>
                <p style="font-size:12px;color:${pctRaw>=100?'var(--primary-text)':'#8F8F8F'};margin-top:5px;font-weight:${pctRaw>=100?700:400}">
                    ${pctRaw>=100?'🏆 Meta atingida!':`Faltam <strong style="color:var(--dark)">R$ ${fmt(metaValor-fatMesAt)}</strong> para a meta.`}
                </p>`;
        }
    }

    // ── EVOLUÇÃO MENSAL 12 MESES ──────────────────────────────────
    const _hj12 = new Date();
    const evolLabels = [], evolRec12 = [], evolPag12 = [];
    for (let i=11;i>=0;i--) {
        const d = new Date(_hj12.getFullYear(), _hj12.getMonth()-i, 1);
        const ms = `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`;
        evolLabels.push(d.toLocaleString('pt-BR',{month:'short'})+'/'+String(d.getFullYear()).slice(2));
        const rm = resultadoFinanceiroDoMes(ms);
        evolRec12.push(rm.entradas);
        evolPag12.push(rm.saidas);
    }
    const ctxEvol = document.getElementById('chart-fin-evolucao');
    if (ctxEvol) {
        if (_chartFinEvolucao) _chartFinEvolucao.destroy();
        _chartFinEvolucao = new Chart(ctxEvol, {
            data:{ labels:evolLabels, datasets:[
                {type:'bar',  label:'Entradas', data:evolRec12, backgroundColor:'#8FD98Dcc', borderColor:'#159912', borderWidth:1, borderRadius:3, yAxisID:'y'},
                {type:'bar',  label:'Saídas',   data:evolPag12, backgroundColor:'#F79B90cc', borderColor:'#F43927', borderWidth:1, borderRadius:3, yAxisID:'y'},
                {type:'line', label:'Resultado', data:evolRec12.map((e,i)=>Math.round((e-evolPag12[i])*100)/100), borderColor:'#005D3B', backgroundColor:'rgba(0,93,59,0.06)', borderWidth:2, pointRadius:3, fill:true, tension:0.35, yAxisID:'y'}
            ]},
            options:{ responsive:true, maintainAspectRatio:false,
                plugins:{ legend:{ position:'top', labels:{ font:{size:11}, boxWidth:10, padding:8 }}},
                scales:{ y:{ beginAtZero:true, ticks:{ callback:v=>'R$'+v.toLocaleString('pt-BR'), font:{size:10}}, grid:{color:'rgba(0,0,0,0.05)'}},
                          x:{ grid:{display:false}, ticks:{ font:{size:10}}}}
            }
        });
    }

    // ── AGING DE RECEBÍVEIS ───────────────────────────────────────
    const _hjD = new Date(hojeStr+'T00:00:00');
    const agBuckets = [
        {label:'A vencer',     color:'#159912', check:d=>d>0},
        {label:'Vence hoje',   color:'#F2C924', check:d=>d===0},
        {label:'1–7d atraso',  color:'#FF7F08', check:d=>d<0&&d>=-7},
        {label:'8–30d atraso', color:'#F43927', check:d=>d<-7&&d>=-30},
        {label:'+30d atraso',  color:'#B3160A', check:d=>d<-30},
    ];
    const agVals = agBuckets.map(()=>0);
    db.contas_receber.filter(cr=>finAberta(cr)&&cr.data_vencimento).forEach(cr=>{
        const diff = Math.round((new Date(cr.data_vencimento+'T00:00:00')-_hjD)/86400000);
        for (let i=0;i<agBuckets.length;i++) { if (agBuckets[i].check(diff)) { agVals[i]+=cr.valor; break; } }
    });
    const ctxAging = document.getElementById('chart-fin-aging');
    if (ctxAging) {
        if (_chartFinAging) _chartFinAging.destroy();
        _chartFinAging = new Chart(ctxAging, {
            type:'bar',
            data:{labels:agBuckets.map(b=>b.label), datasets:[{data:agVals, backgroundColor:agBuckets.map(b=>b.color+'cc'), borderColor:agBuckets.map(b=>b.color), borderWidth:1, borderRadius:4}]},
            options:{indexAxis:'y', responsive:true, maintainAspectRatio:false,
                plugins:{legend:{display:false}, tooltip:{callbacks:{label:ctx=>' R$ '+ctx.raw.toLocaleString('pt-BR',{minimumFractionDigits:2,maximumFractionDigits:2})}}},
                scales:{ x:{beginAtZero:true, ticks:{callback:v=>'R$'+v.toLocaleString('pt-BR'),font:{size:10}}, grid:{color:'rgba(0,0,0,0.05)'}},
                          y:{ticks:{font:{size:11}}, grid:{display:false}}}
            }
        });
    }

    // ── TOP 10 CLIENTES ───────────────────────────────────────────
    const cliMap = {};
    db.contas_receber.filter(cr=>cr.status==='Pago'&&cr.cliente_nome).forEach(cr=>{ cliMap[cr.cliente_nome]=(cliMap[cr.cliente_nome]||0)+cr.valor; });
    const topCli = Object.entries(cliMap).sort(([,a],[,b])=>b-a).slice(0,10);
    const ctxTop = document.getElementById('chart-fin-top-clientes');
    if (ctxTop) {
        if (_chartFinTopClientes) _chartFinTopClientes.destroy();
        if (topCli.length) {
            _chartFinTopClientes = new Chart(ctxTop, {
                type:'bar',
                data:{labels:topCli.map(([n])=>n.length>16?n.slice(0,16)+'…':n), datasets:[{data:topCli.map(([,v])=>v), backgroundColor:'#005D3Bcc', borderColor:'#005D3B', borderWidth:1, borderRadius:3}]},
                options:{indexAxis:'y', responsive:true, maintainAspectRatio:false,
                    plugins:{legend:{display:false}, tooltip:{callbacks:{label:ctx=>' R$ '+ctx.raw.toLocaleString('pt-BR',{minimumFractionDigits:2,maximumFractionDigits:2})}}},
                    scales:{ x:{beginAtZero:true, ticks:{callback:v=>'R$'+v.toLocaleString('pt-BR'),font:{size:10}}, grid:{color:'rgba(0,0,0,0.05)'}},
                              y:{ticks:{font:{size:10}}, grid:{display:false}}}
                }
            });
        } else {
            const el = ctxTop.parentElement;
            if (!el.querySelector('.fin-sem-dados')) { const p=document.createElement('p'); p.className='fin-sem-dados'; p.style.cssText='color:#8F8F8F;font-size:12px;text-align:center;padding:20px 0'; p.textContent='Sem recebimentos registrados.'; el.appendChild(p); }
        }
    }

    // ── FUNIL DE PEDIDOS ──────────────────────────────────────────
    const FUNIL_ST = [
        {key:'Orçamento',            label:'Orçamento',     color:'#F2C924'},
        {key:'Medição',              label:'Medição',       color:'#2D77C1'},
        {key:'Aguardando Tecido',    label:'Ag. Tecido',    color:'#FF7F08'},
        {key:'Na Costura',           label:'Na Costura',    color:'#9B31C8'},
        {key:'Pronto p/ Instalação', label:'Pronto Inst.',  color:'#005D3B'},
        {key:'Aguardando Financeiro', label:'Ag. Financeiro', color:'#FF575F'},
        {key:'Instalado',            label:'Instalado',     color:'#159912'},
    ];
    const funilCounts = FUNIL_ST.map(s=>db.pedidos.filter(p=>normalizarStatus(p.status)===s.key).length);
    const ctxFunil = document.getElementById('chart-fin-funil');
    if (ctxFunil) {
        if (_chartFinFunil) _chartFinFunil.destroy();
        _chartFinFunil = new Chart(ctxFunil, {
            type:'bar',
            data:{labels:FUNIL_ST.map(s=>s.label), datasets:[{data:funilCounts, backgroundColor:FUNIL_ST.map(s=>s.color+'cc'), borderColor:FUNIL_ST.map(s=>s.color), borderWidth:1, borderRadius:4}]},
            options:{indexAxis:'y', responsive:true, maintainAspectRatio:false,
                plugins:{legend:{display:false}, tooltip:{callbacks:{label:ctx=>` ${ctx.raw} pedido${ctx.raw!==1?'s':''}`}}},
                scales:{ x:{beginAtZero:true, ticks:{stepSize:1,font:{size:10}}, grid:{color:'rgba(0,0,0,0.05)'}},
                          y:{ticks:{font:{size:10}}, grid:{display:false}}}
            }
        });
    }

    // ── GRÁFICO COMBO ─────────────────────────────────────────────
    // Mesmos itens do periodo (pela data do dinheiro); o imposto de cada mes inteiro entra no ultimo dia dele
    // e a guia paga num pedaco de mes, na data do pagamento.
    const buckets  = _finGerarBuckets(ini, atePer);
    const naFaixa  = (b, d) => d >= b.ini && d <= b.fim;
    const r2 = v => Math.round(v * 100) / 100;
    const entradas = buckets.map(b=>r2(resPer.itensEntrada.filter(i=>naFaixa(b, i.data)).reduce((s,i)=>s+i.valor,0)));
    const saidas   = buckets.map(b=>r2(resPer.itensSaida.filter(i=>naFaixa(b, i.data)).reduce((s,i)=>s+i.valor,0)
        + Object.entries(resPer.imposto.porMes).filter(([m])=>naFaixa(b, _resUltimoDia(m))).reduce((s,[,v])=>s+v,0)
        + resPer.imposto.pagas.filter(i=>naFaixa(b, i.data)).reduce((s,i)=>s+i.valor,0)));
    let _acc = 0;
    const saldos = entradas.map((e, i) => { _acc += e - saidas[i]; return _acc; });
    const ctxCombo = document.getElementById('chart-fin-combo');
    if (ctxCombo) {
        if (_chartFinCombo) _chartFinCombo.destroy();
        _chartFinCombo = new Chart(ctxCombo, {
            data: { labels: buckets.map(b=>b.label), datasets: [
                { type:'bar',  label:'Entradas', data:entradas, backgroundColor:'#8FD98D', borderColor:'#159912', borderWidth:1, borderRadius:4, yAxisID:'y' },
                { type:'bar',  label:'Saídas',   data:saidas,   backgroundColor:'#F79B90', borderColor:'#F43927', borderWidth:1, borderRadius:4, yAxisID:'y' },
                { type:'line', label:'Saldo',    data:saldos,   borderColor:'#005D3B', backgroundColor:'rgba(0,93,59,0.08)', pointRadius:3, borderWidth:2, fill:true, yAxisID:'y', tension:0.3 }
            ]},
            options: { responsive:true, maintainAspectRatio:false,
                plugins:{ legend:{ position:'top', labels:{ font:{size:11}, padding:10, boxWidth:11 }}},
                scales:{
                    y:{ beginAtZero:true, ticks:{ callback:v=>'R$'+v.toLocaleString('pt-BR'), font:{size:10} }, grid:{color:'rgba(0,0,0,0.05)'} },
                    x:{ grid:{display:false}, ticks:{ font:{size:10}, maxRotation:45 }}
                }
            }
        });
    }

    // ── DONUT RECEBIMENTOS ────────────────────────────────────────
    const recPago = recebido;
    const recPend = db.contas_receber.filter(cr=>cr.status==='Pendente'&&inRange(cr.data_vencimento)).reduce((s,cr)=>s+cr.valor,0);
    const recAtr  = db.contas_receber.filter(cr=>cr.status==='Atrasado').reduce((s,cr)=>s+cr.valor,0);
    const totalRec = recPago + recPend + recAtr;
    const ctxRec  = document.getElementById('chart-fin-rec');
    if (ctxRec) {
        if (_chartFinRec) _chartFinRec.destroy();
        _chartFinRec = new Chart(ctxRec, {
            type:'doughnut',
            data:{ labels:['Recebido','Pendente','Atrasado'], datasets:[{ data:[recPago,recPend,recAtr], backgroundColor:['#159912cc','#F2C924cc','#F43927cc'], borderColor:['#159912','#F2C924','#F43927'], borderWidth:2, hoverOffset:6 }]},
            options:{ responsive:true, maintainAspectRatio:true, cutout:'65%', plugins:{ legend:{ position:'bottom', labels:{ font:{size:11}, padding:8, boxWidth:10 }}, centerText:{ text: totalRec > 0 ? 'R$ '+fmt(totalRec) : '—', subtext:'Total' }}},
            plugins:[_finCenterTextPlugin]
        });
    }

    // ── DONUT DESPESAS POR CATEGORIA ─────────────────────────────
    // Saidas pagas no periodo pelos grupos do Resultado do mes (inclui taxa de cartao e imposto pela referencia).
    const CAT_LABELS = {}; ResultadoCore.GRUPOS.forEach(g => { CAT_LABELS[g.id] = g.rotulo; });
    const CAT_CORES  = { fornecedores:'#9B31C8', servicos:'#D70085', comissoes:'#FF7F08', taxas:'#5B6B7A', fixas:'#F43927', imposto:'#0F8B8D', outros:'#8F8F8F' };
    const despCats = {};
    ResultadoCore.GRUPOS.forEach(g => { if (resPer.porGrupo[g.id] > 0) despCats[g.id] = resPer.porGrupo[g.id]; });
    const catKeys   = Object.keys(despCats);
    const totalDesp = catKeys.reduce((s,k)=>s+despCats[k], 0);
    const ctxDesp   = document.getElementById('chart-fin-desp');
    if (ctxDesp) {
        if (_chartFinDesp) _chartFinDesp.destroy();
        _chartFinDesp = catKeys.length ? new Chart(ctxDesp, {
            type:'doughnut',
            data:{ labels:catKeys.map(k=>CAT_LABELS[k]||k), datasets:[{ data:catKeys.map(k=>despCats[k]), backgroundColor:catKeys.map(k=>(CAT_CORES[k]||'#8F8F8F')+'cc'), borderColor:catKeys.map(k=>CAT_CORES[k]||'#8F8F8F'), borderWidth:2, hoverOffset:6 }]},
            options:{ responsive:true, maintainAspectRatio:true, cutout:'65%', plugins:{ legend:{ position:'bottom', labels:{ font:{size:10}, padding:7, boxWidth:10 }}, centerText:{ text:'R$ '+fmt(totalDesp), subtext:'Total' }}},
            plugins:[_finCenterTextPlugin]
        }) : null;
        if (!catKeys.length) {
            const p = ctxDesp.parentElement.querySelector('p.fin-sem-desp');
            if (!p) { const el=document.createElement('p'); el.className='fin-sem-desp'; el.style.cssText='color:#8F8F8F;font-size:12px;text-align:center;padding:20px 0'; el.textContent='Sem despesas no período.'; ctxDesp.after(el); }
        }
    }

    // ── TABELAS ───────────────────────────────────────────────────
    const _thSort = (which, col, label, align) => {
        const s = which === 'rec' ? _finSortRec : _finSortPag;
        const active = s.col === col;
        const arrow = active ? (s.dir === 1 ? ' ▲' : ' ▼') : '';
        return `<th style="${align?'text-align:'+align+';':''} cursor:pointer;user-select:none;white-space:nowrap;${active?'color:var(--primary);':''}" onclick="_finSortToggle('${which}','${col}')">${label}${arrow}</th>`;
    };
    const _sortList = (list, s, nomeKey) => {
        return [...list].sort((a, b) => {
            if (s.col === 'venc')  return s.dir * (a.data_vencimento||'').localeCompare(b.data_vencimento||'');
            if (s.col === 'nome')  return s.dir * (a[nomeKey]||'').localeCompare(b[nomeKey]||'');
            if (s.col === 'valor') return s.dir * (a.valor - b.valor);
            return 0;
        }).slice(0, 10);
    };

    const recCard = document.getElementById('fin-card-receber');
    if (recCard) {
        const lista = _sortList(db.contas_receber.filter(cr=>finAberta(cr)), _finSortRec, 'cliente_nome');
        recCard.innerHTML = `<h3 style="margin-bottom:14px;font-size:14px">📥 Próximos Recebimentos</h3>
        <table><thead><tr>
            ${_thSort('rec','venc','Vencimento')} ${_thSort('rec','nome','Cliente')}
            <th>Descrição</th>
            ${_thSort('rec','valor','Valor','right')}
            <th>Status</th>
        </tr></thead><tbody>${lista.length ? lista.map(cr => {
            const at = cr.status === 'Atrasado';
            return `<tr class="${at?'fin-atrasado':''}">
                <td>${_fmtVenc(cr.data_vencimento)}</td>
                <td>${escapeHtml(cr.cliente_nome)}</td>
                <td style="font-size:12px;color:#8F8F8F">${escapeHtml(cr.descricao)}</td>
                <td style="text-align:right"><strong>R$ ${fmt(cr.valor)}</strong></td>
                <td><span class="fin-badge fin-badge-${at?'red':'pending'}">${cr.status}</span></td>
            </tr>`;
        }).join('') : '<tr><td colspan="5" style="text-align:center;color:#999;padding:16px">Nenhum recebimento pendente.</td></tr>'}</tbody></table>`;
    }

    const pagCard = document.getElementById('fin-card-pagar');
    if (pagCard) {
        const lista = _sortList(db.contas_pagar.filter(cp=>finAberta(cp)), _finSortPag, 'credor_nome');
        pagCard.innerHTML = `<h3 style="margin-bottom:14px;font-size:14px">📤 Próximos Pagamentos</h3>
        <table><thead><tr>
            ${_thSort('pag','venc','Vencimento')} ${_thSort('pag','nome','Credor')}
            <th>Descrição</th>
            ${_thSort('pag','valor','Valor','right')}
            <th>Status</th>
        </tr></thead><tbody>${lista.length ? lista.map(cp => {
            const at = cp.status === 'Atrasado';
            return `<tr class="${at?'fin-atrasado':''}">
                <td>${_fmtVenc(cp.data_vencimento)}</td>
                <td>${escapeHtml(cp.credor_nome||cp.categoria||'—')}</td>
                <td style="font-size:12px;color:#8F8F8F">${escapeHtml(cp.descricao)}</td>
                <td style="text-align:right"><strong>R$ ${fmt(cp.valor)}</strong></td>
                <td><span class="fin-badge fin-badge-${at?'red':'pending'}">${cp.status}</span></td>
            </tr>`;
        }).join('') : '<tr><td colspan="5" style="text-align:center;color:#999;padding:16px">Nenhum pagamento pendente.</td></tr>'}</tbody></table>`;
    }
}

// Abre o WhatsApp com a mensagem de cobranca da parcela. Independe do DOM do A Receber.
async function cobrarNoWhatsApp(crId) {
    // Checa antes de qualquer await para o window.open continuar valendo como clique do usuario.
    if (!temAcesso('financeiro.receber', 'completo')) { await exigirPermissao('financeiro.receber', 'completo'); return; }
    const cr = db.contas_receber.find(c => CaixaCore.mesmoId(c.id, crId));
    if (!cr) return;
    const ped = db.pedidos.find(p => CaixaCore.mesmoId(p.id, cr.pedido_id));
    const achado = CaixaCore.clienteDaCobranca(cr, db.pedidos, db.clientes);
    const tel = CaixaCore.normalizarTelefone(achado.cliente && achado.cliente.tel);
    // Nome repetido em dois clientes: abre o WhatsApp sem numero em vez de chutar o primeiro.
    if (!tel && !achado.ambiguo) { showAlert('Cliente sem telefone no cadastro.'); return; }
    const emp = getEmpresa();
    const venc = String(cr.data_vencimento).split('-').reverse().join('/');
    const msg = CaixaCore.montarMensagem(emp.mensagem_cobranca || CaixaCore.MENSAGEM_COBRANCA_PADRAO, {
        cliente: cr.cliente_nome,
        empresa: emp.nome_fantasia || emp.razao_social || 'nossa empresa',
        valor: 'R$ ' + cr.valor.toLocaleString('pt-BR', { minimumFractionDigits: 2 }),
        pedido: cr.pedido_id != null && cr.pedido_id !== '' ? '#' + formatPedidoId(cr.pedido_id) : '',
        vencimento: venc
    });
    const link = tel ? CaixaCore.linkWhatsApp(tel, msg) : 'https://wa.me/?text=' + encodeURIComponent(msg);
    const janela = window.open(link, '_blank');
    if (!janela) { showAlert('O navegador bloqueou a janela do WhatsApp. Libere os pop-ups e tente de novo.'); return; }
    try { janela.opener = null; } catch (e) {}
    cr.ultima_cobranca = hojeLocal();
    syncDB();
    if (typeof renderFinLancLista === 'function') renderFinLancLista();
    if (FIN_RECURSOS_ANTIGOS.hoje && document.getElementById('hoje-tarefas')) renderHoje();
}

function renderDespesasFixas() {
    const tb = document.getElementById('tb-despesas-fixas');
    if (!tb) return;
    if (!db.despesas_fixas.length) { tb.innerHTML='<tr><td colspan="5" style="text-align:center;color:#999;padding:24px">Nenhuma despesa fixa cadastrada.</td></tr>'; return; }
    const podeEditar = temAcesso('financeiro.fixas', 'completo');
    tb.innerHTML = db.despesas_fixas.map(df=>`
        <tr>
            <td><strong>${escapeHtml(df.descricao)}</strong></td>
            <td>${escapeHtml((db.fin_categorias && db.fin_categorias.categorias.find(c => String(c.id) === String(df.categoria_id)) || {}).nome || (CATEGORIAS_DESPESA_FIXA.find(c => c[0] === df.categoria) || [, df.categoria])[1])}</td>
            <td>Todo dia ${df.dia_vencimento}</td>
            <td>R$ ${(df.valor||0).toLocaleString('pt-BR',{minimumFractionDigits:2})}</td>
            <td>${podeEditar ? `<button class="btn btn-outline btn-sm btn-danger" onclick="excluirDespesaFixa(${df.id})" title="Excluir">🗑️</button>` : ''}</td>
        </tr>`).join('');
}

function renderDRE() {
    const tb = document.getElementById('tb-dre');
    if (!tb) return;
    const filtroCliente = (document.getElementById('dre-filtro-cliente')?.value||'').toLowerCase().trim();
    let pedidos = db.pedidos.filter(p => normalizarStatus(p.status) !== 'Orçamento');
    if (filtroCliente) pedidos = pedidos.filter(p=>(p.clienteNome||'').toLowerCase().includes(filtroCliente));
    pedidos = pedidos.sort((a,b)=>b.id-a.id).slice(0,50);
    if (!pedidos.length) { tb.innerHTML='<tr><td colspan="8" style="text-align:center;color:#999;padding:24px">Nenhum pedido aprovado encontrado.</td></tr>'; return; }
    const brl = v => 'R$ ' + (v||0).toLocaleString('pt-BR',{minimumFractionDigits:2});
    const corDe = m => m>=30?'var(--primary-text)':m>=15?'#F2C924':'#F43927';
    const cad = { catalogo: db.catalogo, materiais: db.materiais, kits: db.kits };
    let totRec=0, totMat=0, totServ=0, totCom=0, totLucro=0;
    const rows = pedidos.map(p=>{
        const r = FinanceiroCore.resultadoPedido({ ...p, ambientes: normalizarAmbientes(p) }, db.contas_pagar, cad);
        const receita = FinanceiroCore.arredondar(r.receita);
        const cor = corDe(r.margem_pct);
        totRec+=receita; totMat+=r.custo_material; totServ+=r.custos_vinculados; totCom+=r.comissoes; totLucro+=r.lucro;
        const aviso = [];
        if (r.origem_custo === 'estimado') aviso.push('custo estimado');
        if (r.itens_sem_custo > 0) aviso.push(`custo não informado (${r.itens_sem_custo} ${r.itens_sem_custo === 1 ? 'item' : 'itens'})`);
        const badges = aviso.map(t => `<div class="dre-selo-aviso">${t}</div>`).join('');
        return `<tr>
            <td style="font-size:12px;color:#888">#${formatPedidoId(p.id)}</td>
            <td>${escapeHtml(p.clienteNome||'—')}</td>
            <td style="text-align:right">${brl(receita)}</td>
            <td style="text-align:right;color:#888">${brl(r.custo_material)}${badges}</td>
            <td style="text-align:right;color:#888">${brl(r.custos_vinculados)}</td>
            <td style="text-align:right;color:#888">${brl(r.comissoes)}</td>
            <td style="text-align:right"><strong style="color:${cor}">${brl(r.lucro)}</strong></td>
            <td style="text-align:center"><strong style="color:${cor}">${r.margem_pct.toFixed(1).replace('.',',')}%</strong></td>
        </tr>`;
    });
    const totM = totRec>0?Math.round(totLucro/totRec*1000)/10:0;
    const corT = corDe(totM);
    tb.innerHTML = rows.join('') + `
        <tr style="border-top:2px solid #242424;background:var(--surface-2);font-weight:700">
            <td colspan="2">TOTAL (${pedidos.length} pedidos)</td>
            <td style="text-align:right">${brl(totRec)}</td>
            <td style="text-align:right;color:#888">${brl(totMat)}</td>
            <td style="text-align:right;color:#888">${brl(totServ)}</td>
            <td style="text-align:right;color:#888">${brl(totCom)}</td>
            <td style="text-align:right"><strong style="color:${corT}">${brl(totLucro)}</strong></td>
            <td style="text-align:center"><strong style="color:${corT}">${totM.toFixed(1).replace('.',',')}%</strong></td>
        </tr>`;
}
